INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (7,'5cc1f000e7971f9d5466','WellbeingCounties','RFP','OPEN','Tapahtumat','Ke 9.9.2026 kello 00.00 – pe 11.9.2026 kello 00.00','North Ostrobothnia wellbeing county','ANY',3,5,NULL,NULL,NULL,'EUR','https://pohde.fi/ajankohtaista/tapahtumat',NULL,'[\"kello\", \"tapahtumat\", \"north\", \"ostrobothnia\", \"wellbeing\", \"county\", \"healthcare\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Tapahtumat Fibromyalgia sopeutumisvalmennuskurssi Ke 9.9.2026 kello 00.00 – pe 11.9.2026 kello 00.00\"}',50,NULL,'2026-09-04 10:02:04','2026-09-08 15:14:49');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (8,'ff372ebef38da21ad62e','StateOrgs','RFP','OPEN','Hankinnat ja kilpailutukset','Väylävirasto on tilaajavirasto ja työllistää noin 400 asiantuntijaa. Hankintatoimemme ja vuosittaisen noin kahden miljardin budjettimme kautta työllistämme välillisesti 14 000 henkilöä.','Väylävirasto','ANY',4,13,NULL,NULL,NULL,'EUR','http://www.hankintailmoitukset.fi/',NULL,'[\"väylävirasto\", \"noin\", \"hankinnat\", \"kilpailutukset\", \"tilaajavirasto\", \"työllistää\", \"asiantuntijaa\", \"hankintatoimemme\", \"vuosittaisen\", \"kahden\", \"miljardin\", \"budjettimme\", \"kautta\", \"työllistämme\", \"välillisesti\", \"henkilöä\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Hankinnat ja kilpailutukset Väyläviraston toiminnan lähtökohtana on sekä ihmisten päivittäisten matkojen että yritysten raaka-aine- ja tuotekuljetusten sujuvuus ja turvallisuus. Väylävirasto on tilaajavirasto ja työllistää noin 400 asiantuntijaa. Hankintatoimemme ja vuosittaisen noin kahden miljardin budjettimme kautta työllistämme välillisesti 14 000 henkilöä. Käynnissä olevat kilpailutukset löytyvät julkisten hankintojen ilmoituskanava HILMAsta . Kynnysarvon alittavat ilmoitukset Tarjouspalvelusta Lisäksi voimassa olevat puitejärjestelyt löytyvät Puitejärjestelyt-sivulta Tiedot suunnitteilla olevista hankinnoista löytyvät Hankintaohjelmat-sivulta . Hankinnan toimintalinjat Uudistetut hankinnan toimintalinjat julkaistiin helmikuussa 2020. Hankinnan toimintalinjojen päätavoite on edistää ja varmistaa se, että pystymme virastona toteuttamaan hankinnat tehokkaasti ja laadukkaasti. Linjauksilla viestimme odotuksemme palveluntuottajamarkkinoille; mihin Väylävirasto hankkijana kiinnittää huomiota, mitä Väylävirasto pitää tärkeänä yhteiskunnallisesta vaikuttavuusnäkökulmasta eli että mahdollistamme laadukkailla liikenneväylillä sujuvan ja turvallisen liikenteen. Hankinnan toimintalinjat \"}',52,NULL,'2026-09-04 10:04:02','2026-09-08 15:15:38');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (9,'9015fa879d50df24cd0d','StateOrgs','RFP','OPEN','Etusivu','Senaatti-konserni on merkittävä rakentamis- ja kiinteistöpalvelujen ostaja Suomessa ja yksi Suomen suurimmista julkisista hankintaorganisaatioista. Hankimme palveluita ja tuotteita konserniin kuuluvien liikelaitosten käyttöön.','Senaatti-kiinteistot','ANY',2,13,NULL,NULL,NULL,'EUR','https://www.senaatti.fi/',NULL,'[\"senaatti\", \"etusivu\", \"konserni\", \"merkittävä\", \"rakentamis\", \"kiinteistöpalvelujen\", \"ostaja\", \"suomessa\", \"yksi\", \"suomen\", \"suurimmista\", \"julkisista\", \"hankintaorganisaatioista\", \"hankimme\", \"palveluita\", \"tuotteita\", \"konserniin\", \"kuuluvien\", \"liikelaitosten\", \"käyttöön\"]',NULL,NULL,NULL,'{\"text\": \"Etusivu Tietoa meistä Hankinnat Hankinnat ja kilpailuttaminen Senaatti-konserni on merkittävä rakentamis- ja kiinteistöpalvelujen ostaja Suomessa ja yksi Suomen suurimmista julkisista hankintaorganisaatioista. Hankimme palveluita ja tuotteita konserniin kuuluvien liikelaitosten käyttöön. Kilpailutuskalenteriin Miten tarjota meille? kilpailutuskalenteri Infotilaisuudet Ilmoittaudu potentiaaliseksi toimittajaksi Ohjeet & yhteystiedot Kilpailutamme julkisesti kaikki kansallisen kynnysarvon ylittävät julkiset hankintamme. Hankintamme kuuluvat joko hankintalain tai puolustus- ja turvallisuushankintalain soveltamisalaan ja joissain tapauksissa niiden soveltamisalapoikkeusten piiriin. Hankintamme ovat monipuolisia. Hankimme mm. rakennusurakoita, rakennuttamiseen, kiinteistöjen ylläpitoon, huoltoon ja korjauksiin sekä tietohallintoon liittyviä palveluita ja tavaroita sekä asiakkaille tuotettavia ja sisäisesti tarvittavia palveluita. Hankintakategoriat Senaatissa Rakennuttaminen Rakennuttaminen ja valvonta - Suunnittelu ja tutkimukset - Rakentaminen - Rakentamisen palvelut ja hallinto Liiketoiminnan palvelut Toimitilapalvelut - Turvallisuuspalvelut - Johdon työympäristöpalvelut - Ympäristöp\"}',52,NULL,'2026-09-04 10:07:25','2026-09-08 15:16:50');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (10,'c435271aa24af722d13b','StateOrgs','RFP','OPEN','Senaatin hankintajohtaja Esapekka Kuikka valittu Vuoden Hankinta-ammattilaiseksi','','Senaatti-kiinteistot','ANY',10,13,NULL,NULL,NULL,'EUR','https://www.senaatti.fi/fi/hankinnat',NULL,'[\"senaatin\", \"hankintajohtaja\", \"esapekka\", \"kuikka\", \"valittu\", \"vuoden\", \"hankinta\", \"ammattilaiseksi\", \"senaatti\", \"kiinteistot\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Hankinnat\\n                                                                            — 06.02.2026 Senaatin hankintajohtaja Esapekka Kuikka valittu Vuoden Hankinta-ammattilaiseksi Senaatti-kiinteistöjen hankintajohtaja Esapekka Kuikka on saanut Suomen Osto- ja Logistiikkayhdistys LOGY ry myöntämän vuoden 2025 Hankinta-ammattilaisen palkinnon. Kuikka on kehittänyt suomalaista hankintatoimea pitkäjänteisesti sekä omassa työssään että laajemmin alan yhteisössä.\"}',52,NULL,'2026-09-04 10:07:25','2026-09-08 15:16:50');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (11,'489ae6fb3d02c732f566','StateOrgs','RFP','OPEN','Fiksuja säästöjä hankinnoilla','','Senaatti-kiinteistot','ANY',10,13,NULL,NULL,NULL,'EUR','https://www.senaatti.fi/fi/hankinnat',NULL,'[\"fiksuja\", \"säästöjä\", \"hankinnoilla\", \"senaatti\", \"kiinteistot\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Hankinnat\\n                                                                            — 12.12.2025 Fiksuja säästöjä hankinnoilla Nykyisessä taloustilanteessa säästöistä puhuminen saa monet ahdistumaan: mitä nyt vielä? Ja ihan viimeistään silloin, jos julkinen hankintayksikkö ilmoittaa säästävänsä, nousevat niskakarvat pystyyn ‒ nytkö yrittäjien selkänahasta revitään viimeisetkin sentit?\"}',48,NULL,'2026-09-04 10:07:25','2026-09-08 15:16:50');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (12,'799535cf554bab5fc097','StateOrgs','RFP','OPEN','Valtion kiinteistöjen ylläpitokustannukset yli 20 % alan keskiarvoa edullisemmat','','Senaatti-kiinteistot','ANY',2,13,NULL,NULL,NULL,'EUR','https://www.senaatti.fi/fi/hankinnat',NULL,'[\"valtion\", \"kiinteistöjen\", \"ylläpitokustannukset\", \"alan\", \"keskiarvoa\", \"edullisemmat\", \"senaatti\", \"kiinteistot\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Hankinnat\\n                                                                            — 10.06.2025 Valtion kiinteistöjen ylläpitokustannukset yli 20 % alan keskiarvoa edullisemmat KTI Kiinteistötiedon toteuttaman kiinteistöalan vertailun mukaan valtion kiinteistöistä vastaava Senaatti-kiinteistöt pystyy toteuttamaan rakennusten ylläpidon yli 20 % edullisemmin kuin alan toimijat keskimäärin. Senaatti panostaa tilojen…\"}',48,NULL,'2026-09-04 10:07:25','2026-09-08 15:16:50');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (13,'77311945f00b419fde08','StateOrgs','RFP','OPEN','Uusi aikakausi oikeuspsykiatrisessa hoidossa – Niuvanniemen sairaalan uudisrakennuksen suunnittelukilpailu käynnistyy','','Senaatti-kiinteistot','ANY',3,13,NULL,NULL,NULL,'EUR','https://www.senaatti.fi/fi/hankinnat',NULL,'[\"uusi\", \"aikakausi\", \"oikeuspsykiatrisessa\", \"hoidossa\", \"niuvanniemen\", \"sairaalan\", \"uudisrakennuksen\", \"suunnittelukilpailu\", \"käynnistyy\", \"senaatti\", \"kiinteistot\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Hankinnat\\n                                                                            — 30.04.2025 Uusi aikakausi oikeuspsykiatrisessa hoidossa – Niuvanniemen sairaalan uudisrakennuksen suunnittelukilpailu käynnistyy Valtion toimitiloista vastaava Senaatti-kiinteistöt käynnistää merkittävän suunnittelukilpailun Niuvanniemen sairaalan uudisrakennuksen toteuttamiseksi. Kilpailu on osa laajempaa kehityshanketta, jonka tavoitteena on vastata tulevaisuuden vaativan oikeuspsykiatrisen hoidon tarpeisiin.…\"}',52,NULL,'2026-09-04 10:07:25','2026-09-08 15:16:50');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (14,'542783e802445655c98c','StateOrgs','RFP','OPEN','Julkisiin hankintoihin rohkeutta uudistua, ei sääntelytsunamia','','Senaatti-kiinteistot','ANY',10,13,NULL,NULL,NULL,'EUR','https://www.senaatti.fi/fi/hankinnat',NULL,'[\"julkisiin\", \"hankintoihin\", \"rohkeutta\", \"uudistua\", \"sääntelytsunamia\", \"senaatti\", \"kiinteistot\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Hankinnat\\n                                                                            — 05.03.2025 Julkisiin hankintoihin rohkeutta uudistua, ei sääntelytsunamia Senaatti-konserni kannattaa vahvasti julkisten hankintojen kehittämistä ja kilpailun edistämistä. On kaikkien etu, että meillä on toimivat markkinat julkisissa hankinnoissa. Hankintalakiin on esitetty useita tiukennuksia, jotka eivät välttämättä johda haluttuihin lopputuloksiin.…\"}',48,NULL,'2026-09-04 10:07:25','2026-09-08 15:16:50');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (15,'9bf3c6e7f2f15c7fcf2d','StateOrgs','RFP','OPEN','Caishan matka hankintojen parissa','','Senaatti-kiinteistot','ANY',10,13,NULL,NULL,NULL,'EUR','https://www.senaatti.fi/fi/hankinnat',NULL,'[\"caishan\", \"matka\", \"hankintojen\", \"parissa\", \"senaatti\", \"kiinteistot\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Hankinnat\\n                                                                            — 25.11.2024 Caishan matka hankintojen parissa Caisha aloitti Senaatissa kesätyöntekijänä, mutta mahdollisuus kehittää omaa osaamista vei hänet pidemmälle. Nyt hän yhdistää projektityön ja opinnot joustavasti ja nauttii jatkuvasta oppimisesta.\"}',52,NULL,'2026-09-04 10:07:25','2026-09-08 15:16:50');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16,'b65230c1aa8bf465f35f','StateOrgs','RFP','OPEN','Toimittajatyytyväisyystutkimus 2024: luotettavuus ja asiantuntevuus saivat kiitosta Senaatti-konsernin toimittajilta','','Senaatti-kiinteistot','ANY',6,13,NULL,NULL,NULL,'EUR','https://www.senaatti.fi/fi/hankinnat',NULL,'[\"senaatti\", \"toimittajatyytyväisyystutkimus\", \"luotettavuus\", \"asiantuntevuus\", \"saivat\", \"kiitosta\", \"konsernin\", \"toimittajilta\", \"kiinteistot\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Hankinnat\\n                                                                            — 06.11.2024 Toimittajatyytyväisyystutkimus 2024: luotettavuus ja asiantuntevuus saivat kiitosta Senaatti-konsernin toimittajilta Senaatti-konsernin toiminnassa palveluntuottajilla on merkittävä rooli asiakkaille tuotettavissa palveluissa, sillä ostamme valtaosan näistä palveluista markkinoilta. Toimittajat ovat meille tärkeitä kumppaneita. Tähän liittyen toteutimme hankintojen kehitysohjelmassa…\"}',52,NULL,'2026-09-04 10:07:25','2026-09-08 15:16:50');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (17,'42a47aacd3c7a0c19593','StateOrgs','RFP','OPEN','​​Hankintojen infotilaisuudet käynnistyivät hienosti​','','Senaatti-kiinteistot','ANY',10,13,NULL,NULL,NULL,'EUR','https://www.senaatti.fi/fi/hankinnat',NULL,'[\"hankintojen\", \"infotilaisuudet\", \"käynnistyivät\", \"hienosti\", \"senaatti\", \"kiinteistot\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Hankinnat\\n                                                                            — 07.08.2024 ​​Hankintojen infotilaisuudet käynnistyivät hienosti​ Hankimme vuosittain yli miljardilla ja rakentamisen hankintamme ovat kasvussa ympäri Suomen. Tavoitteemme hankintojen kehitysohjelman taustalla on, että olemme houkutteleva tilaaja ja saamme nostettua tarjoushalukkuutta. Toimittajatilaisuudet ovat yksi keino parantaa mielikuvaa…\"}',52,NULL,'2026-09-04 10:07:25','2026-09-08 15:16:50');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (18,'61a8fbf2ae363f3557cc','StateOrgs','RFP','OPEN','Senaatti-konserni käynnisti hankintojen kehitysohjelman: jo 23 miljoonan euron säästöt','','Senaatti-kiinteistot','ANY',10,13,NULL,NULL,NULL,'EUR','https://www.senaatti.fi/fi/hankinnat',NULL,'[\"senaatti\", \"konserni\", \"käynnisti\", \"hankintojen\", \"kehitysohjelman\", \"miljoonan\", \"euron\", \"säästöt\", \"kiinteistot\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Hankinnat\\n                                                                            — 22.04.2024 Senaatti-konserni käynnisti hankintojen kehitysohjelman: jo 23 miljoonan euron säästöt Valtion kiinteistöistä vastaava Senaatti-konserni käynnisti kesällä 2023 hankintatoimen kehitysohjelman, jonka tavoitteena on lisätä hankintojen tuloksellisuutta ja helpottaa yritysten osallistumista julkisiin kilpailutuksiin. Kehitysohjelma on käynnistynyt rivakasti.…\"}',48,NULL,'2026-09-04 10:07:25','2026-09-08 15:16:50');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (19,'f85f8f91b27d4944e13a','Universities','RFP','OPEN','Current large procurements Åbo Akademi publishes procurements that are included in the scope of application of the Procu','Åbo Akademi publishes procurements that are included in the scope of application of the Procurement Act, i.e. those procurements that exceed the national thresholds and the EU thresholds in HILMA. In connection with the procurement announcement, there is a link to Åbo Akademi’s tender requests in the Cloudia Supplier Portal service . To get a username and password, you can register for the service. Registration is free.','Åbo Akademi University','ANY',6,4,NULL,NULL,NULL,'EUR','https://www.facebook.com/sharer.php?u=https%3A%2F%2Fwww.abo.fi%2Fen%2Fcollaborate-with-us%2Fprocurements-at-abo-akademi-university%2Fu0026amp;t=Procurements+at+%C3%85bo+Akademi+University',NULL,'[\"procurements\", \"akademi\", \"publishes\", \"included\", \"scope\", \"application\", \"procurement\", \"thresholds\", \"service\", \"current\", \"large\", \"procu\", \"those\", \"exceed\", \"national\", \"hilma\", \"connection\", \"announcement\", \"there\", \"link\"]',NULL,NULL,NULL,'{\"text\": \"Current large procurements Åbo Akademi publishes procurements that are included in the scope of application of the Procurement Act, i.e. those procurements that exceed the national thresholds and the EU thresholds in HILMA. In connection with the procurement announcement, there is a link to Åbo Akademi’s tender requests in the Cloudia Supplier Portal service . To get a username and password, you can register for the service. Registration is free. Cloudia Supplier Portal Current small procurements Small procurements, i.e. procurements below national thresholds can be published here on Åbo Akademi’s website. Contact persons email: upphandling@abo.fi\"}',50,NULL,'2026-09-04 10:11:20','2026-09-08 15:18:15');
