INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (21,'2024-147414','HILMA','RFP','OPEN','Tarjouspyyntö - Rakennettavuusselvitys L107 Lohjansolmun asemanseudun asemakaavan laatimista varten','Lohjan kaupungin kaavoitus pyytää tarjoustanne maaperä- ja rakennettavuusselvitysten, perustamistapasuositusten sekä vaikutusselvitysten laatimisesta L107 Lohjansolmun asemanseudun asemakaavan laatimista varten. Hankinnan kuvaus Lohjan kaupungin kaavoitus pyytää tarjoustanne maaperä- ja rakennettavuusselvitysten, perustamistapasuositusten sekä vaikutusselvitysten laatimisesta L107 Lohjansolmun asemanseudun asemakaavan laatimista varten. Selvityksen kohteena oleva alue sijaitsee E18 moottoritien pohjoispuolella, noin 5 km Lohjan keskustasta. Selvitysalueen pinta-ala on noin 20,5 hehtaaria. Selvitysalueella sijaitsee yksi kiinteä muinaisjäännös. Espoo-Salo -oikoradan eli ns. Turun tunnin junan asemanseudusta on tarkoitus muodostua n. 15000 asukkaan kaupunginosa Y5a Lohjansolmun asemanseudun ja Lehmijärvi-Pulli maaseutualueiden osayleiskaavan mukaisesti. L107 Lohjansolmun aseman asemakaava tulee olemaan Y5a osayleiskaava-alueen ensimmäinen asemakaava, jonka laatimisen yhteydessä tulee ottaa huomioon ja mahdollistaa alueen myöhempi suotuisa kehitys. Selvitysalueen maankäyttöä on tarkoitus kehittää valtaosin kaupunkimaisena ja tiiviinä keskustatoimintojen alueena. Osayleiskaavatyön yhteydessä alueen rakennettavuutta, vaikutusta pohjavesiin ja massataloutta on selvitetty yleiskaavatasoisesti. Selvityksen sisältö: Selvityksessä tulee: - Tarkentaa tietoa alueen pohjasuhteista ja niiden vaihteluista, pohjaveden olosuhteista, selvittää tarkemmin alueen rakennettavuus sekä antaa yleispiirteiset perustamistapaesitykset erityyppisille rakenteille ja rakennuksille. - Vertailla tuloksia alustavaan suunnitelmaan (sisältää osayleiskaavasta tarkentuneet tielinjaukset ja käyttötarkoitusalueet), ja tarvittaessa esittää vaihtoehtoisia soveltuvia alueita osayleiskaavassa ja ratasuunnitelmassa suunnitelluille toiminnoille. - Tutkia tarvetta maanleikkauksille ja täytöille, pyrkien kustannustehokkaasti optimoimaan massatasapaino ja hulevesien ohjaus muuttamatta alueen luonnonvesien tilaa.- Tutkia mahdollisuudet maalämpökaivoille energian lähteinä ja ylijäämäenergian varastoinnille lämpökaivoihin. Tehtävän kuvaus: Työn tuloksena on tarkoitus laatia asemakaavahankkeita tukeva selvitys alueen rakennettavuudesta. Tarjoukseen tulee sisältyä tilaajan toiveita vastaava työsuunnitelma: työvaiheet, menetelmät, aikataulu, aloituskokous, tarpeellinen määrä työkokouksia ja loppukokous sekä valmiin selvityksen esittely kaavoitukselle. Muista mahdollisista työn esittelyistä sovitaan erikseen. Pohjatutkimuspisteiden numerointi tulee sovittaa kaupungin järjestelmien mukaan. Aikataulu ja raportointi: Tehtävän suorittaminen aloitetaan mahdollisimman pian tarjouksen hyväksymisen jälkeen. Selvityksen alustavien tulosten tulisi pääosin olla tilaajan käytettävissä 31.10.2024 mennessä, jolloin tilaajalle tulee toimittaa tiedot vektorimuodossa (*.shp, koordinaattijärjestelmä Euref GK24, N60) sekä tietokantana (gdb, PostGIS). Raporttiluonnos toimitetaan tilaajalle 1.12.2024 mennessä ja tilaaja voi tarvittaessa kommentoida sen sisältöä. Selvitysraportin tulee olla viimeistelty 8.1.2025 mennessä. Raportti toimitetaan tilaajalle pdf-muodossa ja sen tulee sisältää myös kartat sekä viimeistellyt paikkatiedot tilaajan toivomassa formaatissa. Tarjouksen jättäjät voivat myös ehdottaa muuta aikataulua. Työn tulokset esitetään raportissa (.pdf), jonka tulee sisältää myös kartat. Raportin (.pdf) tulee teknisesti täyttää saavutettavuusdirektiivin (306/2019) vaatimukset, jotka koskevat julkisen sektorin asiakirjatuotantoa. Kaikki kartta-aineistot tulee toimittaa sekä vektoriaineistona että paikkatietomuodossa. Tarkemmat tiedot aineiston toimittamisesta: - Vektoriaineisto (*.shp) - Paikkatieto toimitetaan tietokantana (esim. gdb, PostGIS) - Paikkatietoaineiston toimitetaan tietolajien kuvaus sekä tarvittaessa kaavio aineistojen linkityksistä - Geotiff- rasterikartat selvityksen kartoista - Koordinaatisto: GK24, N60 Lohjan kaupunki toimittaa valitulle konsultille hallussaan olevaa lähtötietoaineistoa.','Lohjan kaupunki','ANY',5,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-147414','[\"71311000\"]','[\"tulee\", \"alueen\", \"lohjansolmun\", \"lohjan\", \"selvityksen\", \"asemanseudun\", \"toimitetaan\", \"asemakaavan\", \"laatimista\", \"varten\", \"kaupungin\", \"kuvaus\", \"tarkoitus\", \"sisältää\", \"tarvittaessa\", \"työn\", \"tilaajan\", \"mennessä\", \"tilaajalle\", \"toimittaa\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/lohja?id=514363&tpk=86c0924d-848c-412a-81e4-a3fa6d5e007f\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-147414\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-147414\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"71311000\", \"currency\": null, \"deadline\": \"2024-06-20T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1B1\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"Hankinnan kuvaus Lohjan kaupungin kaavoitus pyytää tarjoustanne maaperä- ja rakennettavuusselvitysten, perustamistapasuositusten sekä vaikutusselvitysten laatimisesta L107 Lohjansolmun asemanseudun asemakaavan laatimista varten. Selvityksen kohteena oleva alue sijaitsee E18 moottoritien pohjoispuolella, noin 5 km Lohjan keskustasta. Selvitysalueen pinta-ala on noin 20,5 hehtaaria. Selvitysalueella sijaitsee yksi kiinteä muinaisjäännös. Espoo-Salo -oikoradan eli ns. Turun tunnin junan asemanseudusta on tarkoitus muodostua n. 15000 asukkaan kaupunginosa Y5a Lohjansolmun asemanseudun ja Lehmijärvi-Pulli maaseutualueiden osayleiskaavan mukaisesti. L107 Lohjansolmun aseman asemakaava tulee olemaan Y5a osayleiskaava-alueen ensimmäinen asemakaava, jonka laatimisen yhteydessä tulee ottaa huomioon ja mahdollistaa alueen myöhempi suotuisa kehitys. Selvitysalueen maankäyttöä on tarkoitus kehittää valtaosin kaupunkimaisena ja tiiviinä keskustatoimintojen alueena. Osayleiskaavatyön yhteydessä alueen rakennettavuutta, vaikutusta pohjavesiin ja massataloutta on selvitetty yleiskaavatasoisesti.  Selvityksen sisältö:  Selvityksessä tulee: - Tarkentaa tietoa alueen pohjasuhteista ja niiden vaihteluista, pohjaveden olosuhteista, selvittää tarkemmin alueen rakennettavuus sekä antaa yleispiirteiset perustamistapaesitykset erityyppisille rakenteille ja rakennuksille. - Vertailla tuloksia alustavaan suunnitelmaan (sisältää osayleiskaavasta tarkentuneet tielinjaukset ja käyttötarkoitusalueet), ja tarvittaessa esittää vaihtoehtoisia soveltuvia alueita osayleiskaavassa ja ratasuunnitelmassa suunnitelluille toiminnoille. - Tutkia tarvetta maanleikkauksille ja täytöille, pyrkien kustannustehokkaasti optimoimaan massatasapaino ja hulevesien ohjaus muuttamatta alueen luonnonvesien tilaa.- Tutkia mahdollisuudet maalämpökaivoille energian lähteinä ja ylijäämäenergian varastoinnille lämpökaivoihin.  Tehtävän kuvaus:  Työn tuloksena on tarkoitus laatia asemakaavahankkeita tukeva selvitys alueen rakennettavuudesta.  Tarjoukseen tulee sisältyä tilaajan toiveita vastaava työsuunnitelma: työvaiheet, menetelmät, aikataulu, aloituskokous, tarpeellinen määrä työkokouksia ja loppukokous sekä valmiin selvityksen esittely kaavoitukselle. Muista mahdollisista työn esittelyistä sovitaan erikseen. Pohjatutkimuspisteiden numerointi tulee sovittaa kaupungin järjestelmien mukaan.  Aikataulu ja raportointi:  Tehtävän suorittaminen aloitetaan mahdollisimman pian tarjouksen hyväksymisen jälkeen.  Selvityksen alustavien tulosten tulisi pääosin olla tilaajan käytettävissä 31.10.2024 mennessä, jolloin tilaajalle tulee toimittaa tiedot vektorimuodossa (*.shp, koordinaattijärjestelmä Euref GK24, N60) sekä tietokantana (gdb, PostGIS).  Raporttiluonnos toimitetaan tilaajalle 1.12.2024 mennessä ja tilaaja voi tarvittaessa kommentoida sen sisältöä. Selvitysraportin tulee olla viimeistelty 8.1.2025 mennessä.  Raportti toimitetaan tilaajalle pdf-muodossa ja sen tulee sisältää myös kartat sekä viimeistellyt paikkatiedot tilaajan toivomassa formaatissa.   Tarjouksen jättäjät voivat myös ehdottaa muuta aikataulua.  Työn tulokset esitetään raportissa (.pdf), jonka tulee sisältää myös kartat. Raportin (.pdf) tulee teknisesti täyttää saavutettavuusdirektiivin (306/2019) vaatimukset, jotka koskevat julkisen sektorin asiakirjatuotantoa.   Kaikki kartta-aineistot tulee toimittaa sekä vektoriaineistona että paikkatietomuodossa. Tarkemmat tiedot aineiston toimittamisesta:  - Vektoriaineisto (*.shp) - Paikkatieto toimitetaan tietokantana (esim. gdb, PostGIS)  - Paikkatietoaineiston toimitetaan tietolajien kuvaus sekä tarvittaessa kaavio aineistojen linkityksistä  - Geotiff- rasterikartat selvityksen kartoista  - Koordinaatisto: GK24, N60   Lohjan kaupunki toimittaa valitulle konsultille hallussaan olevaa lähtötietoaineistoa.\", \"descriptionSv\": null, \"procedureType\": \"open\", \"estimatedValue\": 0.0, \"expirationDate\": \"2024-06-20T09:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": null, \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": 0, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"s