INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (22,'2024-007880','HILMA','RFP','OPEN','Rataisännöinti, Länsi-Suomi, 2024-2027','Rataisännöinti, Länsi-Suomi, 2024-2027 HANKINNAN KOHDE Hankinnan kohteena on Länsi-Suomen rataisännöinti tarjouspyynnössä ja sen liitteissä määritellyn mukaisesti. Hankinnan kohdetta on kuvattu muun ohella tarjouspyynnön liitteessä 4 \"Hankinnan kohteen kuvaus ja vaatimukset\". Sopimuskausi on kolme (3) vuotta ja seitsemän (7) kuukautta (ks. sopimuksen luku 5). Sopimukseen sisältyy optiona sopimuksen jatkaminen enintään kahdella (2) enintään kahden (2) vuoden pituisella optiokaudella (ks. sopimuksen luku 6). HANKINNAN LAAJUUS Hankinnan ennakoitu kokonaisarvo sopimuskaudella optiot mukaan lukien on 7-8,5 miljoonaa euroa (alv 0%). Palvelu koostuu tuntihintaisista asiantuntijatöistä ja matkustamisesta, joiden tarve vaihtelee ja joita ei ole mahdollista ennustaa tarkasti etukäteen. Lisäksi hankinnan kohteeseen sisältyy muuta asiantuntijatyötä, jonka määrää on vaikea ennustaa tarkasti etukäteen. Hankintayksiköllä ei ole myöskään tarkkaa tietoa tarjottavista asiantuntijoiden tuntihinnoista. Hankinnan ennakoituun kokonaisarvoon on laskettu seitsemän (7) vuoden ja seitsemän (7) kuukauden ajalta arvioidut kustannukset. Edellä esitetty kokonaisarvo on sitoumukseton arvio. Hankinnan laajuutta on kuvattu tarkemmin tarjouspyynnön liitteissä, erityisesti liitteessä 4 \"Hankinnan kohteen kuvaus ja vaatimukset\".,','Väylävirasto','ANY',4,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-007880','[\"50220000\", \"71311230\"]','[\"hankinnan\", \"rataisännöinti\", \"länsi\", \"sei