INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (23,'2024-007877','HILMA','RFP','OPEN','Silmätautien erikoislääkäripalveluiden hankinta','Kainuun hyvinvointialue pyytää tarjouksia silmätautien erikoislääkäripalveluista Kainuun keskussairaalan silmätautien poliklinikalle puitejärjestelyin sopimuskaudelle 1.5.2024-30.4.2025. Tilaaja varaa option 1+1 vuodelle. Hankinnan tärkein tavoite on saada palvelut lakisääteiselle tasolle laadukkaalla ja turvallisella toteutuksella. Silmätautien poliklinikalla käy vuosittain noin 9000 potilasta, joista ensikävijöitä on noin 1400. Hankittavaan palveluun kuuluu päivittäin 2-4 silmätautien erikoislääkärin työpanos silmäpoliklinikalle. Silmätautien poliklinikka on avoinna arkipäivisin klo 8:00 -15:30. Sairaalan virka-aika on klo 8-16, jolloin palvelua tuotetaan. Palveluntuotannon aikana voidaan vastata talon sisäisiin konsultaatiopyyntöihin, jolloin palvelulla tuetaan Tilaajan muuta toimintaa. Tilaajan hyväksymänä voidaan tiettyjä asioita kuten paperityöt (esim. lausuntojen laatiminen, laboratoriovastausten kommentointi jatko-ohjeineen) ja puhelinajat hoitaa myös etätyönä. Tällöin 4 paperityö/puhelintyöaikaa vastaa yhtä poliklinikkapäivän työtuntia. Hoitohenkilökunta toteuttaa mm. injektiohoitoja, joiden valvonta kuuluu Palveluntuottajan palveluntuotantoon. Tilaaja ja Palveluntuottaja sopivat sopimuskaudella tarkemmin palveluprosessista eli miten potilaille hoitoja annetaan. Tilaaja arvioi vastaanotettavien potilaiden määrän yhtä silmälääkäriä kohden olevan sopiva yhtä (1) työpäivää kohden. Osapuolet voivat sopimuskaudella keskustella ja sopia tarkennuksista vastaanotettavien potilaiden määrään. Pyrkimyksenä on sopiva potilasmäärä päivää kohden huomioiden palvelun laatu, Tilaajan resurssit, silmälääkärin osaaminen ja kuormitus sekä hoitoa odottavien potilaiden määrä. Poliklinikkapäivänä potilaita on noin 16 sekä päivystyspotilaita arviolta 4. Poliklinikalle tehdään myös pientoimenpiteitä paikallispuudutuksessa. Toimenpiteitä on 9-12 potilasta/päivä, näistä 1-3 toimenpidearvioita. Tilaaja järjestää välineistön ja muun henkilökunnan. Silmätautien erikoisalan tilanne 31.12.2023: • lähetejono 0 potilasta • määräaikaiskutsujono 175 • hoitajakäynnit 374 • pkl-toimenpiteet 13 Ilmoitetut hankittavan palvelun määrät ovat viitteellisiä eikä Tilaaja sitoudu hankinnassa mihinkään asiakas- tai toimenpidemääriin. Puitejärjestelyyn valitaan kaikki palveluntuottajat, jotka ovat jättäneet hyväksytyn tarjouksen. Puitesopimuskumppanit asetetaan kokonaistaloudellisen edullisuuden mukaiseen etusijajärjestykseen osa-alueittain. , Polikliiniset leikkaukset Polikliiniset leikkaukset., Poliklinikkapäivä Poliklinikkapäivä,','Kainuun hyvinvointialue','ANY',3,3,NULL,NULL,750000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-007877','[\"85121200\"]','[\"silmätautien\", \"tilaaja\", \"kainuun\", \"noin\", \"potilasta\", \"tilaajan\", \"yhtä\", \"potilaiden\", \"kohden\", \"hyvinvointialue\", \"poliklinikalle\", \"kuuluu\", \"jolloin\", \"voidaan\", \"sopimuskaudella\", \"vastaanotettavien\", \"sopiva\", \"palvelun\", \"ovat\", \"polikliiniset\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/kainuunhyvinvointialue?id=496634&tpk=6782f2a6-5e0b-46cd-a0c0-28b10bae8b9c\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-007877\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-7877\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Polikliiniset leikkaukset\", \"titleSv\": \"\", \"cpvCodes\": \"85121200\", \"currency\": \"EUR\", \"deadline\": \"2024-04-16T09:00:00Z\", \"lowCarbon\": false, \"n