INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (24,'2024-007872','HILMA','OTHER','OPEN','Testi Clostridioides difficile PCR-pikadiagnostiikkaan','Testi Clostridioides difficile PCR-pikadiagnostiikkaan Hankinnan kohteena on testi Clostridioides difficile PCR-pikadiagnostiikkaan HUS Diagnostiikkakeskuksen ja ISLAB hyvinvointiyhtymän kliinisen mikrobiologian yksiköille. Kyseessä on yhteishankinta, jonka osapuolet on kuvattu tässä tarjouspyynnössä. Testi hankitaan HUS Diagnostiikkakeskuksen yksiköissä oleville GeneXpert (Cepheid)- tai vaihtoehtoisesti Cobas Liat (Roche)-laitteistoille sekä ISLABin yksiköissä oleville GeneXpert (Cepheid)-laitteistoille. Testiä tullaan käyttämään HUS Diagnostiikkakeskuksen Kymenlaakson ja Etelä-Karjalan sekä ISLAB hyvinvointiyhtymän Kuopion, Joensuun ja Mikkelin toimipisteissä. Hankittavan testin tulee olla CE-IVD-merkitty, laitevalmistajan kyseiselle laitteelle hyväksymä ja soveltua POC-PCR-diagnostiikkaan potilaiden ulostenäytteistä. Tarjoajan tulee tarjouksessaan ilmoittaa mille laitteistolle se tarjoaa testiä. Testihinnan tulee sisältää tarvittavat testikitit, kontrollit, kalibraattorit, testikohtaiset ohjelmistot, toimituskulut ja tuotetuki. Kyseessä on kokonaishankinta, eli hankintaa ei ole jaettu osiin. Hankinnasta tehdään sopimus kahden (2) vuoden sopimuskaudelle, jonka jälkeen sopimus jatkuu toistaiseksi voimassa olevana. Hankinnan kohde ja sitä koskevat vaatimukset on kuvattu yksityiskohtaisesti tarjouspyynnössä ja sen liitteissä. HUS ja ISLAB valitsevat sopimuskumppanikseen yhden (1) toimittajan, joka voi olla molemmilla joko sama tai eri.,','HUS-yhtymä','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-007872','[\"33696500\"]','[\"testi\", \"clostridioides\", \"difficile\", \"pikadiagnostiikkaan\", \"diagnostiikkakeskuksen\", \"islab\", \"tulee\", \"hankinnan\", \"hyvinvointiyhtymän\", \"kyseessä\", \"jonka\", \"kuvattu\", \"tarjouspyynnössä\", \"yksiköissä\", \"oleville\", \"genexpert\", \"cepheid\", \"laitteistoille\", \"testiä\", \"sopimus\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-007872\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-7872\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Testi Clostridioides difficile PCR-pikadiagnostiikkaan\", \"titleSv\": \"\", \"cpvCodes\": \"33696500\", \"currency\": null, \"deadline\": null, \"lowCarbon\": false, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Hankinnan kohteena on testi Clostridioides difficile PCR-pikadiagnostiikkaan HUS Diagnostiikkakeskuksen ja ISLAB hyvinvointiyhtymän kliinisen mikrobiologian yksiköille. Kyseessä on yhteishankinta, jonka osapuolet on kuvattu tässä tarjouspyynnössä. Testi hankitaan HUS Diagnostiikkakeskuksen yksiköissä oleville GeneXpert (Cepheid)- tai vaihtoehtoisesti Cobas Liat (Roche)-laitteistoille sekä ISLABin yksiköissä oleville GeneXpert (Cepheid)-laitteistoille. Testiä tullaan käyttämään HUS Diagnostiikkakeskuksen Kymenlaakson ja Etelä-Karjalan sekä ISLAB hyvinvointiyhtymän Kuopion, Joensuun ja Mikkelin toimipisteissä. Hankittavan testin tulee olla CE-IVD-merkitty, laitevalmistajan kyseiselle laitteelle hyväksymä ja soveltua POC-PCR-diagnostiikkaan potilaiden ulostenäytteistä.\\n\\nTarjoajan tulee tarjouksessaan ilmoittaa mille laitteistolle se tarjoaa testiä.\\n\\nTestihinnan tulee sisältää tarvittavat testikitit, kontrollit, kalibraattorit, testikohtaiset ohjelmistot, toimituskulut ja tuotetuki. \\n\\nKyseessä on kokonaishankinta, eli hankintaa ei ole jaettu osiin