INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (27,'2024-147400','HILMA','RFP','OPEN','TARJOUSPYYNTÖ: Siirrettävä varavoimakone','Hämeenlinnan kaupunki pyytää tarjoustanne varavoimakonelaitteesta. Varavoiman tarve kasvaa koko ajan sähköisten laitteiden määrän kasvun myötä. Varavoimakoneilla varmistetaan kriittisten järjestelmien toimiminen, tuotannon jatkuminen sähkökatkojen aikana. Kyseessä on yleisestä jakeluverkosta erillään toimivan tehonlähteen syöttämää sähköverkkoa. Kyseessä on Hankintalain (1397/2016) mukaista tavarahankintaa ja hankinnan ennakoitu arvo ylittää hankintalain kansallisen kynnysarvon. Hankinta kilpailutetaan kansallisena hankintana avoimena menettelynä siten, että kaikki soveltuvuusvaatimukset täyttävät pääsevät mukaan kilpailuun. Hankinnassa on määritelty liitteessä \'\'siirrettävän varavoimakoneen hankintaohjelma\'\' pakolliset laadulliset vaatimukset ja halvin hinta ratkaisee kilpailun. Sopimuskumppaniksi valitaan yksi toimija, joka toimittaa varavoimakoneen Tilaajalle. Kyseessä on käyttövalmis siirrettävä äänieristetty ja sääsuojattu varavoimalaitteisto tilaajalle toimitettuna. Hankintaan on sisällytettävä kaikki tarvittavat automaatio-, ohjaus- ja mittalaitteet sekä kaapelit. Hankintaan sisältyy tämän tarjouspyynnön mukainen varavoimalaitteisto suunnitteluineen, dokumentointeineen, toimituksineen, koekäyttöineen, täyteen toiminnalliseen käyttökuntoon saatettuna ja käytönopastus annettuna sekä huolto- ja kunnossapito-ohjeet luovutettuna varaosatietoineen, ellei edellä luetuista asioista ole kirjallisesti muuta sovittu. Kaikki ne laitteet ja työt, joiden normaalisti katsotaan kuuluvaan täydelliseen toimitukseen tai jotka ovat välttämättömiä laitteiden moitteettomalle toiminnalle, kuuluvat hankintaan siitä riippumatta, ovatko ne mainittu hankintaohjelmassa tai ei. Hankinnan kohteen tulee täyttää joka suhteessa Suomessa ja EU:ssa voimassa olevat lait, asetukset sekä muut viranomaisten asettamat määräykset.','Hämeenlinnan kaupunki','ANY',1,2,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-147400','[\"42100000\"]','[\"kyseessä\", \"hankintaan\", \"siirrettävä\", \"hämeenlinnan\", \"kaupunki\", \"laitteiden\", \"hankintalain\", \"hankinnan\", \"varavoimakoneen\", \"tilaajalle\", \"varavoimalaitteisto\", \"tarjouspyyntö\", \"varavoimakone\", \"pyytää\", \"tarjoustanne\", \"varavoimakonelaitteesta\", \"varavoiman\", \"tarve\", \"kasvaa\", \"koko\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/hameenlinna?id=517410&tpk=c46687cc-0527-438d-bb0c-0e5a0e73c3b7\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-147400\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-147400\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"42100000\", \"currency\": null, \"deadline\": \"2024-07-15T15:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1C2\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": null, \"descriptionFi\": \"Kyseessä on käyttövalmis siirrettävä äänieristetty ja sääsuojattu varavoimalaitteisto tilaajalle toimitettuna. Hankintaan on sisällytettävä kaikki tarvittavat automaatio-, ohjaus- ja mittalaitteet sekä kaapelit. Hankintaan sisältyy tämän tarjouspyynnön mukainen varavoimalaitteisto suunnitteluineen, dokumentointeineen, toimituksineen, koekäyttöineen, täyteen toiminnalliseen käyttökuntoon saatettuna ja käytönopastus annettuna sekä huolto- ja kunnossapito-ohjeet luovutettuna varaosatietoineen, ellei edellä luetuista asioista ole kirjallisesti muuta sovittu. Kaikki ne laitteet ja työ