INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (28,'2024-007907','HILMA','OTHER','OPEN','Koulunmäen yhtenäiskoulu, C-osan uudisrakennus / Kiintokalusteurakka HP 34','Koulunmäen yhtenäiskoulu, C-osan uudisrakennus / Kiintokalusteurakka HP 34 Äänekosken kaupunki pyysi tarjouksia Koulunmäen C-osan uudisrakennuskohteen kiintokalusteurakkaan. Äänekosken kaupunki ei valinnut tarjouskilpailun perusteella urakoitsijan Koulunmäen C-osan uudisrakennuskohteen kiintokalusteurakkaan. Urakka käsitti kiinteät kalusteet sekä muut suunnitelmien mukaiset kalusteet sekä niihin liittyvät kalustevarustukset asennettuna urakka-asiakirjojen mukaan Hankinnan sisältö on esitetty tarkemmin tarjouspyyntöasiakirjoissa. Hankinnan tässä vaiheessa työmaalla on käynnissä yläpohjavaihe. Kohteeseen ja sen ympäröiviin alueisiin voi tutustua oma-aloitteisesti menemättä työmaa-alueelle. Mikäli tutustuminen on tarve tehdä työmaa-alueelta käsin, on siitä sovittava etukäteen : WSP Finland Oy Juha Mäkelä Puhelin : 040 840 3145 Sähköposti: juha.makela@wsp.com Tarjoajalla ja myöhemmin urakkasopimuksen syntyessä osaurakoitsijalla ei ole myöhemmin oikeutta vedota urakka-asiakirjojen puutteisiin niiltä osin mikä on tutustumisen aikana ollut nähtävillä ja tarvittaessa selvitettävissä.,','Äänekosken kaupunki','ANY',2,15,NULL,NULL,450000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-007907','[\"45214500\", \"45421153\"]','[\"koulunmäen\", \"osan\", \"äänekosken\", \"kaupunki\", \"urakka\", \"yhtenäiskoulu\", \"uudisrakennus\", \"kiintokalusteurakka\", \"uudisrakennuskohteen\", \"kiintokalusteurakkaan\", \"kalusteet\", \"asiakirjojen\", \"hankinna