INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (31,'2024-147479','HILMA','RFP','OPEN','Ahlaisten saariston laitureiden kunnostaminen ja uusiminen','Metsähallitus kilpailuttaa Ahlaisten saariston retkisatamien laitureiden kunnostamisen ja uusimisen urakan tämän tarjouspyynnön sekä liitteenä olevan aineiston mukaisesti. Rakennuskohde sijaitsee Selkämeren kansallispuistossa Porin saaristossa sijaitsevien Ahlaisten saariston saarien Iso-Enskeri, Seliskeri, Munakari retkisatamissa on kolme laituria, yksi kussakin saaressa. Työt voidaan aloittaa syyskuussa 2024 kun sopimus on allekirjoitettu ja urakan tulee olla valmis 1.5.2025 mennessä. Kyseessä on kokonaisurakka ja urakassa noudatetaan rakennusurakan yleisiä sopimusehtoja YSE 1998 (RT 16–10660). Valittu urakoitsija toimii pääurakoitsijana ja lainsäädännön tarkoittamana päätoteuttajana. Urakoitsijaa koskee YSE 1 § -4 § tarkoittamat velvollisuudet jos tarjouspyynnössä tai sen liitteenä olevassa aineistossa ei ole muuta mainittu. Tarjous tulee jättää 28.8.2024 klo 16:00 mennessä. Pyydämme tarjoustanne Ahlaisten saariston retkisatamien laitureiden kunnostamisen ja uusimisen toteutukseen. Iso-Enskerin ja Seliskerin laiturit uusitaan ja Munakarin laiturin kunnostetaan vastaamaan luontomatkailun tarpeita. Tarkoituksena on parantaa retkisatamien laituri- ja poijurakenteita kestävillä ja käyttötarkoitukseen soveltuvilla ratkaisuilla. Laitureiden tulee soveltua huviveneiden pitkäaikaiseen kiinnitykseen. Satamissa ei ole sähköä eikä vettä. Rakenteiden ja ankkurointien tulee kestää aalto- ja jääkuormat sekä veneiden kiinnityksestä aiheutuvat kuormitukset. Käyntisilta tulee olla asennettavissa niin, että maatuen yläpinnan ja sillan välille ei synny kynnystä. Laiturirakenteissa tulee huomioida esteettömyyden vaatimukset. Iso-Enskeri Laiturin koko nykyistä vastaava. Uusittavan laiturin päähän lisätään T-kappale yhteysveneille, koko n. 8 x 3-4 m. Uusi käyntisilta. Uusi maatuki. Tarkemmat tiedot liitteessä 1. Tiedot nykyisestä laiturista: Kelluva betoniponttooni (lev. 2,55 m * paks. 0,85 m * pit. noin 13 m) kä-velysillalla (lev. 1,25 m * pit. 6 m). Ankkuroitu 1 400 kg:n ankkureilla ja 2 cm paksuilla galvanoiduilla kettingeillä. Seliskeri Laituri ja kulkusilta uusitaan. Laiturin päähän lisätään T-kappale yhteysveneille, koko n. 8 x 3-4 m. Uusi käyntisilta. Uusi maatuki. Tarkemmat tiedot liitteessä 2. Tiedot nykyisestä laiturista: kelluva betoniponttooni (lev. 2,55 m * paks. 0,85 m * pit. noin 21 m) maatuella (3 m * 2,5 m) ja kävelysillalla (lev. 1,25 m * pit. 6 m). Ankkuroitu 1 400 kg:n ankkureilla ja 2 cm paksuilla galvanoiduilla kettingeillä. Munakari Laituri korjataan liitteen 3 mukaisesti. Tiedot nykyisestä laiturista: lev. 2,55 m * paks. 0,85 m * pit. noin 8 metriä.','Metsähallitus','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-147479','[\"45241100\"]','[\"tulee\", \"tiedot\", \"ahlaisten\", \"saariston\", \"laitureiden\", \"laiturin\", \"uusi\", \"metsähallitus\", \"retkisatamien\", \"laituri\", \"käyntisilta\", \"koko\", \"nykyisestä\", \"laiturista\", \"paks\", \"noin\", \"kunnostamisen\", \"uusimisen\", \"urakan\", \"liitteenä\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/metsahallitus?id=517191&tpk=96e493c0-9dfa-4beb-a27a-bc147913c709\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-147479\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-147479\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"45241100\", \"currency\": null, \"deadline\": \"2024-08-28T13:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI196\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": null, \"descriptionFi\": \"Pyydämme tarjoustanne Ahlaisten saariston retkisatamien laitureiden kunnostamisen ja uusimisen toteutukseen.  Iso-Enskerin ja Seliskerin laiturit uusitaan ja Munakarin laiturin kunnostetaan vastaamaan luontomatkailun tarpeita.   Tarkoituksena on parantaa retkisatamien laituri- ja poijurakenteita kestävillä ja käyttötarkoitukseen soveltuvilla ratkaisuilla. Laitureiden tulee soveltua huviveneiden pitkäaikaiseen kiinnitykseen. Satamissa ei ole sähköä eikä vettä. Rakenteiden ja ankkurointien tulee kestää aalto- ja jääkuormat sekä veneiden kiinnityksestä aiheutuvat kuormitukset. Käyntisilta tulee olla asennettavissa niin, että maatuen yläpinnan ja sillan välille ei synny kynnystä. Laiturirakenteissa tulee huomioida esteettömyyden vaatimukset.  Iso-Enskeri  Laiturin koko nykyistä vastaava. Uusittavan laiturin päähän lisätään T-kappale yhteysveneille, koko n. 8 x 3-4 m. Uusi käyntisilta. Uusi maatuki.  Tarkemmat tiedot liitteessä 1.  Tiedot nykyisestä laiturista: Kelluva betoniponttooni (lev. 2,55 m * paks. 0,85 m * pit. noin 13 m) kä-velysillalla (lev. 1,25 m * pit. 6 m). Ankkuroitu 1 400 kg:n ankkureilla ja 2 cm paksuilla galvanoiduilla kettingeillä.  Seliskeri Laituri ja kulkusilta uusitaan. Laiturin päähän lisätään T-kappale yhteysveneille, koko n. 8 x 3-4 m.  Uusi käyntisilta. Uusi maatuki.  Tarkemmat tiedot liitteessä 2.  Tiedot nykyisestä laiturista: kelluva betoniponttooni (lev. 2,55 m * paks. 0,85 m * pit. noin 21 m) maatuella (3 m * 2,5 m) ja kävelysillalla (lev. 1,25 m * pit. 6 m). Ankkuroitu 1 400 kg:n ankkureilla ja 2 cm paksuilla galvanoiduilla kettingeillä.  Munakari Laituri korjataan liitteen 3 mukaisesti.  Tiedot nykyisestä laiturista: lev. 2,55 m * paks. 0,85 m * pit. noin 8 metriä.\", \"descriptionSv\": null, \"procedureType\": \"open\", \"estimatedValue\": 0.0, \"expirationDate\": \"2024-08-28T13:00:00Z\", \"cir