INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (34,'2024-007833','HILMA','RFP','OPEN','MliDno-2024-58/ Mikkelin kaupungin puutavaran kuljetuspalvelut vuosille 2024 -2026 + 1 optiovuosi','MliDno-2024-58/ Mikkelin kaupungin puutavaran kuljetuspalvelut vuosille 2024 -2026 + 1 optiovuosi Mikkelin kaupunki pyytää avoimella tarjousmenettelyllä tarjousta puutavaran kuljetuspalvelusta metsät ja vesialueet -vastuualueen käyttöön. Sopimus tehdään yhden urakoitsijan kanssa alustavasti ajanjaksolle (5.2024 - 5.2026). Ja tämän jälkeen tarvittaessa mahdollinen optiovuosi (5.2026- 5.2027) tilaajan toimesta. Työkohteiden ja toiminnan kuvaus: Puutavaran kuljetuksiin kuuluu metsuri- tai konehakkuuna tehdyn puutavaran ja energiapuun sekä hakkuutähteen ajo varastopaikoille. Samalla laitteistolla voidaan tehdä myös pienimuotoista koneellista energiapuun korjuuta. Työmaat sijaitsevat pääasiassa taajamissa ja rakennettavilla kohteilla. Tehtäviin kuuluu myös osallistuminen yksittäisten puiden (katu- ja pihapuut) poistoon asemakaava-alueilla. Toiminta on ympärivuotista ja arvioitu vuosittainen työmäärä on noin 1200 ajotuntia. Kalustovaatimukset: -Metsävarusteinen liikenne- tai maataloustraktori, jossa, mekaanisesti vetävä perävaunu runkolukolla. -Traktorissa tulee olla ketjut sekä perävaunussa telat. -Säännösten mukaisesti tarkastettu kuormausnosturi, jonka vähimmäisulottuvuus on kymmenen (10) metriä. -Ajoneuvo on rekisteröity tieliikenteeseen. -Traktorin sekä perävaunun tulee olla varustettu varoitusvaloilla/vilkuilla. -Perävaunu tulee olla varustettu risulaidoin. -Valmius tehdä energiapuukorjuuta keräävällä hakkuupäällä. Yleiset vaatimukset: -Palvelun toimitusmahdollisuus yhden (1) viikon varoitusajalla. -Metsätuhoja aiheuttavan luonnonilmiön sattuessa talousmetsässä tai taajamassa, Mikkelin Kaupunki on oikeutettu olemaan ensisijainen palvelun saaja 12 tunnin varoitusajalla.,','Mikkelin kaupunki','SME',4,3,NULL,NULL,300000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-007833','[\"77200000\"]','[\"mikkelin\", \"puutavaran\", \"optiovuosi\", \"kaupunki\", \"tulee\", \"mlidno\", \"kaupungin\", \"kuljetuspalvelut\", \"vuosille\", \"yhden\", \"kuuluu\", \"energiapuun\", \"tehdä\", \"perävaunu\", \"varustettu\", \"palvelun\", \"varoitusajalla\", \"pyytää\", \"avoimella\", \"tarjousmenettelyllä\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/mikkeli?id=500475&tpk=95ea3c8c-39a6-47ec-a415-c8ecc38d4754\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-007833\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-7833\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"MliDno-2024-58/ Mikkelin kaupungin puutavaran kuljetuspalvelut vuosille 2024 -2026 + 1 optiovuosi\", \"titleSv\": \"\", \"cpvCodes\": \"77200000\", \"currency\": \"EUR\", \"deadline\": \"2024-04-15T13:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI1D1\", \"titleOther\": \"\", \"biodiversity\": true, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Mikkelin kaupunki pyytää avoimella tarjousmenettelyllä tarjousta puutavaran kuljetuspalvelusta metsät ja vesialueet -vastuualueen käyttöön. Sopimus tehdään yhden urakoitsijan kanssa alustavasti ajanjaksolle (5.2024 - 5.2026). Ja tämän jälkeen tarvittaessa mahdollinen optiovuosi (5.2026- 5.2027) tilaajan toimesta.\\n\\nTyökohteiden ja toiminnan kuvaus: Puutavaran kuljetuksiin kuuluu metsuri- tai konehakkuuna tehdyn puutavaran ja energiapuun sekä hakkuutähteen ajo varastopaikoille. Samalla laitteistolla voidaan tehdä myös pienimuotoista koneellista energiapuun korjuuta. Työmaat sijaitsevat pääasiassa taajamissa ja rakennettavilla kohteilla. Tehtäviin kuuluu myös osallistuminen yksittäisten puiden (katu- ja pihapuut) poistoon asemakaava-alueilla. Toiminta on ympärivuotista ja arvioitu vuosittainen työmäärä on noin 1200 ajotuntia.\\n\\nKalustovaatimukset: \\n-Metsävarusteinen liikenne- tai maataloustraktori, jossa, mekaanisesti vetävä perävaunu runkolukolla. \\n-Traktorissa tulee olla ketjut sekä perävaunussa telat. \\n-Säännösten mukaisesti tarkastettu kuormausnosturi, jonka vähimmäisulottuvuus on kymmenen (10) metriä.\\n-Ajoneuvo on rekisteröity tieliikenteeseen. \\n-Traktorin sekä perävaunun tulee olla varustettu varoitusvaloilla/vilkuilla.\\n-Perävaunu tulee olla varustettu risulaidoin.\\n-Valmius tehdä energiapuukorjuuta keräävällä hakkuupäällä.\\n\\nYleiset vaatimukset: \\n-Palvelun toimitusmahdollisuus yhden (1) viikon varoitusajalla. \\n-Metsätuhoja aiheuttavan luonnonilmiön sattuessa talousmetsässä tai taajamassa, Mikkelin Kaupunki on oikeutettu olemaan ensisijainen palvelun saaja 12 tunnin varoitusajalla.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": 300000.0, \"expirationDate\": \"2024-04-15T13:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": false, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": true, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportun