INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (35,'2024-007828','HILMA','OTHER','OPEN','LIPA Harjun stadionin peruskorjaus ja uusi katsomorakennus, Pää- ja arkkitehtisuunnittelu','LIPA Harjun stadionin peruskorjaus ja uusi katsomorakennus, Pää- ja arkkitehtisuunnittelu Jyväskylän kaupungin liikuntapalvelut pyytää tarjouksia Harjun Stadionin peruskorjauksen ja uuden katsomorakennuksen pää- ja arkkitehtisuunnittelun tehtävistä tarjouspyynnön ja sen liitteiden mukaisesti. Investointihankkeen tavoitteena on luoda Harjun urheilukentälle stadionmaiset olosuhteet rakentamalla etusuoralle uusi katsomo oheistiloineen vanhan katsomon tilalle sekä peruskorjaamalla urheilun suorituspaikat. Suunnittelun lähtötietoina toimii hankkeelle laadittu hankesuunnitelma. Suunnittelutoimeksiannon käynnistymisen ehtona on Jyväskylän kaupunginvaltuuston lainvoimainen päätös hankkeesta. Suunnittelutyö on tarkoitus aloittaa heti lainvoimaisen päätöksen jälkeen tammikuussa 2024.,','Jyväskylän kaupunki','ANY',2,15,NULL,NULL,12276000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-007828','[\"71000000\"]','[\"harjun\", \"stadionin\", \"uusi\", \"jyväskylän\", \"lipa\", \"peruskorjaus\", \"katsomorakennus\", \"arkkitehtisuunnittelu\", \"kaupungin\", \"liikuntapalvelut\", \"pyytää\", \"tarjouksia\", \"peruskorjauksen\", \"uuden\", \"katsomorakennuksen\", \"arkkitehtisuunnittelun\", \"tehtävistä\", \"tarjouspyynnön\", \"liitteiden\", \"mukaisesti\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-007828\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-7828\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \