INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (43,'2024-147575','HILMA','RFI','OPEN','Tietopyyntö: HUS-näytteiden esikäsittely','Tämä asiakirja ei ole hankintailmoitus tai tarjouspyyntö vaan tarkentava markkinakartoitus eli tietopyyntö. Hankinta koostuu kahdesta osasta: OSA 1 pitää sisällään yhteensä 1-4 laitteistoa huoltoineen: - Laitteisto 1 on tarkoitus sijoittaa Kymenlaakson keskussairaalan laboratorioon. Laitteisto on tarkoitus tilata heti, kun hankintasopimus on solmittu. Asennusaikataulu sovitaan tilauksen tekemisen yhteydessä. - Laitteisto 2 on tarkoitus sijoittaa HUSLAB-talon näytteiden vastaanottoon (optio). - Laitteistot 3-4 on tarkoitus sijoittaa muihin HUS Diagnostiikkakeskuksen toimipisteisiin (optio) Optiolaitteistojen mahdollinen tilaus on tarkoitus tehdä vuosien 2025-2027aikana. OSA 2 pitää sisällään yhden (1) hankittavan verinäytteiden automaattisen esikäsittelylaitteiston, joka on tarkoitus sijoittaa Meilahden automaatiolaboratorioon liitettynä verenkuvarataan. Käsiteltävien näyteputkien määrä arkisin on 4000 – 5000 kappaletta vuorokaudessa (verenkuvat ja laskot). Hankinta sisältää sopimuksen laitteistojen vuokrauksesta viiden vuoden ajaksi sekä huoltosopimuksen. Hankinnan tavoitteena on löytää yhteistyökumppani, joka osallistuu paikallisen esikäsittelyprosessin suunnitteluun ja ohjelmiston edellyttämiin määrittelyihin sekä esikäsittelyautomaation prosessin kehittämiseen ja ylläpitoon koko sopimuskauden ajan. Valittu palveluntuottaja sitoutuu sopimusaikana tekemään toiminnan edellyttämiä muutoksia (mm. tutkimuksen reitittäminen, erilaisten telineiden ohjelmoinnit, laitteiston toiminnan ohjelmointi). Laitteiden tarkempi kuvaus ja vaatimus ovat tietopyynnön liitteenä. Tämä asiakirja ei ole hankintailmoitus tai tarjouspyyntö vaan tarkentava markkinakartoitus eli tietopyyntö. Hankinta koostuu kahdesta osasta: OSA 1 pitää sisällään yhteensä 1-4 laitteistoa huoltoineen: - Laitteisto 1 on tarkoitus sijoittaa Kymenlaakson keskussairaalan laboratorioon. Laitteisto on tarkoitus tilata heti, kun hankintasopimus on solmittu. Asennusaikataulu sovitaan tilauksen tekemisen yhteydessä. - Laitteisto 2 on tarkoitus sijoittaa HUSLAB-talon näytteiden vastaanottoon (optio). - Laitteistot 3-4 on tarkoitus sijoittaa muihin HUS Diagnostiikkakeskuksen toimipisteisiin (optio) Optiolaitteistojen mahdollinen tilaus on tarkoitus tehdä vuosien 2025-2027aikana. OSA 2 pitää sisällään yhden (1) hankittavan verinäytteiden automaattisen esikäsittelylaitteiston, joka on tarkoitus sijoittaa Meilahden automaatiolaboratorioon liitettynä verenkuvarataan. Käsiteltävien näyteputkien määrä arkisin on 4000 – 5000 kappaletta vuorokaudessa (verenkuvat ja laskot). Hankinta sisältää sopimuksen laitteistojen vuokrauksesta viiden vuoden ajaksi sekä huoltosopimuksen. Hankinnan tavoitteena on löytää yhteistyökumppani, joka osallistuu paikallisen esikäsittelyprosessin suunnitteluun ja ohjelmiston edellyttämiin määrittelyihin sekä esikäsittelyautomaation prosessin kehittämiseen ja ylläpitoon koko sopimuskauden ajan. Valittu palveluntuottaja sitoutuu sopimusaikana tekemään toiminnan edellyttämiä muutoksia (mm. tutkimuksen reitittäminen, erilaisten telineiden ohjelmoinnit, laitteiston toiminnan ohjelmointi). Laitteiden tarkempi kuvaus ja vaatimus ovat tietopyynnön liitteenä.','HUS-yhtymä','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-147575','[\"38000000\"]','[\"tarkoitus\", \"sijoittaa\", \"laitteisto\", \"hankinta\", \"pitää\", \"sisällään\", \"optio\", \"toiminnan\", \"tietopyyntö\", \"näytteiden\", \"tämä\", \"asiakirja\", \"hankintailmoitus\", \"tarjouspyyntö\", \"va