INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (48,'2024-147520','HILMA','RFP','OPEN','Satamaraiteen perusparannus, projekti 2891','Pohjois-Karjalan hankintatoimi pyytää antamaan tarjouksen Joensuun kaupungin kaupunkirakennepalveluiden toimeksiannosta satamaraiteen korjauksesta tämän tarjouspyynnön ja sen liitteiden mukaisessa laajuudessaan. Urakka käsittää raiteen saneerausta Peltolankadun ylikäytävän ja sataman raiteen välisillä osuuksilla. Saneeraustyö käsittää nykyisen raiteen uusimista. Uusiminen käsittää vanhan raiteen aseman mittaamisen, vanhan raiteen purkamisen, vanhan tukikerroksen poiston, uuden tukikerroksen ja raiteen asentamisen kaikkine siihen liittyvine töineen ja materiaaleineen täysin valmiiksi. Asennettu raide tarkemitataan työn jälkeen. Tarjous pyydetään yksikköhintaurakkana. Tarjous on sitova ja se tulee laatia suomen kielellä. Hankintaprosessi on kokonaisuudessaan suomenkielinen. Työmaan esittely pidetään sähköisenä Teamsin kautta perjantaina 28.6.2024 alkaen klo 10.00. Ilmoittautuminen työmaaesittelyyn tulee tehdä sähköpostitse osoitteeseen ilkka.ratilainen@joensuu.fi 27.6.2024 klo 10.00 mennessä. Urakoitsijan voi tutustua myös paikan päällä urakka-alueeseen ennen tarjouksen jättämistä. Huom! Tarjouksen jättämisen ehtona ei ole esittelyyn osallistuminen tai kohteessa paikan päällä käynti. Urakoitsija ei voi kuitenkaan myöhemmin vedota seikkoihin, jotka olisi tutustumisen yhteydessä käyneet ilmi. Urakan tulee täyttää Euroopan unionin suoraan velvoittavien säädösten, Suomen lakien ja asetusten sekä viranomaisten antamat määräykset mm. rakenteen, varusteiden, työ- ja paloturvallisuuden sekä sähköturvallisuuden osalta. Rakennuskohteena on Joensuun Peltolan alueella sijaitseva junarata. Saneerattava osuus sijoittuu Pelto-lankadun ylikäytävän ja satamaraiteen välisille osuuksille. Rakennushankkeesta käytetään nimitystä ”Satamaraiteen saneeraus”. Hankkeen projektinumero on 2891. Urakka käsittää raiteen saneerausta Peltolankadun ylikäytävän ja sataman raiteen välisillä osuuksilla. Saneeraustyö käsittää nykyisen raiteen uusimista. Uusiminen käsittää vanhan raiteen aseman mittaamisen, vanhan raiteen purkamisen, vanhan tukikerroksen poiston, uuden tukikerroksen ja raiteen asentamisen kaikkine siihen liittyvine töineen ja materiaaleineen täysin valmiiksi. Asennettu raide tarkemitataan työn jälkeen. Työmaan esittely pidetään sähköisenä Teamsin kautta perjantaina 28.6.2024 alkaen klo 10.00. Ilmoittautuminen työmaaesittelyyn tulee tehdä sähköpostitse osoitteeseen ilkka.ratilainen@joensuu.fi 27.6.2024 klo 10.00 mennessä. Urakoitsijan voi tutustua myös paikan päällä urakka-alueeseen ennen tarjouksen jättämistä. Huom! Tarjouksen jättämisen ehtona ei ole esittelyyn osallistuminen tai kohteessa paikan päällä käynti. Urakoitsija ei voi kuitenkaan myöhemmin vedota seikkoihin, jotka olisi tutustumisen yhteydessä käyneet ilmi. Tarkemmat tiedot urakasta ja sen sisällöstä ovat nähtävissä tarjouspyynnön liitteissä.','Pohjois-Karjalan hankintatoimi','ANY',2,3,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-147520','[\"45000000\"]','[\"raiteen\", \"käsittää\", \"vanhan\", \"tarjouksen\", \"satamaraiteen\", \"urakka\", \"tukikerroksen\", \"tulee\", \"paikan\", \"päällä\", \"ylikäytävän\", \"pohjois\", \"karjalan\", \"hankintatoimi\", \"joensuun\", \"tarjouspyynnön\", \"saneerausta\", \"peltolankadun\", \"sataman\", \"välisillä\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/jns?id=518264&tpk=377d7b6d-2bae-4137-9519-dded9a0bc18e\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-147520\", \"name\": \