INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (53,'2024-007664','HILMA','RFP','OPEN','T-sairaala lisäosa sprinkleriurakan tarjouskilpailukutsu','T-sairaala lisäosa sprinkleriurakan tarjouskilpailukutsu Tämä on tarjouskilpailukutsu T-sairaalan lisäosan rakentamisen sprinkleriurakasta täysin valmiiksi asennettuna. Uudisrakennukseen tulee sen valmistumisen jälkeen sijoittumaan infektio- ja iho-osasto ,neurologian poliklinikka ja asiantuntijapalvelut, sisätautiosasto, vatsakeskuksen tähystysyksikkö, vatsakeskuksen vastaanotot, dialyysi, lääkehoitopoliklinikka ja isotooppiosasto. Kohteeseen tulee puhdastiloja. Muutostöitä tehdään myös uudisosaan liittyvän vanhan sairaalanpuolella. Uudisrakennus sijoittuu T-sairaalan tontille Savitehtaankadun ja Hämeenkadun välittömään läheisyyteen. Tarjouskilpailu toteutetaan käyttämällä hankintalain 33 §:n mukaista rajoitettua menettelyä, jossa kaikki halukkaat talouden toimijat voivat jättää osallistumispyynnön perusteella osallistumishakemuksen jäljempänä kuvatulla tavalla. Ainoastaan hankintayksikön valitsemat ehdokkaat voivat tehdä tarjouksen. Hyväksyttävät ehdokkaat valitaan noudattamalla hankintailmoituksessa esitettyjä soveltuvuuden vähimmäisvaatimuksia sekä arviointiperusteita. Valitut ehdokkaat allekirjoittavat salassapitosopimuksen ennen aineiston luovuttamista heille .Tarjouskilpailu toteutetaan käyttämällä rajoitettua menettelyä, jossa kaikki halukkaat toimijat voivat jättää tarjouskilpailukutsun perusteella osallistumishakemuksen toimittamalla hankintayksikön vaatimat tiedot.,','Varsinais-Suomen hyvinvointialue','ANY',3,1,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-007664','[\"45000000\", \"44115500\", \"45343230\", \"44160000\"]','[\"tarjouskilpailukutsu\", \"voivat\", \"ehdokkaat\", \"sairaala\", \"lisäosa\", \"sprinkleriurakan\", \"sairaalan\", \"tulee\", \"vatsakeskuksen\", \"tarjouskilpailu\", \"toteutetaan\", \"käyttämällä\", \"rajoitettua\", \"menettelyä\", \"jossa\", \"halukkaat\", \"toimijat\", \"jättää\", \"perusteella\", \"osallistumishakemuksen\"]',NULL,NULL,'[{\"url\": \"https://bem.buildercom.net/html/rfq2registration/index?rfqId=11110&guid=c93c044d-bc85-4f79-b341-e6cd3ba7fc88\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2024-007664\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-7664\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"T-sairaala lisäosa sprinkleriurakan tarjouskilpailukutsu\", \"titleSv\": \"\", \"cpvCodes\": \"45000000 44115500 45343230 44160000\", \"currency\": null, \"deadline\": \"2024-05-10T09:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI1C1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Tämä on tarjouskilpailukutsu T-sairaalan lisäosan rakentamisen sprinkleriurakasta täysin valmiiksi asennettuna. Uudisrakennukseen tulee sen valmistumisen jälkeen sijoittumaan infektio- ja iho-osasto ,neurologian poliklinikka ja asiantuntijapalvelut, sisätautiosasto, vatsakeskuksen tähystysyksikkö, vatsakeskuksen vastaanotot, dialyysi, lääkehoitopoliklinikka ja isotooppiosasto. Kohteeseen tulee puhdastiloja. Muutostöitä tehdään myös uudisosaan liittyvän vanhan sairaalanpuolella. Uudisrakennus sijoittuu T-sairaalan tontille Savitehtaankadun ja Hämeenkadun välittömään läheisyyteen. Tarjouskilpailu toteutetaan käyttämällä hankintalain 33 §:n mukaista rajoitettua menettelyä, jossa kaikki halukkaat talouden toimijat voivat jättää osallistumispyynnön perusteella osallistumishakemuksen jäljempänä kuvatulla tavalla. Ainoastaan hankintayksikön