INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (58,'2024-147361','HILMA','RFP','OPEN','Kansallinen pienhankinta; Paavolan koulun suunnittelu','Hankinnan kohteena on Paavolan koulun luonnossuunnittelu osoitteeseen Hirsikankaantie 3, 62900 Alajärvi. Hankinnan tarkemmat tiedot ovat tässä tarjouspyynnössä sekä sen liitteenä olevissa dokumenteissa. Hankinta toteutetaan kaksivaiheisena menettelynä, jonka 1. vaiheessa pyydetään hankinnasta kiinnostuneita toimittajia laatimaan osallistumispyyntö. Hankintayksikkö arvioi osallistumispyynnöt ja valitsee kolme vertailussa eniten pisteitä saanutta toimittajaa hankinnan toiseen vaiheeseen. 2. vaiheessa hankintayksikkö pyytää kolmelta valituilta toimittajilta tarjouksia. Hankintayksikkö maksaa tarjouksen luonnossuunnittelusta kullekin toimittajalle palkkiota 3.000 € (alv 0%). Edellytyksenä 2. vaiheen tarjouspalkkion maksamiselle,on että toimittajan tarjous on tarjouspyynnön mukainen ja luonnossuunnitelma on laadittu ammattitaidolla. Toimittaja voi halutessaan antaa 2. vaiheessa useamman tarjouksen. 2. Vaiheen voittaja tekee rakennuslupakuvat tarjoamallaan hinnalla. Hankinta toteutetaan kansallisen kynnysarvon alittavana menettelynä. Ks kohta II.1.4) Lyhyt kuvaus *','Alajärven kaupunki','ANY',2,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-147361','[\"71000000\"]','[\"hankinnan\", \"vaiheessa\", \"hankintayksikkö\", \"paavolan\", \"koulun\", \"hankinta\", \"toteutetaan\", \"menettelynä\", \"tarjouksen\", \"vaiheen\", \"alajärven\", \"kaupunki\", \"kansallinen\", \"pienhankinta\", \"suunnittelu\", \"kohteena\", \"luonnossuunnittelu\", \"osoitteeseen\