INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (67,'2024-147096','HILMA','RFP','OPEN','Työterveyshuollon palvelut','Parkanon kaupungin (=tilaaja) tarjouspyyntö työterveyshuollon palveluista. Tilaaja hankkii tarjouspyynnöllä työterveyspalvelut itselleen. Parkanon kaupungilla työskentelee vakituisesti n. 165 htv ja tyypillisesti vuoden aikana n. 220 ihmistä. Tarjouskilpailun kohteena on työterveyshuollon palvelut tälle henkilökunnalle. Hankinnan perusteella tehtävän sopimuksen kesto on 4 vuotta: 1.1.2025-31.12.2028. Hankinta sisältää option jatkaa sopimusta 1+1 vuotta vuosille 2029 ja 2030. Tilaaja päättää optioiden käytöstä. Tilaaja ilmoittaa option käytöstä palvelutuottajalle viimeistään kaksitoista kuukautta ennen option käyttöönottoa, molempien optiovuosien osalta erikseen. Hankinnan arvo on optiot mukaan luettuna n. 900 000 euroa, alv 0%. Hankinnan arvo ylittää hankintalain (1397/2016) § 25 mukaisen sosiaali- ja terveyspalveluita koskevan kynnysarvon. Hankintaan sovelletaan hankintalakia. HUOM. Tarjouspyyntö julkaistu uudelleen 10.6.2024. Tarjouspyyntöön tarkennettu hinnoittelua ja palvelukuvausta verrattuna toukokuussa julkaistuun kilpailutukseen. Kts. lyhyt kuvaus.','Parkanon kaupunki','ANY',3,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2024-147096','[\"85147000\"]','[\"parkanon\", \"tilaaja\", \"työterveyshuollon\", \"hankinnan\", \"option\", \"palvelut\", \"tarjouspyyntö\", \"vuotta\", \"käytöstä\", \"arvo\", \"kaupunki\", \"kaupungin\", \"palveluista\", \"hankkii\", \"tarjouspyynnöllä\", \"työterveyspalvelut\", \"itselleen\", \"kaupungilla\", \"työskentelee\", \"vakituisesti\"]'