INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (72,'2023-126994','HILMA','OTHER','OPEN','Suomenlinnan lauttaliikenteen ja Kruunuvuorenrannan alusliikenteen operointi','Hankinta koostuu kahden eri reitin operoinnista: Reitti A: Suomenlinnan lauttaliikenteen operointi välillä Kauppatori - Suomenlinna Reitti B: Kruunuvuoren alusliikenteen operointi välillä Meritullintori - Kruunuvuorenranta Reitti B on lisäksi jaettu kahteen erilliseen osa-alueeseen: Reitti B1 Kruunuvuoren alusliikenteen kesäliikenteen operointi välillä Meritullintori - Kruunuvuorenranta Reitti B2 Kruunuvuoren alusliikenteen talviliikenteen operointi välillä Meritullintori - Kruunuvuorenranta Edellä olevan mukaisesti hankinta koostuu täten kolmesta (3) erillisestä osa-alueesta: Osa-alue 1: Suomenlinnan lauttaliikenteen operointi välillä Kauppatori - Suomenlinna (Reitti A) Osa-alue 2: Kruunuvuoren alusliikenteen kesäliikenteen operointi välillä Meritullintori - Kruunuvuorenranta (Reitti B1) Osa-alue 3: Kruunuvuoren alusliikenteen talviliikenteen operointi välillä Meritullintori - Kruunuvuorenranta (Reitti B2) Reittiä A operoidaan tällä hetkellä SLL:n omistamalla M/S Suomenlinna II:lla sekä kahdella SLL:n nykyisen alihankkijan aluksella. SLL omistaa lisäksi M/S Ehrensvärdin, joka liikennöi välillä Katajanokka - Suomenlinna. M/S Ehrensvärdille on keskitetty erityisesti ajoneuvoliikenne ja Suomenlinnan huoltoliikenne. Reitti B on uusi liikennöitävä reitti. Helsingin kaupungin hallitus päätti 27.6.2022 käynnistää ympärivuotisen HSL-lipuilla toimivavan lauttaliikenne Kruunuvuorenrantaan vuonna 2023. Liikennöinnin kysyntää ja tarvetta arvioidaan liikennöinnin aikana ja liikennöintiä jatketaan enintään Kruunusiltojen valmistumiseen asti. Suomenlinnan lauttaliikenteen operointi välillä Kauppatori - Suomenlinna (Reitti A) Hankinnan (osa-alue 1) kohteena on Suomenlinnan lauttaliikenteen operointi Kauppatorin ja Suomenlinnan välillä seuraavasti: - Talviliikennekausi (1.11 – 30.3) • maanantaista sunnuntaihin noin 7,5 ajotuntia/vrk - Kesäliikennekausi (1.4 – 31.10) • maanantaista perjantaihin yhdellä aluksella noin klo 6.00 – 2.30 • lauantaisin ja sunnuntaisin kahdella aluksella seuraavasti: a) alus 1 noin klo 6.00 – 2.30 b) alus 2 noin klo 11.00 – 18.00 Lisäksi alukset toimivat SLL:n omien alusten vara-aluksina. Hankinnan (osa-alue 1) alustavat sopimusehdot on kuvattu tarkemmin osallistumispyynnön liitteissä: - Liite A: Osa-alue 1, Sopimusluonnos - Liite A1: Osa-alue 1, Liikennöinti poikkeustilanteissa Operointiin liittyvät vaatimukset, liikennöintiaika ja sopimusehdot tulevat tarkentumaan hankintaprosessiin liittyvien neuvottelukierrosten aikana. Kruunuvuoren alusliikenteen kesäliikenteen operointi välillä Meritullintori - Kruunuvuorenranta (Reitti B1) Hankinnan (osa-alue 2) kohteena on Kruunuvuoren alusliikenteen kesäliikenteen operointi välillä Meritullintori - Kruunuvuorenranta seuraavasti: - Kesäliikennekausi (1.4 – 31.10) • maanantaista sunnuntaihin yhdellä aluksella noin klo 8.00 – 21.00 Tarjoaja huolehtii tarvittaessa varakalustosta reitille. Hankinnan (osa-alue 2) alustavat sopimusehdot on kuvattu tarkemmin osallistumispyynnön liitteessä: - Liite B, Osa-alue 2, Sopimusluonnos Operointiin liittyvät vaatimukset, liikennöintiaika ja sopimusehdot tulevat tarkentumaan hankintaprosessiin liittyvien neuvottelukierrosten aikana. Kruunuvuoren alusliikenteen talviliikenteen operointi välillä Meritullintori - Kruunuvuorenranta (Reitti B2) Hankinnan (osa-alue 3) kohteena on Kruunuvuoren alusliikenteen talviliikenteen operointi välillä Meritullintori - Kruunuvuorenranta seuraavasti: - Talviliikennekausi (1.11 – 31.3) • maanantaista perjantaihin yhdellä aluksella noin klo 8.00 – 21.00 • lauantai-sunnuntai yhdellä aluksella noin kello 9.00 – 17.00 Tarjoaja huolehtii tarvittaessa varakalustosta reitille. Hankinnan (osa-alue 3) alustavat sopimusehdot on kuvattu tarkemmin osallistumispyynnön liitteessä: - Liite C, Osa-alue 3, Sopimusluonnos Operointiin liittyvät vaatimukset, liikennöintiaika ja sopimusehdot tulevat tarkentumaan hankintaprosessiin liittyvien neuvottelukierrosten aikana.','Suomenlinnan Liikenne Oy','ANY',4,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2023-126994','[\"60600000\"]','[\"operointi\", \"välillä\", \"reitti\", \"alue\", \"alusliikenteen\", \"kruunuvuoren\", \"meritullintori\", \"kruunuvuorenranta\", \"suomenlinnan\", \"noin\", \"aluksella\", \"hankinnan\", \"sopimusehdot\", \"lauttaliikenteen\", \"suomenlinna\", \"kesäliikenteen\", \"talviliikenteen\", \"aikana\", \"seuraavasti\", \"maanantaista\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2023-126994\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-126994\", \"lots\": [{\"id\": \"Osa-alue 1\", \"titleEn\": null, \"titleFi\": \"Suomenlinnan lauttaliikenteen operointi välillä Kauppatori - Suomenlinna (Reitti A)\", \"titleSv\": null, \"cpvCodes\": \"60600000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": true, \"nutsCodes\": \"FI1B1\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": null, \"descriptionFi\": \"Suomenlinnan lauttaliikenteen operointi välillä Kauppatori - Suomenlinna (Reitti A) Hankinnan (osa-alue 1) kohteena on Suomenlinnan lauttaliikenteen operointi Kauppatorin ja Suomenlinnan välillä seuraavasti:  - Talviliikennekausi (1.11 – 30.3) • maanantaista sunnuntaihin noin 7,5 ajotuntia/vrk   - Kesäliikennekausi (1.4 – 31.10) • maanantaista perjantaihin yhdellä aluksella noin klo 6.00 – 2.30 • lauantaisin ja sunnuntaisin kahdella aluksella seuraavasti:  a) alus 1 noin klo 6.00 – 2.30  b) alus 2 noin klo 11