INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (75,'2025-020715','HILMA','RFP','OPEN','Kuumajuoma-automaatit palveluna','Kuumajuoma-automaatit palveluna Yleisradiolla (jäljempänä Yle) on tällä hetkellä lähes 70 kuumajuoma-automaattia sen eri toimipisteissä. Kuumajuoma-automaatteja käyttävät lähtökohtaisesti Ylen työntekijät ja vieraat. Tällä hetkellä täyspalveluautomaatteja on seuraavilla paikkunnilla: Helsinki (45 kpl), Tampere (7 kpl), Vaasa (3 kpl), Hämeenlinna, Jyväskylä, Kuopio, Lahti, Oulu, Pori, Joensuu, Turku ja Seinäjoki. Osittaispalveluna automaatteja on kuudella paikkakunnalla: Kajaani, Kemi, Kokkola, Kotka, Mikkeli ja Rovaniemi. Hankinnan kohteena ovat palveluna toimitettavat kuumajuoma-automaatit, niitä koskevat huolto-, korjaus- ja ylläpitopalvelut sekä juomien valmistuksessa ja palvelussa tarvittavat raaka-aineet ja tarvikkeet. Toimittaja vastaa laitteiden toiminnasta kokonaisuudessaan sisältäen muun muassa laitteiden toimintavarmuuden, raaka-aineiden ja muiden tuotteiden ja tarvikkeiden riittävyyden, automaatin siisteyden, huolto-, korjaus- sekä ylläpitopalvelut, laitteiden asennuksen ja käytön ohjeistuksen. Yle hankkii automaatteja sekä täyspalveluna että osittaispalveluna. Hankinnan kohde on kuvattu tarkemmin tarjouspyynnön liitteissä. Hankinnan tavoitteena on muodostaa sopimus yhden (1) toimittajan kanssa.,','Yleisradio Oy','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2025-020715','[\"55330000\", \"55511000\"]','[\"kuumajuoma\", \"automaatit\", \"palveluna\", \"automaatteja\", \"hankinnan\", \"laitteiden\", \"tällä\", \"hetkellä\", \"osittaispalveluna\", \"huolto\", \"korjaus\", \"ylläpitopalvelut\", \"raaka\", \"yleisradio\", \"yleisradiolla\", \"jäljempänä\", \"lähes\", \"automaattia\", \"toimipisteissä\", \"käyttävät\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/yleisradiooy?id=544274&tpk=7d51593c-dd38-43cb-8f35-d8810a3b46fc\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2025-020715\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-20715\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Kuumajuoma-automaatit palveluna\", \"titleSv\": \"\", \"cpvCodes\": \"55330000 55511000\", \"currency\": null, \"deadline\": \"2025-03-26T10:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"Yleisradiolla (jäljempänä Yle) on tällä hetkellä lähes 70 kuumajuoma-automaattia sen eri toimipisteissä. Kuumajuoma-automaatteja käyttävät lähtökohtaisesti Ylen työntekijät ja vieraat. \\n\\nTällä hetkellä täyspalveluautomaatteja on seuraavilla paikkunnilla: Helsinki (45 kpl), Tampere (7 kpl), Vaasa (3 kpl), Hämeenlinna, Jyväskylä, Kuopio, Lahti, Oulu, Pori, Joensuu, Turku ja Seinäjoki. Osittaispalveluna automaatteja on kuudella paikkakunnalla: Kajaani, Kemi, Kokkola, Kotka, Mikkeli ja Rovaniemi. \\n\\nHankinnan kohteena ovat palveluna toimitettavat kuumajuoma-automaatit, niitä koskevat huolto-, korjaus- ja ylläpitopalvelut sekä juomien valmistuksessa ja palvelussa tarvittavat raaka-aineet ja tarvikkeet. Toimittaja vastaa laitteiden toiminnasta kokonaisuudessaan sisältäen muun muassa laitteiden toimintavarmuuden, raaka-aineiden ja muiden tuotteiden ja tarvikkeiden riittävyyden, automaatin siisteyden, huolto-, korjaus- sekä ylläpitopalvelut, laitteiden asennuksen ja käytön ohjeistuksen. Yle hankkii automaatteja sekä täyspalveluna että osittaispalveluna. \\n\\nHankinnan kohde on kuvattu tarkemmin tarjouspyynnön liitteissä.\\n\\nHankinnan tavoitteena on mu