INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (76,'2023-127288','HILMA','OTHER','OPEN','LYS Laakson yhteissairaalan allianssi; Infravalvoja','Hankinnan kohteena on infravalvoja ja hänen varahenkilönsä Laakson yhteissairaalan allianssiin. Hankkeessa on tällä hetkellä käynnissä infra- ja aluetöiden, päärakennuksen sekä itäisen uudisrakennuksen osalta kehitysvaiheet . Infravalvojan tehtävä on auttaa LYS- allianssia toteuttamaan infrarakentamista siten, että korjaavia toimenpiteitä rakennusaikana, takuuaikana ja sen jälkeen tulisi mahdollisimman vähän eli pääpaino on virheiden ja ongelmien ennalta ehkäisemisessä. Lisäksi tavoitteena on laadunhallinnan prosessin arviointi ja kehittäminen yhdessä allianssin osapuolten kesken. Kyseessä on hankintalain mukainen EU-kynnysarvon ylittävä palveluhankinta ja hankinta toteutetaan käyttäen neuvottelumenettelyä. Hankinta poikkeaa sisällöltään tavanomaisesta infrarakentamisen valvojan tai rakennuttajankonsultin roolista, minkä vuoksi hankinnan aikana on pystyttävä varmistumaan nimettyjen avainhenkilöiden ammatillisesta osaamisesta ja henkilökohtaisesta soveltuvuudesta allianssissa toimivan infravalvojan tehtävään neuvottelumenettelyn aikana. Kokonaistaloudellisen edullisuuden perusteena on paras hinta-laatusuhde.','Kiinteistöosakeyhtiö Laakson yhteissairaala','ANY',2,14,NULL,NULL,1200000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2023-127288','[\"71000000\", \"71520000\"]','[\"laakson\", \"yhteissairaalan\", \"infravalvoja\", \"hankinnan\", \"infravalvojan\", \"hankinta\", \"aikana\", \"kiinteistöosakeyhtiö\", \"yhteissairaala\", \"allianssi\", \"kohteena\", \"hänen\", \"varahenkilönsä\", \"allianssiin\", \"hankkeessa\", \"tällä\", \"hetkellä\", \"käynnissä\", \"infra\", \"aluetöiden\"]',NULL,NULL,'[{\"url\": \"https://bem.buildercom.net/html/rfq2registration/index?rfqId=7034&guid=17ac11b4-08b2-4c05-9d57-e80e77f8fdf1\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2023-127288\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-127288\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"71520000\", \"currency\": \"EUR\", \"deadline\": \"2023-05-30T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1B\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"Kyseessä on hankintalain mukainen EU-kynnysarvon ylittävä palveluhankinta ja hankinta toteutetaan käyttäen neuvottelumenettelyä. Hankinta poikkeaa sisällöltään tavanomaisesta infrarakentamisen valvojan tai rakennuttajankonsultin roolista, minkä vuoksi hankinnan aikana on pystyttävä varmistumaan nimettyjen avainhenkilöiden ammatillisesta osaamisesta ja henkilökohtaisesta soveltuvuudesta allianssissa toimivan infravalvojan tehtävään neuvottelumenettelyn aikana.  Kokonaistaloudellisen edullisuuden perusteena on paras hinta-laatusuhde.\", \"descriptionSv\": null, \"procedureType\": \"neg-w-call\", \"estimatedValue\": 0.0, \"expirationDate\": \"2023-05-30T09:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": null, \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": 4, \"winnerOrganisations\": \"Sitowise Oy (2335445-0)\", \"innovationConsidered\": true, \"lotResultTotalAmount\": 0.0, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFram