INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (79,'2023-127047','HILMA','RFI','OPEN','Kutsu markkinavuoropuhelutilaisuuteen: Pakkaus- ja biojätteiden erilliskeräys','Kuhmoisten kunnan tekninen toimi kutsuu kuljetusliikkeitä osallistumaan markkinavuoropuhelutilaisuuteen osana kilpailuttamiseen valmistautumista. Markkinavuoropuhelutilaisuus koskee asumisessa syntyvän jätteen (pakkaus- ja biojäte) kiinteistökohtaista erilliskeräystä ja kuljetusta Kuhmoisten kunnan alueella sijaitsevilla vähintään 5 huoneiston kiinteistöillä. Kuhmoisten kunta aloittaa erilliskeräyksen kyseisillä kiinteistöillä vuoden 2023 aikana. Markkinavuoropuhelu koskee seuraavia vuonna 2023 kilpailutettavia hankintoja: -Pakkausjätteen tyhjennykset -Biojätteen tyhjennykset Ennen kilpailutuksen ja varsinaisen hankintamenettelyn aloittamista haluamme kuulla mahdollisia tarjoajia markkinavuoropuhelussa. Tilaisuudessa esittelemme alustavia ajatuksiamme hankintoihin liittyen ja aikataulusuunnitelman. Toivomme kuljetusliikkeiden näkemyksiä tuleviin kilpailutuksiin markkinoiden kartoittamiseksi ja hyvien käytänteiden löytämiseksi. Markkinavuoropuhelu pidetään tiistaina 23.5.2023 klo 16.15–17.30 Kuhmoisten kunnanvirastolla osoitteessa Toritie 34 A, 17800 Kuhmoinen. Voit osallistua tilaisuuteen myös etänä teams-linkin välityksellä, jonka toimitamme ilmoittautumisen yhteydessä. Osallistuville lähetetään tilaisuutta edeltävällä viikolla nähtäväksi ennakkomateriaalia. Ilmoittautuminen 18.5.2023 mennessä tekniselle johtajalle sähköpostitse osoitteeseen: hemmo.saartoala@kuhmoinen.fi. Voitte lähettää myös mahdollisia ennakkokysymyksiä. Markkinavuoropuhelussa saatuja tietoja käytetään kilpailutusten valmistelussa. Kilpailutusten aikatauluista ja menettelyistä päätetään vuoropuhelutilaisuuden jälkeen. Kuhmoisten kunnan tekninen toimi kutsuu kuljetusliikkeitä osallistumaan markkinavuoropuhelutilaisuuteen osana kilpailuttamiseen valmistautumista. Markkinavuoropuhelutilaisuus koskee asumisessa syntyvän jätteen (pakkaus- ja biojäte) kiinteistökohtaista erilliskeräystä ja kuljetusta Kuhmoisten kunnan alueella sijaitsevilla vähintään 5 huoneiston kiinteistöillä. Kuhmoisten kunta aloittaa erilliskeräyksen kyseisillä kiinteistöillä vuoden 2023 aikana. Markkinavuoropuhelu koskee seuraavia vuonna 2023 kilpailutettavia hankintoja: -Pakkausjätteen tyhjennykset -Biojätteen tyhjennykset Ennen kilpailutuksen ja varsinaisen hankintamenettelyn aloittamista haluamme kuulla mahdollisia tarjoajia markkinavuoropuhelussa. Tilaisuudessa esittelemme alustavia ajatuksiamme hankintoihin liittyen ja aikataulusuunnitelman. Toivomme kuljetusliikkeiden näkemyksiä tuleviin kilpailutuksiin markkinoiden kartoittamiseksi ja hyvien käytänteiden löytämiseksi. Markkinavuoropuhelu pidetään tiistaina 23.5.2023 klo 16.15–17.30 Kuhmoisten kunnanvirastolla osoitteessa Toritie 34 A, 17800 Kuhmoinen. Voit osallistua tilaisuuteen myös etänä teams-linkin välityksellä, jonka toimitamme ilmoittautumisen yhteydessä. Osallistuville lähetetään tilaisuutta edeltävällä viikolla nähtäväksi ennakkomateriaalia. Ilmoittautuminen 18.5.2023 mennessä tekniselle johtajalle sähköpostitse osoitteeseen: hemmo.saartoala@kuhmoinen.fi. Voitte lähettää myös mahdollisia ennakkokysymyksiä. Markkinavuoropuhelussa saatuja tietoja käytetään kilpailutusten valmistelussa. Kilpailutusten aikatauluista ja menettelyistä päätetään vuoropuhelutilaisuuden jälkeen.','Kuhmoisten kunta','ANY',2,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2023-127047','[\"90511000\"]','[\"kuhmoisten\", \"kunnan\", \"koskee\", \"kiinteistöillä\", \"kunta\", \"markkinavuoropuhelu\", \"tyhjennykset\"