INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (82,'2025-020589','HILMA','OTHER','OPEN','Ammatillisen perhehoitopalvelun suorahankinta lastensuojelun avohuoltoon','Ammatillisen perhehoitopalvelun suorahankinta lastensuojelun avohuoltoon Etelä-Savon hyvinvointialue Eloisa tekee suorahankinnan ammatillisesta perhehoitopalvelusta kahdelle (2) lastensuojelun avohuollon asiakkaalle 11.12.2024 alkaen. Hankinnassa on optio lasten täysi-ikäisyyteen saakka. Ammatillinen perhehoito on perhehoitoa, jota annetaan yksityisistä sosiaalipalveluista annetun lain (922/2011) 7 §:ssä tarkoitetun luvan perusteella ammatillisessa perhekodissa (Perhehoitolaki 263/2015, 4 §). Luvanvaraisella ammatillisella perhehoidolla tarkoitetaan sijaishuollon yksikköä, jossa sijoitettujen lasten kanssa tosiasiallisesti asuu perhekotivanhempi tai perhekotivanhemmat ja jolla on voimassa oleva aluehallintoviraston myöntämä lupa antaa lastensuojelun ympärivuorokautista ammatillista perhehoitoa. Tarjous on pyydetty sähköpostitse Perhekoti Talisman Oy:ltä. Hankinnan ennakoitu kokonaisarvo 2 752 025,00 euroa (alv 0 %) ylittää EU-kynnysarvon. Ennakoitu kokonaisarvon on laskettu sopimuskauden ajalle 11.12.2024-25.6.2040 sisältäen option lasten täysi-ikäisyyteen saakka. Suorahankinnan perusteena on Laki julkisista hankinnoista ja käyttöoikeussopimuksista (1397/2016) 12 luku 110 § Suorahankinta erityistilanteissa; hankintayksikkö voi tehdä suorahankinnan yksittäisissä tapauksissa hankintalain 12 luvun mukaisissa sosiaali- ja terveyspalveluhankinnoissa, jos tarjouskilpailun järjestäminen tai palvelun tarjoajan vaihtaminen olisi ilmeisen kohtuutonta tai erityisen epätarkoituksenmukaista asiakkaan kannalta merkittävän hoito- tai asiakassuhteen turvaamiseksi.,','Etelä-Savon hyvinvointialue','ANY',3,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2025-020589','[\"85300000\"]','[\"lastensuojelun\", \"suorahankinta\", \"suorahankinnan\", \"lasten\", \"ammatillisen\", \"perhehoitopalvelun\", \"avohuoltoon\", \"etelä\", \"savon\", \"hyvinvointialue\", \"täysi\", \"ikäisyyteen\", \"saakka\", \"perhehoitoa\", \"ennakoitu\", \"eloisa\", \"tekee\", \"ammatillisesta\", \"perhehoitopalvelusta\", \"kahdelle\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2025-020589\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-20589\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Ammatillisen perhehoitopalvelun suorahankinta lastensuojelun avohuoltoon\", \"titleSv\": \"\", \"cpvCodes\": \"85300000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": false, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Etelä-Savon hyvinvointialue Eloisa tekee suorahankinnan ammatillisesta perhehoitopalvelusta kahdelle (2) lastensuojelun avohuollon asiakkaalle\\n11.12.2024 alkaen. Hankinnassa on optio lasten täysi-ikäisyyteen saakka.\\n\\nAmmatillinen perhehoito on perhehoitoa, jota annetaan yksityisistä sosiaalipalveluista annetun lain (922/2011) 7 §:ssä tarkoitetun luvan perusteella\\nammatillisessa perhekodissa (Perhehoitolaki 263/2015, 4 §). Luvanvaraisella ammatillisella perhehoidolla tarkoitetaan sijaishuollon yksikköä, jossa\\nsijoitettujen lasten kanssa tosiasiallisesti asuu perhekotivanhempi tai perhekotivanhemmat ja jolla on voimassa oleva aluehallintoviraston myöntämä\\nlupa antaa lastensuojelun ympärivuorokautista ammatillista perhehoitoa.\\n\\nTarjous on pyydetty sähköpostitse Perhekoti Talisman Oy:ltä.\\n\\nHankinnan ennakoitu kokonaisarvo 2 752 025,00 euroa (alv 0 %) ylittää EU-kynn