INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (86,'2023-126962','HILMA','OTHER','OPEN','Vaarallisten jätteiden kuljetus ja käsittely','Porin kaupungin Tekninen toimiala / Jätehuoltoyksikkö pyysi tarjousta vaarallisten jätteiden huoltopalveluista ajalle 1.4.2023 - 31.3.2025 + mahdolliset optiovuodet 1 + 1. Vaarallisia jätteitä otetaan vastaan Porissa Hangassuon jätekeskuksessa ja kierrätyskeskuksessa sekä yhteistyökuntien vastaanottopisteillä Harjavallassa, Merikarvialla ja Ulvilassa. Vaarallisten jätteiden säännölliset mobiilikeräykset Porin Noormarkussa ja Laviassa, Nakkilassa, Kokemäellä, Pomarkussa ja Siikaisissa. Kotitalouksien lääkkeitä vastaanotetaan 22:ssa apteekissa Porissa (15), Kokemäellä (2) sekä Siikaisissa (1), Merikarvialla (1), Pomarkussa (1), Nakkilassa (1) ja Ulvilassa (1). Apteekkeihin kertyneet lääkejätteet noudetaan kuukausittain/tarpeen mukaan apteekista riippuen. Tarjouspyyntö koskee edellä mainituissa kohteissa vastaanotettujen/kerättyjen vaarallisten jätteiden kuljetusta ja käsittelyä luvan omaavassa laitoksessa sekä keräysastioiden vuokraamista/toimittamista. Tilaajalla on oikeus lisätä tai vähentää keräyksen ja kuljetusten piiriin kuuluvien pisteiden määrää. Tarjouspyynnössä esitetyt yksikkömäärät kuvaavat tilaajan tällä hetkellä tiedossa olevaa tilannetta, eivätkä ne sido tilaajaa. Myös muuttuva lainsäädäntö tai jätehuolto- tai ympäristönsuojeluviranomaisen tekemät päätökset voivat muuttaa nyt tarjouspyynnössä esitettyä käytäntöä. Tarjouspyyntö sisältää seuraavat osat: - Jätteiden käsittelymaksut. Vastaanotettujen vaarallisten jätteiden käsittely luvan omaavassa laitoksessa. - Vaarallisten jätteiden noudot vastaanottopaikoista ja keräysastioiden vuokraus / toimittaminen. - Vaarallisten jätteiden mobiilikeräykset. - Vaarallisten jätteiden keräystempaukset. - Apteekkinoudot. (Lääkejätteiden noutaminen ja käsittely luvan omaavassa laitoksessa, sekä keräysastioiden toimittaminen.) Hankinnasta lisätietoa Hankinnan taustaa -kohdassa. Hankintayksikön toiminta siirtyy uudelle perustettavalle jätehuoltoyhtiölle 01.04.2023 alkaen. Tämän hankinnan sopimus tullaan tekemään uuden jätehuoltoyhtiön kanssa/siirtämään uudelle jätehuoltoyhtiölle sellaisenaan. Katso kohta II.1.4) Lyhyt kuvaus.','Porin kaupunki / Tekninen toimiala / Jätehuoltoyksikkö','ANY',5,9,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2023-126962','[\"90510000\", \"90520000\"]','[\"jätteiden\", \"vaarallisten\", \"porin\", \"käsittely\", \"tekninen\", \"toimiala\", \"jätehuoltoyksikkö\", \"luvan\", \"omaavassa\", \"laitoksessa\", \"keräysastioiden\", \"porissa\", \"merikarvialla\", \"ulvilassa\", \"mobiilikeräykset\", \"nakkilassa\", \"kokemäellä\", \"pomarkussa\", \"siikaisissa\", \"tarjouspyyntö\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2023-126962\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-126962\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"90520000 90510000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": false, \"nutsCodes\": \"FI196\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"Katso kohta II.1.4) Lyhyt kuvaus.\", \"descriptionSv\": null, \"procedureType\": \"open\", \"estimatedValue\": 0.0, \"expirationDate\": \"2023-10-28T04:00:53.535Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": null, \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": 4, \"winnerOrganisations\": \"Veikko Lehti Oy (1460563-3)\", \"innovationConsidered\": true, \"lotResultTotalAmount\": 728000.0, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": \"EUR\", \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"300\", \"isPlan\": false, \"planId\": 0, \"titleEn\": null, \"titleFi\": \"Vaarallisten jätteiden kuljetus ja käsittely\", \"titleSv\": null, \"cpvCodes\": \"90510000 90520000\", \"currency\": null, \"deadline\": null, \"eFormsId\": null, \"isEForms\": false, \"mainType\": \"ContractAwardNotices\", \"noticeId\": 126962, \"lowCarbon\": false, \"nutsCodes\": \"FI196\", \"titleOther\": null, \"isCancelled\": false, \"procedureId\": 0, \"biodiversity\": false, \"dateModified\": \"2023-04-28T07:00:53.543Z\", \"fullEFormsId\": null, \"noticeNumber\": \"2023-126962\", \"@search.score\": 1.0, \"codeOfConduct\": false, \"datePublished\": \"2023-04-28T07:00:53.535Z\", \"descriptionEn\": null, \"descriptionFi\": \"Porin kaupungin Tekninen toimiala / Jätehuoltoyksikkö pyysi tarjousta vaarallisten jätteiden huoltopalveluista ajalle 1.4.2023 - 31.3.2025 + mahdolliset optiovuodet 1 + 1.  Vaarallisia jätteitä otetaan vastaan Porissa Hangassuon jätekeskuksessa ja kierrätyskeskuksessa sekä yhteistyökuntien vastaanottopisteillä Harjavallassa, Merikarvialla ja Ulvilassa. Vaarallisten jätteiden säännölliset mobiilikeräykset Porin Noormarkussa ja Laviassa, Nakkilassa, Kokemäellä, Pomarkussa ja Siikaisissa. Kotitalouksien lääkkeitä vastaanotetaan 22:ssa apteekissa Porissa (15), Kokemäellä (2) sekä Siikaisissa (1), Merikarvialla (1), Pomarkussa (1), Nakkilassa (1) ja Ulvilassa (1). Apteekkeihin kertyneet lääkejätteet noudetaan kuukausittain/tarpeen mukaan apteekista riippuen.  Tarjouspyyntö koskee edellä mainituissa kohteissa vastaanotettujen/kerättyjen vaarallisten jätteiden kuljetusta ja käsittelyä luvan omaavassa laitoksessa sekä keräysastioiden vuokraamista/toimittamista. Tilaajalla on oikeus lisätä tai vähentää keräyksen ja kuljetusten piiriin kuuluvien pisteiden määrää. Tarjouspyynnössä esitetyt yksikkömäärät kuvaavat tilaajan tällä hetkellä tiedossa olevaa tilannetta, eivätkä ne sido tilaajaa. Myös muuttuva lainsäädäntö tai jätehuolto- tai ympäristönsuojeluviranomaisen tekemät päätökset voivat muuttaa nyt tarjouspyynnössä esitettyä käytäntöä.   Tarjouspyyntö sisältää seuraavat osat: - Jätteiden käsittelymaksut. Vastaanotettujen vaarallisten jätteiden käsittely luvan omaavassa laitoksessa. - Vaarallisten jätteiden noudot vastaanottopaikoista ja keräysastioiden vuokraus / toimittaminen. - Vaarallisten jätteiden mobiilikeräykset. - Vaarallisten jätteiden keräystempaukset. - Apteekkinoudot. (Lääkejätteiden noutaminen ja käsittely luvan omaavassa laitoksessa, sekä keräysastioiden toimittaminen.)  Hankinnasta lisätietoa Hankinnan taustaa -kohdassa.  Hankintayksikön toiminta siirtyy uudelle perustettavalle jätehuoltoyhtiölle 01.04.2023 alkaen. Tämän hankinnan sopimus tullaan tekemään uuden jätehuoltoyhtiön kanssa/siirtämään uudelle jätehuoltoyhtiölle sellaisenaan.  Katso kohta II.1.4) Lyhyt kuvaus.\", \"descriptionSv\": null, \"isCorrigendum\": false, \"linkedNotices\": null, \"procedureType\": \"open\", \"sendingSystem\": \"Cloudia Kilpailutus\", \"estimatedValue\": 0.0, \"expirationDa