INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (89,'2025-020736','HILMA','OTHER','OPEN','Elintarvikkeet ja non-food -tuotteet 2025-2030','Elintarvikkeet ja non-food -tuotteet 2025-2030 Elintarvikkeet ja non-food -tuotteet 2025–2030 -puitejärjestely on tarkoitettu ammattikeittiössä käytettäville elintarvikkeille, non-food tuotteille ja jälleenmyytäville kioskituotteille. Sekä edellä mainittuja toimintoja tukeville puhtaanapidon tarvikkeille ja kemikaaleille. Lisäksi hankinnan kohteena ovat tuotteiden tilaamiseen ja käyttämiseen liittyvät palvelut. Toimipaikat jakautuvat maanlaajuisesti. Tuotteita käytetään esimerkiksi puolustusvoimien alueilla sijaitsevissa ravintoloissa, vankiloiden ravintoloissa, vankiloiden kanttiineissa sekä projektitoimituksina vaihtelevissa osoitteissa. Tarjoajan on pystyttävä tarjoamaan kaikki tarjouspyynnön mukaiset tuotteet, palvelut ja täyttämään muut vaatimukset. Edellytämme toimittajalta joustavuutta, ehdotonta luotettavuutta, toimitusvarmuutta ja jatkuvuussuunnittelua sekä jatkuvuussuunnitelman harjoittelua. Leijona Catering odottaa pitkää, kehittävää ja molempia osapuolia hyödyttävää yhteistyötä sopimuskauden aikana. Odotamme toimittajalta aktiivista otetta sopimuskaudella tilaus-toimitusketjun prosessien ja ketjumaisen toiminnan valikoimanhallinnan kehittämiseksi (mm. prosessien automatisointi, järjestelmäintegraatioiden kehittäminen) sekä kustannustehokkuuden parantamiseksi ja jatkuvuuden turvaamiseksi yhteistyötä Leijona Cateringin kanssa. Odotamme toimittajalta myös pitkäjänteistä yhteistyötä elintarvikeketjun työhyvinvoinnin ja turvallisuuden parantamiseksi, ja ympäristövaikutusten vähentämiseksi ja tuotantoeläinten hyvinvoinnin turvaamiseksi. Tarjouspyynnössä esitetyt hankintamäärät ovat arvioita eikä mikään sopimus muodosta hankintayksikölle määräostovelvoitetta. Hankinnan kohteen kuvaus, vaatimukset ja muut olennaiset asiat on esitetty tarkemmin tarjouspyynnön liitteissä. Tarjouspyynnön liitteenä on myös aiemmin keskeytetyn tarjouskilpailun aikana vastaanotetut lisätietokysymykset ja vastaukset niihin. Liitteen tarkoitus on tarjota lisätietoa toimittajille.,','Leijona Catering Oy','ANY',9,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2025-020736','[\"15000000\"]','[\"food\", \"tuotteet\", \"leijona\", \"elintarvikkeet\", \"tarjouspyynnön\", \"toimittajalta\", \"catering\", \"yhteistyötä\", \"hankinnan\", \"ovat\", \"palvelut\", \"ravintoloissa\", \"vankiloiden\", \"muut\", \"vaatimukset\", \"aikana\", \"odotamme\", \"prosessien\", \"parantamiseksi\", \"turvaamiseksi\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2025-020736\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-20736\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Elintarvikkeet ja non-food -tuotteet 2025-2030\", \"titleSv\": \"\", \"cpvCodes\": \"15000000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": false, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"Elintarvikkeet ja non-food -tuotteet 2025–2030 -puitejärjestely on tarkoitettu ammattikeittiössä käytettäville elintarvikkeille, non-food tuotteille ja jälleenmyytäville kioskituotteille. Sekä edellä mainittuja toimintoja tukeville puhtaanapidon tarvikkeille ja kemikaaleille. \\n\\nLisäksi hankinnan kohteena ovat tuotteiden tilaamiseen ja käyttämiseen liittyvät palvelut. \\n\\nToimipaikat jakautuvat maanlaajuisesti. Tuotteita käytetään esimerkiksi puolustusvoimien alueilla sijaitsevissa ravintoloissa, vankiloiden ravintoloissa, vankiloiden kanttiineissa sekä projektitoimituksina vaihtelevissa osoitteissa.\\n\\nTarjoajan on pystyttävä tarjoamaan kaikki tarjouspyynnön mukaiset tuotteet, palvelut ja täyttämään muut vaatimukset. Edellytämme toimittajalta joustavuutta, ehdotonta luotettavuutta, toimitusvarmuutta ja jatkuvuussuunnittelua sekä jatkuvuussuunnitelman harjoittelua. \\n\\nLeijona Catering odottaa pitkää, kehittävää ja molempia osapuolia hyödyttävää yhteistyötä sopimuskauden aikana. Odotamme toimittajalta aktiivista otetta sopimuskaudella tilaus-toimitusketjun prosessien ja ketjumaisen toiminnan valikoimanhallinnan kehittämiseksi (mm. prosessien automatisointi, järjestelmäintegraatioiden kehittäminen) sekä kustannustehokkuuden parantamiseksi ja jatkuvuuden turvaamiseksi yhteistyötä Leijona Cateringin kanssa. Odotamme toimittajalta myös pitkäjänteistä yhteistyötä elintarvikeketjun työhyvinvoinnin ja turvallisuuden parantamiseksi, ja ympäristövaikutusten vähentämiseksi ja tuotantoeläinten hyvinvoinnin turvaamiseksi.\\n\\nTarjouspyynnössä esitetyt hankintamäärät ovat arvioita eikä mikään sopimus muodosta hankintayksikölle määräostovelvoitetta. \\n\\nHankinnan kohteen kuvaus, vaatimukset ja muut olennaiset asiat on esitetty tarkemmin tarjouspyynnön liitteissä. \\n\\nTarjouspyynnön liitteenä on myös aiemmin keskeytetyn tarjouskilpailun aikana vastaanotetut lisätietokysymykset ja vastaukset niihin. Liitteen tarkoitus on tarjota lisätietoa toimittajille.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2025-08-20T08:05:04.714Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"Meira Nova Oy (0697627-4)\", \"innovationConsidered\": false, \"lotResultTotalAmount\": 150000000.0, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\