INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (91,'2023-126579','HILMA','RFP','OPEN','Pienhankintailmoitus. Automaattikirjakaapit : Kirjastopalvelujen saavutettavuuden parantamiseen ja kirjastoaineistojen välittämiseen liittyvän automaattilaitteiston hankinta. Hakeutuvat kirjastopalvelut. - Ruskon kunta, Varsinais-Suomi','Ruskon kunnankirjasto hankkii kirjaston ulkopuolelle julkisiin tiloihin sijoitettavia (kauppa, koulu) automaattikirjakaappeja 1-2 kappaletta. Kirjakaapista tms. asiakas voi lainata kirjastokortillaan ja henkilökohtaisen tunnusluvun avulla laitteen sisällä olevaa aineistoa ja kirjaston niin asettaessa myös palauttaa aineistoja ja noutaa varauksia. Asiakas voi tutustua laitteessa tarjolla olevaan valikoimaan paikan päällä ja tehdä lainauspäätöksen sen perusteella. Asiakas näkee laitteessa olevat fyysiset kappaleet. Kappaleita ei ole mahdollista ottaa laitteesta ilman, että ne lainautuvat asiakkaalle. Tunnistetekniikana on rfid. Edellytetään, että Vaski-kirjastoissa käytössä oleva tekniikka on sellaisenaan hyödynnettävissä ilman erillistyötä (esim. tietomallien ja taajuksien sekä mahdollisesti muun asiaan liittyvän signaalitekniikan osin). Koska kirjakaappi on reaaliaikaisessa yhteydessä Vaski-kirjastokimpan kirjastotietokantaan ja asiakasrekisteriin, voidaan määritellä asetus, minkä Vaski-kirjaston aineistoja kaapista välitetään sekä tarkistaa, onko asiakkaalla lainausoikeus. Laitteessa voi olla myös muita ominaisuuksia (näytöllä) kuten aineistosuosittelu, varatuimmat / suosituimmat, verkkokirjaston rajattu selaus, aineiston varaaminen, asiakaspalautteen antaminen, yhteys kirjaston asiakaspalveluun. Hankintaa suunnitellaan 1-2 laitteelle. Hankinta on pienhankinta. Tarjouksia pyydetään Hilma-hankintojen kautta ja niistä arvioitavaksi otetaan markkinavuoropuheluun osallistuneiden tarjouksia. Tarjouksia arvioitaessa painotetaan kokonaistaloudellista edullisuutta, tuotteen käytettävyyttä ja tarjoajan kokemusta kotimaisesta palveluympäristöstä. Hankinta on tarkoitus tehdä toukokuun 2023 aikana ja palvelun käyttöönotto sen jälkeen mahdollisimman pian, kuitenkin viimeistään elo-syyskuussa 2023. Ruskon kunnankirjasto hankkii kirjaston ulkopuolelle julkisiin tiloihin sijoitettavia (kauppa, koulu) automaattikirjakaappeja 1-2 kappaletta. Kirjakaapista tms. asiakas voi lainata kirjastokortillaan ja henkilökohtaisen tunnusluvun avulla laitteen sisällä olevaa aineistoa ja kirjaston niin asettaessa myös palauttaa aineistoja ja noutaa varauksia. Asiakas voi tutustua laitteessa tarjolla olevaan valikoimaan paikan päällä ja tehdä lainauspäätöksen sen perusteella. Asiakas näkee laitteessa olevat fyysiset kappaleet. Kappaleita ei ole mahdollista ottaa laitteesta ilman, että ne lainautuvat asiakkaalle. Tunnistetekniikana on rfid. Koska kirjakaappi on reaaliaikaisessa yhteydessä Vaski-kirjastokimpan kirjastotietokantaan ja asiakasrekisteriin, voidaan määritellä asetus, minkä Vaski-kirjaston aineistoja kaapista välitetään sekä tarkistaa, onko asiakkaalla lainausoikeus. Laitteessa voi olla myös muita ominaisuuksia (näytöllä) kuten aineistosuosittelu, varatuimmat / suosituimmat, verkkokirjaston rajattu selaus, aineiston varaaminen, asiakaspalautteen antaminen, yhteys kirjaston asiakaspalveluun. Hankintaa suunnitellaan 1-2 laitteelle. Hankinta on pienhankinta. Tarjouksia pyydetään Hilma-hankintojen kautta ja niistä arvioitavaksi otetaan markkinavuoropuheluun osallistuneiden tarjouksia. Tarjouksia arvioitaessa painotetaan kokonaistaloudellista edullisuutta, tuotteen käytettävyyttä ja tarjoajan kokemusta kotimaisesta palveluympäristöstä. Hankinta on tarkoitus tehdä toukokuun 2023 aikana ja palvelun käyttöönotto sen jälkeen mahdollisimman pian, kuitenkin viimeistään elo-syyskuussa 2023. Hankinta on pienhankinta','Ruskon kunta','ANY',1,14,NULL,NULL,30000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2023-126579','[\"39155100\"]','[\"kirjaston\", \"hankinta\", \"asiakas\", \"laitteessa\", \"tarjouksia\", \"ruskon\", \"vaski\", \"aineistoja\", \"tehdä\", \"kunta\", \"ilman\", \"pienhankinta\", \"liittyvän\", \"kunnankirjasto\", \"hankkii\", \"ulkopuolelle\", \"julkisiin\", \"tiloihin\", \"sijoitettavia\", \"kauppa\"]',NULL,NULL,'[{\"url\": \"https://hankintailmoitukset.fi/fi/public/procurement/84334/notice/126579\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2023-126579\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-126579\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"39155100\", \"currency\": \"EUR\", \"deadline\": \"2023-05-15T07:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI19\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"Ruskon kunnankirjasto hankkii kirjaston ulkopuolelle julkisiin tiloihin sijoitettavia (kauppa, koulu) automaattikirjakaappeja 1-2 kappaletta. Kirjakaapista tms. asiakas voi lainata kirjastokortillaan ja henkilökohtaisen tunnusluvun avulla laitteen sisällä olevaa aineistoa ja kirjaston niin asettaessa myös palauttaa aineistoja ja noutaa varauksia.  Asiakas voi tutustua laitteessa tarjolla olevaan valikoimaan paikan päällä ja tehdä lainauspäätöksen sen perusteella.  Asiakas näkee laitteessa olevat fyysiset kappaleet. Kappaleita ei ole mahdollista ottaa laitteesta ilman, että ne lainautuvat asiakkaalle. Tunnistetekniikana on rfid. Koska kirjakaappi on reaaliaikaisessa yhteydessä Vaski-kirjastokimpan kirjastotietokantaan ja asiakasrekisteriin, voidaan määritellä asetus, minkä Vaski-kirjaston aineistoja kaapista välitetään sekä tarkista