INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (99,'2023-126865','HILMA','RFP','OPEN','VTS-kodit pienkorjaussopimus','VTS-kodit kilpailuttaa pienkorjaussopimuksensa. Pienkorjaussopimuksen kohteena ovat lyhytkestoiset rakennustekniset pienkorjaukset, niiden laadukas ja asukaslähtöinen toteuttaminen työtehtävälle asetetussa vasteajassa VTS-kotien asunnoissa, yleisissä tiloissa ja piha-alueilla. Pienkorjauksia toteuttavat nimetyt kokoaikaisesti tätä sopimusta toteuttavat vastuuhenkilöt eli nk. aluekorjaajat, joilla on omat vastuukiinteistönsä. Sopimusta koskevat tarkemmat tiedot on esitetty hankinta-asiakirjoissa.','Tampereen Vuokratalosäätiö sr','ANY',2,3,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2023-126865','[\"70000000\"]','[\"kodit\", \"toteuttavat\", \"sopimusta\", \"tampereen\", \"vuokratalosäätiö\", \"pienkorjaussopimus\", \"kilpailuttaa\", \"pienkorjaussopimuksensa\", \"pienkorjaussopimuksen\", \"kohteena\", \"ovat\", \"lyhytkestoiset\", \"rakennustekniset\", \"pienkorjaukset\", \"niiden\", \"laadukas\", \"asukaslähtöinen\", \"toteuttaminen\", \"työtehtävälle\", \"asetetussa\"]',NULL,NULL,'[{\"url\": \"https://public.sokopro.fi/Quotations/Signup.aspx?crypt=WceQV9IImMacAOQN7NA1t18U9uj5TMzgPZ3gy%2F6k%2B%2BpfmOS2KLnCGIETBrSzyD1p\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2023-126865\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-126865\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"\", \"currency\": \"EUR\", \"deadline\": \"2023-05-31T07:00:00Z\", \"lowCarbon\": true, \"nuts