INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (100,'2023-127168','HILMA','RFP','OPEN','Perintäpalvelut/Vaasan Sähkö Oy ja Vaasan Sähköverkko Oy','Hankinta koskee Vaasan Sähkö -konsernin yhtiöiden; Vaasan Sähkö Oy:n ja Vaasan Sähköverkko Oy:n ostamia ulkoistettuja perintäpalveluja. Palvelut käsittävät Vaasan Sähkö -konsernin erääntyneiden saatavien vapaaehtoista, oikeudellista ja jälkiperintää sekä niihin liittyvien riita- ja rikosasioiden hoitoa kotimaassa. Hankinta koskee Vaasan Sähkö -konsernin yhtiöiden; Vaasan Sähkö Oy, 0209628-8 ja Vaasan Sähköverkko Oy, 1993667-7 ostamia ulkoistettuja perintäpalveluja. Palvelut käsittävät Vaasan Sähkö -konsernin erääntyneiden saatavien vapaaehtoista, oikeudellista ja jälkiperintää sekä niihin liittyvien riita- ja rikosasioiden hoitoa kotimaassa. Tarjoaja voi suorittaa perintätoimet omalla nimellään, Tilaajan puolesta ja Tilaajan lukuun. Tilaaja omistaa saatavan korkoineen perinnän kaikissa vaiheissa. Lisäksi Tilaajalla on oikeus päättää oikeudellisen perinnän oikeustoimien tarkoituksenmukaisuudesta. Sopimuksen piiriin kuuluvat muun muassa seuraavat: - Asiakaspalvelu - Saatavien vapaaehtoinen perintä, sisältäen energiantoimituksen katkaisu- ja kytkentäprosessin - Saatavien oikeudellinen perintä - Konkurssivalvonnat - Velkajärjestelyt - Yrityssaneeraukset - Jälkiperintä - Raportointi ja tilitykset - Riita-asiat tarvittaessa Tarjoaja sitoutuu noudattamaan kaikissa suorittamissaan palveluissa ja töissä voimassa olevaa lainsäädäntöä sekä niiden perusteella annettuja viranomaisten määräyksiä ja ohjeita. Palveluntuottaja vastaa siitä, että sen suorittamissa palveluissa ja töissä sovelletaan sähkömarkkinalakia ja -asetusta sekä Tilaajan kulloinkin voimassa olevia ehtoja (SME2014 (liite Sahkonmyyntiehdot-SME-2014),VPE2019 (liite Verkkopalveluehdot-VPE-2019), LE2019 (liite Liittymisehdot-LE-2019), Kaukolämmön yleiset sopimusehdot 1.12.2022 (liite kaukolammon-yleiset-sopimusehdot-1.12.2022-alkaen).','Sansia Oy','SME',5,14,NULL,NULL,1600000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2023-127168','[\"79940000\"]','[\"vaasan\", \"sähkö\", \"konsernin\", \"saatavien\", \"liite\", \"sähköverkko\", \"riita\", \"tilaajan\", \"hankinta\", \"koskee\", \"yhtiöiden\", \"ostamia\", \"ulkoistettuja\", \"perintäpalveluja\", \"palvelut\", \"käsittävät\", \"erääntyneiden\", \"vapaaehtoista\", \"oikeudellista\", \"jälkiperintää\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/sansia?id=457320&tpk=fd0d0a01-4e5e-473c-abf9-225a95678f6c\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2023-127168\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-127168\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"79940000\", \"currency\": \"EUR\", \"deadline\": \"2023-05-29T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI19\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"Hankinta koskee Vaasan Sähkö -konsernin yhtiöiden; Vaasan Sähkö Oy, 0209628-8 ja Vaasan Sähköverkko Oy, 1993667-7 ostamia ulkoistettuja perintäpalveluja.     Palvelut käsittävät Vaasan Sähkö -konsernin erääntyneiden saatavien vapaaehtoista, oikeudellista ja jälkiperintää sekä niihin liittyvien riita- ja rikosasioiden hoitoa kotimaassa.   Tarjoaja voi suorittaa perintätoimet omalla nimellään, Tilaajan puolesta ja Tilaajan lukuun. Tilaaja omistaa saatavan korkoineen perinnän kaikissa vaiheissa. Lisäksi Tilaajalla on oikeus päättää oikeudellisen perinnän oikeustoimien tarkoituksenmukaisuudesta.   Sopimuksen piiriin kuuluvat muun muassa seuraavat:  - Asiakaspalvelu  - Saatavien vapaaehtoinen perintä, sisältäen energiantoimituksen katkaisu- ja kytkentäprosessin  - Saatavien oikeudellinen perintä  - Konkurssivalvonnat  - Velkajärjestelyt  - Yrityssaneeraukset  - Jälkiperintä  - Raportointi ja tilitykset  - Riita-asiat tarvittaessa   Tarjoaja sitoutuu noudattamaan kaikissa suorittamissaan palveluissa ja töissä voimassa olevaa lainsäädäntöä sekä niiden perusteella annettuja viranomaisten määräyksiä ja ohjeita.    Palveluntuottaja vastaa siitä, että sen suorittamissa palveluissa ja töissä sovelletaan sähkömarkkinalakia ja -asetusta sekä Tilaajan kulloinkin voimassa olevia ehtoja (SME2014 (liite Sahkonmyyntiehdot-SME-2014),VPE2019 (liite Verkkopalveluehdot-VPE-2019), LE2019 (liite Liittymisehdot-LE-2019), Kaukolämmön yleiset sopimusehdot 1.12.2022 (liite kaukolammon-yleiset-sopimusehdot-1.12.2022-alkaen).\", \"descriptionSv\": null, \"procedureType\": \"open\", \"estimatedValue\": 1600000.0, \"expirationDate\": \"2023-05-29T09:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": null, \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": 0, \"winnerOrganisations\": \"\", \"innovationConsidered\": true, \"lotResultTotalAmount\": null, \"justWorkingConditions\": true, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTenders