INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (102,'2023-127156','HILMA','RFP','OPEN','Kiinteistönhoitopalvelut; Helsingin Kalasataman Kymppi Koy ja siihen liittyvä ajotunneli','Hankinnan kohteena ovat Helsingin Kalasataman Kymppi Koy:n kiinteistöön ja siihen liittyvään ajotunneliin kohdistuvat kiinteistöhoitopalvelut. Palvelusopimus tullaan tekemään yhden tarjoajan kanssa. Sopimuksen piiriin kuuluvista tehtävistä ja niiden sisällöstä on kerrottu tarkemmin tarjouspyynnön liitteenä olevassa Palvelukuvauksessa ja kohdekohtaisessa sähköisessä huoltokirjassa, johon pääsy ja sisältö on selostettu salassapitositoumusta vastaan erikseen toimitettavassa BEM-huoltokirjaohjeessa (liite 13) sekä tarjouspyynnön muissa liitteissä. Yritysten huomiota pyydetään kiinnittämään siihen, että saadakseen liitteen 13 (BEM-huoltokirjaohje tarjouslaskijalle), joka sisältää linkin ja tunnukset sähköiseen huoltokirjaan ja pääsyn luottamukselliseen aineistoon, yrityksen tulee toimittaa tarjouspyynnön liitteenä 12 toimitettu salassapitositoumus täytettynä ja allekirjoitettuna kohdassa VI.3 Lisätiedot esitetyllä tavalla. Huoltokirja on jatkuvassa käytössä ja sen sisältöä päivitetään. Kuvaus sopimuksen piiriin kuuluvista tehtävistä on kerrottu tarkemmin tarjouspyynnön liitteenä olevassa palvelukuvauksessa ja muissa liitteenä olevissa asiakirjoissa.','Helsingin kaupunki, kaupunkiympäristön toimiala','ANY',5,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2023-127156','[\"70330000\"]','[\"helsingin\", \"tarjouspyynnön\", \"liitteenä\", \"siihen\", \"kalasataman\", \"kymppi\", \"sopimuksen\", \"piiriin\", \"kuuluvista\", 