INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (103,'2023-127175','HILMA','RFP','OPEN','Turvallisuusviranomaisten karttajärjestelmän tuki-, ylläpito-, kehitys- ja asiantuntijapalvelut','Hankinnan kohteena ovat turvallisuustoimijoiden karttajärjestelmän tuki-, ylläpito-, kehitys- ja asiantuntijapalvelut. Karttajärjestelmän omistaa, hallinnoi ja ylläpitää Poliisihallitus. Poliisihallituksen lisäksi karttajärjestelmän käyttäjiä ovat laajasti turvallisuusviranomaiset ja muut valtionhallinnon toimijat sekä pelastus-, sosiaali- ja terveystoimen julkiset ja yksityiset toimijat. Tuki- ja ylläpitopalvelut käsittävät erityisesti karttatuotannon testiympäristöön kohdistuvat toimet kuten paikkatietoaineistojen jakaminen, ylläpitäminen ja erilaisten paikkatietotoiminnallisuuksien rakentaminen. Karttatuotannon kannalta olennaista on lähtöaineistojen tietosisällön ja rakenteen ajan tasalla pito yhteistyössä aineiston toimittajien ja Poliisihallituksen kanssa sekä karttajärjestelmän versioinnin hallinta. Kehitys- ja asiantuntijapalveluiden pääasiallinen tarkoitus on kehittää Poliisihallituksen karttatuotannon ja -palveluiden suorituskykyä sekä teknisesti että käyttäjälähtöisesti. Asiantuntijapalveluiden tehtävänä on konsultoida Poliisihallitusta karttatuotannon aineiston päivityksessä ja tuotantoprosessin muokkauksessa sekä turvallisuusviranomaisten välisten integraatioiden ja datan yhteensovittamisessa. Asiantuntijapalveluihin sisältyvät myös Tilaajan muiden järjestelmien paikkatieto-ominaisuuksien, kuten analyysitoimintojen, kehittäminen sekä karttatuotanto-ohjelmistojen koulutukset. Kilpailutettava sopimus tehdään toistaiseksi voimassa olevana. Hankinnan ennakoitu arvo on laskettu neljän (4) vuoden hankintojen arvioidun määrän mukaan. Tulevien hankintojen määrä riippuu turvallisuusviranomaisten järjestelmäkehitystarpeista ja käytettävissä olevasta rahoituksesta. Määrä voi merkittävästi vaihdella kehitystarpeiden ja käytettävissä olevan rahoituksen mukaisesti, koska kehitystä rahoitetaan vuosittain pääsääntöisesti hankerahoituksella. Tarkempi hankinnan kohteen kuvaus liitteessä 1 Hankinnan kohteen kuvaus. Hankinnan kohteena ovat turvallisuustoimijoiden karttajärjestelmän tuki-, ylläpito-, kehitys- ja asiantuntijapalvelut. Karttajärjestelmän omistaa, hallinnoi ja ylläpitää Poliisihallitus. Poliisihallituksen lisäksi karttajärjestelmän käyttäjiä ovat laajasti turvallisuusviranomaiset ja muut valtionhallinnon toimijat sekä pelastus-, sosiaali- ja terveystoimen julkiset ja yksityiset toimijat. Tuki- ja ylläpitopalvelut käsittävät erityisesti karttatuotannon testiympäristöön kohdistuvat toimet kuten paikkatietoaineistojen jakaminen, ylläpitäminen ja erilaisten paikkatietotoiminnallisuuksien rakentaminen. Karttatuotannon kannalta olennaista on lähtöaineistojen tietosisällön ja rakenteen ajan tasalla pito yhteistyössä aineiston toimittajien ja Poliisihallituksen kanssa sekä karttajärjestelmän versioinnin hallinta. Kehitys- ja asiantuntijapalveluiden pääasiallinen tarkoitus on kehittää Poliisihallituksen karttatuotannon ja -palveluiden suorituskykyä sekä teknisesti että käyttäjälähtöisesti. Asiantuntijapalveluiden tehtävänä on konsultoida Poliisihallitusta karttatuotannon aineiston päivityksessä ja tuotantoprosessin muokkauksessa sekä turvallisuusviranomaisten välisten integraatioiden ja datan yhteensovittamisessa. Asiantuntijapalveluihin sisältyvät myös Tilaajan muiden järjestelmien paikkatieto-ominaisuuksien, kuten analyysitoimintojen, kehittäminen sekä karttatuotanto-ohjelmistojen koulutukset. Kilpailutettava sopimus tehdään toistaiseksi voimassa olevana. Hankinnan ennakoitu arvo on laskettu neljän (4) vuoden hankintojen arvioidun määrän mukaan. Tulevien hankintojen määrä riippuu turvallisuusviranomaisten järjestelmäkehitystarpeista ja käytettävissä olevasta rahoituksesta. Määrä voi merkittävästi vaihdella kehitystarpeiden ja käytettävissä olevan rahoituksen mukaisesti, koska kehitystä rahoitetaan vuosittain pääsääntöisesti hankerahoituksella. Tarkempi hankinnan kohteen kuvaus liitteessä 1 Hankinnan kohteen kuvaus.','Poliisihallitus','ANY',7,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2023-127175','[\"72000000\", \"72212326\", \"72230000\", \"72250000\", \"72220000\", \"72310000\", \"72300000\", \"72320000\", \"72330000\"]','[\"karttajärjestelmän\", \"hankinnan\", \"karttatuotannon\", \"poliisihallituksen\", \"turvallisuusviranomaisten\", \"tuki\", \"kehitys\", \"ovat\", \"poliisihallitus\", \"toimijat\", \"kuten\", \"aineiston\", \"asiantuntijapalveluiden\", \"hankintojen\", \"määrä\", \"käytettävissä\", \"kohteen\", \"kuvaus\", \"ylläpito\", \"asiantuntijapalvelut\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/poliisihallitus?id=431529&tpk=2d2474df-90b0-4a15-9014-96ea95031542\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2023-127175\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-127175\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"72212326 72230000 72250000 72220000 72310000 72300000 72320000 72330000 72000000\", \"currency\": null, \"deadline\": \"2023-05-31T12:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"Hankinnan kohteena ovat turvallisuustoimijoiden karttajärjestelmän tuki-, ylläpito-, kehitys- ja asiantuntijapalvelut. Karttajärjestelmän omistaa, hallinnoi ja ylläpitää Poliisihallitus. Poliisihallituksen lisäksi karttajärjestelmän käyttäjiä ovat laajasti turvallisuusviranomaiset ja