INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (105,'2023-126525','HILMA','RFP','OPEN','Ponto-Kalaojan yksityistien parantaminen','Urakka sisältää Vehmaansuontien ja Pitkäahon yksityisteiden parantamisen, yhteensä noin 8 km, oheisten liiteasiakirjojen mukaisesti. Tarjous tulee antaa hankintailmoitukset.fi -toimittajaportaaliin ja ladata pyydetyt hintatarjouslomakkeet. Tarjouksen kokonaishinnan tulee perustua hintatarjouslomakkeiden (2 kpl) mukaisiin suoritemääriin ja litteroihin. Muita litteroita tai muutoksia alkuperäisiin litteroihin tarjoukseen ei saa sisällyttää. Hintatarjouslomakkeet tulee olla hinnoiteltu ja niissä laskettujen osatöiden hintojen summan tulee olla sama kuin kokonaishinta. Tarjoaja sitoutuu tarjouksen jättäessään kaikkiin tarjouspyynnössä ja sen liitteissä esitettyihin ehtoihin. Tarjoushinnat on esitettävä arvonlisäverollisina (sis alv 24 %) kiinteinä (euromääräisinä) nettohintoina, jotka sisältävät kaikki palvelun tuottamisesta aiheutuvat kustannukset mahdolliset matka-, päiväraha-, ylityö- sekä toimitus-, laskutus- ja toimistokulut mukaan lukien. Hintoihin, maksuihin ja muihin kaupallisiin ehtoihin liittyvät vaatimukset on esitetty tarjouspyynnön liitteenä olevissa asiakirjoissa. Tarjoaja sitoutuu tarjouksen jättäessään kaikkiin tässä tarjouspyynnössä ja sen liitteissä esitettyihin ehtoihin. Urakoitsija valitaan alimman tarjoushinnan perusteella. Tilaaja pidättää itselleen oikeuden olla hyväksymättä mitään annetuista tarjouksista. Tilaaja järjestää tarjoukset saatuaan hoitokunnan kokouksen, mikäli tiekunta päättää, että hanketta ei toteuteta, tilaaja hylkää kaikki tarjoukset ja näinollen hanke ei toteudu. Tilaajalla on oikeus myös hylätä tarjouspyyntöä vastaamattomat tarjoukset, puutteelliset tarjoukset sekä tarjoukset, joihin ei ole liitetty vaadittuja selvityksiä.','Ponto-Kalaoja yksityistien tiekunta','ANY',8,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2023-126525','[\"45000000\"]','[\"tarjoukset\", \"tulee\", \"ponto\", \"yksityistien\", \"tarjouksen\", \"ehtoihin\", \"tilaaja\", \"tiekunta\", \"hintatarjouslomakkeet\", \"litteroihin\", \"tarjoaja\", \"sitoutuu\", \"jättäessään\", \"kaikkiin\", \"tarjouspyynnössä\", \"liitteissä\", \"esitettyihin\", \"kalaoja\", \"kalaojan\", \"parantaminen\"]',NULL,NULL,'[{\"url\": \"https://hankintailmoitukset.fi/fi/public/procurement/86757/notice/126525\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2023-126525\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-126525\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"\", \"currency\": \"EUR\", \"deadline\": \"2023-05-24T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1D9\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"Tarjous tulee antaa hankintailmoitukset.fi -toimittajaportaaliin ja ladata pyydetyt hintatarjouslomakkeet. Tarjouksen kokonaishinnan tulee perustua hintatarjouslomakkeiden (2 kpl) mukaisiin suoritemääriin ja litteroihin. Muita litteroita tai muutoksia alkuperäisiin litteroihin tarjoukseen ei saa sisällyttää. Hintatarjouslomakkeet tulee olla hinnoiteltu ja niissä laskettujen osatöiden hintojen summan tulee olla sama kuin kokonaishinta. Tarjoaja sitoutuu tarjouksen jättäessään kaikkiin tarjouspyynnössä ja sen liitteissä esitettyihin ehtoihin.   Tarjoushinnat on esitettävä arvonlisäverollisina (sis alv 24 %) kiinteinä (euromääräisinä) nettohintoina, jotka sisältävät kaikki palvelun tuottamisesta aiheutuvat kustannukset mahdolliset matka-, päivära