INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (108,'2023-126847','HILMA','RFP','OPEN','ORIMATTILAN KAUPUNGIN KESKUSTA – HENNA LIITYNTÄLIIKENTEEN KÄYTTÖOIKEUSSOPIMUKSEN TARJOUSPYYNTÖ','Orimattilan kaupunki pyytää tarjousta Orimattilan kaupungin keskusta - Henna liityntäliikenteen hoitamisesta. Liikenteellä tarkoitetaan tässä tarjouspyynnössä joukkoliikenneluvan tai taksiluvan nojalla harjoitettavaa julkista henkilöliikennettä, joka on säännöllistä sekä palvelut ovat yleisesti käytettävissä, ja jonka hoitaminen perustuu Orimattilan kaupungin kanssa tehtyyn palvelujen ostamista koskevaan käyttöoikeussopimukseen. Sopimustyyppi on käyttöoikeussopimus. Käyttöoikeussopimuksessa matkustajilta kertyneet lipputulot jäävät suoraan tuloksi liikennöitsijälle. Kertyneet lipputulot, asiakasmäärät ja kilometrit kunkin kuukauden kohdalta tulee liikennöitsijän ilmoittaa reitti-, vuoro- ja päiväkohtaisesti myös nolla asiakasmääräajot kaupungille kuukausittain tapahtuvan laskutuksen yhteydessä palvelun käyttöasteen ja palvelun kehittymisen havaitsemiseksi. Orimattilan kaupunki pyytää tarjousta Orimattilan kaupungin keskusta - Henna liityntäliikenteen hoitamisesta. Liikenteellä tarkoitetaan tässä tarjouspyynnössä joukkoliikenneluvan tai taksiluvan nojalla harjoitettavaa julkista henkilöliikennettä, joka on säännöllistä sekä palvelut ovat yleisesti käytettävissä, ja jonka hoitaminen perustuu Orimattilan kaupungin kanssa tehtyyn palvelujen ostamista koskevaan käyttöoikeussopimukseen. Sopimustyyppi on käyttöoikeussopimus. Käyttöoikeussopimuksessa matkustajilta kertyneet lipputulot jäävät suoraan tuloksi liikennöitsijälle. Kertyneet lipputulot, asiakasmäärät ja kilometrit kunkin kuukauden kohdalta tulee liikennöitsijän ilmoittaa reitti-, vuoro- ja päiväkohtaisesti myös nolla asiakasmääräajot kaupungille kuukausittain tapahtuvan laskutuksen yhteydessä palvelun käyttöasteen ja palvelun kehittymisen havaitsemiseksi.','Orimattilan kaupunki','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2023-126847','[\"60120000\"]','[\"orimattilan\", \"kaupungin\", \"kertyneet\", \"lipputulot\", \"palvelun\", \"keskusta\", \"henna\", \"liityntäliikenteen\", \"kaupunki\", \"pyytää\", \"tarjousta\", \"hoitamisesta\", \"liikenteellä\", \"tarkoitetaan\", \"tässä\", \"tarjouspyynnössä\", \"joukkoliikenneluvan\", \"taksiluvan\", \"nojalla\", \"harjoitettavaa\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/orimattila?id=457640&tpk=bb9a7717-a838-4632-9a59-4ca6bf219bd6\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2023-126847\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-126847\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"60120000\", \"currency\": null, \"deadline\": \"2023-05-09T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1C3\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"Orimattilan kaupunki pyytää tarjousta Orimattilan kaupungin keskusta - Henna liityntäliikenteen hoitamisesta. Liikenteellä tarkoitetaan tässä tarjouspyynnössä joukkoliikenneluvan tai taksiluvan nojalla harjoitettavaa julkista henkilöliikennettä, joka on säännöllistä sekä palvelut ovat yleisesti käytettävissä, ja jonka hoitaminen perustuu Orimattilan kaupungin kanssa tehtyyn palvelujen ostamista koskevaan käyttöoikeussopimukseen. Sopimustyyppi on käyttöoikeussopimus. Käyttöoikeussopimuksessa matkustajilta kertyneet lipputulot jäävät suoraan tuloksi liikennöitsijälle. Kertyneet lipputulot, asiakasmäärät ja kilometrit kunkin kuuk