INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (119,'2025-020791','HILMA','RFP','OPEN','Hemodialyysihoitopaketit Honkaharjun dialyysiyksikköön','Hemodialyysihoitopaketit Honkaharjun dialyysiyksikköön Etelä-Karjalan hyvinvointialue (Ekhva) pyytää tarjouksia hemodialyysihoitopaketista Honkaharjun dialyysiyksikköön. Laitteen toimitusosoite on Honkaharjun dialyysiyksikkö, Honkaharju 4, 55800 Imatra. Hankinnan kohteen tarkat kriteerit ja soveltuvuusvaatimukset tarjouspyynnössä ja sen liitteissä. Sopimuskauden tavoitellaan alkavaksi 1.5.2025 ja se päättyy 30.4.2027, jonka jälkeen sopimus voi jatkua toistaiseksi voimassaolevana sopimuksena. Hemodialyysihoitoja tehdään Honkaharjun dialyysiyksikössä keskimäärin 3000 vuodessa. Tarjous tulee tehdä suomen kielellä. Tarjouspyynnön kohteena ovat täydelliset hemodialyysihoitopaketit WRO-laitteilla. Hoitopaketin hintaan sisältyy hemodialyysi-, WRO-laite ja hemodialyysihoidon koko tarvikepaketti sekä käytön tuki ja määräaikais- ja vikahuollot. Tarkempi kuvaus tarjouspyynnön liitteessä Kuvaus hankinnasta. Tarjoukseen pyydetään liittämään kaikista kulutustarvikkeista tuote- ja hintatiedot. Mikäli teillä on useampia laitteita, jotka vastaavat tarjouspyyntöä, jokaisesta tulee tehdä oma tarjouksensa.,','Etelä-Karjalan hyvinvointialue','ANY',3,11,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2025-020791','[\"33181100\"]','[\"honkaharjun\", \"hemodialyysihoitopaketit\", \"dialyysiyksikköön\", \"etelä\", \"karjalan\", \"hyvinvointialue\", \"tulee\", \"tehdä\", \"tarjouspyynnön\", \"kuvaus\", \"ekhva\", \"pyytää\", \"tarjouksia\", \"hemodialyysihoitopaketista\", \"laitteen\", \"toimitusosoite\", \"dialyysiyksikkö\", \"honkaharju\", \"imatra\", \"hankinnan\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/ekhva?id=523424&tpk=91a61fc6-8dea-49f1-9f6f-12222f3fac9e\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2025-020791\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-20791\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Hemodialyysihoitopaketit Honkaharjun dialyysiyksikköön\", \"titleSv\": \"\", \"cpvCodes\": \"33181100\", \"currency\": null, \"deadline\": \"2025-03-26T10:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1C5\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"Etelä-Karjalan hyvinvointialue (Ekhva) pyytää tarjouksia hemodialyysihoitopaketista Honkaharjun dialyysiyksikköön.  \\n\\nLaitteen toimitusosoite on Honkaharjun dialyysiyksikkö, Honkaharju 4, 55800 Imatra.\\n\\nHankinnan kohteen tarkat kriteerit ja soveltuvuusvaatimukset tarjouspyynnössä ja sen liitteissä.\\n\\nSopimuskauden tavoitellaan alkavaksi 1.5.2025  ja se päättyy 30.4.2027, jonka jälkeen sopimus voi jatkua toistaiseksi voimassaolevana sopimuksena. \\nHemodialyysihoitoja tehdään Honkaharjun dialyysiyksikössä keskimäärin 3000 vuodessa.\\n\\nTarjous tulee tehdä suomen kielellä.   \\n\\nTarjouspyynnön kohteena ovat täydelliset hemodialyysihoitopaketit WRO-laitteilla. Hoitopaketin hintaan sisältyy hemodialyysi-, WRO-laite ja hemodialyysihoidon koko tarvikepaketti sekä käytön tuki ja määräaikais- ja vikahuollot. Tarkempi kuvaus tarjouspyynnön liitteessä Kuvaus hankinnasta.\\n\\nTarjoukseen pyydetään liittämään kaikista kulutustarvikkeista tuote- ja hintatiedot.\\n\\nMikäli teillä on useampia laitteita, jotka vastaavat tarjouspyyntöä, jokaisesta tulee tehdä oma tarjouksensa.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2025-03-26T10:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"16\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"Hemodialyysihoitopaketit Honkaharjun dialyysiyksikköön\", \"titleSv\": \"\", \"cpvCodes\": \"33181100\", \"currency\": null, \"deadline\": \"2025-03-26T10:00:00Z\", \"eFormsId\": \"f0d2f284-ce80-4687-9549-10e524ce41d1\", \"isEForms\": true, \"mainType\": \"ContractNotices\", \"noticeId\": 20791, \"lowCarbon\": false, \"nutsCodes\": \"FI1C5\", \"titleOther\": \"\", \"isCancelled\": false, \"procedureId\": 14246, \"biodiversity\": false, \"dateModified\": \"2025-02-21T08:05:03.13Z\", \"fullEFormsId\": \"f0d2f284-ce80-4687-9549-10e524ce41d1-01\", \"noticeNumber\": \"2025-020791\", \"@search.score\": 1.0, \"codeOfConduct\": true, \"datePublished\": \"2025-02-21T08:05:03.118Z\", \"descriptionEn\": \"\", \"descriptionFi\": \"Hem