INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (275,'DEMO-HC-001','HILMA','RFP','OPEN','Tarjouspyyntö: Terveydenhuollon digitaaliset etäpalvelut ja videovastaanotot','Pirkanmaan hyvinvointialue kilpailuttaa terveydenhuollon digitaaliset etäpalvelut. Hankinta sisältää videovastaanottoalustan, ajanvarausjärjestelmän ja integraatiot olemassa oleviin potilastietojärjestelmiin. Sopimuskausi 2 + 1 + 1 vuotta.','Pirkanmaan hyvinvointialue','SME',1,3,'2026-08-25','2026-10-20',750000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-DEMO-HC1','[\"72000000\", \"85000000\"]','[\"telemedicine\", \"video consultation\", \"digital health\", \"remote care\"]','hankinnat@pirha.fi','+358 3 311 69611','[{\"url\": \"https://tarjouspalvelu.fi/pirha?id=600100\", \"name\": \"Tarjouspyyntö (PDF)\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-DEMO-HC1\", \"name\": \"HILMA Notice\"}, {\"url\": \"https://tarjouspalvelu.fi/pirha?id=600100&att=tech\", \"name\": \"Tekninen liite (PDF)\"}]','{\"source\": \"demo_seed\"}',74,NULL,'2026-09-04 10:46:24','2026-09-04 10:46:24');
