INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (283,'DEMO-EDU-002','TED','RFI','OPEN','Prior Information Notice: National Research Computing Infrastructure 2027','CSC – IT Center for Science announces a Prior Information Notice for the next generation national research computing infrastructure. The procurement will cover HPC cluster hardware, GPU compute capacity, petascale storage and interconnect. Estimated total value EUR 120M over 7 years.','CSC – IT Center for Science','LARGE',6,1,'2026-09-04','2026-12-01',120000000.00,'EUR','https://ted.europa.eu/en/notice/-/detail/2026-DEMO-EDU2','[\"72000000\", \"30000000\"]','[\"HPC\", \"supercomputer\", \"research computing\", \"GPU\", \"data center\"]','hankinta@csc.fi','+358 9 457 2001','[{\"url\": \"https://ted.europa.eu/en/notice/2026-DEMO-EDU2/pdf\", \"name\": \"PIN Notice PDF (ENG)\"}, {\"url\": \"https://ted.europa.eu/fi/notice/2026-DEMO-EDU2/pdf\", \"name\": \"PIN Notice PDF (Finnish)\"}, {\"url\": \"https://ted.europa.eu/en/notice/-/detail/2026-DEMO-EDU2\", \"name\": \"Technical Consultation Document\"}]','{\"source\": \"demo_seed\"}',90,NULL,'2026-09-04 10:46:24','2026-09-04 10:46:24');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (284,'DEMO-FIN-001','HILMA','RFP','OPEN','Tarjouspyyntö: Taloushallinnon SaaS-järjestelmä kunnille','Tampereen kaupunki johtavana hankintayksikkönä kilpailuttaa taloushallinnon SaaS-järjestelmän 12 kunnalle. Hankinta kattaa kirjanpidon, laskutuksen, budjetoinnin ja raportoinnin. Arvioitu kokonaisarvo 2 M€ / 4 vuotta.','Tampereen kaupunki (yhteiShankinta)','SME',1,3,'2026-07-28','2026-09-25',2000000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-DEMO-FIN1','[\"72000000\", \"66000000\"]','[\"ERP\", \"financial management\", \"SaaS\", \"accounting\", \"municipal\"]','yhteiShankinnat@tampere.fi','+358 3 5656 0000','[{\"url\": \"https://tarjouspalvelu.fi/tampere?id=600600\", \"name\": \"Tarjouspyyntö (PDF)\"}, {\"url\": \"https://tarjouspalvelu.fi/tampere?id=600600&att=req\", \"name\": \"Liite 1 – Vaatimusmäärittely (PDF)\"}, {\"url\": \"https://tarjouspalvelu.fi/tampere?id=600600&att=contract\", \"name\": \"Liite 2 – Sopimusluonnos (PDF)\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-DEMO-FIN1\", \"name\": \"HILMA Notice\"}]','{\"source\": \"demo_seed\"}',78,NULL,'2026-09-04 10:46:24','2026-09-04 10:46:24');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (285,'DEMO-DEF-001','TED','RFP','OPEN','Drone Detection and Counter-UAS System for Border Guard','The Finnish Border Guard is procuring a drone detection and counter-UAS system for deployment along the eastern border. The system must integrate with existing surveillance infrastructure, support multi-sensor fusion and AI-based classification. Security-cleared suppliers only. Estimated EUR 9M.','Finnish Border Guard (Rajavartiolaitos)','LARGE',1,13,'2026-08-30','2026-11-07',9000000.00,'EUR','https://ted.europa.eu/en/notice/-/detail/2026-DEMO-DEF1','[\"38000000\", \"72000000\"]','[\"drone detection\", \"counter-UAS\", \"border security\", \"AI surveillance\"]','hankinta@raja.fi','+358 295 421 000','[{\"url\": \"https://ted.europa.eu/en/notice/2026-DEMO-DEF1/pdf\", \"name\": \"Contract Notice PDF (ENG)\"}, {\"url\": \"https://ted.europa.eu/fi/notice/2026-DEMO-DEF1/pdf\", \"name\": \"Contract Notice PDF (Finnish)\"}, {\"url\": \"https://ted.europa.eu/en/notice/-/detail/2026-DEMO-DEF1\", \"name\": \"Security Requirements Document\"}]','{\"source\": \"demo_seed\"}',80,NULL,'2026-09-04 10:46:24','2026-09-04 10:46:24');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (286,'DEMO-OULU-001','FinnishCities','RFP','OPEN','Oulun älykaupunki: IoT-sensorit ja datanhallinnan alusta','Oulun kaupunki kilpailuttaa IoT-sensoreiden laajennuksen ja datanhallinnan alustan älykaupunkistrategian toteuttamiseksi. Hankinta sisältää 2000 uutta ilmanlaatu-, liikenteen ja energiamittaria sekä pilvi-alustan datan käsittelyyn.','Oulun kaupunki / Yhdyskunta- ja ympäristöpalvelut','SME',1,5,'2026-08-05','2026-10-05',1200000.00,'EUR','https://www.ouka.fi/hankintailmoitukset/2026-DEMO-OULU1','[\"38000000\", \"72000000\"]','[\"IoT\", \"smart city\", \"sensors\", \"data platform\", \"air quality\"]','hankinnat@ouka.fi','+358 8 558 410 00','[{\"url\": \"https://tarjouspalvelu.fi/oulu?id=600700\", \"name\": \"Tarjouspyyntö (PDF)\"}, {\"url\": \"https://tarjouspalvelu.fi/oulu?id=600700&att=arch\", \"name\": \"IoT-arkkitehtuuri (PDF)\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-DEMO-OULU1\", \"name\": \"HILMA Notice\"}]','{\"source\": \"demo_seed\"}',77,NULL,'2026-09-04 10:46:24','2026-09-04 10:46:24');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (287,'DEMO-TURKU-001','FinnishCities','RFI','OPEN','Tietopyyntö: Digitaalinen kaksonen Turun satamalle','Turun Satama Oy pyytää tietoja digitaalisen kaksosen (digital twin) toimittajilta sataman operatiivista suunnittelua varten. Ratkaisu integroituu AIS-järjestelmään ja laiturinohjausjärjestelmiin. Tietopyyntö edeltää hankintamenettelyä.','Turun Satama Oy','SME',1,14,'2026-08-12','2026-10-12',NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-DEMO-TURKU1','[\"72000000\", \"63000000\"]','[\"digital twin\", \"port\", \"maritime\", \"simulation\", \"AIS\"]','kilpailutus@portofturku.fi','+358 2 267 3100','[{\"url\": \"https://tarjouspalvelu.fi/turkusatama?id=600800\", \"name\": \"Tietopyyntö (PDF)\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-DEMO-TURKU1\", \"name\": \"HILMA Notice\"}]','{\"source\": \"demo_seed\"}',73,NULL,'2026-09-04 10:46:24','2026-09-04 10:46:24');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (438,'57b18ddbc5d88cb84f0e','FinnishCities','RFP','OPEN','Tarjouspalvelu-portaali','Pirkanmaan hyvinvointialue vastaa sosiaali- ja terveydenhuollosta sekä pelastustoimesta. Asiakkaille kohdentuvien palvelujen lisäksi hyvinvointialue hankkii palvelutuotannon tarvitsemia palveluja, aineita, tarvikkeita ja tavaroita. Hankintojen arvo on hyvinvointialueella noin 1,4 miljardia euroa vuodessa.','City of Tampere – Wellbeing','ANY',3,3,NULL,NULL,NULL,'EUR','http://tarjouspalvelu.fi/Default/Index',NULL,'[\"hyvinvointialue\", \"tarjouspalvelu\", \"portaali\", \"pirkanmaan\", \"vastaa\", \"sosiaali\", \"terveydenhuollosta\", \"pelastustoimesta\", \"asiakkaille\", \"kohdentuvien\", \"palvelujen\", \"lisäksi\", \"hankkii\", \"palvelutuotannon\", \"tarvitsemia\", \"palveluja\", \"aineita\", \"tarvikkeita\", \"tavaroita\", \"hankintojen\"]',NULL,NULL,NULL,'{\"text\": \"Pirkanmaan hyvinvointialue vastaa sosiaali- ja terveydenhuollosta sekä pelastustoimesta. Asiakkaille kohdentuvien palvelujen lisäksi hyvinvointialue hankkii palvelutuotannon tarvitsemia palveluja, aineita, tarvikkeita ja tavaroita. Hankintojen arvo on hyvinvointialueella noin 1,4 miljardia euroa vuodessa. Pirkanmaan hyvinvointialueen hankinnat löytyvät tarjouspalvelu.fi-sivustolta Tuomi Logistiikka Oy:n julkaisemana: Tarjouspalvelu-portaali Kansallisen ja EU-kynnysarvon ylittävät hankinnat ilmoitetaan HILMAssa: Hilma - Julkiset hankinnat Keskeiset asiakirjat Pirkanmaan hyvinvointialueen hankintaohjelma 2026 - 2029 (pdf) Pirkanmaan hyvinvointialueen hankintasuunnitelma 2026 - 2027 (pdf) Sosiaalihuollon kirjaamisen opas (pdf, Pirkanmaan hyvinvointialueelle palveluja tuottaville yksityisille palveluntuottajille Kantaan kirjaamisen tueksi)\"}',47,NULL,'2026-09-04 17:00:16','2026-09-08 15:13:52');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (439,'04f2d224b07356c677d3','FinnishCities','RFP','OPEN','Pirha tutkihankintoja.fi-palvelussa','','City of Tampere – Wellbeing','ANY',3,3,NULL,NULL,NULL,'EUR','https://tutkihankintoja.fi/hankintayksikot/Pirkanmaan%20hyvinvointialue',NULL,'[\"pirha\", \"tutkihankintoja\", \"palvelussa\", \"city\", \"tampere\", \"wellbeing\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Pirha tutkihankintoja.fi-palvelussa\"}',42,NULL,'2026-09-04 17:00:16','2026-09-08 15:13:52');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (440,'dd85f8fd0ea589a14fdc','FinnishCities','RFP','OPEN','Hankintakalenteri','Tarjoamme kuntalaisille erilaisia palveluja ja kilpailutamme ne hankintalain ja kaupungin oman hankintaohjeistuksen mukaisesti. Tehtäviimme kuuluu myös hankkia palveluja ja tavaroita omaan palveluntuotantoomme. Hankinnoilla haluamme tukea paikallista yrittäjyyttä ja elinvoiman kasvua.','City of Kouvola','ANY',10,14,NULL,NULL,NULL,'EUR','https://www.kouvola.fi/wp-content/uploads/2026/05/hankintakalenteri-2026.xlsx',NULL,'[\"palveluja\", \"hankintakalenteri\", \"tarjoamme\", \"kuntalaisille\", \"erilaisia\", \"kilpailutamme\", \"hankintalain\", \"kaupungin\", \"oman\", \"hankintaohjeistuksen\", \"mukaisesti\", \"tehtäviimme\", \"kuuluu\", \"hankkia\", \"tavaroita\", \"omaan\", \"palveluntuotantoomme\", \"hankinnoilla\", \"haluamme\", \"tukea\"]',NULL,NULL,NULL,'{\"text\": \"Tarjoamme kuntalaisille erilaisia palveluja ja kilpailutamme ne hankintalain ja kaupungin oman hankintaohjeistuksen mukaisesti. Tehtäviimme kuuluu myös hankkia palveluja ja tavaroita omaan palveluntuotantoomme. Hankinnoilla haluamme tukea paikallista yrittäjyyttä ja elinvoiman kasvua. Hankintakalenteri Näet suunnitteilla olevat hankinnat ja voimassa olevat vuosisopimukset hankintakalenterista. Hankintakalenterin tavoitteena on lisätä kaupungin ja yrittäjien välistä vuoropuhelua. Jos löydät kalenterista sinua kiinnostavan hankinnan, ota yhteyttä kalenterissa nimettyyn yhteyshenkilöön. Tutustu hankintakalenteriin tästä (xlsx, 49 kt) Tarjouspyynnöt Katso kaikki voimassa olevat avoimet tarjouspyynnöt Cloudia tarjouspalvelusta . Hankintaohjeistus Ohjeistus koostuu hankintaohjelmasta, hankintaohjeesta ja hankintakäsikirjasta. Hankintaohjelma (pdf, 624 kt) perustuu kaupunkistrategiaan. Hankintaohjelmassa linjataan, kuinka hankinnoilla pyrimme lisäämään kaupungin elinvoimaa ja hyvinvointia. Ohjelman tavoitteena on myös hankintatoimintamme kehittäminen. Hankintaohje sisältää yleisiä ohjeita hankintavaltuuksista, hankintaohjelman toimeenpanosta sekä sopimusaikaisesta toiminnasta. Hankintaohj\"}',47,NULL,'2026-09-04 17:16:30','2026-09-08 15:13:54');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (441,'8f27786267fee1cbea16','FinnishCities','RFP','OPEN','Kansalliset ja EU-kynnysarvot','','City of Kouvola','ANY',10,14,NULL,NULL,NULL,'EUR','https://www.hankinnat.fi/mika-julkinen-hankinta/kynnysarvot',NULL,'[\"kansalliset\", \"kynnysarvot\", \"city\", \"kouvola\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Kansalliset ja EU-kynnysarvot\"}',42,NULL,'2026-09-04 17:16:30','2026-09-08 15:13:54');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (442,'a24e21361f4e440a39bc','FinnishCities','RFP','OPEN','Kuntaliiton hankintasivut','','City of Kouvola','ANY',10,14,NULL,NULL,NULL,'EUR','http://www.hankinnat.fi',NULL,'[\"kuntaliiton\", \"hankintasivut\", \"city\", \"kouvola\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Kuntaliiton hankintasivut\"}',42,NULL,'2026-09-04 17:16:30','2026-09-08 15:13:54');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (444,'1d5962c166ace9f4ada9','FinnishCities','RFP','OPEN','Hankinta-asiamiehen uutiskirje 1/2022','','City of Kouvola','ANY',10,14,NULL,NULL,NULL,'EUR','http://uutiskirje.kinno.fi/a/s/188749449-33a3f01ba66064a40b523d5f7f908421/4947103',NULL,'[\"hankinta\", \"asiamiehen\", \"uutiskirje\", \"city\", \"kouvola\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Hankinta-asiamiehen uutiskirje 1/2022\"}',42,NULL,'2026-09-04 17:16:30','2026-09-04 17:16:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (464,'2026-056258','HILMA','RFI','OPEN','Kutsu markkinainfoon ja tekniseen vuoropuheluun: Taloushallinto- ja HR-ratkaisujen tulevat hankinnat','Espoon seudun koulutuskuntayhtymä Omnia (hankintayksikkö) suunnittelee talous- ja HR-järjestelmiensä ja -palveluiden kilpailutusta. Omnia kutsuu kiinnostuneita toimittajia osallistumaan markkinainfotilaisuuteen ja tekniseen vuoropuheluun koskien Omnian tulevia talous- ja HR-ratkaisujen hankintoja. MARKKINAINFOTILAISUUS Markkinainfo järjestetään 1.10.2026 klo 15.00–16.00 etätilaisuutena Teamsillä. Tilaisuudessa esitellään: - hankintojen nykyinen valmistelutilanne - alustavat tavoitteet ja aikataulut - suunniteltu kilpailutusmalli - keskeiset hankinnan kohteet ja rajaukset TEKNINEN VUOROPUHELU Markkinainfon jälkeen Omnia tarjoaa halukkaille toimittajille mahdollisuuden osallistua hankintojen valmistelua tukevaan tekniseen vuoropuheluun. Tekniset vuoropuhelut toteutetaan ensisijaisesti kirjallisesti ja hankintakohtaisesti siten, että taloushallinnon ja HR-ratkaisujen hankinnat käsitellään erillisinä kokonaisuuksina. Teknisten vuoropuhelujen tarkoituksena on kerätä markkinoiden näkemyksiä hankinnan valmistelun tueksi sekä mahdollistaa alustavien hankinta-asiakirjojen kommentointi ennen varsinaisten kilpailutusten käynnistämistä. Kommentoitava aineisto voi sisältää esimerkiksi alustavia vaatimusmäärittelyjä, sopimusluonnoksia ja arviointimalleja. Tekniseen vuoropuheluun osallistuville toimittajille toimitetaan erikseen kommentoitava aineisto sekä tarkemmat ohjeet ja aikataulu. Tekniseen vuoropuheluun on mahdollista osallistua, vaikka ei osallistuisi markkinainfotilaisuuteen. Hankintayksikkö voi pyytää teknisen vuoropuhelun yhteydessä toimittajilta myös alustavia arvioita ratkaisujen kustannustasoista hankinnan ennakoidun arvon arvioinnin tueksi. ILMOITTAUTUMINEN Ilmoittautuminen markkinainfoon ja/tai tekniseen vuoropuheluun viimeistään 30.9.2026 klo 16.00: https://forms.cloud.microsoft/e/TU1Wnxnscg, Taloushallintopalveluiden ja -järjestelmien hankinta SaaS-palveluna Hankinnan kohteena tulevat olemaan Omnian taloushallinnon järjestelmät sekä niihin liittyvät palvelut. Kilpailutuksen piiriin kuuluvat Omnian tämänhetkisten suunnitelmien mukaan seuraavat osa-alueet: osto- ja myyntilasku, kirjanpito mukaan lukien käyttöomaisuuden hallinta, talouden suunnittelu ja raportointi, maksuliikenne ja arkistointi, sekä optiona kassatoiminnot, henkilöstösuunnittelun toiminnot sekä likviditeetin hallinta- ja seurantajärjestelmä. Omnian tavoiteaikataulun mukaisesti talouden suunnittelu tulisi pystyä aloittamaan uudella järjestelmällä syksyllä 2027 ja täysimittainen tuotantokäyttö 1.1.2028. Käyttöönottoprojektin aikana tulee rakentaa tarvittavat integraatiot sekä kouluttaa henkilöstö järjestelmien käyttöön., HR-järjestelmäkokonaisuus SaaS-palveluna ja palkanlaskenta kokonaispalveluna Hankinnan tavoitteena on löytää luotettava ja nykyaikainen palkanlaskennan kumppani, jolta saadaan palkanlaskennan palvelu kokonaispalveluna, laadukas järjestelmäkokonaisuus sekä hyvät käyttömahdollisuudet eri käyttäjäryhmille esim. HR-käyttäjille, esihenkilöille ja työntekijöille. Palkanlaskennan kokonaispalvelulla tarkoitetaan, että palkanlaskennan kumppani tekee palkanlaskennan alusta loppuun sekä hoitaa viranomaisraportoinnit ja muun palkanlaskentaan liittyvän kolmansien osapuolten raportoinnin (sisältäen palkka-avoimuusdirektiivin vaatimusten mukaisen raportoinnin) sekä toimenpiteet Omnian valtuutuksella. Kokonaispalvelun tulee tukea henkilöstön johtamista, työnantajamielikuvaa ja esihenkilötyötä. Tärkeitä ominaisuuksia ovat mm. SSO-kirjautuminen, SaaS-ympäristö sekä käyttäjäystävällisyys. Toimittaja myös kehittää palveluaan ja tarjoamaansa järjestelmää aktiivisesti. Käyttäjien käyttöliittymän sekä palkkapalveluiden käyttökieli on suomi. Ratkaisun on oltava tietosuojalainsäädännön (GDPR) mukainen. Tiedon tallentamisen, tiedonhaun ja raporttitiedon tuottamisen tulee olla käyttäjälähtöistä, sujuvaa ja helppoa. Käytettävien järjestelmien ja sovellusten toimintojen tulee aktiivisesti tukea ja ohjata käyttäjiään. Järjestelmään kertyvien tietojen on oltava käyttäjilleen tehokkaasti saatavilla, käyttipä niitä toimistotiloissa tai etätyöskentelyssä. Käyttöliittymän/työpöytänäkymät tulee voida muokata helposti eri käyttötarpeisiin sopiviksi: esimerkiksi HR-käyttäjälle, esihenkilöille ja taloudelle ovat tarjolla kunkin tehtävän hoitoa tukevat näkymät.,','Espoon seudun koulutuskuntayhtymä Omnia','SME',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056258','[\"48000000\", \"48450000\", \"48812000\", \"72000000\", \"79211100\", \"79631000\", \"48442000\"]','[\"tekniseen\", \"vuoropuheluun\", \"omnian\", \"hankinnan\", \"tulee\", \"palkanlaskennan\", \"ratkaisujen\", \"omnia\", \"järjestelmien\", \"saas\", \"markkinainfoon\", \"tulevat\", \"hankinnat\", \"espoon\", \"seudun\", \"koulutuskuntayhtymä\", \"hankintayksikkö\", \"talous\", \"markkinainfotilaisuuteen\", \"hankintojen\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/omnia?id=623663&tpk=dadae702-2393-47e4-afc5-bffbb478a2ad\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056258\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56258\", \"lots\": [{\"id\": \"PAR-0001\", \"titleEn\": \"\", \"titleFi\": \"Taloushallintopalveluiden ja -järjestelmien hankinta SaaS-palveluna\", \"titleSv\": \"\", \"cpvCodes\": \"48000000 48442000 48812000 72000000 79211100\", \"currency\": null, \"deadline\": null, \"lowCarbon\": null, \"nutsCodes\": \"\", \"titleOther\": \"\", 