INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (466,'2026-056256','HILMA','OTHER','OPEN','Kiinteistönhoitopalvelut Keski-Suomen hyvinvointialueen tiloissa Keskussairaalantie 40, 40630 Jyväskylä','Kiinteistönhoitopalvelut Keski-Suomen hyvinvointialueen tiloissa Keskussairaalantie 40, 40630 Jyväskylä Hankinta koskee Keski-Suomen hyvinvointialueen tilojen kiinteistönhoitopalveluja osoitteessa Keskussairaalantie 40, 40630 Jyväskylä. Lisätietoa kohteesta on tarjouspyynnön liitteessä (liite 1 Sopimusluonnos ja liite 2 Palvelukuvaus) ja huoltokirjassa Granlund Manager. Huoltokirjasta löytyvät pohjakuvat, hoitoaluekartat, järjestelmäkortit sekä tilaajan laatima huolto-ohjelma, jonka mukaisesti työ tehdään. Hankinnasta tehdään sopimus yhden toimittajan kanssa. Hankintaa ei ole jaettu osiin, koska se muodostaa yhden luontevan kokonaisuuden. Suositellaan kohteeseen tutustumista. Tarjoajille järjestetään TUTUSTUMINEN KOHTEESEEEN viikolla 17 To 23.4. klo 14-16 . Kokoontuminen Sairaala Novan infopisteen edessä klo 14. Kokoontumispaikan osoite on Hoitajantie 3, 40630 Jyväskylä Kohdekierrolle ilmoittaudutaan ke 22.4. klo 12 mennessä sähköpostilla kilpailutuspalvelut@hyvaks.fi Sähköpostin otsikoksi \"Kohde-esittely / Keskussairaalantie 40\". HUOLTOKIRJATUNNUKSET Pyydetään sähköpostilla ilkka.kujala@hyvaks.fi,','Keski-Suomen hyvinvointialue','ANY',3,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056256','[\"70000000\"]','[\"keski\", \"suomen\", \"keskussairaalantie\", \"jyväskylä\", \"hyvinvointialueen\", \"kiinteistönhoitopalvelut\", \"tiloissa\", \"liite\", \"tehdään\", \"yhden\", \"sähköpostilla\", 