INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (467,'2026-056255','HILMA','OTHER','OPEN','Avannetarvikkeet','Hankinnan kohteena ovat avannetarvikkeet Pohjois-Pohjanmaan hyvinvointialueelle (Pohde) ja yhteistyöalueen yksiköiden Kainuun, Keski-Pohjanmaan sekä Lapin hyvinvointialueelle tämän tarjouspyynnön ja sen liitteiden mukaisesti. Hankintayksikön tarkoitus on saada tarjoukset uusimmista tuotteista. Hankinta on jaettu useaan osa-alueeseen. Tarjoaja voi jättää tarjouksen yhteen tai useampaan osa-alueeseen. Tarjoaja sitoutuu tarjouksen jättäessään kaikkiin tämän tarjouspyynnön sekä sen liitteiden ehtoihin. Hankintasopimusten arvioitu alkamispäivä on 1.3.2027. Sopimuskausi on kaksi vuotta, jonka jälkeen on mahdollisuus kahteen optiovuoteen (1+1vuotta)., 1-osaisten avannesidosten paketit Ryhmä 1 käsittää 1-osaisten avannesidosten paketit. Katso tarkat hankinnan kohteen kriteerit tarjouspyynnön excel-liitteestä Tarjouspohja PPHVADno-2026-3802 Avannetarvikkeet. Osa-alueittain valitaan enintään 7 toimittajaa. Toimittajien etusijajärjestys määräytyy vertailuperusteiden perusteella halvin hinta. Etusijajärjestyksestä voidaan poiketa yksilöllisin terveydellisin tai hoidollisin perustein. Hankintayksikön tarkoitus on saada tarjoukset uusimmista tuotteista., Avannelevyjen ja 2- osaisten avannepussien paketit Ryhmä 2 käsittää avannelevyjen ja 2- osaisten avannepussien paketit. Katso tarkat hankinnan kohteen kriteerit tarjouspyynnön excel-liitteestä Tarjouspohja PPHVADno-2026-3802 Avannetarvikkeet. Osa-alueittain valitaan enintään 7 toimittajaa. Toimittajien etusijajärjestys määräytyy vertailuperusteiden perusteella halvin hinta. Etusijajärjestyksestä voidaan poiketa yksilöllisin terveydellisin tai hoidollisin perustein. Hankintayksikön tarkoitus on saada tarjoukset uusimmista tuotteista., Ihonsuojarenkaat Ryhmä 3 käsittää ihonsuojarenkaat. Katso tarkat hankinnan kohteen kriteerit tarjouspyynnön excel-liitteestä Tarjouspohja PPHVADno-2026-3802 Avannetarvikkeet. Osa-alueittain valitaan enintään 7 toimittajaa. Toimittajien etusijajärjestys määräytyy vertailuperusteiden perusteella halvin hinta. Etusijajärjestyksestä voidaan poiketa yksilöllisin terveydellisin tai hoidollisin perustein. Hankintayksikön tarkoitus on saada tarjoukset uusimmista tuotteista., Muut avannetarvikkeet Ryhmä 4 käsittää muut avannetarvikkeet. Katso tarkat hankinnan kohteen kriteerit tarjouspyynnön excel-liitteestä Tarjouspohja PPHVADno-2026-3802 Avannetarvikkeet. Osa-alueittain valitaan enintään 7 toimittajaa. Toimittajien etusijajärjestys määräytyy vertailuperusteiden perusteella halvin hinta. Etusijajärjestyksestä voidaan poiketa yksilöllisin terveydellisin tai hoidollisin perustein. Hankintayksikön tarkoitus on saada tarjoukset uusimmista tuotteista.,','Pohjois-Pohjanmaan hyvinvointialue','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056255','[\"33000000\"]','[\"avannetarvikkeet\", \"tarjouspyynnön\", \"hankinnan\", \"hankintayksikön\", \"tarkoitus\", \"saada\", \"tarjoukset\", \"uusimmista\", \"tuotteista\", \"pohjanmaan\", \"osaisten\", \"paketit\", \"ryhmä\", \"käsittää\", \"katso\", \"tarkat\", \"kohteen\", \"kriteerit\", \"excel\", \"liitteestä\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056255\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56255\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"1-osaisten avannesidosten paketit\", \"titleSv\": \"\", \"cpvCodes\": \"33000000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": false, \"nutsCodes\": \"\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfCo