INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (492,'2026-056360','HILMA','RFP','OPEN','Rakennusurakka Kuhmon terveysaseman uudisrakennus','Rakennusurakka Kuhmon terveysaseman uudisrakennus Rakennuskohde on 1. kerroksinen terveysasema. Urakkakilpailu (tarjousaika) toteutetaan hankintalain (519/2026) 57 §:n mukaisesti nopeutetulla menettelyllä. Nykyisen terveysasemalla on huomattava sisäilmasto-ongelma, eikä korvaavia työtiloja ole mahdollista järjestää. Sisäilmasto-ongelman vuoksi uuden terveysaseman rakennuttamista on kiirehdittävä. Lisäksi rakentamisen aloittamisen ajankohdan siirtyminen myöhäisempää syksyyn nostaa urakoitsijoiden kustannuksia ja voi aiheuttaa rakentamisen laatuvirheitä. Urakkakilpailu toteutetaan pääsääntöisesti aiemman (tarjouspyyntö 619937 / 15.7.2026 + lisäkirjeet) kilpailutuksen mukaisella laskenta-aineistolla. Muutokset aiempiin urakka-asiakirjoihin löytyvät kohdassa \"Hankintaa tai osaa koskevat lisätiedot\".,','Kuhmon kaupunki','ANY',1,3,NULL,NULL,5200000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056360','[\"45000000\", \"45211200\"]','[\"kuhmon\", \"terveysaseman\", \"rakennusurakka\", \"uudisrakennus\", \"urakkakilpailu\", \"toteutetaan\", \"sisäilmasto\", \"rakentamisen\", \"rakennuskohde\", \"kerroksinen\", \"terveysasema\", \"tarjousaika\", \"hankintalain\", \"mukaisesti\", \"nopeutetulla\", \"menettelyllä\", \"nykyisen\", \"terveysasemalla\", \"huomattava\", \"ongelma\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/kuhmo?id=626571&tpk=c013a66b-aa9a-4f05-ad36-0fd68c215214\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.f