INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (493,'2026-160556','HILMA','RFP','OPEN','Leiri- ja kurssikeskusvaraukset','Kesälukioseura järjestää Suomessa asuville pakolaislapsille ja -nuorille leirimuotoisia oman äidinkielen ja kulttuurin kursseja. Kesälukioseura etsii vuoden 2027 kursseja varten leiri- ja kurssikeskuksia eri puolilta Suomea. Kurssit ajoittuvat koulujen loma-ajoille (talvilomaviikko 8, kesä–heinäkuu). Oman äidinkielen ja kulttuurin kursseja järjestetään 8–9 (1–2 talvella, seitsemän kesällä). Kesän kurssit ovat pituudeltaan vajaan viikon mittaisia (5 vrk, esim. ma–la). Talvilomaleirin kesto on 4 vrk, ma-pe. Kursseille osallistuu noin 20–32 iältään 7–14-vuotiasta lasta sekä 4–7 omakielistä opettajaa. Jokaiselle osallistujalle pitää olla leirin aikana vuodepaikka (ei patjamajoitusta). Kesälukioseura vastaa kurssien järjestämisestä. Kurssien ohjaajatiimit vastaavat kurssien opetuksesta ja ohjelmasta. Kurssien järjestämisestä aiheutuvat kulut katetaan sosiaali- ja terveysministeriön myöntämällä avustuksella. Avustusta haetaan vuosittain, ja vuoden 2027 avustuspäätös selviää alkuvuodesta 2027. Hankinnan vertailuperusteina ovat turvallisuus, kokonaisedullisuus, luonnonläheisyys, kulkuyhteydet, riittävät opetus- ja harrastetilat, majoitus ja ylläpito sekä ajankohta. Tarjouksen voi tehdä yhdestä tai useammasta kurssiviikosta. Tarjouksesta tulee käydä ilmi ajankohta, jota tarjous koskee.','Kesälukioseura ry','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-160556','[\"55243000\"]','[\"kesälukioseura\", \"kurssien\", \"kursseja\", \"leiri\", \"oman\", \"äidinkielen\", \"kulttuurin\", \"vuoden\", \"kurssit\", \"ovat\", \"järjestämisestä\", \"ajankohta\", \"kurssikeskusvaraukset\", \"järjestää\", \"suomessa\", \"asuville\", \"pakolaislapsille\", \"nuorille\", \"leirimuotoisia\", \"etsii\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/public/procurement/111150/notice/160556\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-160556\", \"name\": \"HILMA Notice\"}]','{\"id\": \"OLD-160556\", \"lots\": [{\"id\": null, \"titleEn\": null, \"titleFi\": null, \"titleSv\": null, \"cpvCodes\": \"\", \"currency\": \"EUR\", \"deadline\": \"2026-09-25T13:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1\", \"titleOther\": null, \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": null, \"descriptionFi\": \"\", \"descriptionSv\": null, \"procedureType\": \"restricted\", \"estimatedValue\": 0.0, \"expirationDate\": \"2026-09-25T13:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": false, \"descriptionOther\": null, \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": 0, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": 0.0, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": \"\", \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tender