INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (502,'2026-056341','HILMA','RFP','OPEN','Piikatu 6 Logistiikan koulutusrakennus, jaettu urakka','Hankinnan kohteena on Piikatu 6 logistiikan koulutusrakennuksen rakennushanke sekä tähän liittyvät tekniset liityntätyöt. Koulutusrakennus sijoittuu Piikatu 6 tontille Imatralla. Rakennushanke sisältää koulutusrakennuksen, jätekatoksen sekä huoltohallin läpiajon mahdollistavan piha-alueen. Hanke toteutetaan tilaajan teettämien suunnitelmien mukaan jaettuna urakkana, jossa urakoitsijat ovat suorassa sopimussuhteessa tilaajaan. Rakennusurakoitsija on pääurakoitsija, joka vastaa työmaan johtovelvollisuuksista ja koordinoi rakentamista alistamissopimuksilla. Kilpailutus on jaettu seuraaviin osa-alueisiin: 1. Pääurakka/Rakennusurakka 2. Putkiurakka (sivu-urakka) 3. IV-urakka (sivu-urakka) 4. Sähköurakka (sivu-urakka) 5. Automaatiourakka (sivu-urakka) Edellytetään tutustumista kohteeseen paikan päällä (Piikatu 6, Imatra) yhteisessä näyttötilaisuudessa 15.9.2026 klo 9-11 tai muuna sovittuna aikana., Pääurakka/Rakennusurakka Rakennusurakoitsija on pääurakoitsija, joka vastaa työmaan johtovelvollisuuksista ja koordinoi rakentamista alistamissopimuksilla. Rakennusurakkaan kuuluu rakennuskohteen rakennustekniset työt saatettuna täysin valmiiksi ja toimintakuntoon asiakirjaluettelossa mainittujen suunnitelmien ja asiakirjojen mukaisesti., Putkiurakka Urakkaan kuuluu rakennuskohteen putkityöt saatettuna täysin valmiiksi ja toimintakuntoon asiakirjaluettelossa mainittujen suunnitelmien ja asiakirjojen mukaisesti. Putkiurakka alistetaan pääurakkaan sivu-urakan alistamissopimuksella., IV-urakka Urakkaan kuuluu rakennuskohteen IV-työt saatettuna täysin valmiiksi ja toimintakuntoon asiakirjaluettelossa mainittujen suunnitelmien ja asiakirjojen mukaisesti. IV-urakka alistetaan pääurakkaan sivu-urakan alistamissopimuksella., Sähköurakka Urakkaan kuuluu rakennuskohteen sähkötyöt saatettuna täysin valmiiksi ja toimintakuntoon asiakirjaluettelossa mainittujen suunnitelmien ja asiakirjojen mukaisesti. Sähköurakka alistetaan pääurakkaan sivu-urakan alistamissopimuksella., Automaatiourakka Urakkaan kuuluu rakennusautomaatiotyöt saatettuna täysin valmiiksi ja toimintakuntoon asiakirjaluettelossa mainittujen suunnitelmien ja asiakirjojen mukaisesti. Automaatiourakka alistetaan pääurakkaan sivu-urakan alistamissopimuksella.,','Etelä-Karjalan koulutuskuntayhtymä','ANY',5,5,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056341','[\"45000000\"]','[\"urakka\", \"sivu\", \"suunnitelmien\", \"kuuluu\", \"saatettuna\", \"täysin\", \"valmiiksi\", \"toimintakuntoon\", \"asiakirjaluettelossa\", \"mainittujen\", \"asiakirjojen\", \"mukaisesti\", \"piikatu\", \"rakennuskohteen\", \"urakkaan\", \"alistetaan\", \"pääurakkaan\", \"urakan\", \"alistamissopimuksella\", \"putkiurakka\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/edusampo?id=626467&tpk=8e742e93-111d-4cc1-b78b-28e9c5cbff44\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056341\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56341\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Pääurakka/Rakennusurakka\", \"titleSv\": \"\", \"cpvCodes\": \"45000000\", \"currency\": null, \"deadline\": \"2026-09-28T09:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI1C5\", \"titleOther\": \"\", \"biodiversity\": true, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Rakennusurakoitsija on pääurakoitsija, joka vastaa työmaan johtovelvollisuuksista ja koordinoi rakentamista alistamissopimuksilla. \\nR