INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (510,'2026-056321','HILMA','RFP','OPEN','Ristipellontien porttaalin rakennusurakka','Ristipellontien porttaalin rakennusurakka Helsingin kaupungin rakentamispalveluliikelaitos, Stara pyytää kokonaisurakkatarjoustanne Ristipellontien/Vihdintie risteyksen porttaalin rakentamisesta suunnitelmien mukaisesti täysin valmiiksi käyttökuntoon. Aikataulu: 9-11/2026. Tarkempi aikataulu sovitaan myöhemmin. Antamalla kokonaishintaisen urakkatarjouksen urakoitsija vakuuttaa, että tarjoukseen sisältyvät kaikki urakan toteuttamisen kannalta oleelliset työvaiheet sekä työvaiheiden suorittamisessa tarvittavat materiaalit, koneet, laitteet ja työvoimat. Urakoitsijan on ennen tarjouksen antamista tutustuttava työkohteeseen ja sen työsuoritukselle tila ja muista rajoituksista. Tilaaja rakentaa samanaikaisesti risteysaluetta. Tilaaja on toteuttanut anturakaivannon aukaivuun ja paalutuksen. Tilaaja tekee kaivannon täyttötyöt. Urakkaan kuuluu anturarakenteen (2kpl) rakentaminen, porttaalin ja opasteiden hankinta ja asennus.,','Stara (Helsingin kaupungin rakentamispalveluliikelaitos)','ANY',2,4,NULL,NULL,35000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056321','[\"45000000\"]','[\"porttaalin\", \"ristipellontien\", \"tilaaja\", \"rakennusurakka\", \"helsingin\", \"kaupungin\", \"rakentamispalveluliikelaitos\", \"stara\", \"aikataulu\", \"pyytää\", \"kokonaisurakkatarjoustanne\", \"vihdintie\", \"risteyksen\", \"rakentamisesta\", \"suunnitelmien\", \"mukaisesti\", \"täysin\", \"valmiiksi\", \"käyttökuntoon\", \"tarkempi\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/s