INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (511,'2026-056296','HILMA','RFP','OPEN','VESIHUOLTOLAITOKSEN MAANRAKENNUS- JA KONEURAKOINNIN PUITEJÄRJESTELY','VESIHUOLTOLAITOKSEN MAANRAKENNUS- JA KONEURAKOINNIN PUITEJÄRJESTELY Lapuan kaupungin tekninen toimiala / vesihuoltolaitos pyytää maanrakennus- ja koneurakoinnin puitejärjestelyä rakennus- ja kunnossapitokaudelle 1.1.2027-31.12.2027 sekä mahdollisesti optiona vuodelle 2028. Tarjous pyydetään ryhmittäin seuraavista koneista: hydrauliset kaivinkoneet (tela ja pyörä) tarvittavista luokista 5kpl, pyörätraktorit 5kpl, kuorma-autot (myös nosturilla varustetut), loka-autot ym. Tarjouspyyntö sisältää myös tarjouspyynnön rakennusaputyöstä. Tarjoukset on annettava rakennus- ja kunnossapitokaudelle 1.1.2027-31.12.2027 sekä optiovuodelle 2028 siten, että annettu tarjoushinta on voimassa 1.1.2027-31.12.2028.Optio voidaan käyttää myös ryhmäkohtaisesti.,','Lapuan kaupunki','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056296','[\"45000000\"]','[\"maanrakennus\", \"koneurakoinnin\", \"lapuan\", \"vesihuoltolaitoksen\", \"puitejärjestely\", \"rakennus\", \"kunnossapitokaudelle\", \"autot\", \"kaupunki\", \"kaupungin\", \"tekninen\", \"toimiala\", \"vesihuoltolaitos\", \"pyytää\", \"puitejärjestelyä\", \"mahdollisesti\", \"optiona\", \"vuodelle\", \"tarjous\", \"pyydetään\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/public/procedure/36737/enotice/56296\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056296\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56296\", \"