INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (621,'2026-056337','HILMA','RFP','OPEN','Terveydenhuollon diagnostiset pienlaitteet','Tuomi Logistiikka Oy kilpailuttaa Terveydenhuollon diagnostiset pienlaitteet: verenpainemittarit, stetoskoopit, kuumemittarit, alkometrit, pulssioksimetrit sekä häkä- ja happimittarit Sisä- Suomen yhteistoiminta-alueelle; Kanta-Hämeen ja Pirkanmaan hyvinvointialueille (lukuun ottamatta Etelä-Pohjanmaan hyvinvointialuetta), Istekki Oy:lle, Oma Hämeen tukipalvelut Oy:lle, Tays Sydänkeskus Oy:lle sekä Coxa Oy:lle. Sopimuskauden pituus on kaksi (2) vuotta. Sopimusta voidaan jatkaa varsinaisen sopimuskauden jälkeen toistaiseksi voimassaolevana. Sopimuksen arvioitu alkamisajankohta on marraskuu 2026. Tällä hankintasopimuksella hankintoja tekevät Tuomi Logistiikka Oy sekä tavarantilaajat Pirkanmaan hyvinvointialue, Kanta-hämeen hyvinvointialue, Istekki Oy, Oma Hämeen tukipalvelut Oy, Tays Sydänkeskus Oy ja Coxa Oy. Tilaaja voi tällä hankintasopimuksella tehdä tavarantilauksia itselleen ja hankintalain mukaisille sidosyksiköilleen. Hankinta on jaettu neljääntoista (14) osa-alueeseen. 1.Digitaalinen, automaattinen, oskillometrinen non-invasiivinen verenpainemittari ammattikäyttöön ja yhteensopivat mansetit, aikuinen 2.Digitaalinen, automaattinen, oskillometrinen non-invasiivinen verenpainemittari ammattikäyttöön ja yhteensopivat mansetit, 3-18- vuotias lapsi/nuori 3.Non-invasiivinen mekaaninen aneroidi verenpainemittari ja yhteensopiva mansetti 4. Stetoskoopit terveydenhuollon ammattikäyttöön 5. Digitaalinen korvakuumemittari ja yhteensopivat mittauspään kertakäyttösuojat, ammattikäyttö 6. Digitaalinen korvakuumemittari ammattikäyttöön, hypoterminen potilas 7. Digitaalinen, kosketusvapaa otsakuumemittari ammattikäyttöön 8. Digitaalinen kainalo-/ per -os kuumemittari 9. Korvakuumemittarin laitekohtaiset suojukset 10. Alkometri ja yhteensopiva suukappale, vaativaan ammattikäyttöön 11. Sormisaturaatiomittari/ sormipulssioksimetri 12. Kannettava saturaatiomittari/oksimetri (ns. sängynvierussaturaatiomittari/oksimetri)- lapsi (≤18-v.) 13. Kannettava saturaatiomittari/oksimetri (ns. sängynvierussaturaatiomittari/oksimetri), aikuinen 14. Yhden kaasun häkä- (CO-) ja happi (O2-) mittari Tarjoajan on mahdollista tehdä tarjous yhteen tai useampaan osa-alueeseen. Hankinnan arvioitu kokonaisarvo neljälle (4) vuodelle on 1 500 000 euroa. Tarjouspyynnöllä ilmoitetut vuoden kulutusmäärät ovat arvioita ja voivat vaihdella sopimuskauden aikana. Määrät perustuvat aikaisempaan yhden vuoden kulutustietoon. Ilmoitettu tuotteiden vuosihankintamäärä voi vaihdella, määrät ovat suuntaa-antavia eikä tilaaja sitoudu mihinkään tiettyihin tilausmääriin., Verenpainemittarit ja stetoskoopit Osa yksi (1) sisältää osa-alueet 1-4 1. Digitaalinen, automaattinen, oskillometrinen non-invasiivinen verenpainemittari ammattikäyttöön ja yhteensopivat mansetit, aikuinen 2. Digitaalinen, automaattinen, oskillometrinen non-invasiivinen verenpainemittari ammattikäyttöön ja yhteensopivat mansetit, 3-18- vuotias lapsi/nuori 3. Non-invasiivinen mekaaninen aneroidi verenpainemittari ja yhteensopiva mansetti 4. Stetoskoopit terveydenhuollon ammattikäyttöön, Kuumemittarit Osa kaksi (2) sisältää osa-alueet 5-9. 5. Digitaalinen korvakuumemittari ja yhteensopivat mittauspään kertakäyttösuojat, ammattikäyttö 6. Digitaalinen korvakuumemittari ammattikäyttöön, hypoterminen potilas 7. Digitaalinen, kosketusvapaa otsakuumemittari ammattikäyttöön 8. Digitaalinen kainalo- / per os -kuumemittari 9. Korvakuumemittarin laitekohtaiset suojukset, Alkometrit Osa kolme (3) sisältää osa-alueen 10: Alkometri ja yhteensopiva suukappale, vaativaan ammattikäyttöön., Saturaatiomittarit Osa neljä (4) sisältää osa-alueet 11-13. 11. Sormisaturaatiomittari/ sormipulssioksimetri 12. Kannettava saturaatiomittari/oksimetri (ns. sängynvierussaturaatiomittari/oksimetri- lapsi (≤18-v.) 13. Kannettava saturaatiomittari/oksimetri (ns. sängynvierussaturaatiomittari/oksimetri), aikuinen, Häkä- ja happimittarit Osa viisi (5) sisältää osa-alueen 14: Yhden kaasun häkä- (CO-) ja happi (O2-) mittari.,','Tuomi Logistiikka Oy','ANY',3,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056337','[\"33000000\"]','[\"digitaalinen\", \"ammattikäyttöön\", \"oksimetri\", \"invasiivinen\", \"verenpainemittari\", \"yhteensopivat\", \"sisältää\", \"terveydenhuollon\", \"tuomi\", \"logistiikka\", \"stetoskoopit\", \"häkä\", \"hämeen\", \"automaattinen\", \"oskillometrinen\", \"mansetit\", \"aikuinen\", \"lapsi\", \"yhteensopiva\", \"korvakuumemittari\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/tuomilogistiikka?id=614401&tpk=60665734-0a6d-461f-b22c-a8601116a8da\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056337\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56337\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Verenpainemittarit ja stetoskoopit\", \"titleSv\": \"\", \"cpvCodes\": \"33000000\", \"currency\": null, \"deadline\": \"2026-10-07T09:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"\", \"titleOther\": \"\", \"biodiversity\": true, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"Osa yksi (1) sisältää osa-alueet 1-4\\n1. Digitaalinen, automaattinen, oskillometrinen non-invasiivinen verenpainemittari ammattikäyttöön ja yhteensopivat mansetit, aikuinen\\n2. Digitaalinen, automaattinen, oskillometrinen non-invasiivinen verenpainemittari ammattikäyttöön ja yhteensopivat mansetit, 3-18- vuotias lapsi/nuori\\n3. Non-invasiivinen mekaaninen aneroidi verenpainemittari ja yhteensopiv