INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (624,'2026-056331','HILMA','OTHER','OPEN','Carbonization and activation unit','Carbonization and activation unit The object of the procurement is a carbonization and activation unit. Continuously fed electrically heated rotary kiln carbonization and activation unit built into a sea container. The procurement will be carried out as a direct award in accordance with 40 article of the Finnish Public Procurement Act. According to the 40 § section 2(1) of the Act on Public Contracts (1397/2016), \"no requests to participate or tenders, or suitable requests to participate or tenders have been received in response to an open or restricted procedure; it shall be a further condition that no essential change has occurred in the terms and conditions of the original call for tenders\". VTT has previously organized a tender process \"Carbonization and activation unit, Reg. no 45/206/2025\". The tender process was based on the open procedure applicable to contracts that exceed the EU procurement threshold. By the deadline of submitting the tenders, no suitable tenders were received. VTT entered into direct procurement negotiations on the basis of the original call for tenders. Iin Konepaja Oy submitted a tender that meets the requirements set in the original call for tenders. The procurement will be carried out as a direct award to the selected supplier on the grounds that no suitable tenders were received under the original open procedure, and that no essential change has occurred in the terms and conditions of the original call for tenders.,','VTT Technical Research Centre of Finland Ltd','ANY',1,13,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056331','[\"38300000\"]','[\"tenders\", \"procurement\", \"carbonization\", \"activation\", \"unit\", \"original\", \"call\", \"direct\", \"suitable\", \"received\", \"open\", \"procedure\", \"tender\", \"finland\", \"into\", \"carried\", \"award\", \"public\", \"contracts\", \"requests\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056331\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56331\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"Carbonization and activation unit\", \"titleFi\": \"\", \"titleSv\": \"\", \"cpvCodes\": \"38300000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": false, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": \"The object of the procurement is a carbonization and activation unit. Continuously fed electrically heated rotary kiln carbonization and activation unit built into a sea container. \\n\\nThe procurement will be carried out as a direct award in accordance with 40 article of the Finnish Public Procurement Act. According to the 40 § section 2(1) of the Act on Public Contracts (1397/2016), \\\"no requests to participate or tenders, or suitable requests to participate or tenders have been received in response to an open or restricted procedure; it shall be a further condition that no essential change has occurred in the terms and conditions of the original call for tenders\\\".\\n\\nVTT has previously organized a tender process \\\"Carbonization and activation unit, Reg. no 45/206/2025\\\". The tender process was based on the open procedure applicable to contracts that exceed the EU procurement threshold. By the deadline of submitting the tenders, no suitable tenders were received. VTT entered into direct procurement negotiations on the basis of the original call for tenders. Iin Konepaja Oy submitted a tender that meets the require