INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (632,'2026-056318','HILMA','OTHER','OPEN','Pumppaamojen sekä niiden korjaus- ja huoltotöiden hankinta','Pumppaamojen sekä niiden korjaus- ja huoltotöiden hankinta Espoon kaupunki (myöhemmin myös Tilaaja) pyytää tarjouksia Espoon kaupungin sekä Espoon kaupungin nimettyjen konserniyhtiöiden hallinnoimien kiinteistöjen kiinteistöpumppaamojen huolloista, korjauksista ja uusimisista. Hankintaan sisältyy myös rasvan- ja öljynerotuskaivojen antureiden ja hälyttimien korjaukset ja uusimiset, sekä pienpuhdistamoiden huollot ja korjaukset. Kiinteistöpumppaamoja on noin 140 kohteessa. Sopimuskausi on neljä (4) vuotta. Kilpailutuksen perusteella muodostetaan puitejärjestely, johon valitaan enintään kolme (3) Palveluntuottajaa ja yksi (1) varapalveluntuottaja. Tarkempi kuvaus puitejärjestelystä ja hankinnan sisällöstä on tarjouspyynnön liitteellä 1. \"Hankinnan kohteen kuvaus\". Hankinnan ennakoitu kokonaisarvo ilman arvonlisäveroa (eli kun alv. 0 %) on 1 000 000 euroa. Kokonaisarvo jakautuu eri hankintayksiköiden välillä seuraavasti: - Espoon kaupunki: 400 000 euroa. - Espoon Elä ja Asu Oy: 20 000 euroa. - Espoon Asunnot Oy: 400 000 euroa. - Kiinteistö Oy Espoon keskuskeittiö: 50 000 euroa. - Espoo Catering: 50 000 euroa. - Kiinteistö Oy Matinkylän uimahalli: 50 000 euroa. - Kiinteistö Oy Opinmäen Kampus: 10 000 euroa. - Weegee Oy: 10 000 euroa. - Kiinteistö Oy Tapiolan Louhi: 10 000 euroa.,','Espoon kaupunki','ANY',1,4,NULL,NULL,1000000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056318','[\"50000000\", \"42120000\", \"45232152\", \"90000000\"]','[\"euroa\", \"espoon\", \"kiinteistö\", \"kaupunki\", \"hankinnan\", \"pumppaamojen\", \"niiden\", \"korjaus\", \"huoltotöiden\", \"hankinta\", \"kaupungin\", \"korjaukset\", \"kuvaus\", \"kokonaisarvo\", \"myöhemmin\", \"tilaaja\", \"pyytää\", \"tarjouksia\", \"nimettyjen\", \"konserniyhtiöiden\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056318\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56318\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Pumppaamojen sekä niiden korjaus- ja huoltotöiden hankinta\", \"titleSv\": \"\", \"cpvCodes\": \"50000000 42120000 45232152 90000000\", \"currency\": \"EUR\", \"deadline\": null, \"lowCarbon\": false, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Espoon kaupunki (myöhemmin myös Tilaaja) pyytää tarjouksia Espoon kaupungin sekä Espoon kaupungin nimettyjen konserniyhtiöiden hallinnoimien kiinteistöjen kiinteistöpumppaamojen huolloista, korjauksista ja uusimisista. Hankintaan sisältyy myös rasvan- ja öljynerotuskaivojen antureiden ja hälyttimien korjaukset ja uusimiset, sekä pienpuhdistamoiden huollot ja korjaukset. Kiinteistöpumppaamoja on noin 140 kohteessa.  \\n\\nSopimuskausi on neljä (4) vuotta.\\n\\nKilpailutuksen perusteella muodostetaan puitejärjestely, johon valitaan enintään kolme (3) Palveluntuottajaa ja yksi (1) varapalveluntuottaja. Tarkempi kuvaus puitejärjestelystä ja hankinnan sisällöstä on tarjouspyynnön liitteellä 1. \\\"Hankinnan kohteen kuvaus\\\".\\n\\nHankinnan ennakoitu kokonaisarvo ilman arvonlisäveroa (eli kun alv. 0 %) on 1 000 000 euroa. \\nKokonaisarvo jakautuu eri hankintayksiköiden välillä seuraavasti:\\n- Espoon kaupunki: 400 000 euroa. \\n- Espoon Elä ja Asu Oy: 20 000 euroa.\\n- Espoon Asunnot Oy: 400 000 euroa.\\n- Kiinteistö Oy Espoon keskuskeittiö: 50 000 euroa.\\n- Espoo Catering: 50 000 euroa.\\n- Kiinteistö Oy Matinkylän uimahalli: 50 000 euroa.\\n- K