INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (633,'2026-056317','HILMA','RFP','OPEN','Köp av platser inom småbarnspedagogik och förskoleundervisning','Pargas stad köper platser inom småbarnspedagogik och vid behov förskoleundervisning med kompletterande småbarnspedagogik. Upphandlingen gäller totalt 119 kalkylmässiga platser. Antalet platser är kalkylmässigt eftersom beställaren behöver flexibilitet i förhållande till barnens ålder, närvarotider och förskoleandel. Anbudsgivaren ska lämna anbud för både Del 1: Daghem A och Del 2: Daghem B. Anbud som inte omfattar båda delarna kommer att förkastas som anbudsstridiga. En serviceproducent kan, beroende på anbudsgivarens angivna kapacitet och tilldelningsmodellen i denna anbudsförfrågan, tilldelas en eller båda delarna. Avtalsperioden planeras att börja 1.8.2027 och är i kraft till 31.7.2029 med möjlighet till 1 + 1 optionsår. Servicen ska finnas i centrum av Pargas kommunområde. Servicen produceras i huvudsak på svenska. Serviceproducenten ska säkerställa att verksamheten kan genomföras på det språk eller de språk som anges i anbudsförfrågan. Om beställaren förutsätter tvåspråkig verksamhet ska serviceproducenten ha tillräckliga personalresurser och tillräcklig språkkompetens för detta. Den språkliga kompetensen ska vara tillräcklig för att daghemmet i praktiken ska kunna erbjuda den tvåspråkiga verksamhet som beställaren förutsätter. Om anbudsförfrågan innehåller optioner, exempelvis assistent, speciallärare inom småbarnspedagogik eller andra tilläggsresurser, ska serviceproducenten genomföra dessa i den omfattning som beställaren beslutar och parterna avtalar om. Behovet och omfattningen av sådana tjänster kan utvärderas inför varje verksamhetsår, eftersom barnens stödbehov kan variera. Pris för eventuella optioner efterfrågas separat och påverkar inte jämförelsepriset, om inte annat anges i anbudsförfrågan. Upphandlingen beskrivs noggrannare i bilaga 1 Servicebeskrivning., Del 1: Daghem A (56 kalkylmässiga platser) Daghem A omfattar 56 kalkylmässiga platser för småbarnspedagogik samt vid behov förskoleundervisning med kompletterande småbarnspedagogik. Antalet platser är definierat som kalkylmässiga platser eftersom beställaren inte på förhand kan veta i vilken ålder barnen är., Del 2: Daghem B ( 63 kalkylmässiga platser) Daghem B omfattar 63 kalkylmässiga platser för småbarnspedagogik samt vid behov förskoleundervisning med kompletterande småbarnspedagogik. Antalet platser är definierat som kalkylmässiga platser eftersom beställaren inte på förhand kan veta i vilken ålder barnen är.,','Pargas stad','ANY',10,1,NULL,NULL,7500000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056317','[\"85312110\", \"80110000\"]','[\"platser\", \"småbarnspedagogik\", \"kalkylmässiga\", \"beställaren\", \"daghem\", \"inte\", \"förskoleundervisning\", \"eftersom\", \"anbudsförfrågan\", \"inom\", \"pargas\", \"behov\", \"kompletterande\", \"antalet\", \"till\", \"ålder\", \"omfattar\", \"eller\", \"serviceproducenten\", \"stad\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/pargas?id=623266&tpk=31007069-c131-48f0-bb92-a2a90788d246\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056317\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56317\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"\", \"titleSv\": \"Del 1: Daghem A (56 kalkylmässiga platser)\", \"cpvCodes\": \"85312110 80110000\", \"currency\": null, \"deadline\": \"2026-10-05T09:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI1C1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfCond