INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (639,'2026-056302','HILMA','RFP','OPEN','Tietomallikoordinointi, rakennusten inventointimittaus sekä -mallinnus ja visualisointipalvelut','Vaasan kaupunki / Talotoimi -liikelaitos pyytää tarjouksia rakennushankkeiden tietomallikoordinointi, rakennushankkeen inventointimittaus- ja mallinnuspalvelu sekä rakennushankkeen visualisointipalvelusta. Puitesopimuksen piiriin kuuluvien toimeksiantojen kohteina ovat pääasiassa Talotoimi –liikelaitoksen hallinnoimien Vaasan kaupungin omistamien julkisiin rakennuksiin (mm, kasvatuksen ja koulutuksen, kulttuuri-, liikunta- ja nuorisotoimen rakennukset sekä toimisto- ja liikerakennukset) kohdistuvien peruskorjaus- ja uudisrakennushankkeiden tietomallikoordinointi, inventointimittaus- ja mallinnuspalvelu sekä visualisointipalvelu. Jokaiseen osa-alueeseen valitaan enintään kolme (3) sopimuskumppania etusijajärjestyksellä. Toimeksiantojen tehtäväkuvaus ja toiminta sopimuskaudella on kuvattu tarjouspyynnön Liitteissä 1-3. Sopimuskausi on kolme (3) vuotta. Sopimuskausi alkaa sopimuksen allekirjoituksesta ja päättyy kolmen vuoden päästä sopimuksen allekirjoituksesta. Tilaaja varaa oikeuden jatkaa sopimusta yhdellä (1) optiovuodella varsinaisen sopimuskauden päättämisestä lukien. Optiovuoden käytöstä ilmoitetaan viimeistään kolme kuukautta ennen varsinaisen sopimuskauden päättymistä., Rakennushankkeiden tietomallikoordinointi Rakennushankkeiden tietomallikoordinointi. Osa-aluetta koskevat työt tilataan tarjouskilpailun tuloksen perusteella määritellyssä etusijajärjestyksessä. Pääsääntöisesti toimeksiannot suoritetaan puitesopimuksen mukaisilla hinnoilla aikapalkkioon perustuvalla korvauksella. Palveluntuottaja laatii Tilaajalle työmääräarvion, jonka tilaaja hyväksyy tai hylkää. Tilaaja pidättää oikeuden kilpailuttaa toimeksiannot joko puitesopimuskumppanien välisellä minikilpailutuksella tai julkisena hankintana avointa menettelyä käyttäen. Tietomallikoordinaattori ei voi toimia samanaikaisesti suunnittelijana samassa hankkeessa., Rakennushankkeiden inventointimittaus- ja mallinnuspalvelut Rakennushankkeiden inventointimittaus- ja mallinnuspalvelut. Osa-aluetta koskevat työt tilataan tarjouskilpailun tuloksen perusteella määritellyssä etusijajärjestyksessä. Pääsääntöisesti toimeksiannot suoritetaan puitesopimuksen mukaisilla hinnoilla aikapalkkioon perustuvalla korvauksella. Palveluntuottaja laatii Tilaajalle työmääräarvion, jonka tilaaja hyväksyy tai hylkää. Tilaaja pidättää oikeuden kilpailuttaa toimeksiannot joko puitesopimuskumppanien välisellä minikilpailutuksella tai julkisena hankintana avointa menettelyä käyttäen. Inventointimallintaja ei voi samanaikaisesti toimia Suunnittelijana kyseisessä hankkeessa., Rakennushankkeiden visualisointipalvelut Rakennushankkeiden visualisointipalvelut. Osa-aluetta koskevat työt tilataan tarjouskilpailun tuloksen perusteella määritellyssä etusijajärjestyksessä. Pääsääntöisesti toimeksiannot suoritetaan puitesopimuksen mukaisilla hinnoilla aikapalkkioon perustuvalla korvauksella. Palveluntuottaja laatii Tilaajalle työmääräarvion, jonka tilaaja hyväksyy tai hylkää. Tilaaja pidättää oikeuden kilpailuttaa toimeksiannot joko puitesopimuskumppanien välisellä minikilpailutuksella tai julkisena hankintana avointa menettelyä käyttäen. Visualisoija ei voi toimia samanaikaisesti suunnittelijana samassa hankkeessa.,','Vaasan Talotoimi -liikelaitos','ANY',1,13,NULL,NULL,600000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056302','[\"71000000\"]','[\"rakennushankkeiden\", \"tilaaja\", \"toimeksiannot\", \"tietomallikoordinointi\", \"inventointimittaus\", \"