INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (645,'2026-056294','HILMA','OTHER','OPEN','Mäntymäen sairaalan kahvilapalvelu','Mäntymäen sairaalan kahvilapalvelu Käyttöoikeussopimuksen kohteena on Mäntymäen sairaalan kahvilapalvelut. Sopimusta on tarpeen jatkaa uuden kilpailutuksen ajaksi siihen asti että uusi kilpailutus saadaan toteutettua ja uudet sopimukset astuvat voimaan, viimeistään vuoden 2027 loppuun mennessä. Hankinnan kohteena on tarjouspyynnössä ja sen liitteissä mainittu palvelu tarjouspyynnössä ja sen liitteissä määritetyllä tavalla.,','Varsinais-Suomen hyvinvointialue','ANY',3,1,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056294','[\"55000000\"]','[\"mäntymäen\", \"sairaalan\", \"kahvilapalvelu\", \"kohteena\", \"tarjouspyynnössä\", \"liitteissä\", \"käyttöoikeussopimuksen\", \"kahvilapalvelut\", \"sopimusta\", \"tarpeen\", \"jatkaa\", \"uuden\", \"kilpailutuksen\", \"ajaksi\", \"siihen\", \"asti\", \"uusi\", \"kilpailutus\", \"saadaan\", \"toteutettua\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056294\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56294\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Mäntymäen sairaalan kahvilapalvelu\", \"titleSv\": \"\", \"cpvCodes\": \"55000000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": null, \"nutsCodes\": \"FI1C1\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Käyttöoikeussopimuksen kohteena on Mäntymäen sairaalan kahvilapalvelut. Sopimusta on tarpeen jatkaa uuden kilpailutuksen ajaksi si