INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (650,'2026-056286','HILMA','OTHER','OPEN','Jälki-ilmoitus suorahankinnasta Philips potilasvalvontajärjestelmään yhteensopivat potilasvalvontamonitorit','Jälki-ilmoitus suorahankinnasta Philips potilasvalvontajärjestelmään yhteensopivat potilasvalvontamonitorit Tämä on jälki-ilmoitus. hankinnasta on tehty aiemmin ennakkoilmoitus suorahankinnasta. Hankinnan kohteena on Philipsin potilasvalvontajärjestelmään yhteensopivat X3 potilasvalvontamonitorit sekä laitesidonnaiset lisätarvikkeet Etelä-Karjalan keskussairaalan. Potilasvalvontamonitorit tullaan liittämään olemassa olevaan keskusvalvontajärjestelmään. Etelä-Karjalan keskussairaalassa käytössä olevien X2 potilasvalvontamonitorien laitetuki on päättynyt. Sopimus on voimassa ajalla 3.9.2026–31.12.2027.,','Etelä-Karjalan hyvinvointialue','ANY',3,11,NULL,NULL,300000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056286','[\"33100000\"]','[\"potilasvalvontamonitorit\", \"etelä\", \"karjalan\", \"jälki\", \"ilmoitus\", \"suorahankinnasta\", \"potilasvalvontajärjestelmään\", \"yhteensopivat\", \"philips\", \"hyvinvointialue\", \"tämä\", \"hankinnasta\", \"tehty\", \"aiemmin\", \"ennakkoilmoitus\", \"hankinnan\", \"kohteena\", \"philipsin\", \"laitesidonnaiset\", \"lisätarvikkeet\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056286\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56286\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Jälki-ilmoitus suorahankinnasta Philips potilasvalvontajärjestelmään yhteensopivat potilasvalvontamonitorit\", \"titleSv\": \"\