INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (654,'2026-056281','HILMA','OTHER','OPEN','JÄLKI-ILMOITUS Oulun yliopiston normaalikoulun uudisrakennuksen sähköurakka','JÄLKI-ILMOITUS Oulun yliopiston normaalikoulun uudisrakennuksen sähköurakka JÄLKI-ILMOITUS Hanke toteutetaan jaettuna urakkana, jossa rakennusurakoitsija toimii kohteen päätoteuttajana ja muut urakoitsijat alistetaan rakennusurakoitsijalle. Hankkeen laajuus on n. 9600 brm2. Sähköurakka sisältää myös AV-kaapeloinnit suunnitelmien mukaisesti. Tavoiteaikataulun mukaisesti rakennustekniset työt voidaan käynnistää elokuun alussa 2026 ja urakan tulee olla valmis ja luovutettavissa tilaajalle toukokuussa 2028. Tarkempi urakka-aikataulu on esitetty urakkaohjelmassa. Hanketta on kuvattu tarkemmin tarjouspyynnön liiteasiakirjoissa, jotka ovat ladattavissa BEM-linkistä.,','Oulun yliopisto','ANY',6,5,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056281','[\"45214200\"]','[\"oulun\", \"jälki\", \"ilmoitus\", \"sähköurakka\", \"yliopiston\", \"normaalikoulun\", \"uudisrakennuksen\", \"mukaisesti\", \"yliopisto\", \"hanke\", \"toteutetaan\", \"jaettuna\", \"urakkana\", \"jossa\", \"rakennusurakoitsija\", \"toimii\", \"kohteen\", \"päätoteuttajana\", \"muut\", \"urakoitsijat\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056281\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56281\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"JÄLKI-ILMOITUS Oulun yliopiston normaalikoulun uudisrakennuksen sähköurakka\", \"titleSv\": \"\", \"cpvCodes\": \"45214200\", \"currency\": null, \"deadline\":