INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (657,'2026-056276','HILMA','RFP','OPEN','Lääkärityövoiman vuokraus lastensuojelun laitoshoidon palveluihin','Hankinnan kohteena on lääkärityövoiman vuokraus lastensuojelun laitoshoidon palveluihin. Hankinta jakautuu seuraaviin osa-alueisiin: 1. Päihde- ja mielenterveyspalvelut 2. Yleislääkäripalvelut 3. Neuropsykiatrian ja kehitysvammalääketieteen palvelut Tilaaja ei sitoudu mihinkään hankintamääriin, vaan palvelua tilataan tarpeen mukaan. Hankittavien palvelujen tarkat sisällöt ja vaatimukset vuokrattaville lääkäreille on esitetty tarjouspyynnön liitteenä olevassa palvelukuvauksessa. Tarjoaja voi jättää yhdellä tarjouksella tarjouksen joko yhdestä tai useammasta tarjouspyynnön osa-alueesta. Tarjousvertailu tehdään osa-alueittain. Tarjousten vertailuperusteena on halvin hinta. Vertailuun otetaan mukaan kaikki ne tarjoajat, jotka täyttävät tarjouspyynnöllä asetetut soveltuvuusvaatimukset ja muut pakolliset vaatimukset ja joiden tarjous on tarjouspyynnönmukainen. Hankinnassa perustetaan puitejärjestely. Puitejärjestelyyn valitaan osa-alueittain Tilaajan tarpeen täyttävä määrä palveluntuottajia ja heidät asetetaan osa-alueittain halvimman hinnan mukaisesti etusijajärjestykseen. Tilaukset tehdään pääsääntöisesti puitejärjestelyn etusijajärjestyksen mukaisesti eli tilaus tehdään aina ensin etusijajärjestyksen ensimmäiseltä palveluntuottajalta. Mikäli kyseisellä palveluntuottajalla ei ole tarjota vaatimukset täyttävää lääkäriä kohtuullisen ajan sisällä, siirrytään puitejärjestelyssä seuraavana olevaan palveluntuottajaan. Tilaaja määrittelee tilauksessaan, mikä on kyseisen tilauksen osalta kohtuullinen aika. Etusijajärjestyksestä on mahdollista poiketa asiakaskohtaisen tarpeen vuoksi, jolloin tilaaja valitsee puitejärjestelyn palveluntuottajista sen palveluntuottajan, jonka tarjoama lääkäri vastaa asiakkaan tarpeita parhaiten. Etusijajärjestyksestä on mahdollista poiketa myös kiiretilanteen vuoksi, jolloin tilaaja valitsee puitejärjestelyn palveluntuottajista sen palveluntuottajan, joka pystyy toimittamaan tilaajalle vaatimukset täyttävän lääkärin nopeimmalla aikataululla / lyhimmällä vasteajalla., Päihde- ja mielenterveyspalvelut Palvelu on kuvattu liitteessä Palvelukuvaus., Yleislääkäripalvelut Palvelu on kuvattu liitteessä Palvelukuvaus., Neuropsykiatrian ja kehitysvammalääketieteen palvelut Palvelu on kuvattu liitteessä Palvelukuvaus.,','Helsingin kaupungin sosiaali-, terveys- ja pelastustoimiala','ANY',3,4,NULL,NULL,2000000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056276','[\"85121000\"]','[\"tilaaja\", \"vaatimukset\", \"tarpeen\", \"tehdään\", \"alueittain\", \"puitejärjestelyn\", \"palvelu\", \"kuvattu\", \"liitteessä\", \"palvelukuvaus\", \"lääkärityövoiman\", \"vuokraus\", \"lastensuojelun\", \"laitoshoidon\", \"palveluihin\", \"päihde\", \"mielenterveyspalvelut\", \"yleislääkäripalvelut\", \"neuropsykiatrian\", \"kehitysvammalääketieteen\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/helsinki?id=614312&tpk=95d00f5a-911d-4a21-a731-66c7c3e3e92d\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056276\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56276\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Päihde- ja mielenterveyspalvelut\", \"titleSv\": \"\", \"cpvCodes\": \"85121000\", \"currency\": null, \"deadline\": \"2026-10-05T07:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Palvelu on kuvattu l