INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (658,'2026-056275','HILMA','RFP','OPEN','Isolahti Gerbyn päiväkodin vuokrapäiväkotihanke','Isolahti Gerbyn päiväkodin vuokrapäiväkotihanke Vaasan kaupunki (jäljempänä ”Tilaaja”) pyytää avoimeen hankintamenettelyyn perustuen tarjousta Isolahti Gerbyn -vuokrapäiväkotihankkeen toteuttamisesta tarjouspyynnön ja sen liitteiden mukaisesti. Hankinnassa on kyse Vaasan kaupungin Isolahti Gerby päiväkodin vuokrapäiväkotihankkeesta. Hanke on vuokramallilla toteutettava päiväkoti, jonka paikkamäärä on 150 lapselle. Päiväkodissa on tilat 8 ryhmälle sekä lisäksi henkilökuntaa 40–45 henkilöä. Hankinta kattaa kohderakennuksen ylläpito- ja käyttäjäpalvelut sovittavan vuokrajakson ajan. Hankkeen toteuttajan vastuulla on rakennuksen käytettävyys ja olosuhteet suunnitellulle vuokra-ajalle. Tavoitteena on allekirjoittaa vuokrasopimus vuoden 2027 alussa ja aloittaa rakennustyöt keväällä 2027. Kalustaminen käynnistyy heinäkuussa 2028. Vuokrakohteen tulee olla valmiina luovutettavaksi vuokralaisen hallintaan ja käyttöön viimeistään 30.06.2028, jolloin vuokrakausi alkaa. Hankkeen toteuttaja vuokraa päiväkodin tontin kaupungilta. Vuokrakohde on vuokranantajan rakentama ja omistama lasten päiväkoti. Hankkeen hyötyala on alustavan tilaohjelman mukaisesti n. 2010,5 hym2. (Ei sisällä seinärakenteita.),','Vaasan kaupunki','ANY',2,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056275','[\"45000000\", \"70310000\"]','[\"isolahti\", \"päiväkodin\", \"vaasan\", \"gerbyn\", \"kaupunki\", \"hankkeen\", \"vuokrapäiväkotihanke\", \"mukaisesti\", \"päiväkoti\", \"jäljempänä\", \"tilaaja\", \"pyytää\", \"avoimeen\", \"hankintamenettelyyn\", \"perustuen\", \"tarjousta\", \"vuokrapäiväkotihankkeen\", \"toteuttamisesta\", \"tarjouspyynnön\", \"liitteiden\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/teese?id=619657&tpk=e18f03af-0af6-443c-8010-4f11f35d7951\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056275\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56275\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Isolahti Gerbyn päiväkodin vuokrapäiväkotihanke\", \"titleSv\": \"\", \"cpvCodes\": \"45000000 70310000\", \"currency\": null, \"deadline\": \"2026-10-16T08:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI19A\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Vaasan kaupunki (jäljempänä ”Tilaaja”) pyytää avoimeen hankintamenettelyyn perustuen tarjousta Isolahti Gerbyn -vuokrapäiväkotihankkeen toteuttamisesta tarjouspyynnön ja sen liitteiden mukaisesti.\\n\\nHankinnassa on kyse Vaasan kaupungin Isolahti Gerby päiväkodin vuokrapäiväkotihankkeesta.\\n\\nHanke on vuokramallilla toteutettava päiväkoti, jonka paikkamäärä on 150 lapselle. Päiväkodissa on tilat 8 ryhmälle sekä lisäksi henkilökuntaa 40–45 henkilöä. Hankinta kattaa kohderakennuksen ylläpito- ja käyttäjäpalvelut sovittavan vuokrajakson ajan. Hankkeen toteuttajan vastuulla on rakennuksen käytettävyys ja olosuhteet suunnitellulle vuokra-ajalle.\\n\\nTavoitteena on allekirjoittaa vuokrasopimus vuoden 2027 alussa ja aloittaa rakennustyöt keväällä 2027. Kalustaminen käynnistyy heinäkuussa 2028. Vuokrakohteen tulee olla valmiina luovutettavaksi vuokralaisen hallintaan ja käyttöön viimeistään 30.06.2028, jolloin vuokrakausi alkaa.\\n\\nHankkeen toteuttaja vuokraa päiväkodin tontin kaupungilta. Vuokrakohde on vuokranantajan rakentama ja omistama lasten päiväkoti.\\n\\nHankkeen hyötyala on alustavan tilaohjelman mukaisesti n. 2010,5 hym2.  (Ei sisällä seinärakenteita.)\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-10-16T08:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"works\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": true, \"lotResultTotalAmount\": null, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": false, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"16\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"Isolahti Gerbyn päiväkodin vuokrapäiväkotihanke\", \"titleSv\": \"\", \"cpvCodes\": \"45000000 70310000\", \"currency\": null, \"deadline\": \"2026-10-16T08:00:00Z\", \"eFormsId\": \"a6eba072-878b-40db-ae0d-23570f2b4806\", \"isEForms\": true, \"mainType\": \"ContractNotices\", \"noticeId\": 56275, \"lowCarbon\": true, \"nutsCodes\": \"FI19A\", \"titleOther\": \"\", \"isCancelled\": false, \"procedureId\": 36012, \"biodiversity\": false, \"dateModified\": \"2026-09-06T06:05:06.965Z\", \"fullEFormsId\": \"a6eba072-878b-40db-ae0d-23570f2b4806-01\", \"notic