INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (662,'2026-056271','HILMA','OTHER','OPEN','Lohjan kaupungin tilausajot ajalla 15.9.-19.9.2026, sisäinen kilpailutus (DPS 2025-2027))','Lohjan kaupunki pyysi tarjouksia tilausajoista ajalla 15.9.-19.9.2026 yhteensä 4 kohteeseen. Tarjouskilpailu käytiin Lohjan kaupungin perustaman dynaamisen hankintajärjestelmän Tilausajot 2025-2027 sisäisenä kilpailutuksena., Kohde 1 tiistai 15.9.2026 Mäntynummen yhtenäiskoulu Reitti klo 09:05 Mäntynummen yhtenäiskoulu (Rantapuisto 39, 08100 Lohja) - Fiskars village (Peltorivi 1, Raasepori). klo 13:00 Fiskars village (Peltorivi 1, Raasepori) - Mäntynummen yhtenäiskoulu (Rantapuisto 39, 08100 Lohja). Auton koko vähintään 27 paikkainen linja-auto, Kohde 2 keskiviikko 16.9.2026 Reitti klo 08:15 Kaupungintalo Monkola (Karstuntie 4, 08100 Lohja) - Kuntatalo (Toinen linja 14, 00530 Helsinki). klo 15:00 Kuntatalo (Toinen linja 14, 00530 Helsinki) - Kaupungintalo Monkola (Karstuntie 4, 08100 Lohja). Auton koko vähintään 35 paikkainen linja-auto, Kohde 3 lauantai 19.9.2026 Reitti Kiertoajelua Lohja-Nummela-Rauma-Nummela-Lohja. Bussin ajomatka n. 460km + Raumalla kiertoajelua. klo 8:30 Lähtö Lohjan kirkkokenttä (Sibeliuksenkatu 1, 08100 Lohja) - n.klo 8:50 Nummelan linja-autoasema - Matka jatkuu Raumalle. Paluu Raumalta, Nummela n.klo 20:00 ja Lohjalla n.klo 20: 20 Auton koko vähintään 40 paikkainen linja-auto, Kohde 4 lauantai 19.9.2026 Reitti klo 13:00 Virkkalan linja-auto asema (08700 Lohja) - Linnanmäki (Tivolikuja 5, 00510 Helsinki). Bussi lähtee Virkkalasta ja pysähtyy matkalla seuraavilla pysäkeillä: Ojamo P, Keskusaukio I, Vesitorni P, Muijala E18 I. Paluukyyti ajetaan käänteisessä järjestyksessä. klo 22:00 Linnanmäki (Tivolikuja 5, 00510 Helsinki) - Virkkalan linja-autoasema (08700 Lohja). Paluumatkalla myös pysähdys edellämainituilla pysäkeillä. Auton koko vähintään 60 paikkainen linja-auto,','Lohjan kaupunki','ANY',1,4,NULL,NULL,219.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056271','[\"60100000\"]','[\"lohja\", \"linja\", \"lohjan\", \"auto\", \"kohde\", \"reitti\", \"auton\", \"koko\", \"vähintään\", \"paikkainen\", \"helsinki\", \"mäntynummen\", \"yhtenäiskoulu\", \"nummela\", \"kaupungin\", \"tilausajot\", \"ajalla\", \"kaupunki\", \"rantapuisto\", \"fiskars\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056271\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56271\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Kohde 1 tiistai 15.9.2026 Mäntynummen yhtenäiskoulu\", \"titleSv\": \"\", \"cpvCodes\": \"60100000\", \"currency\": \"EUR\", \"deadline\": null, \"lowCarbon\": false, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Reitti                                                                        \\nklo 09:05 Mäntynummen yhtenäiskoulu (Rantapuisto 39, \\n08100 Lohja) - Fiskars village (Peltorivi 1, \\nRaasepori).                                                                        \\nklo 13:00 Fiskars village (Peltorivi 1, Raasepori) - \\nMäntynummen yhtenäiskoulu (Rantapuisto 39, 08100 \\nLohja).                                                                \\nAuton koko vähintään 27 paikkainen linja-auto\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": 285.0, \"expirationDate\": \"2027-03-06T06:05:01.801Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"re