INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (676,'2026-056352','HILMA','RFP','OPEN','Hoitajakutsujärjestelmät','Hoitajakutsujärjestelmät Hankinnan kohteena on Helsingin kaupungin sosiaali-, terveys- ja pelastustoimialan käyttöön tulevat hoitajakutsu-, kaatumisentunnistus- sekä liikkumisen seurantajärjestelmät. Hoitajakutsujärjestelmiä käytetään sosiaali-, terveys- ja pelastustoimialalla sairaaloissa, seniorikeskuksissa, palvelutaloissa, tehostetun palveluasumisen yksiköissä, terveysasemien vuodeosastoilla, kuntoutusyksiköissä sekä muissa ympärivuorokautista hoitoa ja valvontaa edellyttävissä toimintaympäristöissä. Lisäksi järjestelmiä hyödynnetään kotihoidon tukipalveluissa ja erityisyksiköissä, joissa asiakkaiden avuntarve voi olla äkillistä ja reagointia edellyttävää. Hoitajakutsujärjestelmät ovat keskeinen osa päivittäistä hoiva, - ja hoitotyötä ja asiakas- sekä potilasturvallisuutta. Niiden avulla varmistetaan, että avunpyynnöt välittyvät viiveettä oikealle henkilöstölle ja että hoitohenkilökunta pystyy priorisoimaan tehtävänsä tilanteen kiireellisyyden mukaan. Samalla ne tukevat henkilöstön työturvallisuutta esimerkiksi uhka- ja vaaratilanteissa sekä mahdollistavat toiminnan seurannan, raportoinnin ja kehittämisen. Hoitajakutsujärjestelmien merkitys korostuu erityisesti tilanteissa, joissa asiakkaiden toimintakyky on heikentynyt, muistisairaudet ovat yleisiä tai hoidon tarve on jatkuvaa. Tällöin järjestelmän toimintavarmuus, helppokäyttöisyys ja integraatio muihin järjestelmiin eivät ole pelkästään teknisiä ominaisuuksia, vaan suoraan hoidon laatuun ja turvallisuuteen vaikuttavia tekijöitä. Hankinnan tavoitteena on varmistaa, että käytössä olevat ratkaisut vastaavat nykyisiä ja tulevia tarpeita. Tämä edellyttää järjestelmiltä skaalautuvuutta, yhteensopivuutta muiden teknologioiden kanssa sekä kykyä mukautua erilaisiin hoitoympäristöihin ilman, että järjestelmien käyttö monimutkaistuu. Samalla varmistetaan, että hankittavat ratkaisut täyttävät tietosuojaa, tietoturvaa ja viranomaisvaatimuksia koskevat velvoitteet. Kokonaisuutena hoitajakutsujärjestelmät ovat kriittinen osa palvelujärjestelmän toimivuutta, ja niiden hankinta tulee toteuttaa siten, että se tukee pitkäjänteisesti palveluiden laatua, turvallisuutta ja kustannustehokkuutta. Puitejärjestelyn kilpailutuksessa on tavoitteena löytää enintään viisi toimittajaa, jotka kykenevät toimittamaan toimialan kohteisiin hoitajakutsujärjestelmän, jolla voidaan hoitaa perinteinen hoitajakutsu (asiakas/potilas voi kutsua hoitajan huoneeseen) ja lisäksi hyödyntää uutta teknologiaa, jonka avulla järjestelmä voi hälyttää hoitajan asiakkaan/potilaan luokse ennakoivasti riskitilanteisiin liittyen (esim. sängyltä nouseminen, kaatuminen). Uuden teknologian avulla pyritään parantamaan asiakas/potilasturvallisuutta lain määrittämissä rajoissa. Hoitajakutsujärjestelmä tarvitaan kaikkiin uusiin ja saneerattaviin sairaaloihin, seniorikeskuksiin jne. Lisäksi sosiaali-, terveys- ja pelastustoimialalla on useita kohteita, joissa aikoinaan hankittu, mutta vanhentunut hoitajakutsujärjestelmä, jolle toimittaja ei enää tarjoa ylläpitoa ja tukea. Nämä vanhentuneet järjestelmät pitää korvata uusilla. Hankinnan kohteena olevat ratkaisut hankintaan pääasiassa puitejärjestelyyn valittujen toimittajien tarjoamana kokonaispalveluna. Tarkemmin hankinnan kohde on kuvattu tämän tarjouspyynnön liitteissä.,','Helsingin kaupungin sosiaali-, terveys- ja pelastustoimiala','ANY',3,4,NULL,NULL,10000000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056352','[\"72000000\", \"32344100\", \"33124110\", \"33195000\", \"35120000\", \"35121700\", \"48000000\", \"50324100\", \"79711000\"]','[\"hoitajakutsujärjestelmät\", \"hankinnan\", \"sosiaali\", \"terveys\", \"lisäksi\", \"joissa\", \"ovat\", \"asiakas\", \"avulla\", \"ratkaisut\", \"kohteena\", \"helsingin\", \"kaupungin\", \"hoitajakutsu\", \"pelastustoimialalla\", \"asiakkaiden\", \"potilasturvallisuutta\", \"niiden\", \"varmistetaan\", \"samalla\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/helsinki?id=595894&tpk=3946f27d-068b-4515-b374-c3d370811b7f\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056352\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56352\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Hoitajakutsujärjestelmät\", \"titleSv\": \"\", \"cpvCodes\": \"72000000 32344100 33124110 33195000 35120000 35121700 48000000 50324100 79711000\", \"currency\": \"EUR\", \"deadline\": \"2026-10-09T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Hankinnan kohteena on Helsingin kaupungin sosiaali-, terveys- ja pelastustoimialan käyttöön tulevat hoitajakutsu-, kaatumisentunnistus- sekä liikkumisen seurantajärjestelmät. \\n\\nHoitajakutsujärjestelmiä käytetään sosiaali-, terveys- ja pelastustoimialalla sairaaloissa, seniorikeskuksissa, palvelutaloissa, tehostetun palveluasumisen yksiköissä, terveysasemien vuodeosastoilla, kuntoutusyksiköissä sekä muissa ympärivuorokautista hoitoa ja valvontaa edellyttävissä toimintaympäristöissä. Lisäksi järjestelmiä hyödynnetään kotihoidon tukipalveluissa ja erityisyksiköissä, joissa asiakkaiden avuntarve voi olla äkillistä ja reagointia edellyttävää. \\n\\nHoitajakutsujärjestelmät ovat keskeinen osa päivittäistä hoiva, - ja hoitotyötä ja asiakas- sekä potilasturvallisuutta. Niiden avulla varmistetaan, että avunpyynnöt välittyvät viiveettä oikealle henkilöstölle ja että hoitohenkilökunta pystyy priorisoimaan tehtävänsä tilanteen kiireellisyyden mukaan. Samalla ne tukevat henkilöstön työturvallisuutta esimerkiksi uhka- ja vaaratilanteissa sekä mahdollistavat toiminnan seurannan, raportoinnin ja kehittämisen. \\n\\nHoitajakutsujärjestelmien merkitys korostuu erityisesti tilanteissa, joissa asiakkaiden toimintakyky on heikentynyt, muistisairaudet ovat yleisiä tai hoidon tarve on jatkuvaa. Tällöin järjestelmän toimintavarmuus, helppokäyttöisyys ja integraatio muihin järjestelmiin eivät ole pelkästään teknisiä ominaisuuksia, vaan suoraan hoidon laatuun ja turvallisuuteen vaikuttavia tekijöitä. \\n\\nHankinnan tavoitteena on varmistaa, että käytössä olevat ratkaisut vastaavat nykyisiä ja tulevia tarpeita. Tämä edellyttää järjestelmiltä skaalautuvuutta, yhteensopivuutta muiden teknologioiden kanssa sekä kykyä mukautua erilaisiin hoitoympäristöihin ilman, että järjestelmien käyttö monimutkaistuu. Samalla varmistetaan, että hankittavat ratkaisut täyttävät tietosuojaa, tietoturvaa ja viranomaisvaatimuksia koskevat velvoitteet. Kokonaisuutena hoitajakutsujärjestelmät ovat kriittinen osa palvelujärjestelmän toimivuutta, ja niiden hankinta tulee toteuttaa siten, että se tukee pitkäjänteisesti palveluiden laatua, turvallisuutta ja kustannustehokkuutta. \\n\\nPuitejärjestelyn kilpailutuksessa on tavoitteena löytää enintään viisi toimittajaa, jotka kykenevät toimittamaan toimialan kohteisiin hoitajakutsujärjestelmän, jolla voidaan hoitaa perinteinen hoitajakutsu (asiakas/potilas voi kutsua hoitajan huoneeseen) ja lisäksi hyödyntää uutta teknologiaa, jonka avulla järjestelmä voi hälyttää hoitajan asiakkaan/potilaan luokse ennakoivasti riskitilanteisiin liittyen (esim. sängyltä nouseminen, kaatuminen). Uuden teknologian avulla pyritään parantamaan asiakas/potilasturvallisuutta lain määrittämissä rajoissa. \\n\\nHoitajakutsujärjestelmä tarvitaan kaikkiin uusiin ja saneerattaviin sairaaloihin, seniorikeskuksiin jne.  Lisäksi sosiaali-, terveys- ja pelastustoimialalla on useita kohteita, joissa aikoinaan hankittu, mutta vanhentunut hoitajakutsujärjestelmä, jolle toimittaja ei enää tarjoa ylläpitoa ja tukea. Nämä vanhentuneet järjestelmät pitää korvata uusilla.  \\n\\nHankinnan kohteena olevat ratkaisut hankintaan pääasiassa puitejärjestelyyn valittujen toimittajien tarjoamana kokonaispalveluna.\\n\\nTarkemmin hankinnan kohde on kuvattu tämän tarjouspyynnön liitteissä.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": 10000000.0, \"expirationDate\": \"2026-10-09T09:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": true, \"employmentCondition\": false, \"procurementTypeCode\": \"services supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": true, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": true, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"16\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"Hoitajakutsujärjestelmät\", \"titleSv\": \"\", \"cpvCodes\": \"72000000 32344100 33124110 33195000 35120000 35121700 48000000 50324100 79711000\", \"currency\": \"EUR\", \"deadline\": \"2026-10-09T09:00