INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (677,'2026-056350','HILMA','RFP','OPEN','Elintarvikehankinnat Sallan kunnan keittiölle 1.1.2027 - 31.12.2028 + optio 1 vuosi','Sallan kunta pyytää tarjousta Sallan koulukeskuksen keittiölle toimitettavista elintarvikkeista ajalle 1.1.2027 - 31.12.2028 + optio 1 vuosi. Hankinta sisältää: 1. Maitotaloustuotteet, voi, juustot ja jäätelöt 2. Kuivatuotteet, mehut, juomat, rasvat ja muut ruoanvalmistustuotteet 3. Pakasteet, tuoretuotteet, hedelmät, säilykkeet ja marjatuotteet 4. Lihat ja muut lihatuotteet, makkarat, leikkeet, sisäelimet ja valmisruoat 5. Leipä ja leipomotuotteet (laktoositon) Tavarantoimitusosoite on Sallan koulukeskuksen keittiö, Kuusamontie 65, 98900 Salla. Elintarvikkeiden viikoittaiset toimituspäivät ovat maanantai, tiistai, keskiviikko, torstai, perjantaina ja lauantai., Maitotaloustuotteet, voi, juustot ja jäätelöt Tarkempi kuvaus liiteasiakirjassa, Kuivatuotteet, mehut, juomat, rasvat ja muut ruoanvalmistustuotteet Tarkempi kuvaus liiteasiakirjassa, Pakasteet, tuoretuotteet, hedelmät, säilykkeet ja marjatuotteet Tarkempi kuvaus liiteasiakirjassa, Lihat ja muut lihatuotteet, makkarat, leikkeet, sisäelimet ja valmisruoat Tarkempi kuvaus liiteasiakirjassa, Leipä ja leipomotuotteet (laktoositon) Tarkempi kuvaus liiteasiakirjassa,','Sallan kunta','ANY',2,14,NULL,NULL,420000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056350','[\"15000000\", \"15800000\", \"15500000\"]','[\"sallan\", \"tarkempi\", \"kuvaus\", \"liiteasiakirjassa\", \"muut\", \"kunta\", \"keittiölle\", \"optio\", \"vuosi\", \"koulukeskuksen\", \"maitotaloustuotteet\", \"ju