INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (678,'2026-056347','HILMA','RFP','OPEN','Turvatekniset järjestelmät palveluineen','Hankinnan kohteena on turvatekniset järjestelmät ja turvatekniikkaan liittyvät palvelut. Rikosseuraamuslaitos hankkii vankiloissa käytettävää turvatekniikkaa ja turvatekniikan huoltopalvelun. Hankinta käsittää kaikki Rikosseuraamuslaitoksen vankilat. Tämä hankinta jaetaan seuraaviin osa-alueisiin: 1. Turvatekniset järjestelmät 2. Kulunvalvontajärjestelmä Hankinnan kohteena olevat tuotteet ja niihin liittyvät palvelut on kuvattu osallistumispyynnön liitteessä 1.1 \"Alustava hankinnan kohteen kuvaus OA1\" ja liitteessä 1.2 \"Alustava hankinnan kohteen kuvaus OA2\". Hankintaan liittyviä vaatimuksia on myös muissa osallistumispyynnön liitteissä. Ehdokas voi osallistua ja tulla valituksi vain toiseen tai molempiin osa-alueeseen. SOPIMUSKAUSI Hankinnan puitesopimuskausi on kiinteänä voimassa 7 vuotta. HANKINNAN LAAJUUS Hankinnan ennakkoitu arvo on arviolta 19 600 000 € (alv. 0 %) koko sopimuskaudelle mukaan lukien optiokausi. Hankinnan ennakoitu kokonaisarvo jakautuu osa-aluekohtaisesti seuraavasti: Osa-alueen 1 Turvateknisten järjestelmien ennakoitu arvo on noin 13 000 000 €-15 400 000€ (alv. 0%) Osa-alueen 2 Kulunvalvontajärjestelmän ennakoitu arvo on noin 3 000 000 € - 4 200 000 € (alv. 0%), Turvatekniset järjestelmät Osa-alueen kohteena on turvatekniset järjestelmät, jotka on kuvattu tarkemmin osallistumispyynnön liitteellä 1.1. SOPIMUSKAUSI Hankinnan puitesopimuskausi on kiinteänä voimassa 7 vuotta. HANKINNAN LAAJUUS Osa-alueen 1 Turvateknisten järjestelmien ennakoitu arvo on noin 13 000 000 €-15 400 000€ (alv. 0%), Kulunvalvontajärjestelmä Osa-alueen kohteena on kulunvalvontajärjestelmä, jotka on kuvattu tarkemmin osallistumispyynnön liitteellä 1.2. SOPIMUSKAUSI Hankinnan puitesopimuskausi on kiinteänä voimassa 7 vuotta. HANKINNAN LAAJUUS Osa-alueen 2 Kulunvalvontajärjestelmän ennakoitu arvo on noin 3 000 000 € - 4 200 000 €(alv. 0%),','Rikosseuraamuslaitos','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056347','[\"35120000\", \"31625300\", \"35121700\", \"42961100\", \"45312000\", \"50610000\", \"51900000\"]','[\"hankinnan\", \"alueen\", \"turvatekniset\", \"järjestelmät\", \"arvo\", \"ennakoitu\", \"kohteena\", \"osallistumispyynnön\", \"noin\", \"rikosseuraamuslaitos\", \"kulunvalvontajärjestelmä\", \"kuvattu\", \"sopimuskausi\", \"puitesopimuskausi\", \"kiinteänä\", \"voimassa\", \"vuotta\", \"laajuus\", \"liittyvät\", \"palvelut\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/rikosseuraamuslaitos?id=624052&tpk=3a8435a0-a08e-450b-a230-e3580cd45df3\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056347\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56347\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Turvatekniset järjestelmät\", \"titleSv\": \"\", \"cpvCodes\": \"35120000 31625300 35121700 45312000 50610000 51900000\", \"currency\": null, \"deadline\": \"2026-10-05T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"Osa-alueen kohteena on turvatekniset järjestelmät, jotka on kuvattu tarkemmin osallistumispyynnön liitteellä 1.1.\\n\\nSOPIMUSKAUSI\\n\\nHankinnan puitesopimuskausi on kiinteänä voimassa 7 vuotta.\\n\\n\\nHANKINNAN LAAJUUS\\n\\nOsa-alueen 1 Turvateknisten järjestelmien ennakoitu arvo on noin  13 000 000 €-15 400 000€ (alv. 0%)\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estima