INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (686,'2026-056377','HILMA','OTHER','OPEN','Kilpisen koulun peruskorjauksen pää-ja arkkitehtisuunnittelu','Kilpisen koulun peruskorjauksen pää-ja arkkitehtisuunnittelu Hankinnan kohteena on koulurakennuksen peruskorjauksen toteutussuunnittelu. Hankkeen tavoitteena on laatia yhteensovitetut ja toteutuskelpoiset suunnitelmat olemassa olevan rakennuksen peruskorjaamiseksi siten, että rakennuksen tekninen, toiminnallinen ja terveydellinen taso saatetaan nykyvaatimuksia vastaavaksi ja tilat palvelevat opetustoiminnan käyttöä. Toteutussuunnittelu käsittää arkkitehti‑, rakenne‑ sekä taloteknisen suunnittelun (LVI ja sähkö) sekä näiden suunnittelualojen yhteensovituksen. Peruskorjaus on tarkoitus toteuttaa osittain siten, että koulutoiminta jatkuu koululla osittain. Kohteessa on tehty laserkeilaus, joka toimii toteutussuunnittelun lähtötietona. Kyseessä on olemassa olevan koulurakennuksen peruskorjaus, minkä vuoksi suunnittelussa korostuu olemassa olevien rakenteiden ja järjestelmien huomioiminen sekä suunnitteluratkaisujen yhteensovittaminen. Toteutussuunnittelu tehdään tietomallipohjaisesti kolmiulotteisena mallina, jota hyödynnetään suunnittelukokouksissa ja käyttäjäyhteistyössä. Suunnittelukokoukset ja käyttäjäpalaverit järjestetään pääsääntöisesti hankkeen kohteella tilaajan kutsusta.,','Jyväskylän kaupunki','ANY',6,15,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056377','[\"71000000\"]','[\"peruskorjauksen\", \"toteutussuunnittelu\", \"olemassa\", \"kilpisen\", \"koulun\", \"arkkitehtisuunnittelu\", \"koulurakennuksen\", \"hankkeen\", \"oleva