INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (693,'2026-056394','HILMA','RFP','OPEN','Kotiin annettavat turvalaitteet, hälytysten vastaanottopalvelu ja hälytysten vastaanottojärjestelmä','Kotiin annettavat turvalaitteet, hälytysten vastaanottopalvelu ja hälytysten vastaanottojärjestelmä Lapin hyvinvointialue pyytää tarjouksia kokonaisuudesta, johon sisältyvät: 1. kotiin annettavat turvalaitteet Lapin hyvinvointialueen asiakkaille 2. hälytysten vastaanottopalvelu 3. hälytysten vastaanottojärjestelmä edellä mainitun palvelun tuottamiseen hyvinvointialueen omana toimintana. Hankinnassa turvalaitteilla tarkoitetaan erilaisia kotiin annettavia turvalaitteita, joilla voidaan parantaa kotona asuvan asiakkaan turvallisuutta. Hankittavia turvalaitteita ovat turvapuhelimet ja niiden lisälaitteet, paikantava turvaranneke sekä ratkaisu yhteisöllisen asumisen ovivalvontaan. Hälytysten vastaanottopalvelulla tarkoitetaan palvelua, jossa otetaan vastaan turvalaitteiden kautta tulevat hälytykset, tehdään alustavan arvion avuntarpeesta ja välitetään pyyntö edelleen turva-auttajille. Palvelun tulee toiminnassa vuorokauden ympäri vuoden jokaisena päivä. Hälytysten vastaanottojärjestelmällä tarkoitetaan järjestelmää, jolla tilaaja voi ottaa eri turvalaitteiden hälytykset vastaan ja edelleenvälittää ne tehtävänä turva-auttajille. Lapin hyvinvointialueella on tarkoitus ottaa hälytysten vastaanottopalvelu omaksi toiminnaksi alustavan aikataulun mukaan keväällä 2028. Hyvinvointialue hankkii hälytysten vastaanottopalvelua siihen asti, kunnes vastaanottojärjestelmä on otettu käyttöön, minkä jälkeen vastaanottopalvelun hankinta päättyy. Hankinnan kohde on kuvattu tarkemmin tarjouspyynnössä ja sen liitteissä, erityisesti liitteessä 1 \"Hankinnan kohteen kuvaus\". Kilpailutuksessa valitaan yksi toimitta puitesopimustoimittajaksi. Puitejärjestelyn kautta hyvinvointialue hankkii valitulta toimittajalta turvalaitteita ja palveluita sopimuskauden aikana tarpeen mukaan. Hyvinvointialueen tarpeet voivat vaihdella sopimuskauden aikana, eikä tarjouspyynnöllä sitouduta tiettyihin hankintamääriin. Puitesopimuksen sopimuskausi on määräaikaisena kaksi vuotta, jonka jälkeen sopimus jatkuu toistaiseksi voimassa olevana. Hankintayksikön tarkoitus on tehdä sopimus valitun toimittajan kanssa heti, kun tarjousaika on päättynyt, tarjoukset on vertailtu, hankintapäätös on tehty ja muutoksenhakuaika on päättynyt. Hankintayksikön arvion mukaan ajankohta on lokakuun 2026 aikana. Laitevaihtojen toteutuksen ja muiden käyttöönottoon liittyvien toimien aikataulut sovitaan yhdessä valitun toimittajan kanssa molempien osapuolten tarpeet huomioivalla tavalla. Lisäksi valitulta toimittajalta hankitaan hälytysten vastaanottojärjestelmä kokonaisuutena, johon sisältyy järjestelmän toimittaminen ja sen jatkuva palvelu. Järjestelmän jatkuvan palvelun sopimus on voimassa toistaiseksi. Hankintaa ei ole jaettu osiin, koska kyseessä on yhtenäinen tavaroiden ja palveluiden muodostama kokonaisuus, jonka kaikkien osasten yhteensopivuus on voitava varmistaa. Lapin hyvinvointialueen asiakkaiden turvallisuuden kannalta on tärkeää, että yksi toimittaja vastaa koko kokonaisuuden toimivuudesta. Hankintailmoitus on julkaistu toisen kerran uudelleen, koska kaksi aiempaa hankintamenettelyä on täytynyt keskeyttää hankinta-asiakirjojen muutostarpeiden vuoksi.,','Lapin hyvinvointialue','ANY',3,14,NULL,NULL,3700000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056394','[\"35120000\", \"48000000\", \"72000000\", \"85000000\"]','[\"hälytysten\", \"lapin\", \"vastaanottojärjestelmä\", \"hyvinvointialue\", \"kotiin\", \"vastaanottopalvelu\", \"hyvinvointialueen\", \"annettavat\", \"turvalaitteet\", \"palvelun\", \"tarkoitetaan\", \"turvalaitteita\", \"mukaan\", \"aikana\", \"sopimus\", \"johon\", \"vastaan\", \"turvalaitteiden\", \"kautta\", \"hälytykset\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/lapha?id=621819&tpk=d4d20d70-a401-46e3-8d0e-61d416fc1773\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056394\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56394\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Kotiin annettavat turvalaitteet, hälytysten vastaanottopalvelu ja hälytysten vastaanottojärjestelmä\", \"titleSv\": \"\", \"cpvCodes\": \"35120000 48000000 72000000 85000000\", \"currency\": \"EUR\", \"deadline\": \"2026-09-21T13:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Lapin hyvinvointialue pyytää tarjouksia kokonaisuudesta, johon sisältyvät:\\n\\n1. kotiin annettavat turvalaitteet Lapin hyvinvointialueen asiakkaille\\n2. hälytysten vastaanottopalvelu\\n3. hälytysten vastaanottojärjestelmä edellä mainitun palvelun tuottamiseen hyvinvointialueen omana toimintana.\\n\\nHankinnassa turvalaitteilla tarkoitetaan erilaisia kotiin annettavia turvalaitteita, joilla voidaan parantaa kotona asuvan asiakkaan turvallisuutta. Hankittavia turvalaitteita ovat turvapuhelimet ja niiden lisälaitteet, paikantava turvaranneke sekä ratkaisu yhteisöllisen asumisen ovivalvontaan. \\n\\nHälytysten vastaanottopalvelulla tarkoitetaan palvelua, jossa otetaan vastaan turvalaitteiden kautta tulevat hälytykset, tehdään alustavan arvion avuntarpeesta ja välitetään pyyntö edelleen turva-auttajille. Palvelun tulee toiminnassa vuorokauden ympäri vuoden jokaisena päivä.\\n\\nHälytysten vastaanottojärjestelmällä tarkoitetaan järjestelmää, jolla tilaaja voi ottaa eri turvalaitteiden hälytykset vastaan ja edelleenvälittää ne tehtävänä turva-auttajille. Lapin hyvinvointialueella on tarkoitus ottaa hälytysten vastaanottopalvelu omaksi toiminnaksi alustavan aikataulun mukaan keväällä 2028. Hyvinvointialue hankkii hälytysten vastaanottopalvelua siihen asti, kunnes vastaanottojärjestelmä on otettu käyttöön, minkä jälkeen vastaanottopalvelun hankinta päättyy.\\n\\nHankinnan kohde on kuvattu tarkemmin tarjouspyynnössä ja sen liitteissä, erityisesti liitteessä 1 \\\"Hankinnan kohteen kuvaus\\\".\\n\\nKilpailutuksessa valitaan yksi toimitta puitesopimustoimittajaksi. Puitejärjestelyn kautta hyvinvointialue hankkii valitulta toimittajalta turvalaitteita ja palveluita sopimuskauden aikana tarpeen mukaan. Hyvinvointialueen tarpeet voivat vaihdella sopimuskauden aikana, eikä tarjouspyynnöllä sitouduta tiettyihin hankintamääriin. Puitesopimuksen sopimuskausi on määräaikaisena kaksi vuotta, jonka jälkeen sopimus jatkuu toistaiseksi voimassa olevana. Hankintayksikön tarkoitus on tehdä sopimus valitun toimittajan kanssa heti, kun tarjousaika on päättynyt, tarjoukset on vertailtu, hankintapäätös on tehty ja muutoksenhakuaika on päättynyt. Hankintayksikön arvion mukaan ajankohta on lokakuun 2026 aikana. Laitevaihtojen toteutuksen ja muiden käyttöönottoon liittyvien toimien aikataulut sovitaan yhdessä valitun toimittajan kanssa molempien osapuolten tarpeet huomioivalla tavalla.\\n\\nLisäksi valitulta toimittajalta hankitaan hälytysten vastaanottojärjestelmä kokonaisuutena, johon sisältyy järjestelmän toimittaminen ja sen jatkuva palvelu. Järjestelmän jatkuvan palvelun sopimus on voimassa toistaiseksi.\\n\\nHankintaa ei ole jaettu osiin, koska kyseessä on yhtenäinen tavaroiden ja palveluiden muodostama kokonaisuus, jonka kaikkien osasten yhteensopivuus on voitava varmistaa. Lapin hyvinvointialueen asiakkaiden turvallisuuden kannalta on tärkeää, että yksi toimittaja vastaa koko kokonaisuuden toimivuudesta.\\n\\nHankintailmoitus on julkaistu toisen kerran uudelleen, koska kaksi aiempaa hankintamenettelyä on täytynyt keskeyttää hankinta-asiakirjojen muutostarpeiden vuoksi.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": 3700000.0, \"expirationDate\": \"2026-09-21T13:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": true, \"employmentCondition\": false, \"procurementTypeCode\": \"supplies services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": true, \"lotResultTotalAmount\": null, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": true, \"smeParticipationConsidered\": false, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"16\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"Kotiin annettavat turvalaitteet, hälytysten vastaanottopalvelu ja hälytysten vastaanottojärjestelmä\", \"titleSv\": \"\", \"cpvCodes\": \"35120000 48000000 72000000 85000000\", \"currency\": \"EUR\", \"deadline\": \"2026-09-21T13:00:00Z\", \"eFormsId\": \"291c75df-1357-4d25-820f-6253cae06d74\", \"isEForms\": true, \"mainType\": \"ContractNotices\", \"noticeId\": 56394, \"lowCarbon\": false, \"nutsCodes\": \"\", \"titleOther\": \"\", \"isCancelled\": false, \"procedureId\": 35387, \"biodiversity\": false, \"dat