INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (694,'2026-056393','HILMA','RFP','OPEN','LP P2 Rakennuttajakonsulttipalveluiden hankinta','LP P2 Rakennuttajakonsulttipalveluiden hankinta Länsiprojekti: Helsingin Sataman Oy:n kehittämisohjelma on kaupunginhallituksen hyväksymä (17.1.2022) pitkäaikaissuunnitelma, jonka tarkoituksena on keskittää Tallinnan liikenne Länsisatamaan ja Ruotsiin suuntautuva liikenne Katajanokalle siten että Eteläsatamasta vapautuu aluetta muuhun käyttöön. Tämän edellytyksenä on toteuttaa Länsiprojekti eli keskittämisen vaatimat muutokset Länsisatamaan. Länsiprojekti koostuu kolmesta eri osaprojektista: - P1 Satamatunneli, kaksisuuntainen väylä, joka johtaa Länsisatamasta Länsiväylälle - P2 Rakennukset, satama-alueella sijaitsevien rakennusten muutokset ja tarvittavat uudet rakennukset - P3 Laituri- ja kenttäjärjestelyistä, laituri- ja kenttäalueiden kehittäminen ja laitureiden uusiminen. Tässä hankinnassa on kysymys P2 Rakennukset -osaprojektin rakennuttajakonsulttipalveluiden hankinnasta. Hankinnan kohdetta on kuvattu tarkemmin tarjouspyynnössä liitteineen.,','Helsingin Satama Oy','ANY',4,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056393','[\"71000000\", \"71500000\"]','[\"rakennuttajakonsulttipalveluiden\", \"länsiprojekti\", \"rakennukset\", \"hankinta\", \"helsingin\", \"liikenne\", \"länsisatamaan\", \"muutokset\", \"satama\", \"laituri\", \"sataman\", \"kehittämisohjelma\", \"kaupunginhallituksen\", \"hyväksymä\", \"pitkäaikaissuunnitelma\", \"jonka\", \"tarkoituksena\", \"keskittää\", \"tallinnan\", \"ruotsiin\"]',NULL,NULL,'[{\"url\": \"https://tarj