INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (697,'2026-056419','HILMA','OTHER','OPEN','Höyryautoklaavi elatusaineiden sekä liuosten ja nesteputkien sterilointiin','Höyryautoklaavi elatusaineiden sekä liuosten ja nesteputkien sterilointiin HUS-Yhtymä pyysi tarjouksia elatusaineiden sekä liuosten ja nesteputkien sterilointiin käytettävästä höyryautoklaavista. Höyryautoklaavin tulee soveltua Bakteriologian laboratorion elatusaineyksikön ja liuoslaboratorion käyttöön. Autoklaavia tullaan käyttämään HUS Diagnostiikkakeskuksen elatusaineyksikössä bakteerien ja sienten kasvatuksessa käytettävien elatusaineiden sekä liuoslaboratorion nesteiden ja liuosputkien sterilointiin. Autoklaavilla tulee olla nesteohjelman lisäksi kuivaohjelma. Autoklaavin kammion tilavuus tulee olla vähintään 400 litraa ja autoklaavissa tulee olla aktiivinen jäähdytys. Nesteitä autoklavoitaessa tuotteet ovat osin avoimissa pulloissa ja putkissa, siten että korkki on päällä suojana, mutta ei suljettuna tiiviisti. Autoklaavia ei käytetä täysin suljettujen nesteiden, kuten ampullien sterilointiin. Steriloitavan nesteen tilavuuden tulee pysyä ennallaan autoklavoinnin aikana. Kyseessä on kokonaishankinta, eli hankintaa ei ole jaettu osiin. Hankinnan kohde ja sitä koskevat vaatimukset on kuvattu yksityiskohtaisesti tarjouspyynnössä ja sen liitteissä. Laitteen rahoitus on tarkoitus toteuttaa HUSin vuoden 2026 investointiohjelmasta. Laite pitää olla toimitettu ja asennettu investointivuoden aikana 2026.,','HUS-yhtymä','ANY',8,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056419','[\"33191110\", \"33191000\"]','[\"steriloin