INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (699,'2026-056472','HILMA','RFI','OPEN','Markkinakartoitus: Biosuojakaapit','Markkinakartoitus: Biosuojakaapit Tämä ilmoitus ei ole hankintailmoitus eikä tarjouspyyntö, eikä sen julkaisemisella aloiteta tarjouskilpailua. Kyseessä on ennakkoilmoitus tulevasta hankinnasta. Ennakkoilmoitukseen liittyy markkinakartoitus/tietopyyntö, jolloin kiinnostuneilla yrityksillä on mahdollisuus käydä hankintaa koskevaa teknistä vuoropuhelua hankintayksikön kanssa. Tietopyynnön tarkoituksena on kartoittaa markkinoilla olevia ratkaisuja ja saada kattavasti niitä koskevaa tietoa, jotta valmisteilla oleva kilpailutus voidaan toteuttaa mahdollisimman tarkoituksenmukaisesti. Tietopyyntöön vastaaminen ei ole edellytys kilpailutukseen osallistumiselle eikä vaikuta tarjoajan asemaan siinä. Tietopyynnössä esitetyt seikat ovat alustavia ja saattavat muuttua hankinnan valmistelun edetessä. Hankinnan kohteena ovat Ruokaviraston käyttöön tulevat biosuojakaapit. Hankintaan sisältyy kaksi (2) EN 12469 -standardin mukaista luokan II A biosuojakaappia BSL-3-laboratorioon. Hankittavilla biosuojakaapeilla korvataan viraston nykyisiä, käyttöikänsä päähän tulleita laitteita. Biosuojakaappien tarkoituksena on suojata työntekijöitä työskentelyn yhteydessä käsiteltäviltä mahdollisesti vaarallisilta biologisilta agensseilta. Lisäksi hankintaan sisältyy optio enintään kolmen (3) vastaavan biosuojakaapin hankkimisesta kahden (2) vuoden aikana sopimuksen alkamisesta rikkoutuneiden tai käyttöikänsä päähän tulleiden biosuojakaappien korvaamiseksi. Hankinta sisältää lisäksi laitteiden toimituksen, käyttökuntoon saattamisen, kokoonpanon sekä asennuksen niille osoitettuihin tiloihin.,','Ruokavirasto','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056472','[\"38000000\"]','[\"markkinakartoitus\", \"biosuojakaapit\", \"eikä\", \"koskevaa\", \"tarkoituksena\", \"ovat\", \"hankinnan\", \"hankintaan\", \"sisältyy\", \"käyttöikänsä\", \"päähän\", \"biosuojakaappien\", \"lisäksi\", \"tämä\", \"ilmoitus\", \"hankintailmoitus\", \"tarjouspyyntö\", \"julkaisemisella\", \"aloiteta\", \"tarjouskilpailua\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056472\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56472\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Markkinakartoitus: Biosuojakaapit\", \"titleSv\": \"\", \"cpvCodes\": \"38000000\", \"currency\": null, \"deadline\": \"2026-09-22T20:59:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Tämä ilmoitus ei ole hankintailmoitus eikä tarjouspyyntö, eikä sen julkaisemisella aloiteta tarjouskilpailua. Kyseessä on ennakkoilmoitus tulevasta hankinnasta. Ennakkoilmoitukseen liittyy markkinakartoitus/tietopyyntö, jolloin kiinnostuneilla yrityksillä on mahdollisuus käydä hankintaa koskevaa teknistä vuoropuhelua hankintayksikön kanssa. Tietopyynnön tarkoituksena on kartoittaa markkinoilla olevia ratkaisuja ja saada kattavasti niitä koskevaa tietoa, jotta valmisteilla oleva kilpailutus voidaan toteuttaa mahdollisimman tarkoituksenmukaisesti. Tietopyyntöön vastaaminen ei ole edellytys kilpailutukseen osallistumiselle eikä vaikuta tarjoajan asemaan siinä. Tietopyynnössä esitetyt seikat ovat alustavia ja saattavat muuttua hankinnan valmistelun edetessä. \\n\\nHankinnan kohteena ovat Ruokaviraston käyttöön tulevat biosuojakaapit. Hankintaan sisältyy kaksi (2) EN 12469 -standardin mukaista luokan II A biosuojakaappia BSL-3-laboratorioon. Hankittavilla biosuojakaapeilla korvataan viraston nykyisiä, käyttöikänsä päähän tulleita laitteita. Biosuojakaappien tarkoituksena on suojata työntekijöitä työskentelyn yhteydessä käsiteltäviltä mahdollisesti vaarallisilta biologisilta agensseilta.\\n\\nLisäksi hankintaan sisältyy optio enintään kolmen (3) vastaavan biosuojakaapin hankkimisesta kahden (2) vuoden aikana sopimuksen alkamisesta rikkoutuneiden tai käyttöikänsä päähän tulleiden biosuojakaappien korvaamiseksi.\\n\\nHankinta sisältää lisäksi laitteiden toimituksen, käyttökuntoon saattamisen, kokoonpanon sekä asennuksen niille osoitettuihin tiloihin.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-09-22T20:59:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": null, \"lotResultTotalAmount\": null, \"justWorkingConditions\": null, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": null, \"includesFrameworkAgreement\": true, \"smeParticipationConsidered\": null, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": null, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"E1\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"title