INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (702,'2026-056471','HILMA','RFI','OPEN','TIETOPYYNTÖ MARKKINAKARTOITUSTA JA -VUOROPUHELUA VARTEN / Varastonhallinnan ja työlaskutuksen ratkaisun uudistaminen','TIETOPYYNTÖ MARKKINAKARTOITUSTA JA -VUOROPUHELUA VARTEN / Varastonhallinnan ja työlaskutuksen ratkaisun uudistaminen Tämä ilmoitus on tietopyyntö markkinakartoitusta ja markkinavuoropuhelua varten. Ilmoituksen tarkoituksena on kartoittaa markkinoilla olevia ratkaisuja, toimintamalleja ja toimittajia Porin kaupungin varastonhallinnan ja työlaskutuksen ratkaisun uudistamiseen tai korvaamiseen. Tämä ilmoitus: • ei ole hankintailmoitus • ei ole tarjouspyyntö • ei käynnistä hankintamenettelyä • ei velvoita hankintayksikköä toteuttamaan hankintaa tässä ilmoituksessa kuvatulla tavalla Tietopyyntöön vastaaminen tai markkinavuoropuheluun osallistuminen ei ole edellytys mahdolliseen myöhempään tarjouskilpailuun osallistumiselle. Osallistuneille yrityksille ei makseta korvausta. Tavoiteltu tulevaisuuden ratkaisu Porin kaupunki hakee markkinoilta näkemyksiä ratkaisusta, joka tukee varastonhallinnan, materiaalien käytön, kustannusten kohdistamisen, työlaskutuksen, laskutusaineiston muodostamisen ja raportoinnin sujuvaa kokonaisuutta. Tavoitteena ei tässä vaiheessa ole lukita ratkaisua tiettyyn tuotteeseen, toimittajaan tai tekniseen toteutustapaan, vaan tunnistaa tarkoituksenmukaiset markkinavaihtoehdot ja hankinnan mahdollinen rajaus. Tavoitteena on kartoittaa, millaiset ratkaisut voisivat tukea erityisesti seuraavia kokonaisuuksia: • varastonhallinnan perusprosessit, kuten nimikkeiden hallinta, vastaanotto, käyttöönotto, siirrot, palautukset, poistot, saldoseuranta, inventointi ja varaston arvon seuranta sekä kalustonvuokraus • materiaalien, työn, polttoaineen ja muiden kustannusten kohdistaminen oikeille työmääräyksille, laskutettaville töille, liikelaitoksille, asiakkaille, kustannuspaikoille tai muille sovituille kohteille • laskutusaineiston muodostaminen, tarkistaminen, hyväksyminen, korjaaminen ja siirtäminen taloushallinnon järjestelmiin hallitusti • käsin tehtävän kirjaamisen, paperiprosessien ja Excel-pohjaisen seurannan vähentäminen • integraatiot taloushallintoon, ostolaskuihin, kalustonhallintaan, polttoainekulutuksen tietoihin ja muihin mahdollisiin tietolähteisiin • raportointi, analytiikka, tiedolla johtaminen, virhetilanteiden seuranta ja laskutusaineiston siirtotilanteiden valvonta • käyttöoikeuksien hallinta, lokitus, muutosten jäljitettävyys ja tietojen siirrettävyys • ylläpidettävä ja dokumentoitu palvelumalli, joka ei perustu yksittäisten henkilöiden hiljaiseen tietoon,','Porin kaupunki','ANY',1,9,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056471','[\"48810000\"]','[\"varastonhallinnan\", \"työlaskutuksen\", \"porin\", \"tietopyyntö\", \"markkinakartoitusta\", \"varten\", \"ratkaisun\", \"kaupunki\", \"laskutusaineiston\", \"vuoropuhelua\", \"uudistaminen\", \"tämä\", \"ilmoitus\", \"kartoittaa\", \"tässä\", \"materiaalien\", \"kustannusten\", \"tavoitteena\", \"hallinta\", \"seuranta\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/pori?id=625640&tpk=39251dfb-8b33-47d3-8815-8c3eb98305d3\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056471\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56471\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"TIETOPYYNTÖ MARKKINAKARTOITUSTA JA -VUOROPUHELUA VARTEN / Varastonhallinnan ja työlaskutuksen ratkaisun uudistaminen\", \"titleSv\": \"\", \"cpvCodes\": \"48810000\", \"currency\": null, \"deadline\": \"2026-09-30T09:00:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Tämä ilmoitus on tietopyyntö markkinakartoitusta ja markkinavuoropuhelua varten. Ilmoituksen tarkoituksena on kartoittaa markkinoilla olevia ratkaisuja, toimintamalleja ja toimittajia Porin kaupungin varastonhallinnan ja työlaskutuksen ratkaisun uudistamiseen tai korvaamiseen.\\n\\nTämä ilmoitus:\\n• ei ole hankintailmoitus\\n• ei ole tarjouspyyntö\\n• ei käynnistä hankintamenettelyä\\n• ei velvoita hankintayksikköä toteuttamaan hankintaa tässä ilmoituksessa kuvatulla tavalla\\n\\nTietopyyntöön vastaaminen tai markkinavuoropuheluun osallistuminen ei ole edellytys mahdolliseen myöhempään tarjouskilpailuun osallistumiselle. Osallistuneille yrityksille ei makseta korvausta.\\n\\nTavoiteltu tulevaisuuden ratkaisu\\n\\nPorin kaupunki hakee markkinoilta näkemyksiä ratkaisusta, joka tukee varastonhallinnan, materiaalien käytön, kustannusten kohdistamisen, työlaskutuksen, laskutusaineiston muodostamisen ja raportoinnin sujuvaa kokonaisuutta. Tavoitteena ei tässä vaiheessa ole lukita ratkaisua tiettyyn tuotteeseen, toimittajaan tai tekniseen toteutustapaan, vaan tunnistaa tarkoituksenmukaiset markkinavaihtoehdot ja hankinnan mahdollinen rajaus.\\n\\nTavoitteena on kartoittaa, millaiset ratkaisut voisivat tukea erityisesti seuraavia kokonaisuuksia:\\n• varastonhallinnan perusprosessit, kuten nimikkeiden hallinta, vastaanotto, käyttöönotto, siirrot, palautukset, poistot, saldoseuranta, inventointi ja varaston arvon seuranta sekä kalustonvuokraus\\n• materiaalien, työn, polttoaineen ja muiden kustannusten kohdistaminen oikeille työmääräyksille, laskutettaville töille, liikelaitoksille, asiakkaille, kustannuspaikoille tai muille sovituille kohteille\\n• laskutusaineiston muodostaminen, tarkistaminen, hyväksyminen, korjaaminen ja siirtäminen taloushallinnon järjestelmiin hallitusti\\n• käsin tehtävän kirjaamisen, paperiprosessien ja Excel-pohjaisen seurannan vähentäminen\\n• integraatiot taloushallintoon, ostolaskuihin, kalustonhallintaan, polttoainekulutuksen tietoihin ja muihin mahdollisiin tietolähteisiin\\n• raportointi, analytiikka, tiedolla johtaminen, virhetilanteiden seuranta ja laskutusaineiston siirtotilanteiden valvonta\\n• käyttöoikeuksien hallinta, lokitus, muutosten jäljitettävyys ja tietojen siirrettävyys\\n• ylläpidettävä ja dokumentoitu palvelumalli, joka ei perustu yksittäisten henkilöiden hiljaiseen tietoon\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-09-30T09:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": null, \"lotResultTotalAmount\": null, \"justWorkingConditions\": null, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": null, \"includesFrameworkAgreement\": null, \"smeParticipationConsidered\": null, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": null, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": null, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"E1\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"TIETOPYYNTÖ MARKKINAKARTOITUSTA JA -VUOROPUHELUA VARTEN / Varastonhallinnan