INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (706,'2026-056462','HILMA','OTHER','OPEN','Maanrakennustöiden hankinta (puitesopimus)','Maanrakennustöiden hankinta (puitesopimus) Hankinnan kohteena on maanrakennusteknisiin pienurakoihin liittyvät laskutyöurakat, joista ei erikseen pyydetä urakkatarjousta. Maanrakennusteknillisillä töillä tarkoitetaan erilaisia korjaus-, uusimis-, huolto- ja muutostöitä sekä pieniä investointeja, jotka ovat kustannuksiltaan pääsääntöisesti EU-kynnysarvon alittavia. Seuraavassa lyhyt erittely tyypillisistä sopimuskauden tehtävistä:- Hankkeen päätoteuttajana toiminen (YSE 98 4§ mukaiset johtovelvollisuudet)- Työnjohtotehtävät· Maanrakennustyöt- Maanrakennustöihin liittyvät mittatyöt- Viherrakentamistyöt. Sopimuksella voidaan tilata myös muita vastaaviin töihin liittyviä pieniä töitä, joita ei ole tässä asiakirjassa mainittu. Solmittavat puitesopimukset eivät tuota valituille urakoitsijoille yksinoikeutta sopimuksessa määriteltyjen palveluiden ja tuotteiden hankintaan. Tilaaja ei myöskään sitoudu tiettyihin hankintamääriin sopimuskauden aikana. Työsuoritukset toteutetaan pääosin laskutusperusteisena tuntityönä. Tilaaja pidättää itsellään oikeuden hankkia myös itse rakennustarvikkeita ja -materiaaleja, jotka urakoitsija on velvollinen asentamaan paikoilleen.,','Savon Koulutuskuntayhtymä','ANY',2,5,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056462','[\"45000000\", \"45200000\"]','[\"maanrakennustöiden\", \"hankinta\", \"puitesopimus\", \"liittyvät\", \"pieniä\", \"jotka\", \"sopimuskauden\", \"tilaaja\", \"savon\", \"koulutuskuntayhtymä\", \"hankinnan\", \"