INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (709,'2026-056448','HILMA','OTHER','OPEN','Perhetalo vaihe 2B kunnallistekniikan rakentaminen','Perhetalo vaihe 2B kunnallistekniikan rakentaminen Tämä hankintailmoitus on ilmoitus \"Perhetalo vaihe 2B kunnallistekniikan rakentaminen\" -urakan tarjouskilpailun käynnistämisestä. Rakennuskohteena on Naantalin kaupungin Luonnonmaan saarella sijaitsevan asemakaava-alueen laajennus. Urakkaan sisältyy kunnallistekniikan rakentamista. Hankinnassa noudatetaan Lakia julkisista hankinnoista ja käyttöoikeussopimuksista (hankintalaki, 1397/2016). Hankinnan kohde on kansallisen kynnysarvon (hankintalaki, 1397/2016 25 §) alittava rakennusurakka. Urakoitsijalla on urakan pääsuoritusvelvollisuus suunnitelmien ja urakkatarjouspyyntöasiakirjojen mukaisen kohteen rakentamiseksi kaikkine työkustannuksineen näiden tarjouspyyntöasiakirjojen mukaisesti toteutettuna. Urakan toteutuksessa on otettava huomioon kaikki tarjouspyyntöasiakirjoissa sekä mahdollisesti toimitetuissa lisäkirjeissä mainitut lähtötiedot. Urakka on tarkemmin kuvattu tarjouspyyntöasiakirjoissa.,','Naantalin kaupunki','ANY',2,1,NULL,NULL,300000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056448','[\"45200000\"]','[\"kunnallistekniikan\", \"perhetalo\", \"vaihe\", \"rakentaminen\", \"urakan\", \"naantalin\", \"hankintalaki\", \"tarjouspyyntöasiakirjoissa\", \"tämä\", \"hankintailmoitus\", \"ilmoitus\", \"tarjouskilpailun\", \"käynnistämisestä\", \"rakennuskohteena\", \"kaupungin\", \"luonnonmaan\", \"saarella\", \"sijaitsevan\", \"asemakaava\", \"alueen\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoi