INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (710,'2026-056447','HILMA','OTHER','OPEN','Hengittävä ja nesteitä läpäisemätön hygieeninen potilastyyny','Hengittävä ja nesteitä läpäisemätön hygieeninen potilastyyny Hankinnan kohteena on Oulun Keskuspesula Oy (Cliini) asiakkailleen (OYS) hankkimat hengittävät ja nesteitä läpäisemättömät hygieeniset potilastyynyt. Tällä hetkellä OYS:ssä on käytössä perinteinen sairaalan perustyyny ja lisäksi osalla on käytössä erillinen muovitettu hygieniapäällinen. Sekä nykyinen tyyny että nykyinen hygieniapäällinen ovat pesun kestäviä tuotteita. Nämä on tarkoitus korvata hankinnan kohteena olevalla hygieenisellä potilastyynyllä, jolla korvataan sekä tyyny ja muovitettu hygieniapäällinen yhdellä tuotteella. Tyynyä ei pestä jatkossa pesulassa. Tyynyn pitää olla nesteitä läpäisemätön, saumat pitää olla kuumaliimatut, jotta se pystytään pesemään ja desinfioimaan paikan päällä sairaalassa pyyhkimällä tyynyn pinta sairaalassa käytettävillä yleispuhdistusaineilla ja desinfektioaineilla. Tyynyn pitää olla myös hengittävä sekä ehkäistä taudinaiheuttajien pääsyn tyynyn sisälle. Potilastyynyjen pääasiallinen käyttö on OYS sairaalan vuodeosastot ja mahdolliset muut yksiköt Oulun Yliopistollisessa sairaalassa. Hankinnan kokonaismääräksi sopimuskaudelle on arvioitu noin 3000 kappaletta. Tilaukset toteutetaan erissä, joista ensimmäisen erän n. 1500 kpl toimitus tulee olla tilaajalla syksyllä 2026 mennessä. Tämä toimitus halutaan pienemmissä erissä, esim. 3 erässä, noin 500 kpl/ vko. Ensimmäisen ison kertaerän jälkeen voi olla pienempiä tilauksia. Loppuerä tulee hankintaan, jos ensimmäisen erän tyynyjen käyttöikä tulee umpeen ennen sopimuskauden umpeutumista. Kilpailutuksessa valitaan yksi (1) toimittaja. Sopimuskausi on määräaikainen 31.12.2030 saakka. Sopimuskausi alkaa syksyllä 2026 tai niin pian kuin mahdollista. Sopimukseen voidaan sisällyttää yhden (1) vuoden optiomahdollisuus.,','Oulun Keskuspesula Oy','ANY',3,5,NULL,NULL,150000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056447','[\"33000000\"]','[\"nesteitä\", \"oulun\", \"tyynyn\", \"hengittävä\", \"läpäisemätön\", \"hankinnan\", \"keskuspesula\", \"hygieniapäällinen\", \"pitää\", \"sairaalassa\", \"ensimmäisen\", \"tulee\", \"hygieeninen\", \"potilastyyny\", \"kohteena\", \"käytössä\", \"sairaalan\", \"muovitettu\", \"nykyinen\", \"tyyny\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056447\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56447\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Hengittävä ja nesteitä läpäisemätön hygieeninen potilastyyny\", \"titleSv\": \"\", \"cpvCodes\": \"33000000\", \"currency\": \"EUR\", \"deadline\": null, \"lowCarbon\": false, \"nutsCodes\": \"FI1D9\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Hankinnan kohteena on Oulun Keskuspesula Oy (Cliini) asiakkailleen (OYS) hankkimat hengittävät ja nesteitä läpäisemättömät hygieeniset potilastyynyt. \\n\\nTällä hetkellä OYS:ssä on käytössä perinteinen sairaalan perustyyny ja lisäksi osalla on käytössä erillinen muovitettu hygieniapäällinen. Sekä nykyinen tyyny että nykyinen hygieniapäällinen ovat pesun kestäviä tuotteita. Nämä on tarkoitus korvata hankinnan kohteena olevalla hygieenisellä potilastyynyllä, jolla korvataan sekä tyyny ja muovitettu hygieniapäällinen yhdellä tuotteella. Tyynyä ei pestä jatkossa pesulassa. Tyynyn pitää olla nesteitä läpäisemätön, saumat pitää olla kuumaliimatut, jotta se pystytään pesemään ja desinfioimaan paikan päällä sairaalassa pyyhkimällä tyynyn pinta sairaalassa käytettävillä yleispuhdistusaineilla ja desinfektioaineilla. Tyynyn pitää olla myös hengittävä sekä ehkäistä taudinaiheuttajien pääsyn tyynyn sisälle.\\n\\nPotilastyynyjen pääasiallinen käyttö on OYS sairaalan vuodeosastot ja mahdolliset muut yksiköt Oulun Yliopistollisessa sairaalassa. Hankinnan kokonaismääräksi sopimuskaudelle on arvioitu noin 3000 kappaletta. Tilaukset toteutetaan erissä, joista ensimmäisen erän n. 1500 kpl toimitus tulee olla tilaajalla syksyllä 2026 mennessä. Tämä toimitus halutaan pienemmissä erissä, esim. 3 erässä, noin 500 kpl/ vko. Ensimmäisen ison kertaerän jälkeen voi olla pienempiä tilauksia. Loppuerä tulee hankintaan, jos ensimmäisen erän tyynyjen käyttöikä tulee umpeen ennen sopimuskauden umpeutumista.\\n\\nKilpailutuksessa valitaan yksi (1) toimittaja. Sopimuskausi on määräaikainen 31.12.2030 saakka. Sopimuskausi alkaa syksyllä 2026 tai niin pian kuin mahdollista. Sopimukseen voidaan sisällyttää yhden (1) vuoden optiomahdollisuus.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": 150000.0, \"expirationDate\": \"2027-03-07T08:04:32.624Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"supplies services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"Steripolar Oy (0603924-8)\", \"innovationConsidered\": false, \"lotResultTotalAmount\": 191180.0, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": \"EUR\", \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOppo