INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (712,'2026-056445','HILMA','RFP','OPEN','Puronsuun perinnebiotooppien raivaaminen ja aitaaminen (Helmi-ohjelma, Jyväskylä)','Puronsuun perinnebiotooppien raivaaminen ja aitaaminen (Helmi-ohjelma, Jyväskylä) Keski-Suomen elinvoimakeskus hankkii Jyväskylässä sijaitsevan Puronsuun perinnebiotooppien kunnostusraivauksen ja aitaamisen laitumeksi kokonaispalveluna syksyllä 2026. Hankinta sisältää vesiuoman ylityksiä varten kahden kulkusillan rakentamisen ja asentamisen. Aidattavana on yksi laidunlohko, joka on kooltaan noin 2,4 ha. Aitauksen pituus on noin 900 m. Raivaukset kohdistuvat pienpuustoon ja pensastoon. Hankinta kuuluu Helmi-elinympäristöohjelman perinnebiotooppiteemaan. Tarjoajan tulee tutustua kohteeseen ennen tarjouksen jättämistä.,','Työllisyys-, kehittämis- ja hallintokeskus','ANY',5,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056445','[\"90722000\"]','[\"puronsuun\", \"perinnebiotooppien\", \"helmi\", \"raivaaminen\", \"aitaaminen\", \"ohjelma\", \"jyväskylä\", \"hankinta\", \"noin\", \"työllisyys\", \"kehittämis\", \"hallintokeskus\", \"keski\", \"suomen\", \"elinvoimakeskus\", \"hankkii\", \"jyväskylässä\", \"sijaitsevan\", \"kunnostusraivauksen\", \"aitaamisen\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/kehakeskus?id=626235&tpk=0c593cb8-e6c3-4ab0-aed8-335eaefbe34a\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056445\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56445\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Puronsuun perinneb