INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (715,'2026-056437','HILMA','OTHER','OPEN','Koululammen puistoalueen perusparannus','Koululammen puistoalueen perusparannus Rakennuskohde sijoittuu Pohjois-Tuusulaan, Jokelan taajama-alueelle. Puisto sijaitsee Opintien ja Riihihaanpolun, lukion ja yläasteen sekä pientaloalueen rajaamalla alueella. Urakka sisältää hankkeen täysin valmiiksi rakentamisen liitteenä olevien suunnitelmien ja asiakirjojen mukaisesti, sisältäen maa-, viher ja vesistörakentamisen sekä valaistuksen uusimisen. Alueen hulevedet imeytetään maaperään ja ohjataan ojien kautta hulevesiverkostoon. Urakka on kokonaishintainen kokonaisurakka, jossa valittu urakoitsija toimii pääurakoitsijana. Urakoitsija laatii kohteista takuuajanhoitosuunnitelman, suunnitelma sekä työn suoritus on pohjauduttava Viherympäristöliiton VKT 2021 julkaisuun. Suunnitelma hyväksytetään Tilaajalla.,','Tuusulan kunta','ANY',2,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056437','[\"45112710\"]','[\"koululammen\", \"puistoalueen\", \"perusparannus\", \"urakka\", \"urakoitsija\", \"suunnitelma\", \"rakennuskohde\", \"sijoittuu\", \"pohjois\", \"tuusulaan\", \"jokelan\", \"taajama\", \"alueelle\", \"puisto\", \"sijaitsee\", \"opintien\", \"riihihaanpolun\", \"lukion\", \"yläasteen\", \"pientaloalueen\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056437\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56437\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Koululammen puistoalueen perusparannus\", \"titleSv\": \"\", \"cpvCodes\": \"45112710\", \"curren