INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (717,'2026-056432','HILMA','RFI','OPEN','TIETOPYYNTÖ: Rautakauppatarvikkeet, pientarvikkeet ja työkalut','TIETOPYYNTÖ: Rautakauppatarvikkeet, pientarvikkeet ja työkalut Senaatti-konserni suunnittelee käynnistävänsä rautakauppatarvikkeiden, pientarvikkeiden ja työkalujen kilpailutuksen syksyllä 2026. Hankinta toteutetaan hankintalain (1397/2016) mukaisena avoimena menettelynä. Tarvikkeita ja työkaluja tullaan hankkimaan tarpeen mukaan sopimustoimittajaksi/-toimittajiksi valitulta. Huomioittehan, että tällä ilmoituksella ei pyydetä tarjouksia, vaan kyse on markkinakartoituksena esitettävästä tietopyynnöstä. Tähän markkinakartoitukseen voi osallistua ainoastaan kirjallisesti jättämällä kirjallisen vastauksen tähän ilmoitukseen. Käsittelemme tähän tietopyyntöön annettuja vastauksia liike- ja ammattisalaisuuksina. Senaatti-kiinteistöt ei maksa korvausta markkinavuoropuheluun osallistumisesta tai tietopyyntöön vastaamisesta.,','Senaatti-kiinteistöt','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056432','[\"44000000\"]','[\"senaatti\", \"tähän\", \"kiinteistöt\", \"tietopyyntö\", \"rautakauppatarvikkeet\", \"pientarvikkeet\", \"työkalut\", \"tietopyyntöön\", \"konserni\", \"suunnittelee\", \"käynnistävänsä\", \"rautakauppatarvikkeiden\", \"pientarvikkeiden\", \"työkalujen\", \"kilpailutuksen\", \"syksyllä\", \"hankinta\", \"toteutetaan\", \"hankintalain\", \"mukaisena\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/senaatti?id=625570&tpk=070f7b8d-ff1f-491b-bee7-be2f781e75f9\", \"name\": \"Procurement Documents\"}, {\"url\": \"http