INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (719,'2026-056427','HILMA','OTHER','OPEN','pXRF-mittalaite / pXRF-analyser','pXRF-mittalaite / pXRF-analyser Geologian tutkimuskeskus pyytää tarjouksia pXRF-mittalaitteesta Hankinnan kohteena on kannettava röntgenfluoresenssianalysaattori (pXRF) geokemialliseen analytiikkaan. Laitetta käytetään kivi-, maaperä- ja kairasydännäytteiden analysointiin. Tarjottavan laitekokonaisuuden on oltava sellaisenaan valmis maastossa ja sisätiloissa tapahtuviin mittauksiin. Toimitusehto toimituksille on DDP GTK:n toimistoon Espoossa, Suomessa, Incoterms 2020. Geologian tutkimuskeskus (in English Geological Survey of Finland) is requesting tenders for pXRF-analyser The object of the procurement is a handheld X-ray fluorescence analyzer (pXRF) for geochemical analytics. The device will be used to analyze rock, soil, and drill core samples. The offered device package must be ready as such for measurements carried out both in the field and indoors. The term of delivery for the Supplies shall be DDP in GTK office in Espoo, Finland, Incoterms 2020.,','Geologian tutkimuskeskus','ANY',6,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056427','[\"38433000\"]','[\"pxrf\", \"analyser\", \"geologian\", \"tutkimuskeskus\", \"finland\", \"mittalaite\", \"incoterms\", \"device\", \"pyytää\", \"tarjouksia\", \"mittalaitteesta\", \"hankinnan\", \"kohteena\", \"kannettava\", \"röntgenfluoresenssianalysaattori\", \"geokemialliseen\", \"analytiikkaan\", \"laitetta\", \"käytetään\", \"kivi\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056427\", 