INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (720,'2026-056425','HILMA','OTHER','OPEN','JÄLKI-ILMOITUS - Helsingin yliopiston Meilahden kampuksen ulkoalueiden hoito','JÄLKI-ILMOITUS - Helsingin yliopiston Meilahden kampuksen ulkoalueiden hoito Helsingin yliopiston kiinteistöpalvelut Oy kilpailutti Helsingin yliopistokonserniin kuuluvien Helsingin yliopiston kiinteistöpalvelut Oy:n (2838529-9) ja Helsingin Yliopistokiinteistöt Oy:n (2267512-1) käyttöön Helsingin Meilahdessa sijaitsevien kiinteistöjen ulkoalueiden puhtaanapito- ja hoitotyöt. Työt käsittävät kiinteistöjen koko tonttialueen, sekä kiinteistön omistajalle kuuluvan puhtaanapitotyön katualueen osalta siinä laajuudessa, kun se on puhtaanapitolaissa määritelty tontin omistajan velvoitteeksi. Työt käsittävät koneellisia ja käsin tehtäviä ulkoaluetöitä. Palvelukuvaus tarjouspyynnön liitteenä (Liite numero 1). Kiinteistöt sijaitsevat osoitteissa: Haartmaninkatu 3 ja Topeliuksenkatu 32. Suuntaa antava kohdekartta tarjouspyynnön liitteenä (Liite numero 2),','Helsingin yliopiston kiinteistöpalvelut Oy','ANY',1,4,NULL,NULL,110000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056425','[\"70000000\"]','[\"helsingin\", \"yliopiston\", \"ulkoalueiden\", \"kiinteistöpalvelut\", \"jälki\", \"ilmoitus\", \"meilahden\", \"kampuksen\", \"hoito\", \"kiinteistöjen\", \"työt\", \"käsittävät\", \"tarjouspyynnön\", \"liitteenä\", \"liite\", \"numero\", \"kilpailutti\", \"yliopistokonserniin\", \"kuuluvien\", \"yliopistokiinteistöt\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056425\", \"name\": \"HILMA Notice\"}]','{\"id\": \"E