INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (721,'2026-056424','HILMA','OTHER','OPEN','Päällystystyöurakka 2026, Hyvinkää','Päällystystyöurakka 2026, Hyvinkää Hankinnan kohteena oli: Hankinnan kohteena on Hyvinkään kaupungin päällystystyöt vuodelle 2026. Vuoden 2026 päällystystyöurakka käsittää eri puolilla Hyvinkään kaupunkia sijaitsevat yleisellä liikenteellä olevat kadut ja tiet sekä muut liikenne- ja piha-alueet. Hankinta toteutetaan yksikköhintaisena kokonaisurakkana. Hankinta on kuvattu tarkemmin tarjouspyynnön liitteellä olevilla asiakirjoilla. Lisäksi työssä tulee noudattaa seuraavia asiakirjoja, joita ei ole liitetty tarjouskyselyyn: Asfaltointityön urakka-asiakirjat 2018, Voimassa olevat Asfalttinormit , Infra 2015 Määrämittausohje ja Voimassa oleva Infra RYL, Suomen kuntatekniikan yhdistyksen julkaisu 1/2013 “Tilapäiset liikennejärjestelyt katu- ja yleisillä alueilla” .,','Hyvinkään kaupunki','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056424','[\"45000000\"]','[\"päällystystyöurakka\", \"hyvinkään\", \"hyvinkää\", \"hankinnan\", \"kohteena\", \"olevat\", \"hankinta\", \"voimassa\", \"infra\", \"kaupungin\", \"päällystystyöt\", \"vuodelle\", \"vuoden\", \"käsittää\", \"puolilla\", \"kaupunkia\", \"sijaitsevat\", \"yleisellä\", \"liikenteellä\", \"kadut\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056424\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56424\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Päällystystyöurakka 2026, Hyvinkää\", \"titleSv\": \"\", \"cpvCodes\": \"45000000\", \"currency\": null,