INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (723,'2026-056423','HILMA','RFI','OPEN','TIPA: Markkinavuoropuhelu tuholaistorjunnan puitesopimukseen','TIPA: Markkinavuoropuhelu tuholaistorjunnan puitesopimukseen Tämä ei ole hankintailmoitus eikä tarjouspyyntö vaan tietopyyntö ja kutsu markkinavuoropuheluun. Ilmoituksessa mainitut hankintamenettelyä, määräaikoja, valintaperustetta, osatarjousten ja vaihtoehtoisten tarjousten hyväksymistä sekä muut hankintaa koskevat tiedot ovat alustavia eivätkä sido hankintayksikköä toteuttamaan suunnitteilla olevaa hankintaa niiden mukaisesti. Tietopyyntö ei sido Jyväskylän kaupunkia eikä hankinnasta kiinnostuneita markkinatoimijoita hankintaan. Tietopyynnön tarkoituksena on kartoittaa markkinatoimijoita ja näiden näkemyksiä Jyväskylän kaupungin tuholaistorjunnan hankinnan mahdollisesta toteuttamisesta. Alustavan suunnitelman mukaan Jyväskylän kaupunki kilpailuttaa \'Tuholaistorjunnan\' hankinnan myöhemmin julkaistavalla tarjouspyynnöllä vuoden 2027 alussa. Tällä ilmoituksella Jyväskylän kaupunki hakee hankinnasta kiinnostuneita toimijoita ilmoittautumaan hankinnan valmistelun osana toteutettaviin teknisiin vuoropuhelutilaisuuksiin. Alustavan suunnitelman mukaan teknisessä vuoropuhelussa on tarkoitus keskustella tuholaistorjunnan teknisestä toteutuksesta, hinnoittelumalleista. Hankintayksikkö lähettää ennakkomateriaalin tekniseen vuoropuheluun osallistuville toimijoille noin viikkoa aiemmin, jotta toimijat voivat valmistautua vuoropuhelussa käsiteltäviin kysymyksiin. Myös markkinatoimijoilla on mahdollisuus esittää kysymyksiä valmisteltavasta hankinnasta hankintayksikölle. Hankintayksikkö pyrkii vastamaan markkinatoimijoiden esittämiin kysymyksiin vuoropuhelun aikana. Tavoitteena on, että hankintayksikkö voi valmistella hankinnasta lopullisen tarjouspyynnön vuoropuheluiden jälkeen. Hankintayksikkö kutsuu ilmoittautuneiden joukosta enintään 2 (kpl) markkinatoimijaa esittäytymään ja keskustelemaan yksitellen valmisteilla olevasta hankinnasta. Mikäli ilmoittautuneita on enemmän, tekninen vuoropuhelu käydään muiden kanssa tarvittaessa sähköpostikyselyn muodossa. Ilmoittautumiset tekniseen vuoropuheluun ja kuvaukset toiminnasta pyydetään lähettämään sähköpostitse osoitteeseen XXX@jyvaskyla.fi xx.xx.202x klo xx.00 mennessä. Teknisten vuoropuheluiden ja hankinnan alustava aikataulu: Viimeinen ajankohta ilmoittautua mukaan tekniseen vuoropuheluun 20.9.2026 klo 23.59 mennessä. Markkinatoimijan tulee esittää kysymyksensä tietopyynnön kohteena olevasta hankinnasta hankintayksikölle viimeistään 14.9.2026 klo 23.59 mennessä. Hankintayksikkö toimittaa ennakkoaineiston tekniseen vuoropuheluun osallistuville 15.9.2026. Teknisen vuoropuhelun 1. neuvottelupäivä (klo 08-11 ja 12-15 välisenä ajankohtana). Mahdollinen hankintamenettely on tarkoitus toteuttaa talvi 2027.,','Jyväskylän kaupunki','ANY',5,15,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056423','[\"90922000\"]','[\"jyväskylän\", \"hankinnasta\", \"tuholaistorjunnan\", \"hankintayksikkö\", \"hankinnan\", \"kaupunki\", \"tekniseen\", \"vuoropuheluun\", \"mukaan\", \"mennessä\", \"tipa\", \"markkinavuoropuhelu\", \"puitesopimukseen\", \"eikä\", \"tietopyyntö\", \"hankintaa\", \"sido\", \"kiinnostuneita\", \"markkinatoimijoita\", \"tietopyynnön\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/jyvaskyla?id=626923&tpk=2dd0ca4d-bb31-465d-944a-22f59b7a1fb9\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056423\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56423\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"TIPA: Markkinavuoropuhelu tuholaistorjunnan puitesopimukseen\", \"titleSv\": \"\", \"cpvCodes\": \"90922000\", \"currency\": null, \"deadline\": \"2026-09-20T20:59:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Tämä ei ole hankintailmoitus eikä tarjouspyyntö vaan tietopyyntö ja kutsu markkinavuoropuheluun. Ilmoituksessa mainitut hankintamenettelyä, määräaikoja, valintaperustetta, osatarjousten ja vaihtoehtoisten tarjousten hyväksymistä sekä muut hankintaa koskevat tiedot ovat alustavia eivätkä sido hankintayksikköä toteuttamaan suunnitteilla olevaa hankintaa niiden mukaisesti. Tietopyyntö ei sido Jyväskylän kaupunkia eikä hankinnasta kiinnostuneita markkinatoimijoita hankintaan. Tietopyynnön tarkoituksena on kartoittaa markkinatoimijoita ja näiden näkemyksiä Jyväskylän kaupungin tuholaistorjunnan hankinnan mahdollisesta toteuttamisesta.\\n\\nAlustavan suunnitelman mukaan Jyväskylän kaupunki kilpailuttaa \'Tuholaistorjunnan\' hankinnan myöhemmin julkaistavalla tarjouspyynnöllä vuoden 2027 alussa.\\n\\nTällä ilmoituksella Jyväskylän kaupunki hakee hankinnasta kiinnostuneita toimijoita ilmoittautumaan hankinnan valmistelun osana toteutettaviin teknisiin vuoropuhelutilaisuuksiin. \\n\\nAlustavan suunnitelman mukaan teknisessä vuoropuhelussa on tarkoitus keskustella tuholaistorjunnan teknisestä toteutuksesta, hinnoittelumalleista. Hankintayksikkö lähettää ennakkomateriaalin tekniseen vuoropuheluun osallistuville toimijoille noin viikkoa aiemmin, jotta toimijat voivat valmistautua vuoropuhelussa käsiteltäviin kysymyksiin. Myös markkinatoimijoilla on mahdollisuus esittää kysymyksiä valmisteltavasta hankinnasta hankintayksikölle. Hankintayksikkö pyrkii vastamaan markkinatoimijoiden esittämiin kysymyksiin vuoropuhelun aikana. Tavoitteena on, että hankintayksikkö voi valmistella hankinnasta lopullisen tarjouspyynnön vuoropuheluiden jälkeen.\\n\\nHankintayksikkö kutsuu ilmoittautuneiden joukosta enintään 2 (kpl) markkinatoimijaa esittäytymään ja keskustelemaan yksitellen valmisteilla olevasta hankinnasta. Mikäli ilmoittautuneita on enemmän, tekninen vuoropuhelu käydään muiden kanssa tarvittaessa sähköpostikyselyn muodossa. \\n\\nIlmoittautumiset tekniseen vuoropuheluun ja kuvaukset toiminnasta pyydetään lähettämään sähköpostitse osoitteeseen XXX@jyvaskyla.fi xx.xx.202x klo xx.00 mennessä.\\n\\nTeknisten vuoropuheluiden ja hankinnan alustava aikataulu:\\n\\nViimeinen ajankohta ilmoittautua mukaan tekniseen vuoropuheluun 20.9.2026 klo 23.59 mennessä.\\n\\nMarkkinatoimijan tulee esittää kysymyksensä tietopyynnön kohteena olevasta hankinnasta hankintayksikölle viimeistään 14.9.2026 klo 23.59 mennessä.\\n\\nHankintayksikkö toimittaa ennakkoaineiston tekniseen vuoropuheluun osallistuville 15.9.2026.\\n\\nTeknisen vuoropuhelun 1. neuvottelupäivä (klo 08-11 ja 12-15 välisenä ajankohtana).\\n\\nMahdollinen hankintamenettely on tarkoitus toteuttaa talvi 2027.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-09-20T20:59:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": null, \"lotResultTotalAmount\": null, \"justWorkingConditions\": null, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": null, \"includesFrameworkAgreement\": null, \"smeParticipationConsidered\": null, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": null, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": null, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"E1\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"TIPA: Markkinavuoropuhelu tuholaistorjunnan puitesopimukseen\", \"titleSv\": \"\", \"cpvCodes\": \"90922000\", \"currency\": null, \"deadline\": \"2026-09-20T20:59:00Z\", \"eFormsId\": \"13c5ba6e-e4e6-41f1-8d5b-fc90763e5adf\", \"isEForms\": true, \"mainType\": \"PriorInformationNotices\", \"noticeId\": 56423, \"lowCarbon\": null, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"isCancelled\": false, \"procedureId\": 36826, \"biodiversity\": null, \"dateModified\": \"2026-09-07T06:13:35.915Z\", \"fullEFormsId\": \"13c5ba6e-e4e6-41f1-8d5b-fc90763e5adf-01\", \"noticeNumber\": \"2026-056423\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2026-09-07T06:13:35.911Z\", \"descriptionEn\": \"\", \"descriptionFi\": \"TIPA: Markkinavuoropuhelu tuholaistorjunnan puitesopimukseen Tämä ei ole hankintailmoitus eikä tarjouspyyntö vaan tietopyyntö ja kutsu markkinavuoropuheluun. Ilmoituksessa mainitut hankintamenettelyä, määräaikoja, valintaperustetta, osatarjousten ja vaihtoehtoisten tarjousten hyväksymistä sekä muut hankintaa koskevat tiedot ovat alustavia eivätkä sido hankintayksikköä toteuttamaan suunnitteilla olevaa hankintaa niiden mukaisesti. Tietopyyntö ei sido Jyväskylän kaupunkia eikä hankinnasta kiinnostuneita markkinatoimijoita hankintaan. Tietopyynnön tarkoituksena on kartoittaa markkinatoimijoita ja näiden näkemyksiä Jyväskylän kaupungin tuholaistorjunnan hankinnan mahdollisesta toteuttamisesta.\\n\\nAlustavan suunnitelman mukaan Jyväskylän kaupunki kilpailuttaa \'Tuholaistorjunnan\' hankinnan myöhemmin julkaistavalla tarjouspyynnöllä vuoden 2027 alussa.\\n\\nTällä ilmoituksella Jyväskylän kaupunki hakee hankinnasta kiinnostuneita toimijoita ilmoittautumaan hankinnan valmistelun osana toteutettaviin teknisiin vuoropuhelutilaisuuksiin. \\n\\nAlustavan suunnitelman mukaan teknisessä vuoropuhelussa on tarkoitus keskustella tuholaistorjunnan teknisestä toteutuksesta, hinnoittelumalleista. Hankintayksikkö lähettää ennakkomateriaalin tekniseen vuoropuheluun osallistuville toimijoille noin viikkoa aiemmin, jotta toimijat voivat valmistautua vuoropuhelussa käsiteltäviin kysymyksiin. Myös markkinatoimijoilla on mahdollisuus esittää kysymyksiä valmisteltavasta hankinnasta hankintayksikölle. Hankintayksikkö pyrkii vastamaan markkinatoimijoiden esittämiin kysymyksiin vuoropuhelun aikana. Tavoitteena on, että hankintayksikkö voi valmistella hankinnasta lopullisen tarjouspyynnön vuoropuheluiden jälkeen.\\n\\nHankintayksikkö kutsuu ilmoittautuneiden joukosta enintään 2 (kpl) markkinatoimijaa esittäytymään ja keskustelemaan yksitellen valmisteilla olevasta hankinnasta. Mikäli ilmoittautuneita on enemmän, tekninen vuoropuhelu käydään muiden kanssa tarvittaessa sähköpostikyselyn muodossa. \\n\\nIlmoittautumiset tekniseen vuoropuheluun ja kuvaukset toiminnasta pyydetään lähettämään sähköpostitse osoitteeseen XXX@jyvaskyla.fi xx.xx.202x klo xx.00 mennessä.\\n\\nTeknisten vuoropuheluiden ja hankinnan alustava aikataulu:\\n\\nViimeinen ajankohta ilmoittautua mukaan tekniseen vuoropuheluun 20.9.2026 klo 23.59 mennessä.\\n\\nMarkkinatoimijan tulee esittää kysymyksensä tietopyynnön kohteena olevasta hankinnasta hankintayksikölle viimeistään 14.9.2026 klo 23.59 mennessä.\\n\\nHankintayksikkö toimittaa ennakkoaineiston tekniseen vuoropuheluun osallistuville 15.9.2026.\\n\\nTeknisen vuoropuhelun 1. neuvottelupäivä (klo 08-11 ja 12-15 välisenä ajankohtana).\\n\\nMahdollinen hankintamenettely on tarkoitus toteuttaa talvi 2027.,\", \"descriptionSv\": \"\", \"isCorrigendum\": false, \"linkedNotices\": \"\", \"procedureType\"