INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (724,'1846a29bc96e59c7','HILMA','OTHER','OPEN','Untitled','','','ANY',10,13,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/1846a29bc96e59c7',NULL,'[\"finland\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/1846a29bc96e59c7\", \"name\": \"HILMA Notice\"}]','{\"noticeId\": 127155, \"@search.score\": 1.0}',40,NULL,'2026-09-07 12:31:28','2026-09-07 12:31:28');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (725,'2021-088776','HILMA','OTHER','OPEN','MRI-laitteen hankittava sydänohjelmisto','Kainuun sosiaali- ja terveydenhuollon kuntayhtymä on hankkinut MRI-laitteen siirron ja päivityksen toimintojen siirron yhteydessä vanhasta sairaalasta uuden sairaalan tiloihin. MRI-laitteiston siirron ja päivityksen yhteydessä laitteistoon ei hankittu valmiutta sydäntutkimuksiin. Sydäntutkimusohjelmiston hankinta mahdollistaa MRI-tutkimustoiminnan käynnistämisen Kainuun keskussairaalassa.','Kainuun sosiaali- ja terveydenhuollon kuntayhtymä','ANY',3,3,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088776','[\"33000000\"]','[\"kainuun\", \"siirron\", \"laitteen\", \"sosiaali\", \"terveydenhuollon\", \"kuntayhtymä\", \"päivityksen\", \"yhteydessä\", \"hankittava\", \"sydänohjelmisto\", \"hankkinut\", \"toimintojen\", \"vanhasta\", \"sairaalasta\", \"uuden\", \"sairaalan\", \"tiloihin\", \"laitteiston\", \"laitteistoon\", \"hankittu\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088776\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88776\", \"type\": 9905, \"cpvCodes\": \"33000000 Lääketieteelliset laitteet, farmaseuttiset valmisteet ja henkilökohtaiseen hygieniaan liittyvät tuotteet\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractAwardNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1D8  FI1D8\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-20T07:30:31.184Z\", \"noticeNumber\": \"2021-088776\", \"projectTitle\": \"MRI-laitteen hankittava sydänohjelmisto\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-20T07:30:31.183Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-04T09:19:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Kainuun sosiaali- ja terveydenhuollon kuntayhtymä\", \"objectDescriptions\": \" \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Sotkamontie 13, H-talo 87300 Kajaani FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62670, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"MRI-LAITTEEN HANKITTAVA SYDÄNOHJELMISTO\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Kainuun sosiaali- ja terveydenhuollon kuntayhtymä on hankkinut MRI-laitteen siirron ja päivityksen toimintojen siirron yhteydessä vanhasta sairaalasta uuden sairaalan tiloihin.  MRI-laitteiston siirron ja päivityksen yhteydessä laitteistoon ei hankittu valmiutta sydäntutkimuksiin. Sydäntutkimusohjelmiston hankinta mahdollistaa MRI-tutkimustoiminnan käynnistämisen Kainuun keskussairaalassa.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": null, \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"2496986-0\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-04T09:19:00Z\"}',40,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (726,'2021-088696','HILMA','RFP','OPEN','SARS-CoV-2:n, influenssa A- ja B-viruksen ja RS-viruksen pikadiagnostiikkaan käytettävät nukleiinihapon osoitukseen perustuvat testit','Hankinnan kohteena ovat SARS-CoV-2:n, influenssa A- ja B-viruksen ja RS-viruksen pikadiagnostiikkaan käytettävät nukleinihapon osoitukseen perustuvat testit HUSLABin ja ISLABin yksiköille. Kyseessä on yhteishankinta, jonka osapuolet on kuvattu tässä tarjouspyynnössä. Tässä tarjouspyynnössä mukana olevista osapuolista käytetään jäljempänä lyhennettä \"Tilaaja\". Testit hankintaan HUSLAB ja ISLAB laboratorioissa oleville GeneXpert (Cepheid), Novodiag (Hologic), Cobas Liat (Roche) laitteistoille sekä ISLABin laboratorioissa oleville Genomera (Abacus diagnostica) laitteistoille. Testien tulee olla CE IVD -merkittyjä nenänielunäytteille. Testihinnan tulee sisältää tarvittavat kasetit ja reagenssit toimituskuluineen. Tarkemmin hankinta sisältää seuraavien testien hankinnan yllä mainituille laitteistoille: InfA/B/RSV- nukleiinihapon osoitus, SARS-CoV2- nukleiinihapon osoitus, InfA/B/RSV/SARS CoV2- nukleiinihapon osoitus. Hankinta on jaettu neljään osa-alueeseen: 1. SARS-CoV-2:n, influenssa A- ja B-viruksen ja RS-viruksen pikadiagnostiikkaan käytettävät nukleinihapon osoitukseen perustuvat testit GeneXpert (Cepheid) laitteistolle (HUSLAB ja ISLAB) 2. SARS-CoV-2:n, influenssa A- ja B-viruksen ja RS-viruksen pikadiagnostiikkaan käytettävät nukleinihapon osoitukseen perustuvat testit Novodiag (Hologic)- laitteistolle (HUSLAB ja ISLAB) 3. SARS-CoV-2:n, influenssa A- ja B-viruksen ja RS-viruksen pikadiagnostiikkaan käytettävät nukleinihapon osoitukseen perustuvat testit Cobas Liat (Roche) - laitteistolle (HUSLAB ja ISLAB) 4. SARS-CoV-2:n, influenssa A- ja B-viruksen ja RS-viruksen pikadiagnostiikkaan käytettävät nukleiinihapon osoitukseen perustuvat testit Genomera (Abacus diagnostica) - laitteistolle (ISLAB) Osa-alueisiin 1 ja 3 sisältyy lisäksi mahdollisuus hankkia optiolaitteita. Kaikki osa-alueet vertaillaan erikseen, eli toimittajan ei tarvitse tarjota testiä kaikille mainituille osa-aluille. Tarjoaja voi tehdä kullekkin osa-alueelle enintään yhden tarjouksen. Osa-alueen sisäiset osatarjoukset ovat sallittuja. Rinnakkaisten tarjousten tekeminen ei ole sallittua. Hankinnasta tehdään sopimus kahden (2) vuoden sopimuskaudelle. Sopimusta voidaan (osa-aluekohtaisesti) jatkaa kahdella yhden vuoden mittaisella optiokaudella (1+1). Sopimuskausi alkaa, kun molemmat osapuolet ovat allekirjoittaneet sopimuksen. Hankinnan kohde ja sitä koskevat vaatimukset on kuvattu yksityiskohtaisesti tarjouspyynnössä ja sen liitteissä.','Helsingin ja Uudenmaan Sairaanhoitopiirin kuntayhtymä','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088696','[\"33696500\", \"38000000\", \"33696500\", \"33696500\", \"38000000\", \"33696500\", \"33000000\"]','[\"viruksen\", \"sars\", \"testit\", \"influenssa\", \"pikadiagnostiikkaan\", \"käytettävät\", \"osoitukseen\", \"perustuvat\", \"nukleiinihapon\", \"islab\", \"nukleinihapon\", \"huslab\", \"laitteistolle\", \"hankinnan\", \"ovat\", \"tarjouspyynnössä\", \"laitteistoille\", \"osoitus\", \"islabin\", \"osapuolet\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088696\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88696\", \"type\": 200, \"cpvCodes\": \"33696500 Laboratorioreagenssit 38000000 Laboratoriolaitteet, optiset ja tarkkuuslaitteet (lukuun ottamatta silmälaseja) 33696500 Laboratorioreagenssit 33696500 Laboratorioreagenssit 38000000 Laboratoriolaitteet, optiset ja tarkkuuslaitteet (lukuun ottamatta silmälaseja) 33696500 Laboratorioreagenssit 33000000 Lääketieteelliset laitteet, farmaseuttiset valmisteet ja henkilökohtaiseen hygieniaan liittyvät tuotteet\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1  FI1  FI1  FI1  FI1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-22T08:00:22.864Z\", \"noticeNumber\": \"2021-088696\", \"projectTitle\": \"SARS-CoV-2:n, influenssa A- ja B-viruksen ja RS-viruksen pikadiagnostiikkaan käytettävät nukleiinihapon osoitukseen perustuvat testit \", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-19T11:00:14.262Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-17T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 248-655664\", \"organisationName\": \"Helsingin ja Uudenmaan Sairaanhoitopiirin kuntayhtymä\", \"objectDescriptions\": \"SARS-CoV-2:n, influenssa A- ja B-viruksen ja RS-viruksen pikadiagnostiikkaan käytettävät nukleinihapon osoitukseen perustuvat testit GeneXpert (Cepheid) laitteistolle Osa-alue 1: SARS-CoV-2:n, influenssa A- ja B-viruksen ja RS-viruksen pikadiagnostiikkaan käytettävät nukleiinihapon osoitukseen perustuvat testit  GeneXpert (Cepheid), -laitteistolle tarjouspyynnön ja sen liitteiden mukaisesti HUSLABille ja ISLABille.   Tilaaja valitsee yhden (1) toimittajan, jonka kanssa se tekee sopimuksen. SARS-CoV-2:n, influenssa A- ja B-viruksen ja RS-viruksen pikadiagnostiikkaan käytettävät nukleinihapon osoitukseen perustuvat testit Novodiag (Hologic)- laitteistolle Osa-alue 2: SARS-CoV-2:n, influenssa A- ja B-viruksen ja RS-viruksen pikadiagnostiikkaan käytettävät nukleinihapon osoitukseen perustuvat testit  Novodiag (Hologic) -laitteistolle tarjouspyynnön ja sen liitteiden mukaisesti HUSLABin ja ISLABin yksiköille.  Tilaaja valitsee yhden (1) toimittajan, jonka k