INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (727,'2021-088663','HILMA','RFP','OPEN','Kajaanin Mamselli -liikelaitoksen ateriakuljetukset 2022 - 2024 (+2)','Kajaanin kaupunki / Kajaanin Mamselli -liikelaitos pyytää tarjoustanne Kajaanin Mamselli -liikelaitoksen (jatkossa Mamselli) ateriakuljetuspalveluista sopimusajalle 1.3.2022- 29.2.2024, jonka jälkeen voidaan tilaajan päätöksellä jatkaa sopimusta alkuperäisin ehdoin kahdella (2) optiovuodella.','Kajaanin kaupunki','ANY',8,3,NULL,NULL,400000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088663','[\"55521200\"]','[\"kajaanin\", \"mamselli\", \"liikelaitoksen\", \"kaupunki\", \"ateriakuljetukset\", \"liikelaitos\", \"pyytää\", \"tarjoustanne\", \"jatkossa\", \"ateriakuljetuspalveluista\", \"sopimusajalle\", \"jonka\", \"jälkeen\", \"voidaan\", \"tilaajan\", \"päätöksellä\", \"jatkaa\", \"sopimusta\", \"alkuperäisin\", \"ehdoin\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088663\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88663\", \"type\": 200, \"cpvCodes\": \"55521200 Ateriakuljetuspalvelut\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1D8  FI1D8\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-22T08:00:20.576Z\", \"noticeNumber\": \"2021-088663\", \"projectTitle\": \"Kajaanin Mamselli -liikelaitoksen ateriakuljetukset 2022 - 2024 (+2)\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-19T08:30:18.505Z\", \"isCorrigendum\": false, \"estimatedValue\": 400000.0, \"expirationDate\": \"2022-01-20T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 248-656696\", \"organisationName\": \"Kajaanin kaupunki\", \"objectDescriptions\": \" Pyydämme tarjousta Mamsellin kuuma- ja kylmäkohteiden ateria- ja erilliskuljetuksista. Kuumakohteiden (Lukio Vuorikatu 2, Seppälän toimipiste ja henkilöstöravintola Kajateria) ja kahviotuotteiden (Net Cafe ja Care Cafe) lähtöpaikka on keittiö Vimpeli. Väinölän ja Kalevan koulujen kuumakuljetus lähtee Keskuskoulun keittiöltä.  Kylmäkuljetuskohteiden (koulut ja päiväkodit) lähtöpaikka on keittiö Lounatuuli. Keittiö Lounatuulesta lähtee sekä ruoka- että välitystuotteita. Näiden lisäksi ruuankuljetuksen mukana kuljetetaan myös esim. lautasliinoja, pesuaineita ja siivouskoneita. Kylmäkuljetuskohteet sijaitsevat Kajaanin kaupungin keskustassa ja sen läheisyydessä. Kaukaisimmat pudotuspaikat ovat taajama-alueen ulkopuolella: Jormuan, Kuluntalahden, Otanmäen ja Vuolijoen kohteet.  Erilliskuljetuksien tarvetta ei voida ennakkoon tarkasti määritellä, koska asiakastarpeita ei tiedetä etukäteen ja erilliskuljetuksen tarve voi tulla äkillisesti. Erilliskuljetukset voidaan tilata ennakkoon esim. viikkoa ennen tilaisuutta, jos kyseinen tilaisuus on ennakkoon tiedossa. Erilliskuljetus voidaan tilata myös seuraavaksi päiväksi tai samalle päivälle, jos esimerkiksi lähtevästä kuormasta on jäänyt puuttumaan palvelukeittiön ruokatuotteita tai asiakkaalta tulee nopealla aikataululla tilaus.    Keittiö Vimpelistä lähtevät erilliskuljetukset kohdistuvat tällä hetkellä eniten Kaukametsän ravintoloiden ja Kaukaveden  tilaamiin kuljetuksiin. Keittiö Lounatuulesta erilliskuljetuksia tilataan päiväkoteihin ja kouluille. Erilliskuljetuksia voidaan tilata myös keittiö Foxista lähteviin kahvitilauksiin esim. lukio Vuorikatu 2, Taito 2 ja Seppälän toimipisteen eri kahvitilauksiin (esim. erilaiset hallit) tarvittavat tuotteet kuljetetaan  erilliskuljetuksena Seppälän palvelukeittiöstä.   Siivouskoneiden kuljettaminen siivouskohteesta toiseen ajetaan erilliskuljetuksena tarvittaessa.  Erilliskuljetuksista on enemmän liitteessä 2 Ateriakuljetuspalvelut.  Tarkemmin hankinnan taustaa on kuvattu: - Liite 1. Palvelutarpeen kokonaiskuva - Liite 2. Ateriakuljetuspalvelut - Liite 3. Mamsellin toimipisteet \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Pohjolankatu 13 87100 Kajaani FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62594, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"KAJAANIN MAMSELLI -LIIKELAITOKSEN ATERIAKULJETUKSET 2022 - 2024 (+2)\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Kajaanin kaupunki / Kajaanin Mamselli -liikelaitos pyytää tarjoustanne Kajaanin Mamselli -liikelaitoksen (jatkossa Mamselli) ateriakuljetuspalveluista sopimusajalle 1.3.2022- 29.2.2024, jonka jälkeen voidaan tilaajan päätöksellä jatkaa sopimusta alkuperäisin ehdoin kahdella (2) optiovuodella.  \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0214958-9\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-20T12:00:00Z\"}',40,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (728,'2021-088621','HILMA','OTHER','OPEN','SAP S/4 HANA -lisenssit (käyttöoikeudet)','Hankinnan kohteena olivat Palkeiden taloushallinnon järjestelmän (SAP FICO) SAP S/4 HANA- lisenssit tarjouspyynnössä ja sen liitteissä määritellyn mukaisesti. Valtion talous- ja henkilöstöhallinnon palvelukeskus (Palkeet) toteuttaa teknisen päivityksen SAP-ympäristöönsä lähivuosina tekemällä päivityksen SAP S/4 HANAan. Ensimmäisessä vaiheessa vv. 2022 - 2023 taloushallinnon järjestelmä (SAP FICO) päivitetään SAP S/4 HANAan. Hankintaan ei sisälly lisenssien ylläpitoa. Kyseessä on kertahankinta (ks. tarjouspyynnön liite Hankintasopimus).','Valtion talous- ja henkilöstöhallinnon palvelukeskus Palkeet','ANY',1,13,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088621','[\"48000000\"]','[\"valtion\", \"talous\", \"henkilöstöhallinnon\", \"palvelukeskus\", \"palkeet\", \"hana\", \"lisenssit\", \"taloushallinnon\", \"fico\", \"päivityksen\", \"hanaan\", \"käyttöoikeudet\", \"hankinnan\", \"kohteena\", \"olivat\", \"palkeiden\", \"järjestelmän\", \"tarjouspyynnössä\", \"liitteissä\", \"määritellyn\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088621\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88621\", \"type\": 300, \"cpvCodes\": \"48000000 Ohjelmatuotteet ja tietojärjestelmät\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractAwardNotices\", \"parentId\": 81429, \"lowCarbon\": null, \"nutsCodes\": \" FI  FI\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-21T08:00:21.74Z\", \"noticeNumbe