INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (732,'2021-088972','HILMA','RFI','OPEN','Natiiviröntgenlaitteistot','TP22-003 Natiiviröntgenlaitteistot Seinäjoen keskussairaalan radiologialle ollaan vuoden 2022 aikana uusimassa 1.5 T magneettikuvauslaitteisto, angiografialaitteisto, läpivalaisulaitteisto ja kaksi natiiviröntgenkuvauslaitteistoa. Hankinnoista on valmisteltu kolme tarjouspyyntöluonnosta vaatimusmäärittelyineen. Yksi tarjouspyyntö natiiviröntgenkuvauslaitteistoista, toinen angiografia- ja läpivalaisulaitteistoista ja kolmas 1.5 T magneettikuvauslaitteistosta. Kaikki laitteistot hankitaan vanhojen käytöstä poistuvien laitteistojen tilalle ja uusille laitteistoille remontoidaan laitevaatimusten mukaan tilat vanhoista tiloista. Pyydämme tarjouspyyntöluonnokseen ja sen vaatimusmäärittelyyn kirjallisia kommentteja joko suoraan lisättynä Word-kommentteina kyseiseen tarjouspyyntöluonnokseen tai erilliseen dokumenttiin kommentit koottuina. Kommentit tulee olla tarjouspyyntöluonnoksen mukaan eriteltynä ja kommenteissa tulee ilmoittaa laitteiston tämän hetkinen toimitusaika tilauspäivästä lukien. Jos vaatimuksissa on epäselviä vaatimuksia tai jotkut vaatimukset eivät toteudu tarjolla olevissa laitteistoissa, tulee kommenteissa perustella miksi ja miten vaatimuksia tulisi muokata, jotta se olisi selvempi tai että se tarjolla olevassa laitteistossa toteutuisi. Saadut kommentit perusteluineen otetaan tilanteen mukaan huomioon, kun tarjouspyyntöluonnoksista valmistellaan lopulliset tarjouspyynnöt. Tarjoajilla on mahdollisuus varata enintään 30 minuutin mittainen Teams-esittely kustakin laitteistosta, jota tarjouspyyntöluonnoksen vaatimusten perusteella mahdollisesti tarjottaisiin. Teams-esittely tallennetaan hankintatyöryhmän käyttöön. Kommenttien ja Teams-esittelyn lisäksi on mahdollista lähettää lisämateriaalia ja esittelyvideoita tai linkkejä esittelyvideoihin, joilla esitetään laitteiston teknisiä ja toiminnallisia ominaisuuksia. Jos tarjolla on niin sanottu monitoiminatiiviröntgenkuvauslaitteisto, jolla voidaan perinteisten natiiviröntgentutkimusten lisäksi tehdä kartiokeilatietokonetomografia (KKTT) tutkimuksia ja radiologian läpivalaisututkimuksia kuten defekografiatutkimus, ruokatorven läpivalaisututkimus ja nielemisfunktiotutkimus, voidaan laitteistolle varata oma Teams-esittelyaika sekä toimittaa laitteistosta lisämateriaalia esittelyvideoineen. Monitoiminatiiviröntgenkuvauslaitteistosta saatujen tietojen ja edellä mainituista tarjouspyyntöluonnoksista saatujen kommenttien perusteella, voidaan harkita toisen natiiviröntgenkuvauslaitteiston sijaan tarjouspyyntöä monitoiminatiiviröntgenkuvauslaitteistosta. Kommentit tarjouspyyntöihin ja mahdollinen lisämateriaalia ja esittelyvideoita tai linkkejä esittelyvideoihin, joilla esitetään laitteiston teknisiä ja toiminnallisia ominaisuuksia tulee lähettää 12.1.2022 klo 12.00 mennessä sähköpostilla osoitteeseen antti.pasala@epshp.fi Sähköpostin aihekentässä tulee olla merkintä ”TP22-003 Natiiviröntgenlaitteistot” 30 minuutin mittaisia Teams-esittelyaikoja laitteistokohtaisesti voi varata päiville 3.1., 4.1., 5.1. 10.1., 11.1. tai 12.1.2022 lähettämällä sähköpostin osoitteella jyrki.ruohonen@epshp.fi. Sähköpostin aihekentässä tulee olla merkintä ”TP22-003 Natiiviröntgenlaitteistot”. Sähköpostissa tulee esittää ajat, jolloin esittelyn pito on mahdollista. Esittelyaika vahvistetaan vahvistamalla sähköpostitse tuleva kalenterikutsu, jossa on Teams-kokouslinkki esittelyn pitämiseksi.','Etelä-Pohjanmaan Sairaanhoitopiirin kuntayhtymä','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088972','[\"33111600\"]','[\"tulee\", \"teams\", \"natiiviröntgenlaitteistot\", \"kommentit\", \"mukaan\", \"laitteiston\", \"tarjolla\", \"varata\", \"esittelyn\", \"lisämateriaalia\", \"voidaan\", \"sähköpostin\", \"tarjouspyyntöluonnokseen\", \"tarjouspyyntöluonnoksen\", \"kommenteissa\", \"vaatimuksia\", \"tarjouspyyntöluonnoksista\", \"minuutin\", \"esittely\", \"laitteistosta\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088972\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88972\", \"type\": 101, \"cpvCodes\": \"33111600 Röntgenkuvauslaitteet\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"PriorInformationNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI194  FI194\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-24T08:00:22.097Z\", \"noticeNumber\": \"2021-088972\", \"projectTitle\": \"Natiiviröntgenlaitteistot\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-23T10:35:14.49Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-06-23T10:35:14.49Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 250-659741\", \"organisationName\": \"Etelä-Pohjanmaan Sairaanhoitopiirin kuntayhtymä\", \"objectDescriptions\": \" TP22-003 Natiiviröntgenlaitteistot    Seinäjoen keskussairaalan radiologialle ollaan vuoden 2022 aikana uusimassa 1.5 T magneettikuvauslaitteisto, angiografialaitteisto, läpivalaisulaitteisto ja kaksi natiiviröntgenkuvauslaitteistoa. Hankinnoista on valmisteltu kolme tarjouspyyntöluonnosta vaatimusmäärittelyineen. Yksi tarjouspyyntö natiiviröntgenkuvauslaitteistoista, toinen angiografia- ja läpivalaisulaitteistoista ja kolmas 1.5 T magneettikuvauslaitteistosta. Kaikki laitteistot hankitaan vanhojen käytöstä poistuvien laitteistojen tilalle ja uusille laitteistoille remontoidaan laitevaatimusten mukaan tilat vanhoista tiloista.   Pyydämme tarjouspyyntöluonnokseen ja sen vaatimus