INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (733,'2021-088968','HILMA','OTHER','OPEN','Meriliikenteen ilmoituspalvelu','Hankintayksikkö hankkiin meriliikenteen ilmoituspalvelun, joka perustuu Euroopan parlamentin ja neuvoston asetukseen (EU 2019/1239) eurooppalaisesta merenkulkualan yhdennetystä palveluympäristöstä (jäljempänä EMSW-asetus). Asetus edellyttää, että kukin jäsenvaltio perustaa tietopalvelun, joka kerää yhden ilmoittamisen periaatteella kaikki asetuksen liitteissä mainitut tiedot yhteiseen meriliikenteestä yhteen EU-tasolla harmonisoituun tietojärjestelmään.','Fintraffic Meriliikenteenohjaus Oy','ANY',1,14,NULL,NULL,9400000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088968','[\"60600000\", \"63720000\", \"48000000\", \"72000000\"]','[\"meriliikenteen\", \"asetus\", \"fintraffic\", \"meriliikenteenohjaus\", \"ilmoituspalvelu\", \"hankintayksikkö\", \"hankkiin\", \"ilmoituspalvelun\", \"perustuu\", \"euroopan\", \"parlamentin\", \"neuvoston\", \"asetukseen\", \"eurooppalaisesta\", \"merenkulkualan\", \"yhdennetystä\", \"palveluympäristöstä\", \"jäljempänä\", \"emsw\", \"edellyttää\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088968\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88968\", \"type\": 300, \"cpvCodes\": \"60600000 Vesikuljetukset ja vastaavat palvelut 63720000 Vesiliikenteen tukipalvelut 48000000 Ohjelmatuotteet ja tietojärjestelmät 72000000 Tietotekniset palvelut: neuvonta, ohjelmistojen kehittäminen, Internet ja tuki\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractAwardNotices\", \"parentId\": 74143, \"lowCarbon\": null, \"nutsCodes\": \" FI  FI\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-24T08:00:21.668Z\", \"noticeNumber\": \"2021-088968\", \"projectTitle\": \"Meriliikenteen ilmoituspalvelu\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-23T10:15:11.411Z\", \"isCorrigendum\": false, \"estimatedValue\": 9400000.0, \"expirationDate\": \"2022-06-23T10:15:11.411Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 250-663365\", \"organisationName\": \"Fintraffic Meriliikenteenohjaus Oy\", \"objectDescriptions\": \" Meriliikenteen ilmoituspalveluna toteutetaan tiedonhallintajärjestelmä kansallisena ‘single window’- palveluna kaikille EMSW-asetuksen mukaisille ilmoitusmenettelyille. Rakentamisvaiheessa toteutetaan käytännön tietoteknisen järjestelmän rakentaminen, testaaminen, koulutus ja käyttöönotto. Tiedonvaihtopalvelun kautta alukset tai alusten edustajat antavat satamakäynnin (saapuminen ja lähtö) alusselvitykseen liittyvät ilmoitukset. Lisäksi sen kautta voidaan antaa lastina olevien tavaroiden tulliselvitykseen liittyviä tavarailmoituk-set, jotka välitetään edelleen Tullin UTU-järjestelmään. Hankintaan sisältyy meriliikenteen tilastopalvelu, pienten matkustaja-alusten ilmoituspalvelu, tukipalvelut koko palvelun elinkaaren ajan ja palveluiden jatkokehittäminen. Viranomaisintegraatiot toteutetaan uusien tässä hankkeessa toteuttavien API-rajapintojen kautta.    Hankinta on kuvattu liitteessä 1 hankinnan kohteen kuvaus ja muissa hankinta-asiakirjoissa.  \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Palkkatilanportti 1 00240 Helsinki FI\", \"innovationConsidered\": false, \"procurementProjectId\": 46834, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"MERILIIKENTEEN ILMOITUSPALVELU\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Hankintayksikkö hankkiin meriliikenteen ilmoituspalvelun, joka perustuu Euroopan parlamentin ja neuvoston asetukseen (EU 2019/1239) eurooppalaisesta merenkulkualan yhdennetystä palveluympäristöstä (jäljempänä EMSW-asetus). Asetus edellyttää, että kukin jäsenvaltio perustaa tietopalvelun, joka kerää yhden ilmoittamisen periaatteella kaikki asetuksen liitteissä mainitut tiedot yhteiseen meriliikenteestä yhteen EU-tasolla harmonisoituun tietojärjestelmään.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"2945246-5\", \"tendersOrRequestsToParticipateDueDateTime\": null}',55,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
