INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (747,'2021-089049','HILMA','OTHER','OPEN','Ateriakomponenttien hankinta','Vantaan kaupunki kilpailuttaa Vantaan Tilapalvelut Vantti Oy:lle esivalmisteltujen komponenttien (jäljempänä Tuotteiden) tuottaminen määriteltyihin Vantaan Tilapalvelut Vantti Oy:n ateriapalvelun kohteisiin. Tuotteet koskevat pääruokaa esim. kastikkeet, keitot, kiusaukset ja pastaruoat. Hankintaan ei kuulu lisäkkeet, salaatit tai juomat. Palvelun piiriin kuuluvissa kohteissa saattaa tulla muutoksia sopimuskauden aikana.','Vantaan kaupunki','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-089049','[\"15894200\", \"15894200\"]','[\"vantaan\", \"kaupunki\", \"tilapalvelut\", \"vantti\", \"ateriakomponenttien\", \"hankinta\", \"kilpailuttaa\", \"esivalmisteltujen\", \"komponenttien\", \"jäljempänä\", \"tuotteiden\", \"tuottaminen\", \"määriteltyihin\", \"ateriapalvelun\", \"kohteisiin\", \"tuotteet\", \"koskevat\", \"pääruokaa\", \"esim\", \"kastikkeet\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-089049\", \"name\": \"HILMA Notice\"}]','{\"id\": \"89049\", \"type\": 300, \"cpvCodes\": \"15894200 Valmisateriat 15894200 Valmisateriat\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractAwardNotices\", \"parentId\": 87803, \"lowCarbon\": null, \"nutsCodes\": \" FI1B1  FI1B\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-27T08:00:04.155Z\", \"noticeNumber\": \"2021-089049\", \"projectTitle\": \"Ateriakomponenttien hankinta\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-24T06:40:13.369Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-06-24T06:40:13.369Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 251-666387\", \"organisationName\": \"Vantaan kaupunki\", \"objectDescriptions\": \" Vantaan kaupunki pyytää Vantaan Tilapalvelut Vantti Oy:n puolesta tarjousta esivalmisteltujen komponenttien (jäljempänä Tuotteiden) tuottaminen määriteltyihin Vantaan Tilapalvelut Vantti Oy:n ateriapalvelun kohteisiin. Tuotteet koskevat pääruokaa esim. kastikkeet, keitot, kiusaukset ja pastaruoat. Hankintaan ei kuulu lisäkkeet, salaatit tai juomat. Palvelun piiriin kuuluvissa kohteissa saattaa tulla muutoksia sopimuskauden aikana.   Sopimuksen kesto on määräaikaisena yhden (1) vuoden.  Määräaikaisen sopimuskauden jälkeen sopimus on voimassa toistaiseksi, sopimuksessa mainituin irtisanomsiehdoin. Sopimuksen arvioitu alkamisajankohta on arviolta 01.02.2022. Palvelun aloittamisesta sovitaan Tilaajan kanssa.  Tuotantotapojen muutosten vuoksi tilaaja siirtyy osittain käyttämään valmiimpia elintarvikekomponentteja toiminnassaan. Tarjottavat elintarvikekomponentit on määritelty liitteessä 3.  Tarjoaja vastaa sekä tuotteista että tuotteiden kuljetuksesta ja kuljetuksen tuottamiseen tarvittavasta kalustosta.  Palveluun kuuluvien tuotteiden tarve on arvion mukaan noin 6500 annosta päivässä. Sopimuskauden aikana arvio annosten määrästä voi kasvaa yli 10 000 annokseen päivässä.   Arvioidut Tuotemäärät ja pudotuspaikat (noin 37 kpl) sekä palvelutarpeen arvioidut määrät löytyvät tarjouspyynnön liitteiltä 3 ja 4. Liitettä tullaan päivittämään sopimuskauden aikana tarpeen mukaan.  Hankinnan arvioitu arvo neljälle vuodelle on noin 10 500 000 -12 500 000 euroa.  Tarjouspyynnön liittessä 1 Sopimusluonnos ja  liitteissä 2 Palvelukuvaus esitetään tiedot yksityiskohtaisemmin.  Hankinnan määrät ovat arvioita eivätkä sido Tilaajaa.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"PL 1100 01030 Vantaan kaupunki FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62035, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"ATERIAKOMPONENTTIEN HANKINTA\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Vantaan kaupunki kilpailuttaa Vantaan Tilapalvelut Vantti Oy:lle esivalmisteltujen komponenttien (jäljempänä Tuotteiden) tuottaminen määriteltyihin Vantaan Tilapalvelut Vantti Oy:n ateriapalvelun kohteisiin. Tuotteet koskevat pääruokaa esim. kastikkeet, keitot, kiusaukset ja pastaruoat. Hankintaan ei kuulu lisäkkeet, salaatit tai juomat. Palvelun piiriin kuuluvissa kohteissa saattaa tulla muutoksia sopimuskauden aikana.  \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": true, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0124610-9\", \"tendersOrRequestsToParticipateDueDateTime\": null}',50,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (748,'2021-088887','HILMA','OTHER','OPEN','Järvenpää - IT-konsultointi 2021-2025 (DPS) - Sovellus- ja ohjelmistokehityspalvelut - Ohjelmistorobotiikan ja Integraatioalustan asiantuntijatyö','Hankinnan kohteena oli Järvenpään kaupungin käyttöön tuleva asiantuntijatiimi. Asiantuntijatiimin avulla tuotetaan Järvenpään kaupungille ohjelmistorobotiikan ja integraatioiden asiantuntija-, tuki- ja ylläpitopalveluita. Palvelua tuotetaan ensisijaisesti ohjelmistorobotiikan osalta UiPath-teknologialla ja integraatioiden osalta FRENDS-integraatioalustalla. Järvenpään kaupunki on myös avoin muille ratkaisuille. Muiden teknologioiden mahdollinen hyödyntäminen arvioidaan tapauskohtaisesti valitun toimittajan kanssa. Palvelua tilataan kerrallaan erikseen sovittavaksi määräajaksi. Sopimus tulee voimaan allekirjoitushetkestä ja sopimus on voimassa kaksi (2) vuotta, jonka jälkeen sopimusta on mahdollista jatkaa optiona vuosi kerrallaan enintään kaksi (2) vuotta. Palvelun tulee olla asiakkaan käytössä loppuvuodesta 2021 alkaen. Ajankohtaa tarkennetaan sopimuksen teon yhteydessä. Hankinnan kohde oli kuvattu tarkemmin liitteessä 1 Hankinnan kohteen kuvaus. Vähimmäisvaatimukset oli kuvattu tässä tarjouspyynnössä ja sen liitteissä.','Järvenpään kaupunki','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088887','[\"72000000\"]','[\"järvenpään\", \"ohjelmistorobotiikan\", \"hankinnan\", \"kaupunki\", \"tuotetaan\", \"integraatioiden\", \"palvelua\", \"osalta\", \"kerrallaan\", \"sopimus\", \"tulee\", \"kaksi\", \"vuotta\", \"kuvattu\", \"järvenpää\", \"konsu