INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (750,'2021-088873','HILMA','RFP','OPEN','Kupittaan kärjen kumppanuushanke','Hanke koostuu seuraavista kokonaisuuksista: - Kokonaissuunnitelma: Suunnittelualueelle laadittava innovatiivinen kokonaisratkaisu, jonka pohjalta laaditaan asemakaava ja johon pohjautuen muut kokonaisuudet toteutetaan. - Infrahanke: Infrahanke on taloudellisesti ajateltuna kokonaisuus, jonka osina ovat Helsinginkadun ja -radan ylittävä kansi ja Itäharjun puolelle rakennettava velvoitepysäköintilaitos. - Taito-kampus: Turun kaupungin toimitilahankinta, joka on päätetty sijoittaa suunnittelualueen ytimeen Turun AMK synergiatavoitteiden pohjalta. - Lisähankintamahdollisuudet: Lisähankintamahdollisuudet ovat suunnittelualueella ja/tai sen reuna-alueilla olevia suunniteltavia ja toteutettavia pienempiä töitä, jotka ovat tarpeen tai kannattavia toteuttaa osana tätä hankekokonaisuutta. - Myytävät rakennusoikeudet: Hankkeen yhteydessä allianssin päätoteuttajan tai ryhmittymän muun nimetyn jäsenen tulee sitoutua toteuttamaan osana kokonaissuunnitelman toteutumisen varmistamista tarjoajan tarjouksen mukaisesti kannelle tai sen välittömään läheisyyteen erikseen sovittavalle kaupungin omistamalle maalle rakentamista siten, että se edistää osaltaan kaupunginosan kokonaisvaltaista kehittämistä ja varmistaa kaupungin tavoitteen alueen nopeaksi ja taloudelliseksi toteutumiseksi (mukaan lukien mutta mitään poissulkematta tilaajan tavoitteet; alueen elävä sydän, logistisesti vetovoimainen fiksun liikkumisen keskus jne.). Hanke on kuvattu yksityiskohtaisemmin hankinta-asiakirjoissa. Lisäksi hankintaan sisältyy hankinta-asiakirjoissa (ks. liitteen 16 kohdat 3 ja 4) velvollisuudet, velvoite ja sitoumus. Solmittavaan sopimukseen voivat halutessaan liittyä Turun kaupungin konserniyhteisöt, mikäli konserniyhteisöstä tulee Projektiin kuuluvan kiinteistön tai rakennuksen omistaja. Konserniyhteisöt ovat yhteisöjä, joissa Turun kaupungilla on määräysvalta.','Turun kaupunki','ANY',2,1,NULL,NULL,191000000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088873','[\"71000000\", \"45000000\"]','[\"turun\", \"ovat\", \"kaupungin\", \"hanke\", \"jonka\", \"pohjalta\", \"infrahanke\", \"lisähankintamahdollisuudet\", \"osana\", \"tulee\", \"alueen\", \"hankinta\", \"asiakirjoissa\", \"konserniyhteisöt\", \"kupittaan\", \"kärjen\", \"kumppanuushanke\", \"koostuu\", \"seuraavista\", \"kokonaisuuksista\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088873\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88873\", \"type\": 200, \"cpvCodes\": \"71000000 Arkkitehti-, rakennus-, insinööri- ja tarkastuspalvelut 45000000 Rakennustyöt\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1C1  FI1C1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-24T08:00:15.462Z\", \"noticeNumber\": \"2021-088873\", \"projectTitle\": \"Kupittaan kärjen kumppanuushanke\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-22T12:25:08.001Z\", \"isCorrigendum\": false, \"estimatedValue\": 191000000.0, \"expirationDate\": \"2022-01-31T13:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 250-658741\", \"organisationName\": \"Turun kaupunki\", \"objectDescriptions\": \" Hankinta toteutetaan noudattaen hankintalakia (1397/2016) ja käyttäen neuvottelumenettelyä.  Hankintaprosessi muodostuu neljästä vaiheesta seuraavasti: - osallistumishakemusvaihe (osallistumishakemusten jättäminen) - tarjousvaihe 1 (tarjousvaiheen 1 tarjoukset: projektitiimin nimeäminen ja referenssit) - tarjousvaihe 2 (tarjousvaiheen 2 tarjoukset: alueen kokonaissuunnitelma) - tarjousvaihe 3 (tarjousneuvottelut ja tarjousvaiheen 3 tarjoukset: projektijohto- ja yhteistoimintakyky, kokonaissuunnitelman nopea ja taloudellinen toteutus, infrahankkeen ehdotussuunnitelma ja infrahankkeen kustannustarkastelu sekä palkkio).\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"  Turku FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62721, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"KUPITTAAN KÄRJEN KUMPPANUUSHANKE\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Hanke koostuu seuraavista kokonaisuuksista:  - Kokonaissuunnitelma: Suunnittelualueelle laadittava innovatiivinen kokonaisratkaisu, jonka pohjalta laaditaan asemakaava ja johon pohjautuen muut kokonaisuudet toteutetaan.  - Infrahanke: Infrahanke on taloudellisesti ajateltuna kokonaisuus, jonka osina ovat Helsinginkadun ja -radan ylittävä kansi ja Itäharjun puolelle rakennettava velvoitepysäköintilaitos.  - Taito-kampus: Turun kaupungin toimitilahankinta, joka on päätetty sijoittaa suunnittelualueen ytimeen Turun AMK synergiatavoitteiden pohjalta.  - Lisähankintamahdollisuudet: Lisähankintamahdollisuudet ovat suunnittelualueella ja/tai sen reuna-alueilla olevia suunniteltavia ja toteutettavia pienempiä töitä, jotka ovat tarpeen tai kannattavia toteuttaa osana tätä hankekokonaisuutta.  - Myytävät rakennusoikeudet: Hankkeen yhteydessä allianssin päätoteuttajan tai ryhmittymän muun nimetyn jäsenen tulee sitoutua toteuttamaan osana kokonaissuunnitelman toteutumisen varmistamista tarjoajan tarjouksen mukaisesti kannelle tai sen välittömään läheisyyteen erikseen sovittavalle kaupungin omistamalle maalle rakentamista siten, että se edistää osaltaan kaupunginosan kokonaisvaltaista kehittämistä ja varmistaa kaupungin tavoitteen alueen nopeaksi ja taloudelliseksi toteutumiseksi (mukaan lukien mutta mitään poissulkematta tilaajan tavoitteet; alueen elävä sydän, logistisesti vetovoimainen fiksun liikkumisen keskus jne.).  Hanke on kuvattu yksityiskohtaisemmin hankinta-asiakirjoissa.  Lisäksi hankintaan sisältyy hankinta-asiakirjoissa (ks. liitteen 16 kohdat 3 ja 4) velvollisuudet, velvoite ja sitoumus.  Solmittavaan sopimukseen voivat halutessaan liittyä Turun kaupungin konserniyhteisöt, mikäli konserniyhteisöstä tulee Projektiin kuuluvan kiinteistön tai rakennuksen omistaja. Konserniyhteisöt ovat yhteisöjä, joissa Turun kaupungilla on määräysvalta.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"Turku\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0204819-8\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-31T13:00:00Z\"}',45,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (751,'2021-088865','HILMA','OTHER','OPEN','Nuorten neurologisen kehityksen häiriöt- kurssi läheisten lähipäivillä','Hankinnan kohteena ovat Kansaneläkelaitoksen (Kelan) henkilöasiakkaille järjestettävät nuorten neurologisen kehityksen häiriöt- kurssi läheisten lähipäivillä. Hankinta tehdään valtakunnallisesti ottaen huomioon myös maantieteellisen kattavuuden näkökulma. Kurssit toteutetaan Kansaneläkelaitoksen kuntoutusetuuksista ja kuntoutusrahaetuuksista annetun lain 566/2005 (myöhemmin KKRL tai Kelan kuntoutuslaki) 12 § mukaisena harkinnanvaraisena kuntoutuksena ja 9 ja 10 § mukaisena vaativana lääkinnällisenä kuntoutuksena. Kelan kuntoutujien kuntoutus alkaa 1.1.2022 lukien.','Kansaneläkelaitos','ANY',1,13,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088865','[\"85000000\"]','[\"kelan\", \"nuorten\", \"neurologisen\", \"kehityksen\", \"häiriöt\", \"kurssi\", \"läheisten\", \"lähipäivillä\", \"kansaneläkelaitoksen\", \"mukaisena\", \"kuntoutuksena\", \"kansaneläkelaitos\", \"hankinnan\", \"kohteena\", \"ovat\", \"henkilöasiakkaille\", \"järjestettävät\", \"hankinta\", \"tehdään\", \"valtakunnallisesti\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088865\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88865\", \"type\": 2102, \"cpvCodes\": \"85000000 Terveyspalvelut ja sosiaalitoimen palvelut\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractAwardNotices\", \"parentId\": 68632, \"lowCarbon\": null, \"nutsCodes\": \" FI  FI\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-24T08:00:14.788Z\", \"noticeNumber\": \"2021-088865\", \"projectTitle\": \"Nuorten neurologisen kehityksen häiriöt- kurssi läheisten lähipäivillä\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-22T11:50:07.125Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-06-22T11:50:07.125Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 250-664449\", \"organisationName\": \"Kansaneläkelaitos\", \"objectDescriptions\": \" Nuorten neurologisen kehityksen häiriöt- kurssi läheisten lähipäivillä toteutetaan seuraavan Kelan kuntoutuksen palvelukuvauksen (voimassa 1.1.2022 alkaen) mukaisesti:  Nuorten neurologisen kehityksen häiriöt- kurssi läheisten lähipäivillä, joka jakautuu kahteen osaan eli kuntoutuspalvelun osaan ja yleiseen osaan. Osat on sijoitettu yhteen asiakirjaan peräkkäin ja molemmilla osilla on oma kansilehtensä sekä sisällysluettelonsa (Liite 1).  Hankittava palvelu toteutetaan siten, että alla olevista sairausryhmistä muodostetaan sopimuskaudella kurssit sairausryhmittäin seuraavasti:  • Kehitysvamma, kehityshäiriö tai monivammaisuus (ks. tarkempi erittely palvelukuvauksen kuntoutuspalvelua koskevan osan liitteestä 1 palvelukuvaukseen kuuluvat sairausryhmät ja diagnoosit) • CP-oireyhtymä tai muu synnynnäinen liikuntavammaisuus • Downin oireyhtymä   Kurssit muodostetaan yllä mainitun sairausryhmäjaon mukaan. Palveluntuottajalla on oltava valmius tuottaa kaikkia yllä mainittujen sairausryhmien kuntoutusta. Kela ilmoittaa palveluntuottajille, miten kurssit toteutetaan kuntoutuspalvelun mukaisille sairausryhmille sopimuskauden aikana.  Jokaisesta tarjottavasta toimipisteestä (laitosyksikkö)  on tehtävä oma erillinen tarjous. Tarjoaja voi antaa samasta toimipisteestä vain yhden tarjouksen. Kyseessä katsotaan olevan yksi toimipiste, vaikka tiloihin olisi olemassa kaksi eri osoitetta, mutta tosiasiasiallisesti kyseessä on kuitenkin sama toimipiste (esim. sisäänkäynnit kahdelta eri kadulta). \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Nordenskiöldinkatu 12 00250 Helsinki FI\", \"innovationConsidered\": false, \"procurementProjectId\": 50287, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"NUORTEN NEUROLOGISEN KEHITYKSEN HÄIRIÖT- KURSSI LÄHEISTEN LÄHIPÄIVILLÄ\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Hankinnan kohteena ovat Kansaneläkelaitoksen (Kelan) henkilöasiakkaille järjestettävät nuorten neurologisen kehityksen häiriöt- kurssi läheisten lähipäivillä.  Hankinta tehdään valtakunnallisesti ottaen huomioon myös maantieteellisen kattavuuden näkökulma.  Kurssit toteutetaan Kansaneläkelaitoksen kuntoutusetuuksista ja kuntoutusrahaetuuksista annetun lain 566/2005 (myöhemmin KKRL tai Kelan kuntoutuslaki) 12 § mukaisena harkinnanvaraisena kuntoutuksena ja 9 ja 10 § mukaisena vaativana lääkinnällisenä kuntoutuksena. Kelan kuntoutujien kuntoutus alkaa 1.1.2022 lukien.  \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": true, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0246246-0\", \"tendersOrRequestsToParticipateDueDateTime\": null}',50,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (752,'2021-089127','HILMA','RFP','OPEN','Näytekuljetusten lämpötilaseuranta','Hankinnan kohteena on Satakunnan sairaanhoitopiirin kuntayhtymän liikelaitoksen SataDiagin laboratorion näytekuljetusten lämpötilaseurantajärjestelmä.','Satakunnan Sairaanhoitopiirin kuntayhtymä','ANY',5,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-089127','[\"38000000\", \"38000000\"]','[\"satakunnan\", \"sairaanhoitopiirin\", \"näytekuljetusten\", \"kuntayhtymä\", \"lämpötilaseuranta\", \"hankinnan\", \"kohteena\", \"kuntayhtymän\", \"liikelaitoksen\", \"satadiagin\", \"laboratorion\", \"lämpötilaseurantajärjestelmä\", \"finland\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-089127\", \"name\": \"HILMA Notice\"}]','{\"id\": \"89127\", \"type\": 9902, \"cpvCodes\": \"38000000 Laboratoriolaitteet, optiset ja tarkkuuslaitteet (lukuun ottamatta silmälaseja) 38000000 Laboratoriolaitteet, optiset ja tarkkuuslaitteet (lukuun ottamatta silmälaseja)\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI196  FI196\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-22T11:26:53.395Z\", \"noticeNumber\": \"2021-089127\", \"projectTitle\": \"Näytekuljetusten lämpötilaseuranta\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-22T11:26:53.394Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-24T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Satakunnan Sairaanhoitopiirin kuntayhtymä\", \"objectDescriptions\": \" Hankinnan kohteena on lämpötilaseurantajärjestelmä kliinisen laboratorion näytteiden ja/tai verituotteiden kuljetuslämpötilan seurantaan.  Mittauksen suorittava laite tullaan sijoittamaan samaan tilaan kuljetettavan materiaalin kanssa. Laite mittaa lämpötilaa kuljetuksen aikana automaattisesti määrätyin väliajoin sekä tallentaa tai lähettää reaaliaikaisena lämpötilatietoa seurantaohjelmaan. Mittalaite vertaa mitattua lämpötilaa etukäteen asiakkaan määrittele-miin lämpötilarajoihin. Kuljetuksen vastaanottajan pitää havaita reaaliaikaisesti laitteesta, mikäli sallitut lämpötilarajat ovat kuljetuksen aikana rikkoutuneet. Järjestelmän ja laitteiden on oltava käytettävissä 24/7 keskeytyksettä. Järjestelmä hankitaan kokonaispalvelusopimuksena.   Hankinta kattaa viisikymmentä (50) mittalaitetta, 2-3 mahdollisesti tarvittavaa tukiasemaa ja käyttöoikeu-den laitteiden seurantaohjelmaan.   Hankinta kattaa hankittavien laitteiden ja ohjelmistojen käyttökoulutuksen.  Tarkemmat edellytettävät ominaisuudet on lueteltu liitteessä 1.  Tarjousten vertailuun otetaan mukaan vain ne tarjoukset, jotka sisältävät hankinnan kohteeksi luetellut kohdat ja täyttävät kaikki liitteessä 1 luetellut ominaisuudet.  Tarjottujen järjestelmien ominaisuudet tullaan pisteyttämään liitteessä 2 esitetyllä tavalla. Eniten pisteitä saanut tarjous valitaan.  Hankinnan kohde ja sitä koskevat vaatimukset on kuvattu yksityiskohtaisesti seuraavissa liitteissä: -\\tEhdottomat vaatimukset (Liite 1) -\\tVertailuperusteet (Liite 2) -\\tSopimusluonnos (Liite 3) -\\tJulkisten hankintojen yleiset sopimusehdot JYSE 2014 Tavarat\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Sairaalantie 3 28500 Pori FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62901, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"NÄYTEKULJETUSTEN LÄMPÖTILASEURANTA\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Hankinnan kohteena on Satakunnan sairaanhoitopiirin kuntayhtymän liikelaitoksen SataDiagin laboratorion näytekuljetusten lämpötilaseurantajärjestelmä.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": null, \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0825915-6\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-24T12:00:00Z\"}',55,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
