INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (756,'2021-089097','HILMA','RFP','OPEN','Suojavaatteet opiskelijoille ja henkilökunnalle','Tarjouskilpailun kohteena ovat SASKY koulutuskuntayhtymän opiskelijoille ja henkilöstölle kustantamat suojavaatteet.','SASKY Koulutuskuntayhtymä','ANY',6,5,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-089097','[\"18830000\"]','[\"sasky\", \"suojavaatteet\", \"opiskelijoille\", \"koulutuskuntayhtymä\", \"henkilökunnalle\", \"tarjouskilpailun\", \"kohteena\", \"ovat\", \"koulutuskuntayhtymän\", \"henkilöstölle\", \"kustantamat\", \"finland\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-089097\", \"name\": \"HILMA Notice\"}]','{\"id\": \"89097\", \"type\": 9902, \"cpvCodes\": \"18830000 Suojajalkineet\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI  FI\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-22T09:39:56.747Z\", \"noticeNumber\": \"2021-089097\", \"projectTitle\": \"Suojavaatteet opiskelijoille ja henkilökunnalle\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-22T09:39:56.746Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-31T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"SASKY Koulutuskuntayhtymä\", \"objectDescriptions\": \" Tarjouskilpailun kohteena ovat SASKY koulutuskuntayhtymän opiskelijoille ja henkilöstölle kustantamat suojavaatteet.  Hankinta tehdään avointa menettelyä noudattaen, ja se on luonteeltaan puitehankinta. Hankintaan ei sisälly enimmäis- tai vähimmäisostovelvoitetta.   Hinnoittelulomakkeella (liite 1) ilmoitettuja määriä tullaan käyttämään vain vertailussa. Määrät ovat suuntaa antavia, eivätkä sellaisenaan Saskya sitovia   Hankinta sisältää opiskelijoille hankittavat suojavaatteet. Saman sopimuksen puitteissa hankitaan myös henkilöstön tarvitsemat suojavaatteet.   Käytössä oleva suojavaatteet voivat myös vaihtua toimittajan mallistojen muuttuessa, suojavaatteiden laatu ei saa muuttua malliston muuttuessa.  Sopimus tehdään yhden toimittajan kanssa, varsinainen sopimuskausi 1.3.2022-31.12.2024. Kaikkiin opetuspisteisiin hankittavat määrät vahvistuvat vuosittain opiskelijavalinnan perusteella. Opetusaloilla tapahtuvat muutokset voivat johtaa lisätilauksiin. Mahdolliset lainsäädännölliset muutokset voivat vaikuttaa ostomääriin.  Vuosittaiset tilausmäärät vaihtelevat riippuen koulutettavien määrästä ja mahdollisista muutoksista koulutusohjelmissa. Nyt kun opintojen aloittaminen voi tapahtua joustavasti, suojavaatteita tullaan tilaamaan vuoden aikana pienimissäkin erissä, jopa yksittäisiä kappaleita, vaikka pääpaino säilyy edelleen elokuun toimituksissa. Pääosa opiskelijoille tulevista suojavaatteista tilataan 1.vuoden opiskelijoille elokuun alussa lukuvuoden alkaessa.   Tilaaja ei sitoudu tarjouspyynnössä ilmoitettuihin määriin.   Sovitukset Tarjoajan on kyettävä järjestämään järjestemään sovitustilaisuus kaikissa opetuspisteissä elokuussa lukuvuoden alussa yhdessä opetuspisteiden kanssa sovittavan aikataulun mukaan ja ottamaan tilaukset vastaan seuraavilla toimipistepaikkakunnilla; Hämeenkyrö, Ikaalinen, Kokemäki, Mänttä-Vilppula, Parkano, Sastamala ja Tampere.  Sovitustilaisuuksissa on oltava tarjolla riittävä koko- ja mallivalikoima. Tarjotuista malleista tulee olla kaikki koot. Sovitustilaisuuksia varten opetuspisteissä laaditaan ryhmäkohtaiset nimilistat, joihin tilattavat suojavaatteet merkitään. Nämä listat on toimitettava kuhunkin opetuspisteeseen laskujen liitteeksi.   Tuotteet tulee toimittajalle viimeistään 1 viikon kuluessa tilauksesta/sovituksesta, sillä opiskelijat tarvitset suojavaatteita heti opetuksen alettua työsaleissa ja työmailla.   Toimintasuunnitelma: Tarjouspyynnössä kerrottujen tietojen perusteella Tarjoajan tulee esittää sovituksesta/tilauksesta/toimituksesta toteutussuunnitelma erillisellä liitteellä, joka sisältää suojavaatteiden sovitusten organisoinnin opetuspisteissä, kuvauksen toimitusten toteutuksesta ja aikataulusta, tilausjärjestelmästä, toimitusvarmuudesta sekä raportoinnista. Raportteihin on kuuluttava ainakin myyntiraportit kuntayhtymätasolla ja opetuspisteittäin, samoin toimitusaikaraportit. Lisäksi selvitys siitä, miten muina aikoina voidaan sovitukset järjestää, esim. myymälä SASKYn toimialueella, postitus, ym \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Ratakatu 36 38210 SASTAMALA FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62884, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"SUOJAVAATTEET OPISKELIJOILLE JA HENKILÖKUNNALLE\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Tarjouskilpailun kohteena ovat SASKY koulutuskuntayhtymän opiskelijoille ja henkilöstölle kustantamat suojavaatteet.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": null, \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0204964-1\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-31T12:00:00Z\"}',40,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
