INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (759,'2021-088557','HILMA','RFP','OPEN','Maankäytön yleissuunnittelun rakenne- ja kalliotekninen puitejärjestely 2022-2024 (2024-2026)','Puitejärjestely muodostuu kahdesta osa-alueesta (1 kalliotekninen yleissuunnittelu ja 2 rakennetekninen yleissuunnittelu). Suunnittelu- ja selvitystoimeksiannot liittyvät maankäytön suunnitteluun pääosin yleiskaava- ja asemakaavatasolla. Puitejärjestelyn osa-alueella 1 kallioteknisen yleissuunnittelun alaisten toimeksiantojen yhteenlaskettu ennakoitu arvo on 2 000 000 € (alv 0 %) ja enimmäisarvo on 2 500 000 € (alv 0 %). Puitejärjestelyn osa-alueella 2 rakenneteknisen yleissuunnittelun alaisten toimeksiantojen yhteenlaskettu ennakoitu arvo on 1 500 000 € (alv 0 %)ja enimmäisarvo on 2 000 000 € (alv 0 %).','Helsingin kaupunki, kaupunkiympäristön toimiala','ANY',5,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088557','[\"71000000\", \"71000000\", \"71000000\"]','[\"yleissuunnittelun\", \"maankäytön\", \"kalliotekninen\", \"puitejärjestely\", \"yleissuunnittelu\", \"puitejärjestelyn\", \"alueella\", \"alaisten\", \"toimeksiantojen\", \"yhteenlaskettu\", \"ennakoitu\", \"arvo\", \"enimmäisarvo\", \"rakenne\", \"muodostuu\", \"kahdesta\", \"alueesta\", \"rakennetekninen\", \"suunnittelu\", \"selvitystoimeksiannot\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088557\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88557\", \"type\": 200, \"cpvCodes\": \"71000000 Arkkitehti-, rakennus-, insinööri- ja tarkastuspalvelut 71000000 Arkkitehti-, rakennus-, insinööri- ja tarkastuspalvelut 71000000 Arkkitehti-, rakennus-, insinööri- ja tarkastuspalvelut\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1B1  FI1B1  FI1B1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-21T08:00:08.895Z\", \"noticeNumber\": \"2021-088557\", \"projectTitle\": \"Maankäytön yleissuunnittelun rakenne- ja kalliotekninen puitejärjestely 2022-2024 (2024-2026)\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-18T09:20:07.96Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-17T09:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 247-653355\", \"organisationName\": \"Helsingin kaupunki, kaupunkiympäristön toimiala\", \"objectDescriptions\": \"Osa-alue 1: Kalliotekninen yleissuunnittelu Kalliotekninen yleissuunnittelu  Osa-alue sisältää maankäytön suunnittelun yhteydessä laadittavien osittain tai kokonaan kalliotiloihin sijoittuvien rakenneteknisten yleissuunnitelmien, tilavaraussuunnitelmien, selvitysten, sekä näihin liittyvien määrä-, kustannus- ja toteutettavuusarvioiden laatimisen ja asiantuntijatehtävät.  Tilattaviin toimeksiantoihin voi kuulua lisäksi maa-, vesi- ja taitorakenteiden, erikoisrakenteiden ja –rakennusten rakenne-, arkkitehti-, taloteknistä sekä palo-, pelastus- ja liikenneteknistä suunnittelua ja asiantuntijatyötä.  Esimerkkejä toimeksiannoista:  - Liikennetunnelin rakenne-, LVIS- ja palotekninen yleissuunnitelma ja tilavaraussuunnitelma - Kalliopysäköintilaitoksen rakennetekninen yleissuunnitelma - Yhdyskuntateknisen huollon tunnelin yleissuunnitelma - Olevien kalliotilojen käyttötarkoituksen muutoksiin liittyvä suunnittelu - Kalliomekaaninen selvitys  Osa-alue 2: Rakennetekninen yleissuunnittelu Rakennetekninen yleissuunnittelu  Osa-alue sisältää maankäytön suunnittelun yhteydessä tarvittavien rakenneteknisten yleissuunnitelmien, toteutettavuusarvioiden, selvitysten, tilavaraussuunnitelmien, vaiheistussuunnitelmien sekä näihin liittyvien määrä- ja kustannusarvioiden laatimisen ja asiantuntijatehtävät.  Toimeksiannot voivat sisältää sekä maanalaisia, että maanpäällisiä rakenteita ja taito-, erikois- ja talonrakennuskohteita.  Tilattaviin toimeksiantoihin voi kuulua lisäksi maa-, vesi- ja kalliorakenteiden, kalliotilojen, erikoisrakenteiden ja –rakennusten rakenne-, arkkitehti-, taloteknistä sekä palo-, pelastus-, raide- ja liikenneteknistä sekä akustista suunnittelua sekä määrä- ja kustannusarvioiden laatimista ja asiantuntijatehtäviä.  Esimerkkejä toimeksiannosta:   - Kansirakenteiden yleissuunnittelu radan tai muun liikenneväylän päälle - Siltavaihtoehtojen ja taitorakenteiden alustava rakennetekninen yleissuunnitelma - Pysäköintilaitoksen rakennetekninen yleissuunnitelma asemakaavoituksen pohjaksi - Olemassa olevien rakenteiden jatkokäytön ja muutosten toteutettavuuden sekä ilmastovaikutusten arviointi\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"PL 58200 00099 Helsingin kaupunki FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62526, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"MAANKÄYTÖN YLEISSUUNNITTELUN RAKENNE- JA KALLIOTEKNINEN PUITEJÄRJESTELY 2022-2024 (2024-2026)\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Puitejärjestely muodostuu kahdesta osa-alueesta (1 kalliotekninen yleissuunnittelu ja 2 rakennetekninen yleissuunnittelu). Suunnittelu- ja selvitystoimeksiannot liittyvät maankäytön suunnitteluun pääosin yleiskaava- ja asemakaavatasolla.  Puitejärjestelyn osa-alueella 1 kallioteknisen yleissuunnittelun alaisten toimeksiantojen yhteenlaskettu ennakoitu arvo on 2 000 000 € (alv 0 %) ja enimmäisarvo on 2 500 000 € (alv 0 %).  Puitejärjestelyn osa-alueella 2 rakenneteknisen yleissuunnittelun alaisten toimeksiantojen yhteenlaskettu ennakoitu arvo on 1 500 000 € (alv 0 %)ja enimmäisarvo on 2 000 000 € (alv 0 %). \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": true, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0201256-6\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-17T09:00:00Z\"}',40,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (760,'2021-088525','HILMA','OTHER','OPEN','40MMX53 HEDP AND 40MMX53 FLASH&BANG AMMUNITION','The procurement involves two (2) types of 40MMX53 AMMUNITIONS. The types and approximate amounts are: - 40 mmx53 HEDP ammunition, amount 42 809 pieces - 40 mmx53 FLASH&BANG ammunition, amount 43 630 pieces - Option 1) 40 mmx53 HEDP ammunition, amount 40 000 - 100 000 pieces - Option 2) 40 mmx53 FLASH&BANG ammunition, amount 40 000 - 100 000 pieces','Puolustusvoimat','ANY',7,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088525','[\"35330000\"]','[\"ammunition\", \"amount\", \"pieces\", \"hedp\", \"flash\", \"bang\", \"types\", \"option\", \"puolustusvoimat\", \"procurement\", \"involves\", \"ammunitions\", \"approximate\", \"amounts\", \"finland\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088525\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88525\", \"type\": 1800, \"cpvCodes\": \"35330000 Ampumatarvikkeet\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractAwardNotices\", \"parentId\": 56202, \"lowCarbon\": null, \"nutsCodes\": \" FI \", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-21T08:00:04.726Z\", \"noticeNumber\": \"2021-088525\", \"projectTitle\": \"40MMX53 HEDP AND 40MMX53 FLASH&BANG AMMUNITION\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-18T05:30:08.646Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-17T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 247-654926\", \"organisationName\": \"Puolustusvoimat\", \"objectDescriptions\": \" \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Hatanpään valtatie 30 33541 Tampere FI\", \"innovationConsidered\": false, \"procurementProjectId\": 42393, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": \"\", \"projectTitleNormalized\": \"40MMX53 HEDP AND 40MMX53 FLASH&BANG AMMUNITION\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"The procurement involves two (2) types of 40MMX53 AMMUNITIONS. The types and approximate amounts are:  -\\t40 mmx53 HEDP ammunition, amount  42 809 pieces -\\t40 mmx53 FLASH&BANG ammunition, amount 43 630 pieces -\\tOption 1) 40 mmx53 HEDP ammunition, amount  40 000 - 100 000 pieces -\\tOption 2) 40 mmx53 FLASH&BANG ammunition, amount  40 000 - 100 000 pieces \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0952029-9\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-17T12:00:00Z\"}',40,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (761,'2021-088742','HILMA','OTHER','OPEN','Kansallisten hankintojen suorahankintailmoitus','Siun sote - Pohjois-Karjalan sosiaali- ja terveyspalvelujen kuntayhtymä on pyytänyt tarjouksia Siun soten diabetespotilaiden käyttöön tulevista monikäyttöisistä NovoPen 5 ja NovoPen Echo -insuliinikynistä sopimuskaudelle 1.12.2021 alkaen, jatkuen toistaiseksi voimassa olevana. Monikäyttöiset insuliinikynät auttavat potilasta muun muassa muistitoiminnon ja annostelutarkkuuden osalta. Kynien muistiin jää annokset ja lisäksi NovoPen Echo insuliinikynällä voi annostella tarvittaessa ½ yksikön välein insuliinia. Monikäyttökynien käyttö on ympäristöystävällisempää, syntyy vähemmän jätettä. Hankittavien monikäyttöisten NovoPen insuliinikynien tarkemmat ehdot sovitaan erikseen tehtävässä kirjallisessa hankintasopimuksessa hankintapäätöksen saatua lainvoiman.','Siun sote - Pohjois-Karjalan sosiaali- ja terveyspalvelujen kuntayhtymä','ANY',3,3,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088742','[\"33000000\"]','[\"novopen\", \"siun\", \"sote\", \"pohjois\", \"karjalan\", \"sosiaali\", \"terveyspalvelujen\", \"kuntayhtymä\", \"echo\", \"kansallisten\", \"hankintojen\", \"suorahankintailmoitus\", \"pyytänyt\", \"tarjouksia\", \"soten\", \"diabetespotilaiden\", \"käyttöön\", \"tulevista\", \"monikäyttöisistä\", \"insuliinikynistä\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088742\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88742\", \"type\": 9905, \"cpvCodes\": \"33000000 Lääketieteelliset laitteet, farmaseuttiset valmisteet ja henkilökohtaiseen hygieniaan liittyvät tuotteet\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractAwardNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1D3  FI1D3\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-17T14:25:40.955Z\", \"noticeNumber\": \"2021-088742\", \"projectTitle\": \"Kansallisten hankintojen suorahankintailmoitus\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-17T14:25:40.954Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-03T16:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Siun sote - Pohjois-Karjalan sosiaali- ja terveyspalvelujen kuntayhtymä\", \"objectDescriptions\": \" \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Tikkamäentie 16 80210 Joensuu FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62657, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"KANSALLISTEN HANKINTOJEN SUORAHANKINTAILMOITUS\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Siun sote - Pohjois-Karjalan sosiaali- ja terveyspalvelujen kuntayhtymä on pyytänyt tarjouksia Siun soten diabetespotilaiden käyttöön tulevista monikäyttöisistä NovoPen 5 ja NovoPen Echo -insuliinikynistä sopimuskaudelle 1.12.2021 alkaen, jatkuen toistaiseksi voimassa olevana.   Monikäyttöiset insuliinikynät auttavat potilasta muun muassa muistitoiminnon ja annostelutarkkuuden osalta. Kynien muistiin jää annokset ja lisäksi NovoPen Echo insuliinikynällä voi annostella tarvittaessa ½ yksikön välein insuliinia. Monikäyttökynien käyttö on ympäristöystävällisempää, syntyy vähemmän jätettä.   Hankittavien monikäyttöisten NovoPen insuliinikynien tarkemmat ehdot sovitaan erikseen tehtävässä kirjallisessa hankintasopimuksessa hankintapäätöksen saatua lainvoiman.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": null, \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"2732095-2\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-03T16:00:00Z\"}',40,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (762,'2021-088499','HILMA','RFP','OPEN','Sovellusvalvontatuote (APM) SaaS-palveluna','Kilpailutuksen tarkoituksena on hankkia Istekille nykyaikainen, tekoälyllä varustettu sovellusvalvontatuote (APM). Termillä APM (Application Performance Monitoring) tarkoitetaan järjestelmän ja sovelluksen suorituskyvyn ja saavutettavuuden monitorointia ja valvontaa. Monitoroinnin ja valvonnan tavoitteena on varmistaa työn kulku, nopeuttaa häiriötilanteista toipumista sekä varmistaa tietojärjestelmien tehokkuus ja jatkuvuus. Mitä kattavammin monitorointi ja valvonta on rakennettu ja mitä paremmin operatiivinten henkilökunta osaa tätä työkaluna käyttää, sitä nopeampaa on virhe- ja häiriötilanteista toipuminen. Valvonnan yhteydessä syntyy analyyseja ja dataa, jota julkaistaan oikeille henkilöille, ryhmille tai työkaluun. Istekillä on asiakasympäristöissään käytössä System Center Operations Manager (SCOM). SCOMilla on valvottu palvelimia ja näiden sisäisiä toimintoja, kuten suorituskykyä, prosesseja, lokeja, ajastuksia ja varmuuskopioita. Järjestelmästä on tuotettu seurantaraportteja ja jatkuvuusarvoja. SCOM järjestelmän lisäksi Istekillä on SquaredUp–liitännäinen, jolla sovellusvalvontaa ja seurantanäkymiä on tehostettu. APM-valvontatuotteen käyttöönotossa ei korvata SCOM-järjestelmää kokonaan. Ensisijaisesti SCOM-järjestelmästä siirretään sovellusvalvonta uuteen APM-tuotteeseen. Myös muita valvontakomponentteja siirretään uuteen tuotteeseen soveltuvin osin.','Istekki Oy','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088499','[\"72000000\"]','[\"scom\", \"sovellusvalvontatuote\", \"järjestelmän\", \"valvonnan\", \"varmistaa\", \"häiriötilanteista\", \"mitä\", \"istekillä\", \"järjestelmästä\", \"siirretään\", \"uuteen\", \"tuotteeseen\", \"istekki\", \"saas\", \"palveluna\", \"kilpailutuksen\", \"tarkoituksena\", \"hankkia\", \"istekille\", \"nykyaikainen\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088499\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88499\", \"type\": 200, \"cpvCodes\": \"72000000 Tietotekniset palvelut: neuvonta, ohjelmistojen kehittäminen, Internet ja tuki\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1  FI1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-20T08:00:17.007Z\", \"noticeNumber\": \"2021-088499\", \"projectTitle\": \"Sovellusvalvontatuote (APM) SaaS-palveluna \", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-17T12:15:07.902Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-27T23:59:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 246-650298\", \"organisationName\": \"Istekki Oy\", \"objectDescriptions\": \" Istekin tavoitteena on hankkia markkinoilla oleva, valmis valvontatuote, joka tuottaa Istekille laadukasta valvontadataa ja helpottaa haastavissa ongelmanselvitystilanteissa. Valvontatuotteen täytyy olla nykyaikainen APM-ominaisuuksilla ja tekoälyllä varustettu valvontatuote. Valvontatuotteen pitää pystyä valvomaan kohteita sekä Istekin on-premises -ympäristössä että eri palveluntarjoajien pilviympäristöissä. Tuote pitää myös pystyä integroimaan Istekin automaatio-, hallinta- sekä toiminnanohjausjärjestelmiin. Tuotteen täytyy tukea kattavaa raportointia, trendien seurantaa ja muokattavia näkymiä. Tuotteen täytyy tukea eri Tier–tukitasoja ja mahdollisuutta määrittää eri organisaatioyksikkökohtaisia hälytyksiä. Hankinnan kohteen tulee täyttää kaikki Istekin vaatimukset, jotka on kuvattu tässä tarjouspyynnössä ja sen liitteissä.  Valvontatuote hankitaan SaaS-palveluna. SaaS-palvelun tulee sisältää valmisohjelmiston uudet versiot, virhekorjaukset, tarvittavat käyttöoikeudet ja tukipalvelu. Hankinnnan kohteena on jatkuvan SaaS-palvelun lisäksi palvelun käyttöönotto sekä valvontatuotteen käyttöön liittyvät erikseen tilattavat asiantuntijapalvelut. Palvelua ei hankita heti kaikille Istekin ympäristössä oleville valvottaville kohteille, vaan myöhemmin täsmentyvinä erinä.   SaaS-palvelun käyttöönottoa varten perustetaan käyttöönottoprojekti, jonka kokonaisvastuu on toimittajalla. Toimittaja liittää tarjoukseensa alustavan projektisuunnitelman, jonka toimittaja viimeistelee ennen käyttöönottoprojektin alkua yhdessä Istekin kanssa. Käyttöönottoprojektin yhtenä tavoitteena on osaamisen siirto siten, että Istekin asiantuntijat voivat ensimmäisten kohteiden käyttöönoton jälkeen itsenäisesti levittää seuraavissa vaiheissa valvontaohjelmiston kaikkiin valvonnan piiriin haluttaviin palveluihin ja ympäristöihin.   Erikseen tilattavia asiantuntijapalveluita voivat olla esimerkiksi seuraavat:  - Toimittaja osallistuu ohjelmiston käytön jatkokehitystarpeiden kartoitukseen, suunnitteluun ja toteutukseen - Toimittaja osallistuu ohjelmiston ja muiden sovellusten ja järjestelmien välisten integraatioiden suunnitteluun ja toteutukseen -Toimittaja osallistuu uusien lisäosien käyttöönottoon -Toimittaja opastaa käytössä, kirjoittaa ohjeistuksia, suunnittelee koulutuksia ja kouluttaa\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"PL 4000 70601 Kuopio FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62479, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"SOVELLUSVALVONTATUOTE (APM) SAAS-PALVELUNA \", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Kilpailutuksen tarkoituksena on hankkia Istekille nykyaikainen, tekoälyllä varustettu sovellusvalvontatuote (APM). Termillä APM (Application Performance Monitoring) tarkoitetaan järjestelmän ja sovelluksen suorituskyvyn ja saavutettavuuden monitorointia ja valvontaa. Monitoroinnin ja valvonnan tavoitteena on varmistaa työn kulku, nopeuttaa häiriötilanteista toipumista sekä varmistaa tietojärjestelmien tehokkuus ja jatkuvuus. Mitä kattavammin monitorointi ja valvonta on rakennettu ja mitä paremmin operatiivinten henkilökunta osaa tätä työkaluna käyttää, sitä nopeampaa on virhe- ja häiriötilanteista toipuminen. Valvonnan yhteydessä syntyy analyyseja ja dataa, jota julkaistaan oikeille henkilöille, ryhmille tai työkaluun.   Istekillä on asiakasympäristöissään käytössä System Center Operations Manager (SCOM). SCOMilla on valvottu palvelimia ja näiden sisäisiä toimintoja, kuten suorituskykyä, prosesseja, lokeja, ajastuksia ja varmuuskopioita. Järjestelmästä on tuotettu seurantaraportteja ja jatkuvuusarvoja. SCOM järjestelmän lisäksi Istekillä on SquaredUp–liitännäinen, jolla sovellusvalvontaa ja seurantanäkymiä on tehostettu. APM-valvontatuotteen käyttöönotossa ei korvata SCOM-järjestelmää kokonaan. Ensisijaisesti SCOM-järjestelmästä siirretään sovellusvalvonta uuteen APM-tuotteeseen. Myös muita valvontakomponentteja siirretään uuteen tuotteeseen soveltuvin osin. \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"2292633-0\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-27T23:59:00Z\"}',70,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (763,'2021-088690','HILMA','RFP','OPEN','OMISTAJANVAIHDOKSEN ASIANTUNTIJAPALVELUT; Jatkis','Savon Yrittäjät on hakenut rahoitusta Jatkis Omistajanvaihdospalvelu -hankkeelle. Kyseessä on ESR-rahoitteinen sekä kuntien rahoittama hanke ajalle 1.1.2022–31.8.2023. Palvelulla tuetaan yrittäjiä ja yrittäjäksi aikovia omistajanvaihdosprosesseissa. Palvelulla autamme yrittäjiä ja yksityishenkilöitä • myymään yrityksen/ liiketoimintaa • ostamaan yrityksen/ liiketoimintaa • sukupolvenvaihdosta suunnittelevia yrittäjiä eli ”luopujia” ja ”jatkajia” Palvelussa yrittäjiä ja yrittäjyyttä suunnittelevia autetaan ymmärtämään myytävän/ostettavan yrityksen tunnuslukuja, määrittelemään yrityksen arvoa tekemällä laaja-alainen yritysanalyysi hyödyntämällä tilinpäätöstietoja sekä suunnittelemaan myynti- ja ostoprosessia; mitä myydään ja miten. Asiakkaille tarjotaan yrityskohtaista neuvontaa sekä kahdenkeskisissä tapaamisissa että ryhmätapaamisissa. Palvelulla turvataan kannattavan yritystoiminnan jatkuminen niin että myyntikuntoisille yrityksille löydetään jatkaja ja että yrittäjän uraa tai yritystoimintansa laajentamista suunnitteleville löydetään sopivia ostokohteita. Palvelulla turvataan yrittäjyyttä koko Pohjois-Savon alueella. Tällöin alueella säilyvät niin työpaikat kuin lähipalvelut.','Savon Yrittäjät ry','ANY',1,7,NULL,NULL,145100.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088690','[\"79400000\"]','[\"palvelulla\", \"yrittäjiä\", \"yrityksen\", \"savon\", \"jatkis\", \"yrittäjät\", \"liiketoimintaa\", \"suunnittelevia\", \"yrittäjyyttä\", \"turvataan\", \"löydetään\", \"alueella\", \"omistajanvaihdoksen\", \"asiantuntijapalvelut\", \"hakenut\", \"rahoitusta\", \"omistajanvaihdospalvelu\", \"hankkeelle\", \"kyseessä\", \"rahoitteinen\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088690\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88690\", \"type\": 9902, \"cpvCodes\": \"79400000 Yrityskonsultointi, johdon konsultointi ja niihin liittyvät palvelut\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1D2  FI1D2\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-17T11:57:58.377Z\", \"noticeNumber\": \"2021-088690\", \"projectTitle\": \"OMISTAJANVAIHDOKSEN ASIANTUNTIJAPALVELUT; Jatkis\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-17T11:57:58.376Z\", \"isCorrigendum\": false, \"estimatedValue\": 145100.0, \"expirationDate\": \"2022-01-02T16:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Savon Yrittäjät ry\", \"objectDescriptions\": \" Hankintayksikkö tukee hankeaikana satoja yritystään myyviä yrittäjiä, yrittäjäksi aikovia yksityishenkilöitä ja yritystoimintaansa yritysostolla laajentavia yrittäjiä omistajanvaihdosprosesseissa. Keskeistä työssä on myytävien ja ostettavien yritysten arvon ja myyntihinnan määrittely, myyntiprosessin suunnittelu, asiakkaiden neuvominen, valmentaminen ja tukeminen omistajanvaihdosprosessien vaiheissa.  Yrityskohtainen neuvonta sisältää: o Yrityskontakteja, niihin liittyvää valmennusta ja neuvontaa, arvonmäärityksiä, työpajatoiminnan vetämistä ja muuta käytännön työtä, joka liittyy omistajanvaihdoksiin maakunnan alueella.  - Tehtävien hoitoon vaaditaan vahvaa kokemusta liike-elämän johtotehtävistä, mikro-, pien- ja keskisuurten yritysten toiminnan ymmärtämistä ja kokemusta niiden kanssa toimimisesta.  - Lisäksi vaaditaan kokemusta yrityskauppojen toteuttamisesta eri kokoisissa yrityksissä ja näiden omistajanvaihdosprosessien kokemusta.   - Asiantuntijatehtävän hoitamisen kannalta välttämätöntä on, että hakijalla on vahvaa kokemusta arvonmääritysten ja rahoitussuunnitelmien laatimisesta eri kokoisissa yrityksissä.   - Asiantuntijapalveluihin on budjetoitu hankeajalle 180 000 €, sisältäen arvonlisäveron 24 %.   - Hankintayksikkö tekee palvelutilauksia tasaisesti koko hankekauden ajan.  - Yrityskohtaiset neuvontapalvelujen kestot vaihtelevat yrityskohtaisesti.   - Palvelutilauksia koordinoi Savon Yrittäjät. Jokaiselle palvelutilauksen tehneelle tehdään alkukartoitus heti palveluun tultaessa. Hankkeen henkilöstö tekee alkukartoituksen, jossa käy ilmi asiakkaan tilanne ja palvelun tarve. Tämän jälkeen Savon Yrittäjien hankehenkilöstö varaa asiakkaalle tapaamisajan palveluntarjoajan kanssa.   - Tarjouksessa voi mainita, mikäli tarjoaja pystyy antamaan neuvontaa myös muulla kuin suomen kielellä.  - Tarjoajan tulee nimetä asiantuntija ja nimetyn henkilön täytyy henkilökohtaisesti vastata tarjottavien palveluiden tuottamisesta.   - Tehtävä hankintasopimus ei sisällä määräostovelvoitetta eikä yksinoikeutta tuotettaviin palveluihin.  - Asiantuntijapalvelut on tarkoitettu pohjoissavolaisille pk-yrityksille sekä yksityishenkilöille, jotka suunnittelevat yrityksen tai liiketoiminnan ostamista (myös sukupolvenvaihdokset). \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Kauppakatu 28 B, 3krs 70100 Kuopio FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62614, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": \"\", \"projectTitleNormalized\": \"OMISTAJANVAIHDOKSEN ASIANTUNTIJAPALVELUT; JATKIS\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Savon Yrittäjät on hakenut rahoitusta Jatkis Omistajanvaihdospalvelu -hankkeelle. Kyseessä on ESR-rahoitteinen sekä kuntien rahoittama hanke ajalle 1.1.2022–31.8.2023. Palvelulla tuetaan yrittäjiä ja yrittäjäksi aikovia omistajanvaihdosprosesseissa.   Palvelulla autamme yrittäjiä ja yksityishenkilöitä •\\tmyymään yrityksen/ liiketoimintaa •\\tostamaan yrityksen/ liiketoimintaa •\\tsukupolvenvaihdosta suunnittelevia yrittäjiä eli ”luopujia” ja ”jatkajia”  Palvelussa yrittäjiä ja yrittäjyyttä suunnittelevia autetaan ymmärtämään myytävän/ostettavan yrityksen tunnuslukuja, määrittelemään yrityksen arvoa tekemällä laaja-alainen yritysanalyysi hyödyntämällä tilinpäätöstietoja sekä suunnittelemaan myynti- ja ostoprosessia; mitä myydään ja miten. Asiakkaille tarjotaan yrityskohtaista neuvontaa sekä kahdenkeskisissä tapaamisissa että ryhmätapaamisissa. Palvelulla turvataan kannattavan yritystoiminnan jatkuminen niin että myyntikuntoisille yrityksille löydetään jatkaja ja että yrittäjän uraa tai yritystoimintansa laajentamista suunnitteleville löydetään sopivia ostokohteita. Palvelulla turvataan yrittäjyyttä koko Pohjois-Savon alueella. Tällöin alueella säilyvät niin työpaikat kuin lähipalvelut.  \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": true, \"smeParticipationConsidered\": true, \"mainsiteplaceWorksDeliveries\": \"Yrityskohtainen neuvonta toteutetaan asiakasyrityksen toiveiden mukaan joko lähitapaamisena tai etätapaamisena. Palveluntarjoaja voi halutessaan kieltäytyä lähitapaamisesta esim.  välimatkan takia.\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0171517-1\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-02T16:00:00Z\"}',45,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (764,'2021-088492','HILMA','RFP','OPEN','Financial management solution for projects','Tampere Universities is currently lacking a comprehensive solution for managing project finances, particularly the finances of externally funded projects (such as projects funded by the EU, national funding agencies or companies). We are looking for a modern, user-friendly, dynamic and modular SaaS solution to serve a variety of needs, in particular: - financial planning and forecasting; - reporting features, including graphical reports. The scope of the financial management system includes externally funded projects, internal core funded projects and budget funding. Internal development projects fall outside of the scope. The scope of the procurement will include the implementation of the solution, support and maintenance services and the further development of the solution. The more specific subject matter of the procurement is described in the appendices.','Tampere University Foundation','ANY',1,3,NULL,NULL,480000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088492','[\"48000000\", \"72000000\"]','[\"projects\", \"solution\", \"funded\", \"financial\", \"tampere\", \"scope\", \"management\", \"finances\", \"externally\", \"funding\", \"internal\", \"development\", \"procurement\", \"university\", \"foundation\", \"universities\", \"currently\", \"lacking\", \"comprehensive\", \"managing\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088492\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88492\", \"type\": 200, \"cpvCodes\": \"48000000 Software package and information systems 72000000 IT services: consulting, software development, Internet and support\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": 83746, \"lowCarbon\": null, \"nutsCodes\": \" FI197  FI197\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-20T08:00:15.719Z\", \"noticeNumber\": \"2021-088492\", \"projectTitle\": \"Financial management solution for projects\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-17T11:15:05.322Z\", \"isCorrigendum\": false, \"estimatedValue\": 480000.0, \"expirationDate\": \"2022-01-27T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 246-650378\", \"organisationName\": \"Tampere University Foundation\", \"objectDescriptions\": \" Tampere Universities is currently lacking a comprehensive solution for managing project finances, particularly the finances of externally funded projects (such as projects funded by the EU, national funding agencies or companies).   We are looking for a modern, user-friendly, dynamic and modular SaaS solution to serve a variety of needs, in particular: - financial planning and forecasting; - reporting features, including graphical reports.  The scope of the financial management system includes externally funded projects, internal core funded projects and budget funding. Internal development projects fall outside of the scope.  The scope of the procurement will include the implementation of the solution, support and maintenance services and the further development of the solution.   The more specific subject matter of the procurement is described in the appendices.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \" 33014 Tampere University FI\", \"innovationConsidered\": false, \"procurementProjectId\": 59329, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"FINANCIAL MANAGEMENT SOLUTION FOR PROJECTS\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Tampere Universities is currently lacking a comprehensive solution for managing project finances, particularly the finances of externally funded projects (such as projects funded by the EU, national funding agencies or companies).   We are looking for a modern, user-friendly, dynamic and modular SaaS solution to serve a variety of needs, in particular: - financial planning and forecasting; - reporting features, including graphical reports.  The scope of the financial management system includes externally funded projects, internal core funded projects and budget funding. Internal development projects fall outside of the scope.  The scope of the procurement will include the implementation of the solution, support and maintenance services and the further development of the solution.   The more specific subject matter of the procurement is described in the appendices.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"2844561-8\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-27T12:00:00Z\"}',60,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (765,'2021-088462','HILMA','OTHER','OPEN','Mikkelin Seudun Matkailupalvelut ry:n operatiivisen toiminnan palveluhankinta sopimuskaudelle 1.6.2022-31.5.2024 + 2 optiovuotta','Mikkelin kaupungin hankintapalvelut kilpailuttaa Mikkelin seudun matkailun kokonaisvaltaisen kehittämisen ja edistämisen palveluhankinnan Mikkelin Seudun Matkailupalvelut ry:n puolesta tällä hankintailmoituksella. Tätä tarjouspyyntöä on edeltänyt markkinavuoropuhelu marraskuussa 2021. Sopimuskausi on 1.6.2022-31.5.2024 + 2 optiovuotta.','Mikkelin kaupunki','ANY',10,3,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088462','[\"63515000\"]','[\"mikkelin\", \"seudun\", \"matkailupalvelut\", \"optiovuotta\", \"operatiivisen\", \"toiminnan\", \"palveluhankinta\", \"sopimuskaudelle\", \"kaupungin\", \"hankintapalvelut\", \"kilpailuttaa\", \"matkailun\", \"kokonaisvaltaisen\", \"kehittämisen\", \"edistämisen\", \"palveluhankinnan\", \"puolesta\", \"tällä\", \"hankintailmoituksella\", \"tätä\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088462\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88462\", \"type\": 300, \"cpvCodes\": \"63515000 Matkailupalvelut\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractAwardNotices\", \"parentId\": 86392, \"lowCarbon\": null, \"nutsCodes\": \" FI1D1  FI1D1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-20T08:00:09.301Z\", \"noticeNumber\": \"2021-088462\", \"projectTitle\": \"Mikkelin Seudun Matkailupalvelut ry:n operatiivisen toiminnan palveluhankinta sopimuskaudelle 1.6.2022-31.5.2024 + 2 optiovuotta\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-17T08:30:06.077Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-06-17T08:30:06.077Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 246-650649\", \"organisationName\": \"Mikkelin kaupunki\", \"objectDescriptions\": \" Hankinnan kohteena ovat operatiiviset toiminnot Mikkelin Seudun Matkailupalvelut ry:lle (MSM ry).   Mikkelin Seudun Matkailupalvelut ry:n (MSM ry) tarkoituksena on kehittää ja edistää Mikkelin seudun matkailun ja vapaa-ajan asutuksen yleisiä edellytyksiä sekä kuntien  ja matkailuelinkeinon yhteistoimintaa. Tarkoituksen toteuttamiseksi yhdistys   1. tuottaa alueesta ja sen matkailupalveluista tiedotus- ja neuvontamateriaalia  monipuolisesti eri kanaviin 2. markkinoi aluetta ja alueen matkailupalveluja kotimaassa ja ulkomailla 3. koordinoi kehittämishankkeita 4. toimii muilla näihin verrattavilla tavoilla alueensa matkailun ja vapaa-ajan  asutuksen edistämiseksi  Yhdistyksen jäseninä on Mikkelin seudun kuntia, yrityksiä, yksityisiä henkilöitä ja  rekisteröityjä yhdistyksiä.   MSM ry on ulkoistanut sopimuskumppanille kaikki yhdistyksen hallinnolliset ja  operatiiviset toiminnot. Sopimuskausi nykyisen palveluntuottajan kanssa on  päättymässä 31.5.2022. Sopimuskaudeksi tulevan kilpailutuksen perusteella  valittavan kumppanin kanssa on suunniteltu 1.6.2022 - 31.5.2024 + 2 optiovuotta.  Sopimuksen sisältö tulee olemaan pääpiirteissään seuraava:  - toimitusjohtajan palvelut  - visitmikkeli -brändin rakentaminen, seudun kattomarkkinointi - markkinointikampanjoiden koordinointi ja toteutus - visitmikkeli.fi sivuston ylläpito ja kehittäminen - digitaalisen ja some-markkinoinnin palvelut - tiivis yhteydenpito ja yhteistyö jäsenyritysten sekä seudun kuntien kanssa - jäsenhankinta - jäsenorganisaatioiden tarvelähtöisten ideoiden jalostaminen kehittämishankkeiksi - seutuesitteiden tuottaminen (suomi, englanti, venäjä ja/tai saksa) - messujen ja muiden markkinointitapahtumien koordinointi - tapahtumamarkkinointi - rajatut neuvontapalvelut (neuvontapisteen pitäminen Mikkelissä määrättyinä aukioloaikoina) - toiminnan raportointi  Tavoitteena on löytää yksi kokonaisuuden hallitseva sopimuskumppani.  Alihankkijoiden käyttö on sallittua.  Tarjouspyyntöä on edeltänyt markkinavuoropuhelu marraskuussa 2021.   Palveluntuottajassa arvostetaan aktiivista kehittämisotetta sekä vahvaa kokonaisnäkemystä matkailupalvelujen tuottamisesta. Palvelukokonaisuuteen  sisältyy EU-projektien rahoitushakemusten laatimista ja projektien hallinnointia. Seudullisen matkailumarkkinoinnin toimintaympäristön ja matkailumarkkinoinnin  tuntemus ja kokemus matkailuneuvonnan järjestämisestä ovat edellytyksiä palvelussa onnistumiselle.   KILPAILUTUSMENETTELY: Hankinta toteutetaan käänteisenä ns. ranskalaisena kilpailutuksena. Tarjouspyynnön ehdot täyttävän kokonaispalvelun korvaus on palveluntuottajalle  enintään 195 000 € (alv 0 %)/vuosi.  Tarjoukset pisteytetään  laadullisesti tarjoajan esittämän toimintasuunnitelman,  tarjoajan henkilöstöresurssien, alan tuntemuksen ja hankeosaamisen perusteella. Pisteytystä varten nimetään työryhmä.   Sopimuksen kokonaisarvo on vastaavasti enintään 780 000 € .    \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"PL 33 50101 Mikkeli FI\", \"innovationConsidered\": false, \"procurementProjectId\": 61057, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"MIKKELIN SEUDUN MATKAILUPALVELUT RY:N OPERATIIVISEN TOIMINNAN PALVELUHANKINTA SOPIMUSKAUDELLE 1.6.2022-31.5.2024 + 2 OPTIOVUOTTA\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Mikkelin kaupungin hankintapalvelut kilpailuttaa Mikkelin seudun matkailun kokonaisvaltaisen kehittämisen ja edistämisen palveluhankinnan Mikkelin Seudun Matkailupalvelut ry:n puolesta tällä hankintailmoituksella. Tätä tarjouspyyntöä on edeltänyt markkinavuoropuhelu marraskuussa 2021. Sopimuskausi on 1.6.2022-31.5.2024 + 2 optiovuotta.     \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"Mikkeli\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0165116-3\", \"tendersOrRequestsToParticipateDueDateTime\": null}',40,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (766,'2021-088458','HILMA','RFP','OPEN','Endoskooppisten tähystyslaitteiden kokonaispalveluhankinta','Sansia Oy pyytää tarjoustanne Pohjois-Karjalan sosiaali- ja terveyspalveluiden kuntayhtymälle endoskooppisista tähystyslaitteista kokonaispalveluna konservatiivisen palvelualueen Vatsakeskuksen tähystysyksikköön alla mainituilla tiedoilla ja ominaisuuksilla toimintakuntoon asennettuna sisältäen integraation sairaalan kuvantallennusjärjestelmiin (Neagen). Hankinta suoritetaan ns. kokonaispalveluhankintana, jossa laitteistot pysyvät toimittajan omistuksessa ja Tilaaja maksaa suoritettavista toimenpiteistä toimenpidehinnan. Toimittaja vastaa laitteiden huollosta, korjauksista, varaosista, kalibroinneista, laitteiden päivittämisestä, vakuuttamisesta, huoltoon liittyvistä kuljetuksista, varalaitteista sekä muista mahdollisista huolto-/korjaustoiminnasta aiheutuvista kuluista sopimuskauden ajan.','Sansia Oy','ANY',3,7,NULL,NULL,1900000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088458','[\"33168000\", \"33168000\"]','[\"sansia\", \"laitteiden\", \"endoskooppisten\", \"tähystyslaitteiden\", \"kokonaispalveluhankinta\", \"pyytää\", \"tarjoustanne\", \"pohjois\", \"karjalan\", \"sosiaali\", \"terveyspalveluiden\", \"kuntayhtymälle\", \"endoskooppisista\", \"tähystyslaitteista\", \"kokonaispalveluna\", \"konservatiivisen\", \"palvelualueen\", \"vatsakeskuksen\", \"tähystysyksikköön\", \"alla\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088458\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88458\", \"type\": 200, \"cpvCodes\": \"33168000 Endoskopia- ja tähystyskirurgialaitteet 33168000 Endoskopia- ja tähystyskirurgialaitteet\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1D2  FI1D3\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-20T08:00:08.937Z\", \"noticeNumber\": \"2021-088458\", \"projectTitle\": \"Endoskooppisten tähystyslaitteiden kokonaispalveluhankinta\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-17T08:10:06.504Z\", \"isCorrigendum\": false, \"estimatedValue\": 1900000.0, \"expirationDate\": \"2022-01-17T10:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 246-649229\", \"organisationName\": \"Sansia Oy\", \"objectDescriptions\": \" Pyydämme tarjoustanne Pohjois-Karjalan sosiaali- ja terveyspalveluiden kuntayhtymälle endoskooppisista tähystyslaitteista konservatiivisen palvelualueen Vatsakeskukseen alla mainituilla tiedoilla ja ominaisuuksilla toimintakuntoon asennettuna sisältäen integraation sairaalan kuvantallennusjärjestelmään (Neagen).  Sopimuksen aloitus 1.5.2022, sopimusaika 5 vuotta.  Veloitus kokonaispalvelusta tapahtuu neljännesvuosittain etukäteen arvioitujen toimenpidemäärien mukaan eritellen. Laskutus tasataan kerran vuodessa. Tämänhetkinen arvio toimenpiteiden määrästä on n. 6300 kpl vuodessa, johon sisältyy noin 2500 kpl gastroskopiaa ja noin 3500 kpl kolonoskopiaa ja kolorektaalisyövän väestöseulontaa noin 300 kpl/v.  Siun sote ei sitoudu yllä mainittuihin määriin, todellisuus voi olla suurempi tai pienempi ja ennakkolaskutus tasataan kerran vuodessa toteutuneiden skopioiden mukaan.  Osatarjouksia ei hyväksytä.  Vaihtoehtoiset tarjoukset eivät ole sallittuja.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"PL 2000, Viestikatu 3 70600 Kuopio FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62458, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"ENDOSKOOPPISTEN TÄHYSTYSLAITTEIDEN KOKONAISPALVELUHANKINTA\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Sansia Oy pyytää tarjoustanne Pohjois-Karjalan sosiaali- ja terveyspalveluiden kuntayhtymälle endoskooppisista tähystyslaitteista kokonaispalveluna konservatiivisen palvelualueen Vatsakeskuksen tähystysyksikköön alla mainituilla tiedoilla ja ominaisuuksilla toimintakuntoon asennettuna sisältäen integraation sairaalan kuvantallennusjärjestelmiin (Neagen).  Hankinta suoritetaan ns. kokonaispalveluhankintana, jossa laitteistot pysyvät toimittajan omistuksessa ja Tilaaja maksaa suoritettavista toimenpiteistä toimenpidehinnan. Toimittaja vastaa laitteiden huollosta, korjauksista, varaosista, kalibroinneista, laitteiden päivittämisestä, vakuuttamisesta, huoltoon liittyvistä kuljetuksista, varalaitteista sekä muista mahdollisista huolto-/korjaustoiminnasta aiheutuvista kuluista sopimuskauden ajan.   \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"Vatsakeskus\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"2364760-8\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-17T10:00:00Z\"}',40,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (767,'2021-088379','HILMA','RFP','OPEN','Tekoniveljärjestelmät','Tuomi Logistiikka Oy kilpailuttaa Coxa Oy:n ja Pshp:n toimeksiannosta tekoniveljärjestelmät. Osista 1-9 tehdään hankintasopimus toimittajan ja Coxa Oy:n välillä. Murtumahoidossa käytettävä lonkkatekonivel tulee myös Tays:n käyttöön, joten tarjouspyynnön osasta 9 tehdään sopimus myös toimittajan ja Tuomi Logistiikan välillä. Hankintapäätöksen tekee Coxa Oy kaikkien tilaajien puolesta. Sopimus on voimassa 24 kuukautta, jonka jälkeen se jatkuu toistaiseksi voimassa olevana optiona. Sopimus tullaan kilpailuttamaan uudelleen arviolta neljän - viiden vuoden kuluttua sopimuskauden alkamisesta. Sopimuksen arvioitu alkamisajankohta on heinäkuu 2022. Sopimuksen arvioitu kokonaisarvo on laskettu viidelle vuodelle.','Tuomi Logistiikka Oy','ANY',10,14,NULL,NULL,44000000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088379','[\"33000000\", \"33000000\", \"33000000\", \"33000000\", \"33000000\", \"33000000\", \"33000000\", \"33000000\", \"33000000\", \"33000000\"]','[\"tuomi\", \"logistiikka\", \"coxa\", \"sopimus\", \"tekoniveljärjestelmät\", \"tehdään\", \"toimittajan\", \"välillä\", \"voimassa\", \"sopimuksen\", \"arvioitu\", \"kilpailuttaa\", \"pshp\", \"toimeksiannosta\", \"osista\", \"hankintasopimus\", \"murtumahoidossa\", \"käytettävä\", \"lonkkatekonivel\", \"tulee\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088379\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88379\", \"type\": 200, \"cpvCodes\": \"33000000 Lääketieteelliset laitteet, farmaseuttiset valmisteet ja henkilökohtaiseen hygieniaan liittyvät tuotteet 33000000 Lääketieteelliset laitteet, farmaseuttiset valmisteet ja henkilökohtaiseen hygieniaan liittyvät tuotteet 33000000 Lääketieteelliset laitteet, farmaseuttiset valmisteet ja henkilökohtaiseen hygieniaan liittyvät tuotteet 33000000 Lääketieteelliset laitteet, farmaseuttiset valmisteet ja henkilökohtaiseen hygieniaan liittyvät tuotteet 33000000 Lääketieteelliset laitteet, farmaseuttiset valmisteet ja henkilökohtaiseen hygieniaan liittyvät tuotteet 33000000 Lääketieteelliset laitteet, farmaseuttiset valmisteet ja henkilökohtaiseen hygieniaan liittyvät tuotteet 33000000 Lääketieteelliset laitteet, farmaseuttiset valmisteet ja henkilökohtaiseen hygieniaan liittyvät tuotteet 33000000 Lääketieteelliset laitteet, farmaseuttiset valmisteet ja henkilökohtaiseen hygieniaan liittyvät tuotteet 33000000 Lääketieteelliset laitteet, farmaseuttiset valmisteet ja henkilökohtaiseen hygieniaan liittyvät tuotteet 33000000 Lääketieteelliset laitteet, farmaseuttiset valmisteet ja henkilökohtaiseen hygieniaan liittyvät tuotteet\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": 87298, \"lowCarbon\": null, \"nutsCodes\": \" FI1  FI197  FI197  FI197  FI197  FI197  FI197  FI197  FI197  FI197\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-20T08:00:05.145Z\", \"noticeNumber\": \"2021-088379\", \"projectTitle\": \"Tekoniveljärjestelmät\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-17T06:40:11.79Z\", \"isCorrigendum\": true, \"estimatedValue\": 44000000.0, \"expirationDate\": \"2022-01-10T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 246-650042\", \"organisationName\": \"Tuomi Logistiikka Oy\", \"objectDescriptions\": \"2 Polven osatekonivel Käyttöön valitaan polven mediaalinen osatekonivel. Arvioitu vuosikulutus on 70 kpl. Valittavalla tekonivelmallilla on oltava vähintään 10A ODEP luokitus sekä pitkäaikaisnäyttöä jostakin seuraavista tekonivelrekistereistä: pohjoismaiset rekisterit, Australia tai Englanti. 3 Sementtikiinnitteinen lonkan reisikomponentti Primaariprotetiikkaan valitaan sementtikiinnitteinen femurkomponentti. Arvioitu vuosikulutus on 1500 kpl. Käyttöön valitaan pääjärjestelmä, jonka osalta Coxa sitoutuu vähintään 60% osuuteen primaariprotetiikan kokonaiskulutuksesta. Ominaisuuksiltaan riittävän kattavan tuotevalikoiman takaamiseksi voidaan lisäksi valita enintään kaksi rinnakkaista tuotetta, joiden kulutusmäärää ei ole ennalta asetettu. Tarjouksessa on esitettävä hinnat erikseen sekä pääjärjestelmää että rinnakkaisjärjestelmää koskien. Tarjottavilla tekoniveltuotteilla on oltava vähintään 10A* ODEP luokitus sekä pitkäaikaisnäyttöä jostakin seuraavista tekonivelrekistereistä: pohjoismaiset rekisterit, Australia tai Englanti. 4 Sementitön lonkan primaari tekoniveljärjestelmä Käyttöön valitaan pääjärjestelmä, joka sisältää sementittömät femur- ja  acetabulumkomponentit. Arvioitu vuosikulutus femur komponentin mukaan laskettuna on 1100 kpl. Tekoniveljärjestelmän tuoteperhe voi sisältää useita varsi- ja kuppivaihtoehtoja sekä eri nuppikokoja. Nämä tulee kuvata tarjouksessa. Femur komponenttien suhteen on hyvä, että kokonaisuus sisältää useamman eri design-tyypin tuotteita kattamaan koko potilaskirjon tarpeet. Tuoteperheeseen voi kuulua enintään kolme erilaista femur-tuotetta ja kaksi acetabulum-tuotetta. Acetabulum komponenttiin on oltava saatavilla ns. lukkoliner ominaisuus. Pääjärjestelmän käytössä Coxa sitoutuu vähintään 60% osuuteen tuoteryhmän kokonaiskulutuksesta. Ominaisuuksiltaan riittävän kattavan tuotevalikoiman takaamiseksi voidaan lisäksi valita enintään kaksi rinnakkaista järjestelmää, joiden kulutusmäärää ei ole ennalta asetettu. Tarjouksessa on esitettävä hinnat erikseen sekä pääjärjestelmää että rinnakkaisjärjestelmää koskien. Tarjottavilla tekoniveltuotteilla on oltava vähintään 5A* ODEP luokitus sekä pitkäaikaisnäyttöä jostakin seuraavista tekonivelrekistereistä: pohjoismaiset rekisterit, Australia tai Englanti.  5 Dual-mobility acetabulum Käyttöön valitaan ominaisuuksiltaan riittävän kattavan tuotevalikoiman takaamiseksi enintään kaksi ns. dual-mobility konseptin mukaista järjestelmää, jotka sisältävät monobloc acetabulum komponentin ja siihen kuuluva nuppijärjestelmän. Arvioitu vuosikulutus on 380 kpl. 6 Lonkan revisiotekoniveljärjestelmä Käyttöön valitaan lonkan revisiotekoniveljärjestelmä, joilla voidaan kattaa lonkan revisiotoimenpiteiden laaja kirjo sekä vaativa primaariprotetiikka. Arvioitu vuosikulutus on acetabulum komponentin osalta 310 kpl ja femur komponentin osalta 75 kpl. Eduksi katsotaan yhdisteltävyys valittujen primaaritekoniveljärjestelmän tuotteiden kanssa. 7 Tuumori- ja rekonstruktioproteesijärjestelmä Käyttöön valitaan enintään kaksi ominaisuuksiltaan riittävän kattavaa luuta korvaavaa rekonstruktioproteesijärjestelmää, joilla voidaan hoitaa rekonstruktiivisen tekonivelkirurgian monipuoliset vaatimukset. Arvioitu vuosikulutus on proximaalireiden osalta 25 kpl ja distaalireiden osalta 20 kpl. 8 Olkatekoniveljärjestelmät Käyttöön valitaan sekä ns. anatominen kokotekonivelratkaisu että reverse-tyyppinen käänteistekonivel. Kumpaankin tekonivelkonseptiin valitaan yksi tai kaksi järjestelmää siten, että tuotevalikoima on ominaisuuksiltaan riittävän laaja. Arvioitu vuosikulutus on anatomisen implantin osalta 60 kpl ja reverse-implantin osalta 170 kpl. Valinta kohdistuu erillisesti molempiin konsepteihin, jolloin on mahdollista, että valitaan eri toimittajat reverse tekonivelelle ja anatomiselle tekonivelelle. Anatomisen järjestelmään täytyy sisältyä ns. mid-head konseptin mukainen varreton kokotekonivelmalli ja optionaalisesti myös varrellinen malli.  Tarjottavilla tekoniveltuotteilla on oltava vähintään 5A ODEP luokitus sekä pitkäaikaisnäyttöä jostakin seuraavista tekonivelrekistereistä: pohjoismaiset rekisterit, Australia tai Englanti. 9 Murtumahoidossa käytettävä lonkkatekonivel Käyttöön valitaan enintään kaksi ominaisuuksiltaan riittävän kattavaa sementtikiinnitteistä tekonivelmallia, jotka soveltuvat reisiluun kaulan murtuman hoitoon puolitekonivelratkaisuna Coxassa ja Tays:n traumayksikössä. Arvioitu vuosikulutus on 300 kpl. 1 Polvitekoniveljärjestelmät Polven primaariprotetiikassa käytettäväksi valitaan järjestelmä, joka sisältää CR ja PS tyyppiset reisikomponentit. Arvioitu implanttien vuosikulutus on yhteensä 3300 kpl (95% CR). Käyttöön valitaan pääjärjestelmä, jonka osalta Coxa sitoutuu vähintään 60% osuuteen primaariprotetiikan kokonaiskulutuksesta. Ominaisuuksiltaan riittävän kattavan tuotevalikoiman takaamiseksi voidaan lisäksi valita enintään kaksi rinnakkaista primaarijärjestelmää, joiden kulutusmäärää ei ole ennalta asetettu. Tarjouksessa on esitettävä hinnat erikseen sekä pääjärjestelmää että rinnakkaisjärjestelmää koskien. CR ja PS tekonivelmalleilla on oltava vähintään 5A ODEP luokitus sekä pitkäaikaisnäyttöä jostakin seuraavista tekonivelrekistereistä: pohjoismaiset rekisterit, Australia tai Englanti.  Revisiokäyttöön valitaan enintään kaksi primaarikäyttöön valittujen järjestelmien tuoteperheeseen kuuluvaa järjestelmää, jotka sisältävät sekä ns. ”constrained condylar”-tyyppisen että kytketyn polvitekonivelmallin. Arvioitu vuosikulutus on CCK- polven osalta 250 kpl ja saranapolvien osalta 50 kpl. \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"  Tampere FI\", \"innovationConsidered\": false, \"procurementProjectId\": 61664, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"TEKONIVELJÄRJESTELMÄT\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Tuomi Logistiikka Oy kilpailuttaa Coxa Oy:n ja Pshp:n toimeksiannosta tekoniveljärjestelmät.   Osista 1-9 tehdään hankintasopimus toimittajan ja Coxa Oy:n välillä. Murtumahoidossa käytettävä lonkkatekonivel tulee myös Tays:n käyttöön, joten tarjouspyynnön osasta 9 tehdään sopimus myös toimittajan ja Tuomi Logistiikan välillä. Hankintapäätöksen tekee Coxa Oy kaikkien tilaajien puolesta.  Sopimus on voimassa 24 kuukautta, jonka jälkeen se jatkuu toistaiseksi voimassa olevana optiona. Sopimus tullaan kilpailuttamaan uudelleen arviolta neljän - viiden vuoden kuluttua sopimuskauden alkamisesta.  Sopimuksen arvioitu alkamisajankohta on heinäkuu 2022.  Sopimuksen arvioitu kokonaisarvo on laskettu viidelle vuodelle.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"2722581-6\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-10T12:00:00Z\"}',40,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (768,'2021-088310','HILMA','RFI','OPEN','GC-MS/MS','Tämä ilmoitus ei ole hankintailmoitus eikä tarjouspyyntö, eikä sen julkaisemisella aloiteta tarjouskilpailua. Kyseessä on ennakkoilmoitus tulevasta hankinnasta. Ennakkoilmoitukseen liittyy markkinakartoitus/tietopyyntö, jolloin kiinnostuneilla yrityksillä on mahdollisuus käydä hankintaa koskevaa teknistä vuoropuhelua hankintayksikön kanssa. Tietopyynnön tarkoituksena on kartoittaa markkinoilla olevia ratkaisuja ja saada kattavasti niitä koskevaa tietoa, jotta valmisteilla oleva kilpailutus voidaan toteuttaa mahdollisimman tarkoituksenmukaisesti. Tietopyyntöön vastaaminen ei ole edellytys kilpailutukseen osallistumiselle eikä vaikuta tarjoajan asemaan siinä. Tietopyynnössä esitetyt seikat ovat alustavia ja saattavat muuttua hankinnan valmistelun edetessä.','Ruokavirasto','ANY',9,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088310','[\"38430000\"]','[\"eikä\", \"koskevaa\", \"ruokavirasto\", \"tämä\", \"ilmoitus\", \"hankintailmoitus\", \"tarjouspyyntö\", \"julkaisemisella\", \"aloiteta\", \"tarjouskilpailua\", \"kyseessä\", \"ennakkoilmoitus\", \"tulevasta\", \"hankinnasta\", \"ennakkoilmoitukseen\", \"liittyy\", \"markkinakartoitus\", \"tietopyyntö\", \"jolloin\", \"kiinnostuneilla\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088310\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88310\", \"type\": 100, \"cpvCodes\": \"38430000 Ilmaisimet ja analyysilaitteet\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"PriorInformationNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI  FI1B\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-17T08:00:16.769Z\", \"noticeNumber\": \"2021-088310\", \"projectTitle\": \"GC-MS/MS\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-16T15:10:08.165Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-10T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 245-643562\", \"organisationName\": \"Ruokavirasto\", \"objectDescriptions\": \" Hankinnan kohteena on kaasukromatografi-kolmoiskvadrupoli-massaspektrometri-laite (GC-MS/MS). Laitetta tullaan käyttämään yhdisteiden kvantitointiin monimutkaisista elintarvike- ja rehumatriiseista (mm. kasvinsuojeluainejäämät ja vierasaineet elintarvikkeista ja rehuista). Laitteella tullaan tekemään päivittäisanalytiikkaa mm. monijäämämenetelmillä, joissa erotetaan ja kvantitoidaan jopa yli 100 yhdistettä samanaikaisesti.  Hankinnan kohde sisältää laitteen ja ohjelmiston, jonka avulla analyysidata voidaan prosessoida nopeasti ja luotettavasti. Hankinnan kohde sisältää lisäksi laitteen toimituksen toimitusehdon mukaisesti, ohjelmiston asennuksen ja optimoinnin käyttökuntoon, vastaanottotarkastuksen ja sen hyväksymisen, testaukset, käyttökoulutuksen, käyttöohjeet sekä laitteen ja ohjelmistojen ylläpidon (vuosihuoltoprotokollan mukainen huolto, vikakorjaus ja päivitys).  \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Alvar Aallon katu 5 60100 Seinäjoki FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62372, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": \"\", \"projectTitleNormalized\": \"GC-MS/MS\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Tämä ilmoitus ei ole hankintailmoitus eikä tarjouspyyntö, eikä sen julkaisemisella aloiteta tarjouskilpailua. Kyseessä on ennakkoilmoitus tulevasta hankinnasta. Ennakkoilmoitukseen liittyy markkinakartoitus/tietopyyntö, jolloin kiinnostuneilla yrityksillä on mahdollisuus käydä hankintaa koskevaa teknistä vuoropuhelua hankintayksikön kanssa.  Tietopyynnön tarkoituksena on kartoittaa markkinoilla olevia ratkaisuja ja saada kattavasti niitä koskevaa tietoa, jotta valmisteilla oleva kilpailutus voidaan toteuttaa mahdollisimman tarkoituksenmukaisesti. Tietopyyntöön vastaaminen ei ole edellytys kilpailutukseen osallistumiselle eikä vaikuta tarjoajan asemaan siinä. Tietopyynnössä esitetyt seikat ovat alustavia ja saattavat muuttua hankinnan valmistelun edetessä. \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"2911686-7\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-10T12:00:00Z\"}',60,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
