INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (772,'2021-089355','HILMA','RFP','OPEN','Varhaiskasvatuksen tietojärjestelmä','Kannuksen kaupunki pyytää tarjousta kunnallisen varhaiskasvatuksen toiminnanohjaamiseen ja prosessienhallintaan soveltuvasta järjestelmäratkaisusta. Hankinnan kohteena on palveluntarjoajan palvelimilta verkon yli toimiva (SaaS) ratkaisu, joka toimii myös integraatioalustana erilaisille taustajärjestelmille. Järjestelmän tulee soveltua varhaiskasvatuksen hakuprosessien ja eri tyyppisten päätösten (esimerkiksi sijoitus-, maksu ja palvelusetelipäätösten) hallintaan, asiakasjonojen ja raportoinnin hallintaan, asiakasviestintään sekä laskutusprosessien ja tilastoinnin työnkulkuihin. Järjestelmäratkaisun tulee sisältää rajapinnat tarvittaviin taustajärjestelmiin. Hankinta käsittää ratkaisun teknisen määrittelyn ja toteutuksen, käyttöönoton sekä käytönaikaisen tuki-, ylläpito- ja pienkehityspalvelun.','Kannuksen kaupunki','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-089355','[\"72000000\"]','[\"varhaiskasvatuksen\", \"kannuksen\", \"kaupunki\", \"tulee\", \"hallintaan\", \"tietojärjestelmä\", \"pyytää\", \"tarjousta\", \"kunnallisen\", \"toiminnanohjaamiseen\", \"prosessienhallintaan\", \"soveltuvasta\", \"järjestelmäratkaisusta\", \"hankinnan\", \"kohteena\", \"palveluntarjoajan\", \"palvelimilta\", \"verkon\", \"toimiva\", \"saas\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-089355\", \"name\": \"HILMA Notice\"}]','{\"id\": \"89355\", \"type\": 9902, \"cpvCodes\": \"72000000 Tietotekniset palvelut: neuvonta, ohjelmistojen kehittäminen, Internet ja tuki\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1D5  FI1D5\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-28T08:38:51.379Z\", \"noticeNumber\": \"2021-089355\", \"projectTitle\": \"Varhaiskasvatuksen tietojärjestelmä\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-28T08:38:51.378Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-17T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Kannuksen kaupunki\", \"objectDescriptions\": \" Kannuksen kaupunki pyytää tarjousta kunnallisen varhaiskasvatuksen toiminnanohjaamiseen ja prosessienhallintaan soveltuvasta järjestelmäratkaisusta. Hankinnan kohteena on palveluntarjoajan palvelimilta verkon yli toimiva (SaaS) ratkaisu, joka toimii myös integraatioalustana erilaisille taustajärjestelmille. Järjestelmän tulee soveltua varhaiskasvatuksen hakuprosessien ja eri tyyppisten päätösten (esimerkiksi sijoitus-, maksu ja palvelusetelipäätösten) hallintaan, asiakasjonojen ja raportoinnin hallintaan, asiakasviestintään sekä laskutusprosessien ja tilastoinnin työnkulkuihin. Järjestelmäratkaisun tulee sisältää rajapinnat tarvittaviin taustajärjestelmiin.  Varhaiskasvatuksen toiminnanohjaukseen ja prosessienhallintaan sekä työajanseurantaan ja työvuorosuunnitteluun liittyvät kriteerit ovat sellaisia, joihin ei ole taustajärjestelmää, vaan kyseisten toiminnallisuuksien tulee sisältyä tarjottavaan järjestelmäratkaisuun ilman rajapintojen rakentamista.  Järjestelmän sisältämien palvelujen toiminnallisuuden tulee olla täysin tilaajan pääkäyttäjän hallittavissa erilaisilla työasemilla ja selaimilla. Järjestelmän tulee lisäksi toimia mobiiliapplikaation kautta. Valitun toimijan kanssa tehdään toistaiseksi voimassa oleva hankintasopimus. Kilpailutuksella valitaan yksi palveluntuottaja. Hankinta toteutetaan avoimena menettelynä, jossa esitetyillä tarjousten pisteytysperusteilla korkeimman kokonaispistemäärän saanut tarjoaja valitaan. Tarjousten valintaperusteena on kokonaistaloudellinen edullisuus. Tarjousten vertailuperusteena on: Laatu 40% = max 40 pistettä Hinta 60% = max 60 pistettä Vertailussa kriteerikohtaisesti halvin hinta saa maksimipisteet. Muut tarjoukset pisteytetään kaavalla: halvin hinta / vertailtava hinta x maksimipisteet. Laatupisteet muodostuvat kriteeristöön annettujen kyllä -vastausten määrästä.  Kannuksen kaupunki vaatii ennen hankintapäätöksen antamista voittaneelta tarjoajalta järjestelmätuotteensa esittelytilaisuuden, jossa järjestelmä ja sen toimittava yritys esitellään ja jossa tarjottu tuote todetaan tarjouspyynnön mukaiseksi. Tilaisuus järjestetään Kannuksen kaupungin määrittämässä paikassa; muilta osin käytännönjärjestelyistä (kuten aikataulu) voidaan sopia erikseen hankintayksikön ja tarjoajan välillä. Tarjoaja ei saa periä esittelytilaisuuden järjestämisestä maksua. \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Asematie 1 69100 Kannus FI\", \"innovationConsidered\": false, \"procurementProjectId\": 63042, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": \"Varhaiskasvatuspalvelut\", \"projectTitleNormalized\": \"VARHAISKASVATUKSEN TIETOJÄRJESTELMÄ\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Kannuksen kaupunki pyytää tarjousta kunnallisen varhaiskasvatuksen toiminnanohjaamiseen ja prosessienhallintaan soveltuvasta järjestelmäratkaisusta. Hankinnan kohteena on palveluntarjoajan palvelimilta verkon yli toimiva (SaaS) ratkaisu, joka toimii myös integraatioalustana erilaisille taustajärjestelmille. Järjestelmän tulee soveltua varhaiskasvatuksen hakuprosessien ja eri tyyppisten päätösten (esimerkiksi sijoitus-, maksu ja palvelusetelipäätösten) hallintaan, asiakasjonojen ja raportoinnin hallintaan, asiakasviestintään sekä laskutusprosessien ja tilastoinnin työnkulkuihin. Järjestelmäratkaisun tulee sisältää rajapinnat tarvittaviin taustajärjestelmiin. Hankinta käsittää ratkaisun teknisen määrittelyn ja toteutuksen, käyttöönoton sekä käytönaikaisen tuki-, ylläpito- ja pienkehityspalvelun.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": null, \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0178455-6\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-17T12:00:00Z\"}',65,NULL,'2026-09-07 12:31:30','2026-09-07 12:31:30');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (773,'2021-089335','HILMA','RFP','OPEN','Ultraäänilaitteet gynekologiseen diagnostiikkaan','Hankinnan kohteena on Satasairaalan naistentautien ja äitiyspoliklinikan käyttöön UÄ- laite vaativaan gynekologiseen diagnostiikkaan, sisältää 3D vaginaalisen anturin.','Satakunnan Sairaanhoitopiirin kuntayhtymä','ANY',3,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-089335','[\"33100000\", \"33100000\"]','[\"gynekologiseen\", \"diagnostiikkaan\", \"satakunnan\", \"sairaanhoitopiirin\", \"kuntayhtymä\", \"ultraäänilaitteet\", \"hankinnan\", \"kohteena\", \"satasairaalan\", \"naistentautien\", \"äitiyspoliklinikan\", \"käyttöön\", \"laite\", \"vaativaan\", \"sisältää\", \"vaginaalisen\", \"anturin\", \"finland\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-089335\", \"name\": \"HILMA Notice\"}]','{\"id\": \"89335\", \"type\": 9902, \"cpvCodes\": \"33100000 Lääketieteelliset laitteet 33100000 Lääketieteelliset laitteet\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI196  FI196\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-28T05:42:39.464Z\", \"noticeNumber\": \"2021-089335\", \"projectTitle\": \"Ultraäänilaitteet gynekologiseen diagnostiikkaan\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-28T05:42:39.463Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-28T13:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"notic