INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (779,'2021-087894','HILMA','RFP','OPEN','Veneiden (2 kpl) hankinta','Helsingin seurakuntayhtymä (jatkossa hankintayksikkö / tilaaja) pyytää tarjousta veneistä (2 kpl) tämän tarjouspyynnön ja sen liitteiden mukaisesti. Veneiden toimitusaika on 20.5.2022 mennessä.','Helsingin seurakuntayhtymä','ANY',10,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-087894','[\"34522000\", \"34520000\"]','[\"veneiden\", \"helsingin\", \"seurakuntayhtymä\", \"hankinta\", \"jatkossa\", \"hankintayksikkö\", \"tilaaja\", \"pyytää\", \"tarjousta\", \"veneistä\", \"tämän\", \"tarjouspyynnön\", \"liitteiden\", \"mukaisesti\", \"toimitusaika\", \"mennessä\", \"turku\", \"finland\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-087894\", \"name\": \"HILMA Notice\"}]','{\"id\": \"87894\", \"type\": 9902, \"cpvCodes\": \"34522000 Huvi- ja urheiluveneet 34520000 Veneet\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1B1  FI1B1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-07T11:00:00.854Z\", \"noticeNumber\": \"2021-087894\", \"projectTitle\": \"Veneiden (2 kpl) hankinta\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-07T11:00:00.853Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2021-12-22T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Helsingin seurakuntayhtymä\", \"objectDescriptions\":