INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (780,'2021-087828','HILMA','RFP','OPEN','Matinsaaren infran toteutussuunnitelman laatiminen','Pyhäjoen kunta pyytää tarjoustanne Matinsaaren infran toteutussuunnitelmien laatimisesta. Suunnittelutyön tulee olla kaikilta osin valmiina ja luovutettavissa viimeistään 9.5.2022 mennessä. Tarjouspyyntöön liittyvät kysymykset on lähetettävä 4.1.2022 klo 12.00 mennessä. Tarjoukset on toimitettava 11.1.2022 klo 12.00 mennessä.','Pyhäjoen kunta','ANY',2,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-087828','[\"71240000\"]','[\"pyhäjoen\", \"kunta\", \"mennessä\", \"matinsaaren\", \"infran\", \"toteutussuunnitelman\", \"laatiminen\", \"pyytää\", \"tarjoustanne\", \"toteutussuunnitelmien\", \"laatimisesta\", \"suunnittelutyön\", \"tulee\", \"kaikilta\", \"osin\", \"valmiina\", \"luovutettavissa\", \"viimeistään\", \"tarjouspyyntöön\", \"liittyvät\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-087828\", \"name\": \"HILMA Notice\"}]','{\"id\": \"87828\", \"type\": 9902, \"cpvCodes\": \"71240000 Arkkitehti-, insinööri- ja suunnittelupalvelut\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1D9  FI1D9\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-07T06:15:20.863Z\", \"noticeNumber\": \"2021-087828\", \"projectTitle\": \"Matinsaaren infran toteutussuunnitelman laatiminen\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-07T06:15:20.861Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-11T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Pyhäjoen kunta\", \"objectDescriptions\": \" Pyhäjoen kunta pyytää tarjoustanne Matinsaaren infran toteutussuunnitelmien laatimisesta.  Hankinnan kohteena on laatia Matinsaaren infran toteutussuunnitelmat Matinsaaren asemakaava-alueelle. Vesihuoltosuunnitelmat ulotetaan Pyhäjokisuun Vesi Oy:n määrittelemiin vesihuollon liitospisteisiin saakka. Liitospisteet on määritelty tarkemmin tarjouspyynnön liitteissä. Toteutussuunnitelmiin sisältyy myös siltasuunnitelmat.  Asemakaavalla muodostuvat korttelit 800-830, virkistysalueita, liikenne-alueita, erityisalueita, maa- ja metsätalousalueita, vesialue sekä katu-alueita.  Asemakaava on hyväksytty kunnanvaltuustossa 11.11.2020, mutta se ei ole vielä lainvoimainen.  Kaava-alue on 73,97 ha. Korttelialue 27,78 ha ja rakennusoikeutta 47.178k-m2. Suunnittelualueen kokoojakatujen, tonttikatujen ja kevyenliikenteen väylien alustavat pituudet löytyvät liitteestä 7.  Suunnittelutyö tulee aloittaa heti, kun konsulttisopimus on allekirjoitettu, tai kun tilaaja on antanut kirjallisen luvan suunnittelutyön aloittamiseen.  Suunnittelutyön tulee olla kaikilta osin valmiina ja luovutettavissa viimeistään 9.5.2022 mennessä.   Tarjouspyyntöön liittyvät kysymykset on lähetettävä ti 4.1.2022 klo 12.00 mennessä.  Kysymykset tulee lähettää Tarjouspalvelu.fi -toimittajaportaalista. Samasta paikasta löytyvät myös kysymyksiin annetut vastaukset viimeistään ke 5.1.2022 klo 15.00 mennessä  Tarjoajien tasapuolisen kohtelun turvaamiseksi muulla tavoin esitettyihin kysymyksiin ei vastata.   Mikäli tarjoaja huomaa tarjouspyynnössä epäselvyyksiä tai ristiriitoja tai jokin tarjouspyynnössä esitetty asia on tulkinnanvarainen, tarjoajan velvollisuus on tuoda asia esille toimittamalla tarkentava kysymys.     Tarjoajan tulee huomioida tarjousta tehdessään edellä mainitut kysymykset ja niihin annetut vastaukset, koska ne sisältävät viimeisimmän tarjouspyyntöä koskevan tiedon.  Tarjoukset on toimitettava ti 11.1.2022 klo 12.00 mennessä.  Kilpailutusjärjestelmä sulkeutuu automaattisesti 12:00:00.  Automattisen sulkeutumisen jälkeen järjestelmä ei ota vastaan myöhästyneitä tarjouksia (12:00:00).  Tarjoukset on lähetettävä sähköisesti Tarjouspalvelu.fi -toimittajaportaalista osoitteesta https://tarjouspalvelu.fi/raahe Muulla tavoin toimitettuja tarjouksia ei oteta vastaan.  Tarjoajan tulee ladata tarjouksen liitteeksi vain tarjouspyynnössä pyydetyt liitteet (mikäli tarjoaja on ladannut tarjouksen liitteeksi muita kuin pyydettyjä asiakirjoja ja selvityksiä, ne voivat johtaa tarjouksen hylkäämiseksi niissä esiintyvien ristiriitaisuuksien vuoksi).   \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Kuntatie 1 86100 Pyhäjoki FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62052, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"MATINSAAREN INFRAN TOTEUTUSSUUNNITELMAN LAATIMINEN\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Pyhäjoen kunta pyytää tarjoustanne Matinsaaren infran toteutussuunnitelmien laatimisesta.  Suunnittelutyön tulee olla kaikilta osin valmiina ja luovutettavissa viimeistään 9.5.2022 mennessä.   Tarjouspyyntöön liittyvät kysymykset on lähetettävä 4.1.2022 klo 12.00 mennessä.   Tarjoukset on toimitettava 11.1.2022 klo 12.00 mennessä.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": null, \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0189127-1\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-11T12:00:00Z\"}',40,NULL,'2026-09-08 01:01:47','2026-09-08 01:01:47');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (781,'2021-087807','HILMA','RFP','OPEN','Kemin ratapihan muutostyöt ja lisäraiteen rakentaminen','Väylävirasto pyytää erityisalojen hankintalain mukaisesti tarjoustanne Kemin ratapihan muutostöistä ja lisäraiteen rakentamisesta tarjouspyyntöasiakirjojen mukaisesti. Kemin ratapihalla uusitaan vaihteita ja raiteita sekä sähköistetään ja jatketaan raiteita. Kemin ja Lautiosaaren väliselle rataosuudelle rakennetaan lisäraide ja siihen liittyvät vaihteet. Urakassa uusitaan päällysrakennetta myös raiteilla R590 ja R008, rakennetaan melueste ME1a ja suoja-aitoja sekä jatketaan ylikulkusiltojen kosketussuojaseinämiä. Urakassa siirretään Lautiosaaren pyörävoimailmaisin (VEKU) Loue kuumakäynti-ilmaisimen (LAKU) yhteyteen. Maa- ja päällysrakennetöiden lisäksi urakkaan sisältyy raidemuutoksista aiheutuvat toimenpiteet turvalaitteisiin, sähkörataan, valaistukseen, vahvavirtaan, kuivatukseen ja radan merkkeihin.','Väylävirasto','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-087807','[\"45000000\"]','[\"kemin\", \"väylävirasto\", \"ratapihan\", \"lisäraiteen\", \"mukaisesti\", \"uusitaan\", \"raiteita\", \"jatketaan\", \"lautiosaaren\", \"rakennetaan\", \"urakassa\", \"muutostyöt\", \"rakentaminen\", \"pyytää\", \"erityisalojen\", \"hankintalain\", \"tarjoustanne\", \"muutostöistä\", \"rakentamisesta\", \"tarjouspyyntöasiakirjojen\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-087807\", \"name\": \"HILMA Notice\"}]','{\"id\": \"87807\", \"type\": 500, \"cpvCodes\": \"45000000 Rakennustyöt\", \"currency\": null, \"i