INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (799,'2021-088507','HILMA','RFP','OPEN','Hervannan kirkon peruskorjauksen arkkitehtisuunnittelu','Tampereen ev.lut. seurakuntayhtymän kiinteistöpalvelut pyytävät tarjoustanne Hervannan kirkon peruskorjauksen pää- ja arkkitehtisuunnittelusta.','Tampereen ev.lut. seurakuntayhtymä','ANY',2,3,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088507','[\"71240000\"]','[\"tampereen\", \"hervannan\", \"kirkon\", \"peruskorjauksen\", \"seurakuntayhtymä\", \"arkkitehtisuunnittelu\", \"seurakuntayhtymän\", \"kiinteistöpalvelut\", \"pyytävät\", \"tarjoustanne\", \"arkkitehtisuunnittelusta\", \"finland\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088507\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88507\", \"type\": 9902, \"cpvCodes\": \"71240000 Arkkitehti-, insinööri- ja suunnittelupalvelut\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": 88348, \"lowCarbon\": null, \"nutsCodes\": \" FI197  FI197\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-15T13:19:10.043Z\", \"noticeNumber\": \"2021-088507\", \"projectTitle\": \"Hervannan kirkon peruskorjauksen arkkitehtisuunnittelu\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-15T13:19:10.037Z\", \"isCorrigendum\": true, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-07T14:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Tampereen ev.lut. seurakuntayhtymä\", \"objectDescriptions\": \" Tampereen ev.lut. seurakuntayhtymän kiinteistöpalvelut pyytävät tarjoustanne Hervannan kirkon peruskorjauksen pää- ja arkkitehtisuunnittelusta.  Rakennuttaja: Tampereen ev.lut. seurakuntayhtymä  Kohde:  Hervannan kirkko, Lindforsinkatu 7, 33720 Tampere Rakennusvuosi 1979 Laajuus 2985 krs-m2 Arkkitehdit Reima ja Raili Pietilä  Kirkon peruskorjaus sisältää kirkon julkisivujen, ulkopuolisten rakenteiden, piha-alueiden sekä sisäpuolen korjaustöiden ja muutostöiden pääsuunnittelun RT 103254 mukaisesti, sekä kohteen arkkitehtisuunnittelun RT 103253 mukaisesti, koko hankkeen ajan. Lopullinen työn laajuus tarkentuu hankkeen edetessä.   Hankinnassa noudatetaan KSE2013 sopimusehtoja.   Suunnittelutyöt alkavat alustavasti helmikuussa 2022. Korjaustyöt alkavat alustavasti 6/2023 ulkopuolisilta osin. Sisäpuolen korjaukset ajoittuvat alustavasti vuosille 2024-2025.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Näsilinnankatu 26 33101 Tampere FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62393, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"HERVANNAN KIRKON PERUSKORJAUKSEN ARKKITEHTISUUNNITTELU\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Tampereen ev.lut. seurakuntayhtymän kiinteistöpalvelut pyytävät tarjoustanne Hervannan kirkon peruskorjauksen pää- ja arkkitehtisuunnittelusta. \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": null, \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0206114-9\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-07T14:00:00Z\"}',40,NULL,'2026-09-08 01:01:48','2026-09-08 01:01:48');
