INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (804,'2021-087812','HILMA','RFP','OPEN','Polttonesteiden jakeluasemien vaatimustenmukaisuusselvitys','Rajavartiolaitos pyytää tarjouksia Rajavartiolaitoksen hallinnoimien polttonesteiden jakeluasemien vaatimustenmukaisuusselvityksistä ja lisähankintavarauksena säiliötarkastuksista tämän tarjouspyynnön ja sen liitteissä määriteltyjen vaatimusten mukaisesti. Tavoitteena on saattaa jakeluasemat voimassa olevien määräysten ja lainsäädännön mukaiseksi. 1. Polttonesteiden jakeluasemien vaatimustenmukaisuusselvitykset Jakeluasemat on jaettu neljään eri alueeseen seuraavasti Alue 1: Etelä-Suomi Alue 2: Länsi-Suomi Alue 3: Pohjois-Suomi Alue 4: Itä-Suomi Tarjousten jättäminen alueittain on sallittua. Tarjoaja voi tarjota yhden tai useamman alueen. 2. Lisähankintavaraus / Säiliötarkastukset Säiliötarkastukset on jaettu neljään eri alueeseen seuraavasti Alue 1: Etelä-Suomi Alue 2: Länsi-Suomi Alue 3: Pohjois-Suomi Alue 4: Itä-Suomi Tarjousten jättäminen alueittain on sallittua. Tarjoaja voi tarjota yhden tai useamman alueen. Tarjoaja voi tarjota molempia palveluja: palvelua 1. polttonesteiden jakeluasemien vaatimustemukaisuusselvitykset ja palvelua 2. lisähankintavaraus: säiliötarkastukset. Tarjoaja voi tarjota pelkästään palvelua 1. polttonesteiden jakeluasemien vaatimustenmukaisuusselvitykset tai pelkästään palvelua 2. lisähankintavaraus: säiliötarkastukset.','Rajavartiolaitos','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-087812','[\"71730000\", \"71730000\", \"71730000\"]','[\"alue\", \"suomi\", \"polttonesteiden\", \"jakeluasemien\", \"tarjoaja\", \"tarjota\", \"säiliötarkastukset\", \"palvelua\", \"lisähankintavaraus\", \"rajavartiolaitos\", \"jakeluasemat\", \"vaatimustenmukaisuusselvitykset\", \"jaettu\", \"neljään\", \"alueeseen\", \"seuraavasti\", \"etelä\", \"länsi\", \"pohjois\", \"tarjousten\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-087812\", \"name\": \"HILMA Notice\"}]','{\"id\": \"87812\", \"type\": 9902, \"cpvCodes\": \"71730000 Teolliset tarkastuspalvelut 71730000 Teolliset tarkastuspalvelut 71730000 Teolliset tarkastuspalvelut\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1B1  FI1 FI2  FI1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-03T14:35:08.102Z\", \"noticeNumber\": \"2021-087812\", \"projectTitle\": \"Polttonesteiden jakeluasemien vaatimustenmukaisuusselvitys\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-03T14:35:08.096Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-17T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Rajavartiolaitos\", \"objectDescriptions\": \"Polttonesteiden jakeluasemien vaatimustenmukaisuusselvitys Hankinnan kohteena on Rajavartiolaitoksen hallinnoimien polttonesteiden jakeluasemien nykytilan kunnon arviointi ja kartoitus vaatimusten ja määräysten mukaisuuden täyttymisestä, mahdollisista puutteista, esitys korjaustoimenpiteistä sekä arvio korjauskustannuksista, joilla jakeluasema saatetaan voimassa olevien määräysten ja lainsäädännön mukaiseksi tämän tarjouspyynnön ja sen liitteiden mukaisesti.  Jakeluasemat on jaettu neljään eri alueeseen seuraavasti Alue 1: Etelä-Suomi Alue 2: Länsi-Suomi Alue 3: Pohjois-Suomi Alue 4: Itä-Suomi  Tarjousten jättäminen alueittain on sallittua. Tarjoaja voi tarjota yhden tai useamman alueen.  Selvityksen ja palvelun tarkempi sisältö, selvityskohteet sekä vaatimukset palvelulle ja tarjoajalle on ilmoitettu liitteessä 1, palvelukuvaus.  Jakeluasemakohtaiset lähtötiedot on ilmoitettu alueittain liitteessä 2.  Palvelulle asetetut tekniset vaatimukset sekä muut tarjouspyynnössä ja sen liiteasiakirjoissa hankinnan kohteelle asetetut vaatimukset tulee täyttää.  Sopimuskausi alkaa kun kumpikin osapuoli on allekirjoittanut sopimuksen (tavoite maaliskuu 2022). Sopimus päättyy 31.12.2022. Lisähankintavaraus: Säiliötarkastukset Säiliötarkastukset on jaettu neljään eri alueeseen seuraavasti Alue 1: Etelä-Suomi Alue 2: Länsi-Suomi Alue 3: Pohjois-Suomi Alue 4: Itä-Suomi  Tarjousten jättäminen alueittain on sallittua. Tarjoaja voi tarjota yhden tai useamman alueen.  Palvelun tarkempi sisältö, tarkastuskohteet sekä vaatimukset palvelulle ja tarjoajalle on ilmoitettu liitteessä 1, palvelukuvaus.  Kohdekohtaiset lähtötiedot on ilmoitettu alueittain liitteessä 2.  Palvelulle asetetut tekniset vaatimukset sekä muut tarjouspyynnössä ja sen liiteasiakirjoissa hankinnan kohteelle asetetut vaatimukset tulee täyttää.  Mikäli lisähankintavaraus käytetään, sopimuskausi alkaa, kun kumpikin osapuoli on allekirjoittanut sopimuksen (tavoite maaliskuu 2022). Sopimus päättyy 31.12.2022.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"PL 3 00131 Helsinki FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62040, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"POLTTONESTEIDEN JAKELUASEMIEN VAATIMUSTENMUKAISUUSSELVITYS\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Rajavartiolaitos pyytää tarjouksia Rajavartiolaitoksen hallinnoimien polttonesteiden jakeluasemien vaatimustenmukaisuusselvityksistä ja lisähankintavarauksena säiliötarkastuksista tämän tarjouspyynnön ja sen liitteissä määriteltyjen vaatimusten mukaisesti.   Tavoitteena on saattaa jakeluasemat voimassa olevien määräysten ja lainsäädännön mukaiseksi.  1. Polttonesteiden jakeluasemien vaatimustenmukaisuusselvitykset  Jakeluasemat on jaettu neljään eri alueeseen seuraavasti Alue 1: Etelä-Suomi Alue 2: Länsi-Suomi Alue 3: Pohjois-Suomi Alue 4: Itä-Suomi  Tarjousten jättäminen alueittain on sallittua. Tarjoaja voi tarjota yhden tai useamman alueen.   2. Lisähankintavaraus / Säiliötarkastukset  Säiliötarkastukset on jaettu neljään eri alueeseen seuraavasti Alue 1: Etelä-Suomi Alue 2: Länsi-Suomi Alue 3: Pohjois-Suomi Alue 4: Itä-Suomi  Tarjousten jättäminen alueittain on sallittua. Tarjoaja voi tarjota yhden tai useamman alueen.  Tarjoaja voi tarjota molempia palveluja:  palvelua 1. polttonesteiden jakeluasemien vaatimustemukaisuusselvitykset ja palvelua 2. lisähankintavaraus: säiliötarkastukset.   Tarjoaja voi tarjota pelkästään palvelua 1. polttonesteiden jakeluasemien vaatimustenmukaisuusselvitykset tai pelkästään palvelua 2. lisähankintavaraus: säiliötarkastukset. \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": null, \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0246003-5\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-17T12:00:00Z\"}',45,NULL,'2026-09-08 01:01:48','2026-09-08 01:01:48');
