INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (808,'2021-088139','HILMA','OTHER','OPEN','Kirjastoauton hankinta','Tornion kaupunki on tehnyt sopimuksen kirjastoauton toimittamisesta. Kirjastoauto hankitaan alustoineen ja koritöineen katsastettuna ja tilaajan käyttöön rekisteröitynä.','Tornion kaupunki','ANY',6,14,NULL,NULL,459070.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088139','[\"34144760\"]','[\"tornion\", \"kaupunki\", \"kirjastoauton\", \"hankinta\", \"tehnyt\", \"sopimuksen\", \"toimittamisesta\", \"kirjastoauto\", \"hankitaan\", \"alustoineen\", \"koritöineen\", \"katsastettuna\", \"tilaajan\", \"käyttöön\", \"rekisteröitynä\", \"finland\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088139\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88139\", \"type\": 300, \"cpvCodes\": \"34144760 Kirjastoautot\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractAwardNotices\", \"parentId\": 74269, \"lowCarbon\": null, \"nutsCodes\": \" FI1D7  FI1D7\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-15T08:00:06.086Z\", \"noticeNumber\": \"2021-088139\", \"projectTitle\": \"Kirjastoauton hankinta \", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-12T08:10:10.516Z\", \"isCorrigendum\": false, \"estimatedValue\": 459070.0, \"expirationDate\": \"2022-06-12T08:10:10.516Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 243-640214\", \"organisationName\": \"Tornion kaupunki\", \"objectDescriptions\": \" Tornion kaupunki on tehnyt sopimuksen kirjastoauton toimittamisesta. Kirjastoauto hankitaan alustoineen ja koritöineen katsastettuna ja tilaajan käyttöön rekisteröitynä. Hankittavan ajoneuvon tulee olla moderni ja toiminnallisuudeltaan helposti muunnettavissa monipuoliseen käyttötarkoitukseen.  Hankintayksikkö edellyttää, että valmis kirjastoauto toimitetaan viimeistään kahdentoista (12) kuukauden kuluessa lainvoimaisesta hankintapäätöksestä.   Kirjastoauton teknisiä ominaisuuksia koskevat vähimmäisvaatimukset on määritelty Suomen kirjastoseuran kirjastoautotyöryhmän ja autonvalmistajien laatimien (13.11.2020) kirjastoauton teknisten laatusuositusten pohjalta. Tarkemmat kriteerit auton hankinnasta on esitetty tarjouspyynnössä ja sen liitteissä. Laitteiden ja varusteiden lopulliset sijoituspaikat suunnitellaan yhteistyönä tilaajan ja toimittajan kesken. Tilaaja hyväksyy tarjoajan esityksen kirjastoauton layoutista ennen valmistusprosessin alkamista.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Suensaarenkatu 4 95400 Tornio FI\", \"innovationConsidered\": false, \"procurementProjectId\": 47757, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"KIRJASTOAUTON HANKINTA \", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Tornion kaupunki on tehnyt sopimuksen kirjastoauton toimittamisesta. Kirjastoauto hankitaan alustoineen ja koritöineen katsastettuna ja tilaajan käyttöön rekisteröitynä.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"Tornio\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0193524-6\", \"tendersOrRequestsToParticipateDueDateTime\": null}',40,NULL,'2026-09-08 01:01:48','2026-09-08 01:01:48');
