INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (817,'2021-086588','HILMA','OTHER','OPEN','Työkonepalvelujen ja katujen kunnossapitotöiden hankinta','Salon kaupunki (hankintayksikkö / tilaaja) pyysi tarjouksia kunnossapitotöiden ja maanrakennustöiden työkonepalveluista kuljettajineen sekä niihin liittyvistä kuljetuspalveluista ajalle 1.5.2021 - 30.4.2026 tarjouspyynnön mukaisesti. Työkonepalveluiden hankinnassa on kyse puitejärjestelystä, jossa tilaaja voi valita useamman tarjoajan työkonepalvelujen toimittajaksi tarjouspyynnössä kuvatulla tavalla. Hankinta koskee kaupungin eri palvelualueiden sekä Liikelaitos Salon Veden käyttämiä työkonepalveluja. Työkonepalveluja kuljettajineen tarvitaan mm. kaupungin katujen ja alueiden kunnossapitoon ja maanrakentamiseen eri työmaille sekä näihin liittyviin kuljetuspalveluihin. Tarvittavia työkoneita ovat esim. kaivinkoneet, kuormaajat, kompressorit, traktorit, kuorma-autot yms. maatyökoneet.','Salon kaupunki','ANY',1,1,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-086588','[\"45500000\", \"90000000\", \"45500000\", \"90000000\", \"45500000\", \"90000000\", \"45500000\", \"90000000\", \"45500000\", \"90000000\", \"45500000\", \"90000000\", \"45500000\", \"90000000\", \"45500000\", \"90000000\", \"45500000\", \"90000000\", \"45500000\", \"90000000\", \"45500000\", \"90000000\", \"45500000\", \"90000000\", \"45500000\", \"90000000\", \"45500000\", \"90000000\", \"45500000\", \"90000000\", \"45500000\", \"90000000\", \"45500000\", \"60181000\", \"90000000\", \"45500000\", \"60181000\", \"90000000\", \"45500000\", \"60181000\", \"90000000\", \"45500000\