INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (827,'2021-088953','HILMA','RFP','OPEN','Lastenkoti Taskukellon LVI -urakka, Iisalmi','LVI-urakkana hankinta käsittää Iisalmen Lastenkoti Taskukello uudisrakennuksen LVI -teknisten töiden toteuttamisen. Hankkeessa hankintamenettelynä käytetään avointa menettelyä. Hankinnan arvo ylittää kansallisen kynnysarvon ja siihen sovelletaan lakia julkisista hankinnoista. LVI-urakkaan kuuluu asiakirjaluettelossa mainittujen suunnitelmien mukaiset putkityöt, ilmanvaihto-, jäähdytys- ja kylmätekniikkatyöt saatettuna täysin valmiiksi ja toimintakuntoon asiakirjaluettelossa mainittujen suunnitelmien mukaisesti.','Iisalmen kaupunki','ANY',10,7,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088953','[\"45331000\"]','[\"lastenkoti\", \"iisalmen\", \"asiakirjaluettelossa\", \"mainittujen\", \"suunnitelmien\", \"taskukellon\", \"urakka\", \"iisalmi\", \"urakkana\", \"hankinta\", \"käsittää\", \"taskukello\", \"uudisrakennuksen\", \"teknisten\", \"töiden\", \"toteuttamisen\", \"hankkeessa\", \"hankintamenettelynä\", \"käytetään\", \"avointa\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088953\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88953\", \"type\": 9902, \"cpvCodes\": \"45331000 Lämmitys-, ilmanvaihto- ja ilmastointilaitteiden asennustyöt\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1D2  FI1D2\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-21T08:45:13.375Z\", \"noticeNumber\": \"2021-088953\", \"proj