INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (832,'2021-088825','HILMA','RFP','OPEN','Limingan kunnan kiinteistöjen jätehuollon palvelusopimus','Limingan kunta solmii jätehuollon palvelusopimuksen hankintakilpailun perusteella. Palvelusopimus jakautuu eri osa-alueisiin: 1. kiinteät jätteet, 2. terveydenhuollon erityis- ja vaaralliset jätteet, 3. kunnan varikon vaaralliset jätteet ja rak/rem. jätteet, 4. sakat ja lietteet, 5. tietoturvapaperi ja It-tietoturva SER ja muu IT SER -jättteet, 6. pakkausmuovin aluekeräys (neljän kunnan alueella). Palvelusopimukset tehdään erikseen sekä kiinteistä jätteistä että sakoista ja lietteistä. Kiinteiden jätteiden palvelusopimukseen yhdistetään muiden osa-alueiden tehtävät, siltä osin, kun kysymyksessä on sama voittanut tarjoaja. Vertailuperusteena käytetään eri osa-alueiden kokonaishintoja. Tarjoaja voi tarjota kaikkiin tai vain yhteen kilpailutuksen osa-alueeseen.','Limingan kunta','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088825','[\"90510000\", \"90520000\", \"90400000\", \"90520000\", \"90510000\", \"90511000\", \"90500000\"]','[\"limingan\", \"jätteet\", \"kunnan\", \"kunta\", \"jätehuollon\", \"palvelusopimus\", \"vaaralliset\", \"alueiden\", \"tarjoaja\", \"kiinteistöjen\", \"solmii\", \"palvelusopimuksen\", \"hankintakilpailun\", \"perusteella\", \"jakautuu\", \"alueisiin\", \"kiinteät\", \"terveydenhuollon\", \"erityis\", \"varikon\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088825\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88825\", \"type\": 9902, \"cpvCodes\": \"90510000 Jätteiden poiskuljetus ja käsittely 90520000 Radioaktiivisia jätteitä, ongelma- ja sairaalajätteitä ja vaarallisia jätteitä koskevat palvelut 90400000 Viemäröinti 90520000 Radioaktiivisia jätteitä, ongelma- ja sairaalajätteitä ja vaarallisia jätteitä koskevat palvelut 90510000 Jätteiden poiskuljetus ja käsittely 90511000 Jätteiden keruupalvelut 90500000 Jätteisiin liittyvät palvelut\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1D9  FI1D9  FI1D9  FI1D9  FI1D9  FI1D9  FI1D9\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-20T09:46:00.624Z\", \"noticeNumber\": \"2021-088825\", \"projectTitle\": \"Limingan kunnan kiinteistöjen jätehuollon palvelusopimus\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-20T09:46:00.623Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-17T09:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Limingan kunta\", \"objectDescriptions\": \"Limingan kunnan kiinteistöjen jätehuollon kokonaishintainen osa Limingan kunta solmii jätehuollon palvelusopimuksen hankintakilpailun perusteella. Palvelusopimus jakautuu kokonaishintaiseen ja yksikköhintaiseen osaan. Yksikköhinnat annetaan erillisellä lomakkeella (liite 3). Osa 1: kilpailutus ratkaistaan kiinteistöjen kokonaishinnan perusteella (liite 1). Terveydenhuollon erityis- ja vaarallinen jäte Limingan kunta kilpailuttaa terveyskeskuksen erityisjätteen ja vaarallisen jätteen, liitteen 2, välilehti 1. mukaisesti.   Annettavaa vuoden kokonaishintaa käytetään vertailuhintana. Laskutus tapahtuu kuitenkin yksikköhinnoin, toteutunein kustannuksin. Sakat ja lietteet  Limingan kunta kilpailuttaan kunnan kohteiden sako ja lietekaivolietteet, sekä rasva- ja hiekanerotuskaivojen jätehuollon. Annettavaa vuoden kokonaishintaa käytetään vertailuhintana. Laskutus tapahtuu kuitenkin yksikköhinnoin, toteutunein kustannuksin. Varikon vaarallinen jäte ja rak/rem Palvelusopimus koskee Limingan kunnan varikon vaarallisia jätteitä, sisältäen rakennus- ja remonttijätteet sekä puhtaan puun.  Vuoden kokonaishintaa käytetään vertailuhintana. Laskutus tapahtuu toteutuneiden kustannuksien mukaan, yksikköhinnoilla. Pakkausmuovin keräys aluekeräyspisteistä Limingan kunta kilpailuttaa Lakeuden EKOn alueen pakkausmuovin keräyksen aluekeräyspisteistä. Vertailuhintana käytetään vuosikustannushintaa. Kukin kunta tekee kuitenkin itsenäisen sopimuksen urakoitsijan kanssa. Laskutus tapahtuu todellisten kustannusten perusteella.   Limingan kunnan jätehuollon kilpailutuksen kokonaisarvoon on huomioitu vain Limingan osuus pakkausmuovin kustannuksesta.  Tietoturvapaperi ja it-tietoturva Limingan kunta kilpailuttaa kunnan kiinteistöjen tietoturvapaperi sekä IT-tietoturva SER -jätteen sekä muun IT SER- jätteen. Vertailuperusteena käytetään vuosikustannushintaa. Laskutus tapahtuu todellisilla kustannuksilla.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Liminganraitti 10 C 91900 Liminka FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62699, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": \"ruoka-, puhtaus- ja kiinteistöpalveluiden liikelaitos\", \"projectTitleNormalized\": \"LIMINGAN KUNNAN KIINTEISTÖJEN JÄTEHUOLLON PALVELUSOPIMUS\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Limingan kunta solmii jätehuollon palvelusopimuksen hankintakilpailun perusteella.  Palvelusopimus jakautuu eri osa-alueisiin:  1. kiinteät jätteet, 2. terveydenhuollon erityis- ja vaaralliset jätteet, 3. kunnan varikon vaaralliset jätteet ja rak/rem. jätteet, 4. sakat ja lietteet, 5. tietoturvapaperi ja It-tietoturva SER ja muu IT SER -jättteet, 6. pakkausmuovin aluekeräys (neljän kunnan alueella).  Palvelusopimukset tehdään erikseen sekä kiinteistä jätteistä että sakoista ja lietteistä. Kiinteiden jätteiden palvelusopimukseen yhdistetään muiden osa-alueiden tehtävät, siltä osin, kun kysymyksessä on sama voittanut tarjoaja.  Vertailuperusteena käytetään eri osa-alueiden kokonaishintoja. Tarjoaja voi tarjota kaikkiin tai vain yhteen kilpailutuksen osa-alueeseen. \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"Limingan kunnan alue Limingan terveyskeskus, Liminganraitti 4 Limingan kunta Limingan kunnan varikko. Limingan, Muhoksen, Tyrnävän ja Utajärven kunnat.\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0186646-3\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-17T09:00:00Z\"}',50,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (833,'2021-089448','HILMA','RFP','OPEN','Ilmanpuhdistimien vuokraus ja hankinta kokonaispalveluna','Vantaan kaupunki pyytää tarjouksia ilmanpuhdistimien vuokraamisesta ja hankinnasta kokonaispalveluna tämän tarjouspyynnön ja sen liitteiden mukaisesti.','Vantaan kaupunki','ANY',10,4,NULL,NULL,1570000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-089448','[\"50000000\", \"39811200\"]','[\"ilmanpuhdistimien\", \"kokonaispalveluna\", \"vantaan\", \"kaupunki\", \"vuokraus\", \"hankinta\", \"pyytää\", \"tarjouksia\", \"vuokraamisesta\", \"hankinnasta\", \"tämän\", \"tarjouspyynnön\", \"liitteiden\", \"mukaisesti\", \"turku\", \"finland\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-089448\", \"name\": \"HILMA Notice\"}]','{\"id\": \"89448\", \"type\": 200, \"cpvCodes\": \"50000000 Korjaus- ja huoltopalvelut 39811200 Ilmanpuhdistimet\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1B1  FI1B1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2022-01-03T08:00:08.859Z\", \"noticeNumber\": \"2021-089448\", \"projectTitle\": \"Ilmanpuhdistimien vuokraus ja hankinta kokonaispalveluna\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-31T13:40:04.467Z\", \"isCorrigendum\": false, \"estimatedValue\": 1570000.0, \"expirationDate\": \"2022-01-31T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2022/S 001-000304\", \"organisationName\": \"Vantaan kaupunki\", \"objectDescriptions\": \" Vantaan kaupunki pyytää tarjouksia ilmanpuhdistimien vuokraamisesta ja hankinnasta kokonaispalveluna tämän tarjouspyynnön ja sen liitteiden mukaisesti.  Ilmanpuhdistimilla haetaan väliaikaista ratkaisua sisäilmaongelmien hallintaan käyttöä turvaavana toimenpiteenä. Ilmanpuhdistimien tulee olla tarkoitettu tähän käyttötarkoitukseen.   Kilpailutuksen perusteella muodostetaan puitejärjestely ilmanpuhdistimien vuokraamisesta ja hankinnasta kokonaispalveluna. Puitejärjestelyyn valitaan viisi (5) kokonaistaloudellisesti edullisimpaa toimittajaa. Puitejärjestelyn toiminta on kuvattu tarkemmin tarjouspyynnön liitteessä 1 Sopimusluonnos (sopimuskohta 6.).  Sopimusten perusteella hankintoja voivat tehdä Vantaan kaupungin kaikki toimialat ja liikelaitokset sekä kaupungin enemmistöosuudella omistamat yhtiöt Kaunialan Sairaala Oy, Vantaan Tilapalvelut Vantti Oy ja VTK Kiinteistöt Oy- konserni.  Sopimuskausi on kaksi (2) vuotta, jonka jälkeen sopimusta voidaan jatkaa kahdella (2) yhden (1) vuoden optiolla (1+1).  Hankintayksikkö ei sitoudu tarjouspyyntöasiakirjoissa ilmoitettuihin euromääräisiin arvoihin tai tiettyihin arvioituihin hankintamääriin sopimuskaudella.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"PL 1100 01030 Vantaan kaupunki FI\", \"innovationConsidered\": false, \"procurementProjectId\": 63087, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"ILMANPUHDISTIMIEN VUOKRAUS JA HANKINTA KOKONAISPALVELUNA\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Vantaan kaupunki pyytää tarjouksia ilmanpuhdistimien vuokraamisesta ja hankinnasta kokonaispalveluna tämän tarjouspyynnön ja sen liitteiden mukaisesti.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": true, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0124610-9\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-31T12:00:00Z\"}',40,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (834,'2021-089439','HILMA','RFP','OPEN','Jätehuoltopalvelut Turun paikallisyksikkö (Turku ja Lieto)','Hankinnan kohteena ovat jätehuoltopalvelut Turun paikallisyksikön toimialueella. Tarjoajiksi aikovien yritysten edustajien tulee osallistua tilaajan järjestämään hankinnan esittelytilaisuuteen.','Puolustuskiinteistöt','ANY',2,1,NULL,NULL,260000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-089439','[\"90510000\"]','[\"jätehuoltopalvelut\", \"turun\", \"hankinnan\", \"paikallisyksikkö\", \"turku\", \"lieto\", \"kohteena\", \"ovat\", \"paikallisyksikön\", \"toimialueella\", \"tarjoajiksi\", \"aikovien\", \"yritysten\", \"edustajien\", \"tulee\", \"osallistua\", \"tilaajan\", \"järjestämään\", \"esittelytilaisuuteen\", \"puolustuskiinteistöt\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-089439\", \"name\": \"HILMA Notice\"}]','{\"id\": \"89439\", \"type\": 200, \"cpvCodes\": \"90510000 Jätteiden poiskuljetus ja käsittely\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1C4  FI1C1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2022-01-03T08:00:08.327Z\", \"noticeNumber\": \"2021-089439\", \"projectTitle\": \"Jätehuoltopalvelut Turun paikallisyksikkö (Turku ja Lieto)\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-31T12:10:03.797Z\", \"isCorrigendum\": false, \"estimatedValue\": 260000.0, \"expirationDate\": \"2022-02-04T10:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2022/S 001-001030\", \"organisationName\": \"Puolustuskiinteistöt\", \"objectDescriptions\": \" Tilaaja järjestää tarjousehdokkaille hankinnan kohteen esittelytilaisuuden.  Esittelytilaisuus on 14.1.2022 klo 9.30, Puolustuskiinteistöjen Turun paikallisyksikössä, osoitteessa Heikkilän kasarmilla, Rykmentintie 15, 20810 Turku.  Osallistujien on ilmoittauduttava esittelytilaisuuteen 12.1.2022 klo 16.15 mennessä, sähköpostiosoitteeseen valtteri.salminen@puolustuskiinteistot.fi. Esittelytilaisuuteen voi osallistua 1 henkilö / yritys. Tilaisuudessa käytettävä kasvomaskeja.  Esittelytilaisuudessa esitellään hankintakohteen kartta-aineisto, jonka saa mukaansa. Esittelytilaisuuteen osallistuvilta edellytetään vaitiolovakuutuksen allekirjoittamista tilaisuudessa.  Tarjouksen jättämisen edellytyksenä on osallistuminen esittelytilaisuuteen.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Isoympyräkatu 10 49400 Hamina FI\", \"innovationConsidered\": false, \"procurementProjectId\": 63080, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"JÄTEHUOLTOPALVELUT TURUN PAIKALLISYKSIKKÖ (TURKU JA LIETO)\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Hankinnan kohteena ovat jätehuoltopalvelut Turun paikallisyksikön toimialueella.  Tarjoajiksi aikovien yritysten edustajien tulee osallistua tilaajan järjestämään hankinnan esittelytilaisuuteen.  \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"Turku ja Lieto\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"3169414-8\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-02-04T10:00:00Z\"}',40,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (835,'2021-089424','HILMA','RFP','OPEN','Kunnan vastuulla olevien lietteiden keräys ja kuljetus Raision, Maskun ja Ruskon kuntien alueilla','Urakka sisältää soveltuvalla kalustolla suoritettavan kaiken kunnan lakisääteisellä järjestämisvastuulla (jätelain 5 luku Kunnan järjestämä jätehuolto 32 § ja 33 §) olevan lietteen keräyksen. Liete tyhjennetään keräysjärjestelmistä, joita ovat mm. saostus- ja umpikaivot, pienpuhdistamot ja muut kaivoryhmät. Keräysjärjestelmä voi sisältää useamman erilaisen tyhjennettävän lietesäiliön samassa pihapiirissä. Liete tulee kuljettaa tilaajan osoittamaan vastaanottopaikkaan tilaajan lukuun. Raisiosta, Maskusta ja Ruskosta kerätyt lietteet tulee toimittaa Gasumin vastaanotto Turkuun Silakatu 16, 20380 Turku avoinna arkisin klo 6.00–20.00. Urakoitsijalla tulee olla sellaista lietteen keräyskalustoa, jolla sopimuksen mukaiset työt voidaan turvallisesti ja asianmukaisesti hoitaa. Ensisijaisesti tyhjennykset tehdään kuorma-autolla ja toissijaisesti tyhjennykset tehdään traktorilla, jolloin olosuhteet tyhjennykseen ovat sellaiset, että se sitä vaatii. Voittanut palveluntuottaja velvoitetaan hyväksymään liitteenä olevan sopimusmallin sisältö sellaiseen.','Lounais-Suomen Jätehuolto Oy','SME',1,1,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-089424','[\"90460000\"]','[\"kunnan\", \"tulee\", \"sisältää\", \"jätehuolto\", \"olevan\", \"lietteen\", \"liete\", \"ovat\", \"tilaajan\", \"tyhjennykset\", \"tehdään\", \"vastuulla\", \"olevien\", \"lietteiden\", \"keräys\", \"kuljetus\", \"raision\", \"maskun\", \"ruskon\", \"kuntien\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-089424\", \"name\": \"HILMA Notice\"}]','{\"id\": \"89424\", \"type\": 200, \"cpvCodes\": \"90460000 Lika- tai sakokaivojen tyhjennyspalvelut\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1C1  FI1C1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2022-01-03T08:00:06.582Z\", \"noticeNumber\": \"2021-089424\", \"projectTitle\": \"Kunnan vastuulla olevien lietteiden keräys ja kuljetus Raision, Maskun ja Ruskon kuntien alueilla\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-31T09:00:02.498Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-02-01T13:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2022/S 001-000970\", \"organisationName\": \"Lounais-Suomen Jätehuolto Oy\", \"objectDescriptions\": \" Kuljetusurakka suoritetaan yksikköurakkahintana, jossa yksikkönä on euroa/keräysjärjestelmän tyhjennyskerta (alv 0 %).   Yksikköurakkahintaan kuuluvat vakiotyhjennykset sekä tilaustyhjennykset, jotka tehdään tilauspäivän jälkeen neljän (4) arkipäivän sisällä. Tyhjennykset tulee tehdä klo 6.00–20.00 välisenä aikana.   Yksikköurakkahintaan kuuluu mm.  keräysajoneuvon ajaminen keräyskohteeseen, keräysjärjestelmän tyhjentäminen keräysajoneuvoon, lietteen kuljettaminen määritettyyn vastaanottopaikkaan ja kuorman purkaminen.   Tarkemmat urakkaan liittyvät tehtävät ja lisätöistä maksettavat korvaukset ovat sopimusmallissa liitteessä 1.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Kuormakatu 17 20380 Turku FI\", \"innovationConsidered\": false, \"procurementProjectId\": 63069, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"KUNNAN VASTUULLA OLEVIEN LIETTEIDEN KERÄYS JA KULJETUS RAISION, MASKUN JA RUSKON KUNTIEN ALUEILLA\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Urakka sisältää soveltuvalla kalustolla suoritettavan kaiken kunnan lakisääteisellä järjestämisvastuulla (jätelain 5 luku Kunnan järjestämä jätehuolto 32 § ja 33 §) olevan lietteen keräyksen. Liete tyhjennetään keräysjärjestelmistä, joita ovat mm. saostus- ja umpikaivot, pienpuhdistamot ja muut kaivoryhmät. Keräysjärjestelmä voi sisältää useamman erilaisen tyhjennettävän lietesäiliön samassa pihapiirissä.  Liete tulee kuljettaa tilaajan osoittamaan vastaanottopaikkaan tilaajan lukuun.   Raisiosta, Maskusta ja Ruskosta kerätyt lietteet tulee toimittaa Gasumin vastaanotto Turkuun Silakatu 16, 20380 Turku avoinna arkisin klo 6.00–20.00.    Urakoitsijalla tulee olla sellaista lietteen keräyskalustoa, jolla sopimuksen mukaiset työt voidaan turvallisesti ja asianmukaisesti hoitaa. Ensisijaisesti tyhjennykset tehdään kuorma-autolla ja toissijaisesti tyhjennykset tehdään traktorilla, jolloin olosuhteet tyhjennykseen ovat sellaiset, että se sitä vaatii.    Voittanut palveluntuottaja velvoitetaan hyväksymään liitteenä olevan sopimusmallin sisältö sellaiseen.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"Raision, Maskun ja Ruskon kuntien alueilla\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"1868393-8\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-02-01T13:00:00Z\"}',45,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (836,'2021-089365','HILMA','OTHER','OPEN','Essoten palvelutalojen asukaspyykin pesupalvelu','Etelä-Savon sosiaali- ja terveyspalvelujen kuntayhtymä (Essote) pyytää tarjousta Essoten omien palvelutalojen pesulapalvelusta. Pesulapalvelu pitää sisällään asukkaiden omien vaatteiden, liina- ja vuodevaatteiden sekä mahdollisten asiakkaiden muiden tekstiilien pesupalvelut. Palvelutaloissa suoritetaan pyykin esilajittelu ja pyykki pakataan asiakaskohtaisesti pusseihin Asiakkaiden pyykki saattaa sisältää erite- sekä eristyspyykkiä. Eristyspyykki merkitään erillisenä. Palveluntuottaja huolehtii pyykin kuljetuksesta yksikköön ja yksiköstä pois. Likapyykin noudot tulee tapahtua kaksi kertaa viikossa. Tarkemmat ajat ja päivät sovitaan yksikkökohtaisesti. Arkivaatteet, liinavaatteet sekä täkit ja tyynyt tulee palautua takaisin yksikköön 7 päivän kuluessa pyykin hakemisesta. Palveluntuottajalla on mahdollisuus tarjota optiona erikseen hintaa asiakkaiden tekstiilien merkitsemisestä. Hinta euroa/merkattu vaate. Tilaaja päättää merkkauksen käyttöönotosta erikseen palveluntuottajakohtaisesti. Tarkempi palvelukuvaus tarjouspyynnön liitteessä 1.','Etelä-Savon sosiaali- ja terveyspalvelujen kuntayhtymä','ANY',3,3,NULL,NULL,1500000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-089365','[\"98310000\"]','[\"asiakkaiden\", \"pyykin\", \"essoten\", \"palvelutalojen\", \"etelä\", \"savon\", \"sosiaali\", \"terveyspalvelujen\", \"kuntayhtymä\", \"omien\", \"tekstiilien\", \"pyykki\", \"yksikköön\", \"tulee\", \"erikseen\", \"asukaspyykin\", \"pesupalvelu\", \"essote\", \"pyytää\", \"tarjousta\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-089365\", \"name\": \"HILMA Notice\"}]','{\"id\": \"89365\", \"type\": 300, \"cpvCodes\": \"98310000 Pesu- ja kuivapesupalvelut\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractAwardNotices\", \"parentId\": 79635, \"lowCarbon\": null, \"nutsCodes\": \" FI1D1  FI1D1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-31T08:00:11.766Z\", \"noticeNumber\": \"2021-089365\", \"projectTitle\": \"Essoten palvelutalojen asukaspyykin pesupalvelu\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-30T10:20:04.906Z\", \"isCorrigendum\": false, \"estimatedValue\": 1500000.0, \"expirationDate\": \"2022-06-30T10:20:04.906Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 255-675546\", \"organisationName\": \"Etelä-Savon sosiaali- ja terveyspalvelujen kuntayhtymä\", \"objectDescriptions\": \" Etelä-Savon sosiaali- ja terveyspalvelujen kuntayhtymä (Essote) pyytää tarjousta Essoten omien palvelutalojen pesulapalvelusta.  Pesulapalvelu pitää sisällään asukkaiden omien vaatteiden, liina- ja vuodevaatteiden sekä mahdollisten asiakkaiden muiden tekstiilien pesupalvelut.  Palvelutaloissa suoritetaan pyykin esilajittelu ja pyykki pakataan asiakaskohtaisesti pusseihin Asiakkaiden pyykki saattaa sisältää erite- sekä eristyspyykkiä. Eristyspyykki merkitään erillisenä.  Palveluntuottaja huolehtii pyykin kuljetuksesta yksikköön ja yksiköstä pois. Likapyykin noudot tulee tapahtua kaksi kertaa viikossa. Tarkemmat ajat ja päivät sovitaan yksikkökohtaisesti.  Arkivaatteet, liinavaatteet sekä täkit ja tyynyt tulee palautua takaisin yksikköön 7 päivän kuluessa pyykin hakemisesta.   Palveluntuottajalla on mahdollisuus tarjota optiona erikseen hintaa asiakkaiden tekstiilien merkitsemisestä. Hinta euroa/merkattu vaate. Tilaaja päättää merkkauksen käyttöönotosta erikseen palveluntuottajakohtaisesti.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Porrassalmenkatu 35-37 50100 Mikkeli FI\", \"innovationConsidered\": false, \"procurementProjectId\": 56803, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"ESSOTEN PALVELUTALOJEN ASUKASPYYKIN PESUPALVELU\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Etelä-Savon sosiaali- ja terveyspalvelujen kuntayhtymä (Essote) pyytää tarjousta Essoten omien palvelutalojen pesulapalvelusta.  Pesulapalvelu pitää sisällään asukkaiden omien vaatteiden, liina- ja vuodevaatteiden sekä mahdollisten asiakkaiden muiden tekstiilien pesupalvelut.  Palvelutaloissa suoritetaan pyykin esilajittelu ja pyykki pakataan asiakaskohtaisesti pusseihin Asiakkaiden pyykki saattaa sisältää erite- sekä eristyspyykkiä. Eristyspyykki merkitään erillisenä.  Palveluntuottaja huolehtii pyykin kuljetuksesta yksikköön ja yksiköstä pois. Likapyykin noudot tulee tapahtua kaksi kertaa viikossa. Tarkemmat ajat ja päivät sovitaan yksikkökohtaisesti.  Arkivaatteet, liinavaatteet sekä täkit ja tyynyt tulee palautua takaisin yksikköön 7 päivän kuluessa pyykin hakemisesta.   Palveluntuottajalla on mahdollisuus tarjota optiona erikseen hintaa asiakkaiden tekstiilien merkitsemisestä. Hinta euroa/merkattu vaate. Tilaaja päättää merkkauksen käyttöönotosta erikseen palveluntuottajakohtaisesti.  Tarkempi palvelukuvaus tarjouspyynnön liitteessä 1.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0825508-3\", \"tendersOrRequestsToParticipateDueDateTime\": null}',45,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (837,'2021-089342','HILMA','OTHER','OPEN','KESKEYTYSILMOITUS:Ratasuunnittelu Tampere-Oulu, Liminka-Oulu kaksoisraiteen sekä Kankaan ja Hirvinevan liikennepaikkojen ratasuunnitelmat','Tehtävä sisältää \"Ratasuunnittelu Tampere-Oulu\" -hankkeen ratasuunnitelmien laatimisen seuraaviin suunnittelukohteisiin: • Liminka-Oulu kaksoisraiteen ratasuunnitelma • Kankaan liikennepaikan ratasuunnitelma • Hirvinevan liikennepaikan ratasuunnitelma Suunnittelusopimus sisältää Option Mestari-kisälli -toiminnasta. Optiota ei ole pakko tarjota. Yksityiskohtaisemmin suoritettava palvelu ja sen sisältö on esitetty tehtävänmäärityksissä 4.11.2021.','Väylävirasto','ANY',4,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-089342','[\"71240000\"]','[\"oulu\", \"ratasuunnitelma\", \"ratasuunnittelu\", \"tampere\", \"liminka\", \"kaksoisraiteen\", \"kankaan\", \"hirvinevan\", \"sisältää\", \"liikennepaikan\", \"väylävirasto\", \"keskeytysilmoitus\", \"liikennepaikkojen\", \"ratasuunnitelmat\", \"tehtävä\", \"hankkeen\", \"ratasuunnitelmien\", \"laatimisen\", \"seuraaviin\", \"suunnittelukohteisiin\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-089342\", \"name\": \"HILMA Notice\"}]','{\"id\": \"89342\", \"type\": 600, \"cpvCodes\": \"71240000 Arkkitehti-, insinööri- ja suunnittelupalvelut\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractAwardNotices\", \"parentId\": 85853, \"lowCarbon\": null, \"nutsCodes\": \" FI1D9  FI1D9\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-31T08:00:08.801Z\", \"noticeNumber\": \"2021-089342\", \"projectTitle\": \"KESKEYTYSILMOITUS:Ratasuunnittelu Tampere-Oulu, Liminka-Oulu kaksoisraiteen sekä Kankaan ja Hirvinevan liikennepaikkojen ratasuunnitelmat\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-30T06:55:06.094Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-06-30T06:55:06.094Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 255-676580\", \"organisationName\": \"Väylävirasto\", \"objectDescriptions\": \" Tehtävänä on laatia Liminka-Oulu kaksoisraiteen sekä Kankaan ja Hirvinevan liikennepaikkojen ratasuunnitelmat.   Liminka-Oulu kaksoisraiteen ratasuunnittelu sisältää ratasuunnitelman laatimisen Limingan ja Oulun välille, yhteensä noin 19 km matkalle. Kankaan liikennepaikan  ratasuunnittelu sisältää uuden sivuraiteen suunnittelun. Hirvinevan liikennepaikan ratasuunnittelu sisältää nykyisen liikennepaikan sivuraiteen jatkamisen sekä uuden  sivuraiteen suunnittelun.  Mahdollisen option sisältö: Tässä toimeksiannossa on optiona vapaaehtoinen mestari-kisälli -malli.  Ratasuunnittelu Tampere-Oulu hankkeen tavoitteena on parantaa rataosuuden  välityskykyä.  Sisältö on tarkemmin määritelty tarkemmin tarjouspyyntöasiakirjoissa.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"PL 33 (Opastinsilta 12 A) 00521 HELSINKI FI\", \"innovationConsidered\": false, \"procurementProjectId\": 60734, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"KESKEYTYSILMOITUS:RATASUUNNITTELU TAMPERE-OULU, LIMINKA-OULU KAKSOISRAITEEN SEKÄ KANKAAN JA HIRVINEVAN LIIKENNEPAIKKOJEN RATASUUNNITELMAT\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Tehtävä sisältää \\\"Ratasuunnittelu Tampere-Oulu\\\" -hankkeen ratasuunnitelmien laatimisen seuraaviin suunnittelukohteisiin: • Liminka-Oulu kaksoisraiteen ratasuunnitelma • Kankaan liikennepaikan ratasuunnitelma • Hirvinevan liikennepaikan ratasuunnitelma  Suunnittelusopimus sisältää Option Mestari-kisälli -toiminnasta. Optiota ei ole pakko tarjota.  Yksityiskohtaisemmin suoritettava palvelu ja sen sisältö on esitetty tehtävänmäärityksissä 4.11.2021.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"Suunnittelukohteet: Oulu, Kempele, Liminka, Ylivieska\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"1010547-1\", \"tendersOrRequestsToParticipateDueDateTime\": null}',40,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (838,'2021-089331','HILMA','RFP','OPEN','Kiinteistökaupan toteuttamisen neuvonanto ja myyntiprosessin toteuttaminen','Oulun kaupunki on päättänyt käynnistää selvityksen yhdeksän kiinteistökohteen myynnistä. Pyydämme tarjoustanne kiinteistöjen myyntiprosessin toteutuksesta ja siihen liittyvästä neuvonannosta tämän tarjouspyynnön mukaisesti. Myyntiprosessin kohteena on Oulun kaupungin suoraan omistamat kuusi palvelurakennusta, kaksi pysäköintilaitosta sekä yksi paloasema. Kohteet ovat: - Kontinkankaan hyvinvointikeskus, Kajaanintie 46 A - Kaupunginsairaala, Kiviharjuntie 5 - Pysäköintitalo kaupunginsairaala, Kiviharjuntie 5 D - Tuiran hyvinvointikeskus, Kangastie 16 - Tuiran hyvinvointikeskus, Kangastie 12 - Tuiran hyvinvointikeskus pysäköintitalo, Kangastie 14 - Intiön hoivakoti, Upseerinkatu 2 - Kiimingin hyvinvointikeskus, Terveystie 1 - Ruskonselän paloasema, Tapsitie 4B Myyntiprosessin kohteena olevien rakennusten yhteispinta-ala on noin 55 000 hum2. Rakennukset ovat julkisen palvelutoiminnan tiloja, jotka sijaitsevat keskeisellä paikalla Oulun kaupunkirakenteessa ja niillä ennakoidaan olevan pitkäaikainen käyttötarve jatkossakin. Myyntiprosessin kohteena olevat rakennukset voidaan myydä yhdelle tai useammalle ostajalle. Tavoiteaikataulu on, että Oulun kaupungin toimivaltainen toimielin päättää kiinteistökaupoista 1.6.2022 mennessä.','Oulun kaupunki','ANY',3,5,NULL,NULL,300000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-089331','[\"79410000\"]','[\"oulun\", \"myyntiprosessin\", \"hyvinvointikeskus\", \"kaupunki\", \"kohteena\", \"tuiran\", \"kangastie\", \"kaupungin\", \"paloasema\", \"ovat\", \"kaupunginsairaala\", \"kiviharjuntie\", \"pysäköintitalo\", \"rakennukset\", \"kiinteistökaupan\", \"toteuttamisen\", \"neuvonanto\", \"toteuttaminen\", \"päättänyt\", \"käynnistää\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-089331\", \"name\": \"HILMA Notice\"}]','{\"id\": \"89331\", \"type\": 200, \"cpvCodes\": \"79410000 Yritysten ja johdon konsulttipalvelut\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1D9  FI1D9\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-31T08:00:08.135Z\", \"noticeNumber\": \"2021-089331\", \"projectTitle\": \"Kiinteistökaupan toteuttamisen neuvonanto ja myyntiprosessin toteuttaminen\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-29T15:20:03.899Z\", \"isCorrigendum\": false, \"estimatedValue\": 300000.0, \"expirationDate\": \"2022-02-01T09:01:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 255-674765\", \"organisationName\": \"Oulun kaupunki\", \"objectDescriptions\": \" Palvelukokonaisuuteen sisältyy mm.seuraavien osatehtävien hoitaminen: • kohteiden myynnin valmisteluun liittyvä neuvonanto • mahdollisten ostajien identifiointi • myyntimateriaalien, sijoitusmuistioiden jne. laatiminen ja toimittaminen mahdollisille ostajille • ostajaehdokkaiden kanssa käytävät neuvottelut, myyntiprosessin organisoiminen ja koordinointi • Tilaajan edellyttämä ja mahdollisesti sovittava muu myyntiin liittyvä neuvonanto ja avustaminen • kauppakirjaluonnosten laatiminen kaikkine tarvittavine liitteineen ja niiden saattaminen allekirjoitusvalmiiksi • raportointi Tilaajan yhteyshenkilölle toimeksiannon mukaisesta toiminnastaan tarkoituksenmukaisella tavalla siten, että Tilaajalla on jatkuvasti ajantasainen         tieto toimeksiannon kohteen myyntiprosessin etenemisestä • muut tässä tarjouspyynnössä sekä tarjoajan esittämässä Työsuunnitelmassa mainitut toimenpiteet  Mikäli tehtävien suorittaminen edellyttää vero-oikeudellista selvitystyötä, tällainen selvitykset hankitaan Tilaajan tilintarkastusyhteisöltä tai sen hankkimisesta sovitaan erikseen.   \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"kirjaamo, PL 71 (Kansankatu 55A) 90015 Oulun kaupunki FI\", \"innovationConsidered\": false, \"procurementProjectId\": 63031, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"KIINTEISTÖKAUPAN TOTEUTTAMISEN NEUVONANTO JA MYYNTIPROSESSIN TOTEUTTAMINEN\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Oulun kaupunki on päättänyt käynnistää selvityksen yhdeksän kiinteistökohteen myynnistä. Pyydämme tarjoustanne kiinteistöjen myyntiprosessin toteutuksesta ja siihen liittyvästä neuvonannosta tämän tarjouspyynnön mukaisesti. Myyntiprosessin kohteena on Oulun kaupungin suoraan omistamat kuusi palvelurakennusta, kaksi pysäköintilaitosta sekä yksi paloasema. Kohteet ovat:  - Kontinkankaan hyvinvointikeskus, Kajaanintie 46 A  - Kaupunginsairaala, Kiviharjuntie 5  - Pysäköintitalo kaupunginsairaala, Kiviharjuntie 5 D - Tuiran hyvinvointikeskus, Kangastie 16 - Tuiran hyvinvointikeskus, Kangastie 12 - Tuiran hyvinvointikeskus pysäköintitalo, Kangastie 14 - Intiön hoivakoti, Upseerinkatu 2  - Kiimingin hyvinvointikeskus, Terveystie 1 - Ruskonselän paloasema, Tapsitie 4B Myyntiprosessin kohteena olevien rakennusten yhteispinta-ala on noin 55 000 hum2. Rakennukset ovat julkisen palvelutoiminnan tiloja, jotka sijaitsevat keskeisellä paikalla Oulun kaupunkirakenteessa ja niillä ennakoidaan olevan pitkäaikainen käyttötarve jatkossakin. Myyntiprosessin kohteena olevat rakennukset voidaan myydä yhdelle tai useammalle ostajalle.   Tavoiteaikataulu on, että Oulun kaupungin toimivaltainen toimielin päättää kiinteistökaupoista 1.6.2022 mennessä. \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"Oulun kaupunki\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0187690-1\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-02-01T09:01:00Z\"}',45,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (839,'2021-089552','HILMA','RFP','OPEN','Lopen koulukeskus, liikuntahalli (rakennusurakka)','Lopen kunnan kirkonkylän taajamassa sijaitsevan koulukeskuksen yhteyteen on suunniteltu rakennettavaksi uusi liikuntahalli. Uudisrakennuksen osoite on Opintie 6, 12700 Loppi.','Lopen kunta','ANY',2,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-089552','[\"45000000\", \"45000000\"]','[\"lopen\", \"liikuntahalli\", \"kunta\", \"koulukeskus\", \"rakennusurakka\", \"kunnan\", \"kirkonkylän\", \"taajamassa\", \"sijaitsevan\", \"koulukeskuksen\", \"yhteyteen\", \"suunniteltu\", \"rakennettavaksi\", \"uusi\", \"uudisrakennuksen\", \"osoite\", \"opintie\", \"loppi\", \"finland\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-089552\", \"name\": \"HILMA Notice\"}]','{\"id\": \"89552\", \"type\": 9902, \"cpvCodes\": \"45000000 Rakennustyöt 45000000 Rakennustyöt\", \"currency\": null, \"isLatest\": false, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI  FI\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2022-01-03T12:21:05.043Z\", \"noticeNumber\": \"2021-089552\", \"projectTitle\": \"Lopen koulukeskus, liikuntahalli (rakennusurakka)\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-31T14:25:23.385Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-02-01T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Lopen kunta\", \"objectDescriptions\": \" Lopen  kirkonkylään on suunniteltu rakennettavaksi uusi liikuntahalli, jonka rakentaminen ajoittuu kevään 2022 ja kevään 2023 ajankohdalle. Tämä halli tulee sijoittumaan olemassa olevan koulukeskuksen yhteyteen. Uudisrakennuksen osoite on Opintie 6, 127600 Loppi.   Hanke aloittaminen on ehdollinen ja vaatii ennen aloittamista Lopen kunnanvaltuuston rakentamista koskevan aloituspäätöksen 2/2022, missä  yhteydessä hankkeen urakkatarjousten mukaiset kustannukset tulee olla käytettävissä.   Tämä hankinta koskee uuden uuden liikuntahallin rakennusurakkaa.  Huomioitavaa on, että hanke on määritetty rakennusluvassa rakenteiltaan poikkeuksellisen vaativaksi rakennuskohteeksi. \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Yhdystie 5 12700 Loppi FI\", \"innovationConsidered\": false, \"procurementProjectId\": 63138, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"LOPEN KOULUKESKUS, LIIKUNTAHALLI (RAKENNUSURAKKA)\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Lopen kunnan kirkonkylän taajamassa sijaitsevan koulukeskuksen yhteyteen on suunniteltu rakennettavaksi uusi liikuntahalli. Uudisrakennuksen osoite on Opintie 6, 12700 Loppi. \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"Lopen kunta, kirkonkylän taajaman koulukeskus. Osoite Opintie 6, 12700 Loppi.\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0150919-1\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-02-01T12:00:00Z\"}',40,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (840,'2021-088178','HILMA','RFP','OPEN','Sähköisen allekirjoituksen palvelut','LapIT Oy (Tilaaja) on kuntien ja kuntayhtymien omistama ICT ja tiedonhallintapalveluita tuottava in-house yhtiö. Omistaja-asiakkaisiimme lukeutuu tällä hetkellä yhteensä 28 organisaatiota ja toiminta-alueemme kattaa Koillismaan ja Lapin maakunnan alueet. LapIT Oy pyytää tarjouksia sähköisen allekirjoituksen palveluista. Tilaajalla on oikeus tämän tarjouspyynnön perusteella tehdyn hankintasopimuksen perusteella myydä ostettavia sähköisen allekirjoituksen palveluita eteenpäin asiakkailleen. Sopimus on voimassa kolme (3) vuotta sen allekirjoittamisesta, jonka jälkeen tilaajalla on mahdollisuus jatkaa sopimusta toistaiseksi voimassa olevana. Tämä tarjouspyyntö muodostuu tästä tarjouspyyntöasiakirjasta sekä seuraavista liitteistä: Liite 1: Vaatimusmäärittely Liite 2: Palvelukuvaus Liite 3: Palvelutasot Liite 4: Käyttötapaukset Liite 5: Tietosuojasopimus Liite 6: Tietoturvallisuussopimus Liite 7: Salassapitosopimus Liite 8: JIT2015 Erityisehtoja tietoverkon välityksellä toimitettavista palveluista Liite 9: JIT2015 Erityisehtoja konsultointipalveluista Liite 10: JIT2015 Yleiset sopimusehdot Liite 11: Sopimusluonnos','LapIT Oy','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088178','[\"72250000\", \"72600000\", \"72000000\"]','[\"liite\", \"lapit\", \"sähköisen\", \"allekirjoituksen\", \"palveluista\", \"tilaajalla\", \"perusteella\", \"voimassa\", \"erityisehtoja\", \"palvelut\", \"tilaaja\", \"kuntien\", \"kuntayhtymien\", \"omistama\", \"tiedonhallintapalveluita\", \"tuottava\", \"house\", \"yhtiö\", \"omistaja\", \"asiakkaisiimme\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088178\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88178\", \"type\": 9902, \"cpvCodes\": \"72250000 Järjestelmä- ja tukipalvelut 72600000 Tietotekniset tuki- ja neuvontapalvelut 72000000 Tietotekniset palvelut: neuvonta, ohjelmistojen kehittäminen, Internet ja tuki\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1D7  FI1D7\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-10T11:48:04.195Z\", \"noticeNumber\": \"2021-088178\", \"projectTitle\": \"Sähköisen allekirjoituksen palvelut \", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-10T11:48:04.195Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-14T15:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"LapIT Oy\", \"objectDescriptions\": \" Tarjouspyyntö koskee sähköisen allekirjoituksen palveluita tämän tarjouspyynnön ja sen liitteiden mukaisesti. \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Rantavitikantie 33 96300 Rovaniemi FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62290, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"SÄHKÖISEN ALLEKIRJOITUKSEN PALVELUT \", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"LapIT Oy (Tilaaja) on kuntien ja kuntayhtymien omistama ICT ja  tiedonhallintapalveluita tuottava in-house yhtiö. Omistaja-asiakkaisiimme lukeutuu  tällä hetkellä yhteensä 28 organisaatiota ja toiminta-alueemme kattaa Koillismaan ja  Lapin maakunnan alueet.   LapIT Oy pyytää tarjouksia sähköisen allekirjoituksen palveluista. Tilaajalla on oikeus tämän tarjouspyynnön perusteella tehdyn hankintasopimuksen perusteella myydä ostettavia sähköisen allekirjoituksen palveluita eteenpäin asiakkailleen.  Sopimus on voimassa kolme (3) vuotta sen allekirjoittamisesta, jonka jälkeen tilaajalla on mahdollisuus jatkaa sopimusta toistaiseksi voimassa olevana.   Tämä tarjouspyyntö muodostuu tästä tarjouspyyntöasiakirjasta sekä seuraavista liitteistä: Liite 1: Vaatimusmäärittely Liite 2: Palvelukuvaus  Liite 3: Palvelutasot  Liite 4: Käyttötapaukset Liite 5: Tietosuojasopimus Liite 6: Tietoturvallisuussopimus Liite 7: Salassapitosopimus  Liite 8: JIT2015 Erityisehtoja tietoverkon välityksellä toimitettavista palveluista Liite 9: JIT2015 Erityisehtoja konsultointipalveluista  Liite 10: JIT2015 Yleiset sopimusehdot Liite 11: Sopimusluonnos\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": null, \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"1637268-5\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-14T15:00:00Z\"}',70,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
