INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (847,'2021-087939','HILMA','RFP','OPEN','OSALLISTUMISHAKEMUSPYYNTÖ: Tekoälyavusteinen itsepalveluanalytiikkaohjelmisto','Verohallinnolla on tarve hankkia itsepalveluanalytiikkaohjelmisto (valmisohjelmisto) sekä sen käyttöönottoon ja ylläpitoon liittyvää palvelua (käyttöönottoprojekti, käyttäjätuki). Verohallinto saa jatkuvasti käyttöönsä suuria tietovirtoja, joiden tiedot tulee kyetä analysoimaan nopeasti, tarkasti ja kustannustehokkaasti verotuksen käyttöön. Verohallinnon tavoitteena on hankkia ohjelmisto, joka tukee jatkossa itsepalveluanalytiikkaa ja tekoälyn hyödyntämistä sekä kasvattaa Verohallinnon ydintoiminnan vaikuttavuutta.','Verohallinto','ANY',1,13,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-087939','[\"48000000\"]','[\"verohallinto\", \"itsepalveluanalytiikkaohjelmisto\", \"hankkia\", \"verohallinnon\", \"osallistumishakemuspyyntö\", \"tekoälyavusteinen\", \"verohallinnolla\", \"tarve\", \"valmisohjelmisto\", \"käyttöönottoon\", \"ylläpitoon\", \"liittyvää\", \"palvelua\", \"käyttöönottoprojekti\", \"käyttäjätuki\", \"jatkuvasti\", \"käyttöönsä\", \"suuria\", \"tietovirtoja\", \"joiden\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-087939\", \"name\": \"HILMA Notice\"}]','{\"id\": \"87939\", \"type\": 200, \"cpvCodes\": \"48000000 Ohjelmatuotteet ja tietojärjestelmät\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": 80318, \"lowCarbon\": null, \"nutsCodes\": \" FI  FI\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-10T08:00:16.277Z\", \"noticeNumber\": \"2021-087939\", \"projectTitle\": \"OSALLISTUMISHAKEMUSPYYNTÖ: Tekoälyavusteinen itsepalveluanalytiikkaohjelmisto\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-09T16:45:08.09Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-14T15:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 240-630296\", \"organisationName\": \"Verohallinto\", \"objectDescriptions\": \" Itsepalveluanalytiikkaohjelmiston hankinnalla on tarkoitus tehostaa datan loppukäyttäjien työtä helpottamalla tekoälyavusteisesti esim. suurten maksutapahtuma-aineistojen analysointia (\\\"automaattinen analysointi\\\"). Lisäksi ohjelmiston on tarkoitus tarjota analyytikoille ja muille asiantuntijoille kyvykkyyksiä löytää tarvittava tieto tehokkaasti ja tarkasti. Avainsanana on analysoinnin nopeus (ei tarvetta SQL-lauseiden tai kuutioiden käytölle) sekä käyttöliittymän helppokäyttöisyys.   \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Vääksyntie 4, Helsinki 00052 Vero FI\", \"innovationConsidered\": false, \"procurementProjectId\": 57181, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"OSALLISTUMISHAKEMUSPYYNTÖ: TEKOÄLYAVUSTEINEN ITSEPALVELUANALYTIIKKAOHJELMISTO\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Verohallinnolla on tarve hankkia itsepalveluanalytiikkaohjelmisto (valmisohjelmisto) sekä sen käyttöönottoon ja ylläpitoon liittyvää palvelua (käyttöönottoprojekti, käyttäjätuki).  Verohallinto saa jatkuvasti käyttöönsä suuria tietovirtoja, joiden tiedot tulee kyetä analysoimaan nopeasti, tarkasti ja kustannustehokkaasti verotuksen käyttöön. Verohallinnon tavoitteena on hankkia ohjelmisto, joka tukee jatkossa itsepalveluanalytiikkaa ja tekoälyn hyödyntämistä sekä kasvattaa Verohallinnon ydintoiminnan vaikuttavuutta.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0245458-3\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-14T15:00:00Z\"}',55,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (848,'2021-087934','HILMA','RFP','OPEN','Tilapäiset siivous- ja ikkunanpesupalvelut','TeeSe Botnia Oy Ab pyytää tarjouksia tilapäisistä siivous- ja ikkunanpesupalveluista puitejärjestelyn muodostamiseksi toistaiseksi voimassa olevalle sopimuskaudelle. Hankintaon jaettu kahteen (2) osa-alueeseen: 1. Tilapäiset ylläpito- ja perussiivoukset 2. Ikkunanpesupalvelut Palveluja tilataan pääsääntöisesti Vaasan kaupungin alueelle, jonka lisäksi palveluja tilataan vähäisemmässä määrin myös Vähänkyrön ja Laihian alueille. Kaikkien hintojen edellytetään olevan voimassa kaikille alueille, Vähänkyrön ja Laihian alueiden osalta hyväksytään lisäksi erikseen ennalta sovittavat matkakustannukset. Hankinnasta muodostetaan puitejärjestely tarjousvertailun perusteella kolmen (3) kokonaistaloudellisesti edullisimmaksi arvioidun tarjoajan kanssa per osa-alue tarjouspyynnön liitteenä olevan hankintasopimusluonnoksen mukaisesti. Sopimuskauden tavoitteellinen alkamisajankohta on 1.2.2022.','TeeSe Botnia Oy Ab','ANY',10,14,NULL,NULL,1800000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-087934','[\"90910000\", \"90911300\", \"90910000\"]','[\"teese\", \"botnia\", \"tilapäiset\", \"siivous\", \"ikkunanpesupalvelut\", \"voimassa\", \"palveluja\", \"tilataan\", \"lisäksi\", \"vähänkyrön\", \"laihian\", \"alueille\", \"olevan\", \"pyytää\", \"tarjouksia\", \"tilapäisistä\", \"ikkunanpesupalveluista\", \"puitejärjestelyn\", \"muodostamiseksi\", \"toistaiseksi\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-087934\", \"name\": \"HILMA Notice\"}]','{\"id\": \"87934\", \"type\": 200, \"cpvCodes\": \"90910000 Siivous- ja puhdistuspalvelut 90911300 Ikkunanpesupalvelut 90910000 Siivous- ja puhdistuspalvelut\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": 83033, \"lowCarbon\": null, \"nutsCodes\": \" FI195  FI195  FI195\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-10T08:00:15.579Z\", \"noticeNumber\": \"2021-087934\", \"projectTitle\": \"Tilapäiset siivous- ja ikkunanpesupalvelut\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-09T15:15:07.116Z\", \"isCorrigendum\": false, \"estimatedValue\": 1800000.0, \"expirationDate\": \"2022-01-05T11:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 240-632157\", \"organisationName\": \"TeeSe Botnia Oy Ab\", \"objectDescriptions\": \"Osa-alue 1. Tilapäiset ylläpito- ja perussiivoukset Kilpailutettava osa-alue 1 sisältää Teese Botnia Oy:n Puhdistuspalvelujen tilaamat tipäiset siivouspalvelut mm. seuraavissa tilanteissa: - vakituisen työntekijän poissaolosta johtuvat tilapäiset tarpeet esim. sairaala-, toimisto-, koulu- ja päiväkotisiivous - tapahtumien aiheuttamat siivoustarpeet esim. kouluissa tai muissa kaupungin kiinteistöissä järjestettävät tilaisuudet - rakennustyömaiden ylläpito- ja loppusiivoukset - perussiivoukset  Tarpeet siivouspalvelulle ovat pääosin ennalta arvaamattomia, jolloin palvelu voidaan tarvita nopeasti ja se on usein ajallisesti lyhytkestoista.   Tiloissa tulee olla aina tarvittava määrä henkilöstöä, jotta siivous voidaan suorittaa työturvallisesti, laadukkaasti ja ammattitaidolla.  Tilattavan palvelun ajankohdasta sovitaan erikseen tilaajan kanssa.  Osa-alue 2. Ikkunanpesupalvelut (arkipäivätyö klo 6-21) Kilpailutettava osa-alue 2 sisältää Teese Botnia Oy:n Puhdistuspalvelujen tilaamat ikkunanpesut käsikäyttöisin työvälinein sekä nostolaitteiden avulla toteutettavista ikkunanpesuista. Ikkunanpesupalvelua hankitaan ns. tavanomaisesti saavutettaviin kohteisiin sekä hankalasti puhdistettaviin kohteisiin (nostinta tai valjaita vaativat, tai muuten hankalasti puhdistettavat ikkunat).    Ikkunanpesua käsityövälinein tai nostolaitteen avulla hankitaan eri tyyppisiin kiinteistöihin, kuten päiväkoteihin, kouluihin, kulttuuritiloihin, liikuntapaikkoihin ja muihin toimitiloihin.   Tarpeet ikkunanpesupalveluille syntyy pääsääntöisesti keväällä ja mahdollisesti syksyllä, jolloin palvelu voidaan tarvita nopeasti ja se on usein ajallisesti lyhytkestoista.  Tiloissa tulee olla aina tarvittava määrä henkilöstöä, jotta siivous voidaan suorittaa työturvallisesti, laadukkaasti ja ammattitaidolla.  Tilattavan palvelun ajankohdasta sovitaan erikseen tilaajan kanssa.  \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Sorakatu 2-4 65100 Vaasa FI\", \"innovationConsidered\": false, \"procurementProjectId\": 58887, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"TILAPÄISET SIIVOUS- JA IKKUNANPESUPALVELUT\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"TeeSe Botnia Oy Ab pyytää tarjouksia tilapäisistä siivous- ja ikkunanpesupalveluista puitejärjestelyn muodostamiseksi toistaiseksi voimassa olevalle sopimuskaudelle.   Hankintaon jaettu kahteen (2) osa-alueeseen: 1. Tilapäiset ylläpito- ja perussiivoukset  2. Ikkunanpesupalvelut  Palveluja tilataan pääsääntöisesti Vaasan kaupungin alueelle, jonka lisäksi palveluja tilataan vähäisemmässä määrin myös Vähänkyrön ja Laihian alueille. Kaikkien hintojen edellytetään olevan voimassa kaikille alueille, Vähänkyrön ja Laihian alueiden osalta hyväksytään lisäksi erikseen ennalta sovittavat matkakustannukset.    Hankinnasta muodostetaan puitejärjestely tarjousvertailun perusteella kolmen (3) kokonaistaloudellisesti edullisimmaksi arvioidun tarjoajan kanssa per osa-alue tarjouspyynnön liitteenä olevan hankintasopimusluonnoksen mukaisesti.  Sopimuskauden tavoitteellinen alkamisajankohta on 1.2.2022.   \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": true, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"2859365-3\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-05T11:00:00Z\"}',40,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
