INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (851,'2021-087900','HILMA','RFI','OPEN','Sosiaalihuoltolain ja lastensuojelulain mukaisten lasten ja perheiden palveluiden hankinta','Oulun kaupunki on valmistelemassa uutta hankintaa sosiaalihuoltolain ja lastensuojelulain mukaisten lasten ja perheiden palveluiden hankinnasta. Oulun kaupunki toteuttaa hankinnan ja kutsuu Pohjois-Pohjanmaan kuntia hankintayhteistyöhön. Uusi sopimus siirtyy hyvinvointialueelle 1.1.2023. Tuleva hankinta on tarkoitus toteuttaa joustavana sähköisenä palveluntuottajarekisterinä. Osallistumispyynnön arvioitu julkaisuaika on tammikuun loppu 2022. Suunnitellut palvelut hankinnassa ovat: - Perhetyö - Lapsiperheiden kotipalvelu ja kotipalvelun tukipalvelut - Sosiaalisen kuntoutuksen palvelu - Ammatillinen tukihenkilötoiminta - Lapsen ja vanhemman tapaamisten valvonta - Tukiperheiden ja perhehoidon valmennuksen ja tuen kokonaisuus - Tehostettu perhetyö - Perhekuntoutus - Sijoitus avohuollon tukitoimena - Sijaishuollon palvelut lastensuojelulaitoksessa ja ammatillisessa perhekodissa - Erityisen huolenpidon järjestäminen lastensuojelulaitoksessa - Kasvatus- ja perheneuvonta - Kehittämispalvelut INFO-TILAISUUS Palveluntuottajille pidetään info-tilaisuus uudesta hankinnasta ti 11.1.2022 klo 13 – 14 Teams-ympäristössä. Ilmoittaudu infoon linkistä: https://zef.fi/s/cqv96n59/ viimeistään 10.1.2022 klo 15.00, niin saat tilaisuuteen osallistumislinkin. Linkki toimitetaan viimeistään ti 11.1. aamuna.','Oulun kaupunki','ANY',3,5,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-087900','[\"85300000\", \"85100000\", \"85300000\", \"85100000\", \"85300000\", \"85300000\", \"85300000\", \"85100000\", \"79400000\", \"85000000\", \"85000000\"]','[\"oulun\", \"kaupunki\", \"sosiaalihuoltolain\", \"lastensuojelulain\", \"mukaisten\", \"lasten\", \"perheiden\", \"palveluiden\", \"hankinta\", \"hankinnasta\", \"toteuttaa\", \"palvelut\", \"perhetyö\", \"lastensuojelulaitoksessa\", \"info\", \"tilaisuus\", \"viimeistään\", \"valmistelemassa\", \"uutta\", \"hankintaa\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-087900\", \"name\": \"HILMA Notice\"}]','{\"id\": \"87900\", \"type\": 2101, \"cpvCodes\": \"85300000 Sosiaalityö ja siihen liittyvät palvelut 85100000 Terveyspalvelut 85300000 Sosiaalityö ja siihen liittyvät palvelut 85100000 Terveyspalvelut 85300000 Sosiaalityö ja siihen liittyvät palvelut 85300000 Sosiaalityö ja siihen liittyvät palvelut 85300000 Sosiaalityö ja siihen liittyvät palvelut 85100000 Terveyspalvelut 79400000 Yrityskonsultointi, johdon konsultointi ja niihin liittyvät palvelut 85000000 Terveyspalvelut ja sosiaalitoimen palvelut 85000000 Terveyspalvelut ja sosiaalitoimen palvelut\", \"currency\": null, \"isLatest\": true, \"mainType\": \"PriorInformationNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1D9  FI  FI  FI  FI  FI  FI  FI\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-10T08:00:11.864Z\", \"noticeNumber\": \"2021-087900\", \"projectTitle\": \"Sosiaalihuoltolain ja lastensuojelulain mukaisten lasten ja perheiden palveluiden hankinta\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-09T11:35:06.915Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-06-09T11:35:06.915Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 240-633459\", \"organisationName\": \"Oulun kaupunki\", \"objectDescriptions\": \"LUOKKA 1 Sosiaalihuollon lapsi- ja perhepalvelut Hankinnan kohteen luokassa 1 ovat perhetyö, lapsiperheiden kotipalvelu ja kotipalvelun tukipalvelut, sosiaalisen kuntoutuksen palvelu, ammatillinen tukihenkilötoiminta, lapsen ja vanhemman tapaamisten valvonta sekä kasvatus- ja perheneuvonta.  LUOKKA 2 Lastensuojelun avopalvelut Hankinnan kohteena luokassa 2 ovat ammatillinen tukihenkilötoiminta, lapsen ja vanhemman tapaamisten valvonta, tehostettu perhetyö ja perhekuntoutus.  LUOKKA 3 Perhehoidon tukipalvelut Hankinnan kohteena luokassa 3 ovat tukiperheiden ja perhehoidon valmennuksen ja tuen kokonaisuus. LUOKKA 4 Ammatilliset perhekotipalvelut Hankinnan kohteena luokassa 4 on ammatillisessa perhekodissa toteutuva lapsen sijoitus avohuollon tukitoimena ja sijaishuollon palvelu. Ammatillinen perhehoito on perhehoitoa, jota annetaan yksityisistä sosiaalipalveluista annetun lain 7 §:ssä tarkoitetun luvan perusteella ammatillisessa perhekodissa. LUOKKA 5 Lastensuojelulaitosten palvelut Hankinnan kohteena luokassa 5 on lastensuojelulaitoksessa toteutuva perhekuntoutus, lapsen sijoitus avohuollon tukitoimena, sijaishuollon palvelu ja erityisen huolenpidon järjestäminen.  Lastensuojelulaitoksia ovat lastensuojelulain 57 §:n tarkoittamat lastenkodit ja koulukodit sekä muut näihin rinnastettavat lastensuojelulaitokset. LUOKKA 6 Kehittämispalvelut Luokan 6 Kehittämispalvelu on lasten, nuorten ja perheiden palveluiden moniammatillista, erikoistuneiden asiantuntijoiden toteuttamaa asiantuntijapalvelua. Kehittämispalvelun tavoitteena voi olla muun muassa palvelun laadun ja vaikuttavuuden kehittäminen, asiakkaiden osallisuuden ja osallistumisen mahdollisuuksien kehittäminen, monialaisen yhteistyön kehittäminen, kannustin- ja sanktiojärjestelmien kehittäminen ja muu vastaava palveluihin ja palvelujärjestelmään liittyvä kehittäminen.  LUOKAT 7, 8, 9 ja 10 Hankintayksikkö voi perustaa uusia luokkia myöhemmin palveluntuottajarekisterin voimassaoloaikana. \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"PL 27 90015 Oulun kaupunki FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62104, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"SOSIAALIHUOLTOLAIN JA LASTENSUOJELULAIN MUKAISTEN LASTEN JA PERHEIDEN PALVELUIDEN HANKINTA\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Oulun kaupunki on valmistelemassa uutta hankintaa sosiaalihuoltolain ja lastensuojelulain mukaisten lasten ja perheiden palveluiden hankinnasta.  Oulun kaupunki toteuttaa hankinnan ja kutsuu Pohjois-Pohjanmaan kuntia hankintayhteistyöhön. Uusi sopimus siirtyy hyvinvointialueelle 1.1.2023.  Tuleva hankinta on tarkoitus toteuttaa joustavana sähköisenä palveluntuottajarekisterinä.  Osallistumispyynnön arvioitu julkaisuaika on tammikuun loppu 2022.  Suunnitellut palvelut hankinnassa ovat: - Perhetyö - Lapsiperheiden kotipalvelu ja kotipalvelun tukipalvelut - Sosiaalisen kuntoutuksen palvelu - Ammatillinen tukihenkilötoiminta - Lapsen ja vanhemman tapaamisten valvonta - Tukiperheiden ja perhehoidon valmennuksen ja tuen kokonaisuus - Tehostettu perhetyö - Perhekuntoutus  - Sijoitus avohuollon tukitoimena - Sijaishuollon palvelut lastensuojelulaitoksessa ja ammatillisessa perhekodissa - Erityisen huolenpidon järjestäminen lastensuojelulaitoksessa - Kasvatus- ja perheneuvonta - Kehittämispalvelut    INFO-TILAISUUS  Palveluntuottajille pidetään info-tilaisuus uudesta hankinnasta ti 11.1.2022 klo 13 – 14 Teams-ympäristössä.   Ilmoittaudu infoon linkistä: https://zef.fi/s/cqv96n59/ viimeistään 10.1.2022 klo 15.00, niin saat tilaisuuteen osallistumislinkin. Linkki toimitetaan viimeistään ti 11.1. aamuna. \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0187690-1\", \"tendersOrRequestsToParticipateDueDateTime\": null}',40,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (852,'2021-088071','HILMA','RFP','OPEN','Kauniaisten kaupungin metsäkuvioiden hoitotyöt 2022-2023','Kauniaisten kaupungin luonnonhoito-suunnitelman mukaiset vuosien 2022-2023 metsäkuvioiden hoitotyöt.','Kauniaisten kaupunki','ANY',10,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088071','[\"77200000\"]','[\"kauniaisten\", \"kaupungin\", \"metsäkuvioiden\", \"hoitotyöt\", \"luonnonhoito\", \"suunnitelman\", \"mukaiset\", \"vuosien\", \"kaupunki\", \"turku\", \"finland\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088071\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88071\", \"type\": 9902, \"cpvCodes\": \"77200000 Metsänhoitopalvelut\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1B1  FI1B1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-09T11:16:37.872Z\", \"noticeNumber\": \"2021-088071\", \"projectTitle\": \"Kauniaisten kaupungin metsäkuvioiden hoitotyöt 2022-2023\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-09T11:16:37.871Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-14T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Kauniaisten kaupunki\", \"objectDescriptions\": \" Hankinnan kohteena ovat Kauniaisten kaupungin luonnonhoito-suunnitelmassa vuosille 2022-2023 (kuvion 172 kohdalla vuodelle 2024) esitetyt metsäkuvioiden hoitotyöt: metsäkuviot 3, 14, 21, 23, 24, 26, 37, 39, 40, 41, 49, 59, 63, 75, 76, 79, 120, 137, 141, 142, 146, 148, 150, 163, 165, 172, 173, 179, 180, 182, 184, 192, 195, 199, 200, 201, 208, 222, 232, 238, 245, 247, 249, 252, 260, 267, 270, 271, 273 ja 277.   \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"PL 52 02701 Kauniainen FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62222, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": \"Kuntatekniikka\", \"projectTitleNormalized\": \"KAUNIAISTEN KAUPUNGIN METSÄKUVIOIDEN HOITOTYÖT 2022-2023\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Kauniaisten kaupungin luonnonhoito-suunnitelman mukaiset vuosien 2022-2023 metsäkuvioiden hoitotyöt.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"mainsiteplaceWorksDeliveries\": \"Kauniainen\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0203026-2\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-14T12:00:00Z\"}',40,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (853,'2021-088058','HILMA','RFP','OPEN','VM-digikehityshankkeen projektipäällikkö','Tarjouspyyntö koskee projektipäällikön tehtävää Helsingin kaupungin johtamassa, valtionvarainministeriön rahoittamassa hankkeessa \"Kunnan rakennusvalvonnan sähköisen lupaprosessin edelleen kehittäminen ja prosessien automatisointi\". Hankkeessa on mukana 26 kuntaa. Hankkeen päähakijana ja hallinnoijana toimii Helsingin kaupungin kaupunkiympäristön toimiala. Hankkeeseen kuuluvat Helsingin kaupungin lisäksi seuraavat kunnat ja kaupungit: Espoo, Hämeenlinna, Joensuu, Jyväskylä, Kuopio, Lahti, Mikkeli, Oulu, Pori, Salo, Seinäjoki, Tampere, Turku, Vantaa, Hyvinkää, Järvenpää, Lohja, Kirkkonummi, Sipoo, Tuusula, Ylöjärvi, Äänekoski, Iisalmi, Asikkala ja Sysmä. Kuntaliitto tukee hankeen toteutumista. Hankkeen toteuttamisaika on 9/2021-10/2023. Tarjousten vertailuperuste on kokonaistaloudellinen edullisuus, joka muodostuu kokonaisuudessaan laadullisista kriteereistä (100 %), eli ns. käänteinen kilpailutus. Hankinnan kokonaishinta on 70 000 euroa (alv 0 %). Hankinnan kohteena oleva asiantuntijapalvelu jakaantuu seuraaviin tehtäviin: - Kehityshankkeen läpivienti hankkeen budjetin ja aikataulun mukaisesti yhteistyössä ohjausryhmän kanssa. Hankkeen projektisuunnitelman ja toteutusten jatkuva tarkentaminen ja osallistuminen hankkeen hankintojen määrittelyyn. - Yhteiskehittäminen hankkeessa mukana olevien kuntien kanssa sekä hankkeessa toimivien ohjelmistotoimittajien kehitystyön koordinointi ja laadunvalvonta. Yhteistyö muiden sidosryhmien, kuten valtion organisaatioiden, kanssa. - Hankkeen sisäinen viestintä ja tarvittaessa osallistuminen ulkoiseen viestintään. - Hankkeen dokumentointi sekä VM:lle tehtävän raportoinnin koordinointi. Tarjoajien tasapuolisen ja syrjimättömän kohtelun turvaamiseksi sekä kilpailun vääristymisen estämiseksi sama yritys tai siihen liittyvä yritys ei voi toimia sekä ”Kunnan rakennusvalvonnan sähköisen lupaprosessin edelleen kehittäminen ja prosessien automatisointi” -hankkeessa projektipäällikön tehtävässä että hankkeen ohjelmistotoimittajana, koska projektipäällikön tehtävään kuuluu hankintojen määrittelytyötä ja ohjelmistotoimittajien työn laadunvalvontaa. Hankintayksiköllä voi olla velvollisuus sulkea tästä kilpailutuksesta tarjoaja tai tarjoajaan liittyvä yritys, joka on mukana ”Kunnan rakennusvalvonnan sähköisen lupaprosessin edelleen kehittäminen ja prosessien automatisointi” -hankkeessa ohjelmistotoimittajan roolissa.','Helsingin kaupunki, kaupunkiympäristön toimiala','ANY',1,4,NULL,NULL,70000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088058','[\"73000000\"]','[\"hankkeen\", \"hankkeessa\", \"helsingin\", \"projektipäällikön\", \"kaupungin\", \"kunnan\", \"rakennusvalvonnan\", \"sähköisen\", \"lupaprosessin\", \"edelleen\", \"kehittäminen\", \"prosessien\", \"automatisointi\", \"mukana\", \"kanssa\", \"yritys\", \"kaupunkiympäristön\", \"toimiala\", \"turku\", \"hankinnan\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088058\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88058\", \"type\": 9902, \"cpvCodes\": \"73000000 (4) Tutkimus- ja kehityspalvelut ja niihin liittyvät konsulttipalvelut\", \"currency\": \"EUR\", \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1B1  FI1B1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-09T09:17:11.334Z\", \"noticeNumber\": \"2021-088058\", \"projectTitle\": \" VM-digikehityshankkeen projektipäällikkö \", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-09T09:17:11.333Z\", \"isCorrigendum\": false, \"estimatedValue\": 70000.0, \"expirationDate\": \"2021-12-28T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Helsingin kaupunki, kaupunkiympäristön toimiala\", \"objectDescriptions\": \" Hankkeessa aloitetaan konkreettisesti rakennuslupatarkastusten automatisointi lupakäsittelyn nopeuttamiseksi. Hankkeen alussa määritellään, mitkä rakennuslupaprosessin vaiheet voidaan suorittaa automaattisesti ilman ihmisen tulkinta- tai harkintatyötä, yhtenäiset säännöt tulkinnoille sekä yhteinen standarditarkastussäännöstö. Toteutetaan automatisoituja prosesseja.  Hankkeessa kehitetään ohjelmistoihin kyvykkyys myös IFC-mallien hallintaan ja tietojen automaattisiin välityksiin. Toteutetaan tarvittavat ominaisuustieto- ja koordinaattitietolataukset IFC-mallista kuntien eri rekistereihin. Toteutetaan IFC-mallin automaattinen vienti kunnan 3D-kaupunkimalliin. Kehitetään lupakynnyksen alittavien rakennustietojen vastaanottoa ja hallintaa sekä tietojen edelleenvälitys esimerkiksi kunnan mittaustoimelle rajapintojen kautta. Toteutetaan tarvittavien tietojen luku kunnan rekisteriin.  Projektipäällikön tehtävänä on laajan kehityshankkeen aktiivinen läpivienti yhteistyössä hankkeen ohjausryhmän kanssa. Projektipäällikkö koordinoi hankkeessa olevien kuntien asiantuntijoiden yhteiskehittämistä. Projektipäällikkö koordinoi myös ohjelmistotoimittajien kehitystyötä ja valvoo toteutusta ja lopputuloksen laatua. Tehtäviin kuuluu myös tarvittava yhteydenpito ympäristöministeriön RYHTI- ja RAVA2- hankkeisiin. Projektipäällikkö osallistuu hankkeen ohjausryhmän ja hankkeen sisäisten projektiryhmien työskentelyyn. Lisäksi tehtävä sisältää tavanomaisia projektinhallintatehtäviä, sisäistä viestintää ja VM:lle tehtävän raportoinnin koordinointia. Työaika arvioltaan 75-90 työpäivää sovitun aikataulun mukaisesti välillä 3.1.2022-31.10.2023.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"PL 58200 00099 HELSINGIN KAUPUNKI FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62211, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \" VM-DIGIKEHITYSHANKKEEN PROJEKTIPÄÄLLIKKÖ \", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Tarjouspyyntö koskee projektipäällikön tehtävää Helsingin kaupungin johtamassa, valtionvarainministeriön rahoittamassa hankkeessa \\\"Kunnan rakennusvalvonnan sähköisen lupaprosessin edelleen kehittäminen ja prosessien automatisointi\\\". Hankkeessa on mukana 26 kuntaa.  Hankkeen päähakijana ja hallinnoijana toimii Helsingin kaupungin kaupunkiympäristön toimiala. Hankkeeseen kuuluvat Helsingin kaupungin lisäksi seuraavat kunnat ja kaupungit: Espoo, Hämeenlinna, Joensuu, Jyväskylä, Kuopio, Lahti, Mikkeli, Oulu, Pori, Salo, Seinäjoki, Tampere, Turku, Vantaa, Hyvinkää, Järvenpää, Lohja, Kirkkonummi, Sipoo, Tuusula, Ylöjärvi, Äänekoski, Iisalmi, Asikkala ja Sysmä. Kuntaliitto tukee hankeen toteutumista. Hankkeen toteuttamisaika on 9/2021-10/2023.   Tarjousten vertailuperuste on kokonaistaloudellinen edullisuus, joka muodostuu kokonaisuudessaan laadullisista kriteereistä (100 %), eli ns. käänteinen kilpailutus. Hankinnan kokonaishinta on 70 000 euroa (alv 0 %).  Hankinnan kohteena oleva asiantuntijapalvelu jakaantuu seuraaviin tehtäviin: - Kehityshankkeen läpivienti hankkeen budjetin ja aikataulun mukaisesti yhteistyössä ohjausryhmän kanssa. Hankkeen projektisuunnitelman ja toteutusten jatkuva tarkentaminen ja osallistuminen hankkeen hankintojen määrittelyyn. - Yhteiskehittäminen hankkeessa mukana olevien kuntien kanssa sekä hankkeessa toimivien ohjelmistotoimittajien kehitystyön koordinointi ja laadunvalvonta. Yhteistyö muiden sidosryhmien, kuten valtion organisaatioiden, kanssa.  - Hankkeen sisäinen viestintä ja tarvittaessa osallistuminen ulkoiseen viestintään.  - Hankkeen dokumentointi sekä VM:lle tehtävän raportoinnin koordinointi.  Tarjoajien tasapuolisen ja syrjimättömän kohtelun turvaamiseksi sekä kilpailun vääristymisen estämiseksi sama yritys tai siihen liittyvä yritys ei voi toimia sekä ”Kunnan rakennusvalvonnan sähköisen lupaprosessin edelleen kehittäminen ja prosessien automatisointi” -hankkeessa projektipäällikön tehtävässä että hankkeen ohjelmistotoimittajana, koska projektipäällikön tehtävään kuuluu hankintojen määrittelytyötä ja ohjelmistotoimittajien työn laadunvalvontaa.   Hankintayksiköllä voi olla velvollisuus sulkea tästä kilpailutuksesta tarjoaja tai tarjoajaan liittyvä yritys, joka on mukana ”Kunnan rakennusvalvonnan sähköisen lupaprosessin edelleen kehittäminen ja prosessien automatisointi” -hankkeessa ohjelmistotoimittajan roolissa.  \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": null, \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0201256-6\", \"tendersOrRequestsToParticipateDueDateTime\": \"2021-12-28T12:00:00Z\"}',60,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
