INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (856,'2021-088251','HILMA','RFP','OPEN','Evijärven ateriakuljetukset','Hankinnan tavoitteena on hankkia ostopalveluna ateriakuljetukset ajalle 1.3.2022 – 28.2.2023 sekä kaksi erillistä optiokautta 1.3.2022 – 29.2.2024 ja 1.3.2024 – 28.2.2025. Hankinnan kohteena ovat kuntayhtymän keittiöiltä toimitettavat ateriakuljetukset Evijärvellä. Ruuat kuljetetaan toimittajan kalustolla kuuma- ja kylmäkuljetuksina, mikä edellyttää kuljettajalta tarkkaa aikataulussa pysymistä. Lähettävä keittiö pakkaa ruuat kuljetuslaatikoihin. Kotiin kuljetettavat ateriat ovat annospakattuja lämpölaatikoita. Samalla kuljetetaan jakelukeittiöihin elintarvikkeita. Ruoanviennin yhteydessä palautetaan edellisenä päivänä viedyt kuljetusastiat takaisin lähettävään keskuskeittiöön. Evijärvellä ateria- ja elintarvikekuljetuksia on kuutena päivänä viikossa.','Kuntayhtymä Kaksineuvoinen','ANY',5,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088251','[\"60000000\", \"60000000\", \"60000000\", \"60000000\"]','[\"ateriakuljetukset\", \"hankinnan\", \"ovat\", \"evijärvellä\", \"ruuat\", \"kuljetetaan\", \"päivänä\", \"kuntayhtymä\", \"kaksineuvoinen\", \"evijärven\", \"tavoitteena\", \"hankkia\", \"ostopalveluna\", \"ajalle\", \"kaksi\", \"erillistä\", \"optiokautta\", \"kohteena\", \"kuntayhtymän\", \"keittiöiltä\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088251\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88251\", \"type\": 9902, \"cpvCodes\": \"60000000 Kuljetuspalvelut (jätteen kuljetusta lukuun ottamatta) 60000000 Kuljetuspalvelut (jätteen kuljetusta lukuun ottamatta) 60000000 Kuljetuspalvelut (jätteen kuljetusta lukuun ottamatta) 60000000 Kuljetuspalvelut (jätteen kuljetusta lukuun ottamatta)\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI194  FI194  FI194  FI194\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-14T07:21:34.448Z\", \"noticeNumber\": \"2021-088251\", \"projectTitle\": \"Evijärven ateriakuljetukset\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-14T07:21:34.436Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2021-12-31T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Kuntayhtymä Kaksineuvoinen\", \"objectDescriptions\": \"Reitti 1. Kotipalvelun ateriat Kotipalvelun ateriakuljetukset maanantaista lauantaihin. Kuljetettavat ateriat noudetaan Evijärven terveysaseman keittiöltä (Antinniemi 8) klo 10:30 mennessä.  Reitillä on keskimäärin 25 ateriaa/pv ja reitti on noin 90 km. Määrät ja reitti vaihtelee päivittäin.  Kotipalvelun ateriat on toimitettava asiakkaille viimeistään kahden tunnin kuluessa. Paluukyydillä toimitetaan edellisen päivän tyhjät astiat/kuljetuslaatikot takaisin keittiöille.   Palveluun kuuluu aterioiden vienti asiakkaan kotiin, ruokaa ei saa jättää huoneiston ulkopuolelle ilman, että asiasta on sovittu asiakkaan kanssa. Tarvittaessa ateriapakkaus avataan valmiiksi asiakkaalle.  Kotipalvelureitin kuljettajan tulee tarkastaa asiakkaan kunto ja tarvittaessa ilmoittaa kotihoitoon ja keittiölle muuttuneesta tilanteesta. Jokaisesta asiakkaasta, jota ei tavoiteta, on kuljettajalla ilmoitusvelvollisuus kotihoidon toimistolle.   Vaitiolo- ja salassapitovelvollisuuden varmistamiseksi kuljettajalta vaaditaan allekirjoitettu vaitiolosopimus. Reitti 2. Päiväkoti Tuulentupa Päiväkoti Tuulentupa (Voltintie 8) aamupala maanantaista perjantaihin klo 7:30. Kuljetettavat ateriat noudetaan Evijärven terveysaseman keittiöltä (Antinniemi 8) Paluukyydillä toimitetaan edellisen päivän tyhjät astiat/kuljetuslaatikot takaisin keittiöille.  Reitti 3. Päiväkotiryhmä Sateenkaaret Päiväkotiryhmä Sateenkaaret (Lehmätie 5 C 3) lounas manantaista perjantaihin klo 10:30. Kuljetettavat ateriat noudetaan Evijärven terveysaseman keittiöltä (Antinniemi 8) Paluukyydillä toimitetaan edellisen päivän tyhjät astiat/kuljetuslaatikot takaisin keittiöille. \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Kauppatie 127 a 62200 Kauhava FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62340, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": \"\", \"projectTitleNormalized\": \"EVIJÄRVEN ATERIAKULJETUKSET\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Hankinnan tavoitteena on hankkia ostopalveluna ateriakuljetukset ajalle 1.3.2022 – 28.2.2023 sekä kaksi erillistä optiokautta 1.3.2022 – 29.2.2024 ja 1.3.2024 – 28.2.2025.  Hankinnan kohteena ovat kuntayhtymän keittiöiltä toimitettavat ateriakuljetukset Evijärvellä.  Ruuat kuljetetaan toimittajan kalustolla kuuma- ja kylmäkuljetuksina, mikä edellyttää kuljettajalta tarkkaa aikataulussa pysymistä. Lähettävä keittiö pakkaa ruuat kuljetuslaatikoihin. Kotiin kuljetettavat ateriat ovat annospakattuja lämpölaatikoita. Samalla kuljetetaan jakelukeittiöihin elintarvikkeita. Ruoanviennin yhteydessä palautetaan edellisenä päivänä viedyt kuljetusastiat takaisin lähettävään keskuskeittiöön.  Evijärvellä ateria- ja elintarvikekuljetuksia on kuutena päivänä viikossa. \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"2071277-7\", \"tendersOrRequestsToParticipateDueDateTime\": \"2021-12-31T12:00:00Z\"}',40,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (857,'2021-088346','HILMA','RFP','OPEN','Lintu- ja Tupenluoman säännöstelypadon rakennusurakka','Etelä-Pohjanmaan ELY-keskus (vesistöyksikkö) rakennuttaa uuden Lintu- ja Tupenluoman säännöstelypadon ja pyytää tarjousta kokonaishintaurakasta. Urakkakohde sijaitsee Etelä-Pohjanmaalla Kurikan kaupungissa Jurvassa.','Etelä-Pohjanmaan elinkeino-, liikenne- ja ympäristökeskus','ANY',2,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088346','[\"45247220\", \"44212382\", \"45247200\", \"45221110\", \"45221111\", \"45247210\"]','[\"etelä\", \"pohjanmaan\", \"lintu\", \"tupenluoman\", \"säännöstelypadon\", \"elinkeino\", \"liikenne\", \"ympäristökeskus\", \"rakennusurakka\", \"keskus\", \"vesistöyksikkö\", \"rakennuttaa\", \"uuden\", \"pyytää\", \"tarjousta\", \"kokonaishintaurakasta\", \"urakkakohde\", \"sijaitsee\", \"pohjanmaalla\", \"kurikan\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088346\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88346\", \"type\": 9902, \"cpvCodes\": \"45247220 Patorakennelmien rakennustyöt 44212382 Patoluukut 45247200 Patojen ja vastaavien kiinteiden rakennelmien rakennustyöt 45221110 Siltojen rakennustyöt 45221111 Maantiesiltojen rakennustyöt 45247210 Patojen rakennustyöt\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI194  FI194\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-14T06:24:03.488Z\", \"noticeNumber\": \"2021-088346\", \"projectTitle\": \"Lintu- ja Tupenluoman säännöstelypadon rakennusurakka \", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-14T06:24:03.487Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-02-07T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Etelä-Pohjanmaan elinkeino-, liikenne- ja ympäristökeskus\", \"objectDescriptions\": \" Lintu- ja Tupenluoman säännöstelypadon rakennusurakan tavoitteena on pienentää Kivi- ja Levalammen tekojärven tulovirtaamaa turvalliselle tasolle myös erittäin harvinaisten tulvien aikana. Tämä toteutetaan kääntämällä Lintuluoman ja Kaunisnevanojan vesiä Lintuluoman kanavasta Lintu- ja Tupenluoman yhdyskanavaan.  Urakassa rakennetaan uusi pato kahdella säännöstelyluukulla ja patoon liittyvällä teräsputkisillalla. Tarjousasiakirjoissa kuvataan uuden säännöstelypadon kokonaisurakka, joka koostuu pääosin:  - Vanhan padon ja tien alitusrummun purkamisesta - Urakassa tarvittavista materiaalihankinnoista  - Patoluukkujen ja nostokoneistojen valmistamisesta ja/tai hankinnoista - Uuden patorakenteen, luukkujen ja nostokoneistojen sekä patoon liittyvän teräsputkisillan rakentamisesta  - Tarvittavien työpatojen, ohijuoksutuksen ja rakennusaikaisen pumppauksen rakentamisesta ja purkamisesta uuden padon käyttöönoton jälkeen. Kokonaishintaurakkaan täytyy sisältyä mm. kaikki materiaalit, hankinnat, työt ja kuljetukset, jotka luonnostaan ovat välttämättömiä työn valmiiksi saattamiseksi. Urakan tarkempi määrittely on esitetty liitteenä olevissa tarjouspyyntöasiakirjoissa. Lisäksi tarjoajan on huomioitava urakkaan liittyvät viranomaisvaatimukset ja määräykset, kuten mm. viranomaisten julkaisemat viimeisimmät standardien painokset, asetukset, käsikirjat, ohjeet ja lupaehdot sekä työsuojeluviranomaisen julkaisemat määräykset ja säännöt. Hankintayksikkö varaa oikeuden neuvotella kaikista kaupallisista ja teknisistä edellytyksistä tarjouksessa, mikäli hankintayksikön olosuhteet, tarpeet tai suunnitteluperusteet muuttuvat hankintakilpailun aikana. Hankintayksikkö tiedottaa kaikkia tarjoajia kirjallisesti kyseisistä muutoksista hankinnassa. Hankintayksikkö pidättää itsellään oikeuden tarvittaessa kaikkien tarjousten hylkäämiseen.  \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Alvar Aallon katu 8 60101 Seinäjoki FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62392, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": \"Etelä-Pohjanmaan ELY-keskus\", \"projectTitleNormalized\": \"LINTU- JA TUPENLUOMAN SÄÄNNÖSTELYPADON RAKENNUSURAKKA \", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Etelä-Pohjanmaan ELY-keskus (vesistöyksikkö) rakennuttaa uuden Lintu- ja Tupenluoman säännöstelypadon ja pyytää tarjousta kokonaishintaurakasta. Urakkakohde sijaitsee Etelä-Pohjanmaalla Kurikan kaupungissa Jurvassa.   \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"N=6955816.392, E=243281.413 (ETRS-TM35FIN) Liittenä kartta ja linkki kohteeseen\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"2296962-1\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-02-07T12:00:00Z\"}',40,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (858,'2021-088314','HILMA','RFP','OPEN','Kivityöt 2022-2026','Järvenpään kaupunki pyytää tarjoustanne Järvenpään kaupungin alueella betoni- ja luonnonkivestä tehtävien reunakivien ja kiveysten materiaalihankinnoista ja asennustöistä. Hankinta on jaettu kuuteen (6) eri osa-alueeseen. - Luonnonkivityöt 1 - Luonnonkivityöt 2 - Betonikivityöt - Liukuvaletut reunakivet - Erikoistyöt - Tuntihinnat Osatarjoukset eivät ole sallittuja vaan tarjoukset tulee jättää kaikista osa-alueista. Tarjouspyyntö on jaettu luonnonkivien osalta kahteen eri osa-alueeseen, joissa toisessa on asetettu rajoituksia materiaalien rahdin kasvihuonepäästöjen osalta. Painotus on tilaajan arvio osa-alueiden käytettävien määrien suhteista. Osa-alueessa 1 yksikköhintojen luonnonkivimateriaalien rahtiin ei aseteta erityistä päästörajoitusta. Osa-alueen yksikköhintoja painotetaan 70%. Osa-alueessa 2 yksikköhintojen luonnonkivimateriaalien rahtiin on asetettu päästövaatimukset. Osa-alueen yksikköhintoja painotetaan 30%. Osa-alueessa 2 luonnonkivimateriaalin rahdin kasvihuonepäästöjen (CO2ekv tai CO2e ) enimmäismäärä saa olla enintään 50 kg/t. Päästöillä tarkoitetaan tässä liikennevälineiden käytönaikaisia päästömääriä kuljetettua massayksikköä kohden (kg CO2e/t). Rahdin koko matka kivien tuotantopisteestä asennuspaikalle tulee sisältyä asetettuun päästörajaan. Rahdin päästöjä määritettäessä tulee käyttää osakuormaa 70%:a täydestä kuormasta. Tämä tarkoittaa käytännössä noin 1 100 km kuljetusta euro VI moottorilla varustetulla puoliperävaunurekalla tai noin 2 000 km kuljetusta isolla konttirahtilaivalla (2000 TEU). Osa-alueessa 2 tarjoajan tulee esittää tarjoamansa luonnonkiven tuotantopaikka. Tarvittaessa tarjoajan tulee esittää selvitys luonnonkivien rahtitavasta ja tuotantoketjusta tuotantopisteestä asennuspaikalle sekä laskema näistä aiheutuvasta kasvihuonepäästöistä. Kriteerissä tarkastellaan puhtaasti rahdin aiheuttamia kasvihuonepäästöjä ja niitä ei voida kompensoida muulla toiminnalla. Kuljetusten keskimääräisiä kasvihuonepäästöjen laskentaan löytyy http://lipasto.vtt.fi/yksikkopaastot. Kilpailutuksen perusteella on tarkoitus solmia puitejärjestely, johon valitaan kolme (3) urakoitsijaa, jollei kelpoisuusehdot täyttäviä tarjoajia tai hyväksyttyjä tarjouksia ole vähemmän. Puitejärjestelyssä urakoitsijan valintaa ohjaa ensisijaisesti kilpailutuksen perusteella määräytyvä etusijajärjestys. Ellei urakoitsijalla ole mahdollisuutta tuottaa palvelua tilattuna ajankohtana, tilaus tehdään järjestyksessä seuraavalta. Työkohteet tarkentuvat työmaakokouksissa tilaajan määräämässä järjestyksessä ja aikataulussa. Urakkaan kuuluu kaikkien tehtävien kiveysten materiaalihankinnat, lukuun ottamatta työmaakokouksissa tai tilauksen yhteydessä erikseen mainitut kohteet, joihin tilaajalla on materiaali varastossa. Urakkaan voidaan lisätä kunnossapidollisia kivikorjaustöitä, joissa käytetään urakan yksikkö- ja tuntiveloitushintoja. Sopimuskausi on kaksi (2) vuotta. Sopimusta on mahdollista jatkaa kahdella (2) erikseen päätettävällä optiovuodella vuosi kerrallaan. Mahdollisten optiokausien hinnan muutokset lasketaan urakkasopimusluonnoksessa esitetyllä tavalla. Sopimus allekirjoitetaan hankintapäätöksen tultua lainvoimaiseksi. Hankinnan ratkaisuperusteena on kokonaisuuden halvin vertailuhinta. Vertailuhinta ei ole hankinnan arvo vaan yksittäiset hankinnat tehdään annetuilla yksikköhinnoilla. Urakka on yksikköhintaurakka. Urakkasumma ja laskutus muodostuu toteutuneiden määrien mukaisesti tilaajan valvojan hyväksymien mittauspöytäkirjojen mukaisesti. Mikäli tilaajan ennakoima arvo yksittäisen hankinnan kohteesta on yli 50 000,00 euroa (alv 0%) kohde minikilpailutetaan kokonaishintaiseksi puitesopimuksen sisällä. Tilaaja ei sitoudu tiettyyn hankintavolyymiin sopimuskauden aikana vaan hankinta tehdään tilaajan hankintatarpeen mukaisesti ja voimassa olevien määrärahojen puitteissa.','Järvenpään kaupunki','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088314','[\"45236000\"]','[\"tulee\", \"rahdin\", \"tilaajan\", \"alueessa\", \"järvenpään\", \"vaan\", \"kasvihuonepäästöjen\", \"tehdään\", \"hankinnan\", \"mukaisesti\", \"kaupunki\", \"tehtävien\", \"kiveysten\", \"hankinta\", \"jaettu\", \"alueeseen\", \"luonnonkivityöt\", \"luonnonkivien\", \"osalta\", \"joissa\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088314\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88314\", \"type\": 9902, \"cpvCodes\": \"45236000 Maan kiveys ja laatoitus\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": 86821, \"lowCarbon\": null, \"nutsCodes\": \" FI1B  FI1B1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-13T13:28:18.364Z\", \"noticeNumber\": \"2021-088314\", \"projectTitle\": \"Kivityöt 2022-2026\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-13T13:28:18.356Z\", \"isCorrigendum\": true, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-17T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Järvenpään kaupunki\", \"objectDescriptions\": \" Järvenpään kaupungin alueella betoni- ja luonnonkivestä tehtävien reunakivien ja kiveysten materiaalihankinnat ja asennustyöt.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Hallintokatu 2 04400 Järvenpää FI\", \"innovationConsidered\": false, \"procurementProjectId\": 61315, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organis