INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (861,'2021-088238','HILMA','RFP','OPEN','Anestesiaventilaattorit','Lapin sairaanhoitopiirin kuntayhtymä pyytää tarjousta kahdesta matalavirtausanestesiaan soveltuvasta anestesiaventilaattorista.','Lapin sairaanhoitopiirin kuntayhtymä','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088238','[\"33171000\"]','[\"lapin\", \"sairaanhoitopiirin\", \"kuntayhtymä\", \"anestesiaventilaattorit\", \"pyytää\", \"tarjousta\", \"kahdesta\", \"matalavirtausanestesiaan\", \"soveltuvasta\", \"anestesiaventilaattorista\", \"finland\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088238\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88238\", \"type\": 9902, \"cpvCodes\": \"33171000 Anestesia- ja elvytyslaitteet\", \"currency\": null, \"isLatest\": false, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1D7  FI1D7\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-30T08:26:19.754Z\", \"noticeNumber\": \"2021-088238\", \"projectTitle\": \"Anestesiaventilaattorit\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-13T07:17:17.792Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-03T08:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": null, \"organisationName\": \"Lapin sairaanhoitopiirin kuntayhtymä\", \"objectDescriptions\": \" Hankinnan kohteena on kaksi matalavirtausanestesiaan soveltuvaa anestesiaventilaattoria Lapin keskussairaalaan leikkaus- ja anestesiayksikköön. Hankintaan sisältyy myös ventilaattoreiden määräaikaishuoltopalvelu, joka takuuajan osalta sisältyy ventilaattorien hintaan ja takuuajan jälkeen hinnoitellaan erikseen.  Anestesiaventilaattorit tullaan hankkimaan alkuvuodesta 2022. Lisäksi hankintaan sisältyy optioina mahdollisuus kahden anestesiaventilaattorin hankintaan vuosina 2023-2024.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Ounasrinteentie 22 96400 Rovaniemi FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62331, \"isNationalProcurement\": true, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"ANESTESIAVENTILAATTORIT\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Lapin sairaanhoitopiirin kuntayhtymä pyytää tarjousta kahdesta matalavirtausanestesiaan soveltuvasta anestesiaventilaattorista.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"Rovaniemi\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0819616-7\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-03T08:00:00Z\"}',50,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (862,'2021-088190','HILMA','RFP','OPEN','4 pieces of 63 MVAr shunt reactors','Four (4) pieces of 20 kV 63 MVA shunt reactors. As an option five (5) pieces of 20 kV 63 MVA shunt reactors.','Fingrid Oyj','ANY',5,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088190','[\"31000000\"]','[\"pieces\", \"shunt\", \"reactors\", \"fingrid\", \"mvar\", \"four\", \"option\", \"five\", \"finland\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088190\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88190\", \"type\": 500, \"cpvCodes\": \"31000000 Electrical machinery, apparatus, equipment and consumables; lighting\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI  FI\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-15T08:00:12.222Z\", \"noticeNumber\": \"2021-088190\", \"projectTitle\": \"4 pieces of 63 MVAr shunt reactors\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-12T13:10:13.188Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-21T13:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 243-642018\", \"organisationName\": \"Fingrid Oyj\", \"objectDescriptions\": \" Fingrid Oyj, the Finnish national transmission system operator, is initiating a procurement process for 20 kV 63 MVAr dry-type shunt reactors with the intended deliveries during 2023...2025 for existing substations in various locations in Finland.  With this invitation to participate Fingrid is looking for capable and interested suppliers of shunt reactors. In our operating model, the network of service and goods suppliers and good co-operation with suppliers are especially important. We require all our contractual partners who supply us with services or goods to be aware of Fingrid’s significant social duty and to commit to responsibility for the economic, social and environmental effects of their operations.  Delivery consists of four (4) pieces 20 kV 63 MVA shunt reactors and as an option five (5) pieces of 20 kV 63 MVA shunt reactors. Unloading of all reactor sets is included in the scope of delivery. Preliminary dry-type shunt reactor specification is attached to this prequalification (see attachment PRELIMINARY S22343E1 Dry-type shunt reactor).  Preliminary delivery schedule for deliveries: 3 x 63 MVAr, DDP Simojoki (Q4/2023) 1 x 63 MVAr, DDP Tuovila (Q1/2023)  Preliminary delivery schedule for deliveries (options): 2 x 63 MVAr, DDP Espoo (2024) 3 x 63 MVAr, DDP Hämeenlinna (2025)   See attachment \\\"REA07 Delivery locations\\\".  Delivery locations are preliminary and may be altered during procurement process. Detailed schedules shall be given in the tender inquiry documents.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Läkkisepäntie 21 00620 Helsinki FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62308, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"4 PIECES OF 63 MVAR SHUNT REACTORS\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Four (4) pieces of 20 kV 63 MVA shunt reactors. As an option five (5) pieces of 20 kV 63 MVA shunt reactors. \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"Delivery substations are Simojoki and Tuovila\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"1072894-3\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-21T13:00:00Z\"}',40,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (863,'2021-088184','HILMA','OTHER','OPEN','Helen Oy:n hukkalämmön talteenottolaitoksen hankinta','Hankinnan kohteena on hukkalämmön talteenottolaitos. Laitoksen ensisijainen käyttötarkoitus on konesalin jäähdyttäminen. Laitoksen toissijainen käyttötarkoitus on jäähdytyksestä talteenotetun lämmön jalostaminen kaukolämpöverkkoon sopivaksi lämmöksi. Hankinta on kokonaistoimitus, johon sisältyy kaikki tarvittava suunnittelu, laitteet, asennukset, koestukset ja käyttöönotto sekä laitoksen koekäyttö. Myös toimituksen dokumentointi sekä käyttö- ja kunnossapitohenkilöstön koulutus sisältyvät hankintaan. Toimitussisältö, laitoksen ja laitosyksiköiden toiminta sekä tekniset arvot tarkentuvat myöhemmässä kilpailutuksen vaiheessa.','Helen Oy','ANY',6,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-088184','[\"09324000\", \"42500000\"]','[\"laitoksen\", \"helen\", \"hukkalämmön\", \"hankinta\", \"käyttötarkoitus\", \"talteenottolaitoksen\", \"hankinnan\", \"kohteena\", \"talteenottolaitos\", \"ensisijainen\", \"konesalin\", \"jäähdyttäminen\", \"toissijainen\", \"jäähdytyksestä\", \"talteenotetun\", \"lämmön\", \"jalostaminen\", \"kaukolämpöverkkoon\", \"sopivaksi\", \"lämmöksi\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-088184\", \"name\": \"HILMA Notice\"}]','{\"id\": \"88184\", \"type\": 600, \"cpvCodes\": \"09324000 Kaukolämmitys 42500000 Jäähdytys- ja ilmanvaihtolaitteet\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractAwardNotices\", \"parentId\": 67884, \"lowCarbon\": null, \"nutsCodes\": \" FI1B1  FI1B1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-15T08:00:10.992Z\", \"noticeNumber\": \"2021-088184\", \"projectTitle\": \"Helen Oy:n hukkalämmön talteenottolaitoksen hankinta\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-12T12:50:11.906Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-06-12T12:50:11.906Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 243-642046\", \"organisationName\": \"Helen Oy\", \"objectDescriptions\": \" Hankinnan kohteena on hukkalämmön talteenottolaitos. Hankintaan kuuluu jäähdytysteholtaan yhteensä noin 20 MW modulaarisen laitoskokonaisuuden toteutussuunnittelu. Laitoskokonaisuus koostuu jäähdytysteholtaan noin 5 MW tehoisista laitosyksiköistä, joten laitoksen jäähdytystehoa tulee voida kasvattaa 5 MW:n portain aina 20 MW:iin saakka. Lisäksi hankintaan kuuluu laitoksen ensimmäisen jäähdytysteholtaan noin 5 MW kokoisen laitosyksikön toimituskokonaisuus ja toisen vastaavan kokoisen laitosyksikön toimitus optiona (Optio 4) siten, että laitosyksiköt muodostavat jäähdytysteholtaan yhteensä 10 MW laitoskokonaisuuden.  Laitoksen ensisijainen käyttötarkoitus on konesalin jäähdyttäminen. Kunkin laitosyksikön jäähdytystehon toiminta-alueen tulee olla noin 1 MW - 5 MW.  Laitoksen toissijainen käyttötarkoitus on jäähdytyksestä talteenotetun lämmön jalostaminen kaukolämpöverkkoon sopivaksi lämmöksi. Kunkin laitosyksikön kaukolämpötehon toiminta-alue tulee olla noin 1,3 MW - 6,1 MW.  Hankintaan sisältyy ensimmäisen jäähdytysteholtaan 5 MW:n laitoskokonaisuus seuraavasti: Jäähdytysteholtaan yhteensä 20 MW:n modulaarisen laitoskokonaisuuden toteutussuunnittelu (kone- ja prosessi, sähköistys ja automaatio), ensimmäisen laitosyksikön detaljisuunnittelu ja sen rakenteet, putkistot, laitteistot, laitteet ja komponentit, näiden asennustyöt, koestukset ja käyttöönotot sekä laitoksen koekäyttö.  Kukin laitosyksikkö tulee suunnitella ja toimittaa EN-standardien ja Painelaitedirektiivin vaatimusten mukaisesti.  Lisäksi hankintaan kuuluu tarjouspyynnössä ja sen liitteissä määritelty dokumentointi sekä käyttö- ja kunnossapitohenkilöstön koulutus. Lisäksi hankintaan kuuluu takuuajan aikainen ylläpito- ja huoltopalvelu.  \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \" 00090 HELEN FI\", \"innovationConsidered\": false, \"procurementProjectId\": 49825, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"HELEN OY:N HUKKALÄMMÖN TALTEENOTTOLAITOKSEN HANKINTA\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Hankinnan kohteena on hukkalämmön talteenottolaitos.  Laitoksen ensisijainen käyttötarkoitus on konesalin jäähdyttäminen.  Laitoksen toissijainen käyttötarkoitus on jäähdytyksestä talteenotetun lämmön jalostaminen kaukolämpöverkkoon sopivaksi lämmöksi.  Hankinta on kokonaistoimitus, johon sisältyy kaikki tarvittava suunnittelu, laitteet, asennukset, koestukset ja käyttöönotto sekä laitoksen koekäyttö. Myös toimituksen dokumentointi sekä käyttö- ja kunnossapitohenkilöstön koulutus sisältyvät hankintaan.  Toimitussisältö, laitoksen ja laitosyksiköiden toiminta sekä tekniset arvot tarkentuvat myöhemmässä kilpailutuksen vaiheessa. \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"Hukkalämmön talteenottolaitos sijoitetaan kolmannen osapuolen konesalirakennukseen.\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"2630573-4\", \"tendersOrRequestsToParticipateDueDateTime\": null}',45,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (864,'2021-087787','HILMA','RFI','OPEN','Helsinki-Vantaan lentoaseman maaliikenteen valvontajärjestelmän päivitys','Hankinta sisältää Helsinki-Vantaan lentoaseman maaliikenteen valvontajärjestelmän (Multilateration Surveillance (MLAT)) ohjelmiston päivityksen ja laitteiston laajennuksen sekä tiettyjen olemassa olevien laitteiden siirron, konfiguroinnin ja testauksen, jotta lentoaseman laajennuksen aiheuttamat katvealueet saadaan poistettua, ja että voidaan varautua tulevaan kiitotiekunnostukseen.','Fintraffic Lennonvarmistus Oy','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-087787','[\"51900000\"]','[\"lentoaseman\", \"helsinki\", \"vantaan\", \"maaliikenteen\", \"valvontajärjestelmän\", \"laajennuksen\", \"päivitys\", \"hankinta\", \"sisältää\", \"multilateration\", \"surveillance\", \"mlat\", \"ohjelmiston\", \"päivityksen\", \"laitteiston\", \"tiettyjen\", \"olemassa\", \"olevien\", \"laitteiden\", \"siirron\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-087787\", \"name\": \"HILMA Notice\"}]','{\"id\": \"87787\", \"type\": 1500, \"cpvCodes\": \"51900000 Ohjaus- ja valvontajärjestelmien asennuspalvelut\", \"currency\": null, \"isLatest\": true, \"mainType\": \"PriorInformationNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1B1  FI1B\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-08T08:00:17.34Z\", \"noticeNumber\": \"2021-087787\", \"projectTitle\": \"Helsinki-Vantaan lentoaseman maaliikenteen valvontajärjestelmän päivitys\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-05T12:50:14.502Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-06-05T12:50:14.502Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 238-628657\", \"organisationName\": \"Fintraffic Lennonvarmistus Oy\", \"objectDescriptions\": \" Hankinta sisältää Helsinki-Vantaan lentoaseman maaliikenteen valvontajärjestelmän (Multilateration Surveillance (MLAT)) ohjelmiston päivityksen ja laitteiston laajennuksen sekä tiettyjen olemassa olevien laitteiden siirron, konfiguroinnin ja testauksen, jotta lentoaseman laajennuksen aiheuttamat katvealueet saadaan poistettua, ja että voidaan varautua tulevaan kiitotiekunnostukseen.  MLAT-järjestelmän päivityksellä vastataan ensisijaisesti Helsinki-Vantaan lentoaseman laajennushankkeesta aiheutuneisiin lähilennonjohdon tarpeisiin ilma-aluksien ja ajoneuvojen paikka- ja tunnistetietojen saatavuuteen ja näiden perusteella muodostettavaan maaliikenteen tilannekuvaan, jota hyödynnetään maaliikenteen johtamisessa. Lisäksi hankinnalla varaudutaan Helsinki-Vantaan lentoasemalla suoritettavaan kiitotiekunnostukseen ja ILS-uusintaan, jolla on vaikutuksia MLAT-järjestelmän käytettävyyteen. Varautumisella pyritään minimoimaan vaikutukset lentoaseman liikennekapasiteettiin ja lennonjohdon työkuormaan kiitotiekunnostuksen aikana.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"PL 157 01531 Vantaa FI\", \"innovationConsidered\": false, \"procurementProjectId\": 62021, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"HELSINKI-VANTAAN LENTOASEMAN MAALIIKENTEEN VALVONTAJÄRJESTELMÄN PÄIVITYS\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Hankinta sisältää Helsinki-Vantaan lentoaseman maaliikenteen valvontajärjestelmän (Multilateration Surveillance (MLAT)) ohjelmiston päivityksen ja laitteiston laajennuksen sekä tiettyjen olemassa olevien laitteiden siirron, konfiguroinnin ja testauksen, jotta lentoaseman laajennuksen aiheuttamat katvealueet saadaan poistettua, ja että voidaan varautua tulevaan kiitotiekunnostukseen.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"2767840-1\", \"tendersOrRequestsToParticipateDueDateTime\": null}',40,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (865,'2021-087340','HILMA','RFP','OPEN','Leväsen palvelutalo Kivelä, Kuopio, Sprinkleriurakka','Leväsen palvelutalo Kivelän sprinkleriurakka alistettuna sivu-urakkana tarjouspyyntöasiakirjojen mukaisesti.','Niiralan Kulma Oy','ANY',10,7,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-087340','[\"45343230\"]','[\"leväsen\", \"palvelutalo\", \"sprinkleriurakka\", \"kivelä\", \"kuopio\", \"kivelän\", \"alistettuna\", \"sivu\", \"urakkana\", \"tarjouspyyntöasiakirjojen\", \"mukaisesti\", \"niiralan\", \"kulma\", \"lahti\", \"finland\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-087340\", \"name\": \"HILMA Notice\"}]','{\"id\": \"87340\", \"type\": 200, \"cpvCodes\": \"45343230 Sprinklerilaitteiston asennustyöt\", \"currency\": \"EUR\", \"isLatest\": false, \"mainType\": \"ContractNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1D2  FI1D2\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-22T10:30:08.608Z\", \"noticeNumber\": \"2021-087340\", \"projectTitle\": \"Leväsen palvelutalo Kivelä, Kuopio, Sprinkleriurakka \", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-05T11:45:04.879Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-01-18T12:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 238-625996\", \"organisationName\": \"Niiralan Kulma Oy\", \"objectDescriptions\": \" Rakennuskohde käsittää yhden kaksikerroksisen uudisrakennuksen, johon n sijoittuu 56 tehostetun palveluasumisen asuntoa. Rakennuksen kellarikerrokseen sijoittuu teknisiä-, yhteis- ja aputiloja ja 1. & 2. kerrokseen tehostetun palveluasumisen tiloja. Rakennukseen tulee sprinkleri- ja paloilmoitinjärjestelmä. Tontille rakennetaan urakassa myös jätekylmiö ja jätekatos. Koko kiinteistö on varustettu jäähdytyksellä ja kohteeseen tulee maalämpö/maakylmäjärjestelmä ja aurinkosähköjärjestelmä. \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Hatsalankatu 37 70110 Kuopio FI\", \"innovationConsidered\": false, \"procurementProjectId\": 61691, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": \"\", \"projectTitleNormalized\": \"LEVÄSEN PALVELUTALO KIVELÄ, KUOPIO, SPRINKLERIURAKKA \", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Leväsen palvelutalo Kivelän sprinkleriurakka alistettuna sivu-urakkana tarjouspyyntöasiakirjojen mukaisesti. \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": true, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"mainsiteplaceWorksDeliveries\": \"Kuopio \", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0171260-8\", \"tendersOrRequestsToParticipateDueDateTime\": \"2022-01-18T12:00:00Z\"}',40,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (866,'2021-087753','HILMA','RFI','OPEN','Request for Information: Media Marketing & Communications Solution','Please see the detailed description of the procurement.','Yleisradio Oy','ANY',10,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-087753','[\"72000000\"]','[\"yleisradio\", \"request\", \"information\", \"media\", \"marketing\", \"communications\", \"solution\", \"please\", \"detailed\", \"description\", \"procurement\", \"finland\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-087753\", \"name\": \"HILMA Notice\"}]','{\"id\": \"87753\", \"type\": 100, \"cpvCodes\": \"72000000 IT services: consulting, software development, Internet and support\", \"currency\": null, \"isLatest\": true, \"mainType\": \"PriorInformationNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI  FI\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-08T08:00:13.641Z\", \"noticeNumber\": \"2021-087753\", \"projectTitle\": \"Request for Information: Media Marketing & Communications Solution\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-05T10:20:12.221Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-06-05T10:20:12.221Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 238-627286\", \"organisationName\": \"Yleisradio Oy\", \"objectDescriptions\": \" OBJECT OF RFI  Yle is looking for a solution to replace current systems used in media communication and marketing.  Please note that considering the rapid evolution of the media industry, Yle needs great flexibility in terms of process modifiability and continuous development. It is foreseeable that the business, environments and customer needs evolve. The preliminary requirements for the Solution are:  1) The Solution is provided as a ready-made SaaS (Software as a Service) that is ready to be implemented in the Yle environment with little customization. The Solution shall be pre-existing and in operational use.  2) The user interface should be modern, fast and intuitive. UI should be based on widely known, open source web technologies and support all of the major desktop and mobile browsers.  3) All of the functionality and data stored by the Solution should be available through open API’s that supports modifying, uploading and downloading new and existing data, by using HTTP protocol and generally used data exchange formats like JSON. Yle and third parties need to be able to build their own custom integrations and workflows and use and enrich the data as needed.  4) Yle expects the future Solution to have versatile search options that contain search API.   INTERESTED?  Yle has described the targeted solution in detail. In case you are interested in taking part of the RFI, you can ask for more information from tarjoukset.yle@yle.fi by 20th of December 2021. We\'ll send you more detailed description of the procurement and a short questionnaire concerning your solution. Please use the reference \\\"YLE20210071 Media Marketing & Communications Solution\\\" as a headline of your e-mail.  Yle will review the responses to the RFI and if necessary, will have a second round of discussions with participants most suitable to the need. In case Yle finds it helpful, Yle may also ask for you to arrange a demo session of your solution as well.   REQUEST FOR INFORMATION (RFI)  The purpose of this RFI is to collect information from the market and inform companies of the upcoming procurement. With this RFI you are invited to take part in the market dialogue.  With this RFI Yle is not asking for tenders. In addition, it is not necessary to reply to this RFI in order to later participate in the upcoming procurement procedure and invitation to tender.  The description and object of the RFI is preliminary and Yle will specify the needs and objectives of the procurement in the final invitation to tender.  All material provided for the RFI will be kept confidential and only for Yle\'s internal use.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Uutiskatu 5 00240 Helsinki FI\", \"innovationConsidered\": false, \"procurementProjectId\": 61996, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"REQUEST FOR INFORMATION: MEDIA MARKETING & COMMUNICATIONS SOLUTION\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Please see the detailed description of the procurement.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"0215438-8\", \"tendersOrRequestsToParticipateDueDateTime\": null}',55,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (867,'2021-087748','HILMA','RFI','OPEN','Taloussuunnittelujärjestelmän hankinta','Sarastia Oy hankkii taloussuunnittelujärjestelmän omaan, tytär- ja osakkuusyhtiöiden ja asiakkaiden (mm. kuntien, kuntayhtymien, hyvinvointialueiden ja kuntien osakeyhtiöiden) tarpeisiin. Hankittava ratkaisu on tarkoitettu Sarastian omistaja-asiakkaiden käyttöön välillisesti siten, että kokonaisratkaisun myy Sarastia Oy. Näin ollen järjestelmää hyödynnetään osana Sarastian asiakkailleen tuottamaa taloussuunnittelun kokonaispalvelua, jolloin valittava palveluntuottaja järjestelmäratkaisuineen myy palvelua Sarastialle. Hankittavan järjestelmäratkaisun tulee soveltua kuntaorganisaatioiden talouden suunnitteluun sisältäen ennustamisen ja budjetoinnin. Järjestelmän tulee mahdollistaa keskitetyt pääkäyttäjätoiminnot, tietokantarakenteen tulee tukea moniyritysympäristöä ja järjestelmän tulee olla helposti laajennettavissa uusille asiakkaille. Järjestelmästä tulee olla mahdollisuus reaaliaikaiseen tiedonsiirtoon muiden järjestelmien ja taloussuunnittelujärjestelmän välillä automaattisen rajapinnan kautta. Järjestelmän tulee tukea Azure AD-tunnistautumista.','Sarastia Oy','ANY',3,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-087748','[\"72000000\"]','[\"tulee\", \"sarastia\", \"taloussuunnittelujärjestelmän\", \"järjestelmän\", \"asiakkaiden\", \"kuntien\", \"sarastian\", \"tukea\", \"hankinta\", \"hankkii\", \"omaan\", \"tytär\", \"osakkuusyhtiöiden\", \"kuntayhtymien\", \"hyvinvointialueiden\", \"osakeyhtiöiden\", \"tarpeisiin\", \"hankittava\", \"ratkaisu\", \"tarkoitettu\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-087748\", \"name\": \"HILMA Notice\"}]','{\"id\": \"87748\", \"type\": 100, \"cpvCodes\": \"72000000 Tietotekniset palvelut: neuvonta, ohjelmistojen kehittäminen, Internet ja tuki\", \"currency\": null, \"isLatest\": true, \"mainType\": \"PriorInformationNotices\", \"parentId\": null, \"lowCarbon\": null, \"nutsCodes\": \" FI1  FI1\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-08T08:00:13.023Z\", \"noticeNumber\": \"2021-087748\", \"projectTitle\": \"Taloussuunnittelujärjestelmän hankinta\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-05T09:50:14.686Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-06-05T09:50:14.686Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 238-627283\", \"organisationName\": \"Sarastia Oy\", \"objectDescriptions\": \" Sarastia Oy hankkii taloussuunnittelujärjestelmän omaan, tytär- ja osakkuusyhtiöiden ja asiakkaiden (mm. kuntien, kuntayhtymien, hyvinvointialueiden ja kuntien osakeyhtiöiden) tarpeisiin. Hankittava ratkaisu on tarkoitettu Sarastian omistaja-asiakkaiden käyttöön välillisesti siten, että kokonaisratkaisun myy Sarastia Oy. Näin ollen järjestelmää hyödynnetään osana Sarastian asiakkailleen tuottamaa taloussuunnittelun kokonaispalvelua, jolloin valittava palveluntuottaja järjestelmäratkaisuineen myy palvelua Sarastialle.  Hankittavan järjestelmäratkaisun tulee soveltua kuntaorganisaatioiden talouden suunnitteluun sisältäen ennustamisen ja budjetoinnin. Järjestelmän tulee mahdollistaa keskitetyt pääkäyttäjätoiminnot, tietokantarakenteen tulee tukea moniyritysympäristöä ja järjestelmän tulee olla helposti laajennettavissa uusille asiakkaille. Järjestelmästä tulee olla mahdollisuus reaaliaikaiseen tiedonsiirtoon muiden järjestelmien ja taloussuunnittelujärjestelmän välillä automaattisen rajapinnan kautta. Järjestelmän tulee tukea Azure AD-tunnistautumista.\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Tornatorintie 3 48100 Kotka FI\", \"innovationConsidered\": false, \"procurementProjectId\": 61993, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"TALOUSSUUNNITTELUJÄRJESTELMÄN HANKINTA\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Sarastia Oy hankkii taloussuunnittelujärjestelmän omaan, tytär- ja osakkuusyhtiöiden ja asiakkaiden (mm. kuntien, kuntayhtymien, hyvinvointialueiden ja kuntien osakeyhtiöiden) tarpeisiin. Hankittava ratkaisu on tarkoitettu Sarastian omistaja-asiakkaiden käyttöön välillisesti siten, että kokonaisratkaisun myy Sarastia Oy. Näin ollen järjestelmää hyödynnetään osana Sarastian asiakkailleen tuottamaa taloussuunnittelun kokonaispalvelua, jolloin valittava palveluntuottaja järjestelmäratkaisuineen myy palvelua Sarastialle.  Hankittavan järjestelmäratkaisun tulee soveltua kuntaorganisaatioiden talouden suunnitteluun sisältäen ennustamisen ja budjetoinnin. Järjestelmän tulee mahdollistaa keskitetyt pääkäyttäjätoiminnot, tietokantarakenteen tulee tukea moniyritysympäristöä ja järjestelmän tulee olla helposti laajennettavissa uusille asiakkaille. Järjestelmästä tulee olla mahdollisuus reaaliaikaiseen tiedonsiirtoon muiden järjestelmien ja taloussuunnittelujärjestelmän välillä automaattisen rajapinnan kautta. Järjestelmän tulee tukea Azure AD-tunnistautumista.\", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"2360731-5\", \"tendersOrRequestsToParticipateDueDateTime\": null}',60,NULL,'2026-09-08