INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (874,'2021-087863','HILMA','OTHER','OPEN','Hedelmät, vihannekset, sekä kypsät ja raa\'at perunat ja juurekset','Tuomi Logistiikka Oy kilpailutti hedelmien, vihannesten, sekä kypsien ja raakojen perunoiden ja juuresten yhteishankinnan. Tuomi Logistiikka Oy:n yhteishankintasopimusta olivat oikeutettuja käyttämään Pirkanmaan Voimia Oy, Tampereen kaupungin yksiköt, Tammenlehväkeskus Oy, Valkeakosken kaupunki, Akaan kaupunki ja Urjalan kunta. Hankinta on jaettu seuraaviin osa-alueisiin: Osa-alue 1 Kokonaiset ja leikatut hedelmät, vihannekset ja juurekset, sekä raa\'at ja kypsät perunat Osa-alue 2 Kypsät juurekset','Tuomi Logistiikka Oy','ANY',10,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2021-087863','[\"15300000\", \"15300000\", \"15331110\", \"03200000\"]','[\"tuomi\", \"logistiikka\", \"kypsät\", \"juurekset\", \"hedelmät\", \"vihannekset\", \"perunat\", \"kaupunki\", \"alue\", \"kilpailutti\", \"hedelmien\", \"vihannesten\", \"kypsien\", \"raakojen\", \"perunoiden\", \"juuresten\", \"yhteishankinnan\", \"yhteishankintasopimusta\", \"olivat\", \"oikeutettuja\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2021-087863\", \"name\": \"HILMA Notice\"}]','{\"id\": \"87863\", \"type\": 300, \"cpvCodes\": \"15300000 Hedelmät, vihannekset ja vastaavat tuotteet 15300000 Hedelmät, vihannekset ja vastaavat tuotteet 15331110 Juuresjalosteet 03200000 Viljat, perunat, kasvikset, hedelmät ja pähkinät\", \"currency\": null, \"isLatest\": true, \"mainType\": \"ContractAwardNotices\", \"parentId\": 65335, \"lowCarbon\": null, \"nutsCodes\": \" FI197  FI197  FI197\", \"isCancelled\": false, \"biodiversity\": null, \"dateModified\": \"2021-12-10T08:00:08.224Z\", \"noticeNumber\": \"2021-087863\", \"projectTitle\": \"Hedelmät, vihannekset, sekä kypsät ja raa\'at perunat ja juurekset\", \"@search.score\": 1.0, \"codeOfConduct\": null, \"datePublished\": \"2021-12-09T08:50:06.754Z\", \"isCorrigendum\": false, \"estimatedValue\": 0.0, \"expirationDate\": \"2022-06-09T08:50:06.754Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"noticeOjsNumber\": \"2021/S 240-630687\", \"organisationName\": \"Tuomi Logistiikka Oy\", \"objectDescriptions\": \"Kokonaiset ja leikatut hedelmät, vihannekset ja juurekset, sekä raa\'at ja kypsät perunat Osa-alueen 1. Kokonaiset ja leikatut hedelmät, vihannekset ja juurekset, sekä raa\'at ja kypsät perunat puitejärjestelyyn valitaan kaksi (2) toimittajaa.   Sopimuskauden aikana kullekin hintajaksolle (1.1.-30.6. ja 1.7. - 31.12) valitaan minikilpailutuksella kokonaistaloudellisesti edullisin toimittaja.  Tuomi Logistiikka Oy:n yhteishankintasopimusta ovat oikeutettuja käyttämään Pirkanmaan Voimia Oy, Tampereen kaupungin yksiköt, Tammenlehväkeskus Oy, Valkeakosken kaupunki, Akaan kaupunki ja Urjalan kunta.   Valkeakosken kaupungin raakojen perunoiden ostot eivät kuulu tähän sopimukseen. Kypsät juurekset Osa-alueeseen 2. kypsät juurekset valitaan yksi toimittaja.  Tuomi Logistiikka Oy:n yhteishankintasopimusta ovat oikeutettuja käyttämään Pirkanmaan Voimia Oy,  Tammenlehväkeskus Oy, Tampereen kaupungin yksiköt, Valkeakosken kaupunki, Akaan kaupunki ja Urjalan kunta.   Tarjouspyynnön julkaisuhetkellä kypsien juureksien tarve on vain Pirkanmaan Voimia Oy:llä ja Tammenlehväkeskus Oy:llä.  \", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"organisationAddress\": \"Särkijärvenkatu 1 33840 Tampere FI\", \"innovationConsidered\": false, \"procurementProjectId\": 48121, \"isNationalProcurement\": false, \"justWorkingConditions\": null, \"organisationDepartment\": null, \"projectTitleNormalized\": \"HEDELMÄT, VIHANNEKSET, SEKÄ KYPSÄT JA RAA\'AT PERUNAT JA JUUREKSET\", \"listedGreenCriteriaUsed\": null, \"projectShortDescription\": \"Tuomi Logistiikka Oy kilpailutti hedelmien, vihannesten, sekä kypsien ja raakojen perunoiden ja juuresten yhteishankinnan.  Tuomi Logistiikka Oy:n yhteishankintasopimusta olivat oikeutettuja käyttämään Pirkanmaan Voimia Oy, Tampereen kaupungin yksiköt, Tammenlehväkeskus Oy, Valkeakosken kaupunki, Akaan kaupunki ja Urjalan kunta.   Hankinta on jaettu seuraaviin osa-alueisiin:  Osa-alue 1 Kokonaiset ja leikatut hedelmät, vihannekset ja juurekset, sekä raa\'at ja kypsät perunat Osa-alue 2 Kypsät juurekset  \", \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": true, \"smeParticipationConsidered\": false, \"mainsiteplaceWorksDeliveries\": \"\", \"solutionNewToMarketOrIndustry\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"organisationNationalRegistrationNumber\": \"2722581-6\", \"tendersOrRequestsToParticipateDueDateTime\": null}',40,NULL,'2026-09-08 01:34:00','2026-09-08 01:34:00');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (880,'8a7b0d45323440abff5a','FinnishCities','RFP','OPEN','Hankinta-asiamiespalvelu','','City of Kouvola','ANY',10,14,NULL,NULL,NULL,'EUR','https://kinno.fi/yrityspalvelut/julkiset-hankinnat/hankinta-asiamiehen-tehtavat/',NULL,'[\"hankinta\", \"asiamiespalvelu\", \"city\", \"kouvola\", \"finland\"]',NULL,NULL,NULL,'{\"text\": \"Hankinta-asiamiespalvelu\"}',42,NULL,'2026-09-08 07:40:31','2026-09-08 15:13:54');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (999,'2026-056631','HILMA','RFI','OPEN','Kutsu markkinavuoropuheluun, Väyläviraston mediatiedotejakelu','Kutsu markkinavuoropuheluun, Väyläviraston mediatiedotejakelu MARKKINAVUOROPUHELU Markkinavuoropuhelun kohteena on valmistelussa oleva mediatiedotejakeluun soveltuvan verkkoselainpohjaisen järjestelmän hankinta Väyläviraston tarpeisiin. TAUSTAA JA TAVOITTEET Väylävirasto kilpailuttaa seuraavan palveluhankinnan: Väyläviraston mediatiedotejakelu on keskeinen osa viraston mediaviestintää. Tiedotejakelun avulla virasto lähettää tiedotteensa medialle ja sidosryhmille oman kohdennuksen mukaan. Kohteena voivat olla valtakunnan media, paikallismedia, verkkomedia, sekä radio ja tv -toimitukset. Sidosryhmistä kohteena voivat olla esimerkiksi päättäjät, ministeriöt, järjestöt tai oppilaitokset. Väylävirasto lähettää 250–350 tiedotetta vuodessa. Lähetty mediatiedote tuodaan samalla vayla.fi-sivustolle, josta ne löytyvät ajankohtaisosiosta artikkeleina. Käyttäjätunnuksia palveluun luodaan n. 50–70 kappaletta. Hankinnan kohde sisältää myös mediakontaktien ajantasaisen ylläpidon. Tiedotteiden avulla rakennamme ja ylläpidämme mielikuvaa verorahojen vaikuttavasta käytöstä, osaavasta väylänpitäjästä, luotettavasta yhteistyökumppanista ja kiinnostavasta työnantajasta. Tiedotteita lähettävät Väyläviraston viestintäyksikkö ja ulkopuoliset viestintäkonsultit (isoissa väylähankkeissa). ALUSTAVA AIKATAULU Tilaajan tavoiteaikataulu markkinavuoropuhelun ja hankinnan toteuttamiselle on: - Markkinavuoropuhelu 9/2026 - Tarjouspyynnön julkaisu 10/2026 - Laskenta-aika 10/2026 - Tarjousten vertailu ja hankintapäätös 10-11/2026 ILMOITUKSEN LISÄTIEDOT Tämä ilmoitus on ennakkoilmoitus. Tällä ilmoituksella ei pyydetä tarjouksia. Ennakkoilmoitukseen liittyy kutsu markkinavuoropuheluun, jolloin kaikilla hankinnasta kiinnostuneilla toimittajilla on mahdollisuus käydä hankintaa koskevaa teknistä vuoropuhelua Väyläviraston kanssa. Teknisen vuoropuhelun tarkoituksena on käydä yleisellä tasolla vuoropuhelua hankinnan kohteesta ja sen määrittämisestä. Tekninen vuoropuhelu ei sido Väylävirastoa toteuttamaan hankintaa. Tekninen vuoropuhelu ei myöskään sido toimittajaa mahdolliseen tarjouskilpailuun osallistumiseen, eikä markkinavuoropuheluun osallistumatta jättäminen estä myöhemmin järjestettävään tarjouskilpailuun osallistumista. Tekninen vuoropuhelu järjestetään tarjouspyyntöaineiston luonnosversioiden kommentointikierroksena. Vuoropuhelussa tilaaja lähettää materiaalin ja esittää kysymyksiä tähän vuoropuheluun ilmoittautuneille, joilla on mahdollisuus vastata kysymyksiin ja jättää kommentteja materiaalin pohjalta. Alustava ajankohta tarjouspyyntöaineiston luonnosversioiden ja kysymysten toimittamiselle on 17.9.2026. Tilaaja varaa toimittajille noin 1-2 viikon kommentointiajan. ILMOITTAUTUMISOHJE: Toimittajan tulee ilmoittaa kiinnostuksensa osallistua markkinavuoropuheluun 16.9.2026 klo 12.00 mennessä lähettämällä osoitteisiin juha.stjarnstedt@vayla.fi ja aino.mannikko@vayla.fi viesti otsikolla: \"Väyläviraston mediatiedotejakelu, markkinavuoropuhelu\". Toimittajaa pyydetään ilmoittamaan viestissä mihin sähköpostiosoitteisiin markkinavuoropuhelumateriaali toimitetaan. Toimittajaa pyydetään ilmoittamaan viestissä seuraavat tiedot: - toimittajan yhteyshenkilön sähköpostiosoite. Tilaaja varaa oikeuden kutsua toimittajia myös kahdenkeskisiin neuvotteluihin tai jatkaa teknistä vuoropuhelua muulla erikseen ilmoitettavalla tavalla, joista ilmoitetaan tarvittaessa myöhemmin. Tässä ennakkoilmoituksessa esitetyt kuvaukset ja hankintailmoituksen arvioitu julkaisupäivämäärä, kuten myös myöhemmin toimitettavat vuoropuhelun luonnosmateriaalit ovat alustavia ja suuntaa antavia hankinnan ennakkotietoja. Osallistuneille yrityksille ei makseta korvausta vastaamisesta tai osallistumisesta.,','Väylävirasto','SME',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056631','[\"72000000\", \"79340000\"]','[\"väyläviraston\", \"markkinavuoropuheluun\", \"mediatiedotejakelu\", \"väylävirasto\", \"hankinnan\", \"kutsu\", \"markkinavuoropuhelu\", \"kohteena\", \"lähettää\", \"vayla\", \"vuoropuhelua\", \"tekninen\", \"vuoropuhelu\", \"toimittajaa\", \"myöhemmin\", \"tilaaja\", \"markkinavuoropuhelun\", \"avulla\", \"voivat\", \"alustava\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/vayla?id=626638&tpk=637f54d6-b9e2-4cb6-9604-0305f32eb065\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056631\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56631\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Kutsu markkinavuoropuheluun, Väyläviraston mediatiedotejakelu\", \"titleSv\": \"\", \"cpvCodes\": \"72000000 79340000\", \"currency\": null, \"deadline\": \"2026-09-16T09:00:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"MARKKINAVUOROPUHELU\\n\\nMarkkinavuoropuhelun kohteena on valmistelussa oleva mediatiedotejakeluun soveltuvan verkkoselainpohjaisen järjestelmän hankinta Väyläviraston tarpeisiin. \\n\\nTAUSTAA JA TAVOITTEET\\n\\nVäylävirasto kilpailuttaa seuraavan palveluhankinnan:\\n\\nVäyläviraston mediatiedotejakelu on keskeinen osa viraston mediaviestintää. Tiedotejakelun avulla virasto lähettää tiedotteensa medialle ja sidosryhmille oman kohdennuksen mukaan. Kohteena voivat olla valtakunnan media, paikallismedia, verkkomedia, sekä radio ja tv -toimitukset. Sidosryhmistä kohteena voivat olla esimerkiksi päättäjät, ministeriöt, järjestöt tai oppilaitokset.\\n\\nVäylävirasto lähettää 250–350 tiedotetta vuodessa. Lähetty mediatiedote tuodaan samalla vayla.fi-sivustolle, josta ne löytyvät ajankohtaisosiosta artikkeleina. Käyttäjätunnuksia palveluun luodaan n. 50–70 kappaletta. Hankinnan kohde sisältää myös mediakontaktien ajantasaisen ylläpidon. \\n\\nTiedotteiden avulla rakennamme ja ylläpidämme mielikuvaa verorahojen vaikuttavasta käytöstä, osaavasta väylänpitäjästä, luotettavasta yhteistyökumppanista ja kiinnostavasta työnantajasta. Tiedotteita lähettävät Väyläviraston viestintäyksikkö ja ulkopuoliset viestintäkonsultit (isoissa väylähankkeissa).\\n\\n\\nALUSTAVA AIKATAULU\\n\\nTilaajan tavoiteaikataulu markkinavuoropuhelun ja hankinnan toteuttamiselle on:\\n- Markkinavuoropuhelu 9/2026\\n- Tarjouspyynnön julkaisu 10/2026\\n- Laskenta-aika 10/2026\\n- Tarjousten vertailu ja hankintapäätös 10-11/2026\\n\\nILMOITUKSEN LISÄTIEDOT\\n\\nTämä ilmoitus on ennakkoilmoitus. Tällä ilmoituksella ei pyydetä tarjouksia.\\nEnnakkoilmoitukseen liittyy kutsu markkinavuoropuheluun, jolloin kaikilla hankinnasta kiinnostuneilla toimittajilla on mahdollisuus käydä hankintaa koskevaa teknistä vuoropuhelua Väyläviraston kanssa. Teknisen vuoropuhelun tarkoituksena on\\nkäydä yleisellä tasolla vuoropuhelua hankinnan kohteesta ja sen määrittämisestä. Tekninen vuoropuhelu ei sido Väylävirastoa toteuttamaan hankintaa. Tekninen vuoropuhelu ei myöskään sido toimittajaa mahdolliseen tarjouskilpailuun osallistumiseen, eikä markkinavuoropuheluun osallistumatta jättäminen estä myöhemmin järjestettävään tarjouskilpailuun osallistumista.\\n\\nTekninen vuoropuhelu järjestetään tarjouspyyntöaineiston luonnosversioiden kommentointikierroksena. Vuoropuhelussa tilaaja lähettää materiaalin ja esittää kysymyksiä tähän vuoropuheluun ilmoittautuneille, joilla on mahdollisuus vastata kysymyksiin ja jättää kommentteja materiaalin pohjalta. \\n\\nAlustava ajankohta tarjouspyyntöaineiston luonnosversioiden ja kysymysten\\ntoimittamiselle on 17.9.2026. Tilaaja varaa toimittajille noin 1-2 viikon kommentointiajan.\\n\\nILMOITTAUTUMISOHJE:\\n\\nToimittajan tulee ilmoittaa kiinnostuksensa osallistua markkinavuoropuheluun 16.9.2026 klo 12.00 mennessä lähettämällä\\nosoitteisiin juha.stjarnstedt@vayla.fi ja aino.mannikko@vayla.fi viesti otsikolla: \\\"Väyläviraston mediatiedotejakelu, markkinavuoropuhelu\\\".\\nToimittajaa pyydetään ilmoittamaan viestissä mihin sähköpostiosoitteisiin markkinavuoropuhelumateriaali toimitetaan. \\nToimittajaa pyydetään ilmoittamaan viestissä seuraavat tiedot:\\n- toimittajan yhteyshenkilön sähköpostiosoite.\\n\\nTilaaja varaa oikeuden kutsua toimittajia myös kahdenkeskisiin neuvotteluihin tai jatkaa teknistä vuoropuhelua muulla erikseen ilmoitettavalla tavalla, joista ilmoitetaan tarvittaessa myöhemmin.\\n\\nTässä ennakkoilmoituksessa esitetyt kuvaukset ja hankintailmoituksen arvioitu julkaisupäivämäärä, kuten myös myöhemmin toimitettavat vuoropuhelun luonnosmateriaalit ovat alustavia ja suuntaa antavia hankinnan ennakkotietoja.\\n\\nOsallistuneille yrityksille ei makseta korvausta vastaamisesta tai osallistumisesta.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-09-16T09:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": null, \"lotResultTotalAmount\": null, \"justWorkingConditions\": null, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": null, \"includesFrameworkAgreement\": null, \"smeParticipationConsidered\": null, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": null, \"tendersFromMicroTenderersCount\"