INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1002,'2026-056626','HILMA','RFI','OPEN','Markkinakartoitus/tietopyyntö: silmälääkäripalvelujen hankinta','Markkinakartoitus ja tietopyyntö tulevasta hankinnasta Markkinakartoituksella ja tietopyynnöllä Kainuun hyvinvointialue selvittää mahdollisten palveluntuottajien näkemyksiä tulevaa silmälääkäripalvelujen hankinnan valmistelua varten. Markkinakartoituksen tarkoituksena on saada tietoa markkinoilla olevista mahdolliista palveluntuottajista ja heidän näkemyksiään tarjottavan palvelun sisällöstä ja vaatimuksista. Tämä tietopyyntö ei ole hankintailmoitus eikä tarjouspyyntö eikä siihen vastaaminen sido vastaajaa eikä hankintayksikköä. Tietopyynnön kysymykset ovat erillisessä liitteessä. Hankintayksikkö pyytää toimittajia täyttämään liitteenä oleva kysymyslomake ja lataamaan se tämän markkinakartoituksen yhteyteen. Voitte liittää asialle halutessanne myös omia liitteitänne. Silmätautien poliklinikan toiminnasta antaa tarv. lisätietoja apulaispalveluesihenkilö heli.kuukasjärvi@kainuu.fi Vastaukset pyydetään toimittamaan viimeistään 22.9.2026. Hankintayksikkö voi markkinakartoituksen perusteella pyytää lisätietoja toimittajilta., Silmätautien poliklinikkapalvelut Poliklinikkapalvelu sisältää ajanvarauspotilaita ja päivystyspotilaita, vastaamista talon sisäisiin konsultaatiopyyntöihin sekä hoitohenkilökunnan toteuttamien injektiohoitojen ja muiden vastaavien toimenpiteiden valvontaa., Silmätautien polikliiniset leikkaukset Polikliiniset leikkaukset ovat paikallispuudutuksessa tapahtuvia polikliinisia leikkauksia tai pientoimenpiteitä sekä potilaiden toimenpidearvioita., 