INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1003,'2026-056619','HILMA','RFI','OPEN','Tekninen vuoropuhelu / markkinavuoropuhelu: Rauman kaupungin koulukuljetusten operatiivinen järjestämis-, ajojärjestely- ja välityspalvelu sekä joustava kuljetuskapasiteetti','Tekninen vuoropuhelu / markkinavuoropuhelu: Rauman kaupungin koulukuljetusten operatiivinen järjestämis-, ajojärjestely- ja välityspalvelu sekä joustava kuljetuskapasiteetti Rauman kaupunki valmistelee koulukuljetusten hankintaa, jossa hankinnan kohteena olisi koulukuljetusten operatiivinen järjestämis-, ajojärjestely- ja välityspalvelu sekä palveluntuottajan joustava kuljetuskapasiteetti. Valmisteltavassa mallissa tilaajan käytössä olevat päivähintaiset ajoneuvot otettaisiin palveluntuottajan ajojärjestelyyn ja välitykseen. Lisäksi palveluntuottaja järjestäisi tarvittavan joustavan kuljetuskapasiteetin niihin kuljetuksiin, joita ei ole tarkoituksenmukaista hoitaa päivähintaisella kapasiteetilla. Tilaaja säilyttäisi päätösvallan kuljetusoikeuksista, kuljetusperiaatteista, palvelutasosta, valvonnasta ja reklamaatioiden käsittelystä. Markkinavuoropuhelun tarkoituksena on saada potentiaalisilta tarjoajilta näkemyksiä erityisesti palvelumallin toteutettavuudesta, joustavan kapasiteetin järjestämisestä, hinnoittelumekanismista, järjestelmä- ja valvontanäkymästä, kalustovaatimuksista, käyttöönotosta sekä tarjouspyyntöluonnoksen ja liitteiden ymmärrettävyydestä. Tämä tietopyyntö ei ole hankintailmoitus eikä tarjouspyyntö. Tietopyynnöllä ei pyydetä tarjouksia. Tietopyyntöön vastaaminen tai markkinavuoropuheluun osallistuminen ei sido toimijaa osallistumaan tarjouskilpailuun eikä osallistumatta jättäminen estä osallistumasta myöhemmin mahdolliseen tarjouskilpailuun. Tilaaja voi muuttaa hankinnan sisältöä, ehtoja, vaatimuksia, hinnoittelumallia, liiterakennetta ja aikataulua markkinavuoropuhelussa saadun palautteen perusteella.,','Rauman kaupunki','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056619','[\"60100000\", \"60120000\", \"60130000\", \"63712000\"]','[\"rauman\", \"koulukuljetusten\", \"operatiivinen\", \"järjestämis\", \"ajojärjestely\", \"välityspalvelu\", \"joustava\", \"kuljetuskapasiteetti\", \"kaupunki\", \"tekninen\", \"vuoropuhelu\", \"markkinavuoropuhelu\", \"kaupungin\", \"hankinnan\", \"palveluntuottajan\", \"joustavan\", \"tilaaja\", \"eikä\", \"tarjouskilpailuun\", \"valmistelee\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/rauma?id=627313&tpk=feadab73-d7eb-421e-acc2-ebf163c0c548\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056619\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56619\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Tekninen vuoropuhelu / markkinavuoropuhelu: Rauman kaupungin koulukuljetusten operatiivinen järjestämis-, ajojärjestely- ja välityspalvelu sekä joustava kuljetuskapasiteetti\", \"titleSv\": \"\", \"cpvCodes\": \"60100000 60120000 60130000 63712000\", \"currency\": null, \"deadline\": \"2026-09-22T11:00:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Rauman kaupunki valmistelee koulukuljetusten hankintaa, jossa hankinnan kohteena olisi koulukuljetusten operatiivinen järjestämis-, ajojärjestely- ja välityspalvelu sekä palveluntuottajan joustava kuljetuskapasiteetti. \\n\\nValmisteltavassa mallissa tilaajan käytössä olevat päivähintaiset ajoneuvot otettaisiin palveluntuottajan ajojärjestelyyn ja välitykseen. Lisäksi palveluntuottaja jär