INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1008,'2026-056608','HILMA','RFI','OPEN','Honkaharjun kutsujärjestelmä','Honkaharjun kutsujärjestelmä Keski-Pohjanmaan hyvinvointialue Soite valmistelee Honkaharjun toimintakeskuksen (Kokkola; 7 yksikköä, 111 asukashuonetta, 114 asukasta, 27 työntekijää) kutsu- ja henkilöturvajärjestelmän hankintaa. Suunniteltu hankintamalli on kokonaispalvelu: toimittaja toimittaa, omistaa ja ylläpitää laitteet ja järjestelmän tarvitseman tiedonsiirtoverkon sekä vastaa palvelusta koko sopimuskauden ajan kuukausihinnoiteltuna palveluna. Suunniteltu sopimusrakenne on kiinteä peruskausi ja optiokaudet, yhteensä enintään 10 vuotta. Toteutamme hankinnan valmisteluvaiheessa hankintalain 65 §:n mukaisen markkinakartoituksen, jonka tavoitteena on: 1. varmistaa hankintamallin (kokonaispalvelu vs. investointi + ylläpito) taloudellinen tarkoituksenmukaisuus, 2. varmistaa, että liitteenä oleva vaatimusluonnos on teknologianeutraali ja mahdollistaa usean toimittajan tarjoukset, sekä 3. saada realistinen kuva hinnoittelusta, sopimuskausista, elinkaaresta ja toimitusajoista. Kyse ei ole tarjouspyynnöstä: vastaukset eivät sido vastaajaa eivätkä hankintayksikköä, vastaaminen ei ole edellytys tulevaan tarjouskilpailuun osallistumiselle eikä siitä makseta korvausta. Vastauksia käsitellään luottamuksellisesti hankinnan valmistelussa; liikesalaisuuksiksi katsomanne kohdat pyydämme merkitsemään selvästi. Hankintayksikkö ei siirrä yksittäisen toimittajan ratkaisukuvauksia sellaisenaan tarjouspyynnön vaatimuksiksi. Vastauksen laajuudeksi riittää n. 2–5 sivua tai vastaukset suoraan alla oleviin kysymyksiin; myös osittaiset vastaukset ovat arvokkaita. Esittely ei ole edellytys eikä vaikuta asemaanne mahdollisessa tulevassa tarjouskilpailussa.,','Keski-Pohjanmaan hyvinvointialue','ANY',3,14,NULL,NULL,150000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056608','[\"51314000\"]','[\"honkaharjun\", \"keski\", \"pohjanmaan\", \"hyvinvointialue\", \"vastaukset\", \"kutsujärjestelmä\", \"suunniteltu\", \"kokonaispalvelu\", \"hankinnan\", \"varmistaa\", \"toimittajan\", \"edellytys\", \"eikä\", \"soite\", \"valmistelee\", \"toimintakeskuksen\", \"kokkola\", \"yksikköä\", \"asukashuonetta\", \"asukasta\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/soite?id=626835&tpk=fbc22b56-99b8-4470-9de3-2411e67ae526\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056608\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56608\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Honkaharjun kutsujärjestelmä\", \"titleSv\": \"\", \"cpvCodes\": \"51314000\", \"currency\": \"EUR\", \"deadline\": \"2026-09-17T11:00:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"FI1D5\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Keski-Pohjanmaan hyvinvointialue Soite valmistelee Honkaharjun toimintakeskuksen (Kokkola; 7 yksikköä, 111 asukashuonetta, 114 asukasta, 27 työntekijää) kutsu- ja henkilöturvajärjestelmän hankintaa. Suunniteltu hankintamalli on kokonaispalvelu: toimittaja toimittaa, omistaa ja ylläpitää laitteet ja järjestelmän tarvitseman tiedonsiirtoverkon sekä vastaa palvelusta koko sopimuskauden ajan kuukausihinnoiteltuna palveluna. Suunniteltu sopimusrakenne on kiinteä peruskausi ja optiokaudet, yhteensä enintään 10 vuotta.\\n\\nToteutamme hankinnan valmisteluvaiheessa hankintalain 65 §:n mukaisen markkinakartoituksen, jonka tavoitteena on:\\n\\n1. varmistaa hankintamallin (kokonaispalvelu vs. investointi + ylläpito) taloudellinen tarkoituksenmukaisuus,\\n2. varmistaa, että liitteenä oleva vaatimusluonnos on teknologianeutraali ja mahdollistaa usean toimittajan tarjoukset, sekä\\n3. saada realistinen kuva hinnoittelusta, sopimuskausista, elinkaaresta ja toimitusajoista.\\n\\nKyse ei ole tarjouspyynnöstä: vastaukset eivät sido vastaajaa eivätkä hankintayksikköä, vastaaminen ei ole edellytys tulevaan tarjouskilpailuun osallistumiselle eikä siitä makseta korvausta. Vastauksia käsitellään luottamuksellisesti hankinnan valmistelussa; liikesalaisuuksiksi katsomanne kohdat pyydämme merkitsemään selvästi. Hankintayksikkö ei siirrä yksittäisen toimittajan ratkaisukuvauksia sellaisenaan tarjouspyynnön vaatimuksiksi.\\n\\n Vastauksen laajuudeksi riittää n. 2–5 sivua tai vastaukset suoraan alla oleviin kysymyksiin; myös osittaiset vastaukset ovat arvokkaita. Esittely ei ole edellytys eikä vaikuta asemaanne mahdollisessa tulevassa tarjouskilpailussa.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": 150000.0, \"expirationDate\": \"2026-09-17T11:00:00Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": null, \"lotResultTotalAmount\": null, \"justWorkingConditions\": null, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": null, \"includesFrameworkAgreement\": null, \"smeParticipationConsidered\": null, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": null, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": null, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmi