INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1009,'2026-051963','HILMA','RFP','OPEN','Koulutusten ja tukien hallinta- sekä asiakasrekisterijärjestelmä (KARE)','Koulutusten ja tukien hallinta- sekä asiakasrekisterijärjestelmä (KARE) Hankinnan kohteena on yksi yhtenäinen järjestelmäkokonaisuus (Koulutusten ja tukien hallinta- sekä asiakasrekisterijärjestelmä (KARE)) pilvipalveluna (SaaS) sekä sen käyttöönotto ja jatkuvat palvelut. Hankinta sisältää: •määrittelyvaiheen, jossa tarkennetaan toteutettava ratkaisu ja toteutuksen yksityiskohdat •käyttöönottoprojektin: konfiguroinnin, pakolliset integraatiot, tietojen migraation nykyjärjestelmästä, dokumentoinnin, koulutuksen sekä testauksen ja laadunvarmistuksen •järjestelmän käyttöoikeudet palveluna koko sopimuskaudelle •tuki- ja ylläpitopalvelut sovituilla palvelutasoilla •jatkokehityksen ja asiantuntijatyön tilattavana lisätyönä Ratkaisu hankitaan yhdeltä toimittajalta kokonaisuutena. Tarjoaja vastaa kokonaisuudesta myös siltä osin kuin se käyttää alihankkijoita.,','Toimihenkilöjärjestöjen Sivistysliitto TJS - Funktionärsorganisationernas Bildningsförbund FOB ry','ANY',1,4,NULL,NULL,215000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-051963','[\"72000000\", \"48000000\"]','[\"koulutusten\", \"tukien\", \"hallinta\", \"asiakasrekisterijärjestelmä\", \"kare\", \"ratkaisu\", \"hankinnan\", \"kohteena\", \"yksi\", \"yhtenäinen\", \"järjestelmäkokonaisuus\", \"pilvipalveluna\", \"saas\", \"käyttöönotto\", \"jatkuvat\", \"palvelut\", \"hankinta\", \"sisältää\", \"määrittelyvaiheen\", \"jossa\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/f