INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1012,'2026-056596','HILMA','OTHER','OPEN','Kiinteistönhoitopalvelut 2 + 3 vuotta','Kiinteistönhoitopalvelut 2 + 3 vuotta Hankinnan kohteena on Jämijärven kunnan kiinteistönhoitopalvelut 1.9.2026-30.8.2028. Hankintayksiköllä on lisäksi oikeus jatkaa sopimusta kolmen (3) vuoden optiokaudella. Hankintayksikkö päättää option käyttöönotosta erikseen liitteenä 2 olevassa sopimusluonnoksessa kuvatulla tavalla. Palveluntuottaja vastaa kaikista Jämijärven kunnan kiinteistönhoitopalveluista siten, kuin liitteenä 1 olevassa palvelukuvauksessa on tarkemmin määritelty. Palveluntuottajan vastuulla ovat siten - Jämijärven kunnan omistamien kiinteistöjen kiinteistönhoito ja kunnossapito piha- ja ulkoalueineen - asemakaavateiden, Jämin valaistun ulkoilureitin ja Mutkalan teollisuusalueen valaistuksen hoito (pl. luvanvaraiset sähkötyöt) - jätehuolto ja aluekeräyspisteet - Pihlajamaan muistomerkki ulkoalueineen - kotiseutumuseon ulkoalueet - matonpesupaikka - torialue - koirapuisto - palvelukuvauksessa yksilöityjen liikuntapaikkojen hoito ja kunnossapito sekä - puisto- ja nurmialueet (kuvattu liitteessä 6). Palveluntuottaja vastaa siten edellä mainittujen kohteiden teknisten järjestelmien hoidosta, kiinteistöhuollosta ja kunnossapidosta sekä erityislaitehuollosta. Kiinteistöjen yhteenlaskettu kerrosala on n. 10 600 m2 ja kokonaistonttiala n. 70 000 m2. Hoitoalueet ja niiden tarkat sijainnit on kuvattu liitteessä 1 Palvelukuvaus. Hoidettavista nurmialueista on suuntaa-antavat kartat liitteessä 6. Kiinteistönhoitopalvelut suoritetaan pääasiassa Palveluntuottajan työvälineillä, koneilla ja laitteilla, joiden hankkimisesta ja ylläpidosta aiheutuvista kustannuksista Palveluntuottaja vastaa. Erillistä kilometrikorvausta ei makseta. Tilaaja kustantaa kaikki aineet ja sopimuskohteisiin kiinteästi asennettavat tarvikkeet (kuten vesihanat, sulakkeet, lamput, ilmanvaihtokoneiden suodattimet). Materiaalien ja aineiden hankinta varmistetaan Tilaajalta ennen tilausta. Palveluntuottaja suorittaa kiinteistönhoitopalvelut kohteissa liitteenä 1 olevassa Palvelukuvauksessa esitettyinä normaaleina työaikoina niiltä osin kuin töiden suorittaminen ei haittaa kiinteistöjen tavanomaista käyttöä eikä tarkempaa suoritusaikaa ole ilmoitettu. Palveluntuottajan on lisäksi oltava 24/7 päivystysvalmiudessa. Kiireellisten palvelupyyntöjen osalta Palveluntuottajan on aloitettava työn suorittaminen viimeistään yhden (1) tunnin kuluessa siitä, kun palvelupyyntö on saapunut Palveluntuottajalle. Mikäli palvelun laajuudessa sopimuskaudella tapahtuu muutoksia (esim. palveluntuottajan hoitovastuulla oleva kohde puretaan tai saneerataan tai omistussuhde muuttuu), Tilaajalla on oikeus edellyttää muutoksia kuukausihintaan siten, kuin tarjouspyynnön liitteenä 2 olevassa sopimusluonnoksessa on tarkemmin kuvattu. Ennen tarjouksen tekemistä tilaaja järjestää hankinnan kohteena olevien kiinteistönhoitopalveluiden esittelykierroksen. Kiinteistöihin tutustuminen toteutetaan 25.5.2026 klo 9.00 alkaen. Kokoontuminen Jämijärven kunnanvirastolla osoitteessa Peijarintie 5 A, 38800 Jämijärvi. Lisätietoja antaa suunnittelija Marko Sillanpää, p. 050 322 9008. Mikäli Tarjoaja ei pääse osallistumaan em. kierrokseen, on hänen ilmoitettava siitä ennen esittelykierrosta, jolloin kunta pyrkii järjestämään vaihtoehtoisen ajankohdan. Esittelykierrokselle osallistuminen on edellytyksenä tarjouksen tekemiselle.,','Jämijärven kunta','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056596','[\"70332000\"]','[\"jämijärven\", \"kiinteistönhoitopalvelut\", \"palveluntuottajan\", \"liitteenä\", \"olevassa\", \"palveluntuottaja\", \"siten\", \"kunnan\", \"vastaa\", \"palvelukuvauksessa\", \"kiinteistöjen\", \"kuvattu\", \"liitteessä\", \"ennen\", \"kunta\", \"vuotta\", \"hankinnan\", \"kohteena\", \"lisäksi\", \"oikeus\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056596\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56596\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Kiinteistönhoitopalvelut 2 + 3 vuotta\", \"titleSv\": \"\", \"cpvCodes\": \"70332000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": false, \"nutsCodes\": \"FI196\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Hankinnan kohteena on Jämijärven kunnan kiinteistönhoitopalvelut 1.9.2026-30.8.2028. Hankintayksiköllä on lisäksi oikeus jatkaa sopimusta kolmen (3) vuoden optiokaudella. Hankintayksikkö päättää option käyttöönotosta erikseen liitteenä 2 olevassa sopimusluonnoksessa kuvatulla tavalla.\\n\\nPalveluntuottaja vastaa kaikista Jämijärven kunnan kiinteistönhoitopalveluista siten, kuin liitteenä 1 olevassa palvelukuvauksessa on tarkemmin määritelty. \\n\\nPalveluntuottajan vastuulla ovat siten\\n- Jämijärven kunnan omistamien kiinteistöjen kiinteistönhoito ja kunnossapito piha- ja ulkoalueineen\\n- asemakaavateiden, Jämin valaistun ulkoilureitin ja Mutkalan teollisuusalueen valaistuksen hoito (pl. luvanvaraiset sähkötyöt) \\n- jätehuolto ja aluekeräyspisteet\\n- Pihlajamaan muistomerkki ulkoalueineen\\n- kotiseutumuseon ulkoalueet \\n- matonpesupaikka\\n- torialue\\n- koirapuisto \\n- palvelukuvauksessa yksilöityjen liikuntapaikkojen hoito ja kunnossapito sekä\\n- puisto- ja nurmialueet (kuvattu liitteessä 6).\\n\\nPalveluntuottaja vastaa siten edellä mainittujen kohteiden teknisten järjestelmien hoidosta, kiinteistöhuollosta ja kunnossapidosta sekä erityislaitehuollosta. Kiinteistöjen yhteenlaskettu kerrosala on n. 10 600 m2 ja kokonaistonttiala n. 70 000 m2. Hoitoalueet ja niiden tarkat sijainnit on kuvattu liitteessä 1 Palvelukuvaus. Hoidettavista nurmialueista on suuntaa-antavat kartat liitteessä 6. \\n\\nKiinteistönhoitopalvelut suoritetaan pääasiassa Palveluntuottajan työvälineillä, koneilla ja laitteilla, joiden hankkimisesta ja ylläpidosta aiheutuvista kustannuksista Palveluntuottaja vastaa. Erillistä kilometrikorvausta ei makseta. Tilaaja kustantaa kaikki aineet ja sopimuskohteisiin kiinteästi asennettavat tarvikkeet (kuten vesihanat, sulakkeet, lamput, ilmanvaihtokoneiden suodattimet). Materiaalien ja aineiden hankinta varmistetaan Tilaajalta ennen tilausta.\\n\\nPalveluntuottaja suorittaa kiinteistönhoitopalvelut kohteissa liitteenä 1 olevassa Palvelukuvauksessa esitettyinä normaaleina työaikoina niiltä osin kuin töiden suorittaminen ei haittaa kiinteistöjen tavanomaista käyttöä eikä tarkempaa suoritusaikaa ole ilmoitettu. Palveluntuottajan on lisäksi oltava 24/7  päivystysvalmiudessa. Kiireellisten palvelupyyntöjen osalta Palveluntuottajan on aloitettava työn suorittaminen viimeistään yhden (1) tunnin kuluessa siitä, kun palvelupyyntö on saapunut Palveluntuottajalle. \\n \\nMikäli palvelun laajuudessa sopimuskaudella tapahtuu muutoksia (esim. palveluntuottajan hoitovastuulla oleva kohde puretaan tai saneerataan tai omistussuhde muuttuu), Tilaajalla on oikeus edellyttää muutoksia kuukausihintaan siten, kuin tarjouspyynnön liitteenä 2 olevassa sopimusluonnoksessa on tarkemmin kuvattu.  \\n\\nEnnen tarjouksen tekemistä tilaaja järjestää hankinnan kohteena olevien kiinteistönhoitopalveluiden esittelykierroksen. Kiinteistöihin tutustuminen toteutetaan 25.5.2026 klo 9.00 alkaen. Kokoontuminen Jämijärven kunnanvirastolla osoitteessa Peijarintie 5 A, 38800 Jämijärvi. \\n\\nLisätietoja antaa suunnittelija Marko Sillanpää, p. 050 322 9008. Mikäli Tarjoaja ei pääse osallistumaan em. kierrokseen, on hänen ilmoitettava siitä ennen esittelykierrosta, jolloin kunta pyrkii järjestämään vaihtoehtoisen ajankohdan.\\n\\nEsittelykierrokselle osallistuminen on edellytyksenä tarjouksen tekemiselle.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2027-03-08T11:39:49.895Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"Alarotu Jussi (2953797-9)\", \"innovationConsidered\": false, \"lotResultTotalAmount\": 0.0, \"justWorkingConditions\": false, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": 3, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"E4\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"Kiinteistönhoitopalvelut 2 + 3 vuotta\", \"titleSv\": \"\", \"cpvCodes\": \"70332000\", \"currency\": null, \"deadline\": null, \"eFormsId\": \"cfc30667-74b5-4512-ad26-33940436ca8c\", \"isEForms\": true, \"mainType\": \"ContractAwardNotices\", \"noticeId\": 56596, \"lowCarbon\": false, \"nutsCodes\": \"FI196\", \"titleOther\": \"\", \"isCancelled\": false, \"procedureId\": 32520, \"biodiversity\": false, \"dateModified\": \"2026-09-08T11:39:49.904Z\", \"fullEFormsId\": \"cfc30667-74b5-4512-ad26-33940436ca8c-01\", \"noticeNumber\": \"2026-056596\", \"@search.score\": 1.0, \"codeOfConduct\": false, \"datePublished\": \"2026-09-08T11:39:49.895Z\", \"descriptionEn\": \"\", \"descriptionFi\": \"Kiinteistönhoitopalvelut 2 + 3 vuotta Hankinnan kohteena on Jämijärven kunnan kiinteistönhoitopalvelut 1.9.2026-30.8.2028. Hankintayksiköllä on lisäksi oikeus jatkaa sopimusta kolmen (3) vuoden optiokaudella. Hankintayksikkö päättää option käyttöönotosta erikseen liitteenä 2 olevassa sopimusluonnoksessa kuvatulla tavalla.\\n\\nPalveluntuottaja vastaa kaikista Jämijärven kunnan kiinteistönhoitopalveluista siten, kuin liitteenä 1 olevassa palvelukuvauksessa on tarkemmin määritelty. \\n\\nPalveluntuottajan vastuulla ovat siten\\n- Jämijärven kunnan omistamien kiinteistöjen kiinteistönhoito ja kunnossapito piha- ja ulkoalueineen\\n- asemakaavateiden, Jämin valaistun ulkoilureitin ja Mutkalan teollisuusalueen valaistuksen hoito (pl. luvanvaraiset sähkötyöt) \\n- jätehuolto ja aluekeräyspisteet\\n- Pihlajamaan muistomerkki ulkoalueineen\\n- kotiseutumuseon ulkoalueet \\n- matonpesupaikka\\n- torialue\\n- koirapuisto \\n- palvelukuvauksessa yksilöityjen liikuntapaikkojen hoito ja kunnossapito sekä\\n- puisto- ja nurmialueet (kuvattu liitteessä 6).\\n\\nPalveluntuottaja vastaa siten edellä mainittujen kohteiden teknisten järjestelmien hoidosta, kiinteistöhuollosta ja kunnossapidosta sekä erityislaitehuollosta. Kiinteistöjen yhteenlaskettu kerrosala on n. 10 600 m2 ja kokonaistonttiala n. 70 000 m2. Hoitoalueet ja niiden tarkat sijainnit on kuvattu liitteessä 1 Palvelukuvaus. Hoidettavista nurmialueista on suuntaa-antavat kartat liitteessä 6. \\n\\nKiinteistönhoitopalvelut suoritetaan pääasiassa Palveluntuottajan työvälineillä, koneilla ja laitteilla, joiden hankkimisesta ja ylläpidosta aiheutuvista kustannuksista Palveluntuottaja vastaa. Erillistä kilometrikorvausta ei makseta. Tilaaja kustantaa kaikki aineet ja sopimuskohteisiin kiinteästi asennettavat tarvikkeet (kuten vesihanat, sulakkeet, lamput, ilmanvaihtokoneiden suodattimet). Materiaalien ja aineiden hankinta varmistetaan Tilaajalta ennen tilausta.\\n\\nPalveluntuottaja suorittaa kiinteistönhoitopalvelut kohteissa liitteenä 1 olevassa Palvelukuvauksessa esitettyinä normaaleina työaikoina niiltä osin kuin töiden suorittaminen ei haittaa kiinteistöjen tavanomaista käyttöä eikä tarkempaa suoritusaikaa ole ilmoitettu. Palveluntuottajan on lisäksi oltava 24/7  päivystysvalmiudessa. Kiireellisten palvelupyyntöjen osalta Palveluntuottajan on aloitettava työn suorittaminen viimeistään yhden (1) tunnin kuluessa siitä, kun palvelupyyntö on saapunut Palveluntuottajalle. \\n \\nMikäli palvelun laajuudessa sopimuskaudella tapahtuu muutoksia (esim. palveluntuottajan hoitovastuulla oleva kohde puretaan tai saneerataan tai omistussuhde muuttuu), Tilaajalla on oikeus edellyttää muutoksia kuukausihintaan siten, kuin tarjouspyynnön liitteenä 2 olevassa sopimusluonnoksessa on tarkemmin kuvattu.  \\n\\nEnnen tarjouksen tekemistä tilaaja järjestää hankinnan kohteena olevien kiinteistönhoitopalveluiden esittelykierroksen. Kiinteistöihin tutustuminen toteutetaan 25.5.2026 klo 9.00 alkaen. Kokoontuminen Jämijärven kunnanvirastolla osoitteessa Peijarintie 5 A, 38800 Jämijärvi. \\n\\nLisätietoja antaa suunnittelija Marko Sillanpää, p. 050 322 9008. Mikäli Tarjoaja ei pääse osallistumaan em. kierrokseen, on hänen ilmoitettava siitä ennen esittelykierrosta, jolloin kunta pyrkii järjestämään vaihtoehtoisen ajankohdan.\\n\\nEsittelykierrokselle osallistuminen on edellytyksenä tarjouksen tekemiselle.,\", \"descriptionSv\": \"\", \"isCorrigendum\": false, \"linkedNotices\": \"\", \"procedureType\": \"open\", \"sendingSystem\": \"Cloudia Kilpailutus\", \"estimatedValue\": null, \"expirationDate\": \"2027-03-08T11:39:49.895Z\", \"parentNoticeId\": null, \"circularEconomy\": false, \"endUserInvolved\": null, \"isEuProcurement\": false, \"noticeOjsNumber\": \"\", \"contractFolderId\": \"c253c7e5-49ea-4e54-982b-dd090a8675ea\", \"descriptionOther\": \"\", \"organisationType\": \"body-pl\", \"previousEFormsId\": [], \"tedPublicationId\": null, \"tenderingInHilma\": false, \"previousSearchIds\": [], \"organisationNameEn\": \"\", \"organisationNameFi\": \"Jämijärven kunta\", \"organisationNameSv\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"organisationAddress\": \"Peijarintie 5 A 38800 Jämijärvi FIN\", \"procurementTypeCode\": \"services\", \"winnerOrganisations\": \"Alarotu Jussi (2953797-9)\", \"innovationConsidered\": false, \"organisationNutsCode\": \"FI196\", \"previousFullEFormsId\": [], \"previousNoticeNumber\": [], \"isNationalProcurement\": true, \"justWorkingConditions\": false, \"organisationNameOther\": \"\", \"organisationDepartment\": \"\", \"listedGreenCriteriaUsed\": null, \"noticeResultTotalAmount\": 684000.0, \"oldProcurementProjectId\": 0, \"procurementDocumentsUrl\": null, \"previousContractFolderId\": [], \"previousTedPublicationId\": [], \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"refOldNoticeTedPublicationId\": \"fb859d99-43c1-436c-b8a6-61da8506edbe-01\", \"solutionNewToMarketOrIndustry\": false, \"isPrivateSmallValueProcurement\": false, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"isNationalSmallValueProcurement\": false, \"noticeResultTotalAmountCurrency\": \"EUR\", \"organisationNationalRegistrationNumber\": \"0133127-4\", \"overallMaximumFrameworkContractsAmount\": null, \"overallMaximumFrameworkContractsCurrency\": null, \"overallApproximateFrameworkContractsAmount\": null, \"overallApproximateFrameworkContractsCurrency\": null}',55,NULL,'2026-09-08 14:03:47','2026-09-08 21:34:14');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1013,'2026-056593','HILMA','OTHER','OPEN','Tiehöylä','Tiehöylä Ammattiopisto Gradian maarakennusala hankkii opetuskäyttöön tiehöylän. Koneen tulee olla painoltaan 16 - 24 tonninen ja runko-ohjattu. Tarkemmat konetta koskevat vaatimukset ovat tämän tarjouspynnön kohdassa \"Hankinnan kohteen kriteerit\". Hankintaan on käytettävissä enintään 100 000 € (alv 0%), joten tätä kalliimmat tarjoukset hylätään. Tarjouksessa tarjoaja valitsee annetun ohjeiden mukaisesti osan laatupisteistä (vuosimallin, ajotuntien ym. mukaisesti). Tarjousajan päättymisen jälkeen tilaajan edustajat ovat yhteydessä tarjouksessa mainittuun yhteyshenkilöön koneeseen tutustumisen ajankohdan sopimiseksi. Koekäytön myötä tilaajan edustajat pisteyttävät tarjotun koneen loput laatupisteet, jotka lisätään tarjouksen laatupisteytykseen. Tarjouksen pyytäjä pidättää itsellään oikeuden olla kokonaan hankkimatta kyseistä konetta tämän kilpailutuksen perusteella. Mikäli tarjottu kone on tarjoushetkellä ulkomailla, tilajaa pidättää oikeuden olla koeajamatta konetta, mikäli sen saamat lähtöpisteet osoittavat, ettei se pärjää pisteytyksessä.,','Jyväskylän koulutuskuntayhtymä Gradia','ANY',6,5,NULL,NULL,100000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056593','[\"34144400\"]','[\"konetta\", \"tiehöylä\", \"koneen\", \"ovat\", \"tämän\", \"tarjouksessa\", \"mukaisesti\", \"tilaajan\", \"edustajat\", \"tarjouksen\", \"pidättää\", \"oikeuden\", \"mikäli\", \"jyväskylän\", \"koulutuskuntayhtymä\", \"gradia\", \"ammattiopisto\", \"gradian\", \"maarakennusala\", \"hankkii\"]',NULL,NULL,'[{\"url\": \"h