INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1014,'2026-056587','HILMA','RFP','OPEN','Paltamon kunnan omistamien rakennuksien purku-urakka','Purku-urakan kohteena on kaksi erillistä purkukohdetta. Paltamon kunnan omistama entinen koulu- ja virastorakennus, jonka alkuperäisosa on rakennettu 1960- luvun alussa. Virastotalonlaajennus on rakennettu 1970 -luvulla. Rakennuskokonaisuus on kaksikerroksinen. Rakennuskokonaisuudessa virastotalon alla on osittainen kellari. Myös kouluosan alla on kellari, joka on osittain maan pinnantasolla. Rakennuksen kuuluva liikuntasaliosan on muita tiloja korkeampi. Lisäksi piha-alueen asfaltoinin purusta annetaan oma urakkahinta. Purettavan asfaltoinin pinta-ala on n. 4300 m2. Lisäksi puretaan Kajaanintie 29 oleva rakennuksen harkkosokkeli ja betoninen alapohjarakenne. Varsinainen rakennus on siirretty toisaalle. Rakennuksen ala on n. 10x14 m. Purettavien kohteiden tarkemmat tiedot käyvät esiin liitteinä olevista asiakirjoista. Tilaaja pidättää itsellään oikeuden olla hyväksymättä yhtäkään annetuista tarjouksista., Koulukankaan koulu-/kunnanviraston purku-urakka Paltamon kunnan omistama entinen koulu- ja virastorakennus, jonka alkuperäisosa on rakennettu 1960- luvun alussa. Virastotalonlaajennus on rakennettu 1970 -luvulla. Rakennuskokonaisuus on kaksikerroksinen. Rakennuskokonaisuudessa virastotalon alla on osittainen kellari. Myös kouluosan alla on kellari, joka on osittain maan pinnantasolla. Rakennuksen kuuluva liikuntasaliosan on muita tiloja korkeampi., Koulu-/kunnanviraston piha-alueen asfaltoinnin purku-urakka Piha-alueen asfaltoinin purusta annetaan oma urakkahinta. Purettavan asfaltoinin pinta-ala on n. 4300 m2., Kajaanintie 29 perustus- ja sokkelirakenteiden purku-urakka Kajaanintie 29 oleva rakennuksen harkkosokkeli ja betoninen alapohjarakenne. Varsinainen rakennus on siirretty toisaalle. Rakennuksen ala on n. 10x14 m.,','Paltamon kunta','ANY',2,3,NULL,NULL,400000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056587','[\"45111300\", \"45111000\"]','[\"rakennuksen\", \"purku\", \"paltamon\", \"urakka\", \"koulu\", \"rakennettu\", \"alla\", \"kellari\", \"asfaltoinin\", \"kunnan\", \"piha\", \"alueen\", \"kajaanintie\", \"omistama\", \"entinen\", \"virastorakennus\", \"jonka\", \"alkuperäisosa\", \"luvun\", \"alussa\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/paltamo?id=622712&tpk=4be3169c-804b-4031-8d33-7d58af12aca1\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056587\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56587\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Koulukankaan koulu-/kunnanviraston purku-urakka\", \"titleSv\": \"\", \"cpvCodes\": \"45111300\", \"currency\": \"EUR\", \"deadline\": \"2026-09-13T20:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI1D8\", \"titleOther\": \"\", \"biodiversity\": true, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Paltamon kunnan omistama entinen koulu- ja virastorakennus, jonka alkuperäisosa on rakennettu 1960- luvun alussa. Virastotalonlaajennus on rakennettu 1970 -luvulla. Rakennuskokonaisuus on kaksikerroksinen.\\n\\nRakennuskokonaisuudessa virastotalon alla on osittainen kellari. Myös kouluosan alla  on kellari, joka on osittain maan pinnantasolla. Rakennuksen kuuluva liikuntasaliosan on muita tiloja korkeampi.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": 400000.0, \"expirationDate\": \"2026-09-13T20:00:00Z\", \"circularEconomy\": true, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, 