INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1015,'2026-056584','HILMA','OTHER','OPEN','Mt 357 Hurukselantie parantaminen Keltakalliontie kohdalla ja Peippolan LITU kohde, Kotka, KU.','Mt 357 Hurukselantie parantaminen Keltakalliontie kohdalla ja Peippolan LITU kohde, Kotka, KU. Mt 357 Huruksenlantieltä rakennetaan ajoyhteys Keltakalliontielle. Hanke sisältää maanleikkaustöitä, pilaristabilointia, vaahtolasikevennystä, rakennekerrosten rakentamista ja uusia liittymäjärjestelyjä ja valaistuksen rakentamista. Hankealueella sijaitsee eri laitosten putkia ja johtoja joiden suojaus / siirto toimenpiteitä suoritetaan urakassa. Peippolan LITU-kohde sijaitsee Hurukselantiellä ennen Lentokentäntien liittymää. Hankkeessa rakennetaan uusi suojatiesaareke maantielle 357. Hanke sisältää maanleikkaustöitä, louhintatöitä, rakennekerrosten ja valaistuksen rakentamista ja liittymäjärjestelyjä. Hanke sijaitsee Kotkan kaupungin alueella Tarkempi kuvaus on esitetty tarjouspyynnön asiakirjoissa. Urakka on kokonaishintaperusteinen kokonaisurakka (KU).,','Työllisyys-, kehittämis- ja hallintokeskus','ANY',2,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056584','[\"45200000\"]','[\"peippolan\", \"litu\", \"kohde\", \"hanke\", \"rakentamista\", \"sijaitsee\", \"hurukselantie\", \"parantaminen\", \"keltakalliontie\", \"kohdalla\", \"kotka\", \"rakennetaan\", \"sisältää\", \"maanleikkaustöitä\", \"rakennekerrosten\", \"liittymäjärjestelyjä\", \"valaistuksen\", \"työllisyys\", \"kehittämis\", \"hallintokeskus\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056584\", \"name\": \"H