INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1017,'2026-056580','HILMA','RFP','OPEN','Ruskon kirjaston irtokalustehankinta','Ruskon kirjaston irtokalustehankinta Ruskon kunta kilpailuttaa käänteisenä kilpailutuksena Ruskon uuden kirjaston irtokalusteet tarjouskilpailussa kuvatulla tavalla. Liiteasiakirjoissa kuvataan Ruskon uuden kirjaston kirjastokalustehankinnan toiminnalliset lähtökohdat, käyttäjät, suunnitteluperiaatteet sekä tilakohtaiset tarpeet. Hankintaan kuuluvat kirjaston aineistojen säilyttämiseen, esillepanoon, käsittelyyn ja asiakaspalveluun tarkoitetut kalusteet, kuten kirjahyllyt, lasten aineistokalusteet, lehtien esittely- ja säilytyskalusteet, aineiston esittelykalusteet, kirjavaunut ja palvelupöytä. Kirjastosalin muu irtokalustus hankitaan erikseen. Käänteisen kilpailutuksen kustannuksena on 70.000,00 € alv0% hinnalla. Tilaaja on julkinen toimija. Hankinnassa noudatetaan JYSE 2025 Tavarat - sopimusehtoja kohdassa hinta- ja kaupalliset ehdot mainituin poikkeuksin.,','Ruskon kunta','ANY',6,14,NULL,NULL,70000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056580','[\"39155000\"]','[\"ruskon\", \"kirjaston\", \"kunta\", \"irtokalustehankinta\", \"uuden\", \"kilpailuttaa\", \"käänteisenä\", \"kilpailutuksena\", \"irtokalusteet\", \"tarjouskilpailussa\", \"kuvatulla\", \"tavalla\", \"liiteasiakirjoissa\", \"kuvataan\", \"kirjastokalustehankinnan\", \"toiminnalliset\", \"lähtökohdat\", \"käyttäjät\", \"suunnitteluperiaatteet\", \"tilakohtaiset\"]',NULL,NULL,'[{\"url\": \"https://supplierportal.c1.app.mercell.com/Ruskon%20kunta%2002045245/?tpg=76549b0a-a093-4659-b478-e9eb818e4ef4\", \"n