INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1018,'2026-056576','HILMA','RFP','OPEN','Spektrofotometri','Spektrofotometri HUS-yhtymä pyytää tarjouksia spektrofotometrista. Hankittavaa UV-Vis spektrofotometria käytetään HUS Diagnostiikkakeskuksen erikoiskemian laboratoriossa kvalitatiivisissa ja kvantitatiivisissa määrityksissä aineenvaihdunta- ja porfyria-analytiikassa sekä in house –menetelmien vakioliuosten pitoisuuden tarkistamisessa. Hankittavalla spektrofotometrilla määritetään potilasnäytteitä. Laitettä käytetään lisäksi Automaatiolaboratoriossa likvorinäytteiden tutkimukseen pyyhkäisemällä spektri. Tämän lisäksi hankintaan sisältyy huoltosopimukset hankittaville laitteille sekä työasema kaikkine ohjelmistoineen, jotka laitteisto tarvitsee toimiakseen aiotussa tarkoituksessa, työasemalle asennetuna. Hankintaan sisältyy lisäksi optio kahdesta samanlaisesta spektrofotometristä vuosien 2027-2030 aikana. Laitteella tällä hetkellä tehtävät tutkimukset ovat mm. plasman hemoglobiinimääritys laskemalla spektristä derivaatta, likvorin bilirubiini ja oksihemoglobiini spektrimittauksella sekä muita kvantitatiivisia yhdisteiden pitoisuusmittauksia (pyruvaatti, tiosyanaatti, porfyriinejä). Hankintaa ei ole jaettu osiin, koska kilpailutettava hankinta muodostaa yhden kokonaisuuden ja osiin jakaminen tekisi sopimuksen toteuttamisesta teknisesti ja sopimuksellisesti liian vaikeaa. Hankinnan kohde ja sitä koskevat vaatimukset on kuvattu yksityiskohtaisesti tarjouspyynnössä ja sen liitteissä.,','HUS-yhtymä','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056576','[\"38000000\", \"38433000\"]','[\"yhtymä\", \"lisäksi\", \"spektrofotometri\", \"käytetään\", \"hankintaan\", \"sisältyy\", \"osiin\", \"pyytää\", \"tarjouksia\", \"spektrofotometrista\", \"hankittavaa\", \"spektrofotometria\", \"diagnostiikkakeskuksen\", \"erikoiskemian\", \"laboratoriossa\", \"kvalitatiivisissa\", \"kvantitatiivisissa\", \"määrityksissä\", \"aineenvaihdunta\", \"porfyria\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/huslogistiikka?id=606178&tpk=f6ae5e05-989f-473b-b919-07e0ba8dea38\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056576\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56576\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Spektrofotometri\", \"titleSv\": \"\", \"cpvCodes\": \"38000000 38433000\", \"currency\": null, \"deadline\": \"2026-09-18T09:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"HUS-yhtymä pyytää tarjouksia spektrofotometrista. Hankittavaa UV-Vis spektrofotometria käytetään HUS Diagnostiikkakeskuksen erikoiskemian laboratoriossa kvalitatiivisissa ja kvantitatiivisissa määrityksissä aineenvaihdunta- ja porfyria-analytiikassa sekä in house –menetelmien vakioliuosten pitoisuuden tarkistamisessa. Hankittavalla spektrofotometrilla määritetään potilasnäytteitä. Laitettä käytetään lisäksi Automaatiolaboratoriossa likvorinäytteiden tutkimukseen pyyhkäisemällä spektri. \\n\\nTämän lisäksi hankintaan sisältyy huoltosopimukset hankittaville laitteille sekä työasema kaikkine ohjelmistoineen, jotka laitteisto tarvitsee toimiakseen aiotussa tarkoituksessa, työasemalle asennetuna. Hankintaan sisältyy lisäksi optio kahdesta samanlaisesta spektrofotometristä vuosien 2027-2030 aikana.\\n\\nLaitteella tällä hetkellä tehtävät tutkimukset ovat mm. plasman hemoglobiinimääritys laskemalla spektristä derivaatta, likvorin  bilirubiini ja oksihemoglobiini spektrimittauksella sekä muita kvantitatiivisia yhdisteiden pitoisuusmittauksia (pyruvaatti, tiosyanaatti, porfyriinejä). \\n\\nHankintaa ei ole jaettu osiin, koska kilpailutettava hankinta muodostaa yhden kokonaisuuden ja osiin jakaminen tekisi sopimuksen toteuttamisesta teknisesti ja sopimuksellisesti liian vaikeaa.\\n\\nHankinnan kohde ja sitä koskevat vaatimukset on kuvattu yksityiskohtaisesti tarjouspyynnössä ja sen liitteissä.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-09-18T09:00:00Z\", \"circularEconomy\": true, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": true, \"listedGreenCriteriaUsed\": false, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": true, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"E3\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"Spektrofotometri\", \"titleSv\": \"\", \"cpvCodes\": \"38000000 38433000\", \"currency\": null, \"deadline\": \"2026-09-18T09:00:00Z\", \"eFormsId\": \"99b46e60-1f0a