INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1020,'2026-056574','HILMA','OTHER','OPEN','Keskuspuistokadun ja Meripuistokadun liittymän rakentaminen','Keskuspuistokadun ja Meripuistokadun liittymän rakentaminen Kemin kaupunki pyysi tarjouksia Keskuspuistokadun ja Meripuistokadun liittymän rakentamisesta rakennussuunnitelman mukaisesti kaikkine töineen, järjestelyineen ja materiaalihankintoineen. Urakkaan kuuluu työt siinä laajuudessa, kuin ne on tarjouspyynnön liitteenä olevissa asiakirjoissa määritelty kaikkine tiejärjestelyineen, varusteineen ja laitteineen. Rakennuskohde sijaitsee Kemin Sauvosaaren kaupunginosassa Keskuspuistokadun ja Meripuistokadun risteyksessä. Rakennuttaja edellytti, että urakoitsija on tutustunut urakka-asiakirjoihin, rakennuspaikkoihin ja työskentelyolosuhteisiin ennen tarjouksen antamista. Urakka oli kokonaishintaperusteinen kokonaisurakka. Kokonaishinta perustuu urakoitsijan tarjouspyyntöasiakirjojen perusteella laskemaansa kokonaishintaan. Tarjousten vertailu tehdään kokonaishinnan perusteella. Kokonaishinnan tuli perustua suunnitelmista ja muista urakka-asiakirjoista ilmeneviin määriin ja urakoitsijan suorittamaan määrälaskentaan. Koko urakan tulee olla täysin valmis sekä urakan luovutusaineistot tilaajalle luovutettuina ja tilaajan tarkastamia sekä hyväksymiä 30.11.2026 mennessä. Urakka-aikataulu ja välitavoitteet on esitetty tarjouspyynnön liitteissä. Hankintaan sovelletaan YSE98-sopimusehtoja. Hankinnan arvioidaan ylittävän hankintalain 25 § kynnysarvon.,','Kemin kaupunki','ANY',2,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056574','[\"45236119\"]