INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1022,'2026-056572','HILMA','OTHER','OPEN','Jokihelmisimpukan esiintymisen selvittäminen eDNA-menetelmällä Simojoen ja Hossanjoen alueilla','Metsähallitus Metsätalous Oy ostaa kokonaispalveluna jokihelmisimpukan (Margaritifera margaritifera) eli raakun esiintymisen selvittämistä virtavesistä ympäristö-DNA (eDNA) -menetelmällä. Selvitykset tulee toteuttaa lajispesifiseen PCR-pohjaiseen eDNA-analyysiin (qPCR tai dPCR) perustuen ja kohdistuvat alueisiin, joilla tullaan toteuttamaan virtavesikunnostuksia. Hankinta jakautuu kahteen osaan: Lapin alueen (Simojoen vesistö) ja Pohjanmaa–Kainuun alueen (Hossanjoen vesistö) selvityksiin. Tarjouspyynnön julkaisuhetkellä virtavesikunnostuskohteet olivat vielä suunnitteluvaiheessa. Tarjouspyynnön karttaliitteissä on esitetty Simojokeen ja Hossanjokeen laskevat valtion monikäyttömetsien purot, joista kunnostuskohteet tullaan valitsemaan. Kohteet varmistuvat kunnostussuunnittelun edetessä kesällä 2026, viimeistään elokuun lopussa 2026. Palvelun toteuttaja ottaa näytteet kunnostuskohteiden varmistumisen jälkeen syyskuun 2026 aikana. Selvityksen lopullinen raportti liitteineen tulee toimittaa tilaajalle viimeistään 26.1.2027., Simojoki ks. hankinnan kuvaus sekä hankintaa tai osaa koskevat lisätiedot, Hossanjoki ks. hankinnan kuvaus sekä hankintaa tai osaa koskevat lisätiedot,','Metsähallitus Metsätalous Oy','ANY',1,3,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056572','[\"73200000\"]','[\"edna\", \"jokihelmisimpukan\", \"esiintymisen\", \"menetelmällä\", \"simojoen\", \"hossanjoen\", \"metsähallitus\", \"m