INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1025,'2026-056567','HILMA','OTHER','OPEN','Kontiolahden kunnan ja sen tytäryhteisöjen tilintarkastuspalvelut tilikausille 2026 - 2029 + optiot tilikausille 2030 ja 2031','Kontiolahden kunnan ja sen tytäryhteisöjen tilintarkastuspalvelut tilikausille 2026 - 2029 + optiot tilikausille 2030 ja 2031 Hankinnan kohteena olivat kuntalain (410/2015) mukaiset hallinnon ja talouden tarkastuspalvelut Kontiolahden kunnalle sekä Kontiolahden kunnan tytäryhteisöjen tilintarkastuslain (1141/2015) mukaiset tilintarkastuspalvelut sopimuskaudelle 1.8.2026 - 31.7.2030 sekä optiona yhdelle (1) vuodelle + yhdelle (1) vuodelle. Hankinta koskee tilikausia 2026-2029 ja optiona tilikausia 2030 ja 2031. Palvelun tulee täyttää Euroopan unionin suoraan velvoittavien säädösten, Suomen lakien ja asetusten sekä viranomaisten antamat määräykset.,','Pohjois-Karjalan hankintatoimi','ANY',8,10,NULL,NULL,120000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056567','[\"79210000\"]','[\"kontiolahden\", \"tilikausille\", \"kunnan\", \"tytäryhteisöjen\", \"tilintarkastuspalvelut\", \"optiot\", \"mukaiset\", \"optiona\", \"yhdelle\", \"vuodelle\", \"tilikausia\", \"pohjois\", \"karjalan\", \"hankintatoimi\", \"hankinnan\", \"kohteena\", \"olivat\", \"kuntalain\", \"hallinnon\", \"talouden\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056567\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56567\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Kontiolahden kunnan ja sen tytäryhteisöjen tilintarkastuspalvelut tilikausille 2026 - 2029 + optio