INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1026,'2026-056565','HILMA','RFP','OPEN','Verkkosivustouudistus jäteyhtiöille','Verkkosivustouudistus jäteyhtiöille Pohjois-Karjalan hankintatoimi pyytää antamaan tarjouksen viiden kuntaomisteisen jätehuoltoyhtiön (Puhas Oy, Jätekukko Oy, Metsäsairila Oy, Ylä-Savon Jätehuolto Oy ja Ekokymppi) verkkopalvelukokonaisuuden toteutuksesta ja käyttöpalveluista WordPress-alustalle tämän tarjouspyynnön ja sen liitteiden mukaisesti sopimuskaudelle 1.10.2026 - 31.12.2028 + mahdollisuus jatkaa toistaiseksi voimassa olevana. Mikäli jokin tilaajataho irtisanoo sopimuksen viimeistään kuusi (6) kuukautta ennen sopimuskauden päättymistä, sopimus päättyy 31.12.2028. Jos sopimusta ei irtisanota sopimuskauden päättyessä, sopimus jatkuu toistaiseksi voimassa olevana kuuden (6) kuukauden irtisanomisajalla. Jokaisella tilaajataholla on oikeus irtisanoa oma sopimuksensa irtisanomisperusteiden mukaisesti ilman, että sillä on vaikutusta muihin tämän kilpailutuksen mukaisesti solmittuihin sopimuksiin. Tarjous on sitova ja se tulee laatia suomen kielellä. Hankintaprosessi on kokonaisuudessaan suomenkielinen.,','Pohjois-Karjalan hankintatoimi','ANY',5,10,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056565','[\"48220000\"]','[\"pohjois\", \"karjalan\", \"hankintatoimi\", \"mukaisesti\", \"verkkosivustouudistus\", \"jäteyhtiöille\", \"tämän\", \"toistaiseksi\", \"voimassa\", \"olevana\", \"sopimuskauden\", \"sopimus\", \"pyytää\", \"antamaan\", \"tarjouksen\", \"viiden\", \"kuntaomisteisen\", \"jätehuoltoyhtiön\", \"puhas\", \"jätekukko\"]',NULL,NULL,'[{\"url\": \"https