INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1027,'2026-056564','HILMA','RFI','OPEN','KUTSU MARKKINAVUOROPUHELUUN: tutkintotilaisuuksien järjestäminen','KUTSU MARKKINAVUOROPUHELUUN: tutkintotilaisuuksien järjestäminen Patentti- ja rekisterihallitus on käynnistänyt tutkintotilaisuuksien järjestämisen hankinnan valmistelun. Hankinnan kohteena ovat alustavasti Patentti- ja rekisterihallituksen tilintarkastajatutkintotilaisuudet ja teollisoikeusasiamieslautakunnan järjestämät asiamiestutkinnot. Hankinta sisältää palvelujen tuottamispaikan, tilajärjestelyt tutkinnoissa, tutkintotilaisuuksissa käytettävät laitteet ja tarvittavan henkilöstön ja palvelut. Tämän markkinakartoitusilmoituksen tarkoituksena on käynnistää markkinavuoropuhelu kutsumalla hankinnasta kiinnostuneet yritykset ilmoittautumaan markkinavuoropuheluun. MARKKINAVUOROPUHELU Markkinavuoropuhelu on tarkoitettu hankinnasta kiinnostuneille yrityksille. Markkinavuoropuhelussa yrityksille varataan mahdollisuus kommentoida hankintaan liittyviä luonnosmateriaaleja kirjallisesti. Hankinnan tavoiteaikataulu on seuraava: - Kirjallinen kommentointikierros hankinnasta kiinnostuneille yrityksille käynnistetään vko 42/2026 - Tarjouspyynnön julkaisu vko 45/2026 - Hankintapäätöksen tiedoksi saattaminen vko 50/2026 - Sopimuksen voimaantulo 1.1.2027 Hankintayksikkö varaa oikeuden kutsua hankinnasta kiinnostuneita yrityksiä kahdenvälisiin tapaamisiin. Mahdolliset tapaamiset järjestetään Teamsin välityksellä. ILMOITTAUTUMINEN Hankinnasta kiinnostuneita yrityksiä pyydetään ilmoittautumaan markkinavuoropuheluun alla olevalla verkkosivustolla. https://forms.cloud.microsoft/e/WgBJh5EW8G Ilmoittautuminen markkinavuoropuheluun kyseisen verkkosivuston kautta on mahdollista 25.9.2026 klo 12.00 asti. Ilmoittautuneiden henkilöiden henkilötietoja käytetään vain tämän hankinnan valmisteluun liittyviin yhteydenottoihin. MUUTA HUOMIOITAVAA Huomioittehan, että kyseessä on markkinakartoitusilmoitus, eikä tällä ilmoituksella pyydetä tarjouksia. Tässä ilmoituksessa esitetyt tiedot ovat alustavia ja saattavat muuttua hankinnan valmistelun edetessä. Markkinavuoropuheluiun osallistuminen tai osallistumatta jättäminen ei estä mahdolliseen hankintamenettelyyn osallistumista. Hankintayksikkö ei maksa korvausta markkinavuoropuheluun osallistumisesta.,','Patentti- ja rekisterihallitus','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056564','[\"75121000\"]','[\"markkinavuoropuheluun\", \"hankinnan\", \"hankinnasta\", \"tutkintotilaisuuksien\", \"patentti\", \"markkinavuoropuhelu\", \"yrityksille\", \"kutsu\", \"järjestäminen\", \"rekisterihallitus\", \"valmistelun\", \"ovat\", \"tämän\", \"ilmoittautumaan\", \"kiinnostuneille\", \"hankintayksikkö\", \"kiinnostuneita\", \"yrityksiä\", \"ilmoittautuminen\", \"käynnistänyt\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/prh?id=627260&tpk=c8802552-cd7a-47d4-af6c-deddfb605e4e\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056564\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56564\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"KUTSU MARKKINAVUOROPUHELUUN: tutkintotilaisuuksien järjestäminen\", \"titleSv\": \"\", \"cpvCodes\": \"75121000\", \"currency\": null, \"deadline\": \"2026-09-25T09:00:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Patentti- ja rekisterihallitus on käynnistänyt tutkintotilaisuuksien järjestämisen hankinnan valmistelun. \\n\\nHankinnan kohteena ovat alustavasti Patentti- ja rekisterihallituksen tilintarkastajatutkintotilaisuudet ja teollisoikeusasiamieslautakunnan järjestämät asiamiestutkinnot. Hankinta sisältää palvelujen tuottamispaikan, tilajärjestelyt tutkinnoissa, tutkintotilaisuuksissa käytettävät laitteet ja tarvittavan henkilöstön ja palvelut.\\n\\nTämän markkinakartoitusilmoituksen tarkoituksena on käynnistää markkinavuoropuhelu kutsumalla hankinnasta kiinnostuneet yritykset ilmoittautumaan markkinavuoropuheluun.\\n\\nMARKKINAVUOROPUHELU\\n\\nMarkkinavuoropuhelu on tarkoitettu hankinnasta kiinnostuneille yrityksille.\\n\\nMarkkinavuoropuhelussa yrityksille varataan mahdollisuus kommentoida hankintaan liittyviä luonnosmateriaaleja kirjallisesti.\\n\\nHankinnan tavoiteaikataulu on seuraava:\\n- Kirjallinen kommentointikierros hankinnasta kiinnostuneille yrityksille käynnistetään vko 42/2026\\n- Tarjouspyynnön julkaisu vko 45/2026\\n- Hankintapäätöksen tiedoksi saattaminen vko 50/2026\\n- Sopimuksen voimaantulo 1.1.2027\\n\\nHankintayksikkö varaa oikeuden kutsua hankinnasta kiinnostuneita yrityksiä kahdenvälisiin tapaamisiin. Mahdolliset tapaamiset järjestetään Teamsin välityksellä.\\n\\nILMOITTAUTUMINEN\\n\\nHankinnasta kiinnostuneita yrityksiä pyydetään ilmoittautumaan markkinavuoropuheluun alla olevalla verkkosivustolla.\\nhttps://forms.cloud.microsoft/e/WgBJh5EW8G\\n\\nIlmoittautuminen markkinavuoropuheluun kyseisen verkkosivuston kautta on mahdollista 25.9.2026 klo 12.00 asti. Ilmoittautuneiden henkilöiden henkilötietoja käytetään vain tämän hankinnan valmisteluun liittyviin yhteydenottoihin.\\n\\nMUUTA HUOMIOITAVAA\\n\\nHuomioittehan, että kyseessä on markkinakartoitusilmoitus, eikä tällä ilmoituksella pyydetä tarjouksia.\\n\\nTässä ilmoituksessa esitetyt tiedot ovat alustavia ja saattavat muuttua hankinnan valmistelun edetessä.\\n\\nMarkkinavuoropuheluiun osallistuminen tai osallistumatta jättäminen ei estä mahdolliseen hankintamenettelyyn osallistumista. Hankintayksikkö ei maksa korvausta markkina