INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1030,'2026-056552','HILMA','RFI','OPEN','TIETOPYYNTÖ Lokiarkkitehtuuri','TIETOPYYNTÖ Lokiarkkitehtuuri Pyydämme teitä toimittamaan vastauksenne tähän Lokiarkkitehtuurin hankintaa koskevaan tietopyyntöön. Tällä tietopyynnöllä haluamme kartoittaa toimittajien tarjontaa järjestelmistä, jotka tukevat Istekin ja Istekin asiakkaiden lokienhallintaa ja tarjoavat tarkoituksenmukaiset sekä kustannustehokkaat ratkaisut. Samalla pyrimme tutustumaan järjestelmiin liittyvien palvelujen markkinatilanteeseen, järjestelmän käyttöön mahdollisesti liittyviin tuotteisiin, sopimusehtoihin ja kaupallisiin ehtoihin kuten hinnoitteluun. Tietopyynnön vastauksien perusteella voidaan järjestää markkinavuoropuhelutilaisuuksia, joissa toimittajat voivat esitellä omia palveluita, tuotteita ja vaihtoehtojaan kilpailutuksen kohteen toteutumiselle. Lokiarkkitehtuuri on DPS:n Tietoturvapalveluiden teknologiaratkaisut 2026-2034 sisäinen kilpailutus, joten varsinaiseen tarjouspyyntövaiheeseen osallistuminen vaatii liittymisen DPS:ään Tietoturvapalveluiden teknologiaratkaisut. HANKINNAN KUVAUS Tarkemmat tiedot löytyvät tietopyynnön liitteeltä 1 Hankinnan kohteen kuvaus. Hankintaa koskevat kysymykset on esitetty liitteellä 2 Kysymykset. TIETOPYYNTÖÖN VASTAAMINEN Tietopyyntöön tulee vastata ti 22.9. klo 12:00 mennessä Tarjouspalvelu.fi -portaalin kautta. Vastauksen liitteenä tulee toimittaa täytettynä liite ”Kysymykset”. Vastaukset tulee toimittaa kyseisellä liitteellä suomen kielellä, jotta niiden käsittely on mahdollisimman sujuvaa. Halutessanne voitte liittää mukaan myös suomen- tai englanninkielisiä esitteitä tai muuta materiaalia, joka tukee vastauksenne sisältöä. Pyydämme ilmoittamaan selkeästi, sisältääkö annetut tiedot liikesalaisuuksia. Saatujen vastausten pohjalta Istekki voi valita harkintansa perusteella tarjoajia esittelemään palveluitaan mahdollisessa markkinavuoropuhelutapaamisessa. Mahdollinen esittely toteutetaan oletusarvoisesti noin yhden (1) tunnin Teams-tapaamisena Istekin ja kyseisen toimittajan välillä. Mahdolliset markkinavuoropuhelutapaamiset pyritään järjestämään ti 29.9. ja ke 30.9. Kaikki tietopyyntöön tulleet vastaukset otetaan huomioon tarjouspyynnön valmistelussa, ja ne ovat tärkeä osa kokonaisuuden hahmottamista. Jos markkinavuoropuhelutilaisuuksia järjestetään, ne toteutetaan suomen kielellä. Istekki ilmoittaa tilaisuuksiin osallistuville yrityksille tarkemmat aikataulut sekä Teams‑kokouslinkin myöhemmin. Huomioithan, että tässä tietopyynnössä esitetyt tiedot, kuvaukset ja arviot kilpailutuksen julkaisuajankohdasta ovat vasta alustavia ja suuntaa antavia. Lopulliset aikataulut tarkentuvat valmistelun edetessä. Tietopyyntöön vastaaminen on vapaaehtoista, eikä se ole edellytys mahdolliseen tarjouskilpailuun osallistumiselle tai sido Istekkiä julkaisemaan tarjouskilpailua. Tietopyyntöön vastaamisesta tai mahdollisiin esittelytilaisuuksiin osallistumisesta ei makseta erillistä korvausta. Kyseessä on tietopyyntö — ei ennakkoilmoitus, hankintailmoitus tai tarjouspyyntö.,','Istekki Oy','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056552','[\"72000000\", \"48000000\", \"48730000\", \"72212730\"]','[\"tietopyyntöön\", \"istekki\", \"tietopyyntö\", \"lokiarkkitehtuuri\", \"istekin\", \"tiedot\", \"kysymykset\", \"tulee\", \"suomen\", \"pyydämme\", \"vastauksenne\", \"hankintaa\", \"tietopyynnön\", \"perusteella\", \"markkinavuoropuhelutilaisuuksia\", \"kilpailutuksen\", \"kohteen\", \"tietoturvapalveluiden\", \"teknologiaratkaisut\", \"hankinnan\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/iste