INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1031,'2026-056545','HILMA','RFI','OPEN','Tietopyyntö / Markkinakartoitus: Plasmasolutautien diagnostiikka ja seuranta -laitteisto perustuen polyklonaalisten vasta-aineiden käyttöön','Tietopyyntö / Markkinakartoitus: Plasmasolutautien diagnostiikka ja seuranta -laitteisto perustuen polyklonaalisten vasta-aineiden käyttöön HUOM! TÄMÄ EI OLE HANKINTAILMOITUS TAI TARJOUSPYYNTÖ VAAN TIETOPYYNTÖ MARKKINAKARTOITUSTA VARTEN. Tietopyynnön tarkoituksena on kartoittaa markkinoilla olevia ratkaisuja ja saada kattavasti niitä koskevaa tietoa, jotta valmisteilla oleva hankinta voidaan toteuttaa mahdollisimman tarkoituksenmukaisesti. Tietopyyntöön vastaaminen ei ole edellytys kilpailutukseen osallistumiselle eikä vaikuta tarjoajan asemaan siinä. Tietopyynnössä esitetyt seikat ovat alustavia ja saattavat muuttua hankinnan valmistelun edetessä. NordLab hyvinvointiyhtymä valmistelee plasmasolutautien diagnostiikkaan ja seurantaan liittyvän analytiikan mahdollista hankintaa. Hankinnan suunnittelun tueksi NordLab toteuttaa tämän tietopyynnön kartoittaakseen markkinoilla saatavilla olevia ratkaisuja, niiden ominaisuuksia, toiminnallisuuksia, teknisiä toteutusvaihtoehtoja sekä toimittajien näkemyksiä hankinnan toteuttamisesta. Tietopyynnön tavoitteena on saada riittävästi tietoa hankinnan kohteen määrittelyä, teknisten vaatimusten laatimista, hankinnan toteutustavan arviointia sekä kustannusvaikutusten selvittämistä varten. Lisäksi tavoitteena on varmistaa, että mahdollinen tuleva hankinta valmistellaan tarkoituksenmukaisesti ja markkinoilla tarjolla olevat ratkaisut huomioiden. Tietopyynnön kohteena ovat erityisesti: S-IgLc-V -tutkimukseen sekä siihen liittyviin osatutkimuksiin soveltuvat analyysimenetelmät ja analyysilaitteet analytiikassa käytettävät reagenssit laitteistojen käyttöönotto-, huolto- ja tukipalvelut mahdolliset ohjelmistoratkaisut sekä muut kokonaisuuteen liittyvät palvelut ja tarvikkeet. Vuosittainen tutkimusmäärä on tällä hetkellä noin 5 200 näytettä. Toimittajia pyydetään kuvaamaan, millaisiin näytemääriin vastauksen ratkaisu soveltuu ja millaiset kapasiteetti- ja laajennusmahdollisuudet siihen liittyvät.,','Nordlab hyvinvointiyhtymä','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056545','[\"38000000\", \"33696500\"]','[\"hankinnan\", \"tietopyynnön\", \"nordlab\", \"tietopyyntö\", \"plasmasolutautien\", \"markkinoilla\", \"hyvinvointiyhtymä\", \"markkinakartoitus\", \"diagnostiikka\", \"seuranta\", \"laitteisto\", \"perustuen\", \"polyklonaalisten\", \"vasta\", \"aineiden\", \"käyttöön\", \"varten\", \"olevia\", \"ratkaisuja\", \"saada\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/nordlab?id=626078&tpk=fa9fdb7f-5034-46b8-82f7-ff1c843183ab\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056545\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56545\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Tietopyyntö / Markkinakartoitus: Plasmasolutautien diagnostiikka ja seuranta -laitteisto perustuen polyklonaalisten vasta-aineiden käyttöön\", \"titleSv\": \"\", \"cpvCodes\": \"38000000 33696500\", \"currency\": null, \"deadline\": \"2026-09-23T09:00:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"HUOM! TÄMÄ EI OLE HANKINTAILMOITUS TAI TARJOUSPYYNTÖ VAAN TIETOPYYNTÖ MARKKINAKARTOITUSTA VARTEN.\\n\\nTietopyynnön tarkoituksena on kartoittaa markkinoilla olevia ratkaisuja ja saada kattavasti niitä kosk