INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1033,'2026-056537','HILMA','RFP','OPEN','Miilin liikuntahalli, AV - hankinta','Miilin liikuntahalli, AV - hankinta Hankinnan tavoitteena on hankkia tilaajan käyttöön palveluntuottaja, jolla on parhaat edellytykset toteuttaa kohteen AV - hankinta yhteistyössä tilaajan, käyttäjän, pääurakoitsijan sekä suunnittelijoiden ja konsulttien kanssa. Hankinta koskee tarjouspyynnön liitteenä olevien AV-laitteiden hankintaa ja asennusta. Hankinnassa noudatetaan tässä hankintailmoituksessa määritettyjä sopimusehtoja ja JYSE 2025 TAVARAT julkisten hankintojen yleisiä sopimusehtoja tavarahankinnoissa. AV-laitteet hankitaan ja asennetaan rakenteillaan olevaan liikuntahalliin ja koulun olemassa olevaan saneerattavaan liikuntasaliin. Liikuntahallin rakennustyöt ja liikuntasalin saneeraustyöt valmistuvat 12/2026 mennessä. Hankittavien AV-laitteiden toimitussisältöön kuuluu laitteiden asentaminen käyttökuntoon, jätteiden poisto ja käyttäjien käytönopastus asennettujen tuotteiden käyttöön. Hankkeen osoite on Söderkullan Koulutie 7, 01150 Söderkulla.,','Sipoon kunta','ANY',2,4,NULL,NULL,160000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056537','[\"32321200\", \"50340000\", \"51313000\", \"51314000\"]','[\"hankinta\", \"laitteiden\", \"miilin\", \"liikuntahalli\", \"tilaajan\", \"käyttöön\", \"sopimusehtoja\", \"olevaan\", \"hankinnan\", \"tavoitteena\", \"hankkia\", \"palveluntuottaja\", \"jolla\", \"parhaat\", \"edellytykset\", \"toteuttaa\", \"kohteen\", \"yhteistyössä\", \"käyttäjän\", \"pääurakoitsijan\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/sipoo?id=62