INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1035,'2026-056533','HILMA','RFP','OPEN','Katselutasanteen ja portaiden suunnittelu Astuvansalmen kalliomaalausten edustalle','Katselutasanteen ja portaiden suunnittelu Astuvansalmen kalliomaalausten edustalle Työ käsittää Mikkelin Ristiinassa sijaitsevan Astuvansalmen kalliomaalauskentän katselutasanteen ja portaan suunnittelun tarjouspyynnön (MH 4193/2026) ja sen liitteenä olevien tarjouspyyntöasiakirjojen mukaisessa laajuudessa. Suunnittelutyön toteuttajaksi valitaan soveltuvuusvaatimukset täyttävä tarjoaja, joka on jättänyt hinnaltaan halvimman tarjouspyynnön mukaisen tarjouksen. Suunnittelutehtävä edellyttää sekä rakennesuunnitteluosaamista että arkkitehtonista osaamista. Tehtävä painottuu enemmän rakennesuunnitteluratkaisuihin. Suunnitelman tulee sisältää urakoinnin edellyttämät asiakirjat toimenpiteiden toteutuksen ja urakan kilpailutuksen edellyttämällä tasolla. Katselutasanteen toteutus kilpailutetaan tässä hankinnassa tuotettavalla aineistolla välittömästi sen valmistuttua ja tasanne toteutetaan paikalleen vuoden 2027 aikana. Suunnittelukokonaisuus, sen laajuus, määritelmät, vaatimukset ja aikataulu on esitetty seikkaperäisemmin tarjouspyynnön liitteenä olevassa aineistossa (Liitteet 1; 1.1; 1.2; 1.3) . Tarjoajan tulee tutustua aineistoihin huolellisesti ennen tarjouksen jättämistä. Kallio maalauksineen, sekä sitä ympäröivä ranta-alue on suojeltu Muinaismuistolain nojalla kiinteänä muinaisjäännöksenä. Kohde on arvotettu Valtakunnallisesti arvokkaaksi arkeologiseksi kohteeksi (VARK), ja lisäksi se sijaitsee Valtakunnallisesti merkittävässä rakennetussa kulttuuriympäristössä (RKY, Toijolan kylän historialliset kohteet), sekä Valtakunnallisesti arvokkaalla maisema-alueella (VAMA, Ristiinan veskansan kulttuurimaisema). Kalliomaalauskenttä kuuluu myös Saimaa Unesco Global Geoparkiin, ja se on yhtenä kahdesta suomalaisesta kohteesta sisällytetty Euroopan neuvoston esihistoriallisten kalliotaidepolkujen verkostoon ( The Prehistoric Rock Art Trails). Lisäkysymykset tulee esittää järjestelmässä 18.9.2026 kello 12.00 mennessä. Tarjous tulee jättää 30.9.2026 klo 12.00 mennessä. Sopimus allekirjoitetaan hankintapäätöksen valitusajan umpeuduttua, noin viikolla 41. Sopimus allekirjoitetaan lähtökohtaisesti sähköisesti. Töiden tarkasta toteutusajankohdasta sovitaan sopimuksen selonottoneuvotteluiden yhteydessä. Tarjoajan oletetaan esittävän aikataulua työn etenemiselle selonottoneuvotteluiden yhteydessä. Tarjoajan tulee varautua osallistumaan selonottoneuvotteluihin etäyhteydellä. Tarjoajan tulee täyttää tarjouspyynnön soveltuvuusvaatimukset. Tarjouksen jättämisen yhteydessä tulee täyttää edellytetyt referenssit. Referenssit eivät vaikuta vertailuun, vaan koskevat tarjoajan soveltuvuutta eli kykyä suoriutua hankinnan kohteena olevan tehtävän toteuttamisesta. Mikäli referenssivaatimukset eivät täyty, tarjous hylätään.,','Metsähallitus','LARGE',5,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056533','[\"71220000\"]','[\"tulee\", \"tarjoajan\", \"katselutasanteen\", \"tarjouspyynnön\", \"astuvansalmen\", \"tarjouksen\", \"valtakunnallisesti\", \"yhteydessä\", \"portaiden\", \"suunnittelu\", \"kalliomaalausten\", \"edustalle\", \"liitteenä\", \"soveltuvuusvaatimukset\", \"mennessä\", \"tarjous\", \"sopimus\", \"allekirjoitetaan\", \"selonottoneuvotteluiden\", \"täyttää\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/metsahallitus?id=625631&tpk=4d3fc63f-98ce-44f5-8cb8-cb5b43f03844\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056533\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56533\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Katselutasanteen ja portaiden suunnittelu Astuvansalmen kalliomaalausten edustalle\", \"titleSv\": \"\", \"cpvCodes\": \"71220000\", \"currency\": null, \"deadline\": \"2026-09-30T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"Työ käsittää Mikkelin Ristiinassa sijaitsevan Astuvansalmen kalliomaalauskentän katselutasanteen ja portaan suunnittelun tarjouspyynnön (MH 4193/2026) ja sen liitteenä olevien tarjouspyyntöasiakirjojen mukaisessa laajuudessa.\\n\\nSuunnittelutyön toteuttajaksi valitaan soveltuvuusvaatimukset täyttävä tarjoaja, joka on jättänyt hinnaltaan halvimman tarjouspyynnön mukaisen tarjouksen.   \\n\\nSuunnittelutehtävä edellyttää sekä rakennesuunnitteluosaamista että arkkitehtonista osaamista. Tehtävä painottuu enemmän rakennesuunnitteluratkaisuihin. Suunnitelman tulee sisältää urakoinnin edellyttämät asiakirjat toimenpiteiden toteutuksen ja urakan kilpailutuksen edellyttämällä tasolla. Katselutasanteen toteutus kilpailutetaan tässä hankinnassa tuotettavalla aineistolla välittömästi sen valmistuttua ja tasanne toteutetaan paikalleen vuoden 2027 aikana.  \\n\\nSuunnittelukokonaisuus, sen laajuus, määritelmät, vaatimukset ja aikataulu on esitetty seikkaperäisemmin tarjouspyynnön liitteenä olevassa aineistossa (Liitteet 1; 1.1; 1.2; 1.3) . Tarjoajan tulee tutustua aineistoihin huolellisesti ennen tarjouksen jättämistä. \\n\\nKallio maalauksineen, sekä sitä ympäröivä ranta-alue on suojeltu Muinaismuistolain nojalla kiinteänä muinaisjäännöksenä. Kohde on arvotettu Valtakunnallisesti arvokkaaksi arkeologiseksi kohteeksi (VARK), ja lisäksi se sijaitsee Valtakunnallisesti merkittävässä rakennetussa kulttuuriympäristössä (RKY, Toijolan kylän historialliset kohteet), sekä Valtakunnallisesti arvokkaalla maisema-alueella (VAMA, Ristiinan veskansan kulttuurimaisema). Kalliomaalauskenttä kuuluu myös Saimaa Unesco Global Geoparkiin, ja se on yhtenä kahdesta suomalaisesta kohteesta sisällytetty Euroopan neuvoston esihistoriallisten kalliotaidepolkujen verkostoon (  The Prehistoric Rock Art Trails). \\n\\nLisäkysymykset tulee esittää järjestelmässä 18.9.2026 kello 12.00 mennessä. \\n\\nTarjous tulee jättää 30.9.2026 klo 12.00 mennessä. Sopimus allekirjoitetaan hankintapäätöksen valitusajan umpeuduttua, noin viikolla 41. Sopimus allekirjoitetaan lähtökohtaisesti sähköisesti. \\n\\nTöiden tarkasta toteutusajankohdasta sovitaan sopimuksen selonottoneuvotteluiden yhteydessä. Tarjoajan oletetaan esittävän aikataulua työn etenemiselle selonottoneuvotteluiden yhteydessä. Tarjoajan tulee varautua osallistumaan selonottoneuvotteluihin etäyhteydellä. Tarjoajan tulee täyttää tarjouspyynnön soveltuvuusvaatimukset. Tarjouksen jättämisen yhteydessä tulee täyttää edellytetyt referenssit. Referenssit eivät vaikuta vertailuun, vaan koskevat tarjoajan soveltuvuutta eli kykyä suoriutua hankinnan kohteena olevan tehtävän toteuttamisesta. Mikäli referenssivaatimukset eivät täyty, tarjous hylätään.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-09-30T09:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": true, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndu