INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1036,'2026-056530','HILMA','RFP','OPEN','Pyhäkosken uittokanavan (uittokourun) kunnostus, Mäntyharju','Pyhäkosken uittokanavan (uittokourun) kunnostus, Mäntyharju Kaakkois-Suomen elinvoimakeskus pyytää kokonaishintaurakkatarjouksen Pyhäkosken uittokanavan (uittokourun) kunnostuksesta. Rakennuskohde sijaitsee Mäntyharjun kunnassa. Lähin osoite kohteelle on Pyhäkosken uittokanavan silta 729 52700 Mäntyharju. Uittokanava sijaistee Pyhäkosken venesulun jatkeena. Urakka sisältää noin 80 metriä pitkän ja 4-5 metriä leveän uittokourun kunnostuksen siten, että nykyisten teräslevyjen päälle ruuvataan uudet teräslevyt. Työ tehdään kuivatyönä ja urakkaan kuuluu työpadon rakentaminen. Rakennussuunnitelmat on laatinut FCG Rakennettu Ympäristö Oy. Kokonaishintaurakkaan täytyy sisältyä mm. kaikki materiaalit, hankinnat, työt ja kuljetukset, jotka ovat välttämättömiä töiden valmiiksi saattamiseksi. Lisäksi tarjoajan on huomioitava urakkaan liittyvät viranomaisvaatimukset ja määräykset, kuten mm. viranomaisten julkaisemat viimeisimmät standardien painokset, asetukset, käsikirjat, ohjeet ja lupaehdot sekä työsuojeluviranomaisen julkaisemat määräykset ja säännöt. Kunnostusurakan tarkempi määrittely on esitetty tarjouspyyntöaineiston liitetiedostossa (Julkaisun asiakirjat). Hankintayksikkö edellyttää, että tarjoaja on käynyt tutustumassa kohteeseen ennen tarjouksen jättämistä. Hankintayksikkö varaa oikeuden neuvotella kaikista kaupallisista ja teknisistä edellytyksistä tarjouksessa, mikäli hankintayksikön olosuhteet, tarpeet tai suunnitteluperusteet muuttuvat hankintakilpailun aikana. Hankintayksikkö varaa oikeuden hylätä tarjouksen julkisista hankinnoista annetun lain ja oikeuskäytännön mukaisilla perusteilla,','Työllisyys-, kehittämis- ja hallintokeskus','ANY',2,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056530','[\"45200000\"]','[\"pyhäkosken\", \"uittokanavan\", \"uittokourun\", \"mäntyharju\", \"hankintayksikkö\", \"kunnostus\", \"metriä\", \"urakkaan\", \"määräykset\", \"julkaisemat\", \"tarjouksen\", \"varaa\", \"oikeuden\", \"työllisyys\", \"kehittämis\", \"hallintokeskus\", \"kaakkois\", \"suomen\", \"elinvoimakeskus\", \"pyytää\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/kehakeskus?id=626000&tpk=7baece5f-5b07-421f-8b86-f5ba9eb3b0f0\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056530\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56530\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Pyhäkosken uittokanavan (uittokourun) kunnostus, Mäntyharju\", \"titleSv\": \"\", \"cpvCodes\": \"45200000\", \"currency\": null, \"deadline\": \"2026-09-30T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1DA\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Kaakkois-Suomen elinvoimakeskus pyytää kokonaishintaurakkatarjouksen Pyhäkosken uittokanavan (uittokourun) kunnostuksesta. Rakennuskohde sijaitsee Mäntyharjun kunnassa. Lähin osoite kohteelle on Pyhäkosken uittokanavan silta 729 52700 Mäntyharju. Uittokanava sijaistee Pyhäkosken venesulun jatkeena.\\n\\nUrakka sisältää noin 80 metriä pitkän ja 4-5 metriä leveän uittokourun kunnostuksen siten, että nykyisten teräslevyjen päälle ruuvataan uudet teräslevyt. Työ tehdään kuivatyönä ja urakkaan kuuluu työpadon rakentaminen.\\n\\nRakennussuunnitelmat on laatinut FCG Rakennettu Ympäristö Oy.\\n\\nKokonaishintaurakkaan täytyy sisältyä mm. kaikki materiaalit, hankinnat, työt ja kuljetukset, jotka ovat välttämättömiä