INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1038,'2026-056526','HILMA','RFP','OPEN','Liminganjoen ja ruotsinojan valuma-alueen kunnostus ja vesienhallinnan kehittäminen','Liminganjoen ja ruotsinojan valuma-alueen kunnostus ja vesienhallinnan kehittäminen Hankinta liittyy VESI-hankkeeseen, jonka tarkoitus on Liminganjoen ja Ruotsinojan valuma-alueen kunnostus ja vesienhallinnan kehittäminen. Hankkeen toteutusaika on 28.11.2025–31.8.2027. Hankkeen tavoitteena on parantaa Liminganjoen ja Ruotsinojan ekologista tilaa ja vesienhallintaa kokonaisuutena. Liminganjoki on luokiteltu ekologiselta tilaltaan välttäväksi. Valuma-alueilta tarvitaan ajantasainen selvitys kuormituksesta, vesienhallinnan kehittämistarpeista, kunnostusmahdollisuuksista sekä toimenpiteiden vaikuttavuudesta ja toteuttamiskelpoisuudesta.,','Limingan kunta','ANY',10,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056526','[\"90710000\"]','[\"liminganjoen\", \"ruotsinojan\", \"valuma\", \"vesienhallinnan\", \"alueen\", \"kunnostus\", \"kehittäminen\", \"hankkeen\", \"limingan\", \"kunta\", \"hankinta\", \"liittyy\", \"vesi\", \"hankkeeseen\", \"jonka\", \"tarkoitus\", \"toteutusaika\", \"tavoitteena\", \"parantaa\", \"ekologista\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/liminka?id=627144&tpk=e0d8d040-0c20-470f-8497-f0ebea65cd2e\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056526\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56526\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Liminganjoen ja ruotsinojan valuma-alueen kunnostus