INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1039,'2026-056524','HILMA','RFP','OPEN','Peltosaaren puistokokonaisuuden toteutus','Peltosaaren puistokokonaisuuden toteutus Riihimäen kaupunki (jäljempänä \"tilaaja\" tai \"hankintayksikkö\") pyytää tarjoustanne Riihimäen kaupungin Peltosaaren puistokokonaisuuden toteutuksesta liitteenä olevien tarjouspyyntöasiakirjojen mukaisesti. Rakennuskohde sijaitsee Riihimäellä Peltosaaren kaupunginosassa. Urakka muodostuu Peltosaaren puistokokonaisuuden toteutuksesta sekä Telluskadun perusparannuksesta suunnitelma-asiakirjojen mukaisesti. Hankkeen tavoitteena on toteuttaa Peltosaareen viihtyisä, toiminnallinen ja yhteisöllinen puistokokonaisuus, joka palvelee kaikenikäisiä käyttäjiä. Tavoitteena on luoda turvallinen ja esteetön kaupunkipuisto, jossa on mahdollisuus sekä oleskeluun että aktiiviseen tekemiseen. Telluskadun perusparannuksen tavoitteena on yhtenäisen ilmeen luominen Peltosaareen sekä Telluskadun kunnon parantaminen ja liikennejärjestelyjen selkeyttäminen. Telluskatu jää jalankulun ja pyöräilyn käyttöön ja se toteutetaan yleisilmeeltään puistoalueeseen ja aukioon yhteensopivaksi. Sopimuskausi alkaa alustavasti tammikuussa 2027 ja töiden tulee olla valmiit viimeistään lokakuun 2027 loppuun mennessä. Tässä hankinnassa kokonaistaloudellisen edullisuuden perusteena käytetään halvinta hintaa. Tarjouspyynnössä laadulle asetut vähimmäisvaatimukset mahdollistavat vertailun ainoastaan hinnalla. Töiden tarkempi laajuus ja sisältö käy ilmi urakkaohjelmasta sekä muista tarjouspyyntöasiakirjoista ja -suunnitelmista. Kaikki hankintaa koskevat vaatimukset on esitetty tarjouspyynnössä ja sen liitteissä.,','Riihimäen kaupunki','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056524','[\"45000000\"]','[\"peltosaaren\", \"puistokokonaisuuden\", \"riihimäen\", \"kaupunki\", \"telluskadun\", \"tavoitteena\", \"toteutus\", \"toteutuksesta\", \"mukaisesti\", \"peltosaareen\", \"töiden\", \"tarjouspyynnössä\", \"jäljempänä\", \"tilaaja\", \"hankintayksikkö\", \"pyytää\", \"tarjoustanne\", \"kaupungin\", \"liitteenä\", \"olevien\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/riihimaki?id=594924&tpk=6a510ca6-6ab3-4b59-b895-775269b58201\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056524\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56524\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Peltosaaren puistokokonaisuuden toteutus\", \"titleSv\": \"\", \"cpvCodes\": \"45000000\", \"currency\": null, \"deadline\": \"2026-10-06T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": true, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"Riihimäen kaupunki (jäljempänä \\\"tilaaja\\\" tai \\\"hankintayksikkö\\\") pyytää tarjoustanne Riihimäen kaupungin Peltosaaren puistokokonaisuuden toteutuksesta liitteenä olevien tarjouspyyntöasiakirjojen mukaisesti. Rakennuskohde sijaitsee Riihimäellä Peltosaaren kaupunginosassa. \\n\\nUrakka muodostuu Peltosaaren puistokokonaisuuden toteutuksesta sekä Telluskadun perusparannuksesta suunnitelma-asiakirjojen mukaisesti. Hankkeen tavoitteena on toteuttaa Peltosaareen viihtyisä, toiminnallinen ja yhteisöllinen puistokokonaisuus, joka palvelee kaikenikäisiä käyttäjiä. Tavoitteena on luoda turvallinen ja esteetön kaupunkipuisto, jossa on mahdollisuus sekä oleskeluun että aktiiviseen tekemiseen. Telluskadun perusparannuksen tavoitteena on yhtenäisen ilmeen luominen Peltosaareen sekä Telluskadun kunnon parantaminen ja liikennejärjestelyjen selkeyttäminen. Telluskatu jää jalankulun ja pyöräilyn käyttöön ja se toteutetaan yleisilmeeltään puistoalueeseen ja aukioon yhteensopivaksi.\\n\\nSopimuskausi alkaa alustavasti tammikuussa 2027 ja töiden tulee olla valmiit viimeistään lokakuun 2027 loppuun mennessä.\\n\\nTässä hankinnassa kokonaistaloudellisen edullisuuden perusteena käytetään halvinta hintaa. Tarjouspyynnössä laadulle asetut vähimmäisvaatimukset mahdollistavat vertailun ainoastaan hinnalla.\\n\\nTöiden tarkempi laajuus ja sisältö käy ilmi urakkaohjelmasta sekä muista tarjouspyyntöasiakirjoista ja -suunnitelmista. Kaikki hankintaa koskevat vaatimukset on esitetty tarjouspyynnössä ja sen liitteissä.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-10-06T09:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"works\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": true, \"listedGreenCriteriaUsed\": true, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": true, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"E