INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1043,'2026-056501','HILMA','RFP','OPEN','Ruokatuotteet','Ruokatuotteet Hankinnan kohteena on Helsingin kaupungin palvelukeskusliikelaitoksen (myöhemmin Palvelukeskus Helsinki tai tilaaja) ruoka- ja leipomotuotteet Helsingin kouluja, päiväkoteja ja hoitoalaa varten. Tarkempi hankinnan kuvaus tarjouspyynnössä ja sen liitteissä. Hankinta koostuu muun muassa seuraavista tuoteryhmistä: - Kala-, kasvis-, liha- ja hybridikappaletuotteet - Gluteenittomat tuotteet - Joululaatikot - Leivonnaiset - Kiusaukset ja laatikot - Erityisruokavalio tuotteet Jokaiselle tuotteelle valitaan yksi toimittaja. Tässä hankinnassa tyhjät rivit on sallittu, eli tarjoaja valitsee mitä tuotteita (rivejä) tämä tarjoaa. Hankintayksikkö vertailee tarjotut tuotteet rivikohtaisesti. Tarjoaja ei saa tarjota täysin samaa tuotetta kuin yhdelle riville. Mikäli tarjoaja tarjoaa samaa tuotetta enemmän kuin yhdelle riville, hylätään nämä tarjoukset tarjouspyynnön vastaisina. Tarjoaja saa jättää useamman tarjouksen samalle riville, jos tarjottavat tuotteet eroavat toisistaan tuotteiden ominaisuuksien osalta. Tällöin tarjoaja täyttää tarjoamiensa saman rivin tuotteiden tiedot erillisille hankintaohjelmille ja liittää ne tarjouksensa liitteeksi. Hankittavat tuotenimikkeet, tuotenimikkeiden lukumäärät, alustava käyttöönoton aikataulu ja tuotteiden toimituspaikat ovat tilaajan esittämiä arvioita neljälle (4) vuodelle. Tilaaja ei sitoudu mihinkään tilausmääriin. Mikäli tuotteiden tilausmäärät tai toimituspaikkojen määrät muuttuvat sopimuskauden aikana, ei sillä saa olla vaikutusta tarjoajan tarjouksessaan antamaan hinnoitteluun. Hinnanmuutosehdot on kuvattu hankintasopimuksessa, joka on tämän tarjouspyynnön liitteenä.,','Helsingin kaupungin palvelukeskusliikelaitos','ANY',1,4,NULL,NULL,4100000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056501','[\"15000000\", \"15130000\", \"15800000\", \"15810000\", \"15882000\", \"15894000\"]','[\"tarjoaja\", \"tuotteet\", \"tuotteiden\", \"helsingin\", \"riville\", \"ruokatuotteet\", \"hankinnan\", \"kaupungin\", \"tilaaja\", \"tarjoaa\", \"samaa\", \"tuotetta\", \"yhdelle\", \"mikäli\", \"tarjouspyynnön\", \"kohteena\", \"palvelukeskusliikelaitoksen\", \"myöhemmin\", \"palvelukeskus\", \"helsinki\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/helpalvelukeskus?id=618662&tpk=67b64098-e435-4716-9a1a-fa52741bfa53\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056501\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56501\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Ruokatuotteet\", \"titleSv\": \"\", \"cpvCodes\": \"15000000 15130000 15800000 15810000 15882000 15894000\", \"currency\": \"EUR\", \"deadline\": \"2026-10-09T09:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"\", \"titleOther\": \"\", \"biodiversity\": true, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"Hankinnan kohteena on Helsingin kaupungin palvelukeskusliikelaitoksen (myöhemmin Palvelukeskus Helsinki tai tilaaja) ruoka- ja leipomotuotteet Helsingin kouluja, päiväkoteja ja hoitoalaa varten. Tarkempi hankinnan kuvaus tarjouspyynnössä ja sen liitteissä.\\n\\nHankinta koostuu muun muassa seuraavista tuoteryhmistä:\\n- Kala-, kasvis-, liha- ja hybridikappaletuotteet\\n- Gluteenittomat tuotteet\\n- Joululaatikot\\n- Leivonnaiset\\n- Kiusaukset ja laatikot\\n- Erityisruokavalio tuotteet\\n\\nJokaiselle tuotteelle valitaan yksi toimittaja. Tässä hankinnassa tyhjät rivit on sallittu, eli tarjoaja valitsee mitä tuotteita (rivejä) tämä tarjoaa. Hankintayksikkö vertailee tarjotut tuotteet rivikohtaisesti. Tarjoaja ei saa tarjota täysin samaa tuotetta kuin yhdelle riville. Mikäli tarjoaja tarjoaa samaa tuotetta enemmän kuin yhdelle riville, hylätään nämä tarjoukset tarjouspyynnön vastaisina. Tarjoaja saa jättää useamman tarjouksen samalle riville, jos tarjottavat tuotteet eroavat toisistaan tuotteiden ominaisuuksien osalta. Tällöin tarjoaja täyttää tarjoamiensa saman rivin tuotteiden tiedot erillisille hankintaohjelmille ja liittää ne tarjouksensa liitteeksi.\\n\\nHankittavat tuotenimikkeet, tuotenimikkeiden lukumäärät, alustava käyttöönoton aikataulu ja tuotteiden toimituspaikat ovat tilaajan esittämiä arvioita neljälle (4) vuodelle. Tilaaja ei sitoudu mihinkään tilausmääriin. Mikäli tuotteiden tilausmäärät tai toimituspaikkojen määrät muuttuvat sopimuskauden aikana, ei sillä saa olla vaikutusta tarjoajan tarjouksessaan antamaan hinnoitteluun. Hinnanmuutosehdot on kuvattu hankintasopimuksessa, joka on tämän tarjouspyynnön liitteenä.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": 4100000.0, \"expirationDate\": \"2026-10-09T09:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": true, \"employmentCondition\": false, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": true, \"lotResultTotalAmount\": null, \"justWorkingConditions\": true, \"listedGreenCriteriaUsed\": true, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": true, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharin