INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1044,'2026-056500','HILMA','RFP','OPEN','Invasiiviset kardiologiset tarvikkeet 2','HUS-yhtymä pyytää tarjouksia invasiivisista kardiologisista tarvikkeista. Hankinta on jaettu 14 osa-alueeseen. Hankinnan osa-alueet sekä tarjouskilpailua koskevat tuotteet ja vaatimukset on kuvattu tarkemmin liitteessä 1. Tuoteliite HUS 266-2026. Hankinnan kohteena ovat mm.: - synnynnäisten sydänvikojen kardiologiset tarvikkeet - sulkulaitteet ja plugit - isot valvuloplastiakatetrit. Osatarjoukset ovat sallittuja. Tarjoaja voi jättää tarjouksen yhteen tai useampaan osa-alueeseen. Osatarjoukset eivät ole sallittuja osa-alueiden sisällä. Rinnakkaisia tarjouksia voi antaa kaksi (2) kappaletta. Tarjoaja voi antaa siis yhteensä 3 eri tarjousta. Rinnakkainen tarjous on aina oma, ERILLINEN, tarjous. Hankinnan kohteeseen sisältyvät myös tarjottuihin tuotteisiin liittyvät lisätuotteet kuten lisäkoot ja -tarvikkeet, jotka ilmoitetaan liitteessä 1. välilehdellä Kaikki koot ja mallit. Sopimuskaudella voidaan lisäksi hankkia hankinnan ennakoidun arvon mukaisesti sopimuksen kohteena oleviin tuoteryhmiin kuuluvia tuotteita, joita ei ole yksilöity tuoteliitteessä (ks. sopimusluonnos). Liitteessä 1. Tuoteliite HUS 266-2026 on osa-alueittain ilmoitettu, kuinka monta toimittajaa valitaan kuhunkin osa-alueeseen. Sopimus on voimassa määräaikaisena 4 vuotta, minkä jälkeen se on voimassa toistaiseksi. Sopimuksen arvioitu alkamisajankohta on marraskuu-joulukuu 2026. Tässä tarjouspyynnössä pyydettyjä tuotteita tulee käyttämään HUS-yhtymä (HUS). Hankinnan ennakoitu kokonaisarvo (alv 0 %) on yhteensä noin 5 miljoonaa euroa laskettuna 48 kk ajanjaksolle. Kyse on arviosta, eikä hankintayksikkö sitoudu ilmoitettuihin euromääriin ja tarjouspyynnössä ilmoitettuihin, toteutuneisiin kulutusmääriin. Lopulliset tilausmäärät voivat olla ilmoitettua suurempia tai pienempiä. Hankinnan kohde ja sitä koskevat vaatimukset on kuvattu yksityiskohtaisesti tarjouspyynnössä ja sen liitteissä. IPI-ASETUKSEN JA TOIMENPITEEN SOVELTAMINEN Tähän hankintaan sovelletaan Euroopan parlamentin ja neuvoston asetusta (EU) 2022/1031 (kansainvälisten julkisten hankintojen väline, IPI) sekä komission täytäntöönpanoasetusta (EU) 2025/1197. IPI-toimenpiteen velvoittamana hankintayksikkö tulee sulkemaan pois hankintamenettelystä Kiinan kansantasavallasta peräisin olevat tarjoajat. Lisäksi hankintayksikkö tulee soveltamaan IPI-asetuksen 8. artiklan mukaisia, tarjouskilpailussa valittuja toimittajia koskevia velvoitteita. Ks. tarjouspyynnön liite 11. Sopimus. Jos tarjoaja tarjoaa kiinalaista alkuperää olevia tuotteita, ne käsitellään hankintamenettelyssä samoin kuin muistakin maista tulevat tuotteet. Kiinalaisia tuotteita ei siis suljeta hankintamenettelystä. Mikäli tarjotut tuotteet tulevat hankintamenettelyssä valituiksi sopimukselle, ja valintojen seurauksena hankintasopimukselle olisi tulossa yli 50 % kiinalaisia tuotteita (laskettuna ko. sopimuksen kokonaisarvosta, ei siis tuotteiden lukumäärästä), tarjoajan on sitouduttava liitteen 11 Sopimus mukaiseen sakkomaksuun 10 - 30 % ko. sopimuksen arvosta. Hankintapäätöksen jälkeen tarjottuja tuotteita ei lähtökohtaisesti voi vaihtaa toisiksi. Julkisen hankintamenettelyn lähtökohtana on tarjouksen lopullisuus (hankintalaki 74 § ja oikeuskäytäntö). Lisäksi hankintalain 136 § määrää, ettei sopimuksia saa olennaisesti muuttaa (tuotteiden vaihtaminen toisiksi katsottaisiin olennaiseksi muutokseksi)., Synnynnäiset sydänviat Synnynnäiset sydänviat, Sulkulaitteet ja plugit Sulkulaitteet ja plugit, Isot valvuloplastiakatetrit Isot valvuloplastiakatetrit,','HUS-yhtymä','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056500','[\"33000000\"]','[\"hankinnan\", \"tuotteita\", \"sopimuksen\", \"tarvikkeet\", \"yhtymä\", \"alueeseen\", \"tuotteet\", \"liitteessä\", \"sulkulaitteet\", \"plugit\", \"isot\", \"valvuloplastiakatetrit\", \"tarjoaja\", \"siis\", \"lisäksi\", \"sopimus\", \"tarjouspyynnössä\", \"tulee\", \"hankintayksikkö\", \"kardiologiset\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/huslogistiikka?id=624612&tpk=639ce08b-9673-4c63-a4e5-5aa82d9bd030\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056500\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56500\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Synnynnäiset sydänviat\", \"titleSv\": \"\", \"cpvCodes\": \"33000000\", \"currency\": null, \"deadline\": \"2026-10-13T06:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"Synnynnäiset sydänviat\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-10-13T06:00:00Z\", \"circularEconomy\": true, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": true, \"listedGreenCriteriaUsed\": false, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSm