INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (1046,'2026-056497','HILMA','RFP','OPEN','Hammaskuvauslaitteet','Hammaskuvauslaitteet Hankinnan kohteena on hammaskuvauslaitteet panoraama- ja kefalotutkimuksiin Keski-Suomen hyvinvointialueen kuvantamisen eri yksiköihin. Hankintaan sisältyvät myös laitesidonnaiset tarvikkeet, ohjelmiston ylläpito sekä huoltosopimus takuuajan loppumisen jälkeen. Hankittavan laitteiston tulee täyttää tarjouspyynnössä asetetut vaatimukset. Sopimuskumppaniksi valitaan yksi (1) toimittaja, jonka kanssa solmitaan määräaikainen hankintasopimus 31.12.2030 asti, sisältäen kahden (2) vuoden optiokauden. Vuonna 2026 tullaan hankkimaan kaksi laitetta määrärahojen puitteissa, ja tulevien vuosien laiteinvestoinnit tullaan toteuttamaan myönnettävien määrärahojen mukaisesti. Hankintayksikkö ei kuitenkaan sitoudu ilmoitettuihin arvioituihin hankintamääriin. Vaihtoehtoiset tarjoukset eivät ole sallittuja. Rinnakkaiset tarjoukset eivät ole sallittuja.,','Keski-Suomen hyvinvointialue','ANY',1,14,NULL,NULL,420000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056497','[\"33000000\", \"33111000\"]','[\"hammaskuvauslaitteet\", \"keski\", \"suomen\", \"tullaan\", \"määrärahojen\", \"tarjoukset\", \"eivät\", \"sallittuja\", \"hyvinvointialue\", \"hankinnan\", \"kohteena\", \"panoraama\", \"kefalotutkimuksiin\", \"hyvinvointialueen\", \"kuvantamisen\", \"yksiköihin\", \"hankintaan\", \"sisältyvät\", \"laitesidonnaiset\", \"tarvikkeet\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/hyvaks?id=625369&tpk=2041567d-bde5-4090-9667-fee8c852f7dc\", \"name\": \"Procurement Documents\"}, {\"url\": 