INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16077,'082951b0f6838f4254b7','Hansel','RFP','OPEN','KULJETUSTA JO 31 VUOTTA','','Hanki / Valtiokonttori','ANY',10,13,NULL,NULL,NULL,'EUR','https://hanki.fi/',NULL,'[\"kuljetusta\", \"vuotta\", \"finland\", \"government\", \"procurement\"]',NULL,NULL,NULL,'{\"text\": \"KULJETUSTA JO 31 VUOTTA Ammattitaidolla, Luotettavasti ja Turvallisesti 1995 - 2026 Tilausliikenne Hanki Oy on kolmekymmentä vuotias perheyritys. Kuljetamme ammattitaidolla kotimaassa, pohjoismaissa, manner Euroopassa ja Baltian maissa. Teitä kuljettavat ja palvelevat, lain vaatiman Ammattitutkinnon suorittaneet kuljettajat. On matka lyhyt tai pitkä, me kuljetamme turvallisesti perille! (Kuljettajiemme keski-ikä on 43 vuotta, emme käytä eläkeläis kuljettajia kuljetuksissamme)\"}',50,NULL,'2026-09-08 15:12:26','2026-09-08 15:12:26');
INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16078,'7c47f1e68b7d2d1a3d64','Hansel','RFP','OPEN','Myynnissä olevat matkat. ​ Tervetuloa matkaamme mukaan! RALLIPÄIVÄ PORVOOSSA 26.9.2026 Lähde mukaan vauhdikkaalle päiväm','','Hanki / Valtiokonttori','ANY',10,13,NULL,NULL,NULL,'EUR','https://hanki.fi/',NULL,'[\"mukaan\", \"myynnissä\", \"olevat\", \"matkat\", \"tervetuloa\", \"matkaamme\", \"rallipäivä\", \"porvoossa\", \"lähde\", \"vauhdikkaalle\", \"päiväm\", \"finland\", \"government\", \"procurement\"]',NULL,NULL,NULL,'{\"text\": \"Myynnissä olevat matkat. ​ Tervetuloa matkaamme mukaan! RALLIPÄIVÄ PORVOOSSA 26.9.2026 Lähde mukaan vauhdikkaalle päivämatkalle Porvoon SM-rallin päätösosakilpailuun! Koe rallin tunnelma, jännitys ja vauhti parhaimmillaan -  tai vietä päivä omatoimisesti kauniissa Porvoossa. ​ Porvoon Taidetehtaan ja Vanhan Raatihuoneentorin Joulumarkkinat 12.12.2026 ​ Joulun tunnelmaa Porvoossa! Lähde mukaan viettämään ihanaa joulupäivää Porvoon tunnelmallisiin maisemiin. Ihania joululahjoja, käsitöitä, herkkuja ja paljon kaunista katseltavaa. Porvoon Vanhan kaupungin idyllinen joulutunnelma, kauniit vanhat rakennukset ja jouluiset kojut tekevät päivästä ikimuistoisen. Mukana suuren suosion saanut elämysjoulupolku Runebergin puistossa joka johdattaa sinut Vanhaan  kaupunkiin. Polulta löytyy myyntikioskeja, joulupukki, laavu tulipaikkoineen, kotieläimiä, musiikkia ym. muuta mukavaa. ​ ​ ​ Matkojen tarkemmat tiedot löytyy valmismatkoistamme.​ ​ Myynnissä olevat matkat Tervetuloa matkaamme mukaan!! Unohtumaton matka bussilla Kroatia Opatija 22.9.- 5.10.2026 Rallimatka Saarenmaalle 9.-11.10.2026 Hemmotteluloma Hotelli Emmi Pärnu 18.-24.10.2026 Lindoran kylämarkkinat ja Kubian kylpylä 27.-29.10.2026 Os\"}',50,NULL,'2026-09-08 15:12:26','2026-09-08 15:12:26');
