INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16256,'2026-056628','HILMA','OTHER','OPEN','Jälki-ilmoitus: Kainuun keskussairaalan uuden ravintokeskuksen rakennusurakan hankinta','Kainuun hyvinvointialue (Tilaaja) pyysi tarjouksia Kainuun keskussairaalan uuden ravintokeskuksen (Ravintokeskus Kataja; \"valmistuskeittiö\") rakennusurakasta, tämän tarjouspyynnön ja muun tarjouspyyntöaineiston mukaisesti. Kyseessä oli hankintalain (Laki julkisista hankinnoista ja käyttöoikeussopimuksista 1397/2016) mukainen EU-kynnysarvon ylittävä rakennusurakoiden hankinta. Urakkamuotona oli jaettu urakka, jossa rakennusteknisten töiden urakoitsija toimii pääurakoitsijana ja lainsäädännön tarkoittamana päätoteuttajana. Putki-, ilmanvaihto-, rakennusautomaatio ja sähkötöiden urakat toteutetaan pääurakkaan alistettuina sivu-urakoina. Tarkempi kuvaus hankinnan sisällöstä löytyy 607381 / Hankintailmoitus: Kainuun keskussairaalan uuden ravintokeskuksen rakennusurakan hankinta., Kainuun keskussairaalan valmistuskeittiö: RAKENNUS-/PÄÄURAKKA Rakennuspaikka on Kajaanissa Kainuun keskussairaalalla, osoitteessa Sotkamontie 13. RAKENNUS-/PÄÄURAKKA urakkaohjelman mukaisesti., Kainuun keskussairaalan valmistuskeittiö: ILMANVAIHTOURAKKA Rakennuspaikka on Kajaanissa Kainuun keskussairaalalla, osoitteessa Sotkamontie 13. ILMANVAIHTOURAKKA urakkaohjelman mukaisesti., Kainuun keskussairaalan valmistuskeittiö: RAKENNUSAUTOMAATIOURAKKA Rakennuspaikka on Kajaanissa Kainuun keskussairaalalla, osoitteessa Sotkamontie 13. RAKENNUSAUTOMAATIOURAKKA urakkaohjelman mukaisesti., Kainuun keskussairaalan valmistuskeittiö: SÄHKÖURAKKA Rakennuspaikka on Kajaanissa Kainuun keskussairaalalla, osoitteessa Sotkamontie 13. SÄHKÖURAKKA urakkaohjelman mukaisesti., Kainuun keskussairaalan valmistuskeittiö: YHDISTELMÄTARJOUS Rakennuspaikka on Kajaanissa Kainuun keskussairaalalla, osoitteessa Sotkamontie 13. Yhdistelmätarjous urakkaohjelman mukaisesti. Tarjoaja voi tehdä myös yhdistelmätarjouksen ja mikäli tarjoaja tekee yhdistelmätarjouksen, on tarjoajan tehtävä oma tarjous jokaiseen osa-alueeseen, joka sisältyy yhdistelmätarjoukseen. Mikäli yhdistelmätarjous ei tule sellaisenaan valituksi, on tarjouksen tekijällä velvollisuus hoitaa ne yhdistelmätarjouksessa mukana olevat osa-alueet, jotka mahdollisesti tulevat valituksi omina erillisinä osa-alueina. Yhdistelmätarjous tulee valituksi silloin, kun sen tarjoushinta jää tilaajalle edullisemmaksi, kuin kyseisten urakoiden halvimpien erillistarjousten summa., Kainuun keskussairaalan valmistuskeittiö: PUTKIURAKKA Rakennuspaikka on Kajaanissa Kainuun keskussairaalalla, osoitteessa Sotkamontie 13. PUTKIURAKKA urakkaohjelman mukaisesti.,','Kainuun hyvinvointialue','ANY',3,3,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056628','[\"45000000\"]','[\"kainuun\", \"keskussairaalan\", \"valmistuskeittiö\", \"mukaisesti\", \"rakennuspaikka\", \"kajaanissa\", \"keskussairaalalla\", \"osoitteessa\", \"sotkamontie\", \"urakkaohjelman\", \"yhdistelmätarjous\", \"uuden\", \"ravintokeskuksen\", \"hankinta\", \"valituksi\", \"rakennusurakan\", \"hyvinvointialue\", \"rakennus\", \"pääurakka\", \"ilmanvaihtourakka\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056628\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56628\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Kainuun keskussairaalan valmistuskeittiö: RAKENNUS-/PÄÄURAKKA\", \"titleSv\": \"\", \"cpvCodes\": \"45000000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": false, \"nutsCodes\": \"FI1D8\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": 