INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16258,'2026-056624','HILMA','OTHER','OPEN','JÄLKI-ILMOITUS Verkkotallennusjärjestelmien hankinta','Hankinnan kohteena ovat verkkotallennusratkaisuihin (NAS) liittyvät laitteet sekä näiden asennus- ja tukipalvelut. Hankintayksikkönä toimii Helsingin yliopisto ja hankintaan osallistuu hankintayksikön lisäksi Itä-Suomen yliopisto, Oulun yliopisto, Oulun ammattikorkeakoulu, Tampereen yliopisto ja Turun yliopisto. Kukin hankintayksikkö hankkii kilpailutuksen tulosten pohjalta omiin tarpeisiinsa sopivan kokonaisuuden, johon kuuluu yksi (tai useampi) verkkotallennusjärjestelmä ja siihen kuuluvat ohjelmistot ja palvelut. Kullakin hankintayksiköllä on ennestään käytössään yksi tai useampia verkkotallennusjärjestelmä, joita käytetään palvelujen tuottamiseen hankintayksikköjen edustamien korkeakouluyhteisöjen tutkimuksen, opetuksen ja hallinnon tarpeisiin. Tallennusjärjestelmät ovat tyypillisesti kunkin hankintayksikön omistuksessa ja sijaitsevat niiden omissa konesaleissa. Tallennusjärjestelmillä on tyypillisesti ollut noin viiden vuoden elinkaari, mutta itse verkkotallennuspalvelussa olevan datan elinkaari voi olla hyvinkin pitkä. Hankinta on jaettu neljään eri osa-alueeseen ja kilpailutuksen vertailuperusteena on kokonaistaloudellisesti edullisin hinta. Hintaa on käytetty kokonaistaloudellisen edullisuuden ainoana vertailuperusteena, koska laatu on huomioitu kattavissa vähimmäisvaatimuksissa. Tilaaja valitsee puitesopimustoimittajikseen kokonaistaloudellisesti edullisimmat tarjoajat osa-alueilta B-D ja näiden tarjoajien kanssa tehdään puitesopimus neljäksi (4) vuodeksi, jonka lisäksi on mahdollisuus jatkaa sopimusta kahdella optiovuodella yksi vuosi kerrallaan. Jokainen mukana oleva hankintayksikkö tekee omat sopimuksensa ja vastaavat niistä sopimuskauden ajan. Puitesopimusluonnos on tarjouspyynnön liitteenä. Hankinnan kohde ja sitä koskevat vaatimukset on kuvattu yksityiskohtaisesti tarjouspyynnössä ja sen liitteissä., A: Osa-alueisiin B-D valitut toimittajat Osa-alueeseen A tulevat valituksi automaattisesti kaikki muihin osa-alueisiin valitut toimittajat, eikä pelkästään osa-alueeseen A voi jättää tarjouksia. Osa-alueella A ei sovelleta etusijajärjestystä., B: Teknologiakohtainen osa-alue: Dell PowerScale Teknologiakohtaisten osa-alueiden B ja C tuotteiden vähimmäisvaatimukset löytyvät tarjouspyynnön liitteestä Tekniset vähimmäisvaatimukset., C: Teknologiakohtainen osa-alue: NetApp Teknologiakohtaisten osa-alueiden B ja C tuotteiden vähimmäisvaatimukset löytyvät tarjouspyynnön liitteestä Tekniset vähimmäisvaatimukset., D: Osa-alue: Teknologiariippumattomat Osa-alueeseen D voi tarjota vastaavia, mutta eri laitevalmistajien tuotteita kuin osa-alueisiin B ja C. Tuotteiden vähimmäisvaatimukset löytyvät tarjouspyynnön liitteestä Tekniset vähimmäisvaatimukset.,','Helsingin yliopisto','ANY',1,14,NULL,NULL,25400000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056624','[\"30200000\", \"30230000\", \"30233000\", \"30234000\", \"32580000\", \"48000000\", \"48800000\", \"48823000\", \"50312000\", \"72100000\"]','[\"yliopisto\", \"vähimmäisvaatimukset\", \"alueeseen\", \"tarjouspyynnön\", \"helsingin\", \"yksi\", \"alueisiin\", \"alue\", \"tuotteiden\", \"löytyvät\", \"liitteestä\", \"tekniset\", \"hankinta\", \"hankinnan\", \"ovat\", \"näiden\", \"hankintayksikön\", \"lisäksi\", \"oulun\", \"hankintayksikkö\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056624\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56624\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"A: Osa-alueisiin B-D valitut toimittajat\", \"titleSv\": \"\", \"cpvCodes\": \"30200000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": null, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Osa-alueeseen A tulevat valituksi automaattisesti kaikki muihin osa-alueisiin valitut toimittajat, eikä pelkästään osa-alueeseen A voi jättää tarjouksia. Osa-alueella A ei sovelleta etusijajärjestystä.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2027-03-09T03:05:16.943Z\", \"circularEconomy\": null, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": null, \"employmentCondition\": null, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": null, \"lotResultTotalAmount\": null, \"justWorkingConditions\": null, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": null, \"energyEfficiencyConsidered\": null, \"includesFrameworkAgreement\": true, \"smeParticipationConsidered\": null, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": null, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": 0, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}, {\"id\": \"LOT-0002\", \"titleEn\": \"\", \"titleFi\": \"B: Teknologiakohtainen osa-alue: Dell PowerScale\", \"titleSv\": \"\", \"cpvCodes\": \"30200000\", \"currency\": null, \"deadline\": null, \"lowCarbon\"