INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16260,'2026-056621','HILMA','RFP','OPEN','Sako- ja umpikaivolietteiden vastaanotto ja hyödyntäminen','Sako- ja umpikaivolietteiden vastaanotto ja hyödyntäminen Tämän hankinnan kohteena on kunnan järjestämisvastuulle kuuluvien saostus- ja umpisäiliölietteiden sekä muiden asumisessa syntyvien lietteiden vastaanotto ja käsittely jätelain (646/2011) 32 §:n ja 33 §:n mukaisesti. Jätelain 32 §:n perusteella kunta vastaa vakinaisessa asunnossa, vapaa-ajanasunnossa, asuntolassa ja muussa asumisessa syntyvän saostus- ja umpisäiliölietteen jätehuollon järjestämisestä. Hankinnan kohteena oleva urakka kattaa kaiken kunnan lakisääteisen järjestämisvastuun piiriin kuuluvan lietteen vastaanoton, käsittelyn ja niihin liittyvät palvelut. Vastaanotettava ja käsiteltävä liete kerätään erilaisista kiinteistökohtaisista jätevesijärjestelmistä, kuten: * saostussäiliöistä, * umpisäiliöistä, * pienpuhdistamoista sekä * muista vastaavista lietettä sisältävistä säiliö- ja käsittelyjärjestelmistä. Hankinnan kohteena ovat kunnan jätehuoltovastuulle kuuluvat asumisessa syntyvät lietteet sekä jätelain 33 §:n mukaisen kunnan toissijaisen jätehuoltopalvelun (TSV) perusteella vastaanotettavat yrityslietteet. Muut elinkeinotoiminnassa, teollisuudessa, maataloudessa tai vastaavassa toiminnassa syntyvät lietteet eivät kuulu tämän sopimuksen piiriin. Palveluntarjoajan tulee järjestää lietteiden vastaanotto ja käsittely voimassa olevan lainsäädännön, viranomaismääräysten sekä ympäristölupaehtojen mukaisesti.,','Lounais-Suomen Jätehuolto Oy','ANY',5,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056621','[\"90513800\"]','[\"vastaanotto\", \"kunnan\", \"hankinnan\", \"kohteena\", \"asumisessa\", \"jätelain\", \"sako\", \"umpikaivolietteiden\", \"hyödyntäminen\", \"tämän\", \"saostus\", \"lietteiden\", \"käsittely\", \"mukaisesti\", \"perusteella\", \"piiriin\", \"syntyvät\", \"lietteet\", \"lounais\", \"suomen\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/lsjh?id=625695&tpk=ed4da7e2-d2a8-4d44-bd89-3187f4f72c74\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056621\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56621\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Sako- ja umpikaivolietteiden vastaanotto ja hyödyntäminen\", \"titleSv\": \"\", \"cpvCodes\": \"90513800\", \"currency\": null, \"deadline\": \"2026-10-07T06:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"Tämän hankinnan kohteena on kunnan järjestämisvastuulle kuuluvien saostus- ja umpisäiliölietteiden sekä muiden asumisessa syntyvien lietteiden vastaanotto ja käsittely jätelain (646/2011) 32 §:n ja 33 §:n mukaisesti.\\n\\nJätelain 32 §:n perusteella kunta vastaa vakinaisessa asunnossa, vapaa-ajanasunnossa, asuntolassa ja muussa asumisessa syntyvän saostus- ja umpisäiliölietteen jätehuollon järjestämisestä. Hankinnan kohteena oleva urakka kattaa kaiken kunnan lakisääteisen järjestämisvastuun piiriin kuuluvan lietteen vastaanoton, käsittelyn ja niihin liittyvät palvelut.\\n\\nVastaanotettava ja käsiteltävä liete kerätään erilaisista kiinteistökohtaisista jätevesijärjestelmistä, kuten:\\n* saostussäiliöistä,\\n* umpisäiliöistä,\\n* pienpuhdistamoista sekä\\n* muista vastaavista lietettä sisältävistä säiliö- ja käsittelyjärjestelmistä.\\n\\nHankinnan kohteena ovat kunnan jätehuoltovastuulle kuuluvat asumisessa syntyvät lietteet sekä jätelain 33 §:n mukaisen kunnan toissijaisen jätehuoltopalvelun (TSV) perusteella vastaanotettavat yrityslietteet. Muut elinkeinotoiminnassa, teollisuudessa, maataloudessa tai vastaavassa toiminnassa syntyvät lietteet eivät kuulu tämän sopimuksen piiriin.\\n\\nPalveluntarjoajan tulee järjestää lietteiden vastaanotto ja käsittely voimassa olevan lainsäädännön, viranomaismääräysten sekä ympäristölupaehtojen mukaisesti.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-10-07T06:00:00Z\", \"circularEconomy\": true, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": false, \"lotResultTotalAmount\": null, \"justWorkingConditions\": true, \"listedGreenCriteriaUsed\": false, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": null, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}], \"type\": \"16\", \"isPlan\": false, \"planId\": 0, \"titleEn\": \"\", \"titleFi\": \"Sako- ja umpikaivolietteiden vastaanotto ja hyödyntäminen\", \"titleSv\": \"\", \"cpvCodes\": \"90513800\", \"currency\": null, \"deadline\": \"2026-10-07T06:00:00Z\", \"eFormsId\": \"59303768-bff0-43f8-a44e-8912d1