INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16261,'2026-056620','HILMA','RFP','OPEN','Kaivokselan koulu korjaus ja tilamuutokset, putkiurakka','Kaivokselan koulu korjaus ja tilamuutokset, putkiurakka Hankinta käsittää Kaivokselan koulu korjaus- ja tilamuutoshankkeen rakentamisen putkiurakan työt urakkalaskenta-asiakirjojen mukaisesti. Putkiurakka on pääurakkaan alistettu sivu-urakka. Työt tehdään tilaajan laadituttamien suunnitelmien mukaan. Rakennusurakoitsija toimii työmaan päätoteuttajana ja työmaan johtovelvollisena urakoitsijana. Tilaajan nimiin kilpailutetaan erikseen sivu-urakoitsijat ja tilaajan erillishankinnat. Sivu-urakoitsijat alistetaan pääurakkaan. Tarjous annetaan tarjouspyyntömateriaalien perusteella. Kaupalliset asiakirjat ovat tässä liitteitä, muut asiakirjat ovat saatavilla SokoPron linkin kautta. Rakennuskohteen nimi: Kaivokselan koulu korjaus ja tilamuutokset Kaivosvuodintie 10, 01610 Vantaa,','Vantaan kaupunki','ANY',2,4,NULL,NULL,500000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056620','[\"45332000\"]','[\"kaivokselan\", \"koulu\", \"korjaus\", \"tilamuutokset\", \"putkiurakka\", \"sivu\", \"tilaajan\", \"työt\", \"pääurakkaan\", \"työmaan\", \"urakoitsijat\", \"asiakirjat\", \"ovat\", \"hankinta\", \"käsittää\", \"tilamuutoshankkeen\", \"rakentamisen\", \"putkiurakan\", \"urakkalaskenta\", \"asiakirjojen\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/vantaa?id=627221&tpk=01bd8ab3-89b0-42a3-aa1a-932cfb973c1f\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056620\", \"name\": \"HILMA Notice\"}]','{\"id\": \"