INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16263,'2026-056613','HILMA','RFI','OPEN','MARKKINAVUOROPUHELUKUTSU Turun kaupungin energiankulutuksen valvontapalvelu','MARKKINAVUOROPUHELUKUTSU Turun kaupungin energiankulutuksen valvontapalvelu MARKKINAKARTOITUSVAIHEESSA VOIT VIELÄ VAIKUTTAA! Haluamme Turun kaupungilla tehdä laadukkaita hankintoja ja tehdä yhteistyötä yritysten kanssa. Teemme siksi markkinakartoitusta ennen varsinaisen hankintailmoituksen julkaisua. Tavoitteena on kertoa tulevasta kilpailutuksesta, kartoittaa hankinnan kohteen markkinoita sekä saada kattavasti tietoa palvelun saatavuudesta, toteutusmahdollisuuksista sekä potentiaalisista toimittajista. Tulemme pyytämään markkinavuoropuheluun osallistuvilta toimittajilta myös kommentteja hankinta-asiakirjoihin tulevista vähimmäisvaatimuksista ja laatukriteereistä. Markkinavuoropuhelussa on tavoitteena käydä läpi myös tulevan kilpailutuksen aikataulutusta ja toteutusta. Tämä on kutsu markkinavuoropuheluun, joka koskee Turun kaupungin suunnittelemaa energiankulutuksen valvontapalvelusta. Turun kaupunki valvoo energiankulutusta n. 600 rakennuksessa, joista yli 200:ssa on kaukolämpö. Mittauskeskitin, jolla saadaan tarkempaa kulutustietoa löytyy n. 70 rakennuksesta. Tavoitteena on luoda energiankulutuksen valvontaa tuottava digitaalinen palvelu, joka tekee asiantuntijan manuaaliset työvaiheet tuottaen mahdollisimman pitkälle valmiiksi jalostettua tietoa kulutusmuutoksista helpoilla näkymillä, selitteillä ja jatkotoimenpiteillä. Tavoitteena on tehdä kulutusvalvonnasta mahdollisimman automaattista vähentämällä manuaalisen työn vaiheita, kuten nousseen kulutuksen alkuajankohdan, esiintymisen ja kokonaisvaikutusten selvittämistä. Käyttäjän tulisi saada automaattisesti tärkeimmiksi priorisoidut kärkihavainnot näkyviin ja helposti havainnon analyysi näkyviin. Markkinavuoropuhelu järjestetään webinaarina Teamsissa 2.10. klo 9 -11. Tilaisuuden ohjelma: 9:00-10:00 Kilpailutuksen esittely 10:00-11:00 Kysymyksiä, vastauksia ja keskustelua Lämpimästi tervetuloa! ILMOITTAUTUMINEN: Ilmoittautuminen Tarjouspalvelun kautta 25.9.2026 klo 16:00 mennessä tai s-postitse sari.holmberg@turku.fi. Ilmoita yrityksestänne osallistuvat henkilöt ja heidän sähköpostiosoitteensa. Tämä ilmoitus ei ole hankintailmoitus eikä tarjouspyyntö, vaan kutsu markkinavuoropuheluun, jolla pyritään kartoittamaan markkinoita ja kehittämään hankinnan kilpailutusasiakirjoja. Kutsu ei sido siihen vastanneita. Markkinavuoropuhelutilaisuuteen osallistumatta jättäminen ei estä mahdolliseen tarjouskilpailuun osallistumista eikä tilaisuuteen osallistuminen vaikuta millään tavoin tarjoajan asemaan varsinaisessa tarjouskilpailussa. Hankintayksikkö ei sitoudu toteuttamaan hankintaa markkinakartoituksen perusteella, eivätkä esitetyt kuvaukset / määritykset sido tilaajaa. Ilmoitamme tulevista hankinnoistamme Hilman -suunnittelutyökalussa, johon on mahdollista asettaa haku-vahteja. Hilman suunnittelutyökalu Lisätietoja meistä löydät www.turku.fi/hankinnat ja ajankohtaisia asioita julkaisemme LinkedIn-sivullamme ”Turun kaupungin hankintapalvelut”.,','Turun kaupunki','ANY',5,1,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056613','[\"60000000\", \"60600000\"]','[\"turun\", \"kaupungin\", \"energiankulutuksen\", \"tavoitteena\", \"tehdä\", \"markkinavuoropuheluun\", \"kutsu\", \"markkinavuoropuhelukutsu\", \"valvontapalvelu\", \"hankinnan\", \"markkinoita\", \"saada\", \"tietoa\", \"tulevista\", \"kilpailutuksen\", \"tämä\", \"kaupunki\", \"jolla\", \"mahdollisimman\", \"näkyviin\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/turku?id=626184&tpk=cf030240-e8ce-4ffc-b2bd-9e42338c7043\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056613\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56613\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"MARKKINAVUOROPUHELUKUTSU Turun kaupungin energiankulutuksen valvontapalvelu\", \"titleSv\": \"\", \"cpvCodes\": \"60000000 60600000\", \"currency\": null, \"deadline\": \"2026-09-25T13:00:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"FI1C1\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"MARKKINAKARTOITUSVAIHEESSA VOIT VIELÄ VAIKUTTAA!\\n\\nHaluamme Turun kaupungilla tehdä laadukkaita hankintoja ja tehdä yhteistyötä yritysten kanssa. Teemme siksi markkinakartoitusta ennen varsinaisen hankintailmoituksen julkaisua. Tavoitteena on kertoa tulevasta kilpailutuksesta, kartoittaa hankinnan kohteen markkinoita sekä saada kattavasti tietoa palvelun saatavuudesta, toteutusmahdollisuuksista sekä potentiaalisista toimittajista. Tulemme pyytämään markkinavuoropuheluun osallistuvilta toimittajilta myös kommentteja hankinta-asiakirjoihin tulevista vähimmäisvaatimuksista ja laatukriteereistä. Markkinavuoropuhelussa on tavoitteena käydä läpi myös tulevan kilpailutuksen aikataulutusta ja toteutusta. \\n\\nTämä on kutsu markkinavuoropuheluun, joka koskee Turun kaupungin suunnittelemaa energiankulutuksen valvontapalvelusta. Turun kaupunki valvoo energiankulutusta n. 600 rakennuksessa, joista yli 200:ssa on kaukolämpö. Mittauskeskitin, jolla saadaan tarkempaa kulutustietoa löytyy n. 70 rakennuksesta. \\n\\nTavoitteena on luoda energiankulutuksen valvontaa tuottava digitaalinen palvelu, joka tekee asiantuntijan manuaaliset työvaiheet tuottaen mahdollisimman pitkälle valmiiksi jalostettua tietoa kulutusmuutoksista helpoilla näkymillä, selitteillä ja jatkotoimenpiteillä. \\n\\nTavoitteena on tehdä kulutusvalvonnasta mahdollisimman automaattista väh