INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16264,'2026-056612','HILMA','OTHER','OPEN','Matkailun yhteismarkkinointipalveluiden hankinta','Matkailun yhteismarkkinointipalveluiden hankinta Kalajoen kaupunki pyytää tarjouksia Kalajoen matkailukeskuksen ja sen lähialueen matkailun yhteismarkkinointipalveluiden hankintaan. Toimittajan tulee tarjota palvelukokonaisuutta, joka koostuu seuraavista Kalajoen matkailualueelle tuotettavista yhteismarkkinoinnin palvelujen suunnittelusta ja käytännön toteutuksesta: 1. Matkailun yhteismarkkinointi ympärivuotisesti sekä matkailualueen imagon ja brändin kehittäminen 2. Yritys- ja sidosryhmäyhteistyö sekä uusien kumppanuuksien hakeminen 3. Matkailukeskuksen aluetapahtumien teemoittelu ja kehittäminen sekä valikoitujen aluetapahtumien koordinointi ja järjestäminen 4. Matkailualueen saavutettavuuden ja ympärivuotisuuden edistäminen Hankinnan kohde on kuvattu tarkemmin jäljempänä tarjouspyynnössä ja sen liitteissä. Hankinnan kohdetta ei ole jaettu osa-alueisiin. Tarjoajan on tarjottava kaikkia palvelukokonaisuuksia, eikä palvelukokonaisuuskohtaisia tai palvelukokonaisuuden sisäisiä osatarjouksia hyväksytä. Hankinta toteutetaan ns. käänteisenä kilpailutuksena, jossa hankintayksikkö on määritellyt hinnan, jonka se on valmis maksamaan valittavalle palveluntuottajalle matkailun yhteismarkkinoinnin toteutuksesta. Tarjoajien välinen kilpailu käydään yksinomaan laatuun liittyvillä perusteilla. Tarjouskilpailun perusteella valitaan yksi toimittaja sopimuskumppaniksi. Sopimus solmitaan toistaiseksi voimassaolevana sisältäen 12 kk irtisanomisehdon.,','Kalajoen kaupunki','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056612','[\"79340000\"]','[\"matkailun\", \"kalajoen\", \"yhteismarkkinointipalveluiden\", \"hankinta\", \"kaupunki\", \"matkailukeskuksen\", \"yhteismarkkinoinnin\", \"toteutuksesta\", \"matkailualueen\", \"kehittäminen\", \"aluetapahtumien\", \"hankinnan\", \"pyytää\", \"tarjouksia\", \"lähialueen\", \"hankintaan\", \"toimittajan\", \"tulee\", \"tarjota\", \"palvelukokonaisuutta\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056612\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56612\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Matkailun yhteismarkkinointipalveluiden hankinta\", \"titleSv\": \"\", \"cpvCodes\": \"79340000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": false, \"nutsCodes\": \"FI1D9\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Kalajoen kaupunki pyytää tarjouksia Kalajoen matkailukeskuksen ja sen lähialueen matkailun yhteismarkkinointipalveluiden hankintaan. Toimittajan tulee tarjota palvelukokonaisuutta, joka koostuu seuraavista Kalajoen matkailualueelle tuotettavista yhteismarkkinoinnin palvelujen suunnittelusta ja käytännön toteutuksesta: \\n\\n1. Matkailun yhteismarkkinointi ympärivuotisesti sekä matkailualueen imagon ja brändin kehittäminen\\n2. Yritys- ja sidosryhmäyhteistyö sekä uusien kumppanuuksien hakeminen\\n3. Matkailukeskuksen aluetapahtumien teemoittelu ja kehittäminen sekä valikoitujen aluetapahtumien koordinointi ja järjestäminen\\n4. Matkailualueen saavutettavuuden ja ympärivuotisuuden edistäminen \\n\\nHankinnan kohde on kuvattu tarkemmin jäljempänä tarjouspyynnössä ja sen liitteissä. Hankinnan kohdetta ei ole jaettu osa-alueisiin. Tarjoajan on tarjottava kaikkia palvelukokonaisuuksia, eikä palvelukokonaisuuskohtaisia tai palvelukokonaisuuden sisäisiä osatarjouksia hyväksytä. \\n\\nHankinta toteutetaan ns. käänteisenä kilpai