INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16265,'2026-056610','HILMA','RFP','OPEN','Ilmanpuhdistuslaitteiden vuokraus ja hankinta','Vantaan kaupunki pyytää tarjouksia ilmanpuhdistimien vuokraamisesta ja hankinnasta. Hankinnan kohteena ovat vuokrattavat ja ostettavat sisäilmanpuhdistuslaitteet julkisiin tiloihin, kuten koulu- ja päiväkotitiloihin, toimistoihin, arkistoihin, auditorioihin jne. Tilaajat hankkivat pääosin vuokrattavia laitteita, ja vähäisissä määrin laitteita tullaan ostamaan omaksi. Ilmanpuhdistimilla haetaan väliaikaista ratkaisua sisäilmaongelmien hallintaan käyttöä turvaavana toimenpiteenä. Ilmanpuhdistimien tulee olla tarkoitettu tähän käyttötarkoitukseen. Hankinnan kohde on kuvattu tarkemmin tarjouspyynnön liitteellä 2 Palvelukuvaus. Kilpailutus suoritetaan avoimella menettelyllä, jonka perusteella jokaiseen osa-alueeseen puitetoimittajiksi valitaan kolme (3) vertailussa eniten pisteitä saanutta tarjoajaa etusijajärjestyksessä. Hankinta kilpailutetaan yhteishankintana niin, että Vantaan kaupunki julkaisee tarjouspyynnön. Kilpailutuksen perusteella tehdään samansisältöiset, sopimusluonnoksen (liite 1) mukaiset sopimukset Vantaan kaupungille, Kauniaisten kaupungille ja Vantaan ja Keravan hyvinvointialueelle. Hankintayksiköt tekevät myös oman päätöksensä. Vantaan kaupungille tehtävien sopimusten perusteella hankintoja voivat tehdä Vantaan kaupungin kaikki toimialat sekä Vantaan Tilapalvelut Vantti Oy, VTK Kiinteistöt Oy- konserni, VAV Yhtymä Oy, VAV Asunnot Oy, VAV Palvelukodit Oy, VAV Hoiva-asunnot Oy, Hakopolun Liikekiinteistö Oy, Kiinteistö Oy Hakucenter, Kiinteistö Oy Vantaan Maakotkantie 10, Pallastunturintien Liikekiinteistö Oy ja Asunto Oy Vantaan Katriinanrinne. Sopimustoimittaja voi tarjota samoin ehdoin tuotteitaan ja palvelujaan Vantaan kaupungin seuraaville konsernitoimijoille: Vivamus Kiinteistöt Oy ja Kiinteistö Oy Vantaan Sote-tilat. Sopimuskausi on kaksi (2) vuotta, jonka jälkeen sopimusta voidaan jatkaa kahdella (2) yhden (1) vuoden optiolla (1+1). Hankintayksikkö ei sitoudu tarjouspyyntöasiakirjoissa ilmoitettuihin euromääräisiin arvoihin tai tiettyihin arvioituihin hankintamääriin sopimuskaudella., Osa-alue 1: Puhtaanilmantuotto 160 m3/h Ilmanpuhdistuslaitteiden vuokraus ja hankinta toimistotiloihin., Osa-alue 2: Puhtaanilmantuotto 400 m3/h Ilmanpuhdistinten vuokraus ja hankinta., Osa-alue 3: Puhtaanilmantuotto 800 m3/h Ilmanpuhdistinten vuokraus ja hankinta isoihin tiloihin.,','Vantaan kaupunki','ANY',3,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056610','[\"39811200\"]','[\"vantaan\", \"hankinta\", \"vuokraus\", \"kaupunki\", \"perusteella\", \"kaupungille\", \"kiinteistö\", \"alue\", \"puhtaanilmantuotto\", \"ilmanpuhdistuslaitteiden\", \"ilmanpuhdistimien\", \"hankinnan\", \"tiloihin\", \"laitteita\", \"tarjouspyynnön\", \"jonka\", \"kaupungin\", \"kiinteistöt\", \"asunnot\", \"liikekiinteistö\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/vantaa?id=600297&tpk=e3e87dab-2964-483c-bce4-88915dd3849e\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056610\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56610\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Osa-alue 1: Puhtaanilmantuotto 160 m3/h\", \"titleSv\": \"\", \"cpvCodes\": \"39811200\", \"currency\": null, \"deadline\": \"2026-10-19T13:15:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Ilmanpuhdistuslaitteiden vuokraus ja hankinta toimistotiloihin.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-10-19T13:15:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": true, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": true, \"lotResultTotalAmount\": null, \"justWorkingConditions\": true, \"listedGreenCriteriaUsed\": null, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": false, \"energyEfficiencyConsidered\": false, \"includesFrameworkAgreement\": true, \"smeParticipationConsidered\": true, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"solutionNewToMarketOrIndustry\": false, \"tendersFromMicroTenderersCount\": null, \"tendersFromSmallTenderersCount\": null, \"howManyOpportunitiesIsEstimated\": 3, \"includesDynamicPurcharingSystem\": false, \"tendersFromMediumTenderersCount\": null, \"electronicallySubmittedTendersCount\": null, \"tendersVerifiedAndInadmissibleCount\": null, \"tendersNotVerifiedForAdmissibilityCount\": null, \"tendersFromMicroSmallMediumTenderersCount\": null, \"tendersVerifiedAndInadmissibleLowValueCount\": null}, {\"id\": \"LOT-0002\", \"titleEn\": \"\", \"titleFi\": \"Osa-alue 2: Puhtaanilmantuotto 400 m3/h\", \"titleSv\": \"\", \"cpvCodes\": \"39811200\", \"currency\": null, \"deadline\": \"2026-10-19T13:15:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Ilmanpuhdistinten vuokraus ja hankinta.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-10-19T13:15:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": 