INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16267,'2026-056607','HILMA','OTHER','OPEN','Siuntion kunnan ruokapalvelut','Siuntion kunnan ruokapalvelut Siuntion kunta pyytää tarjoustanne ruokapalveluista. Tarjouspyyntöön sisältyvät kaikki kunnan kaikki itse tuottamat ruokapalvelut. Lisätietoja tarjouspyynnön liitteistä. Sopimuskausi on 1.1.2027 - 31.7.2030. Sopimusta on mahdollista jatkaa varsinaisen sopimuskauden jälkeen toistaiseksi voimassa olevalla optiokaudella. Optiokauden käyttöönotosta päättää tilaaja ja ilmoittaa sen sopimustoimittajalle ennen sopimuskauden päättymistä. Ilmoituksena toimii sopimusliite tai hallintopäätös, joka toimitetaan osapuolelle sähköisesti, pyydetty allekirjoitus on vakuus ilmoituksen vastaanottamisesta. Optiokaudella sopimus jatkuu sopimuksen alkuperäisin ehdoin. Mikäli sopimus jatkuu toistaiseksi voimassa olevana, on irtisanomisaika kaksitoista (12) kuukautta kirjallisesta irtisanomisilmoituksesta. Myös toistaiseksi voimassa oleva sopimus kilpailutetaan säännöllisesti (n. 4–5 vuoden kuluttua) varsinaisen sopimuskauden alkamisesta.,','Siuntion kunta','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056607','[\"55500000\"]','[\"siuntion\", \"kunnan\", \"ruokapalvelut\", \"sopimuskauden\", \"toistaiseksi\", \"voimassa\", \"sopimus\", \"kunta\", \"varsinaisen\", \"optiokaudella\", \"jatkuu\", \"pyytää\", \"tarjoustanne\", \"ruokapalveluista\", \"tarjouspyyntöön\", \"sisältyvät\", \"itse\", \"tuottamat\", \"lisätietoja\", \"tarjouspyynnön\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056607\", \"name\": \"HILMA Notice