INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16268,'2026-056606','HILMA','RFP','OPEN','Turun kaupungin puhtauspalvelut','Turun kaupungin konsernihallinnon hankintapalvelut pyytää tarjouksia puhtauspalveluista. Sopimusajat käyvät ilmi hankinnan osien kuvauksesta, minkä jälkeen sopimusta voidaan tilaajan päätöksellä jatkaa alkuperäisin ehdoin kahdella (2) kahden (2) vuoden pituisella optiolla. Hankinnan kohteina on Turun kaupungin tilapalvelujen hallinnoimat toimitilat sekä kolmen yhtiön tilat. Yhteishankinnassa on mukana Turun kaupunki, Länsirannikon Työterveys Oy, Turun Taiteen talo Oy ja Turun Satama Oy. HANKITTAVA PALVELU Puhtauspalvelut sisältävät sovittujen palvelukuvausten mukaiset ylläpito- ja perussiivoustyöt sekä ikkunoiden pesut. Ylläpitosiivouksella tarkoitetaan säännöllisestä, sovitun puhtaustason ylläpitämiseksi tehtävää siivousta. Perussiivous on harvemmin tehtävä kertaluonteinen siivous, joka tilataan vuosittain erikseen. Ikkunan pesut tilataan myös vuosittain erikseen Kohteina on koulu- ja monitoimikiinteistöjä, toimistotiloja, yleisiä kaupungin kulttuurin ja vapaa-ajantiloja, sekä erilaisia muita julkisia tiloja. Hankinnasta tehdään sopimukset osakokonaisuuksittain. Hankinta on jaettu seuraaviin osa-alueisiin: 1. Jäkärlä - Ylimaaria - Paattinen Monitoimitaloja (samassa rakennuksessa useita eri palvelukokonaisuuksia) ja muita toimitiloja n. 20 000 m2 2. Kohmo - Nummi - Halinen Museoalue – oppilaitoksia – vapaa-ajan kohteita n. 27 000 m2 3. Varissuo - Pääskyvuori - Lauste - Vasaramäki - Liikunnan kohteita – oppilaitoksia - vapaa-ajan kohteita n. 31 000 m2 4. Kupittaa - Liikunnan kohteita – oppilaitoksia n. 28 000 m2 5. Urheilupuisto - vanha Suurtori - Kerttuli Kulttuurikohteita – liikunnan kohteita – oppilaitoksia n. 35 000 m2 6. Aninkainen - Puutarhakatu - Keskusta-alueen oppilaitoksia n. 39 000 m2 7. Pansio - Juhannuskukkula - Oppilaitoksia – liikunnan kohteita – vapaa-ajan kohteita n. 30 000 m2 8. Satama - Topelius mm. Oppilaitoksia – linna – toimistoja - vapaa-ajan kohteita n. 33 000 m2 9. Keskusta mm. Toimistoja – pääkirjasto – vapaa-ajan kohteita n. 32 000 m2 10. Kaupunkiympäristön palvelukokonaisuus (Kaupunkivessat ) – Funikulaari n. 200 m2 (9 rakennusta) 11. Länsirannikon työterveys Oy - Vastaanotto, tutkimus- ja toimistohuoneita, n. 3600 m2 12. Turun Taiteen talo Oy - Kulttuurikohde n. 2600 m2 13. Turun Satama Oy - Uusi Matkustajaterminaali n. 15 000 m2 Rakennusten ja kohteiden tarkemmat tiedot on kerrottu tarjouspyynnön liitteissä. Kohteita tullaan esittelemään kesäkuussa erillisen (liite 4) aikataulun mukaan. Kilpailutukseen osallistuminen edellyttää toimittajilta näyttökohteisiin tutustumista. Tarkemmat tiedot esittelyistä liitteissä. Hankinnan osakokonaisuuksiin 1-9 ja 11 on sisällytetty tarjoajaa sitova työllistämisehto. Ehdot kuvataan kohdassa \"Tarjouspyynnön muut ehdot\". Ehdot on suhteutettu osakokonaisuuksien arvoon. Lisätietoa työllistämisehdon käytäntöönpanosta on saatavilla tarjouspyynnön liitteessä Työllistämisehtoliite. Hankinta on kuvattuna tässä tarjouspyynnössä ja sen liitteissä. Tarkemmat tiedot kohteista, vastuunjaosta yms. löytyvät tarjouspyynnön liitteistä ja linkeistä. Tilaaja ei sitoudu tiettyyn volyymiin tai arvoon., Jäkärlä - Ylimaaria - Paattinen Hankinta on kuvattuna tässä tarjouspyynnössä ja sen liitteissä. Tätä osaa koskee työllistämisehto., Kohmo-Nummi-Halinen Hankinta on kuvattuna tässä tarjouspyynnössä ja sen liitteissä. Tätä osaa koskee työllistämisehto., Varissuo-Pääskyvuori-Lauste- Vasaramäki Hankinta on kuvattuna tässä tarjouspyynnössä ja sen liitteissä. Tätä osaa koskee työllistämisehto., Kupittaa Hankinta on kuvattuna tässä tarjouspyynnössä ja sen liitteissä. Tätä osaa koskee työllistämisehto., Urheilupuisto - Vanha suurtori - Kerttuli Hankinta on kuvattuna tässä tarjouspyynnössä ja sen liitteissä. Tätä osaa koskee työllistämisehto., Aninkainen - Puutarhakatu Hankinta on kuvattuna tässä tarjouspyynnössä ja sen liitteissä. Tätä osaa koskee työllistämisehto., Pansio - Juhannuskukkula Hankinta on kuvattuna tässä tarjouspyynnössä ja sen liitteissä. Tätä osaa koskee työllistämisehto., Satama-Topelius Hankinta on kuvattuna tässä tarjouspyynnössä ja sen liitteissä. Tätä osaa koskee työllistämisehto., Keskusta Hankinta on kuvattuna tässä tarjouspyynnössä ja sen liitteissä. Tätä osaa koskee työllistämisehto., Kaupunkiympäristön palvelukokonaisuus (kaupunkivessat) Hankinta on kuvattuna tässä tarjouspyynnössä ja sen liitteissä., Länsirannikon Työterveys Oy Hankinta on kuvattuna tässä tarjouspyynnössä ja sen liitteissä. Tätä osaa koskee työllistämisehto., Turun Taiteen talo Oy Hankinta on kuvattuna tässä tarjouspyynnössä ja sen liitteissä., Turun Satama Oy Hankinta on kuvattuna tässä tarjouspyynnössä ja sen liitteissä.,','Turun kaupunki','ANY',2,1,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056606','[\"90910000\"]','[\"liitteissä\", \"hankinta\", \"kuvattuna\", \"tässä\", \"tarjouspyynnössä\", \"turun\", \"työllistämisehto\", \"kohteita\", \"tätä\", \"osaa\", \"koskee\", \"oppilaitoksia\", \"vapaa\", \"satama\", \"ajan\", \"kaupungin\", \"liikunnan\", \"tarjouspyynnön\", \"hankinnan\", \"länsirannikon\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/turku?id=598763&tpk=a479a7c5-7274-4b47-a6ae-bf059fd913b5\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056606\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56606\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Jäkärlä - Ylimaaria - Paattinen\", \"titleSv\": \"\", \"cpvCodes\": \"90910000\", \"currency\": null, \"deadline\":