INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16273,'2026-056601','HILMA','OTHER','OPEN','Tornion meriväylän ja sataman geometrian parantaminen, KU','Tornion meriväylän ja sataman geometrian parantaminen, KU Urakka on kokonaishintainen kokonaisurakka (KU). Väylävirasto ja Outokumpu Stainless Oy toteuttavat yhdessä Tornion meriväylän ja sataman geometrian parantamisurakan. Urakka käsittää Tornion 9 metrin meriväylän geometrian parantamisen väylän kaarteita ja kapeita kohtia leventämällä sekä satama-altaan laajentamisen. Väylän kokonaispituus on 25 km, josta 23,8 km sijaitsee Väyläviraston hallinnassa ja 1,2 km Outokumpu Stainless Oy:n hallinnoimalla satama-alueella. Urakkaan sisältyy ruoppaus- ja läjitystöitä sekä väylän merkintään liittyvien turvalaitteiden muutostöitä. Ruoppausmassat läjitetään sataman läheisyydessä olevaan läjitysaltaaseen. Tarkempi kuvaus on tarjouspyynnön asiakirjoissa.,','Väylävirasto','ANY',4,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056601','[\"45000000\"]','[\"tornion\", \"meriväylän\", \"sataman\", \"geometrian\", \"väylävirasto\", \"väylän\", \"parantaminen\", \"urakka\", \"outokumpu\", \"stainless\", \"satama\", \"kokonaishintainen\", \"kokonaisurakka\", \"toteuttavat\", \"yhdessä\", \"parantamisurakan\", \"käsittää\", \"metrin\", \"parantamisen\", \"kaarteita\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056601\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56601\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Tornion meriväylän ja sataman geometrian parantaminen, KU\", \"titleSv\": \"\", \"cpv