INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16274,'2026-056600','HILMA','RFP','OPEN','Osallistumispyyntö: Hintan pintavesilaitoksen laajennushankkeen pääurakka','Osallistumispyyntö: Hintan pintavesilaitoksen laajennushankkeen pääurakka Oulun vesi -liikelaitos (jäljempänä myös \"Hankintayksikkö\") pyytää osallistumishakemuksia hankintailmoituksen ja sen liitteiden mukaisesti Hinttaan rakennettavan uuden pintavesilaitoksen laajennuksen pääurakasta kilpailullisella neuvottelumenettelyllä. Hankinnan kohteena on Hinttaan rakennettavan uuden pintavesilaitoksen laajennuksen pääurakka. Hankinnan tavoitteena on turvata Oulun kaupungin talousveden riittävyys ja vesihuollon toimintavarmuus sekä mahdollistaa nykyisen vesilaitoksen perusparantaminen. Urakkamuotona on kokonaisurakka. Hintan pintavesilaitos laajennushanke sisältää suunnitelmien mukaan pintavesilaitoksen rakentamisen kokonaisurakkana. Pintavesilaitos rakennetaan käyttökuntoon saatettuna kokonaisurakassa. Pintavesilaitoslaajennushanke sisältää vesilaitosrakennuksen, maanalaisen tunnelin ja alavesisäiliörakennuksen rakentamisen. Bruttoneliöt: n. 12 000 m². Urakka sisältää muun muassa poikkeuksellisen vaativia maa- ja pohjarakentamisen töitä, vesitiiviiden allas- ja betonirakenteiden, prosessi- ja talotekniikan, putkistojen sekä yhdystunnelin rakentamisen. Uusi laitoskokonaisuus rakennetaan olemassa olevan pintavesilaitoksen viereen. Lisäksi hankinnan kohteena voivat olla lisätyöt, joiden tarve käy ilmi töitä suoritettaessa. Hankkeeseen liittyvä automaatiourakka hankitaan erikseen, ja kyseinen urakka alistetaan tämän osallistumispyynnön kohteena olevaan pääurakkaan. Hankinnan kohteena olevien töiden on suunniteltu käynnistyvän maaliskuun puolivälissä 2027, ja laitoksen on oltava käyttöönottovalmiudessa vuoden 2029 loppuun mennessä. Laitoksen on oltava käytössä ja luovutettu 30.6.2030 mennessä. Hankinnan ja hankkeen kieli on suomi. Hankkeeseen tarjottavilta henkilöiltä edellytetään erinomaista suomen kielen taitoa.,','Oulun kaupunki','ANY',5,5,NULL,NULL,50000000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056600','[\"45000000\"]','[\"pintavesilaitoksen\", \"hankinnan\", \"oulun\", \"kohteena\", \"hintan\", \"pääurakka\", \"sisältää\", \"rakentamisen\", \"osallistumispyyntö\", \"laajennushankkeen\", \"hinttaan\", \"rakennettavan\", \"uuden\", \"laajennuksen\", \"pintavesilaitos\", \"rakennetaan\", \"urakka\", \"töitä\", \"hankkeeseen\", \"laitoksen\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/ouka?id=613446&tpk=19c91723-779b-4c8b-bf33-753b6258cf48\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056600\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56600\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Osallistumispyyntö: Hintan pintavesilaitoksen laajennushankkeen pääurakka\", \"titleSv\": \"\", \"cpvCodes\": \"45000000\", \"currency\": \"EUR\", \"deadline\": \"2026-09-10T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1D9\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"Oulun vesi -liikelaitos (jäljempänä myös \\\"Hankintayksikkö\\\") pyytää osallistumishakemuksia hankintailmoituksen ja sen liitteiden mukaisesti Hinttaan rakennettavan uuden pintavesilaitoksen laajennuksen pääurakasta kilpailullisella neuvottelumenettelyllä.\\n\\nHankinnan kohteena on Hinttaan rakennettavan uuden pintavesilaitoksen laajennuksen pääurakka. Hankinnan tavoitteena on turvata Oulun kaupungin talousveden riittävyys ja vesihuollon toimintavarmuus sekä mahdollistaa nyky