INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16276,'2026-056595','HILMA','RFP','OPEN','Espoon kulttuurikeskuksen teatteri','Espoon kulttuurikeskuksen teatteri Espoon kaupungin Tilapalvelut-liikelaitos (myöhemmin Tilaaja) pyytää tarjouksia hankinnan kohteena olevan Espoon kulttuurikeskuksen teatterin toteuttamiseen yhteistoiminnallisena projektinjohtourakkana (YPJU) tavoitehinnalla Tapiolassa. Urakka jakautuu Kehitysvaiheeseen ja Toteutusvaiheeseen. Projektinjohtourakoitsija toimii hankkeessa pääurakoitsijana ja vastaa kokonaisvaltaisesti hankkeen toteutuksen johtamisesta, hankintojen kilpailuttamisesta, työmaan johtamisesta sekä eri osapuolten yhteensovittamisesta sopimusasiakirjojen, sekä hankkeen aikataulun mukaisesti sekä osallistuu kehitysvaiheessa suunnitelmien tarkastukseen ja optimointiin yhdessä Tilaajan ja suunnittelijoiden kanssa. Urakka jakautuu Kehitysvaiheeseen ja Toteutusvaiheeseen. Kehitysvaiheen (alustavasti tammi–huhtikuu 2027, kesto noin 3–4 kk) aikana projektinjohtourakoitsija sitoutetaan hankkeeseen, suunnitelmat tarkastetaan ja optimoidaan yhdessä Tilaajan ja suunnittelijoiden kanssa, hankkeen riskit kartoitetaan ja Toteutusvaiheen Tavoitehinta vahvistetaan. Toteutusvaiheessa (alustavasti huhtikuu 2027 alkaen, urakka-aika 30 kk) toteutetaan hankkeeseen liittyvät työt Kehitysvaiheessa tehtyjen päätösten ja suunnitteluratkaisujen pohjalta. Kulttuurikeskuksen teatterin vastaanotto on alustavasti tarkoitus tapahtua 11/2029. Tilaajalla on oikeus olla tekemättä Toteutusvaiheen Tilausta Kehitysvaiheen päätteeksi. Tilaajan ja PJU:n yhteisenä tavoitteena on edetä Toteutusvaiheen Tilaukseen. Toteutusvaiheen tilaamatta jättäminen (”exit”) on viimesijainen vaihtoehto. Urakka käsittää uuden teatterin rakentamisen, siihen liittyvät muutostyöt nykyisessä kulttuurikeskuksessa sekä Kulttuuriaukion alueelle kohdistuvat rakennustyöt. Toteutus tapahtuu osittain toiminnassa olevan kulttuurikeskuksen yhteydessä, mikä edellyttää erityistä huomiota työmaan vaiheistukseen, turvallisuuteen sekä käyttäjätoiminnan häiriöttömään jatkumiseen. Hankkeen tavoitteena on mahdollistaa Espoon kaupunginteatterin toiminnan keskittäminen Espoon kulttuurikeskuksen yhteyteen ja korvata nykyinen Revontulihalli. Samalla kehitetään kulttuurikeskuksen toiminnallisuutta ja parannetaan Tapiolan kulttuuriympäristön vetovoimaa. Hanke sisältää muun muassa: • noin 500–700-paikkaisen muuntojoustavan teatterisalin, joka mahdollistaa erilaisten esitysmuotojen toteuttamisen • näyttämö-, harjoitus- ja tuotantotilat, jotka tukevat teatterin operatiivista toimintaa • yleisötilat ja palvelut, kuten aulat, ravintolatilat ja muut asiakaspalvelutoiminnot • logistiikka- ja huoltotilat, mukaan lukien lastaus- ja kuljetusjärjestelyt • vaativat esitys- ja talotekniset järjestelmät, joiden toteutus, yhteensovitus, testaus ja käyttöönotto ovat keskeinen osa hanketta Projektinjohtourakkaan sisältyvät lisäksi kaikki hankkeen toteuttamisen edellyttämät johtamis-, ohjaus-, koordinointi- ja työmaatehtävät, rakennus- ja talotekniset työt sekä hankintojen toteutus siten, että lopputulos täyttää asetetut laatu-, toiminnallisuus-, kustannus- ja aikataulutavoitteet. Hankinnan tarkempi sisältö on kuvattu tämän tarjouspyynnön liitteissä olevassa hankinnan tarjouspyynnössä sekä, sen muissa liitteissä (kts. ilmoituksen kohta liitteet ja linkit) TUTUSTUMISKÄYNTI: Tilaaja edellyttää Tarjoajan osallistuvan tilaajan järjestämälle pakolliselle tutustumiskäynnille ennen tarjoamista. Pakollinen tutustumiskäynti järjestetään 1.9. klo 10. Kohde on osoitteessa Kulttuurinaukio 2 Espoo. Tilaaja hylkää tarjouksen, mikäli tarjoaja ei ole tutustunut kohteeseen Tilaajan järjestämällä tutustumiskäynnillä. Tutustumiskäynnille tulee ilmoittautua etukäteen 31.8. klo 14 mennessä. Ilmoittautuminen tehdään sähköpostitse Jani Kerviselle (jani.kervinen@boostbrothers.fi) ja Markus Salinille (markus.salin@espoo.fi). Ilmoittautuneille toimitetaan tarkemmat saapumisohjeet sähköpostitse. Kohdekäynnin kesto on noin yksi (1) tunti. Tilaisuudessa ei anneta lisätietoja hankintaan liittyen. Mahdolliset kysymykset tulee esittää tarjouspyynnössä määritellyn kysymysten jättöajan puitteissa.,','Espoon kaupunki','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056595','[\"45000000\"]','[\"espoon\", \"kulttuurikeskuksen\", \"hankkeen\", \"tilaajan\", \"teatterin\", \"urakka\", \"toteutusvaiheen\", \"tilaaja\", \"hankinnan\", \"alustavasti\", \"noin\", \"toteutus\", \"teatteri\", \"olevan\", \"jakautuu\", \"kehitysvaiheeseen\", \"toteutusvaiheeseen\", \"projektinjohtourakoitsija\", \"johtamisesta\", \"hankintojen\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/espoo?id=614397&tpk=bd4b92cd-1a90-428b-b23b-d6510ada4bc4\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056595\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56595\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Espoon kulttuurikeskuksen teatteri\", \"titleSv\": \"\", \"cpvCodes\": \"45000000\", \"currency\": null, \"deadline\": \"2026-10-22T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Espoon kaupungin Tilapalvelut-liikelaitos (myöhemmin Tilaaja) pyytää tarjouksia hankinnan kohteena olevan Espoon kulttuurikeskuksen teatterin toteuttamiseen yhteistoiminnallisena projektinjohtourakkana (YPJU) tavoitehinnalla Tapiolassa. Urakka jakautuu Kehitysvaiheeseen ja Toteutusvaiheeseen. Projektinjohtourakoitsija toimii hankkeessa pääurakoitsijana ja vastaa kokonaisvaltaisesti hankkeen toteutuksen johtamisesta, hankintojen kilpailuttamisesta, työmaan johtamisesta sekä eri osapuolten yhteensovittamisesta sopimusasiakirjojen, sekä hankkeen aikataulun mukaisesti sekä osallistuu kehitysvaiheessa suunnitelmien tarkastukseen ja optimointiin yhdessä Tilaajan ja suunnittelijoiden kanssa.\\n\\nUrakka jakautuu Kehitysvaiheeseen ja Toteutusvaiheeseen. Kehitysvaiheen (alustavasti tammi–huhtikuu 2027, kesto noin 3–4 kk) aikana projektinjohtourakoitsija sitoutetaan hankkeeseen, suunnitelmat tarkastetaan ja optimoidaan yhdessä Tilaajan ja suunnittelijoiden kanssa, hankkeen riskit kartoitetaan ja Toteutusvaiheen Tavoitehinta vahvistetaan. Toteutusvaiheessa (alustavasti huhtikuu 2027 alkaen, urakka-aika 30 kk) toteutetaan hankkeeseen liittyvät työt Kehitysvaiheessa tehtyjen päätösten ja suunnitteluratkaisujen pohjalta. Kulttuurikeskuksen teatterin vastaanotto on alustavasti tarkoitus tapahtua 11/2029. Tilaajalla on oikeus olla tekemättä Toteutusvaiheen Tilausta Kehitysvaiheen päätteeksi. Tilaajan ja PJU:n yhteisenä tavoitteena on edetä Toteutusvaiheen Tilaukseen. Toteutusvaiheen tilaamatta jättäminen (”exit”) on viimesijainen vaihtoehto.\\n\\nUrakka käsittää uuden teatterin rakentamisen, siihen liittyvät muutostyöt nykyisessä kulttuurikeskuksessa sekä Kulttuuriaukion alueelle kohdistuvat rakennustyöt. Toteutus tapahtuu osittain toiminnassa olevan kulttuurikeskuksen yhteydessä, mikä edellyttää erityistä huomiota työmaan vaiheistukseen, turvallisuuteen sekä käyttäjätoiminnan häiriöttömään jatkumiseen.\\n\\nHankkeen tavoitteena on mahdollistaa Espoon kaupunginteatterin toiminnan keskittäminen Espoon kulttuurikeskuksen yhteyteen ja korvata nykyinen Revontulihalli. Samalla kehitetään kulttuurikeskuksen toiminnallisuutta ja parannetaan Tapiolan kulttuuriympäristön vetovoimaa.\\n\\nHanke sisältää muun muassa:\\n• noin 500–700-paikkaisen muuntojoustavan teatterisalin, joka mahdollistaa erilaisten esitysmuotojen toteuttamisen \\n• näyttämö-, harjoitus- ja tuotantotilat, jotka tukevat teatterin operatiivista toimintaa \\n• yleisötilat ja palvelut, kuten aulat, ravintolatilat ja muut asiakaspalvelutoiminnot \\n• logistiikka- ja huoltotilat, mukaan lukien lastaus- ja kuljetusjärjestelyt \\n• vaativat esitys- ja talotekniset järjestelmät, joiden toteutus, yhteensovitus, testaus ja käyttöönotto ovat keskeinen osa hanketta \\n\\nProjektinjohtourakkaan sisältyvät lisäksi kaikki hankkeen toteuttamisen edellyttämät johtamis-, ohjaus-, koordinointi- ja työmaatehtävät, rakennus- ja talotekniset työt sekä hankintojen toteutus siten, että lopputulos täyttää asetetut laatu-, toiminnallisuus-, kustannus- ja aikataulutavoitteet.\\nHankinnan tarkempi sisältö on kuvattu tämän tarjouspyynnön liitteissä olevassa hankinnan tarjouspyynnössä sekä, sen muissa liitteissä (kts. ilmoituksen kohta liitteet ja linkit)\\n\\nTUTUSTUMISKÄYNTI: \\nTilaaja edellyttää Tarjoajan osallistuvan tilaajan järjestämälle pakolliselle tutustumiskäynnille ennen tarjoamista. Pakollinen tutustumiskäynti järjestetään 1.9. klo 10. Kohde on osoitteessa Kulttuurinaukio 2  Espoo. Tilaaja hylkää tarjouksen, mikäli tarjoaja ei ole tutustunut kohteeseen Tilaajan järjestämällä tutustumiskäynnillä.\\n\\nTutustumiskäynnille tulee ilmoittautua etukäteen 31.8. klo 14 mennessä. Ilmoittautuminen tehdään sähköpostitse Jani Kerviselle (jani.kervinen@boostbrothers.fi) ja Markus Salinille (markus.salin@espoo.fi).\\n\\nIlmoittautuneille toimitetaan tarkemmat saapumisohjeet sähköpostitse. Kohdekäynnin kesto on noin yksi (1) tunti.\\n\\nTilaisuudessa ei anneta lisätietoja hankintaan liittyen. Mahdolliset kysymykset tulee esittää tarjouspyynnössä määritellyn kysymysten jättöajan puitteissa.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-10-22T09:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, 