INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16278,'2026-056592','HILMA','RFP','OPEN','Matkustajalaskentalaitteiden sekä niihin liittyvien asennus-, ylläpito- ja tukipalvelujen hankinta','Matkustajalaskentalaitteiden sekä niihin liittyvien asennus-, ylläpito- ja tukipalvelujen hankinta Oulun kaupunki pyytää tarjouksia Oulun seudun liikenteen matkustajalaskentalaitteiden sekä niihin liittyvien asennus-, ylläpito- ja tukipalveluiden hankinnasta Hankinnan kohteena on Oulun seudun liikenteen (OSL) joukkoliikennekalustoon asennettavien matkustajalaskentalaitteiden sekä niihin liittyvien asennus-, ylläpito-, tukipalvelu- ja raportointipalveluiden toimittaminen. Hankintaan sisältyy matkustajamäärätiedon kerääminen, siirtäminen ja raportointi tilaajan käyttöön tarjouspyynnön ja sopimusasiakirjojen mukaisesti. Tavoitteena on tuottaa luotettavaa matkustajadataa joukkoliikenteen suunnittelun, seurannan ja kehittämisen tueksi. Hankinnan ensimmäisessä vaiheessa matkustajalaskentalaitteet asennetaan 40 kappaleeseen Oulun seudun liikenteen kolmiovisia BYD-merkkisiä sähkölinja-autoja. Tilaaja voi sopimuskauden aikana laajentaa järjestelmän käyttöä myös muuhun kalustoon tarjouspyynnön ja sopimuksen ehtojen mukaisesti.,','Oulun kaupunki','ANY',4,5,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056592','[\"30144000\", \"72250000\"]','[\"oulun\", \"matkustajalaskentalaitteiden\", \"niihin\", \"liittyvien\", \"asennus\", \"ylläpito\", \"kaupunki\", \"seudun\", \"liikenteen\", \"tukipalvelujen\", \"hankinta\", \"hankinnan\", \"tarjouspyynnön\", \"mukaisesti\", \"pyytää\", \"tarjouksia\", \"tukipalveluiden\