INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16281,'2026-056589','HILMA','OTHER','OPEN','Turvallisuus- ja aulapalvelut','Turvallisuus- ja aulapalvelut Hankinnan kohteena oli Aalto-yliopiston turvallisuus- ja aulapalveluita koskeva hankintakokonaisuus. Kokonaisuus sisälsi ulkoa ostettavat aula-, paikallisvartiointi-, järjestyksenvalvonta-, piirivartiointi-, hälytysvalvonta- ja hälytysvartiointipalvelut sekä Aalto-Apua -palvelun tarjouspyynnössä kuvatun mukaisesti. Selvyyden vuoksi todetaan, että Aalto-yliopiston omat vahtimestaripalvelut eivät kuuluneet hankinnan piiriin. Kilpailutuksella Aalto-yliopisto etsi palvelutoimittajaa, joka pystyisi toteuttamaan hankintailmoituksessa kuvatun palvelukokonaisuuden laadukkaasti ja kokonaistaloudellisesti, Aalto-yliopiston toimintaympäristön luonne ja erityispiirteet huomioiden. Tavoitteena oli löytää kumppani, jonka kanssa Aalto-yliopisto pystyisi yhteistyössä varmistamaan korkeatasoisen palvelutuotannon ja kehittämään palveluiden laatua koko sopimuskauden ajan. Hankinnan kohteena ollut palvelu ja sitä koskevat vähimmäisvaatimukset kuvattiin tarkemmin tarjouspyyntöasiakirjoissa. Laatu oli huomioitu tarjouspyyntöasiakirjoissa palvelulle asetetuissa korkeissa vähimmäisvaatimuksissa.,','Aalto University Foundation sr','ANY',6,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056589','[\"79710000\", \"79713000\"]','[\"aalto\", \"turvallisuus\", \"hankinnan\", \"yliopiston\", \"aulapalvelut\", \"kohteena\", \"kuvatun\", \"yliopisto\", \"pystyisi\", \"tarjouspyyntöasiakirjoissa\", \"aulapalveluita\", \"koskeva\", \"hankintakokonaisuus\", \"kokonaisuus\