INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16285,'2026-056581','HILMA','OTHER','OPEN','Mulby Åminne kadut ja Grigor Auerin polku','Mulby Åminne kadut ja Grigor Auerin polku Urakan kohteena on katujen ja vesihuollon rakennustöitä sekä tukimuurien ja paalulaattojen rakennustöitä. Työt tehdään katualueella yleisen liikenteen parissa. Työt on toteutettava niin, ettei yleistä liikennettä vaaranneta eikä kohtuuttomasti haitata. Urakka koskee Åminnenrannan, Aavasaksanpolun, Vesikelkantien, Vionojantien, Pulkkatien, Uraalinpolun, Rannikontien, Koikorvenpolun, Kurtinmäenkujan, Mulbynmäen, Viirukallionpolun, Kurtinmäentaipaleen, Kurtinmäentien, Åminnentien ja Åminnenmäen katuja. Lisäksi alueeseen kuuluu Arpaonnenkujan ja Koikorvenpolun välille tulevat maastoportaat. Uraalinrinteen VL-alueelle on toteutettu raitti erillisessä urakassa. Raitin liitostyöt katuun (Åminnentie, Pulkkatie) viimeistellään katu-urakassa. Lisäksi urakkaan sisältyy Grigor Auerin polun rakentaminen. Kohde sijaitsee Kurttilan kaupunginosassa. Kyseessä on uusi puistoraitti, joka liittyy pohjoisosassa rakennettuun katuun (Kaskimäki) ja eteläosassa rakennettuun puistoraittiin (Lambronpolku). Puistoraitin lisäksi urakassa rakennetaan hulevesiviemäriä sekä raitin valaistus. Työalueeseen kuluu myös risteävien ja liittyvien katujen ja puistoraittien työt rakenteiden liittämisen edellyttämässä laajuudessa. Kohteessa kaadetaan puita, tehdään maaleikkaus- ja louhintatöitä, vesihuollon kaivantotöitä, teräsponttiseinien lyöntiä, paalutus- ja paalulaattatöitä, pilaristabilointia, penkereiden ja rakennekerrosten täyttötöitä sekä uuden katupäällysteen kivi- ja asfaltointitöitä. Huomiota kiinnitetään myös urakassa käytettävien luonnonkiveysmateriaalien päästöarvoihin. Urakassa käytetään Infrakit-projektipankkia, tietomalleja ja koneohjausta.,','Espoon kaupunki / Kaupunkitekniikan keskus','ANY',2,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056581','[\"45200000\"]','[\"urakassa\", \"grigor\", \"auerin\", \"työt\", \"lisäksi\", \"mulby\", \"åminne\", \"kadut\", \"polku\", \"katujen\", \"vesihuollon\", \"rakennustöitä\", \"tehdään\", \"koikorvenpolun\", \"raitin\", \"katuun\", \"rakennettuun\", \"urakan\", \"kohteena\", \"tukimuurien\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056581\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56581\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Mulby Åminne kadut ja Grigor Auerin polku\", \"titleSv\": \"\", \"cpvCodes\": \"45200000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": true, \"nutsCodes\": \"\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Urakan kohteena on katujen ja vesihuollon rakennustöitä sekä tukimuurien ja paalulaattojen rakennustöitä. Työt tehdään katualueella yleisen liikenteen parissa. Työt on toteutettava niin, ettei yleistä liikennettä vaaranneta eikä kohtuuttomasti haitata.\\nUrakka koskee Åminnenrannan, Aavasaksanpolun, Vesikelkantien, Vionojantien, Pulkkatien, Uraalinpolun, Rannikontien, Koikorvenpolun, Kurtinmäenkujan, Mulbynmäen, Viirukallionpolun, Kurtinmäentaipaleen, Kurtinmäentien, Åminnentien ja Åminnenmäen katuja.\\n\\nLisäksi alueeseen kuuluu Arpaonnenkujan ja Koikorvenpolun välille tulevat maastoportaat. Uraalinrinteen VL-alueelle on toteutettu raitti erillisessä urakassa. Raitin liitostyöt katuun (Åminnentie, Pulkkatie) viimeistellään katu-urakassa.\\nLisäksi urakkaan sisältyy Grigor Auerin polun rakentaminen. Kohde sijaitsee Kurttilan kaupunginosassa. Kyseessä on uusi puistoraitti, j