INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16288,'2026-056575','HILMA','RFI','OPEN','Tietopyyntö: Sähköautojen RFID-tunnistepohjainen latauspalvelu','Tietopyyntö: Sähköautojen RFID-tunnistepohjainen latauspalvelu TÄMÄ EI OLE HANKINTAILMOITUS, EIKÄ TARJOUSPYYNTÖ, VAAN TIETOPYYNTÖ MAHDOLLISILLE TARJOAJILLE. Varsinais-Suomen hyvinvointialue selvittää markkinoilla olevia ratkaisuja, joissa sähköauton lataaminen voidaan tunnistaa fyysisellä tunnisteella (RFID-tunniste) ilman käyttäjän henkilökohtaista maksukorttia tai mobiilisovellusta. Lataustapahtumat tulee voida laskuttaa keskitetysti jälkikäteen tilaajalta. Ratkaisun tulisi soveltua usean käyttäjän ja usean ajoneuvon käyttöympäristöön siten, että tunnisteet ovat tilaajan keskitetysti hallinnoitavissa eikä niiden käyttö ole sidottu yksittäiseen käyttäjään. Lisäksi tavoitteena on selvittää ratkaisuja, jotka mahdollistavat lataamisen laajasti eri latausoperaattoreiden ja latausverkostojen latausasemilla. Tarkoituksena on selvittää, onko tarjoajilla mahdollisuus tarjota palvelukokonaisuutta pyydetyillä ehdottomilla vaatimuksilla. Pyydämme antamaan vastaukset Liitteen 1 Tietopyyntö_ Sähköautojen_RFID-tunnistepohjainen_latauspalvelu kysymyksiin 23.9.2026 klo 12.00 mennessä. Voitte liittää vastaukseenne myös esitteitä. Täytetty vastausliite sekä mahdolliset esitteet voidaan toimittaa joko vastaamalla tietopyyntöön tai lähettämällä aineisto sähköpostitse osoitteeseen tavarahankinnat@varha.fi otsikolla ”Sähköautojen RFID-tunnistepohjainen latauspalvelu”. Vastausten yhteydessä pyydetään ilmoittamaan niiden mahdollisesti sisältämät liikesalaisuustiedot, jotka käsitellään luottamuksellisesti. Viranomaiselle toimitettujen tietojen ja asiakirjojen julkisuuteen sovelletaan lakia viranomaisen toiminnan julkisuudesta (21.5.1999/621). Tämä ilmoitus ei ole tarjouspyyntö. Tämä ilmoitus on kutsu markkinavuoropuheluun, jonka tarkoituksena on kartoittaa markkinoilla toimivien toimittajien ratkaisuvaihtoehtoja. Tietopyyntöön voi vastata, vaikka jokin tietopyynnössä kuvatuista toiminnoista ei täyty. Kuvaa tällöin lisätietoja-kohtaan, mikä kohta ei täyty ja miten omassa sähköautojen latauksen palvelussanne asia on ratkaistu. Tässä tietopyynnössä annetut tiedot ja vastaukset eivät sido niiden antajaa. Vasta mahdollisen tarjouspyynnön perusteella annetussa tarjouksessa ilmoitetut tiedot ovat tarjoajaa sitovia. Tämä ilmoitus ei velvoita hankintayksikköä toteuttamaan hankintaa. Hankintayksikkö ei korvaa mahdollisia kustannuksia, jotka aiheutuvat markkinavuoropuheluun osallistumisesta.,','Varsinais-Suomen hyvinvointialue','ANY',3,1,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056575','[\"09310000\", \"63712600\"]','[\"sähköautojen\", \"rfid\", \"tietopyyntö\", \"tunnistepohjainen\", \"latauspalvelu\", \"tämä\", \"selvittää\", \"niiden\", \"jotka\", \"ilmoitus\", \"eikä\", \"tarjouspyyntö\", \"varsinais\", \"suomen\", \"hyvinvointialue\", \"markkinoilla\", \"ratkaisuja\", \"voidaan\", \"käyttäjän\", \"keskitetysti\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/varsinaissuomenhva?id=627259&tpk=d53d2aa4-c4ca-4aee-a3ba-ca00df73ae14\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056575\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56575\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Tietopyyntö: Sähköautojen RFID-tunnistepohjainen latauspalvelu\", \"titleSv\": \"\", \"cpvCodes\": \"09310000 63712600\", \"currency\": null, \"deadline\": \"2026-09-23T09:00:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"FI1C1\", \"titleOther\": \"\", \"biodivers