INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16289,'2026-056573','HILMA','RFP','OPEN','Perusterveydenhuollon lääkinnällisten pienlaitteiden kilpailutus (Syksy2026)','Hankinnan kohteena olevien laitteiden tulee soveltua terveydenhuollon ammattikäyttöön. Tilaaja ostaa osa-aluekohtaisesti hankinnan kohteena olevat laitteet valituksi tulleelta Toimittajalta ostomallilla ja tarjoaa niitä edelleen laitepalveluna omille asiakkailleen. Hankinnan kohteena olevien laitteiden vähimmäisvaatimukset ja vähimmäisvaatimuksien ylittävin osin pisteytettävät ominaisuudet sekä hintavertailuun vaikuttavat tekijät on kuvattu tarkemmin osa-aluekohtaisissa liitteissä ”Vaatimusmäärittely + vertailutiedot\" Hankinta on jaettu seuraaviin osa-alueisiin: 1. Osa-alue | Verenpainemittarit; automaattinen 2. Osa-alue | Verenpainemittari, automaattinen: yli 3 vuotiaalle soveltuva 3. Osa-alue | Verenpainemittari, mekaaninen 4. Osa-alue | Korvakuumemittari, digitaalinen Tarjoaja voi jättää tarjouksen mihin tahansa (yhteen) osa-alueeseen, useampaan tai kaikkiin osa-alueisiin oman harkintansa mukaisesti. Yksittäisen osa-alueen sisällä rinnakkaistarjouksen jättäminen ei ole sallittua. Vaihtoehtoiset tarjoukset eivät ole sallittuja. Tilaaja valitsee hankinnan osa-aluekohtaisesti yhden (1) toimittajan, jonka kanssa se tekee hankintasopimuksen. Hankintasopimusta tulee käyttämään ainoastaan Istekki Oy ja syntyvän sopimuksen osapuolina ovat ainoastaan Istekki Oy ja valittu Toimittaja. Selvyyden vuoksi todetaan, että Istekin asiakkaat eivät ole tämän kilpailutuksen tai sen perusteella tehtävän hankintasopimuksen sopijapuolia. Tarjouspyynnössä ja sen liitteissä esitetyt hankintamäärät ovat arvioita, eikä sopimus muodosta tilaajalle määräostovelvoitetta., 1. Osa-alue | Verenpainemittarit; automaattinen Verenpainemittarit; automaattinen, 2. Osa-alue | Verenpainemittari, automaattinen: yli 3 vuotiaalle soveltuva Verenpainemittari, automaattinen: yli 3 vuotiaalle soveltuva, 3. Osa-alue | Verenpainemittari, mekaaninen Verenpainemittari, mekaaninen, 4. Osa-alue | Korvakuumemittari, digitaalinen Korvakuumemittari, digitaalinen,','Istekki Oy','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056573','[\"33100000\"]','[\"alue\", \"automaattinen\", \"verenpainemittari\", \"hankinnan\", \"istekki\", \"kohteena\", \"verenpainemittarit\", \"vuotiaalle\", \"soveltuva\", \"mekaaninen\", \"korvakuumemittari\", \"digitaalinen\", \"olevien\", \"laitteiden\", \"tulee\", \"tilaaja\", \"aluekohtaisesti\", \"liitteissä\", \"alueisiin\", \"eivät\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/istekki?id=617538&tpk=a9a773e5-a0d4-4f34-bd28-091fb12fce2e\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056573\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56573\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"1. Osa-alue | Verenpainemittarit; automaattinen\", \"titleSv\": \"\", \"cpvCodes\": \"33100000\", \"currency\": null, \"deadline\": \"2026-10-13T20:59:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": true, \"descriptionEn\": \"\", \"descriptionFi\": \"Verenpainemittarit; automaattinen\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-10-13T20:59:00Z\", \"circularEconomy\": true, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innov