INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16290,'2026-056571','HILMA','RFP','OPEN','Henkilöstövuokrauspalvelut, Jätekukko Oy','Henkilöstövuokrauspalvelut, Jätekukko Oy Hankinnan kohteena on henkilöstövuokrauspalvelu, jossa toimittaja tuottaa soveltuvat työntekijät lajitteluaseman operatiivisiin tukitehtäviin Jätekukon uudelle lajitteluasemalle Kuopion Matkukseen ja Kuopion lajitteluasemalle tehtäväkuvausten mukaisesti. Lajitteluasemalla tehtävä työ on asiakaspalvelutyötä lajitteluasemanhoitajien apuna, joka kattaa asiakkaiden ja jätteiden vastaanoton ja ohjauksen sekä alueen turvallisuuden ja siisteyden tarjousasiakirjojoissa esitetyn mukaisesti. Sopimus on voimassa määräaikaisena yhden (1) vuoden ajalla 1.12.2026- 30.11.2027. Tämän jälkeen sopimus jatkuu toistaiseksi voimassa olevana. Hankinnan arvioitu arvo on 300 000 euroa. Hankinta on kokonaisuus ja osatarjouksia ei hyväksytä. Hankintaa ei ole jaettu osiin, koska se ei ole hankinnan luonteen perusteella tarkoituksenmukaista. Sopimukseen valitaan yksi (1) toimittaja.,','Sansia Oy','ANY',5,14,NULL,NULL,300000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056571','[\"79600000\", \"79620000\"]','[\"hankinnan\", \"henkilöstövuokrauspalvelut\", \"jätekukko\", \"toimittaja\", \"lajitteluasemalle\", \"kuopion\", \"mukaisesti\", \"sopimus\", \"voimassa\", \"sansia\", \"kohteena\", \"henkilöstövuokrauspalvelu\", \"jossa\", \"tuottaa\", \"soveltuvat\", \"työntekijät\", \"lajitteluaseman\", \"operatiivisiin\", \"tukitehtäviin\", \"jätekukon\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/sansia?id=613590&tpk=0b4df6d5-d293-4510-b867-7d3a47117b41