INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16292,'2026-056566','HILMA','OTHER','OPEN','Kierrätysperusteisen dieselpolttoaineen hankinta','Kierrätysperusteisen dieselpolttoaineen hankinta Tarjouspyyntö käsittää jäte- ja kierrätysmateriaalista 100-%:sti valmistettavan uusiutuvan diesel-polttoaineen hankinnan hankintayksikön tarpeisiin. Arvioitu vuosikulutus on n. 800 000 litraa vuodessa. Hankintayksikkö ei kuitenkaan sitoudu tiettyyn hankintamäärään. Hankintayksikön omistaja, Porin kaupunki, liittyi mukaan Kohti hiilineutraalia kuntaa -hankkeeseen vuonna 2016 ja on sitoutunut tavoittelemaan 80 prosentin päästövähennystä vuoteen 2030 mennessä vuoden 2007 tasosta. Tarjouspyynnöllä hankittavan dieselpolttoaineen hankinta on osa Porin kaupungin ja Porin Linjat Oy:n käytännön toimia toteuttaa em. hankkeen tavoitteita. Tarjouspyyntöön sisältyy hankintayksikön varaus pidättäytyä hankinnasta, mikäli yhtiön omistaja ei vahvista hankinnan edellyttämää lisämäärärahaa.,','Porin Linjat Oy','ANY',5,9,NULL,NULL,4500000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056566','[\"09100000\"]','[\"porin\", \"dieselpolttoaineen\", \"hankinta\", \"hankintayksikön\", \"linjat\", \"kierrätysperusteisen\", \"hankinnan\", \"omistaja\", \"tarjouspyyntö\", \"käsittää\", \"jäte\", \"kierrätysmateriaalista\", \"valmistettavan\", \"uusiutuvan\", \"diesel\", \"polttoaineen\", \"tarpeisiin\", \"arvioitu\", \"vuosikulutus\", \"litraa\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056566\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56566\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"t