INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16294,'2026-056562','HILMA','RFP','OPEN','Kokonaisurakka, peruskorjaus, Helsinki, Heka Itäkeskus Asiakkaankatu 4','Kokonaisurakka, peruskorjaus, Helsinki, Heka Itäkeskus Asiakkaankatu 4 Hankinnan kohteena on Helsingin Itäkeskuksessa sijaitsevien asuinkerrostalojen peruskorjaus kiinteähintaisena kokonaisurakkana sisältäen rakennusteknisten töiden lisäksi kaikki LVISA-työt. Peruskorjauksen kohteena on Helsingin kaupungin asunnot Oy:n omistama vuokratalokohde, joka sijaitsee Helsingin kaupungin tontilla 45053/1 (Asiakkaankatu 4, 00930 Helsinki) Urakan arvioitu alkamisajankohta on 01.02.2027 ja rakentamisen arvioitu alkamisajankohta 03/2027. Hankintaa ei jaeta osiin, sillä usean toimittajan malli tuottaisi epätarkoituksenmukaisen sopimuskokonaisuuden aikataulunhallinnan sekä töiden yhteensovittamisen kannalta. Ennen hankintailmoituksen julkaisua hankintayksikkö on tehnyt markkinakartoituksen. Markkinakartoitus on perustunut toistuvien vastaavanlaisten hankintojen systemaattiseen analyysiin ja alan toimittajien kanssa ylläpidettävään vuorovaikutukseen. PERUSKORJAUSHANKKEEN TIETOJA - Kohde on valmistunut vuonna 1977 - Kohteessa on kaksi asuinkerrostaloa, kaksi autokatosta ja jätekatos. - Asuinkerrostaloissa on 3-5 asuinkerrosta ja molemmissa rakennuksissa on neljä porrashuonetta. - Tällä hetkellä vuokra-asuntoja on yhteensä 96 kpl ja peruskorjauksen jälkeen vuokra-asuntoja tulee olemaan 99 kpl (n. 5 597 asm2) PERUSKORJAUKSEN TOTEUTUS - Urakka on lähtökohtaisesti on suunniteltu tehtäväksi yhdessä vaiheessa. Vaiheistusta voidaan täsmentää yhteisellä sopimuksella, mikäli muu vaiheistus on urakan näkökulmasta perusteltua. - Asukkaat muuttavat korjaustöiden ajaksi sijaisasuntoihin. Urakka alkaa asukkaiden poismuutoilla. Pois- ja takaisinmuutot sisältyvät urakkaan. Hankinnan kohde on tarkemmin kuvattu tarjouspyynnön liitteenä olevissa kaupallisissa ja teknisissä asiakirjoissa. Liiteasiakirjat löytyvät julkaisun Tarjouspalvelu-sivuilta kohdassa \"Liitteet ja linkit\".,','Helsingin kaupunki, kaupunkiympäristön toimiala, asuntotuotanto','SME',5,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056562','[\"45000000\"]','[\"helsingin\", \"peruskorjaus\", \"helsinki\", \"asiakkaankatu\", \"peruskorjauksen\", \"kokonaisurakka\", \"heka\", \"itäkeskus\", \"hankinnan\", \"kohteena\", \"töiden\", \"kaupungin\", \"urakan\", \"arvioitu\", \"alkamisajankohta\", \"kohde\", \"kaksi\", \"vuokra\", \"asuntoja\", \"urakka\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/helsinki?id=624960&tpk=ae691433-73fa-4624-a9cb-4d086dd647ff\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056562\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56562\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Kokonaisurakka, peruskorjaus, Helsinki, Heka Itäkeskus Asiakkaankatu 4\", \"titleSv\": \"\", \"cpvCodes\": \"45000000\", \"currency\": null, \"deadline\": \"2026-10-05T09:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Hankinnan kohteena on Helsingin Itäkeskuksessa sijaitsevien asuinkerrostalojen peruskorjaus kiinteähintaisena kokonaisurakkana sisältäen rakennusteknisten töiden lisäksi kaikki LVISA-työt. \\n\\nPeruskorjauksen kohteena on Helsingin kaupungin asunnot Oy:n omistama vuokratalokohde, joka sijaitsee Helsingin kaupungin tontilla 45053/1 (Asiakkaankatu 4, 00930 Helsinki)\\n\\nUrakan arvioitu alkamisajankohta on 01.02.2027 ja rakentamisen