INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16295,'2026-056560','HILMA','RFP','OPEN','Lähi-, luomu- ja pientuottajien elintarvikkeet','Lähi-, luomu- ja pientuottajien elintarvikkeet Huittisten kaupunki ilmoittaa perustavansa dynaamisen hankintajärjestelmän elintarvikkeista lähi-, luomu- ja pientuottajien tuotteille hankinnassa mukana oleville asiakkailleen (jäljempänä myös \"tilaajat\") tämän osallistumispyynnön ja sen liitteiden mukaisesti. Dynaaminen hankintajärjestelmä tarjoaa toimijoille ja tilaajille yhteisen kanavan jonka kautta yhteistyötä saadaan lisättyä ja tiivistettyä eri toimijoiden kesken. Dynaamisen hankintajärjestelmän aikana tilaaja valitsee kokonaistaloudellisesti soveltuvimman toimittajan tai toimittajat tapauskohtaisesti osallistumishakemuksessa kuvatulla tavalla. Tilaukset sisältävät elintarvikkeita tilaajan tarpeen mukaisesti ja sovituissa aikatauluissa, noudattaen tilaajan asettamia vaatimuksia.,','Huittisten kaupunki','ANY',1,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056560','[\"15000000\"]','[\"lähi\", \"luomu\", \"pientuottajien\", \"huittisten\", \"kaupunki\", \"elintarvikkeet\", \"dynaamisen\", \"hankintajärjestelmän\", \"mukaisesti\", \"tilaajan\", \"ilmoittaa\", \"perustavansa\", \"elintarvikkeista\", \"tuotteille\", \"hankinnassa\", \"mukana\", \"oleville\", \"asiakkailleen\", \"jäljempänä\", \"tilaajat\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/pori?id=486435&tpk=56914ad2-c712-4ead-97fc-e283b3632e72\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056560\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56560\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Lähi-, luomu- ja pientuottajien elintarvikkeet\", \"titleSv\": \"\", \"cpvCodes\": \"15000000\", \"currency\": null, \"deadline\": \"2033-12-31T10:00:00Z\", \"lowCarbon\": true, \"nutsCodes\": \"FI196\", \"titleOther\": \"\", \"biodiversity\": true, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Huittisten kaupunki ilmoittaa perustavansa dynaamisen hankintajärjestelmän elintarvikkeista lähi-, luomu- ja pientuottajien tuotteille hankinnassa mukana oleville asiakkailleen (jäljempänä myös \\\"tilaajat\\\") tämän osallistumispyynnön ja sen liitteiden mukaisesti. \\n\\nDynaaminen hankintajärjestelmä tarjoaa toimijoille ja tilaajille yhteisen kanavan jonka kautta yhteistyötä saadaan lisättyä ja tiivistettyä eri toimijoiden kesken. \\n\\nDynaamisen hankintajärjestelmän aikana tilaaja valitsee kokonaistaloudellisesti soveltuvimman toimittajan tai toimittajat tapauskohtaisesti osallistumishakemuksessa kuvatulla tavalla. \\n\\nTilaukset sisältävät elintarvikkeita tilaajan tarpeen mukaisesti ja sovituissa aikatauluissa, noudattaen tilaajan asettamia vaatimuksia.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2033-12-31T10:00:00Z\", \"circularEconomy\": true, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": true, \"employmentCondition\": false, \"procurementTypeCode\": \"supplies\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": true, \"lotResultTotalAmount\": null, \"justWorkingConditions\": true, \"listedGreenCriteriaUsed\": false, \"receivedApplicationCount\": null, \"tendersFromOtherEEACount\": null, \"sustainableFoodProduction\": true, \"energyEfficiencyConsidered\": true, \"includesFrameworkAgreement\": false, \"smeParticipationConsidered\": false, \"tendersFromOutsideEEACount\": null, \"lotResultTotalAmountCurrency\": null, \"s