INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16299,'2026-056555','HILMA','RFI','OPEN','Tietopyyntö: Kotiin vietävät ateriapalvelut','Tietopyyntö: Kotiin vietävät ateriapalvelut Tämä ei ole hankintailmoitus eikä tarjouspyyntö, vaan tietopyyntö mahdollisille tarjoajille. Tietopyynnön tarkoituksena on kartoittaa markkinoita ja kerätä tietoa sekä palvelutuottajien kommentteja, jotta mahdollinen tuleva tarjouskilpailu voitaisiin toteuttaa tarkoituksenmukaisella tavalla. Tietopyynnöllä ei pyydetä, eikä siihen anneta tarjouksia. Hankintayksikölle esitettyihin kommentteihin ja lisäkysymyksiin ei vastata. Tietopyyntö ei velvoita hankintayksikköä suorittamaan varsinaista hankintaa tai toteuttamaan hankintaa tietopyynnössä kuvatulla tavalla. Hankintayksikkö ei ole velvollinen ottamaan huomioon tietopyyntöön saatuja vastauksia tarjouspyynnön laadinnassa. Tietopyyntöön vastanneille ei makseta korvausta tietopyyntöön vastaamisesta tai mahdolliseen markkinavuoropuhelutilaisuuteen osallistumisesta. Tietopyyntöön vastaaminen ei sido toimittajaa tarjouskilpailuun osallistumiseen, eikä myöskään ole edellytyksenä myöhemmin varsinaiseen tarjouskilpailuun osallistumiselle. Tietopyyntöön vastaaminen tai vastaamatta jättäminen ei vaikuta tarjoajan asemaan varsinaisessa tarjouskilpailussa. Keski-Pohjanmaan hyvinvointialue on valmistelemassa kotiin vietävien ateriapalveluiden kilpailutusta. Hankinnan arvioitu sopimuskauden alkamisajankohta on 1.2.2027. Tällä tietopyynnöllä pyydetään alan palveluntuottajien näkemyksiä hankinnan toteuttamistapaan. Tietopyyntöön pyydetään vastaamaan täyttämällä liitteenä oleva kysely ja palauttamalla täytetty liite tämän tietopyynnön kohdassa \"Muut ehdot\".,','Keski-Pohjanmaan hyvinvointialue','ANY',3,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056555','[\"55520000\", \"55521200\"]','[\"tietopyyntöön\", \"tietopyyntö\", \"kotiin\", \"eikä\", \"keski\", \"pohjanmaan\", \"hyvinvointialue\", \"vietävät\", \"ateriapalvelut\", \"tietopyynnön\", \"tavalla\", \"tietopyynnöllä\", \"hankintaa\", \"vastaaminen\", \"tarjouskilpailuun\", \"hankinnan\", \"pyydetään\", \"tämä\", \"hankintailmoitus\", \"tarjouspyyntö\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/soite?id=626918&tpk=0584a313-9760-4fd0-bae5-2b5c4ebdc566\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056555\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56555\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Tietopyyntö: Kotiin vietävät ateriapalvelut\", \"titleSv\": \"\", \"cpvCodes\": \"55520000 55521200\", \"currency\": null, \"deadline\": \"2026-09-21T13:00:00Z\", \"lowCarbon\": null, \"nutsCodes\": \"FI1D5\", \"titleOther\": \"\", \"biodiversity\": null, \"codeOfConduct\": null, \"descriptionEn\": \"\", \"descriptionFi\": \"Tämä ei ole hankintailmoitus eikä tarjouspyyntö, vaan tietopyyntö mahdollisille tarjoajille. Tietopyynnön tarkoituksena on kartoittaa markkinoita ja kerätä tietoa sekä palvelutuottajien kommentteja, jotta mahdollinen tuleva tarjouskilpailu voitaisiin toteuttaa tarkoituksenmukaisella tavalla.\\n\\nTietopyynnöllä ei pyydetä, eikä siihen anneta tarjouksia.\\n\\nHankintayksikölle esitettyihin kommentteihin ja lisäkysymyksiin ei vastata. Tietopyyntö ei velvoita hankintayksikköä suorittamaan varsinaista hankintaa tai toteuttamaan hankintaa tietopyynnössä kuvatulla tavalla. Hankintayksikkö ei ole velvollinen ottamaan huomioon tietopyyntöön saatuja vastauksia tarjouspyynnön laadinnassa.\\n\\nTietopyyntöön vastanneille ei makseta korvausta tietopyyntöön vastaamisesta tai mahdolliseen 