INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16301,'2026-056553','HILMA','OTHER','OPEN','Apuvälinehuollon renkaat, pyörät, akut, akkulaturit ja muut varaosat','HUS-yhtymä pyytää tarjouksia apuvälinehuollon kunnossapitoon/huoltotoimintaan tarkoitetuista yleisluonteisista tuotteista. Hankintaan sisältyvät mm. seuraavat tuoteryhmät/tuotteet: liikkumisen apuvälineiden renkaat, pyörät, akut, akkulaturit ja muut tarjouspyyntömateriaalissa erikseen nimetyt varaosat sekä niiden toimittamiseen liittyvät palvelut. Tuotteet on tarkemmin kuvattu tarjouspyynnön liitteissä 1a-c Hinta- ja tuoteliite. Hankinta on jaettu osiin seuraavasti: 1. Liikkumisen apuvälineiden renkaat, pyörät ja muut huollon varaosat 2. Akut 3. Akkulaturit Sopimus on voimassa kolme (3) vuotta määräaikaisena, jatkuen toistaiseksi voimassa olevana. Kyseessä on useamman hankintayksikön yhteishankinta, joka toteutetaan hankintarenkaana. Tässä tarjouspyynnössä pyydettyjä tuotteita tulevat käyttämään: HUS-yhtymä (HUS), Etelä-Karjalan hyvinvointialue, Kymenlaakson hyvinvointialue ja Päijät-Hämeen hyvinvointialue. Ks. tarkemmat tiedot tarjouspyynnön liitteessä 2 Hankintasopimus. Hankinnan ennakoitu kokonaisarvo (alv 0 %) on yhteensä noin 900 000 euroa. Kyse on arviosta, eikä hankintayksikkö sitoudu ilmoitettuihin euromääriin ja tarjouspyynnössä ilmoitettuihin, toteutuneisiin kulutusmääriin. Lopulliset tilausmäärät voivat olla ilmoitettua suurempia tai pienempiä. Hankinnan kohde ja sitä koskevat vaatimukset on kuvattu yksityiskohtaisesti tarjouspyynnössä ja sen liitteissä., Renkaat, pyörät ja muut varaosat Listaus kilpailutettavista tuotteista tuoteryhmityksineen ja määrityksineen on tarjouspyynnön liitteellä 1a Hinta- ja tuotelomake. Tarjottujen tuotteiden tulee olla vähintään ko. liitteestä ja muusta tarjouspyyntömateriaalista ilmi käyvien ehdottomien vaatimusten ja määritysten mukaisia., Akut Listaus kilpailutettavista tuotteista tuoteryhmityksineen ja määrityksineen on tarjouspyynnön liitteellä 1b Hinta- ja tuotelomake. Tarjottujen tuotteiden tulee olla vähintään ko. liitteestä ja muusta tarjouspyyntömateriaalista ilmi käyvien ehdottomien vaatimusten ja määritysten mukaisia., Akkulaturit Listaus kilpailutettavista tuotteista tuoteryhmityksineen ja määrityksineen on tarjouspyynnön liitteellä 1c Hinta- ja tuotelomake. Tarjottujen tuotteiden tulee olla vähintään ko. liitteestä ja muusta tarjouspyyntömateriaalista ilmi käyvien ehdottomien vaatimusten ja määritysten mukaisia.,','HUS-yhtymä','ANY',1,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056553','[\"33000000\", \"33193000\"]','[\"tarjouspyynnön\", \"renkaat\", \"pyörät\", \"akut\", \"akkulaturit\", \"muut\", \"varaosat\", \"tuotteista\", \"hinta\", \"yhtymä\", \"tarjouspyynnössä\", \"hyvinvointialue\", \"listaus\", \"kilpailutettavista\", \"tuoteryhmityksineen\", \"määrityksineen\", \"liitteellä\", \"tuotelomake\", \"tarjottujen\", \"tuotteiden\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056553\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56553\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Renkaat, pyörät ja muut varaosat\", \"titleSv\": \"\", \"cpvCodes\": \"33000000\", \"currency\": null, \"deadline\": null, \"lowCarbon\": true, \"nutsCodes\": \"\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Listaus kilpailutettavista tuotteista tuoteryhmityksineen ja määrityksineen on tarjouspyynnön liitteellä 1a Hinta- ja tuotelomake. \\nTarjottujen tuotteiden tulee olla vähintään ko. liitteestä ja muusta tarjouspyy