INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16305,'2026-056548','HILMA','RFP','OPEN','Toimitilojen käyttäjäpalvelut 2021–2025 (DPS)','DYNAAMISEN HANKINTAJÄRJESTELMÄN KOHDE Tämän dynaamisen hankintajärjestelmän (jäljempänä myös ”DPS”) kohteena on toimitilojen käyttäjäpalvelut ja niihin liittyvien lisäpalveluiden tuottaminen Hansel Oy:n (jäljempänä Hansel) asiakkaille osallistumispyynnössä määritellyillä ehdoilla asiakkaan määrittelemissä kohteissa ja tiloissa. DPS:n kohde on kuvattu tarkemmin osallistumispyynnössä ja sen liitteissä. DYNAAMISEN HANKINTAJÄRJESTELMÄN LUOKAT Dynaaminen hankintajärjestelmä on jaettu kolmeen (3) toisistaan riippumattomaan luokkaan. Luokat sisältävät alla mainitut palveluyhdistelmät lisäpalveluineen: - Luokka 1. Siivouspalvelut ja Turvallisuus- ja aulapalvelut - Luokka 2. Siivouspalvelut ja Ateriapalvelun avustavat tehtävät - Luokka 3. Toimitilojen lisäpalvelut. Ehdokas voi hakea yhteen tai useampaan luokkaan yhdellä osallistumishakemuksella. Selvyyden vuoksi todetaan, että ehdokkaan tulee toimittaa kuhunkin hakemaansa luokkaan edellytetyt ehdokkaan soveltuvuutta ja osallistumispyynnön mukaisuutta osoittavat liitteet ja selvitykset. DYNAAMISEN HANKINTAJÄRJESTELMÄN KESTO DPS on voimassa 31.12.2027 saakka, ellei sitä keskeytetä aikaisemmin. DPS:n keston aikana kaikki kiinnostuneet ehdokkaat voivat tehdä siihen osallistumishakemuksen. Hansel Oy:n asiakkaat toteuttavat hankinnat DPS:n kuhunkin luokkaan hyväksyttyjen ehdokkaiden kesken DPS:n luokkakohtaisilla sisäisillä kilpailutuksilla, jotka voivat ajoittua DPS:n koko hankintavaiheen ajalle. DPS:n hankintavaihe alkaa perustamisvaiheen jälkeen 18.06.2021, ellei perustamisvaiheen pidennyksestä muuta johdu, ja päättyy DPS:n voimassaoloajan päättyessä. Hanselilla on oikeus keskeyttää dynaaminen hankintajärjestelmä kesken sen voimassaolon., Luokka 1: Siivouspalvelut ja Turvallisuus- ja aulapalvelut Katso osallistumispyynnön liitteet: - DPS kohde - Luokka 1 (Siivouspalvelut ja Turvallisuus- ja aulapalvelut) - DPS ehdot - Luokka 1 (Siivouspalvelut ja Turvallisuus- ja aulapalvelut), Luokka 2: Siivouspalvelut ja Ateriapalvelun avustavat tehtävät Katso osallistumispyynnön liitteet: - DPS kohde - Luokka 2 (Siivouspalvelut ja Ateriapalvelun avustavat tehtävät) - DPS ehdot - Luokka 2 (Siivouspalvelut ja Ateriapalvelun avustavat tehtävät), Luokka 3: Toimitilojen lisäpalvelut Katso osallistumispyynnön liitteet: - DPS kohde - Luokka 3 (Toimitilojen lisäpalvelut) - DPS ehdot - Luokka 3 (Toimitilojen lisäpalvelut),','Hansel Oy','ANY',1,13,NULL,NULL,40000000.00,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056548','[\"90900000\", \"55520000\", \"60000000\", \"75100000\", \"79711000\", \"79713000\", \"79714000\", \"79715000\", \"79716000\", \"90910000\", \"98310000\", \"98341120\", \"90510000\"]','[\"luokka\", \"siivouspalvelut\", \"toimitilojen\", \"kohde\", \"hansel\", \"dynaamisen\", \"hankintajärjestelmän\", \"luokkaan\", \"turvallisuus\", \"aulapalvelut\", \"ateriapalvelun\", \"avustavat\", \"tehtävät\", \"lisäpalvelut\", \"osallistumispyynnön\", \"liitteet\", \"katso\", \"ehdot\", \"käyttäjäpalvelut\", \"jäljempänä\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/hansel?id=350356&tpk=9151484e-b3ac-482e-91ae-e6277f1697ba\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056548\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56548\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Luokka 1: Siivouspalvelut ja Turvallisuus- ja aulapalvelut\", \"titleSv\": \"\", \"cpvCodes\": \"90900000 55520000 60000000 75100000 79711000 7971