INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16308,'2026-056652','HILMA','RFP','OPEN','Kiinteistön- ja vuokravälityspalveluiden hankinta','Vantaan seurakuntayhtymä pyytää tarjousta asuntojen, toimitilojen ja kiinteistöjen kiinteistön- sekä vuokravälityspalveluista. Hankinnassa perustetaan osa-alueittain puitejärjestely tarjouspyynnön ja sen liitteiden mukaisesti. Hankinta on jaettu seuraaviin osa-alueisiin: Osa-alue 1. Kiinteistönvälityspalvelut Osa-alue 2. Vuokravälityspalvelut Tilaajalla on pääkaupunkiseudun kiinteistökannassa pääosin asuinkiinteistöjä sekä sen lisäksi toimitilakiinteistöjä ja erilaisia seurakunnallisia kiinteistöjä. Palveluntuottajan tulee osata toteuttaa tilaajan erilaiset toimeksiannot ammattitaitoisesti sekä toimia tilaajan edustajana toimeksiantojen aikana hyvän välitystavan mukaisesti. Palvelun tulee täyttää Euroopan unionin suoraan velvoittavien säädösten, Suomen lakien ja asetusten sekä viranomaisten antamat määräykset. Hankittava palvelu on kuvattu tarkemmin tässä tarjouspyynnössä ja sen liitteissä., Kiinteistönvälityspalvelut Osa-alueessa perustetaan puitejärjestely kolmen (3) tarjoajan kanssa. Tilaajalla on pääkaupunkiseudun kiinteistökannassaan pääosin asunto-osakkeita ja muun muassa seurakunnallisia kiinteistöjä, asuin- ja toimitiloja. Palveluntuottajan tulee osata toteuttaa tilaajan erilaiset kiinteistövälitystoimeksiannot ammattitaitoisesti sekä toimia tilaajan edustajana toimeksiantojen aikana. Palveluntuottajan vastuulla olevia tehtäviä ovat muun muassa Tilaajan omistamien kiinteistöjen, asunto- ja toimitilaosakkeiden sekä huoneistojen välitystehtävät noudattaen ajanmukaista lainsäädäntöä, yleisesti hyväksyttyjä välityskäytäntöjä ja hyvää välitystapaa. Tarkemmin osa-alue on kuvattu liitteestä 1. Palvelukuvaus., Vuokravälityspalvelut Osa-alueessa perustetaan puitejärjestely kolmen (3) tarjoajan kanssa. Palveluntuottajan vastuulla olevia tehtäviä ovat muun muassa Tilaajan omistamien kiinteistöjen, asunto- ja toimitilaosakkeiden sekä huoneistojen vuokravälityspalvelut noudattaen ajanmukaista lainsäädäntöä, yleisesti hyväksyttyjä välityskäytäntöjä ja hyvää välitystapaa. Palveluntuottajan tulee toteuttaa tilaajan erilaiset kiinteistönvälitystoimeksiannot ammattitaitoisesti ja huolellisesti sekä toimia toimeksiantojen aikana tilaajan edustajana. Vuokralaisen hankinta tapahtuu seuraavasti: - toimeksianto kiinteistövälittäjälle asunnon vuokrauksesta - välittäjälle annetaan tiedot kiinteistöstä, välittäjä hankkii isännöitsijätoimistosta isännöitsijätodistuksen paitsi Vantaan seurakuntayhtymän vuokrataloyhtiön osalta - välittäjä noutaa avaimet Tilaajan avainhallinnasta - välittäjä hoitaa asunnon kuvauksen ja markkinointimateriaalin - välittäjä hoitaa ilmoitusmarkkinoinnin - välittäjä tarkistuttaa markkinointimateriaalin tilaajalla - välittäjä tarkistaa hakijan taustat/luottotiedot - välittäjä palauttaa avaimet avainhallintaan prosessin päätteeksi - välittäjä laskuttaa toteutuneesta vuokrauksesta siten, että kaikki yllä mainitut velvoitteet sisältyvät kiinteään välityspalkkioon = kohde/euroa + alv % Tilaaja vastaa vuokralaisen valinnasta ja hyväksymisestä. Tilaaja määrittelee vuokrattavan kohteen vuokratason sekä laatii vuokrasopimuksen. Lisäksi tilaaja sopii vuokralaisen kanssa avainhallintaan liittyvistä käytännöistä. Tarkemmin osa-alue on kuvattu liitteessä 2. Palvelukuvaus.,','Vantaan seurakuntayhtymä','ANY',2,4,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056652','[\"70300000\"]','[\"tilaajan\", \"välittäjä\", \"palveluntuottajan\", \"alue\", \"tulee\", \"hankinta\", \"vantaan\", \"kiinteistöjen\", \"perustetaan\", \"puitejärjestely\", \"vuokravälityspalvelut\", \"tilaajalla\", \"toteuttaa\", \"erilaiset\", \"ammattitaitoisesti\", \"toimia\", \"edustajana\", \"toimeksiantojen\", \"aikana\", \"kuvattu\"]',NULL,NULL,'[{\"url\": \"https://tarjouspalvelu.fi/vantaanseurakunnat?id=624221&tpk=7506415f-6951-40e8-9d00-567e902840e9\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056652\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56652\", \"lots\": [{\"id\": \"LOT-0001\", \"titleEn\": \"\", \"titleFi\": \"Kiinteistönvälityspalvelut\", \"titleSv\": \"\", \"cpvCodes\": \"70300000\", \"currency\": null, \"deadline\": \"2026-09-30T09:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1B1\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Osa-alueessa perustetaan puitejärjestely kolmen (3) tarjoajan kanssa.\\n\\nTilaajalla on pääkaupunkiseudun kiinteistökannassaan pääosin asunto-osakkeita ja muun muassa seurakunnallisia kiinteistöjä, asuin- ja toimitiloja. Palveluntuottajan tulee osata toteuttaa tilaajan erilaiset kiinteistövälitystoimeksiannot ammattitaitoisesti sekä toimia tilaajan edustajana toimeksiantojen aikana. \\n\\nPalveluntuottajan vastuulla olevia tehtäviä ovat muun muassa Tilaajan omistamien kiinteistöjen, asunto- ja toimitilaosakkeiden sekä huoneistojen välitystehtävät noudattaen ajanmukaista lainsäädäntöä, yleisesti hyväksyttyjä välityskäytäntöjä ja hyvää välitystapaa.\\n\\nTarkemmin osa-alue on kuvattu liitteestä 1. Palvelukuvaus.\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-09-30T09:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": false, \"employmentCondition\": false, \"procurementTypeCode\": \"services\", \"receivedTenderCount\": null, \"winnerOrganisations\": \"\", \"innovationConsidered\": true, \"lotResultTotalAmoun