INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16311,'2026-056644','HILMA','RFP','OPEN','Visit Northern Finland B2B-alustan kehitystyö','Visit Northern Finland B2B-alustan kehitystyö Visit Northern Finland Oy (jäljempänä VNF tai VNF Oy) pyytää tarjouksia uuden yritysten välisen (B2B) verkkoalustan suunnittelusta, toteutuksesta ja julkaisusta. Tarjouspyyntö julkaistaan Hilmassa (hankintailmoitukset.fi) kansallisena hankintana julkisista hankinnoista ja käyttöoikeussopimuksista annetun lain (1397/2016) mukaisesti. Käyttöliittymäprototyyppi on jo olemassa, ja se määrittelee, miltä alusta voisi näyttää ja miten se voisi toimia. Tämä tarjouspyyntö koskee sen taustalle rakennettavan tuotantoalustan toteutusta, mukaan lukien luvussa 4 kuvatut integraatiot ja ominaisuudet. Tarjouspyyntöön sisältää liitteitä. Nämä muodostavat yhdessä prototyypin kanssa osan tarjouspyyntöasiakirjoista. Jos asiakirjojen välillä on ristiriitoja, tarjoajan on nostettava asia esiin kysymysten esittämisaikana; tarjouspyyntö on ensisijainen. Hankinta toteutetaan osana Euroopan unionin osarahoittamaa Smart Growth for International Tourism (SmartGIT) -hanketta (https://visitoulu.fi/en/smart-growth-for-international-tourism-smartgit/).,','Visit Northern Finland Oy','ANY',1,13,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056644','[\"72000000\"]','[\"finland\", \"visit\", \"northern\", \"tarjouspyyntö\", \"alustan\", \"kehitystyö\", \"voisi\", \"smart\", \"growth\", \"international\", \"tourism\", \"smartgit\", \"jäljempänä\", \"pyytää\", \"tarjouksia\", \"uuden\", \"yritysten\", \"välisen\", \"verkkoalustan\", \"suunnittelusta\"]',NULL,NULL,'[{\"url\": \"https://www.hankintailmoitukset.fi/fi/public/procedure/36143/enotice/56644\", \"name\": \"Procurement Documents\"}, {\"url\": \"https://www.hankintailmoitukset.fi/fi/notice/2026-056644\", \"name\": \"HILMA Notice\"}]','{\"id\": \"EF-56644\", \"lots\": [{\"id\": \"LOT-0000\", \"titleEn\": \"\", \"titleFi\": \"Visit Northern Finland B2B-alustan kehitystyö\", \"titleSv\": \"\", \"cpvCodes\": \"72000000\", \"currency\": null, \"deadline\": \"2026-10-06T12:00:00Z\", \"lowCarbon\": false, \"nutsCodes\": \"FI1D9\", \"titleOther\": \"\", \"biodiversity\": false, \"codeOfConduct\": false, \"descriptionEn\": \"\", \"descriptionFi\": \"Visit Northern Finland Oy (jäljempänä VNF tai VNF Oy) pyytää tarjouksia uuden yritysten välisen (B2B) verkkoalustan suunnittelusta, toteutuksesta ja julkaisusta. Tarjouspyyntö julkaistaan Hilmassa (hankintailmoitukset.fi) kansallisena hankintana julkisista hankinnoista ja käyttöoikeussopimuksista annetun lain (1397/2016) mukaisesti. Käyttöliittymäprototyyppi on jo olemassa, ja se määrittelee, miltä alusta voisi näyttää ja miten se voisi toimia. Tämä tarjouspyyntö koskee sen taustalle rakennettavan tuotantoalustan toteutusta, mukaan lukien luvussa 4 kuvatut integraatiot ja ominaisuudet.\\n\\nTarjouspyyntöön sisältää liitteitä. Nämä muodostavat yhdessä prototyypin kanssa osan tarjouspyyntöasiakirjoista. Jos asiakirjojen välillä on ristiriitoja, tarjoajan on nostettava asia esiin kysymysten esittämisaikana; tarjouspyyntö on ensisijainen. \\n\\nHankinta toteutetaan osana Euroopan unionin osarahoittamaa Smart Growth for International Tourism (SmartGIT) -hanketta (https://visitoulu.fi/en/smart-growth-for-international-tourism-smartgit/).\", \"descriptionSv\": \"\", \"procedureType\": \"\", \"estimatedValue\": null, \"expirationDate\": \"2026-10-06T12:00:00Z\", \"circularEconomy\": false, \"endUserInvolved\": null, \"descriptionOther\": \"\", \"solutionNewToBuyer\": true, \"employmentCondition\": false, \"procurementT