INSERT INTO `tenders` (`id`, `external_id`, `source`, `type`, `status`, `title`, `description`, `contracting_authority`, `company_size`, `industry_area_id`, `location_id`, `published_date`, `deadline_date`, `estimated_value`, `currency`, `source_url`, `cpv_codes`, `keywords`, `buyer_email`, `buyer_phone`, `pdf_urls`, `raw_data`, `opportunity_score`, `related_tender_id`, `created_at`, `updated_at`) VALUES (16314,'2026-056640','HILMA','OTHER','OPEN','Paineilmalaitteisto','Paineilmalaitteisto Pohjois-Pohjanmaa hyvinvointialue (myöhemmin Pohde) pyytää tarjoustanne Paineilmalaitteistosta tämän tarjouspyynnön ja sen liitteiden mukaisesti. Hankinnan kohteena on paineilmalaitteet tarvikkeineen. Hankintasopimus on voimassa yhden vuoden, jonka lisäksi on mahdollisuus 1+1 vuoden optioon. Tilaaja päättää optioiden käytöstä erikseen. Lisäksi tilaaja päättää erikseen mahdollisesta huoltosopimuksesta ja sen laajuudesta takuuajan jälkeen. Tarjouspyynnössä ilmoitetut kulutusmäärät ovat arvioituja hankintakauden kulutusmääriä. Arvioidut kulutusmäärät ilmoitetaan tarjoajalle ainoastaan tarjouksen tekemisen tueksi. Hankintasopimus ei muodosta hankintayksikölle määräostovelvoitetta, vaan todellinen kulutus voi olla suurempi tai pienempi. Hankintayksikkö valitsee yhden Toimittajan hinnan perusteella. Tarvittava ja riittävä laatu varmistetaan pakottavilla vaatimuksilla. Sopimuskauden aikana hyvinvointialue osoittaa määrärahat tämän tarjouspyynnön mukaisille hankinnoille kunakin vuonna erikseen. Hankintoja toteutetaan kunakin vuonna määrärahojen puitteissa. Jos määrärahaa ei jotakin vuotta koskien myönnetä lainkaan, ei hankintapäätöksen mukaisia hankintoja tuona vuotena tehdä. Hankinnan kohde on kuvattu tarkemmin tarjouspyyntöasiakirjoissa.,','Pohjois-Pohjanmaan hyvinvointialue','ANY',3,14,NULL,NULL,NULL,'EUR','https://www.hankintailmoitukset.fi/fi/notice/2026-056640','[\"42123610\"]','[\"hyvinvointialue\", \"pohjois\", \"erikseen\", \"paineilmalaitteisto\", \"tämän\", \"tarjouspyynnön\", 